static int g_fail = 0, g_total = 0;
#define CHECK(cond) do { g_total++; if (!(cond)) { g_fail++; \
    printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond); } } while (0)
#define CHECK_EQ(a,b) do { g_total++; long long _a=(long long)(a), _b=(long long)(b); \
    if (_a!=_b) { g_fail++; printf("FAIL %s:%d  %s == %s  (%lld vs %lld)\n", \
    __FILE__, __LINE__, #a, #b, _a, _b); } } while (0)

// reads an ENTIRE file in binary mode into a std::string
// ("" if it fails to open). The "fread in a loop" idiom was repeated inline in ~10 places across the harness
// (lines 3361, 16215, 16838...); this helper centralizes it — later tasks in the phase reuse it.
static std::string SlurpBytes(const char* relPath) {
    FILE* f = fopen(relPath, "rb");
    if (!f) return std::string();
    std::string all; char buf[8192]; size_t n;
    while ((n = fread(buf, 1, sizeof(buf), f)) > 0) all.append(buf, n);
    fclose(f);
    return all;
}

// reusable contract for seeding determinism.
// Seeding two VIRGIN SaveData instances with the SAME seed function must produce exactly the same world:
// it compares by serializing with career::SaveCareer and diffing the bytes -- the same mechanism as the
// fixture round-trip (test_fixture_roundtrip, below), so it automatically covers any
// field the save format gains in later phases without touching this helper. It does NOT call CHECK internally: the
// caller (the test) decides what to assert, both the good case and the two bad ones. `what` names the
// temp files (build/seeddet_<what>_*.sav) so two uses in the same process don't collide; all three get deleted
// on BOTH exit paths (success and failure).
static bool SeedDeterminismCheck(const char* what, void(*seedFn)(career::SaveData&),
                                  long long minGrowthBytes, std::string* whyOut) {
    using namespace career;
    if (whyOut) whyOut->clear();
    const std::string tag = what;
    const std::string pathVirgin = "build/seeddet_" + tag + "_virgin.sav";
    const std::string pathA      = "build/seeddet_" + tag + "_a.sav";
    const std::string pathB      = "build/seeddet_" + tag + "_b.sav";
    paths::EnsureParentDir(pathVirgin);   // all three live under build/ -- a single EnsureParentDir is enough

    auto cleanup = [&]() {
        paths::RemoveFile(pathVirgin);
        paths::RemoveFile(pathA);
        paths::RemoveFile(pathB);
    };

    SaveData virgin;
    SaveCareer(virgin, pathVirgin.c_str());
    const std::string bytesVirgin = SlurpBytes(pathVirgin.c_str());

    SaveData a; seedFn(a);
    SaveCareer(a, pathA.c_str());
    const std::string bytesA = SlurpBytes(pathA.c_str());

    SaveData b; seedFn(b);
    SaveCareer(b, pathB.c_str());
    const std::string bytesB = SlurpBytes(pathB.c_str());

    // Empty world: the seeded result comes out byte-identical to the virgin one -- a helper that compares nothing against
    // nothing can't pass as good (guarded explicitly).
    if (bytesA == bytesVirgin) {
        if (whyOut) *whyOut = tag + ": mundo vacio -- el save sembrado es identico al virgen";
        cleanup();
        return false;
    }
    // Insufficient world: it seeded SOMETHING (passed the guard above) but less than the minimum the
    // caller asked for -- deterministic isn't enough if the resulting world is too thin for the subject.
    const long long growth = (long long)bytesA.size() - (long long)bytesVirgin.size();
    if (growth < minGrowthBytes) {
        if (whyOut) *whyOut = tag + ": mundo insuficiente -- crecio " + std::to_string(growth) +
            " bytes, por debajo del minimo pedido (" + std::to_string(minGrowthBytes) + ")";
        cleanup();
        return false;
    }
    // Divergence: the two seedings (same function, two distinct virgin SaveData instances) don't match byte for
    // byte -- it reports the FIRST line that differs, with both versions, instead of a bare "they differ" over
    // a save file with thousands of lines (same criterion as test_fixture_roundtrip).
    if (bytesA != bytesB) {
        size_t lineNo = 1, i = 0, minLen = std::min(bytesA.size(), bytesB.size());
        for (; i < minLen; i++) {
            if (bytesA[i] != bytesB[i]) break;
            if (bytesA[i] == '\n') lineNo++;
        }
        auto lineAt = [](const std::string& s, size_t pos) {
            size_t start = s.rfind('\n', pos); start = (start == std::string::npos) ? 0 : start + 1;
            size_t end = s.find('\n', pos); end = (end == std::string::npos) ? s.size() : end;
            return s.substr(start, end - start);
        };
        if (whyOut) *whyOut = tag + ": divergencia en la linea " + std::to_string(lineNo) +
            " -- A='" + lineAt(bytesA, i) + "'  B='" + lineAt(bytesB, i) + "'";
        cleanup();
        return false;
    }

    cleanup();
    return true;
}

