    CHECK(m.history[0].sponsorCardId == "card_x");
    CHECK_EQ((long)e.withdrawn_offers.count("of_f3_br"), 1L);
    CHECK(e.emails.back().neg_id == n.neg_id);

    // Comprehensive assertions for all 31 negotiation fields:
    CHECK_EQ(m.patience_base, 60);
    CHECK_EQ(m.respond_day, 739130);
    CHECK_EQ(m.reserve_day, 0);
    CHECK_EQ(m.last_action_day, 739123);
    CHECK_EQ(m.form_pct, 74);
    CHECK_EQ(m.trial_pct, 100);
    CHECK_EQ(m.player_terms.sponsorTierRank, 2);
    CHECK_EQ(m.table_terms.salaryPct, 50);
    CHECK_EQ(m.table_terms.sponsorTierRank, -1);
    CHECK(m.offer.id == "of_gt3_eu");
    CHECK(m.offer.from == "Alpha");
    CHECK(m.offer.clsId == "gt3");
    CHECK(m.offer.scope == "eu");
    CHECK_EQ(m.offer.contractKind, 0);
    CHECK_EQ(m.offer.archetype, 3);
    CHECK_EQ(m.offer.signBonus, 12000L);
    CHECK_EQ(m.offer.perRace, 4000L);
    CHECK_EQ(m.offer.commitment, 1);
