// Cleanliness EMA moves by alpha toward 100*cleanRace; below the teamInterest floor
// it lowers teamInterest; below the accident floor it activates the trial trigger; it round-trips
// save/reload. FAILS NOW: CareerProgress has no `cleanliness` field / no EMA / no save line.
static void test_cleanliness() {
    using namespace career;
    namespace bal = career::bal;

    // (1) SEED on first use + EMA toward 100 on a CLEAN race. A fresh prog (cleanliness==0.0) seeds to
    // CLEAN_ROOKIE_SEED (70) BEFORE the first EMA step, then a clean+finished race nudges toward 100 by α.
    {
        CareerProgress prog; prog.frontier_phase = 1;
        RaceResult r; r.pos = 1; r.field = 10; r.finished = true; r.clean = true; r.race_phase = 1;
        Settle(prog, r, 10000, 4000, /*rented=*/false, /*rentPct=*/0, /*carValue=*/0);
        // seed 70, cleanRace=1.0 -> 70 + 0.2*(100-70) = 76.0
        double expect = bal::CLEAN_ROOKIE_SEED + bal::CLEAN_ALPHA * (100.0 - bal::CLEAN_ROOKIE_SEED);
        CHECK(fabs(prog.cleanliness - expect) < 1e-6);
        // a SECOND clean race moves it the EMA delta α·(100 − clean) again.
        double before = prog.cleanliness;
        Settle(prog, r, 10000, 4000, false, 0, 0);
        CHECK(fabs(prog.cleanliness - (before + bal::CLEAN_ALPHA * (100.0 - before))) < 1e-6);
        CHECK(prog.cleanliness > before);   // a clean race raises cleanliness
    }

    // (2) a DIRTY race drops cleanliness toward 0 by α (cleanRace=0.0).
    {
        CareerProgress prog; prog.frontier_phase = 1; prog.cleanliness = 80.0;
        RaceResult r; r.pos = 5; r.field = 10; r.finished = true; r.clean = false; r.race_phase = 1;
        Settle(prog, r, 10000, 4000, false, 0, 0);
        // 80 + 0.2*(0 - 80) = 64.0
        CHECK(fabs(prog.cleanliness - (80.0 + bal::CLEAN_ALPHA * (0.0 - 80.0))) < 1e-6);
        CHECK(prog.cleanliness < 80.0);   // a dirty race lowers cleanliness
    }

    // (3) teamInterest: BELOW the floor a dirty driver is wanted LESS; at/above the floor it is a NO-OP
    // (MK_W_CLEAN live but the deficit is 0). Identical inputs but a sub-floor cleanliness must lower Want_T.
    {
        market::WantInputs clean;  clean.rating = 1600; clean.prestige = 50; clean.rel = 0.5;
        // default WantInputs.cleanliness == 100.0 -> NO-OP -> the byte-identical 0.5825 core holds.
        CHECK(fabs(market::Want_T(clean) - 0.5825) < 1e-6);
        market::WantInputs dirty = clean; dirty.cleanliness = 20.0;   // well below the 55 floor
        CHECK(market::Want_T(dirty) < market::Want_T(clean));
        // at the floor itself the penalty is still 0 (deficit==0) -> NO-OP.
        market::WantInputs atFloor = clean; atFloor.cleanliness = bal::CLEAN_TEAMINTEREST_FLOOR;
        CHECK(fabs(market::Want_T(atFloor) - market::Want_T(clean)) < 1e-6);
    }

    // (4) the accident trial trigger: ComingFromAccidents flips true BELOW CLEAN_ACCIDENT_TRIGGER_FLOOR.
    {
        CHECK(market::ComingFromAccidents(bal::CLEAN_ACCIDENT_TRIGGER_FLOOR - 1.0));   // below -> armed
        CHECK(!market::ComingFromAccidents(bal::CLEAN_ACCIDENT_TRIGGER_FLOOR));        // at the floor -> not armed
        CHECK(!market::ComingFromAccidents(70.0));                                      // a clean rookie -> not armed
    }

    // (5) round-trips save/reload (additive line; kSaveVersion stays 2).
    {
        const char* path = "career_test_clean.sav";
        SaveData out; out.prog.cleanliness = 42.5;
        CHECK(SaveCareer(out, path));
        SaveData in;
        CHECK(LoadCareer(in, path));
        CHECK(fabs(in.prog.cleanliness - 42.5) < 1e-4);   // survives (%.4f)
        remove(path);
        // legacy: a save written WITHOUT a cleanliness line loads the default 0.0 (the parser stays dumb;
        // the seed-to-70 lives in Settle, not the parser).
        const char* legacy = "career_test_clean_legacy.sav";
        FILE* lf = fopen(legacy, "wb");
        CHECK(lf != nullptr);
        if (lf) { fprintf(lf, "version 2\r\nrep 0\r\n"); fclose(lf); }
        SaveData old;
        CHECK(LoadCareer(old, legacy));
        CHECK(fabs(old.prog.cleanliness - 0.0) < 1e-9);   // absent -> default 0.0
        remove(legacy);
    }
}

// A contract at end-of-term generates a RENEWAL offer at rollover with terms shifted
// by obj_ratio + rel; contract fields persist through a year rollover. FAILS NOW: no RENEWAL generation in
// RolloverYearReport (ARCH_RENEWAL offer + obj_ratio/rel term shift do not exist yet).


// Lifecycle close-out: CloseStaleRenewalMails is PURE/directly testable, without
// having to run a whole rollover. RolloverYearReport calls it with year=cc.year right before clearing
// save.pending_renewals (career_calendar.cpp) — here the helper is exercised in isolation, with its three cases: (a)
// an unanswered mail from the exact year -> gets closed (answered=1, choice=0); (b) an ALREADY-answered mail ->
// stays intact (its real choice isn't overwritten with a fake 0); (c) mail from a DIFFERENT year -> the id doesn't match, untouched.
static void test_close_stale_renewal_mails() {
    using namespace career;

    // (a) unanswered + exact year -> gets closed.
    {
        SaveData s;
        market::OfferDef ren; ren.id = "of_harbor_trophy_6546";
        s.pending_renewals.push_back(ren);
        GeneratedEmail e; e.id = "renew_of_harbor_trophy_6546_2026"; e.family = 0; e.answered = 0; e.payload_key = "of_harbor_trophy_6546";
        s.emails.push_back(e);
        CloseStaleRenewalMails(s, 2026);
        int answered = -1, choice = -1;
        for (const auto& em : s.emails) if (em.id == "renew_of_harbor_trophy_6546_2026") { answered = em.answered; choice = em.choice; }
        CHECK_EQ(answered, 1);
        CHECK_EQ(choice, 0);
    }
    // (b) already answered (the player signed/declined) -> intact, NOT overwritten with choice 0.
    {
        SaveData s;
        market::OfferDef ren; ren.id = "of_harbor_trophy_6546";
        s.pending_renewals.push_back(ren);
        GeneratedEmail e; e.id = "renew_of_harbor_trophy_6546_2026"; e.family = 0; e.answered = 1; e.choice = 1;
        s.emails.push_back(e);
        CloseStaleRenewalMails(s, 2026);
        int choice = -1;
        for (const auto& em : s.emails) if (em.id == "renew_of_harbor_trophy_6546_2026") choice = em.choice;
        CHECK_EQ(choice, 1);
    }
    // (c) mail from a DIFFERENT year -> the id doesn't match -> untouched.
    {
        SaveData s;
        market::OfferDef ren; ren.id = "of_harbor_trophy_6546";
        s.pending_renewals.push_back(ren);
        GeneratedEmail e; e.id = "renew_of_harbor_trophy_6546_2025"; e.family = 0; e.answered = 0;
        s.emails.push_back(e);
        CloseStaleRenewalMails(s, 2026);
        int answered = -1;
        for (const auto& em : s.emails) if (em.id == "renew_of_harbor_trophy_6546_2025") answered = em.answered;
        CHECK_EQ(answered, 0);
    }
}

// CloseStalePressMails is PURE/directly testable, without running a whole rollover —
// same pattern as test_close_stale_renewal_mails above. (a) an unanswered interview (family 6, subtype<=3)
// -> gets closed (answered=1, choice=0), MailResolvedKey goes back to null (only choices 1/2/3 map to anything), it stops blocking
// PressInterviewPending, and rep/beef/rel_marks stay UNTOUCHED (the close-out never goes through ApplyPressAnswer). (b)
// an interview that's ALREADY answered -> stays intact (a real choice isn't overwritten with a fake 0). (c) subtype RANKING (10, not a
// question) -> outside the subtype<=3 filter, left intact.
static void test_close_stale_press_mails() {
    using namespace career;

    // (a) unanswered -> gets closed + zero side effects + unblocks PressInterviewPending.
    {
        SaveData s;
        s.prog.rep = 42;
        s.beef["rival_x"] = Beef{2, 2020};
        s.rel_marks.push_back(RelMark{"Team X", 2020, 500});
        GeneratedEmail e; e.id = "press_tf_gt3_2026"; e.family = 6; e.subtype = 1; e.answered = 0;
        s.emails.push_back(e);
        CHECK(PressInterviewPending(s));            // before the close-out: still unanswered -> blocks
        CloseStalePressMails(s);
        const GeneratedEmail* m = nullptr;
        for (const auto& em : s.emails) if (em.id == "press_tf_gt3_2026") m = &em;
        CHECK(m != nullptr);
        if (m) {
            CHECK_EQ(m->answered, 1);
            CHECK_EQ(m->choice, 0);
            CHECK(MailResolvedKey(*m) == nullptr);   // choice 0 -> never maps to a "press_res_*" (only 1/2/3 do)
        }
        CHECK(!PressInterviewPending(s));            // unblocked: the press can write again
        CHECK_EQ(s.prog.rep, 42);                    // untouched (never went through ApplyPressAnswer)
        CHECK_EQ((long)s.beef["rival_x"].level, 2L);
        CHECK_EQ((long)s.rel_marks.size(), 1L);
        CHECK_EQ((long)s.rel_marks[0].delta_x1000, 500L);
    }
    // (b) already answered -> intact, a real choice isn't overwritten with a fake 0.
    {
        SaveData s;
        GeneratedEmail e; e.id = "press_tw_harbor_trophy_6546_2026"; e.family = 6; e.subtype = 2; e.answered = 1; e.choice = 2;
        s.emails.push_back(e);
        CloseStalePressMails(s);
        int choice = -1;
        for (const auto& em : s.emails) if (em.id == "press_tw_harbor_trophy_6546_2026") choice = em.choice;
        CHECK_EQ(choice, 2);
    }
    // (c) subtype RANKING (not an interview, subtype>3) -> stays intact.
    {
        SaveData s;
        GeneratedEmail e; e.id = "press_ranking_2026"; e.family = 6;
        e.subtype = career::bal::MK_PRESS_SUBTYPE_RANKING; e.answered = 0;
        s.emails.push_back(e);
        CloseStalePressMails(s);
        int answered = -1;
        for (const auto& em : s.emails) if (em.id == "press_ranking_2026") answered = em.answered;
        CHECK_EQ(answered, 0);
    }
}

// CompletedSeason.team_id is captured at rollover (from the active contract) and persists
// additively. (1) a season with team_id="x" round-trips identically; (2) a legacy 4-field 'season' line (no
// team_id) loads to team_id==""  (back-compat); (3) the RolloverYearReport archive populates team_id from the
// active contract for that series (and leaves "" when self-funded / no contract). Data capture ONLY — no UI /
// TeamRelationship change. kSaveVersion stays 2 (purely additive).


// A no-show season does NOT floor at +1 REP; a per-contract missed-round counter
// increments; auto-BreakContract fires at MK_NOSHOW_BREACH_LIMIT; a partially-raced season is NOT wrongly
// floored-down. The REP-floor condition is keyed off the per-contract missed-round counter (
// missed_rounds == rounds), NOT playerPos==fieldSize.

static void test_settle_rating() {
    using career::DnfKind;
    // player among two EQUAL-rated cars, finishes 1st (idx 0), no AI fold: +6 at K=settled? No — provisional.
    // rating_races=0 => provisional K=32. RatingUpdateRace({1500,1500},0,32)[0] = +16 (winner of equal pair).
    career::CareerProgress p; p.rating = 1500.0; p.rating_races = 0;
    career::RatingSettleReport r = career::SettleRating(p, {1500.0, 1500.0}, 0, 0, DnfKind::Finished);
    CHECK(fabs(r.before - 1500.0) < 1e-9);
    CHECK(fabs(r.delta - 16.0) < 1e-6);            // K_PROVISIONAL=32, equal pair winner = 32 * 0.5
    CHECK(fabs(r.after - 1516.0) < 1e-6);
    CHECK(fabs(p.rating - 1516.0) < 1e-6);         // mutated in place
    CHECK_EQ(p.rating_races, 1);                   // counter advanced
    // losing the same duel: symmetric -16
    career::CareerProgress q; q.rating = 1500.0; q.rating_races = 0;
    career::RatingSettleReport rq = career::SettleRating(q, {1500.0, 1500.0}, 1, 0, DnfKind::Finished);
    CHECK(fabs(rq.delta + 16.0) < 1e-6);
    // audience effect is UPSIDE-ONLY. Winning (+16) at an event with audience 100 -> +25% = +20.
    career::CareerProgress pa; pa.rating = 1500.0; pa.rating_races = 0;
    career::RatingSettleReport ra = career::SettleRating(pa, {1500.0, 1500.0}, 0, 0, DnfKind::Finished, /*audience=*/100);
    CHECK(fabs(ra.delta - 20.0) < 1e-6);           // +16 * 1.25
    // Losing (-16) is NOT scaled by audience (only the positive delta is).
    career::CareerProgress qa; qa.rating = 1500.0; qa.rating_races = 0;
    career::RatingSettleReport rqa = career::SettleRating(qa, {1500.0, 1500.0}, 1, 0, DnfKind::Finished, /*audience=*/100);
    CHECK(fabs(rqa.delta + 16.0) < 1e-6);          // unchanged (negative delta)
    // once SETTLED (rating_races>=10) K drops from provisional 32 to the player's K_PLAYER_MIN floor (16,
    // not K_SETTLED 12 — RatingK keeps the player always responsive) -> winning the equal pair = 16*0.5 = +8.
    career::CareerProgress s; s.rating = 1500.0; s.rating_races = 20;
    career::RatingSettleReport rs = career::SettleRating(s, {1500.0, 1500.0}, 0, 0, DnfKind::Finished);
    CHECK(fabs(rs.delta - 8.0) < 1e-6);
    // band/tier views are populated and consistent with the rating maths
    CHECK_EQ(rs.band_after, career::RatingBand(rs.after));
    CHECK_EQ(rs.tier_after, career::RatingRepTier(rs.after));
}
static void test_settle_rating_dnf() {
    using career::DnfKind;
    // Mechanical DNF: rating UNCHANGED, but the race still counts toward the provisional window.
    career::CareerProgress m; m.rating = 1600.0; m.rating_races = 3;
    career::RatingSettleReport rm = career::SettleRating(m, {1600.0, 1600.0, 1600.0}, 2, 100, DnfKind::MechanicalDnf);
    CHECK(fabs(rm.delta) < 1e-9);
    CHECK(fabs(m.rating - 1600.0) < 1e-9);
    CHECK_EQ(m.rating_races, 4);
    // No-show: exactly -RATING_NOSHOW_DING, neutral on duels.
    career::CareerProgress ns; ns.rating = 1600.0; ns.rating_races = 20;
    career::RatingSettleReport rns = career::SettleRating(ns, {}, -1, 0, DnfKind::NoShow);
    CHECK(fabs(rns.delta + career::bal::RATING_NOSHOW_DING) < 1e-9);   // 15
    CHECK(fabs(ns.rating - (1600.0 - career::bal::RATING_NOSHOW_DING)) < 1e-9);
    // Error DNF placed LAST in a strong field: counts as that finish -> negative (lost every duel).
    career::CareerProgress e; e.rating = 1600.0; e.rating_races = 20;   // settled -> player K floor = 16
    // order: two faster cars ahead, player out at the back (idx 2). Equal ratings -> beat nobody -> 16*(-1)/2 = -8.
    career::RatingSettleReport re = career::SettleRating(e, {1600.0, 1600.0, 1600.0}, 2, 0, DnfKind::ErrorDnf);
    CHECK(re.delta < 0.0);
    CHECK(fabs(re.delta + 8.0) < 1e-6);                               // player K floor 16, lost both duels
}
// SettleRatingGrid applies a post-race update to the WHOLE grid
// (every AI finisher, not just the player). Whole-field zero-sum, per-driver race-count bump driving the
// dynamic K, lazy seed of an absent id, DNF v1 rule, and the player path left untouched.
static void test_settle_rating_grid() {
    using career::GridFinisher;
    // (1) whole-grid zero-sum + winner gains / last loses (equal-rated field, all already-present) ---
    {
        std::map<std::string, double> ratings = { {"a", 1500.0}, {"b", 1500.0}, {"c", 1500.0} };
        std::map<std::string, int>    races;
        std::vector<GridFinisher> order = {   // finish order: a (winner) .. c (last); no DNFs
            { "a", 1, 1, 3, false, false },
            { "b", 1, 2, 3, false, false },
            { "c", 1, 3, 3, false, false },
        };
        career::SettleRatingGrid(ratings, races, order);
        double da = ratings["a"] - 1500.0, db = ratings["b"] - 1500.0, dc = ratings["c"] - 1500.0;
        CHECK(fabs(da + db + dc) < 1e-6);   // zero-sum across the whole field
        CHECK(da > 0.0);                    // winner gains
        CHECK(dc < 0.0);                    // last loses
        CHECK(fabs(db) < 1e-9);             // middle of an equal 3-field nets ~0
        // (2) race-count bump: each grid driver's count increments by exactly 1 per settle ---
        CHECK_EQ(races["a"], 1); CHECK_EQ(races["b"], 1); CHECK_EQ(races["c"], 1);
        career::SettleRatingGrid(ratings, races, order);
        CHECK_EQ(races["a"], 2); CHECK_EQ(races["b"], 2); CHECK_EQ(races["c"], 2);   // +1 again
    }
    // (3) lazy seed: a grid id ABSENT from driver_ratings is seeded (LevelAnchoredSeed) before its delta ---
    {
        std::map<std::string, double> ratings;   // empty: every id must be seeded on the fly
        std::map<std::string, int>    races;
        std::vector<GridFinisher> order = {      // level 6 series, two finishers; absent in the store
            { "fresh_win",  6, 1, 2, false, false },
            { "fresh_lose", 6, 2, 2, false, false },
        };
        career::SettleRatingGrid(ratings, races, order);
        CHECK_EQ((long)ratings.count("fresh_win"),  1);   // seeded, not skipped
        CHECK_EQ((long)ratings.count("fresh_lose"), 1);
        // seeded around the level-6 midpoint (1850), then the duel delta applied: winner > loser.
        CHECK(ratings["fresh_win"] > ratings["fresh_lose"]);
        // anchored near level 6 (well above the rookie base), proving LevelAnchoredSeed (not a flat seed) ran.
        CHECK(ratings["fresh_win"] > 1700.0);
    }
    // (4) dynamic K: same equal-field finishing result moves a LOW-race-count field MORE than a settled one ---
    {
        std::map<std::string, double> rLo = { {"x", 1500.0}, {"y", 1500.0} };
        std::map<std::string, int>    racesLo = { {"x", 0}, {"y", 0} };          // provisional (K=32)
        std::map<std::string, double> rHi = { {"x", 1500.0}, {"y", 1500.0} };
        std::map<std::string, int>    racesHi = { {"x", 50}, {"y", 50} };        // settled (K=12)
        std::vector<GridFinisher> duel = {
            { "x", 1, 1, 2, false, false },
            { "y", 1, 2, 2, false, false },
        };
        career::SettleRatingGrid(rLo, racesLo, duel);
        career::SettleRatingGrid(rHi, racesHi, duel);
        double moveLo = rLo["x"] - 1500.0;   // provisional winner gain
        double moveHi = rHi["x"] - 1500.0;   // settled winner gain
        CHECK(moveLo > moveHi);              // an unproven field swings more for the same result
        CHECK(moveHi > 0.0);
    }
    // (5) DNF v1: an AI DNF does NOT contest the duels (excluded from the order) but still counts a race;
    //         the finishers settle zero-sum among themselves, and nothing crashes (documented v1 rule). ---
    {
        std::map<std::string, double> ratings = { {"p", 1500.0}, {"q", 1500.0}, {"dnf", 1500.0} };
        std::map<std::string, int>    races;
        std::vector<GridFinisher> order = {
            { "p",   1, 1, 3, false, false },   // finished 1st
            { "q",   1, 2, 3, false, false },   // finished 2nd
            { "dnf", 1, 3, 3, false, true  },   // DNF: excluded from duels (v1 rule)
        };
        career::SettleRatingGrid(ratings, races, order);
        double dp = ratings["p"] - 1500.0, dq = ratings["q"] - 1500.0, dd = ratings["dnf"] - 1500.0;
        CHECK(fabs(dd) < 1e-9);              // DNF driver: no duel delta (excluded), rating unchanged
        CHECK(fabs(dp + dq) < 1e-6);         // the two finishers settle zero-sum BETWEEN THEMSELVES
        CHECK(dp > 0.0 && dq < 0.0);         // p beat q
        CHECK_EQ(races["dnf"], 1);           // the DNF still counts toward the provisional window
        CHECK_EQ(races["p"], 1); CHECK_EQ(races["q"], 1);
    }
    // (6) player not double-updated: an id flagged is_player in the grid input is NOT touched here ---
    {
        std::map<std::string, double> ratings = { {"ai1", 1500.0}, {"ai2", 1500.0}, {"player", 1500.0} };
        std::map<std::string, int>    races;
        std::vector<GridFinisher> order = {
            { "ai1",    1, 1, 3, false, false, /*is_player=*/false },
            { "player", 1, 2, 3, false, false, /*is_player=*/true  },   // the player: handled by SettleRating, not here
            { "ai2",    1, 3, 3, false, false, /*is_player=*/false },
        };
        career::SettleRatingGrid(ratings, races, order);
        CHECK(fabs(ratings["player"] - 1500.0) < 1e-9);   // player rating untouched (no double-update)
        CHECK_EQ((long)races.count("player"), 0);         // player race-count not bumped here either
        // the two AI drivers still settle zero-sum between themselves (player excluded from the duels).
        double d1 = ratings["ai1"] - 1500.0, d2 = ratings["ai2"] - 1500.0;
        CHECK(fabs(d1 + d2) < 1e-6);
        CHECK(d1 > 0.0 && d2 < 0.0);
        CHECK_EQ(races["ai1"], 1); CHECK_EQ(races["ai2"], 1);
    }
}
// The de-mocked world ranking + player rating.
// ProfileWorldRanking reads the REAL driver_ratings pool, filters to the active-modern subset,
// maps id->display name (DriverById), inserts the player, sorts desc. ProfileRating returns
// prog.rating directly + the per-race delta. No kWorld mock; no provisional badge.
static void test_world_ranking() {
    using namespace career;
    // (1) real pool, sorted desc, player inserted at their rating; no mock names appear ---
    {
        // A small synthetic pool. The active set lists which ids render on the modern board.
        std::map<std::string, double> pool = {
            { "rd_a", 1900.0 }, { "rd_b", 1500.0 }, { "rd_c", 1700.0 },
        };
        std::set<std::string> active = { "rd_a", "rd_b", "rd_c" };
        std::vector<RankRow> v = ProfileWorldRanking(pool, active, "Test Player", 1620, /*seriesFilter=*/"");
        // 3 pool ids + the player = 4 rows, sorted descending by rating.
        CHECK_EQ((long)v.size(), 4);
        for (size_t i = 0; i + 1 < v.size(); i++) CHECK(v[i].rating >= v[i+1].rating);
        // exactly one player row, at the inserted rating
        int youCount = 0; int youRating = -1;
        for (auto& r : v) if (r.you) { youCount++; youRating = r.rating; }
        CHECK_EQ(youCount, 1);
        CHECK_EQ(youRating, 1620);
        // none of the old mock kWorld names leak in
        for (auto& r : v) {
            CHECK(r.name != "V. Petrov");
            CHECK(r.name != "E. Castellano");
            CHECK(r.name != "S. Nakai");
        }
    }
    // (2) active-modern filter: an id NOT in the active set is excluded; an active id is included ---
    {
        std::map<std::string, double> pool = {
            { "rd_active", 1800.0 }, { "rd_historic", 1850.0 },
        };
        std::set<std::string> active = { "rd_active" };   // rd_historic is rated but NOT active (era driver)
        std::vector<RankRow> v = ProfileWorldRanking(pool, active, "Test Player", 1500, "");
        bool sawActive = false, sawHistoric = false;
        for (auto& r : v) {
            if (r.name.find("rd_active") != std::string::npos || r.name == "rd_active") sawActive = true;
        }
        // rd_historic must NOT appear as a ranked row (excluded by the active filter), regardless of its name mapping.
        // We assert via rating: 1850 (rd_historic) should not be present among the non-player rows.
        for (auto& r : v) if (!r.you && r.rating == 1850) sawHistoric = true;
        (void)sawActive;
        CHECK(!sawHistoric);   // the historic/non-active driver is filtered out
        // and the active one IS present (its rating row exists)
        bool activePresent = false; for (auto& r : v) if (!r.you && r.rating == 1800) activePresent = true;
        CHECK(activePresent);
    }
    // (3) band: each row carries a band derived via RatingBand (number + band consistent) ---
    {
        std::map<std::string, double> pool = { { "rd_elite", 2050.0 }, { "rd_low", 1150.0 } };
        std::set<std::string> active = { "rd_elite", "rd_low" };
        std::vector<RankRow> v = ProfileWorldRanking(pool, active, "P", 1600, "");
        for (auto& r : v) {
            int expect = career::RatingBand((double)r.rating);
            // BandView maps RatingBand(0..5) F..A; the row's band.idx must reflect the same band (S=6 above A).
            if (r.rating < (int)bal::RATING_BAND_MIN[5] + 400)
                CHECK_EQ(r.band.idx, expect);
            CHECK(r.band.key != nullptr && r.band.key[0] != '\0');
        }
    }
    // (4) ProfileRating returns prog.rating directly (NOT the wins/podiums formula) + surfaces the delta ---
    {
        ProfileRatingInfo info = ProfileRating(/*playerRating=*/1842, /*lastDelta=*/18);
        CHECK_EQ(info.score, 1842);                 // reads prog.rating directly
        CHECK_EQ(info.delta, 18);                   // per-race delta surfaced
        CHECK_EQ(info.band.idx, career::RatingBand(1842.0));   // band via RatingBand ("A" for 1842)
        // a negative delta survives too (a bad race)
        ProfileRatingInfo info2 = ProfileRating(1500, -7);
        CHECK_EQ(info2.score, 1500);
        CHECK_EQ(info2.delta, -7);
    }
    // (5) empty pool renders gracefully: just the player row (a DoS guard) ---
    {
        std::map<std::string, double> pool;
        std::set<std::string> active;
        std::vector<RankRow> v = ProfileWorldRanking(pool, active, "Solo", 1300, "");
        CHECK_EQ((long)v.size(), 1);
        CHECK(v[0].you);
        CHECK_EQ(v[0].rating, 1300);
    }
    // (6) ProfileMyRank is 1-based and consistent with the sorted board ---
    {
        std::map<std::string, double> pool = { { "rd_top", 2000.0 }, { "rd_bot", 1200.0 } };
        std::set<std::string> active = { "rd_top", "rd_bot" };
        int rank = ProfileMyRank(pool, active, "Mid", 1600, "");   // 2000 > 1600 > 1200 -> rank 2
        CHECK_EQ(rank, 2);
    }
}
// The modern/historic split + the active-modern world filter.
// IsModernSeries reads SeriesDef.era; ActiveModernSet excludes retired ids and respects the series filter.

static void test_rep_as_view() {
    using namespace career;
    // RatingRepTier bands per bal::REP_TIER_RATING { 0, 1200, 1400, 1600, 1850, 2100 }
    CHECK_EQ(RatingRepTier(1150.0), 0);   // Unknown (rookie start)
    CHECK_EQ(RatingRepTier(1250.0), 1);   // Prospect
    CHECK_EQ(RatingRepTier(1450.0), 2);   // Known
    CHECK_EQ(RatingRepTier(1650.0), 3);   // Established
    CHECK_EQ(RatingRepTier(1900.0), 4);   // Star
    CHECK_EQ(RatingRepTier(2200.0), 5);   // Legend
    // RatingDisplayBand is exactly RatingBand (the ELO letter view)
    CHECK_EQ(RatingDisplayBand(2100.0), RatingBand(2100.0));
    CHECK_EQ(RatingDisplayBand(1000.0), RatingBand(1000.0));
    // both are VIEWS of the SAME number: a single rating yields one tier AND one band, not two metrics
    double r = 1700.0;
    CHECK_EQ(RatingRepTier(r), 3);                 // Established
    CHECK_EQ(RatingDisplayBand(r), 4);             // B band (>=1700)
}
static void test_save_rating() {
    career::SaveData a;
    a.prog.credits = 5000; a.prog.rep = 100;
    a.prog.rating = 1623.5; a.prog.rating_races = 14;
    const char* path = "build\\career_rating.sav";
    CHECK(career::SaveCareer(a, path));
    career::SaveData b; CHECK(career::LoadCareer(b, path));
    CHECK(fabs(b.prog.rating - 1623.5) < 1e-3);
    CHECK_EQ(b.prog.rating_races, 14);
    a.driver_ratings["rival_alpha"] = 1734.25;
    a.driver_ratings["rival_beta"]  = 1410.0;
    // A per-driver races-completed counter rides additively beside driver_ratings.
    a.driver_races["rival_alpha"] = 7;
    a.driver_races["rival_beta"]  = 0;     // n==0 -> NOT written (write-when >0); should be absent after reload
    a.driver_races["rival_gamma"] = 3;     // an id with only a race-count (no rating) still round-trips
    CHECK(career::SaveCareer(a, path));
    career::SaveData c; CHECK(career::LoadCareer(c, path));
    CHECK(fabs(c.driver_ratings["rival_alpha"] - 1734.25) < 1e-3);
    CHECK(fabs(c.driver_ratings["rival_beta"]  - 1410.0)  < 1e-3);
    CHECK_EQ((long)c.driver_ratings.size(), 2);
    // driver_races round-trips: alpha=7, gamma=3 survive; beta (n==0) was not written -> absent.
    CHECK_EQ(c.driver_races["rival_alpha"], 7);
    CHECK_EQ(c.driver_races["rival_gamma"], 3);
    CHECK_EQ((long)c.driver_races.count("rival_beta"), 0);   // write-when>0: beta omitted
    CHECK_EQ((long)c.driver_races.size(), 2);                // only the two non-zero entries persisted
    // Old-save-loads-clean (additive, no migration): a save lacking ANY 'driverraces' lines loads with an
    // empty driver_races map and no error (mirror of test_save_v1_migration_seeds_rating's old-save idiom).
    const char* noraces = "build\\career_noraces.sav";
    { FILE* f = fopen(noraces, "wb");
      fputs("version 2\r\ncredits 200\r\nrep 50\r\ndriverrating rival_alpha 1500.0000\r\n", f); fclose(f); }
    career::SaveData d2; CHECK(career::LoadCareer(d2, noraces));
    CHECK_EQ((long)d2.driver_races.size(), 0);               // no driverraces lines -> empty map, clean load
    CHECK(fabs(d2.driver_ratings["rival_alpha"] - 1500.0) < 1e-3);   // the rest still loads
}
static void test_save_v1_migration_seeds_rating() {
    // A legacy v1 save (no rating lines) with a mid REP: after load+migrate, rating is seeded > rookie base.
    const char* v1 = "build\\career_v1_rating.sav";
    { FILE* f = fopen(v1, "wb"); fputs("version 1\r\ncredits 4000\r\nrep 150\r\n", f); fclose(f); }
    career::SaveData L; CHECK(career::LoadCareer(L, v1));
    // REP 150 -> RepDisplayBand index 3 (>=120) -> REP_TIER_RATING[3] = 1600
    CHECK(fabs(L.prog.rating - 1600.0) < 1e-6);
    CHECK_EQ(L.prog.rating_races, 0);
    // A legacy v0 save (no version line) with REP 0 -> seeds at the rookie base (not below).
    const char* v0 = "build\\career_v0_rating.sav";
    { FILE* f = fopen(v0, "wb"); fputs("credits 100\r\nrep 0\r\n", f); fclose(f); }
    career::SaveData L0; CHECK(career::LoadCareer(L0, v0));
    CHECK(fabs(L0.prog.rating - career::bal::RATING_ROOKIE_BASE) < 1e-6);  // 1150
    // A v2 save with an explicit rating is NOT re-seeded (migration only fires when rating==0).
    career::SaveData a; a.prog.rep = 0; a.prog.rating = 1800.0; a.prog.rating_races = 5;
    const char* v2 = "build\\career_v2_rating.sav";
    CHECK(career::SaveCareer(a, v2));
    career::SaveData L2; CHECK(career::LoadCareer(L2, v2));
    CHECK(fabs(L2.prog.rating - 1800.0) < 1e-6);   // untouched

    // post-load heal. Real case: a career created via the gate's SLOTS (without cmd.profile.create)
    // -> rating 0 -> the first race did ELO math from 0 and persisted ~32. A rating >0 but <900 (below the
    // legitimate ~930 floor) gets re-seeded to RATING_PLAYER_SEED while PRESERVING rating_races.
    const char* c32 = "build\\career_rating32.sav";
    { FILE* f = fopen(c32, "wb"); fputs("version 2\r\ncredits 21159\r\nrep 6\r\nrating 31.9418\r\nrating_races 2\r\n", f); fclose(f); }
    career::SaveData H; CHECK(career::LoadCareer(H, c32));
    CHECK(fabs(H.prog.rating - career::bal::RATING_PLAYER_SEED) < 1e-6);   // repaired to 1250
    CHECK_EQ(H.prog.rating_races, 2);                                       // provisional window preserved
    // v2 with an EXPLICIT rating of 0 (a slot profile not yet seeded): clean seed + counter reset to 0.
    const char* c0 = "build\\career_rating0.sav";
    { FILE* f = fopen(c0, "wb"); fputs("version 2\r\ncredits 100\r\nrep 0\r\nrating 0.0000\r\nrating_races 0\r\n", f); fclose(f); }
    career::SaveData H0; CHECK(career::LoadCareer(H0, c0));
    CHECK(fabs(H0.prog.rating - career::bal::RATING_PLAYER_SEED) < 1e-6);
    CHECK_EQ(H0.prog.rating_races, 0);
    // a legitimately LOW rating (a bad provisional streak, ~930) is left untouched.
    const char* cLow = "build\\career_ratinglow.sav";
    { FILE* f = fopen(cLow, "wb"); fputs("version 2\r\ncredits 100\r\nrep 0\r\nrating 930.0000\r\nrating_races 10\r\n", f); fclose(f); }
    career::SaveData HL; CHECK(career::LoadCareer(HL, cLow));
    CHECK(fabs(HL.prog.rating - 930.0) < 1e-6);
    remove(c32); remove(c0); remove(cLow);
}
static void test_seed_driver_ratings() {
    std::map<std::string, double> r;
    std::vector<career::SeedFieldEntry> field = {
        {"d_best",  1, true},   // order 1, iconic -> SEED_TOP + ICONIC_BUMP = 1900 + 60 = 1960
        {"d_mid",   2, false},  // order 2 of 3 -> midpoint = 1550
        {"d_last",  3, false},  // order 3 (last) -> SEED_BOTTOM = 1200
    };
    int n = career::SeedDriverRatings(r, field);
    CHECK_EQ(n, 3);
    CHECK(fabs(r["d_best"] - 1960.0) < 1e-6);
    CHECK(fabs(r["d_mid"]  - 1550.0) < 1e-6);
    CHECK(fabs(r["d_last"] - 1200.0) < 1e-6);
    // idempotent: an already-present (evolved) id is NOT overwritten; only missing ones seed.
    r["d_mid"] = 1700.0;               // pretend d_mid climbed
    int n2 = career::SeedDriverRatings(r, field);
    CHECK_EQ(n2, 0);                   // nothing missing -> nothing seeded
    CHECK(fabs(r["d_mid"] - 1700.0) < 1e-6);   // preserved
    // entries with empty id are skipped (not seeded)
    std::map<std::string, double> r2;
    std::vector<career::SeedFieldEntry> f2 = { {"", 1, false}, {"x", 2, false} };
    int n3 = career::SeedDriverRatings(r2, f2);
    CHECK_EQ(n3, 1);
    CHECK_EQ((long)r2.count(""), 0);
}
// The level-anchored seed that removes the per-field "wall"
// (every series' #1 ≈ 1900). Goes GREEN only once career::LevelAnchoredSeed lands.
static void test_level_anchored_seed() {
    using career::LevelAnchoredSeed;
    // Anti-wall: order-1 of a HIGH-prestige series anchors well above order-1 of a LOW one.
    // (The old RatingSeedFromOrder put BOTH at ~1900 — the wall this test forbids.)
    double topLo = LevelAnchoredSeed(2, 1, 20, false);   // #1 of a low-tier (level 2) field
    double topHi = LevelAnchoredSeed(6, 1, 20, false);   // #1 of a high-tier (level 6) field
    CHECK(topHi - topLo > 150.0);                        // meaningful prestige gap, NOT a tie
    // Overlap: the TOP of a lower level can OUT-RATE the BOTTOM of the level above it
    // (the "hero in a bad car" case). Adjacent levels must overlap at the edges.
    double lowTop  = LevelAnchoredSeed(4, 1,  20, false);   // best driver in level 4
    double highBot = LevelAnchoredSeed(5, 20, 20, false);   // worst driver in level 5
    CHECK(lowTop > highBot);                                // at least one adjacent-edge pair overlaps
    // Iconic retained: an iconic driver seeds above a non-iconic peer at the same level+order.
    double plain  = LevelAnchoredSeed(4, 3, 20, false);
    double iconic = LevelAnchoredSeed(4, 3, 20, true);
    CHECK(iconic > plain);
    CHECK(fabs((iconic - plain) - career::bal::RATING_ICONIC_BUMP) < 1e-6);  // exactly the bump
    // Monotone midpoint: the per-level midpoint (order-fraction t=0.5, fieldSize 1 -> t=0) is
    // NON-DECREASING in level 1..7. Use fieldSize 1 so order-spread collapses to the pure midpoint.
    double prev = LevelAnchoredSeed(1, 1, 1, false);
    for (int lvl = 2; lvl <= 7; lvl++) {
        double mid = LevelAnchoredSeed(lvl, 1, 1, false);
        CHECK(mid >= prev - 1e-9);   // non-decreasing
        prev = mid;
    }
    // DoS guard: an out-of-range level must not crash / index OOB; it clamps.
    CHECK(fabs(LevelAnchoredSeed(0,   1, 1, false) - LevelAnchoredSeed(1, 1, 1, false)) < 1e-6);
    CHECK(fabs(LevelAnchoredSeed(999, 1, 1, false) - LevelAnchoredSeed(7, 1, 1, false)) < 1e-6);
}
// Whole-pool materialization over a synthetic multi-series pool. Asserts a
// non-flat spread (no wall of ties), idempotence (re-run seeds 0), and evolved-rating preservation.
// Goes GREEN only once career::SeedAllDrivers(map, pool) lands.
static void test_seed_all_drivers() {
    using career::SeedFieldEntry;
    using career::SeedSeriesEntry;
    // Two series at DIFFERENT levels: a low-tier feeder (level 2) and a top series (level 6).
    std::vector<SeedSeriesEntry> pool = {
        { 2, { {"feeder_p1", 1, false}, {"feeder_p2", 2, false}, {"feeder_p3", 3, false} } },
        { 6, { {"top_p1",    1, false}, {"top_p2",    2, false}, {"top_p3",    3, false} } },
    };
    std::map<std::string, double> r;
    int n = career::SeedAllDrivers(r, pool);
    CHECK_EQ(n, 6);                          // every id materialized
    CHECK_EQ((long)r.size(), 6);
    // Non-flat spread: NOT all six at the same value (the anti-wall property), and the top series'
    // #1 out-ranks the feeder's #1 (cross-series prestige shows through).
    CHECK(r["top_p1"] - r["feeder_p1"] > 150.0);
    // No wall of ties at any single value: the six distinct (level,order) slots yield >=4 distinct
    // rating buckets (a flat seed would collapse them).
    std::vector<double> vals = { r["feeder_p1"], r["feeder_p2"], r["feeder_p3"],
                                 r["top_p1"], r["top_p2"], r["top_p3"] };
    int distinct = 0;
    for (size_t i = 0; i < vals.size(); i++) {
        bool seen = false;
        for (size_t j = 0; j < i; j++) if (fabs(vals[i] - vals[j]) < 1e-6) { seen = true; break; }
        if (!seen) distinct++;
    }
    CHECK(distinct >= 4);
    // Idempotent: re-running over the same pool seeds 0 (everything already present).
    int n2 = career::SeedAllDrivers(r, pool);
    CHECK_EQ(n2, 0);
    // Evolved preservation: a pre-set (evolved) id is NOT overwritten.
    r["top_p2"] = 1999.0;
    int n3 = career::SeedAllDrivers(r, pool);
    CHECK_EQ(n3, 0);
    CHECK(fabs(r["top_p2"] - 1999.0) < 1e-6);
    // Empty-id entries are skipped (the idempotent guard from SeedDriverRatings, kept verbatim).
    std::vector<SeedSeriesEntry> pool2 = { { 3, { {"", 1, false}, {"real_id", 2, false} } } };
    std::map<std::string, double> r2;
    int n4 = career::SeedAllDrivers(r2, pool2);
    CHECK_EQ(n4, 1);
    CHECK_EQ((long)r2.count(""), 0);
}
// ~~~08/09 — THE POOL'S ORIGIN CATEGORY (pool_origin.psv): the loader reads the key (FNV of the id, the
//  same as driver_profiles), the class, the confidence and the note; flags «era» by WORD in the note; skips
//  anything malformed; and with no file leaves the table empty (the world as before) without breaking anything.
static void test_pool_origin_loader() {
    const char* cf = "build/__test_pool_origin__.psv";   // forward slashes: fopen accepts them on Windows
    const unsigned h1 = career::PoolOriginHash("rd_test_origen_1");
    const unsigned h2 = career::PoolOriginHash("rd_test_origen_2");
    const unsigned h3 = career::PoolOriginHash("rd_test_origen_3");
    {
        FILE* f = fopen(cf, "wb");
        fputs("# fixture" "\r\n", f);
        fputs("name_hash|name|home_class|confidence|note" "\r\n", f);
        fprintf(f, "%u|Uno|Onyx_Cup_4824|alta|corre GT3 en 2025" "\r\n", h1);
        fprintf(f, "%u|Dos|Ivory_Cup|baja|F1 de los 70, retirado" "\r\n", h2);
        fprintf(f, "%u|Tres|Onyx Challenge" "\r\n", h3);                     // three columns: no confidence or note
        fputs("abc|malo|Onyx_Cup_4824|alta|" "\r\n", f);                 // non-numeric key -> skipped
        fputs("12|corta" "\r\n", f);                                // < 3 columns -> skipped
        fputs("13|sin clase||alta|carrera larga" "\r\n", f);        // empty class -> skipped
        fclose(f);
    }
    CHECK(career::LoadPoolOrigin(cf));
    CHECK_EQ(career::PoolOriginCount(), 3);
    const career::PoolOrigin* o1 = career::PoolOriginFor("rd_test_origen_1");
    CHECK(o1 && o1->home_class == "Onyx_Cup_4824" && o1->confidence == 3 && !o1->era);
    const career::PoolOrigin* o2 = career::PoolOriginFor("rd_test_origen_2");
    CHECK(o2 && o2->home_class == "Ivory_Cup" && o2->confidence == 1 && o2->era);   // «retirado» as a word
    const career::PoolOrigin* o3 = career::PoolOriginFor("rd_test_origen_3");
    CHECK(o3 && o3->confidence == 0 && o3->note.empty() && !o3->era);
    CHECK(career::PoolOriginFor("rd_nadie") == nullptr);
    CHECK(career::PoolOriginForHash(h1) == o1);
    // «carrera» is not «era»: the flag goes by word, not by fragment
    {
        FILE* f = fopen(cf, "wb");
        fprintf(f, "%u|Uno|Onyx_Cup_4824|media|una carrera larga en GT" "\r\n", h1);
        fclose(f);
    }
    CHECK(career::LoadPoolOrigin(cf));
    CHECK_EQ(career::PoolOriginCount(), 1);
    o1 = career::PoolOriginFor("rd_test_origen_1");
    CHECK(o1 && o1->confidence == 2 && !o1->era);
    // no file: empty table and nothing broken
    CHECK(!career::LoadPoolOrigin("build/__no_existe_pool_origin__.psv"));
    CHECK_EQ(career::PoolOriginCount(), 0);
    CHECK(career::PoolOriginFor("rd_test_origen_1") == nullptr);
}
// ~~~0.7.0 port — what's left of `test_derive_real_profile`: its parts (a) and (b) measured
// `DeriveRealProfile` and the `driver_profiles.psv` curation, and both have been retired with the module
// `career_profiles` (without a single production consumer, neither in 0.7.0 nor in f0). This part is NOT:
// it measures `ApplyAiPersonality`, which is still alive and is used by the grid paths that don't go through the
// F08 human band. 15 complete parameters: the archetype moves fuel/blue/weather and two
// different archetypes do NOT write the same thing.
static void test_ai_personality_params_vary_by_archetype() {
    using namespace career;
    // (c) 15-param completeness via ApplyAiPersonality: feeding the derived archetype+base yields
    // fuel/blue/weather that are NOT the flat struct defaults, and they VARY across archetypes.
    // Struct defaults (career_customai.h:22): fuel=0.65, blue=0.95, weather=0.70.
    const double DEF_FUEL = 0.65, DEF_BLUE = 0.95, DEF_WEATHER = 0.70;
    auto paramsFor = [](const std::string& arch, double base, double& fuel, double& blue, double& weather) {
        GridDriver g;            // fresh defaults
        ApplyAiPersonality(g, arch, base);
        fuel = g.fuel_management; blue = g.blue_flag_conceding; weather = g.weather_tyre_changes;
    };
    double f1, b1, w1, f2, b2, w2;
    paramsFor("metronomo", 0.95, f1, b1, w1);   // disciplined -> should differ from flat defaults
    paramsFor("cargador",  0.80, f2, b2, w2);   // aggressive charger -> different profile
    // At least one of the three differs from the default for EACH of two distinct archetypes.
    bool m_diff = fabs(f1 - DEF_FUEL) > 1e-6 || fabs(b1 - DEF_BLUE) > 1e-6 || fabs(w1 - DEF_WEATHER) > 1e-6;
    bool c_diff = fabs(f2 - DEF_FUEL) > 1e-6 || fabs(b2 - DEF_BLUE) > 1e-6 || fabs(w2 - DEF_WEATHER) > 1e-6;
    CHECK(m_diff);
    CHECK(c_diff);
    // The two archetypes are NOT identical across all three params (they vary BY archetype).
    bool varies = fabs(f1 - f2) > 1e-6 || fabs(b1 - b2) > 1e-6 || fabs(w1 - w2) > 1e-6;
    CHECK(varies);
}
