    career::RaceResult r; r.pos = 1; r.field = 10; r.finished = true; r.clean = false; r.race_phase = 1;
    career::SettleReport s = career::Settle(prog, r, 4500, 1000, /*rented=*/true, /*rentPct=*/22, /*carValue=*/0);
    // XpFor(1,10,false,1,1) = 1000 * 1.15(podium) = 1150 ; 37000+1150 = 38150 >= 38000 -> unlocks phase 2
    CHECK(s.phase_unlocked);
