// Version + migration hook. (1) a save written at kSaveVersion loads back intact and MigrateSave
// leaves it at kSaveVersion; (2) a legacy save with "version 1" loads cleanly; (3) a legacy save with NO version line
// (fromVersion=0) also loads cleanly; (4) MigrateSave is an idempotent no-op for v0 and for the current version.
static void test_save_version_migration() {
    // (1) round-trip at the current version: the data survives (MigrateSave is invoked inside LoadCareer)
    career::SaveData a;
    a.prog.credits = 777; a.prog.frontier_phase = 3; a.prog.rep = 42;
    const char* path = "build\\career_ver.sav";
    CHECK(career::SaveCareer(a, path));
    career::SaveData b; CHECK(career::LoadCareer(b, path));
    CHECK_EQ(b.prog.credits, 777);
    CHECK_EQ(b.prog.frontier_phase, 3);
    CHECK_EQ(b.prog.rep, 42);

    // (2) legacy save with an explicit "version 1" -> loads cleanly (back-compat)
    const char* v1 = "build\\career_ver_v1.sav";
    { FILE* f = fopen(v1, "wb"); fputs("version 1\r\ncredits 500\r\nfrontier_phase 2\r\nrep 10\r\n", f); fclose(f); }
    career::SaveData L1; CHECK(career::LoadCareer(L1, v1));
    CHECK_EQ(L1.prog.credits, 500);
    CHECK_EQ(L1.prog.frontier_phase, 2);

    // (3) legacy save with NO "version" line (fromVersion=0) -> loads cleanly all the same (the line is optional)
    const char* v0 = "build\\career_ver_v0.sav";
    { FILE* f = fopen(v0, "wb"); fputs("credits 999\r\nrep 7\r\n", f); fclose(f); }
    career::SaveData L0; CHECK(career::LoadCareer(L0, v0));
    CHECK_EQ(L0.prog.credits, 999);
    CHECK_EQ(L0.prog.rep, 7);
    CHECK_EQ(L0.prog.frontier_phase, 1);   // clean default (it wasn't in the file)

    // (4) MigrateSave directly: an idempotent no-op (doesn't mutate data), true for v0 (legacy) and for the current version
    career::SaveData m = a;
    CHECK(career::MigrateSave(m, 0));                       // an old save -> brought up to date with no changes
    CHECK_EQ(m.prog.credits, 777);                         // touched nothing
    CHECK(career::MigrateSave(m, career::kSaveVersion));    // already up to date -> true with no changes
    CHECK_EQ(m.prog.credits, 777);
}

