static void test_owns_rent() {
    // OwnsClassId: scans owned[] by class_id (the prototype's car id)
    career::SaveData d;
    d.owned.push_back({"gt4_mclar", 426939550, 0, 0.0f, true});
    CHECK( career::OwnsClassId(d, "gt4_mclar"));
    CHECK(!career::OwnsClassId(d, "gt3_992"));
    // per-car settlement: renting = rentPct% of the CAR'S VALUE; owning = run_cost, 2.5% of the value.
    career::RaceResult r; r.pos = 5; r.field = 12; r.finished = true; r.clean = false; r.race_phase = 1;
    career::CareerProgress pr1; pr1.frontier_phase = 1;
    career::SettleReport sa = career::Settle(pr1, r, 21000, 1000, /*rented=*/true,  /*rentPct=*/16, /*carValue=*/28000);
    career::CareerProgress pr2; pr2.frontier_phase = 1;
    career::SettleReport sb = career::Settle(pr2, r, 21000, 1000, /*rented=*/false, /*rentPct=*/16, /*carValue=*/28000);
    CHECK_EQ(sa.prize, sb.prize);                                  // same prize per position
    CHECK_EQ(sa.entry, sb.entry);                                  // same entry fee (same phase)
    CHECK_EQ(sa.entry, 500);                                       // phase-1 entry fee
    CHECK_EQ(sa.costs, (long)(28000 * 16 / 100.0 + 0.5));          // rental = 16% of the car's value, 28000 -> 4480
    CHECK_EQ(sb.costs, (long)(28000 * 0.025 + 0.5));               // own-car run_cost = 2.5% of 28000 -> 700
    CHECK(sb.credits_delta > sa.credits_delta);                   // owning nets more this race (run_cost < rental)
}
static void test_owned_race_costs() {
    // Amendment: REAL components; consumables scale with the race's LAP count
    // (18 vs 40 at 100%), not the duration multiplier. At COST_REF_LAPS laps each component equals its base
    // PCT and the total == RUN_COST_PCT (identical economics at the reference race).
    using namespace career;
    const int REF = bal::COST_REF_LAPS;
    CHECK(fabs((bal::COST_INSURANCE_PCT + bal::COST_TYRES_PCT + bal::COST_FUEL_PCT + bal::COST_FLUIDS_PCT)
               - bal::RUN_COST_PCT) < 1e-9);
    RaceCostBreakdown a = OwnedRaceCosts(28000, REF);   // REFERENCE race -> base PCT
    CHECK_EQ(a.insurance, (long)(28000 * bal::COST_INSURANCE_PCT + 0.5));   // 420
    CHECK_EQ(a.tyres,     (long)(28000 * bal::COST_TYRES_PCT     + 0.5));   // 140
    CHECK_EQ(a.fuel,      (long)(28000 * bal::COST_FUEL_PCT      + 0.5));   // 84
    CHECK_EQ(a.fluids,    (long)(28000 * bal::COST_FLUIDS_PCT    + 0.5));   // 56
    CHECK_EQ(a.total, a.tyres + a.fuel + a.fluids + a.insurance);          // 700 = the sum
    CHECK_EQ(a.total, (long)(28000 * bal::RUN_COST_PCT + 0.5));            // == run-cost at the reference
    // MORE laps than the reference -> consumables proportionally MORE expensive; INSURANCE doesn't scale
    RaceCostBreakdown lng = OwnedRaceCosts(28000, REF * 2);
    CHECK_EQ(lng.insurance, a.insurance);                                 // insurance is fixed (per event)
    CHECK_EQ(lng.tyres, (long)(28000 * bal::COST_TYRES_PCT * 2.0 + 0.5)); // double the laps -> double the tires
    CHECK(lng.total > a.total);                                           // a longer race = more expensive
    // FEWER laps -> cheaper consumables
    RaceCostBreakdown shrt = OwnedRaceCosts(28000, REF / 2);
    CHECK_EQ(shrt.tyres, (long)(28000 * bal::COST_TYRES_PCT * 0.5 + 0.5));// half the laps -> half the tires
    CHECK(shrt.total < a.total);
    // what the host asked for: 40 laps costs MORE than 18 laps (same car)
    CHECK(OwnedRaceCosts(28000, 40).total > OwnedRaceCosts(28000, 18).total);
    // clamps
    CHECK_EQ(OwnedRaceCosts(28000, 0).tyres, 0);                          // 0 laps -> no consumables
    CHECK_EQ(OwnedRaceCosts(28000, 0).total, a.insurance);               // insurance only
    CHECK_EQ(OwnedRaceCosts(28000, -5).total, a.insurance);              // negative laps -> clamped to 0
    CHECK_EQ(OwnedRaceCosts(-5, REF).total, 0);                          // a negative value -> 0
    // NOMINAL laps-equivalent (the duration % doesn't factor in: it's a tweak, not economics)
    CHECK_EQ(RaceLapEquivalent(18, 0), 18);                              // race by LAPS
    CHECK_EQ(RaceLapEquivalent(40, 0), 40);
    CHECK_EQ(RaceLapEquivalent(0, 40), (int)(40 / bal::COST_MIN_PER_LAP + 0.5));   // by TIME -> equivalent (40min/2=20)
    CHECK_EQ(RaceLapEquivalent(0, 0), 1);                                // no data -> minimum 1
}
static void test_settle_length_scaling() {
    // Amendment: Settle scales the PLAYER'S OWN car's consumables by LAP count (default REF = back-compat).
    using namespace career;
    const int REF = bal::COST_REF_LAPS;
    RaceResult r; r.pos = 5; r.field = 12; r.finished = true; r.clean = false; r.race_phase = 1;
    CareerProgress p1; p1.frontier_phase = 1;
    SettleReport ref = Settle(p1, r, 21000, 1000, /*rented=*/false, 16, /*carValue=*/28000);   // default REF vueltas
    CHECK_EQ(ref.costs, OwnedRaceCosts(28000, REF).total);               // 700
    CareerProgress p2; p2.frontier_phase = 1;
    SettleReport lng = Settle(p2, r, 21000, 1000, false, 16, 28000,
                               -1, false, 0, 0, 0, 0, 0, /*raceLaps=*/REF * 2);
    CHECK_EQ(lng.costs, OwnedRaceCosts(28000, REF * 2).total);           // more laps -> more expensive
    CHECK(lng.costs > ref.costs);
    // RENTED: rental = rentPct% of the value, LAPS don't touch it
    CareerProgress p3; p3.frontier_phase = 1;
    SettleReport rentLng = Settle(p3, r, 21000, 1000, /*rented=*/true, 16, 28000,
                               -1, false, 0, 0, 0, 0, 0, /*raceLaps=*/REF * 2);
    CHECK_EQ(rentLng.costs, (long)(28000 * 16 / 100.0 + 0.5));           // 4480 (not scaled by laps)
}
// (real wear): ApplyWearToCosts scales the nominal CONSUMABLES using shared-memory telemetry, and
// Settle applies it to the PLAYER'S OWN car. Invariants:
//   (a) a REFERENCE race (wear == WEAR_REF_*) -> EXACTLY the nominal value (multiplier 1.0);
//   (b) no telemetry (fields < 0 / null pointer) -> NOMINAL (fail-open: shared memory off = the old economics);
//   (c) babying the car makes it cheaper, thrashing it makes it pricier, with a floor/cap (WEAR_MULT_MIN/MAX);
//   (d) fluids + insurance are NEVER touched (damage is already billed through the deductible -> no double-charging);
//   (e) a RENTED car ignores wear (consumables are baked into the rental price).
static void test_wear_costs() {
    using namespace career;
    const int REF = bal::COST_REF_LAPS;
    RaceCostBreakdown nom = OwnedRaceCosts(28000, REF);

    // (a) reference wear -> EXACTLY nominal
    WearTelemetry refWear; refWear.tyreWear = (float)bal::WEAR_REF_TYRE; refWear.fuelUsed = (float)bal::WEAR_REF_FUEL;
    RaceCostBreakdown atRef = ApplyWearToCosts(nom, refWear);
    CHECK_EQ(atRef.tyres, nom.tyres);
    CHECK_EQ(atRef.fuel,  nom.fuel);
    CHECK_EQ(atRef.total, nom.total);

    // (b) NO telemetry -> nominal untouched
    WearTelemetry none;                                    // both fields -1 (no data)
    RaceCostBreakdown noTel = ApplyWearToCosts(nom, none);
    CHECK_EQ(noTel.tyres, nom.tyres);
    CHECK_EQ(noTel.fuel,  nom.fuel);
    CHECK_EQ(noTel.total, nom.total);

    // (c) CAREFUL driving (tires nearly new, low fuel use) -> cheaper, but not below the floor
    WearTelemetry soft; soft.tyreWear = 0.05f; soft.fuelUsed = 0.05f;
    RaceCostBreakdown cheap = ApplyWearToCosts(nom, soft);
    CHECK(cheap.tyres < nom.tyres);
    CHECK(cheap.total < nom.total);
    CHECK_EQ(cheap.tyres, (long)(nom.tyres * bal::WEAR_MULT_MIN + 0.5));   // hits the FLOOR
    CHECK_EQ(cheap.fuel,  (long)(nom.fuel  * bal::WEAR_MULT_MIN + 0.5));
    // BRUTAL driving (tires trashed, tank run dry) -> more expensive, with a cap
    WearTelemetry hard; hard.tyreWear = 1.0f; hard.fuelUsed = 1.0f;
    RaceCostBreakdown dear = ApplyWearToCosts(nom, hard);
    CHECK(dear.tyres > nom.tyres);
    CHECK(dear.total > nom.total);
    CHECK_EQ(dear.tyres, (long)(nom.tyres * bal::WEAR_MULT_MAX + 0.5));    // hits the CAP
    // monotonic: more wear never costs less
    WearTelemetry mid; mid.tyreWear = 0.75f; mid.fuelUsed = 0.75f;
    RaceCostBreakdown midc = ApplyWearToCosts(nom, mid);
    CHECK(midc.total >= atRef.total && midc.total <= dear.total);

    // (d) fluids + insurance untouched in ALL cases; total = the sum of the 4
    CHECK_EQ(cheap.fluids, nom.fluids);   CHECK_EQ(cheap.insurance, nom.insurance);
    CHECK_EQ(dear.fluids,  nom.fluids);   CHECK_EQ(dear.insurance,  nom.insurance);
    CHECK_EQ(dear.total, dear.tyres + dear.fuel + dear.fluids + dear.insurance);

    // only one component has data -> the other stays nominal
    WearTelemetry onlyTyre; onlyTyre.tyreWear = 1.0f;      // fuelUsed stays -1 (no data)
    RaceCostBreakdown ot = ApplyWearToCosts(nom, onlyTyre);
    CHECK(ot.tyres > nom.tyres);
    CHECK_EQ(ot.fuel, nom.fuel);                           // NOMINAL fuel

    // Settle: the PLAYER'S OWN car is billed real wear; a RENTED one is not ---
    RaceResult r; r.pos = 5; r.field = 12; r.finished = true; r.clean = false; r.race_phase = 1;
    CareerProgress pn; pn.frontier_phase = 1;
    SettleReport sNom = Settle(pn, r, 21000, 1000, /*rented=*/false, 16, 28000);   // sin wear -> nominal
    CHECK_EQ(sNom.costs, nom.total);
    CareerProgress ph; ph.frontier_phase = 1;
    SettleReport sHard = Settle(ph, r, 21000, 1000, false, 16, 28000,
                                -1, false, 0, 0, 0, 0, 0, REF, /*wear=*/&hard);
    CHECK_EQ(sHard.costs, dear.total);                     // punishing the car costs MORE
    CHECK(sHard.costs > sNom.costs);
    CareerProgress ps; ps.frontier_phase = 1;
    SettleReport sSoft = Settle(ps, r, 21000, 1000, false, 16, 28000,
                                -1, false, 0, 0, 0, 0, 0, REF, /*wear=*/&soft);
    CHECK_EQ(sSoft.costs, cheap.total);                    // looking after it costs LESS
    CHECK(sSoft.credits_delta > sHard.credits_delta);      // and therefore nets more
    // (e) RENTED: wear does NOT change the cost (it's baked into the rental price)
    CareerProgress pr1; pr1.frontier_phase = 1;
    SettleReport sRent = Settle(pr1, r, 21000, 1000, /*rented=*/true, 16, 28000,
                                -1, false, 0, 0, 0, 0, 0, REF, /*wear=*/&hard);
    CHECK_EQ(sRent.costs, (long)(28000 * 16 / 100.0 + 0.5));
    // a FACTORY seat: costs are 0 no matter what happens with wear
    CareerProgress pf; pf.frontier_phase = 1;
    SettleReport sFac = Settle(pf, r, 21000, 1000, false, 16, 28000,
                               -1, /*factorySeat=*/true, 0, 0, 0, 0, 0, REF, /*wear=*/&hard);
    CHECK_EQ(sFac.costs, 0);
}
