// The race that was lost entirely to an ODD sequence number (from a player's log, 08/06/2026).
// AMS2 resets mSequenceNumber on every session change, and the starting value can land on an odd number; with the
// SDK's bare rule ("odd = a write is in progress, skip the frame") that vetoes 100% of the reads
// for the rest of the session, silently. In their log: qualifying was normal, then 6m30s into the race with not one
// single shared-memory read — they won the race and nothing got recorded. Parity checking now vetoes WITH A TIMEOUT.
static void test_shm_seq_gate() {
    using namespace career;
    // (a) normal parity: even always passes, odd vetoes (a write in flight)
    ShmSeqGate g;
    CHECK(g.Allow(1000, 10000));
    CHECK(!g.Allow(1001, 10000));      // odd just seen -> the frame is skipped, as always
    CHECK(g.Allow(1002, 10001));       // the write finished
    CHECK(!g.parked);

    // (b) a long BUT plausible write is still vetoed while inside the timeout window
    ShmSeqGate h;
    CHECK(!h.Allow(7, 5000));
    CHECK(!h.Allow(7, 5000 + kOddParkMs));   // right at the edge of the window: not yet
    CHECK(!h.parked);

    // (c) that player's case: the counter rests at an ODD value and advances two at a time.
    //     Once the window passes, the rest state is declared inverted and reading resumes (announced only once).
    ShmSeqGate k;
    CHECK(!k.Allow(111, 1000));
    CHECK(!k.Allow(471, 1500));
    CHECK(k.Allow(831, 1000 + kOddParkMs + 1));
    CHECK(k.parked);
    CHECK(k.JustParked());                     // the notice fires on the edge...
    CHECK(k.Allow(1191, 3000));
    CHECK(!k.JustParked());                    // ...and does NOT repeat every frame
    CHECK(k.Allow(999999, 9000));              // it keeps reading for as long as the odd streak lasts

    // (d) a new session with normal parity -> the SDK's rule re-arms, without carrying over state
    CHECK(k.Allow(200, 9500));
    CHECK(!k.parked);
    CHECK(!k.Allow(201, 9500));

    // (e) GetTickCount wrapping to zero (49.7 days) doesn't hand out a negative window or fire it early
    ShmSeqGate w;
    const unsigned long nearWrap = 0xFFFFFF00ul;
    CHECK(!w.Allow(3, nearWrap));
    CHECK(!w.Allow(3, (unsigned long)(nearWrap + 100)));            // 100 ms later, still inside the window
    CHECK(w.Allow(3, (unsigned long)(nearWrap + kOddParkMs + 1)));  // crossing zero, the window elapses
}
// The settlement gate: RETIRING IS NOT THE SAME AS THE RACE HAVING ENDED.
// A report from 08/06, log in hand: the player pitted, stayed on as a spectator, and the result got
// recorded at that exact instant (18:39:34) while the race was still live two and a half minutes later (18:41:53). The gate
// was checking the PLAYER's own state (3=finished / 5=retired / 6=DNF), and none of the three says anything about the race itself.
// The right piece already existed and just wasn't wired in: RaceIsOver, which asks about the REAL leader. This pins down its
// contract for the cases that actually occur on an AMS2 grid -- including a Safety Car, which is exactly what
// breaks any "nobody is still racing" rule (the Safety Car never crosses the finish line).
static void test_race_over_gate() {
    using namespace career;
    // the player retires to the pits in last place; everyone else is still on track -> the race has NOT ended
    std::vector<ParticipantSnap> retiredMidRace = {
        { "Emil Strand",  "Ember_Series", 1, 8, RS_RACING,  true },
        { "Marco Bianchi","Ember_Series", 2, 8, RS_RACING,  true },
        { "Safety Car",   "",        0, 8, RS_RACING,  true },
        { "Josh B",       "Ember_Series",28, 3, RS_RETIRED, true },
    };
    CHECK(!RaceIsOver(retiredMidRace));
    // ... and when the leader crosses, the race HAS NOT ended yet while anyone is still on their last lap
    // (19/09, see test_race_over_waits_for_field). When the last one crosses, it HAS, even if the Safety Car is still
    // flagged as running: the SC never crosses the line and so does not count.
    std::vector<ParticipantSnap> leaderHome = {
        { "Emil Strand",  "Ember_Series", 1, 9, RS_FINISHED, true },
        { "Marco Bianchi","Ember_Series", 2, 9, RS_RACING,   true },
        { "Safety Car",   "",        0, 9, RS_RACING,   true },
        { "Josh B",       "Ember_Series",28, 3, RS_RETIRED,  true },
    };
    CHECK(!RaceIsOver(leaderHome));
    leaderHome[1].laps = 10; leaderHome[1].raceState = RS_FINISHED;
    CHECK(RaceIsOver(leaderHome));
    // the retired player still stays IN the final standings: waiting for the checkered flag doesn't erase them from the classification, which is
    // the other half of what's needed (being able to retire and still get a result). Their DNF mark is set by
    // the settle step (r.finished); Classify currently doesn't match that criterion -- a separate defect, untouched here.
    { auto cls = Classify(leaderHome);
      auto me = std::find_if(cls.begin(), cls.end(), [](const ClassifiedEntry& e){ return e.name == "Josh B"; });
      CHECK(me != cls.end()); CHECK_EQ(me->pos, 3); }   // 3 real drivers: the Safety Car doesn't get classified
    // a grid still on the starting grid (nobody has raced yet) -> NOT the end of the race
    std::vector<ParticipantSnap> onGrid = {
        { "Emil Strand",  "Ember_Series", 1, 0, 1, true },   // 1 = NOT_STARTED
        { "Marco Bianchi","Ember_Series", 2, 0, 1, true },
    };
    CHECK(!RaceIsOver(onGrid));
    // an empty read / no readable leader -> not that either (the session-exit fallback covers this case)
    CHECK(!RaceIsOver(std::vector<ParticipantSnap>{}));
    std::vector<ParticipantSnap> noLeader = {
        { "Marco Bianchi","Ember_Series", 2, 9, RS_FINISHED, true },
    };
    CHECK(!RaceIsOver(noLeader));
    // the Safety Car can NEVER decide the end of the race even if it shows up first
    std::vector<ParticipantSnap> scFirst = {
        { "Safety Car",   "",        1, 9, RS_FINISHED, true },
        { "Emil Strand",  "Ember_Series", 2, 9, RS_RACING,   true },
    };
    CHECK(!RaceIsOver(scFirst));
}

// 19/09 — «Everyone who was behind comes out lapped» (player report). He won, and the race was settled at
// the instant HE crossed the line: the rest were halfway through their last lap, so the app showed them with
// one lap less, with half-finished times and with positions that could still change... and the championship
// points came out of that snapshot. The end of the race now waits until no active real driver is still on track.
static void test_race_over_waits_for_field() {
    using namespace career;
    // the reported case: the player wins and the rest are still on their last lap -> NOT finished
    std::vector<ParticipantSnap> g = {
        { "Jugador",       "GT3", 1, 12, RS_FINISHED, true },
        { "Emil Strand",   "GT3", 2, 11, RS_RACING,   true },
        { "Marco Bianchi", "GT3", 3, 11, RS_RACING,   true },
        { "Doblado Uno",   "GT3", 4, 10, RS_RACING,   true },   // lapped: has to cross once more
        { "Safety Car",    "",    0, 12, RS_RACING,   true },   // artifact: never blocks
    };
    CHECK(!RaceIsOver(g));
    // they cross one at a time: while one is still on track, it is still not finished
    g[1].laps = 12; g[1].raceState = RS_FINISHED;
    CHECK(!RaceIsOver(g));
    g[2].laps = 12; g[2].raceState = RS_FINISHED;
    CHECK(!RaceIsOver(g));
    // the lapped car crosses with ONE lap less than the leader (the one it really lacks), not two
    g[3].laps = 11; g[3].raceState = RS_FINISHED;
    CHECK(RaceIsOver(g));
    { auto cls = Classify(g);
      CHECK_EQ((long)cls.size(), 4);
      CHECK(cls[1].name == "Emil Strand" && cls[1].laps == 12 && cls[1].finished);
      CHECK(cls[3].name == "Doblado Uno" && cls[3].laps == 11 && cls[3].finished); }
    // DNFs, retired and disqualified are already out: they make nobody wait
    std::vector<ParticipantSnap> outs = {
        { "Jugador",     "GT3", 1, 12, RS_FINISHED, true },
        { "Roto",        "GT3", 0,  5, RS_DNF,      true },
        { "A boxes",     "GT3", 0,  8, RS_RETIRED,  true },
        { "Bandera negra","GT3",0,  7, RS_DSQ,      true },
        { "Inactivo",    "GT3", 9,  3, RS_RACING,   false },   // inactive slot: ignored even if it says RACING
    };
    CHECK(RaceIsOver(outs));
    // an odd state (0 = no data, 1 = not out) with the leader already at the finish cannot advance: does not block
    std::vector<ParticipantSnap> odd = {
        { "Jugador",     "GT3", 1, 12, RS_FINISHED, true },
        { "Nunca salio", "GT3", 2,  0, 1,           true },
        { "Sin dato",    "GT3", 3,  0, 0,           true },
    };
    CHECK(RaceIsOver(odd));
    // and the leader still rules: with the leader still running it has not finished even if everyone else is out
    std::vector<ParticipantSnap> leaderRunning = {
        { "Emil Strand", "GT3", 1, 11, RS_RACING,  true },
        { "Jugador",     "GT3", 2, 11, RS_RETIRED, true },
    };
    CHECK(!RaceIsOver(leaderRunning));
}

static void test_classify_by_class() {
    using namespace career;
    // A multiclass grid: 2 Pemberton_Zel121 + 4 GT3 (one DNF). The player is in GT3: P3 overall but P1 IN CLASS.
    std::vector<ClassifiedEntry> global = {
        { "Pemberton Zel121 Uno",    "Pemberton_Zel121",     1, 40, true,  false },
        { "Pemberton Zel121 Dos",    "Pemberton_Zel121",     2, 40, true,  false },
        { "Jugador",     "GT3 Gen1", 3, 40, true,  false },
        { "Gt3 Bravo",   "GT3 Gen1", 4, 40, true,  false },
        { "Gt3 Charlie", "gt3 gen1", 5, 39, true,  false },   // different capitalization: same class
        { "Gt3 Dnf",     "GT3 Gen1", 6, 30, false, true  },
        { "Gt3 Echo",    " GT3 Gen1 ", 7, 29, false, true  },   // a class with spaces: normClass trims it
    };
    CHECK_EQ(DistinctClassCount(global), 2);
    std::vector<ClassifiedEntry> mono = {
        { "A", "F-V12", 1, 10, true, false }, { "B", "F-V12", 2, 10, true, false },
    };
    CHECK_EQ(DistinctClassCount(mono), 1);

    ClassResult cr = ClassifyByClass(global, "GT3 Gen1", "Jugador");
    CHECK_EQ((long)cr.entries.size(), 5);
    CHECK_EQ(cr.pos, 1);                          // P3 overall -> P1 in class
    CHECK_EQ(cr.field, 5);
    CHECK(cr.entries[0].name == "Jugador"     && cr.entries[0].pos == 1);
    CHECK(cr.entries[1].name == "Gt3 Bravo"   && cr.entries[1].pos == 2);
    CHECK(cr.entries[2].name == "Gt3 Charlie" && cr.entries[2].pos == 3);   // case-insensitive match
    CHECK(cr.entries[3].name == "Gt3 Dnf"     && cr.entries[3].pos == 4 && cr.entries[3].dnf);   // a DNF keeps its position at the end
    CHECK(cr.entries[4].name == "Gt3 Echo"    && cr.entries[4].pos == 5);   // a class with spaces: trimmed in normClass

    CHECK_EQ(ClassifyByClass(global, "GT3 Gen1", "").pos, 0);   // an empty name NEVER matches (a guard from final review)

    ClassResult other = ClassifyByClass(global, "PEMBERTON_ZEL121", "Jugador");   // the player is NOT in that class
    CHECK_EQ((long)other.entries.size(), 2);
    CHECK_EQ(other.pos, 0);

    ClassResult empty = ClassifyByClass(global, "", "Jugador");       // an empty class -> no match
    CHECK(empty.entries.empty() && empty.pos == 0 && empty.field == 0);

    ClassResult unknown = ClassifyByClass(global, "LANTERN_MASTERS_7489", "Jugador"); // a missing class -> no match
    CHECK(unknown.entries.empty() && unknown.pos == 0);
}
// RETIRING IS A DNF, IN THE STANDINGS TOO.
// User reports: "my penalties aren't being applied". Half the cause had already been fixed (the
// player's result and the season history already recorded the DNF); the other half was still open here. Classify
// was counting a RETIRED driver (state 5, which is what AMS2 sets when pitting out) as FINISHED:
//     e.dnf = (DNF || DSQ);   e.finished = (FINISHED || RETIRED);
// and from there hang the championship points (ScoreRound skips DNFs), the rating duel (career_engine:
// "DNF does not contest") and the grid the app displays. The result: you'd retire, your card would say DNF, and the
// standings would still give you the points for your position. The settle step had already been using the correct criterion since
// (r.finished = state != DNF && != RETIRED && != DSQ); this brings Classify in line with it.
static void test_classify_retired_is_dnf() {
    using namespace career;
    std::vector<ParticipantSnap> grid = {
        { "Emil Strand",  "Ember_Series", 1, 9, RS_FINISHED, true },
        { "Marco Bianchi","Ember_Series", 2, 9, RS_FINISHED, true },
        { "Otto Vance",   "Ember_Series", 3, 9, RS_DSQ,      true },   // disqualified: a DNF as always
        { "Josh B",       "Ember_Series", 4, 3, RS_RETIRED,  true },   // pitting out: AMS2 flags it as 5, not 6
        { "Pol Riera",    "Ember_Series", 5, 2, RS_DNF,      true },
    };
    auto cls = Classify(grid);
    auto at = [&](const char* n) { for (const auto& e : cls) if (e.name == n) return e; return ClassifiedEntry{}; };
    CHECK(at("Emil Strand").finished  && !at("Emil Strand").dnf);
    CHECK(!at("Josh B").finished      &&  at("Josh B").dnf);        // whoever retires has NOT finished
    CHECK(!at("Otto Vance").finished  &&  at("Otto Vance").dnf);
    CHECK(!at("Pol Riera").finished   &&  at("Pol Riera").dnf);
    // the SAME criterion the player's settle step uses — one single source of truth for both paths
    for (const auto& p : grid) {
        bool settleSaysFinished = (p.raceState != RS_DNF && p.raceState != RS_RETIRED && p.raceState != RS_DSQ);
        CHECK_EQ((long)at(p.name.c_str()).finished, (long)settleSaysFinished);
    }
    // and the missing penalty: retiring stops earning championship points
    PointsSystem sys; sys.points = {25,18,15,12,10,8,6,4,2,1}; sys.fl_point = 1; sys.fl_top_n = 10;
    auto sc = ScoreRound(cls, sys, 1.0, "Josh B");   // even while holding the fastest lap
    auto pts = [&](const char* n) { for (const auto& r : sc) if (r.name == n) return r; return RoundScore{}; };
    CHECK_EQ((long)pts("Emil Strand").points, 25L);
    CHECK_EQ((long)pts("Josh B").points, 0L);        // no points for position...
    CHECK(!pts("Josh B").fl);                        // ...nor the fastest-lap point
    CHECK(pts("Josh B").dnf);
    CHECK_EQ((long)pts("Otto Vance").points, 0L);
}

static void test_scoring() {
    using namespace career;
    PointsSystem sys; sys.points = {25,18,15,12,10,8,6,4,2,1}; sys.fl_point = 1; sys.fl_top_n = 10;
    std::vector<ClassifiedEntry> cls = {
        { "Aryton Senda", "", 1, 10, true,  false },
        { "Alan Prest",   "", 2, 10, true,  false },
        { "Nilson Picket","", 3, 10, true,  false },
        { "Nicky Mansel", "", 4,  6, false, true  },   // DNF -> 0
    };
    auto find = [](const std::vector<RoundScore>& v, const char* n) -> RoundScore {
        for (const auto& r : v) if (r.name == n) return r; return RoundScore{};
    };
    auto feat = ScoreRound(cls, sys, 1.0, "Aryton Senda");   // the leader's fastest lap
    CHECK_EQ((long)feat.size(), 4);
    CHECK(find(feat, "Aryton Senda").points == 26 && find(feat, "Aryton Senda").fl);   // 25 + 1 for fastest lap
    CHECK(find(feat, "Alan Prest").points == 18);
    CHECK(find(feat, "Nilson Picket").points == 15);
    CHECK(find(feat, "Nicky Mansel").points == 0 && find(feat, "Nicky Mansel").dnf);

    auto sprint = ScoreRound(cls, sys, 0.5, "");             // half points, no fastest lap
    CHECK_EQ(find(sprint, "Aryton Senda").points, 13);       // round(25*0.5)=13
    CHECK_EQ(find(sprint, "Alan Prest").points, 9);          // round(18*0.5)=9
    CHECK_EQ(find(sprint, "Nilson Picket").points, 8);       // round(15*0.5)=8
    CHECK(!find(sprint, "Aryton Senda").fl);                 // no fastest lap
}
static void test_standings() {
    using namespace career;
    Standings s; s.node_id = "f_v12"; s.points_system = "nimbus_championship_1339";
    // Rounds 1 and 2: Senda wins both, Prest 2nd, Picket 3rd.
    std::vector<RoundScore> r1 = { {"Senda",1,25,false,false}, {"Prest",2,18,false,false}, {"Picket",3,15,false,false} };
    std::vector<RoundScore> r2 = { {"Senda",1,25,false,false}, {"Prest",2,18,false,false}, {"Picket",3,15,false,false} };
    ApplyRound(s, 1, r1);
    ApplyRound(s, 2, r2);
    CHECK_EQ(s.round, 2);
    auto tbl = FinalTable(s, 0);
    CHECK_EQ((long)tbl.size(), 3);
    CHECK(tbl[0].name == "Senda" && tbl[0].total == 50 && tbl[0].wins == 2 && tbl[0].played == 2);
    CHECK(tbl[1].name == "Prest" && tbl[1].total == 36 && tbl[1].wins == 0);
    CHECK(tbl[2].name == "Picket"&& tbl[2].total == 30);

    // Drop-rounds: a driver with 25,10,2; drop the worst (2) -> 35.
    Standings d; d.node_id = "x"; d.points_system = "y";
    ApplyRound(d, 1, { {"Solo",1,25,false,false} });
    ApplyRound(d, 2, { {"Solo",5,10,false,false} });
    ApplyRound(d, 3, { {"Solo",9, 2,false,false} });
    CHECK_EQ(FinalTable(d, 0)[0].total, 37);
    CHECK_EQ(FinalTable(d, 1)[0].total, 35);   // drops the 2

    // a DUPLICATED driver on the grid would appear TWICE in the same classification, and the table would
    // add up both positions (points accumulate by name). New rule: a driver scores ONCE per
    // round — keeping their BEST result (more points; ties broken by better position).
    Standings dup; dup.node_id = "x2"; dup.points_system = "y";
    ApplyRound(dup, 1, { {"Doble",1,25,false,false}, {"Solo2",2,18,false,false}, {"Doble",5,10,false,false} });
    auto tdup = FinalTable(dup, 0);
    CHECK_EQ((long)tdup.size(), 2);
    CHECK(tdup[0].name == "Doble" && tdup[0].total == 25 && tdup[0].played == 1 && tdup[0].wins == 1);
    CHECK(tdup[1].name == "Solo2" && tdup[1].total == 18);
    // reverse order (the worse result arrives first): the better one still wins, and played doesn't double-count
    Standings dup2; dup2.node_id = "x3"; dup2.points_system = "y";
    ApplyRound(dup2, 1, { {"Doble",5,10,false,false}, {"Doble",1,25,false,false} });
    CHECK_EQ(FinalTable(dup2, 0)[0].total, 25);
    CHECK_EQ(FinalTable(dup2, 0)[0].played, 1);
}
// (08/24): the player changes their nickname (Steam/AMS2) mid-season — the table accumulates by name, and
// the change split them into two drivers with the points divided between them (a player reported: 2 races under the nickname, then the real name
// afterward, "the league table counts me as a new driver"). RenameDriverInStandings merges them.
// 01/10 ([tester]): the nick migration only touched the per-class files; the tables of the
// ENROLLED championships (career_seasons.sav, the ones on screen) still had the player split in two: "[tester]" P2 with
// nine rounds and "[tester]" P10 with one. RenamePlayerInEnrollments merges in each enrollment.
static void test_enrollments_rename_player() {
    using namespace career;
    CareerCalendar cc;
    SeasonState e; e.series_id = "granite_series"; e.standings.node_id = "Millhurst Motors"; e.standings.points_system = "club";
    for (int r = 1; r <= 9; r++) ApplyRound(e.standings, r, { {"[tester-14]",1,25,false,false}, {"Marcelo Britto",2,18,false,false} });
    ApplyRound(e.standings, 10, { {"[tester-15]",1,25,false,false}, {"Marcelo Britto",2,18,false,false} });
    SeasonState f; f.series_id = "drift_masters_3348"; f.standings.node_id = "Onyx Challenge"; f.standings.points_system = "club";
    ApplyRound(f.standings, 1, { {"Otro Piloto",1,25,false,false}, {"[tester-14]",2,18,false,false} });
    cc.enrollments.push_back(e); cc.enrollments.push_back(f);
    CHECK_EQ(RenamePlayerInEnrollments(cc, "[tester-14]", "[tester-15]"), 2);   // the TWO enrollments
    CHECK_EQ((long)cc.enrollments[0].standings.drivers.count("[tester-14]"), 0);
    CHECK_EQ((long)cc.enrollments[0].standings.drivers["[tester-15]"].size(), 10);   // 9 + 1, a single row
    auto tbl = FinalTable(cc.enrollments[0].standings, 0);
    CHECK_EQ((long)tbl.size(), 2);
    CHECK(tbl[0].name == "[tester-15]" && tbl[0].total == 250 && tbl[0].played == 10);
    CHECK_EQ((long)cc.enrollments[1].standings.drivers["[tester-15]"].size(), 1);
    CHECK_EQ(RenamePlayerInEnrollments(cc, "[tester-14]", "[tester-15]"), 0);   // idempotent
    CHECK_EQ(RenamePlayerInEnrollments(cc, "Nadie", "[tester-15]"), 0);
    // 02/10: the card->nick reconciliation goes with a GUARD. An AI rival named like the card ran the
    // same rounds as the player: they share a round and are NOT merged. The real case (disjoint rounds) is.
    Standings g; g.node_id = "Millhurst Motors"; g.points_system = "club";
    ApplyRound(g, 1, { {"Felipe Tanaka",1,25,false,false}, {"xXnickXx",2,18,false,false} });   // AI namesake
    ApplyRound(g, 2, { {"Felipe Tanaka",3,15,false,false}, {"xXnickXx",1,25,false,false} });
    CHECK(!MergePlayerKeyInStandings(g, "Felipe Tanaka", "xXnickXx"));
    CHECK_EQ((long)g.drivers.count("Felipe Tanaka"), 1);                              // the rival stays in its row
    CHECK_EQ((long)g.drivers["xXnickXx"].size(), 2);
    Standings h; h.node_id = "Millhurst Motors"; h.points_system = "club";
    for (int r = 1; r <= 9; r++) ApplyRound(h, r, { {"[tester-14]",1,25,false,false} });
    ApplyRound(h, 10, { {"[tester-15]",1,25,false,false} });
    CHECK(MergePlayerKeyInStandings(h, "[tester-14]", "[tester-15]"));            // disjoint: it is the same person
    CHECK_EQ((long)h.drivers["[tester-15]"].size(), 10);
    CHECK(!MergePlayerKeyInStandings(h, "[tester-14]", "[tester-15]"));           // idempotent
    Standings w; ApplyRound(w, 1, { {"[tester-14]",1,25,false,false} });          // no nick row yet
    CHECK(MergePlayerKeyInStandings(w, "[tester-14]", "[tester-15]"));
    Standings d2; ApplyRound(d2, 1, { {"[tester-14]",1,25,false,false} }); ApplyRound(d2, 2, { {"[tester-15]",1,25,false,false} });
    d2.ids["[tester-14]"] = "rd_otra"; d2.ids["[tester-15]"] = "player";       // two different ids: two people
    CHECK(!MergePlayerKeyInStandings(d2, "[tester-14]", "[tester-15]"));
    CareerCalendar cg; SeasonState eg; eg.series_id = "granite_series"; eg.standings = g; cg.enrollments.push_back(eg);
    CHECK_EQ(RenamePlayerInEnrollments(cg, "Felipe Tanaka", "xXnickXx", /*guarded=*/true), 0);
}

static void test_standings_rename() {
    using namespace career;
    Standings s; s.node_id = "g40"; s.points_system = "club";
    ApplyRound(s, 1, { {"[tester-2]",1,25,false,false}, {"Rival",2,18,false,false} });
    ApplyRound(s, 2, { {"[tester-2]",2,18,false,false}, {"Rival",1,25,false,false} });
    ApplyRound(s, 3, { {"Dario Rossi",1,25,false,false}, {"Rival",2,18,false,false} });   // already renamed
    s.contacts["[tester-2]"] = 2; s.contacts["Dario Rossi"] = 1;
    CHECK(RenameDriverInStandings(s, "[tester-2]", "Dario Rossi"));
    CHECK_EQ((long)s.drivers.count("[tester-2]"), 0);              // the old name disappears
    CHECK_EQ((long)s.drivers["Dario Rossi"].size(), 3);        // all 3 rounds, merged and sorted
    CHECK_EQ(s.drivers["Dario Rossi"][0].round, 1);
    CHECK_EQ(s.drivers["Dario Rossi"][2].round, 3);
    auto tbl = FinalTable(s, 0);
    CHECK_EQ((long)tbl.size(), 2);                             // the player and Dario Rossi are now ONE
    CHECK(tbl[0].name == "Dario Rossi" && tbl[0].total == 68 && tbl[0].wins == 2 && tbl[0].played == 3);
    CHECK_EQ(s.contacts["Dario Rossi"], 3);                    // legacy contacts summed
    // a round clash (an odd save: both names scored round 1) -> keeps the BEST one
    Standings c;
    ApplyRound(c, 1, { {"Viejo",3,15,false,false}, {"Nuevo",5,10,false,false} });
    CHECK(RenameDriverInStandings(c, "Viejo", "Nuevo"));
    CHECK_EQ((long)c.drivers["Nuevo"].size(), 1);
    CHECK_EQ(c.drivers["Nuevo"][0].points, 15);                // 15 > 10: the old name's result wins
    // no-ops: name absent, or old == new
    CHECK(!RenameDriverInStandings(c, "NoEsta", "Nuevo"));
    CHECK(!RenameDriverInStandings(c, "Nuevo", "Nuevo"));
    // round-trip: the merge survives save/load
    const char* p = "build/_rename_champ.sav";
    CHECK(SaveStandings(s, p));
    Standings r; CHECK(LoadStandings(r, p));
    CHECK_EQ((long)r.drivers.count("[tester-2]"), 0);
    CHECK_EQ((long)r.drivers["Dario Rossi"].size(), 3);
    remove(p);
    // the shared-memory's latest nickname round-trips through the career save (a key with spaces)
    { const char* ps = "build/_shmname.sav";
      SaveData a; a.shm_player_name = "Dario Rossi 27";
      CHECK(SaveCareer(a, ps));
      SaveData b; CHECK(LoadCareer(b, ps));
      CHECK(b.shm_player_name == "Dario Rossi 27");
      remove(ps); }
}

// (08/24, a player's report): "two parents with different names" in the memories feature — the tree is now
// a FAMILY: within a generation, the most recent decade is the direct line and the rest are uncles.
static void test_ancestor_relations() {
    auto rel = capi::AncestorRelationsForDecades({1990, 1980, 1970, 1960, 1950}, /*birthYear=*/1985);
    CHECK(rel[1990] == "father");            // the most recent from generation 1 = direct line
    CHECK(rel[1980] == "uncle");             // the reported case: it used to produce TWO "father" entries
    CHECK(rel[1970] == "grandfather");
    CHECK(rel[1960] == "greatUncle");
    CHECK(rel[1950] == "greatGrandfather");
    // a single decade per generation -> everything direct line (no gratuitous uncles)
    auto solo = capi::AncestorRelationsForDecades({1990, 1970}, 1985);
    CHECK(solo[1990] == "father");
    CHECK(solo[1970] == "grandfather");
    // birth year left unset (internal fallback to 2000): with 2000 the 1990/1980 decades fall into
    // DIFFERENT generations -> both direct line, and there's still no two fathers
    auto def = capi::AncestorRelationsForDecades({1990, 1980}, 0);
    CHECK(def[1990] == "father");
    CHECK(def[1980] == "grandfather");
}

static void test_standings_save() {
    using namespace career;
    Standings a; a.node_id = "f_v12"; a.points_system = "nimbus_championship_1339"; a.season_year = 1;
    ApplyRound(a, 1, { {"Aryton Senda",1,25,true,false}, {"Alan Prest",2,18,false,false} });
    ApplyRound(a, 2, { {"Alan Prest",1,25,false,false},  {"Aryton Senda",2,18,false,false} });

    const char* path = "build\\champ_test.sav";
    CHECK(SaveStandings(a, path));

    Standings b;
    CHECK(LoadStandings(b, path));
    CHECK(b.node_id == "f_v12" && b.points_system == "nimbus_championship_1339");
    CHECK_EQ(b.season_year, 1);
    CHECK_EQ(b.round, 2);
    CHECK_EQ((long)b.drivers.size(), 2);
    CHECK(b.drivers.count("Aryton Senda") == 1 && (long)b.drivers["Aryton Senda"].size() == 2);
    CHECK(b.drivers["Aryton Senda"][0].round == 1 && b.drivers["Aryton Senda"][0].pos == 1 &&
          b.drivers["Aryton Senda"][0].points == 25 && b.drivers["Aryton Senda"][0].fl);
    // the table gets rebuilt the same way after loading
    auto tbl = FinalTable(b, 0);
    CHECK(tbl[0].total == 43 && tbl[1].total == 43);       // tie 25+18 both; tiebreak by wins->name
    Standings c;
    CHECK(!LoadStandings(c, "build\\no_existe_champ.sav"));
    CHECK_EQ(c.round, 0);                                   // falls back to defaults
}

static std::string slurp(const char* p) {
    FILE* f = fopen(p, "rb"); if (!f) return std::string();
    std::string s; char b[256]; size_t n;
    while ((n = fread(b, 1, sizeof(b), f)) > 0) s.append(b, n);
    fclose(f); return s;
}
















