// from the portal: the calendar's weather column as a list. Empty = the player decides; "0" IS already a
// datum (clear); "0,8,12,17" = four slots; from the fifth on it is ignored. The columns behind it do not move.
static void test_series_calendar_weather_list() {
    using namespace career;
    { FILE* f = fopen("build\\wx_cal.psv", "wb");
      fputs("# series_id|round|doy|date|track_hash|track_name|fmt|laps|durationMin|hour|weather|note|practiceMin|qualifyMin\r\n"
            "wx|1|70|Mar 11|1|Fairworth Speedway|1|72|0|13||lo decide el jugador|30|15\r\n"
            "wx|2|80|Mar 21|2|Wildham|1|44|0|13|0|despejado autorado|30|15\r\n"
            "wx|3|90|Mar 31|3|Northhurst Park|1|53|0|13|8|tormenta electrica|30|15\r\n"
            "wx|4|100|Apr 9|4|Thorndale|1|60|0|13|0,8,12,17|cuatro franjas|30|15\r\n"
            "wx|5|110|Apr 19|5|Stonemoor Speedway|1|60|0|13|1,2,3,4,5|cinco: se queda con cuatro\r\n"
            "wx|6|120|Apr 29|6|Blackvale|1|60|0|13| 8 , 12 |con espacios\r\n", f); fclose(f); }
    CHECK(LoadSeriesCalendar("build\\wx_cal.psv"));
    auto cal = CalendarForSeries("wx");
    CHECK_EQ((long)cal.size(), 6);
    CHECK(cal[0].weather.empty());
    CHECK_EQ((long)cal[1].weather.size(), 1); CHECK_EQ(cal[1].weather[0], 0);
    CHECK_EQ((long)cal[2].weather.size(), 1); CHECK_EQ(cal[2].weather[0], 8);
    CHECK_EQ((long)cal[3].weather.size(), 4); CHECK_EQ(cal[3].weather[0], 0); CHECK_EQ(cal[3].weather[3], 17);
    CHECK_EQ((long)cal[4].weather.size(), 4); CHECK_EQ(cal[4].weather[3], 4);
    CHECK_EQ((long)cal[5].weather.size(), 2); CHECK_EQ(cal[5].weather[0], 8); CHECK_EQ(cal[5].weather[1], 12);
    CHECK_EQ(cal[3].practiceMin, 30); CHECK_EQ(cal[3].qualifyMin, 15);   // the columns behind it stay in place
    CHECK(cal[3].note == "cuatro franjas");

    // Task 4, ruling (b): RoundPlan.weather (career_season.cpp:49) uses AnyWeatherWet over the WHOLE list, not
    // just the first slot. Round 4 (0,8,12,17) is the case the old `c.weather[0]` got wrong (it looked at the 0
    // clear and lost the storm at index 1). Round 5 (1,2,3,4, clouds only) has to stay dry: a
    // "any value != 0 is wet" would have failed here. SeriesDef is not needed ("wx" is not in any
    // loaded series): PlanRound computes p.weather BEFORE the `if (d)`.
    {
        SeasonState s; s.series_id = "wx";
        const int expected[6] = {0, 0, 2, 2, 0, 2};
        for (int i = 0; i < 6; i++) {
            s.round_idx = i;
            CHECK_EQ(PlanRound(s).weather, expected[i]);
        }
    }
}

