static void test_weather_slots() {
    using namespace career;
    // AGREED RULE (all races random): the calendar's EXPLICIT value (>=0) WINS; no value (-1) -> random(17).
    // The profile wx NO LONGER affects anything (previously "dry" forced sun; removed).
    int w[4];
    auto all = [&](int v){ return w[0]==v && w[1]==v && w[2]==v && w[3]==v; };
    WeatherSlotsForEvent(8, "seco", w);       CHECK(all(8));    // cal=8 (storm) explicit value wins
    WeatherSlotsForEvent(17, "seco", w);      CHECK(all(17));   // cal=17 explicit random also wins
    WeatherSlotsForEvent(0, "dinamico", w);   CHECK(all(0));    // cal=0 deterministic sun (explicit >=0)
    WeatherSlotsForEvent(1, "seco", w);       CHECK(all(1));    // any explicit value >=0 passes through as-is
    WeatherSlotsForEvent(-1, "seco", w);      CHECK(all(17));   // no data -> RANDOM; the 'dry' profile wx NO LONGER forces sun
    WeatherSlotsForEvent(-1, "dinamico", w);  CHECK(all(17));   // no data -> 4x random
    WeatherSlotsForEvent(-1, "", w);          CHECK(all(17));   // no data + no profile -> 4x random
    WeatherSlotsForEvent(-1, "variable", w);  CHECK(all(17));   // no data (any wx) -> 4x random
}

// from the portal (19/09): AUTHORED weather is a LIST of 1..4 slots, the same in rounds and events; empty = the
// player decides. PlanRaceWeather is the ONLY rule of the three launch paths.
static void test_weather_list_parse_and_plan() {
    using namespace career;
    CHECK(ParseWeatherList("").empty());
    CHECK(ParseWeatherList("   ").empty());
    { auto v = ParseWeatherList("8");           CHECK_EQ((long)v.size(), 1); CHECK_EQ(v[0], 8); }
    { auto v = ParseWeatherList("0");           CHECK_EQ((long)v.size(), 1); CHECK_EQ(v[0], 0); }   // 0 = AUTHORED clear
    { auto v = ParseWeatherList("0, 8,12 ,17"); CHECK_EQ((long)v.size(), 4); CHECK_EQ(v[1], 8); CHECK_EQ(v[3], 17); }
    { auto v = ParseWeatherList("1,2,3,4,5");   CHECK_EQ((long)v.size(), 4); CHECK_EQ(v[3], 4); }   // maximum 4 slots
    { auto v = ParseWeatherList("8,x,99,-1");   CHECK_EQ((long)v.size(), 1); CHECK_EQ(v[0], 8); }   // garbage out
    CHECK(FormatWeatherList(std::vector<int>{}) == "");
    CHECK(FormatWeatherList(std::vector<int>{0, 8}) == "0,8");
    CHECK(!AnyWeatherWet(std::vector<int>{}));
    CHECK(!AnyWeatherWet(std::vector<int>{0, 4}));
    CHECK(AnyWeatherWet(std::vector<int>{0, 8}));
    CHECK(AnyWeatherWet(std::vector<int>{17}));   // native random = uncertain = treated as wet (canon)

    WeatherPrefs inherit; inherit.mode = WeatherMode::Inherit;
    WeatherPrefs random;  random.mode  = WeatherMode::Random;
    // AUTHORED: ALWAYS wins, also in Inherited. 1 value -> all 4 slots equal and automatic counter (0);
    // N>=2 -> N slots are forced and the leftover slots repeat the last one (as CareerArmEvent does today).
    { RaceWeatherPlan p = PlanRaceWeather(std::vector<int>{8}, "s#1", 2026, 60, inherit);
      CHECK(p.write); CHECK(p.authored); CHECK_EQ(p.forcedSlots, 0);
      CHECK(p.slots[0] == 8 && p.slots[1] == 8 && p.slots[2] == 8 && p.slots[3] == 8); }
    { RaceWeatherPlan p = PlanRaceWeather(std::vector<int>{0, 8, 12}, "s#1", 2026, 60, random);
      CHECK(p.write); CHECK(p.authored); CHECK_EQ(p.forcedSlots, 3);
      CHECK(p.slots[0] == 0 && p.slots[1] == 8 && p.slots[2] == 12 && p.slots[3] == 12); }
    { RaceWeatherPlan p = PlanRaceWeather(std::vector<int>{0}, "s#1", 2026, 60, inherit);   // authored clear
      CHECK(p.write); CHECK(p.authored); CHECK_EQ(p.slots[0], 0); CHECK_EQ(p.forcedSlots, 0); }
    // NOT AUTHORED: the player's mode rules. Inherited -> nothing is written. Random -> NATIVE 17 (29/07).
    { RaceWeatherPlan p = PlanRaceWeather(std::vector<int>{}, "s#1", 2026, 60, inherit);
      CHECK(!p.write); CHECK(!p.authored); }
    { RaceWeatherPlan p = PlanRaceWeather(std::vector<int>{}, "s#1", 2026, 60, random);
      CHECK(p.write); CHECK(!p.authored);
      for (int i = 0; i < 4; i++) CHECK_EQ(p.slots[i], WX_RANDOM);
      CHECK(p.forcedSlots >= 0 && p.forcedSlots <= 4 && p.forcedSlots != 1); }   // band by duration (): 0 · 2..4
}







