static void test_settle_factory() {
    using namespace career;
    // factory seat: costs 0, entry 0 (the team foots the bill) — "you no longer pay, you get paid" (fully covered).
    // Variable-salary rework: the flat FACTORY_SEAT_SALARY is NO LONGER paid via s.salary (it stays
    // always 0, factorySeat or not); the salaried seat's real salary comes through dealSalary/deal_salary
    // (= negotiated contract.per_race), covered by test_settle_pays_per_race. This test sticks to the part
    // the part still in force: costs/entry at 0 under factorySeat.
    CareerProgress p; p.credits = 0; p.frontier_phase = 7;
    RaceResult r; r.pos = 5; r.field = 20; r.finished = true; r.clean = false; r.race_phase = 7;
    SettleReport s = Settle(p, r, 180000, FloorForPhase(7), /*rented=*/false, 0, /*carValue=*/0,
                            /*entryOverride=*/20000, /*factorySeat=*/true);
    CHECK_EQ(s.costs, 0);
    CHECK_EQ(s.entry, 0);                                   // even when entryOverride>0 comes in
    CHECK_EQ(s.salary, 0);                                  // Variable-salary rework: the factory flat rate is no longer paid through s.salary
    CHECK_EQ(s.credits_delta, s.prize + s.clean_bonus + s.salary);
    CHECK(s.credits_delta > 0);                             // even with no flat salary, entry/costs at 0 -> positive net
    // regression: without factorySeat behavior is as always (salary 0, real entry and costs)
    CareerProgress p2; p2.frontier_phase = 7;
    SettleReport s2 = Settle(p2, r, 180000, FloorForPhase(7), false, 0, 1500000);
    CHECK_EQ(s2.salary, 0);
    CHECK(s2.costs > 0);
    CHECK(s2.entry > 0);
}

// Variable-salary rework: settlement no longer pays the flat factory rate (FACTORY_SEAT_SALARY)
// via s.salary — the salaried seat's salary comes through dealSalary (= negotiated contract.per_race). A
// factorySeat=true seat still has costs/entry at 0 ("fully covered"), but s.salary is now ALWAYS 0; the
// real salary money shows up in s.deal_salary, exactly as the contract delivers it (not a flat constant).
static void test_settle_pays_per_race() {
    using namespace career;
    CareerProgress prog{}; prog.credits = 0;
    RaceResult r{}; r.pos = 5; r.field = 20; r.finished = true; r.race_phase = 5;
    // salaried seat works: factorySeat=TRUE (covers costs/entry) but the SALARY is no longer the flat constant:
    // it's paid via dealSalary (= contract.per_race). BEFORE the fix, s.salary == FACTORY_SEAT_SALARY (150000) -> the
    // first CHECK fails; AFTER the fix, s.salary == 0 and the salary comes through deal_salary.
    SettleReport s = Settle(prog, r, /*winnerPrize*/0, /*floor*/0, /*rented*/false, 0, /*carValue*/0,
                            /*entryOverride*/0, /*factorySeat*/true, /*coverage*/0,
                            /*dealSalary*/47000, /*deductible*/0, /*travel*/0, /*resultBonus*/0,
                            /*raceLaps*/bal::COST_REF_LAPS, /*wear*/nullptr, /*repBonus*/0);
    CHECK_EQ(s.salary, 0);              // FAILS before the fix (== 150000); passes after
    CHECK_EQ(s.deal_salary, 47000);    // the salary is paid through the contract's per_race
}



// REACHABILITY regression (from an internal audit): the engine's net per season, with
// conservative assumptions (fixed P2 finish, 50% clean races, sponsor tier 0, OWN car),
// must allow buying the next tier's flagship car within <= ~2 seasons.
static long seasonNetOwned(const char* seriesId) {
    using namespace career;
    const SeriesDef* d = SeriesById(seriesId);
    const SeriesEcon* ec = EconForSeries(seriesId);
    if (!d || !ec) return -1;
    int rounds = (int)CalendarForSeries(seriesId).size();
    if (rounds <= 0) rounds = d->rounds;
    if (rounds <= 0) return -1;
    long prize2  = PrizeFor(2, RoundWinnerPrize(seriesId), FloorForPhase(d->level));
    long cleanB  = (long)(prize2 * bal::XP_CLEAN_BONUS + 0.5) / 2;        // finishes 50% of races clean
    long runCost = (long)(ec->comprar * bal::RUN_COST_PCT + 0.5);          // own car
    // no sponsor retainer — per-race income is prize + clean-race bonus minus costs.
    long perRace = prize2 + cleanB - EntryFeeFor(seriesId) - runCost;
    SeasonOutcome bono = ChampionshipBonus(2, 20, d->level);               // championship purse (P2 finish)
    return perRace * rounds + bono.money - InscriptionFor(seriesId);
}



