static void test_replacecount() {
    using namespace career;
    // Pass 2b: cap HIGH at the bottom (club tier, cohort-dominated) and it drops going up (elite = few cohort drivers + real ones).
    CHECK_EQ(ReplaceCount(1, 20), 20);           // tier1 cap 24 -> clamped to a grid of 20 (almost all cohort)
    CHECK_EQ(ReplaceCount(1, 30), 24);           // tier1 saturates at the cap of 24 (leaves ~few real-driver seats)
    CHECK_EQ(ReplaceCount(3, 20), 14);           // junior: cap 14
    CHECK_EQ(ReplaceCount(4, 20), 10);           // semi-pro: cap 10
    CHECK_EQ(ReplaceCount(7, 20), 4);            // elite: only the top 4 cohort drivers + real ones
    CHECK_EQ(ReplaceCount(1, 4), 4);             // clamped to gridSize
    CHECK(ReplaceCount(1, 20) >= ReplaceCount(7, 20));  // monotonic (lower down, more cohort)
}

// Two helpers for the grid-composition tests. The driver model moved WHERE two
// things live, without changing the properties the suite protects:
//  · authored/live skill NO LONGER lands in race_skill (which is now a TRAIT of the factor model):
//    it lands in GridDriver::talent, shifted by the genome's affinity with the class's car family.
//  · personality is no longer a flat value per archetype: the archetype BIASES the trait that comes out of the genome.
// ExpectedTalent reproduces the first exactly; NeutralTwin gives the SAME driver with no archetype or
// authored data, to isolate how much personality moves them without depending on the luck of a genome draw.
static double ExpectedTalent(const char* canonName, double base, const char* className) {
    return career::TalentInFamily(career::GenomeSeed(canonName), base, career::FamilyForClass(className));
}
static career::TraitVector NeutralTwin(const char* canonName, double talent) {
    career::TraitBias none;
    return career::TraitsFor(career::GenomeSeed(canonName), talent, none);
}

static void test_compose() {
    using namespace career;
    // temporary livery catalog with 10 liveries of the TEST class
    { FILE* f = fopen("build\\c_liv.psv", "wb");
      std::string s = "class_name|xml_name|livery_name|livery_id|display\r\n";
      for (int i = 1; i <= 10; i++) s += "TEST|TEST|Liv" + std::to_string(i) + "|" + std::to_string(i) + "|TEST\r\n";
      fputs(s.c_str(), f); fclose(f); }
    { FILE* f = fopen("build\\c_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of\r\n"
            "cs1|TEST|T|INT|2024|cp|club|6|\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\c_prof.psv", "wb");
      fputs("profile_id|campos\r\ncp|ai=88-106;aggr=media\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\c_fields.psv", "wb");
      std::string s = "series_id|order|name|country|iconic|skill|aggr|note\r\n";
      for (int i = 1; i <= 8; i++) s += "cs1|" + std::to_string(i) + "|Real" + std::to_string(i) + "|INT|0|||\r\n";
      fputs(s.c_str(), f); fclose(f); }
    { FILE* f = fopen("build\\c_roster.psv", "wb");
      fputs("driver_id|name|homage_name|country|tier_min|tier_max|base_skill|aggression|consistency|hot|archetype\r\n"
            "h|Hot|HotBak|INT|1|7|0.50|0.70|0.85|1|x\r\n"
            "a|RosA|RosABak|INT|1|7|0.78|0.60|0.85|0|x\r\n"
            "b|RosB|RosBBak|INT|1|7|0.76|0.60|0.85|0|x\r\n"
            "c|RosC|RosCBak|INT|1|7|0.74|0.60|0.85|0|x\r\n"
            "d|RosD|RosDBak|INT|1|7|0.72|0.60|0.85|0|x\r\n"
            "e|RosE|RosEBak|INT|1|7|0.70|0.60|0.85|0|x\r\n", f); fclose(f); }
    CHECK(LoadLiveries("build\\c_liv.psv"));
    CHECK(LoadSeries("build\\c_series.psv"));
    CHECK(LoadProfiles("build\\c_prof.psv"));
    CHECK(LoadFields("build\\c_fields.psv"));
    CHECK(LoadRoster("build\\c_roster.psv"));

    auto grid = ComposeSeasonGrid("cs1", /*tier*/1, /*playerForm*/0.80, /*gridSize*/10, /*useHomage*/false);
    CHECK_EQ((long)grid.size(), 10);                       // gridSize
    // Pass 2b: tier 1 cap 24 -> ReplaceCount(1,10)=10, but the roster only has 6 -> 6 cast (unique) +
    // 4 real drivers from the field's defensive extension (Real1..Real4) = 10. Cohort-dominated split (all cohort
    // available + filled out with real drivers), not the old 4-real/6-cast. Tally: 6 cast + 4 real.
    int ros = 0, real = 0;
    for (const auto& g : grid) {
        if (g.name == "Hot" || g.name == "RosA" || g.name == "RosB" ||
            g.name == "RosC" || g.name == "RosD" || g.name == "RosE") ros++;
        if (g.name.rfind("Real", 0) == 0) real++;
    }
    CHECK_EQ((long)ros, 6);
    CHECK_EQ((long)real, 4);
    // unique liveries
    std::vector<std::string> livs; for (const auto& g : grid) livs.push_back(g.livery_name);
    std::sort(livs.begin(), livs.end());
    CHECK(std::unique(livs.begin(), livs.end()) == livs.end());
    // No rubber-band or band clamp: the cast's skill = STABLE base_skill (difficulty comes from the
    // global slider, not this value) and doesn't depend on the player's form. That now lives in `talent`
    // (race_skill became a trait of the factor model), so it's measured there, exactly.
    for (const auto& g : grid) if (g.name == "Hot") CHECK(g.talent == ExpectedTalent("Hot", 0.50, "TEST"));
    // homage toggle: swaps the roster's names for their homage versions
    auto gridH = ComposeSeasonGrid("cs1", 1, 0.80, 10, /*useHomage*/true);
    bool hasBak = false; for (const auto& g : gridH) if (g.name == "HotBak") hasBak = true;
    CHECK(hasBak);
}

