static void test_compose_pinned() {
    using namespace career;
    // PIN class with 8 liveries; pin1 series with 3 drivers pinned to P5/P2/P7 (NOT in catalog order)
    { FILE* f = fopen("build\\pn_liv.psv", "wb");
      std::string s = "class_name|xml_name|livery_name|livery_id|display\r\n";
      for (int i = 1; i <= 8; i++) s += "PIN|PIN|P" + std::to_string(i) + "|" + std::to_string(i) + "|PIN\r\n";
      fputs(s.c_str(), f); fclose(f); }
    { FILE* f = fopen("build\\pn_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of\r\n"
            "pin1|PIN|P|INT|2024|pp|club|6|\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\pn_prof.psv", "wb");
      fputs("profile_id|campos\r\npp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\pn_rosters.psv", "wb");
      fputs("series_id|car_no|driver|country|skill|aggr|cons|archetype|livery_name|binding|real\r\n"
            "pin1|6|Alpha|DEU|0.96|0.52|0.94|MT|P5|direct|1\r\n"
            "pin1|50|Beta|ITA|0.93|0.55|0.92|AP|P2|whatif|1\r\n"
            "pin1|7|Gamma|JPN|0.90|0.74|0.82|CH|P7|color|1\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\pn_roster.psv", "wb");          // cast (series_roster.psv)
      fputs("driver_id|name|homage_name|country|tier_min|tier_max|base_skill|aggression|consistency|hot|archetype\r\n"
            "h|Hot|HotBak|INT|1|7|0.50|0.70|0.85|1|x\r\n"
            "a|RosA|RosABak|INT|1|7|0.78|0.60|0.85|0|x\r\n"
            "b|RosB|RosBBak|INT|1|7|0.76|0.60|0.85|0|x\r\n"
            "c|RosC|RosCBak|INT|1|7|0.74|0.60|0.85|0|x\r\n", f); fclose(f); }
    CHECK(LoadLiveries("build\\pn_liv.psv"));
    CHECK(LoadSeries("build\\pn_series.psv"));
    CHECK(LoadProfiles("build\\pn_prof.psv"));
    CHECK(LoadSeriesRosters("build\\pn_rosters.psv"));
    CHECK(LoadRoster("build\\pn_roster.psv"));
    { FILE* f = fopen("build\\pn_fields.psv", "wb");          // curve-based field: must NOT be used
      fputs("series_id|order|name|country|iconic|skill|aggr|note\r\n"
            "pin1|1|NoDebeSalir|INT|0|||\r\n", f); fclose(f); }
    CHECK(LoadFields("build\\pn_fields.psv"));

    // Pass 2b: PINNED series are all top-tier (low cap). tier 7 -> N=4; gridSize 7 -> pinCount=3
    // (the 3 pinned via the primary path, verbatim binding) + 4 cast in free liveries.
    auto g1 = ComposeSeasonGrid("pin1", 7, 0.40, 7, false);
    CHECK_EQ((long)g1.size(), 7);                                 // exactly gridSize (feasibility)
    auto liveryOf = [](const std::vector<career::GridDriver>& g, const std::string& n) {
        for (const auto& d : g) if (d.name == n) return d.livery_name; return std::string(); };
    CHECK(liveryOf(g1, "Alpha") == "P5");                         // VERBATIM binding, not by catalog order
    CHECK(liveryOf(g1, "Beta") == "P2");
    CHECK(liveryOf(g1, "Gamma") == "P7");
    CHECK(liveryOf(g1, "NoDebeSalir").empty());                   // the curve-based field does NOT kick in when there are pinned drivers
    // skills/archetype from the PSV. Authored skill now lives in `talent` (exact), and personality
    // is no longer a FLAT value per archetype — the archetype BIASES the trait that comes out of the genome. What gets
    // checked is what the bias actually guarantees: it shifts EACH driver relative to their archetype-free twin (same genome,
    // same talent). Comparing Alpha to Beta head-on would be a lottery: the defending bias between MT (0.70)
    // and AP (0.88) is worth ~0.07 while that trait's own noise has an SD of 0.13, so it wouldn't prove anything.
    double defBeta = -1, aggrAlpha = -1, consGamma = -1;
    for (const auto& d : g1) {
        if (d.name == "Alpha") { CHECK(d.talent == ExpectedTalent("Alpha", 0.96, "PIN")); aggrAlpha = d.aggression; }
        if (d.name == "Beta")  { CHECK(d.talent == ExpectedTalent("Beta",  0.93, "PIN")); defBeta   = d.defending; }
        if (d.name == "Gamma") { CHECK(d.talent == ExpectedTalent("Gamma", 0.90, "PIN")); consGamma = d.consistency; }
    }
    // Aug 9: `defending` now comes out CLAMPED by discipline (RacecraftFor), so the neutral twin gets clamped
    // with the SAME rule before comparing — otherwise you'd compare a free number against a capped one and the test
    // would measure the clamp, not the bias. Same situation as the note below about consistency saturating: when
    // both sides hit the ceiling the comparison proves nothing, which is why it's `>=`.
    {   const RacecraftBounds rb = RacecraftFor(FamilyForClass("PIN"));
        auto acota = [&](double v) { return v < rb.def_lo ? rb.def_lo : (v > rb.def_hi ? rb.def_hi : v); };
        CHECK(defBeta <= rb.def_hi && defBeta >= rb.def_lo);
        // 26/08 — THIS CHECK CHANGES CONTRACT, it is not relaxed. It said `defBeta >= the NEUTRAL twin`, and it was
        // correct as long as defense was a NUDGE: the bias only moved upward from a common anchor.
        // Now defense COMES FROM ITS RATING (career_traits.h: defending_target), so an archetype that
        // defends little MUST end up below the neutral one -- that is the goal of the change, not a defect. Measured:
        // the defense range within a grid went from 0,18 to 0,59 with this.
        // What is fixed now is what the model DOES guarantee: that Beta comes from its archetype's rating
        // (`AP` = 0,70) and that its own noise (kSdDefend 0,10) cannot pull it away from there.
        const double notaAP = 0.70;
        CHECK(defBeta >= DefendingInBand(notaAP - 0.35, rb));
        CHECK(defBeta <= DefendingInBand(notaAP + 0.35, rb)); }
    CHECK(aggrAlpha > 0.0 && aggrAlpha < NeutralTwin("Alpha", ExpectedTalent("Alpha", 0.96, "PIN")).aggression);
    CHECK(consGamma > 0.0 && consGamma < NeutralTwin("Gamma", ExpectedTalent("Gamma", 0.90, "PIN")).consistency);
    // NOTE: Alpha's consistency is NOT compared: with talent 0.96 and MT bias (+0.15 from the archetype, +0.09
    // from the 0.94 authored value) the trait SATURATES at 1.00, and so does its neutral twin — comparing two ceilings proves
    // nothing. An elite metronome having consistency 1.00 is the correct result, not a bug.
    // the cast occupies ONLY free liveries (not P5/P2/P7), with no duplicates
    std::vector<std::string> livs; for (const auto& d : g1) livs.push_back(d.livery_name);
    std::sort(livs.begin(), livs.end());
    CHECK(std::unique(livs.begin(), livs.end()) == livs.end());
    // STABILITY across rounds: a different player form (hot-streak rubber-band) -> SAME name->livery mapping
    auto g2 = ComposeSeasonGrid("pin1", 7, 0.95, 7, false);
    CHECK_EQ((long)g2.size(), 7);
    bool stable = true;
    for (const auto& d : g1) if (liveryOf(g2, d.name) != d.livery_name) stable = false;
    CHECK(stable);
    // No rubber-band: the cast's skill = STABLE base_skill, does NOT depend on the player's form.
    // base 0.50 in both forms (0.40 and 0.95) -> identical. The livery doesn't move either (the test's goal).
    // Measured in `talent`, which is where authored skill now lives.
    double h1 = -1, h2 = -1;
    for (const auto& d : g1) if (d.name == "Hot") h1 = d.talent;
    for (const auto& d : g2) if (d.name == "Hot") h2 = d.talent;
    CHECK(h1 == ExpectedTalent("Hot", 0.50, "PIN"));            // stable base_skill
    CHECK(h2 == h1);                                            // no rubber-band: identical across rounds
    // truncated by standings: gridSize 5, tier 7 -> N=4, pinCount=1 -> only the file's 1st entry (Alpha)
    auto g3 = ComposeSeasonGrid("pin1", 7, 0.40, 5, false);
    CHECK_EQ((long)g3.size(), 5);
    CHECK(liveryOf(g3, "Alpha") == "P5");
    CHECK(liveryOf(g3, "Beta").empty() && liveryOf(g3, "Gamma").empty());
}

