// ===================================================================================================
// 19/08 — THE SILHOUETTE OF A CLASS, EXACTLY AS PRODUCTION WRITES IT
// ===================================================================================================
//
// A single place that composes the grid EXACTLY like `WriteSeasonGridXml` (career_fields.cpp) and
// reads the result FROM THE XML. Used by the car discount test, the three-pin conversion
// invariants and the `--silueta` diagnostic. Having just one is deliberate: the time the «as
// production» helper diverged from production (a call with the defaults) a width of 0,419 was measured where the game
// received 0,214, and half an afternoon was lost from that.
//
// THE GRID SIZE AND THE LEVEL ARE PRODUCTION'S, with the guard against `GridSizeForSeries`.
// Measuring a grid that does not exist in a race has crept in TWICE in this project (28/07 and 06/08): with
// a fixed 20, 55 of 101 classes composed different people from those who go out on track, and the loop could not catch it alone
// because it uses the same number on both sides of its own comparison.
struct SiluetaRow {
    std::string cls, series;
    int    n = 0;
    double obj_total  = 0.0;   // cp.spread_dry: the TOTAL spread of the class (driver + car)
    double obj_piloto = 0.0;   // DriverSpreadPct(...): what production really passes to BuildGridXml
    double entregado  = 0.0;   // lap % READ FROM THE XML through the measured transfer
    double ratio      = 0.0;   // delivered / obj_piloto
    double top10      = 0.0;   // lap % spanned by the top 10 (or as many as there are)
    double sd         = 0.0;   // SD of the delivered race_skill
    double p10        = 0.0;   // p10 BELOW the delivered race_skill
    double span_talento = 0.0; // TALENT spread of the live grid (the live yardstick)
    int    en_suelo   = 0;     // how many touch the floor of THEIR class
    int    en_030     = 0;     // how many touch kMinDriveableSkill (the bottom of the measured table)
    int    empate_abajo = 1;   // how many share the grid's MINIMUM talent (1 = the backmarker alone)
    bool   oval       = false;
};

// `forzarAbanicoPiloto` is THE NON-VACUITY LEVER that replaces `g_curveByRank`. With >0, all the
// classes receive the SAME driver spread instead of their own — which is exactly what the distribution
// by RANK produced: all 109 delivering 11,3%-11,6%. It serves to switch off the mechanism the invariants say they measure
// («each class delivers ITS spread») without needing to keep the entire Curve distribution for that.
// The median is forced in the same proportion as the `BuildGridXml` defaults (2,4 over 6,0).
//
// `guardaTamano` is OPTIONAL, and the reason is measured: `GridSizeForSeries` bounds its answer by the
// names that the class's XML has ACTUALLY written (`g_observedXmlNames`, career_fields.cpp:415), which is
// a global that fills up as soon as some earlier test writes real grids. So the equality
// «what I compose == what production composes» holds on a clean load —where this loop was born— and stops
// holding mid-suite, with up to 24 classes capped by another test's multiclass exclusion. It is kept
// where it DOES measure (the car discount loop, which loads its PSVs and runs early) instead of softening it into
// a comparison that never fails.
static bool SiluetaForSeries(const career::SeriesDef& s, SiluetaRow& r, bool guardaTamano = false,
                            double forzarAbanicoPiloto = 0.0) {
    using namespace career;
    EnsureClassPaceLoaded();
    const ClassPace cp = ClassPaceFor(s.class_name);
    if (!cp.found) return false;                      // with no real spread data: not judged
    const int gs = GridSizeForClassName(s.class_name);
    if (gs < 8) return false;                         // class without enough liveries
    const auto grid = ComposeSeasonGrid(s.id, s.level, 0.0, gs, false);
    if ((int)grid.size() < 8) return false;
    // THE GUARD: what is composed HERE has to be what PRODUCTION composes for this series.
    if (guardaTamano) CHECK_EQ((int)grid.size(), GridSizeForSeries(s.id));
    // The three lines of WriteSeasonGridXml (career_fields.cpp:1831-1836), literal: the car is discounted
    // ONCE, here, and the median shrinks in the SAME proportion.
    const double spreadDriver = (forzarAbanicoPiloto > 0.0)
                                    ? forzarAbanicoPiloto
                                    : DriverSpreadPct(s.id, s.class_name, cp.spread_dry);
    const double medianDriver = (forzarAbanicoPiloto > 0.0)
                                    ? forzarAbanicoPiloto * 0.4
                                    : cp.median_dry * ((cp.spread_dry > 0.0) ? (spreadDriver / cp.spread_dry) : 1.0);
    const bool oval = (FamilyForClass(s.class_name) == CarFamily::Oval);
    const std::string xml = BuildGridXml(grid, spreadDriver, medianDriver, oval);
    std::vector<double> sk;
    const std::string open = "<race_skill>";
    for (size_t p = xml.find(open); p != std::string::npos; p = xml.find(open, p + 1)) {
        const size_t a = p + open.size(), b = xml.find('<', a);
        if (b == std::string::npos) break;
        sk.push_back(atof(xml.substr(a, b - a).c_str()));
    }
    if ((int)sk.size() < 8) return false;
    std::sort(sk.begin(), sk.end(), std::greater<double>());   // 0 = the fastest

    r.cls = s.class_name; r.series = s.id; r.n = (int)sk.size(); r.oval = oval;
    r.obj_total = cp.spread_dry; r.obj_piloto = spreadDriver;
    // THE DELIVERED % IS READ FROM THE XML, passing each race_skill through the MEASURED transfer. It cannot be read
    // from `PctOffOnPins`: on a FLAT grid that function returns 0% for everyone (there is no gap to measure)
    // while the XML carries the full spread distributed by rank. And besides, this is what measures what the
    // GAME receives, which is the only place where the whole chain closes.
    r.entregado = PctOffForRaceSkill(sk.back()) - PctOffForRaceSkill(sk.front());
    r.ratio = (spreadDriver > 1e-9) ? r.entregado / spreadDriver : 0.0;
    const size_t k = sk.size() < 10 ? sk.size() : 10;
    r.top10 = PctOffForRaceSkill(sk[k - 1]) - PctOffForRaceSkill(sk.front());
    double mu = 0.0; for (double v : sk) mu += v; mu /= (double)sk.size();
    double va = 0.0; for (double v : sk) va += (v - mu) * (v - mu); va /= (double)(sk.size() - 1);
    r.sd  = sqrt(va);
    r.p10 = sk[(size_t)(0.90 * (sk.size() - 1))];
    // The floor is THAT class's (not 0,30): the race_skill whose lap % is the driver spread. The XML
    // writes %.4f, so the comparison is made at the file's resolution, not with a double epsilon.
    const double suelo = FloorForSpread(spreadDriver);
    for (double v : sk) {
        if (fabs(v - suelo) <= 6e-5)               r.en_suelo++;
        if (fabs(v - kMinDriveableSkill) <= 6e-5)  r.en_030++;
    }
    double tHi = grid[0].talent, tLo = grid[0].talent;
    for (const auto& d : grid) { if (d.talent > tHi) tHi = d.talent; if (d.talent < tLo) tLo = d.talent; }
    r.span_talento = tHi - tLo;
    // How many carry EXACTLY the minimum talent. It is the equality comparison used by the tie-break of
    // `BuildGridXml`, not an epsilon: two drivers with the same talent receive the same gap by definition,
    // and they are the only legitimate reason a class's floor can hold more than one.
    for (const auto& d : grid) if (d.talent == tLo) r.empate_abajo++;
    r.empate_abajo--;                                  // starts at 1 so that an empty pins does not count 0
    return true;
}

// One row per CLASS with data (the first series of each class: it is not over-weighted).
static std::vector<SiluetaRow> SiluetaDeProduccion(bool guardaTamano = false,
                                                   double forzarAbanicoPiloto = 0.0) {
    std::vector<SiluetaRow> rows;
    std::set<std::string> vistas;
    for (const auto& s : career::AllSeries()) {
        if (vistas.count(s.class_name)) continue;
        SiluetaRow r;
        if (!SiluetaForSeries(s, r, guardaTamano, forzarAbanicoPiloto)) continue;
        vistas.insert(s.class_name);
        rows.push_back(r);
    }
    return rows;
}

// ===================================================================================================
// THE CAR DISCOUNT — the ONLY criterion of the invariants table that is NOT tautological
// ===================================================================================================
//
// WHERE THIS TEST COMES FROM. It was `test_class_spread_delivered_vs_target`, the closing of the cold loop of
// 27/07: it composed each class, wrote its XML and compared the delivered % against `spread_pct_dry`. Its target
// moved three times (1:1 with real times -> x2,28 with the Curve shape -> x3,14 with the distribution
// by rank), and each time it moved it lost a little more meaning.
//
// WHY ITS OLD VERSION BECOMES VACUOUS WITH THE THREE-PIN CONVERSION. It passed `cp.spread_dry` —the
// TOTAL— where production passes `spreadDriver` —the DRIVER part—. With the live yardstick the backmarker receives
// EXACTLY the spread it is given, whatever it is: the test would deliver the number it had itself just
// given and would come out green with any car/driver split, including none. of the spec says it in
// plain words: with the live yardstick I1, I2, the WIDTH of I5, I7 and I8 are true BY CONSTRUCTION.
//
// WHAT IT BECOMES: the only question in that chain that still has a possible «no» answer. The
// PSV spread is driver + car. `DriverSpreadPct` discounts what the material actually puts, and that
// discount happens in `WriteSeasonGridXml`, ONCE. If someone applied it also inside
// `BuildGridXml`, or removed it from where it is, no other measure in the suite would notice — the end
// would keep landing where it is told — and on track the grid would come out with half, or double, the
// measured spread.
//
// AND IT CARRIES ITS OWN NON-VACUITY GUARD: it checks that the correct discount, the double discount and the
// no discount are three DISTINCT numbers for each judged class. If one day `car_share` were set to
// zero in all tiers, this test would no longer be able to fail — and instead of staying green, it would go red
// right there.
//
// NOTED DEVIATION FROM THE PLAN: it asked for ±1e-6 on the delivered fraction. It is not attainable, and not because of the
// model: the XML writes `%.4f`, so the backmarker's race_skill arrives rounded to 1e-4 and returning it
// through the measured transfer (slope of up to 29,7 percentage points per unit of skill at the bottom of the
// table) brings in up to 1,5e-3 percentage points of noise. The tolerance is 3e-3 on the FRACTION, which is still
// an order of magnitude finer than the distance between discounting right, twice or not at all — and that
// distance is checked explicitly instead of assumed.


// Jul 27 — does the grid actually stop bunching up at the front? It gets MEASURED, on the REAL series and
// through the real XML (BuildGridXml), not the talent: what the game reads is the race_skill already
// anchored to the class's ace, and that's where you can see whether the pack spreads out or bunches up. Each
// grid gets composed TWICE — with the table loaded and without it — and the two distributions are compared.


// Jul 27 — VOCABULARY GUARD over the REAL PSVs. A misspelled archetype doesn't fail: ProfileForArch
// silently returns the neutral profile and the driver ends up with no character with NO WARNING AT ALL. That's how "metodico"
// (instead of `tecnico`) and "fria" (instead of `frio`) had been sitting in the cast for months: 2 of the 28 cohort drivers, invisible. This test reads the
// production files, not a copy, so a future typo turns up RED instead of in a bland-looking grid.


// The REAL field's personality. Until now, the two push_back calls that put a real driver into ComposeSeasonGrid
// were writing archetype "" and a bare consistency of 0.85, so the game's 1,280 real drivers were all the SAME robot
// neutral. What's checked is the loader (accent folding, vocabulary guards) and that the profile reaches the
// grid — and, most importantly, that WITHOUT a profile the result is byte-for-byte what it was before.
static void test_authored_field_profiles() {
    using namespace career;
    const char* af = "build\\__test_f3_authored__.psv";
    { FILE* f = fopen(af, "wb");
      fputs("# comentario: se salta\r\n", f);
      fputs("name|is_real|talent|archetype|affinity_family|history|source_class|era\r\n", f);   // header: gets skipped
      fputs("Agustin Canapino|1|0.880|metronomo|stockcar|prosa|Stock_USA|2020\r\n", f);
      fputs("Zdenek Zzz|1|0.700|cargador|gt|prosa|GT3|2020\r\n", f);
      // 16/09: column 9 is the COUNTRY. Both forms that coexist in the real corpus are tested: with
      //  a flag (the authored reserve, which cannot run without it) and without it (whoever resolves by pool,
      //  pack, field or pinned, which already carry it).
      fputs("Con Bandera|0|0.800|solido|gt|prosa|GT3|2020|SWE\r\n", f);
      fputs("Sin Arquetipo|1|0.900||gt|prosa|GT3|2020\r\n", f);      // empty archetype -> DISCARDED
      fputs("Talento Alto|1|1.400|apex|gt|prosa|GT3|2020\r\n", f);   // talent outside [0,1] -> DISCARDED
      fputs("Talento Cero|1|0|apex|gt|prosa|GT3|2020\r\n", f);       // talent 0 -> DISCARDED
      fputs("corta|1|0.5\r\n", f);                                    // < 4 fields -> skipped, no crash
      fputs("\r\n", f);                                               // empty -> skipped
      fclose(f); }
    CHECK(LoadAuthoredProfiles(af));
    CHECK_EQ(AuthoredProfileCount(), 3);                              // only the three well-formed ones

    // 16/09 — column 9 (country) is read, and its absence leaves the field EMPTY, not garbage.
    { const AuthoredProfile* conB = AuthoredProfileFor("Con Bandera");
      CHECK(conB != nullptr);
      CHECK(conB->country == "SWE");
      const AuthoredProfile* sinB = AuthoredProfileFor("Zdenek Zzz");
      CHECK(sinB != nullptr);
      CHECK(sinB->country.empty()); }

    // (a) the lookup is by FOLDED name. Accents are written as explicit UTF-8 BYTES on purpose:
    // so the test doesn't depend on whatever encoding someone saves this .cpp with.
    CHECK(AuthoredProfileFor("Agustin Canapino") != nullptr);
    CHECK(AuthoredProfileFor("Agust\xC3\xADn Canapino") != nullptr);  // U+00ED i-acute  <- the real case from the corpus
    CHECK(AuthoredProfileFor("AGUSTIN CANAPINO") != nullptr);         // uppercase
    CHECK(AuthoredProfileFor("Agustin  Canapino.") != nullptr);       // punctuation and double space
    CHECK(AuthoredProfileFor("\xC5\xBD" "denek Zzz"   /* split Z with caron: \xBDde would swallow 'd' and 'e' as hex digits */) != nullptr);        // U+017D Ž  <- Latin Extended-A
    CHECK(AuthoredProfileFor("Nadie De Nada") == nullptr);
    CHECK(AuthoredProfileFor("") == nullptr);
    const AuthoredProfile* ac = AuthoredProfileFor("Agust\xC3\xADn Canapino");
    CHECK(ac && ac->archetype == "metronomo");
    CHECK(ac && fabs(ac->talent - 0.880) < 1e-9);

    // (b) the profile REACHES the grid: an authored real driver stops being neutral; one without a profile does NOT change.
    { FILE* f = fopen("build\\f3_liv.psv", "wb");
      std::string s = "class_name|xml_name|livery_name|livery_id|display\r\n";
      for (int i = 1; i <= 8; i++) s += "GT3|GT3|G" + std::to_string(i) + "|" + std::to_string(i) + "|GT\r\n";
      fputs(s.c_str(), f); fclose(f); }
    { FILE* f = fopen("build\\f3_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of\r\n"
            "f3s|GT3|GT|INT|2024|f3p|club|6|\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\f3_prof.psv", "wb");
      fputs("profile_id|campos\r\nf3p|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\f3_fields.psv", "wb");
      // the authored entry has an accent in the FIELD data and no accent in the AUTHORING data: that's the case that used to break the lookup.
      fputs("series_id|order|name|country|iconic|skill|aggr|note\r\n"
            "f3s|1|Agust\xC3\xADn Canapino|ARG|0|||\r\n"
            "f3s|2|Nadie De Nada|INT|0|||\r\n"
            "f3s|3|Zdenek Zzz|CZE|0|||\r\n"
            "f3s|4|Otro Cualquiera|INT|0|||\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\f3_roster.psv", "wb");
      fputs("driver_id|name|homage_name|country|tier_min|tier_max|base_skill|aggression|consistency|hot|archetype\r\n"
            "rk_f3_a|Relleno A|RA|INT|1|7|0.78|0.60|0.85|0|solido\r\n"
            "rk_f3_b|Relleno B|RB|INT|1|7|0.78|0.60|0.85|0|solido\r\n"
            "rk_f3_c|Relleno C|RC|INT|1|7|0.78|0.60|0.85|0|solido\r\n"
            "rk_f3_d|Relleno D|RD|INT|1|7|0.78|0.60|0.85|0|solido\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\f3_pinned.psv", "wb");   // no pinned drivers: forces the field+cast branch
      fputs("series_id|car_no|driver|country|skill|aggr|cons|archetype|livery_name|binding|real\r\n", f); fclose(f); }
    CHECK(LoadLiveries("build\\f3_liv.psv"));
    CHECK(LoadSeries("build\\f3_series.psv"));
    CHECK(LoadProfiles("build\\f3_prof.psv"));
    CHECK(LoadFields("build\\f3_fields.psv"));
    CHECK(LoadRoster("build\\f3_roster.psv"));
    CHECK(LoadSeriesRosters("build\\f3_pinned.psv"));

    auto byName = [](const std::vector<GridDriver>& g, const std::string& n) {
        for (const auto& d : g) if (d.name == n) return d;
        return GridDriver{};
    };
    auto grid = ComposeSeasonGrid("f3s", 1, 0.0, 8, false);
    CHECK(!grid.empty());
    const GridDriver au = byName(grid, "Agust\xC3\xADn Canapino");   // authored (matched via folded accent)
    const GridDriver ne = byName(grid, "Nadie De Nada");             // no profile -> the usual neutral
    CHECK(!au.name.empty() && !ne.name.empty());

    // the authored driver's talent is the AUTHORED value (absolute 0.880), not whatever `order` on the curve would have given them.
    CHECK(au.talent > 0.0 && ne.talent > 0.0);
    CHECK(fabs(au.talent - ne.talent) > 1e-9);
    // the AUTHORED driver ends up ahead of the one the curve had placed AHEAD of them: Canapino is order=1 and "Nadie" order=2,
    // so by curve order Canapino was already first; what's measured here is that the talent value COMES FROM the profile.
    // It's checked against the no-profile version of the SAME grid, whose talent still comes from the curve.
    CHECK(au.race_skill > 0.0 && au.consistency > 0.0);

    // (c) REGRESSION, the part that really matters: with no file the grid is the one from BEFORE this change, driver by
    // driver. The SAME series is compared with the table loaded and with the table empty: those without a
    // profile should come out identical (same genome, zero bias), and the authored ones should CHANGE.
    CHECK(!LoadAuthoredProfiles("build\\__f3_inexistente__.psv"));
    CHECK_EQ(AuthoredProfileCount(), 0);
    auto plain = ComposeSeasonGrid("f3s", 1, 0.0, 8, false);
    CHECK(!plain.empty());
    const GridDriver au0 = byName(plain, "Agust\xC3\xADn Canapino");
    const GridDriver ne0 = byName(plain, "Nadie De Nada");
    CHECK(!au0.name.empty() && !ne0.name.empty());
    // no profile BEFORE and no profile AFTER -> byte-for-byte the same: unauthored drivers are untouched.
    CHECK(fabs(ne.talent      - ne0.talent)      < 1e-12);
    CHECK(fabs(ne.race_skill  - ne0.race_skill)  < 1e-12);
    CHECK(fabs(ne.consistency - ne0.consistency) < 1e-12);
    CHECK(fabs(ne.wet_skill   - ne0.wet_skill)   < 1e-12);
    // the authored driver DOES change when it loses its profile (otherwise the wiring wouldn't be doing anything).
    CHECK(fabs(au.talent - au0.talent) > 1e-9);
    CHECK(fabs(au.consistency - au0.consistency) > 1e-9);
    // and the direction is correct: the metronome has consistency 0.97 versus the neutral's 0.85, so it goes up.
    CHECK(au.consistency > au0.consistency);
}

// The grid is composed from the DRIVER MODEL (genome + affinity + traits) instead of from
// ApplyAiPersonality. What's checked is what the model promises and used to be impossible: every driver brings their talent
// as an absolute, two drivers of the same archetype and level do NOT come out cloned, the archetype's character still
// comes through, and the SAME driver performs differently depending on the class's car FAMILY.
static void test_compose_driver_model() {
    using namespace career;
    // two classes from a different FAMILY (single-seater vs GT) with the SAME cast.
    { FILE* f = fopen("build\\dm_liv.psv", "wb");
      std::string s = "class_name|xml_name|livery_name|livery_id|display\r\n";
      for (int i = 1; i <= 8; i++) s += "Onyx Challenge|FVEE|V" + std::to_string(i) + "|" + std::to_string(i) + "|FV\r\n";
      for (int i = 1; i <= 8; i++) s += "GT3|GT3|G" + std::to_string(i) + "|" + std::to_string(i) + "|GT\r\n";
      fputs(s.c_str(), f); fclose(f); }
    { FILE* f = fopen("build\\dm_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of\r\n"
            "dmfv|Onyx Challenge|FV|INT|2024|dmp|club|6|\r\n"
            "dmgt|GT3|GT|INT|2024|dmp|club|6|\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\dm_prof.psv", "wb");
      fputs("profile_id|campos\r\ndmp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\dm_fields.psv", "wb");
      std::string s = "series_id|order|name|country|iconic|skill|aggr|note\r\n";
      for (int i = 1; i <= 4; i++) {
          s += "dmfv|" + std::to_string(i) + "|FvReal" + std::to_string(i) + "|INT|0|||\r\n";
          s += "dmgt|" + std::to_string(i) + "|GtReal" + std::to_string(i) + "|INT|0|||\r\n";
      }
      fputs(s.c_str(), f); fclose(f); }
    { FILE* f = fopen("build\\dm_roster.psv", "wb");
      fputs("driver_id|name|homage_name|country|tier_min|tier_max|base_skill|aggression|consistency|hot|archetype\r\n"
            "rk_lucia_vega|Lucia Vega|LV|ESP|1|7|0.92|0.60|0.88|1|apex\r\n"
            "rk_metro_one|Metro One|M1|ITA|1|7|0.80|0.50|0.85|0|metronomo\r\n"
            "rk_metro_two|Metro Two|M2|FRA|1|7|0.80|0.50|0.85|0|metronomo\r\n"
            "rk_charger|Charger|CH|BRA|1|7|0.80|0.90|0.85|0|cargador\r\n"
            "rk_rookie|Rookie|RK|JPN|1|7|0.74|0.65|0.80|0|novato\r\n"
            "rk_solid|Solid|SL|GBR|1|7|0.78|0.60|0.85|0|solido\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\dm_pinned.psv", "wb");   // no pinned drivers: forces the field+cast branch
      fputs("series_id|car_no|driver|country|skill|aggr|cons|archetype|livery_name|binding|real\r\n", f); fclose(f); }
    CHECK(LoadLiveries("build\\dm_liv.psv"));
    CHECK(LoadSeries("build\\dm_series.psv"));
    CHECK(LoadProfiles("build\\dm_prof.psv"));
    CHECK(LoadFields("build\\dm_fields.psv"));
    CHECK(LoadRoster("build\\dm_roster.psv"));
    CHECK(LoadSeriesRosters("build\\dm_pinned.psv"));

    auto byName = [](const std::vector<GridDriver>& g, const std::string& n) {
        for (const auto& d : g) if (d.name == n) return d;
        return GridDriver{};
    };
    auto fv = ComposeSeasonGrid("dmfv", 1, 0.0, 8, false);
    auto gt = ComposeSeasonGrid("dmgt", 1, 0.0, 8, false);
    CHECK(!fv.empty() && !gt.empty());

    // (1) EVERY driver brings talent and identity, and no trait falls outside [0,1].
    for (const auto& d : fv) {
        CHECK(d.talent >= 0.0);                          // <0 = "no data" -> BuildGridXml would fall back to the old remapping
        CHECK(!d.name.empty());                          // stable identity (driver_id, or the name in PSV mode)
        const double v[12] = { d.race_skill, d.qualifying, d.aggression, d.defending, d.consistency,
                               d.stamina, d.start_reactions, d.wet_skill, d.tyre_management,
                               d.avoidance_of_mistakes, d.avoidance_of_forced_mistakes, d.blue_flag_conceding };
        for (int i = 0; i < 12; i++) CHECK(v[i] >= 0.0 && v[i] <= 1.0);
    }

    // (2) 17/08 — DECISION (Task 6): the SAME driver performs EQUALLY according to car family (single-seater vs
    // GT). Until this date it performed DIFFERENTLY because of the family affinity; it was switched off in production
    // (career_traits.cpp, g_affinityScale = 0.0) because its cap (0,12) was the size of the ENTIRE F1
    // grid (0,11 of talent): it added no texture, it shuffled the order. The mechanism is still alive behind the
    // switch (see test_affinity_zero_sum_survives_but_is_off_in_production), so this CHECK guards
    // exactly the other side: if someone re-enables affinity without deciding it, Lucia Vega goes back to performing differently
    // in Onyx Challenge and in GT3 and this test catches it.
    const GridDriver lFv = byName(fv, "Lucia Vega"), lGt = byName(gt, "Lucia Vega");
    CHECK(!lFv.name.empty() && !lGt.name.empty());
    CHECK(fabs(lFv.talent - lGt.talent) < 1e-9);
    // the equality propagates to the traits: same seed, same input talent, same bias -> TraitsFor is
    // a pure function of those three, so race_skill comes out identical between families.
    CHECK(fabs(lFv.race_skill - lGt.race_skill) < 1e-9);

    // (3) 17/08 — same decision: two drivers of the SAME archetype and the SAME level go back to having the
    // SAME talent (before they were separated by their own affinities, see above). But they are still TWO
    // PEOPLE: the genome draws the rest of the trait vector by identity, not by affinity -- that part
    // is not touched by this decision and is checked further down (peak/moved) over the 8 free traits.
    const GridDriver m1 = byName(fv, "Metro One"), m2 = byName(fv, "Metro Two");
    CHECK(!m1.name.empty() && !m2.name.empty());
    CHECK(fabs(m1.talent - m2.talent) < 1e-9);           // there is no longer any affinity to separate them
    // the separation is measured over the WHOLE VECTOR, not a single trait: the difference between two
    // normal draws is a lottery and two drivers can match on any one trait by pure chance (these two
    // match on the wet trait within 0.002). What the model promises is that they are NOT the same driver, and that shows
    // in the vector: no trait identical and some genuinely far apart.
    // Aug 9: `defending` comes out of the vector and `start_reactions` goes in. It's not cosmetic: defending now has
    // a HARD CAP by discipline (RacecraftFor), and two drivers hitting the same cap share a value by
    // design — requiring them to differ would measure the clamp, not cloning. The promise (they're not the same driver) still
    // gets checked over 8 traits, all of them unclamped.
    { const double d[8] = { fabs(m1.race_skill - m2.race_skill), fabs(m1.qualifying - m2.qualifying),
                            fabs(m1.aggression - m2.aggression), fabs(m1.start_reactions - m2.start_reactions),
                            fabs(m1.consistency - m2.consistency), fabs(m1.wet_skill - m2.wet_skill),
                            fabs(m1.tyre_management - m2.tyre_management),
                            fabs(m1.avoidance_of_mistakes - m2.avoidance_of_mistakes) };
      double peak = 0; int moved = 0;
      for (int i = 0; i < 8; i++) { if (d[i] > peak) peak = d[i]; if (d[i] > 1e-9) moved++; }
      CHECK(peak > 0.05);            // on at least one trait they genuinely diverge
      CHECK_EQ((long)moved, 8); }    // and none match: no cloning, partial or otherwise

    // (4) the FULL WIRING, reproduced from outside: identity = CANONICAL name -> genome; talent =
    // base_skill shifted by affinity with the class's car family; traits = factor model biased by
    // the archetype AND by the driver's authored data (aggression/consistency from the PSV, which is more specific
    // than their archetype). If any of those pieces got disconnected, this exact equality would break.
    const GridDriver ch = byName(fv, "Charger");
    CHECK(!ch.name.empty());
    {   const uint64_t s = GenomeSeed("Charger");
        const double t = TalentInFamily(s, 0.80, CarFamily::OpenWheel);
        // 26/08: the bias is requested WHOLE from production (archetype + authored data + scale cap). Before it
        // was reassembled here by hand and every new piece of the model broke the equality: a test that COPIES the
        // logic it guards guards nothing. The two numbers are those of the `Charger` PSV.
        const TraitBias b = BiasForDriver("cargador", /*aggr*/ 0.90, /*cons*/ 0.85);
        const TraitVector tv = TraitsFor(s, t, b);
        CHECK(ch.talent      == t);
        // 26/08: aggression also goes through the discipline band, just like `defending` two
        // lines below (ApplyDriverModel: AggressionInBand). The raw equality only held
        // while the value fell INSIDE the band, that is, by chance.
        CHECK(ch.aggression  == AggressionInBand(tv.aggression, RacecraftFor(CarFamily::OpenWheel)));
        CHECK(ch.consistency == tv.consistency);
        CHECK(ch.wet_skill   == tv.wet_skill);
        // Aug 9: the wiring still comes through whole, but `defending` now passes through the discipline cap.
        CHECK(ch.defending == DefendingInBand(tv.defending, RacecraftFor(CarFamily::OpenWheel)));
        // and personality DOES move the driver relative to their twin with no archetype or authored data (same genome,
        // same talent): the charger is more aggressive and less consistent. Comparing charger against metronome
        // head-on would be a lottery — the bias is worth ~0.2 while aggression's own noise has an SD of 0.13.
        const TraitVector neutral = NeutralTwin("Charger", t);
        CHECK(ch.aggression  > neutral.aggression);
        CHECK(ch.consistency < neutral.consistency);
    }
    {   const double t = ExpectedTalent("Metro One", 0.80, "Onyx Challenge");
        const TraitVector neutral = NeutralTwin("Metro One", t);
        CHECK(m1.consistency > neutral.consistency);   // the metronome is MORE consistent than their neutral twin
        CHECK(m1.aggression  < neutral.aggression);    // and less aggressive (0.50 authored < 0.60 reference)
    }

    // (5) DETERMINISTIC: the same grid composed twice gives exactly the same numbers (the genome comes from the id).
    auto fv2 = ComposeSeasonGrid("dmfv", 1, 0.0, 8, false);
    CHECK_EQ((long)fv2.size(), (long)fv.size());
    bool same = true;
    for (size_t i = 0; i < fv.size() && i < fv2.size(); i++)
        if (fv[i].name != fv2[i].name || fv[i].talent != fv2[i].talent ||
            fv[i].wet_skill != fv2[i].wet_skill || fv[i].aggression != fv2[i].aggression) same = false;
    CHECK(same);

    // (6) talent does NOT depend on the player's form (the rubber-band was killed on Jul 2 and stays dead).
    auto fvHot = ComposeSeasonGrid("dmfv", 1, 0.95, 8, false);
    CHECK(byName(fvHot, "Lucia Vega").talent == lFv.talent);

    // (7) Blue flag by CLASS ROLE. The SLOW class in a multiclass -> 0.00 (non-negotiable).
    // Aug 9: in SINGLE-CLASS it's no longer a flat 0.95 — it's the DISCIPLINE constant (RacecraftFor: 0.73
    // closed-wheel / 0.77 open-wheel). What this block protects is still the same thing: that the role dictates it and
    // single-class and slow-multiclass do NOT get the same value. It checks that the whole grid shares a
    // single value, and that the value is one of the two legal ones, without hardcoding the fixture's family.
    {   const double bf = fv.front().blue_flag_conceding;
        for (const auto& d : fv) CHECK(fabs(d.blue_flag_conceding - bf) < 1e-9);
        CHECK(fabs(bf - RacecraftFor(CarFamily::OpenWheel).blue) < 1e-9 ||
              fabs(bf - RacecraftFor(CarFamily::GT).blue) < 1e-9);
        CHECK(bf > 0.5); }   // and definitely not the 0.00 of the slow class
    auto slow = ComposeSeasonGrid("dmgt", 1, 0.0, 8, false, EmptyRivalForm(), nullptr, nullptr,
                                  ClassRole::SlowerInMulticlass);
    CHECK(!slow.empty());
    for (const auto& d : slow) CHECK(fabs(d.blue_flag_conceding) < 1e-9);
    // and reaches the XML as-is (it's the parameter the game reads)
    CHECK(BuildGridXml(slow, 6.0, 2.4).find("<blue_flag_conceding>0.0000</blue_flag_conceding>") != std::string::npos);

    // (8) the composed grid's XML goes down the ANCHORED-TO-THE-ACE branch (everyone brings talent): a single driver
    // at 1.00 and a tail that genuinely tapers off, which is the shape of the real packs.
    { const std::string xml = BuildGridXml(fv, 6.0, 2.4);
      size_t p = 0; int atTop = 0; double lowest = 1.0;
      const std::string tag = "<race_skill>";
      while ((p = xml.find(tag, p)) != std::string::npos) {
          double v = atof(xml.c_str() + p + tag.size());
          if (v > 0.995) atTop++;
          if (v < lowest) lowest = v;
          p += tag.size();
      }
      CHECK_EQ((long)atTop, 1);            // a single ace at the top
      CHECK(lowest < 0.90);                // and a real tail, not a tight band
    }
}

// Rating-driven skill — a driver with a live rating races at RatingQuality(r) instead
// of the static base_skill / CurveSkill value. Tests: (a) monotonic: higher-rated cast driver
// gets a higher composed race_skill than a lower-rated one; (b) fallback: a driver with NO stored
// rating gets exactly the old castSkill value (no change in behavior for the unrated case).
static void test_compose_rating_skill() {
    using namespace career;
    // Reuse the fb_* dataset (LoadFields/LoadRoster/LoadSeries already done by test_compose_fallback_stable
    // which runs before us; reload for independence).
    { FILE* f = fopen("build\\fb_liv.psv", "wb");
      std::string s = "class_name|xml_name|livery_name|livery_id|display\r\n";
      for (int i = 1; i <= 10; i++) s += "FBS|FBS|F" + std::to_string(i) + "|" + std::to_string(i) + "|FBS\r\n";
      fputs(s.c_str(), f); fclose(f); }
    { FILE* f = fopen("build\\fb_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of\r\n"
            "fs1|FBS|F|INT|2024|fp|club|6|\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\fb_prof.psv", "wb");
      fputs("profile_id|campos\r\nfp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\fb_fields.psv", "wb");
      std::string s = "series_id|order|name|country|iconic|skill|aggr|note\r\n";
      for (int i = 1; i <= 8; i++) s += "fs1|" + std::to_string(i) + "|Real" + std::to_string(i) + "|INT|0|||\r\n";
      fputs(s.c_str(), f); fclose(f); }
    // Roster: 3 drivers — "Hot" (id "h") has a high rating, "RosA" (id "a") has a low rating,
    // "RosB" (id "b") has no stored rating (tests the fallback path).
    { FILE* f = fopen("build\\fb_roster.psv", "wb");
      fputs("driver_id|name|homage_name|country|tier_min|tier_max|base_skill|aggression|consistency|hot|archetype\r\n"
            "h|Hot|HotBak|INT|1|7|0.50|0.70|0.85|1|x\r\n"
            "a|RosA|RosABak|INT|1|7|0.50|0.60|0.85|0|x\r\n"   // same base_skill as Hot
            "b|RosB|RosBBak|INT|1|7|0.70|0.60|0.85|0|x\r\n"   // different base_skill, NO rating stored
            "c|RosC|RosCBak|INT|1|7|0.68|0.60|0.85|0|x\r\n"
            "d|RosD|RosDBak|INT|1|7|0.66|0.60|0.85|0|x\r\n"
            "e|RosE|RosEBak|INT|1|7|0.64|0.60|0.85|0|x\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\fb_pinned.psv", "wb");
      fputs("series_id|car_no|driver|country|skill|aggr|cons|archetype|livery_name|binding|real\r\n", f); fclose(f); }
    CHECK(LoadLiveries("build\\fb_liv.psv"));
    CHECK(LoadSeries("build\\fb_series.psv"));
    CHECK(LoadProfiles("build\\fb_prof.psv"));
    CHECK(LoadFields("build\\fb_fields.psv"));
    CHECK(LoadRoster("build\\fb_roster.psv"));
    CHECK(LoadSeriesRosters("build\\fb_pinned.psv"));

    // (a) Monotonic: Hot(h) has rating 1900 (near top), RosA(a) has rating 1200 (low).
    //     Same base_skill (0.50) so without the fix they'd get identical race_skill; WITH the fix,
    //     Hot's evolved rating produces higher q(R) -> higher race_skill.
    std::map<std::string, double> ratings;
    ratings["h"] = 1900.0;   // q(1900) ~ 0.87
    ratings["a"] = 1200.0;   // q(1200) ~ 0.22
    auto gRated = ComposeSeasonGrid("fs1", 1, 0.0, 10, false, EmptyRivalForm(), nullptr, &ratings);
    double skH = -1, skA = -1, tB = -1, tBAuthored = -1.0;
    for (const auto& d : gRated) {
        if (d.driver_id == "h") skH = d.race_skill;
        if (d.driver_id == "a") skA = d.race_skill;
        if (d.driver_id == "b") { tB = d.talent; tBAuthored = d.authored_talent; }
    }
    CHECK(skH > 0);    // Hot is in the grid
    CHECK(skA > 0);    // RosA is in the grid
    CHECK(skH > skA);  // higher rating -> higher race_skill (MONOTONIC)

    // (b) Fallback: RosB (id "b") has NO stored rating -> gets castSkill(r) = base_skill (0.70).
    //     That value no longer lands in race_skill (now a trait of the factor model) but instead in
    //     `talent`, shifted by the genome's affinity with the class's car family. Same property, exact.
    // 18/08 — REWRITTEN AGAIN, and this time because the 17/08 rewrite ended up VACUOUS.
    //
    // That one swapped the exact equality for three tolerances (direction + free bound + clamp bound) in order to
    // coexist with the bounded affinity. Hours later, affinity was switched off in production
    // (g_affinityScale = 0.0) and the three became true by construction: `tBDeltaLibre` came to be
    // 0, so the escape clause of the direction check is ALWAYS met and the other two compare
    // 0 <= 0. A comment that said «affinity is still alive» above a check that could no longer fail.
    //
    // What is true TODAY, and it is STRONGER than the three together: on this row no source of noise is left --
    // "b" has no rating (EffectivePace returns the authored value as is) and affinity is at scale 0 --
    // so the delivered talent is EXACTLY the authored one. The strict equality of the original check is back.
    // The affinity MECHANISM is guarded by test_affinity_zero_sum_survives_but_is_off_in_production, which
    // turns it on with a scoped object; it has no place here.
    CHECK(tB > 0);
    CHECK(std::fabs(tBAuthored - 0.70) < 1e-9);          // the fallback lands EXACTLY on the authored base_skill
    CHECK(std::fabs(tB - tBAuthored) < 1e-12);           // and with no noise to apply to it, the delivered one is that same one
    CHECK(tB == ExpectedTalent("RosB", 0.70, "FBS"));    // with affinity at 0, ExpectedTalent IS the authored one
    // AND THE CLAMP, MEASURED WHERE THERE IS NOISE. In "b" there is nothing to clip, so checking it there proves
    // nothing. The one that does carry noise is "h": without a race map, `EffectivePace` returns
    // `RatingQuality(1900)` WHOLE (~0,87) over an authored 0,50, that is, a jump of ~0,37 against an
    // authored spread of this class that is much smaller. BOTH halves are asserted -- that there is more than enough noise
    // to clip, and that it comes out clipped -- so the check cannot empty itself again on its own.
    {
        double lo = 2.0, hi = -2.0;
        for (const auto& d : gRated) { if (d.authored_talent <= 0.0) continue;
            if (d.authored_talent < lo) lo = d.authored_talent; if (d.authored_talent > hi) hi = d.authored_talent; }
        CHECK(hi > lo);
        const double limite = bal::NOISE_SPAN_FRAC * (hi - lo);
        double tH = -1, tHAut = -1, tA = -1, tAAut = -1;
        for (const auto& d : gRated) {
            if (d.driver_id == "h") { tH = d.talent; tHAut = d.authored_talent; }
            if (d.driver_id == "a") { tA = d.talent; tAAut = d.authored_talent; }
        }
        CHECK(tHAut > 0.0 && tAAut > 0.0);
        CHECK(std::fabs(RatingQuality(1900.0) - tHAut) > limite + 1e-6);   // there is more than enough noise: the check is NOT vacuous
        CHECK(std::fabs(tH - tHAut) <= limite + 1e-9);                     // and the clamp leaves it inside
        CHECK(std::fabs(tA - tAAut) <= limite + 1e-9);
    }

    // (c) No-ratings pointer: passing nullptr -> same as the old behavior (no change, no crash).
    auto gNoRat = ComposeSeasonGrid("fs1", 1, 0.0, 10, false);
    double tH2 = -1;
    for (const auto& d : gNoRat) if (d.driver_id == "h") tH2 = d.talent;
    CHECK(tH2 == ExpectedTalent("Hot", 0.50, "FBS"));   // nullptr -> old castSkill = base_skill 0.50
}

// The BOOT grid-write (WriteAllClassGrids) must forward driverRatings into
// ComposeSeasonGrid, so the grids a player races in a FRESH season reflect each driver's seeded rating
// — not the flat static curve. Mirror of test_compose_rating_skill but through the boot path:
//   (a) monotonic: a high-rating cast id gets a higher race_skill than a low-rating one (same base_skill);
//   (b) fallback: a cast id ABSENT from the driverRatings map keeps its old castSkill (base_skill) — no
//       regression for un-seeded ids.
// The `out` sink carries the ABSOLUTE race_skill (the XML on disk is normalized top=1.0 by BuildGridXml),
// so we assert on the absolute spread there. Reuses the fb_* dataset shape (single class FBS / series fs1).
static void test_boot_grid_reflects_rating() {
    using namespace career;
    // Single class FBS (xml_name BOOTRAT to get a dedicated output file), one series fs1_boot at level 1.
    { FILE* f = fopen("build\\br_liv.psv", "wb");
      std::string s = "class_name|xml_name|livery_name|livery_id|display\r\n";
      for (int i = 1; i <= 10; i++) s += "BRC|BOOTRAT|F" + std::to_string(i) + "|" + std::to_string(i) + "|BRC\r\n";
      fputs(s.c_str(), f); fclose(f); }
    { FILE* f = fopen("build\\br_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of|level\r\n"
            "fs1_boot|BRC|F|INT|2024|bp|club|6||1\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\br_prof.psv", "wb");
      fputs("profile_id|campos\r\nbp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\br_fields.psv", "wb");
      std::string s = "series_id|order|name|country|iconic|skill|aggr|note\r\n";
      for (int i = 1; i <= 8; i++) s += "fs1_boot|" + std::to_string(i) + "|Real" + std::to_string(i) + "|INT|0|||\r\n";
      fputs(s.c_str(), f); fclose(f); }
    // Hot(h) and RosA(a) share base_skill 0.50; RosB(b) has base_skill 0.70 and NO stored rating (fallback).
    { FILE* f = fopen("build\\br_roster.psv", "wb");
      fputs("driver_id|name|homage_name|country|tier_min|tier_max|base_skill|aggression|consistency|hot|archetype\r\n"
            "h|Hot|HotBak|INT|1|7|0.50|0.70|0.85|1|x\r\n"
            "a|RosA|RosABak|INT|1|7|0.50|0.60|0.85|0|x\r\n"
            "b|RosB|RosBBak|INT|1|7|0.70|0.60|0.85|0|x\r\n"
            "c|RosC|RosCBak|INT|1|7|0.68|0.60|0.85|0|x\r\n"
            "d|RosD|RosDBak|INT|1|7|0.66|0.60|0.85|0|x\r\n"
            "e|RosE|RosEBak|INT|1|7|0.64|0.60|0.85|0|x\r\n", f); fclose(f); }
    CHECK(LoadLiveries("build\\br_liv.psv"));
    CHECK(LoadSeries("build\\br_series.psv"));
    CHECK(LoadProfiles("build\\br_prof.psv"));
    CHECK(LoadFields("build\\br_fields.psv"));
    CHECK(LoadRoster("build\\br_roster.psv"));
    ReplacePinned({});                                            // no pinned drivers

    std::map<std::string, double> ratings;
    ratings["h"] = 1900.0;   // q(1900) ~ 0.87 (high)
    ratings["a"] = 1200.0;   // q(1200) ~ 0.22 (low)   — same base_skill as h, so only the rating differs

    remove("build\\BOOTRAT.xml");
    std::vector<std::pair<std::string, std::vector<career::GridDriver>>> out;
    // The new trailing driverRatings arg on the BOOT path: without it, the boot grid
    // would use the flat curve and skH would equal skA (both base_skill 0.50).
    int n = WriteAllClassGrids("build", EmptyRivalForm(), false, &out, &ratings);
    CHECK_EQ((long)n, 1);
    CHECK_EQ((long)out.size(), 1);

    double skH = -1, skA = -1, tB = -1, tBAuthored = -1.0;
    for (auto& pr : out)
        for (const auto& d : pr.second) {
            if (d.driver_id == "h") skH = d.race_skill;
            if (d.driver_id == "a") skA = d.race_skill;
            if (d.driver_id == "b") { tB = d.talent; tBAuthored = d.authored_talent; }
        }
    // (a) monotonic: the boot grid reflects the rating — high-rating id out-skills the low-rating id.
    CHECK(skH > 0);
    CHECK(skA > 0);
    CHECK(skH > skA);
    // (b) fallback: RosB has NO stored rating -> old castSkill = base_skill 0.70 (no regression).
    //     Measured in `talent` (where the skill now lives), exact, and with the class's affinity.
    // 18/08 — REWRITTEN AGAIN, same reason and same form as in test_compose_rating_skill: the three
    // tolerances of 17/08 ended up VACUOUS when affinity was switched off (`tBDeltaLibre` = 0 makes the
    // escape clause always hold). Here too there is no noise left to apply to "b" -- without rating,
    // `EffectivePace` returns the authored value; with affinity at 0, `TalentInFamily` does not move it -- so
    // the strict equality is back, which is stronger.
    CHECK(tB > 0);
    CHECK(std::fabs(tBAuthored - 0.70) < 1e-9);          // the fallback lands EXACTLY on the authored base_skill
    CHECK(std::fabs(tB - tBAuthored) < 1e-12);
    CHECK(tB == ExpectedTalent("RosB", 0.70, "BRC"));    // with affinity at 0, ExpectedTalent IS the authored one
    // AND THE CLAMP WHERE THERE IS NOISE, as in the twin test: "h" comes in with `RatingQuality(1900)`
    // whole (~0,87) over an authored 0,50. It is asserted that this jump does NOT fit within the limit (that is, there is
    // something to clip) and that what is delivered does fit.
    {
        double lo = 2.0, hi = -2.0;
        for (auto& pr : out) for (const auto& d : pr.second) { if (d.authored_talent <= 0.0) continue;
            if (d.authored_talent < lo) lo = d.authored_talent; if (d.authored_talent > hi) hi = d.authored_talent; }
        CHECK(hi > lo);
        const double limite = bal::NOISE_SPAN_FRAC * (hi - lo);
        double tH = -1, tHAut = -1, tA = -1, tAAut = -1;
        for (auto& pr : out) for (const auto& d : pr.second) {
            if (d.driver_id == "h") { tH = d.talent; tHAut = d.authored_talent; }
            if (d.driver_id == "a") { tA = d.talent; tAAut = d.authored_talent; }
        }
        CHECK(tHAut > 0.0 && tAAut > 0.0);
        CHECK(std::fabs(RatingQuality(1900.0) - tHAut) > limite + 1e-6);   // there is more than enough noise: the check is NOT vacuous
        CHECK(std::fabs(tH - tHAut) <= limite + 1e-9);
        CHECK(std::fabs(tA - tAAut) <= limite + 1e-9);
    }

    remove("build\\BOOTRAT.xml");
    remove("build\\BOOTRAT.xml.careerbak");
}

static void test_compose_exact_gridsize() {
    using namespace career;
    // short field (3) + short cast (2): the cast does NOT cycle (ros[i], not ros[i % n]) -> NO duplicates.
    // gridSize=8, tier7 N=4 -> realCount=4 but field=3 -> 3 real drivers; castN=8-3=5 but ros=2 -> 2 cast;
    // the real field's defensive extension is exhausted (field=3) -> grid = 3+2 = 5 (smaller rather than duplicating).
    { FILE* f = fopen("build\\xg_fields.psv", "wb");
      fputs("series_id|order|name|country|iconic|skill|aggr|note\r\n"
            "fs1|1|Real1|INT|0|||\r\nfs1|2|Real2|INT|0|||\r\nfs1|3|Real3|INT|0|||\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\xg_roster.psv", "wb");
      fputs("driver_id|name|homage_name|country|tier_min|tier_max|base_skill|aggression|consistency|hot|archetype\r\n"
            "p|Solo|SoloB|INT|1|7|0.60|0.60|0.85|0|x\r\n"
            "q|Duo|DuoB|INT|1|7|0.58|0.60|0.85|0|x\r\n", f); fclose(f); }
    CHECK(LoadLiveries("build\\fb_liv.psv"));                 // reuses the FBS class (10 liveries)
    CHECK(LoadSeries("build\\fb_series.psv"));
    CHECK(LoadProfiles("build\\fb_prof.psv"));
    CHECK(LoadFields("build\\xg_fields.psv"));
    CHECK(LoadRoster("build\\xg_roster.psv"));
    CHECK(LoadSeriesRosters("build\\fb_pinned.psv"));         // no pinned drivers
    auto grid = ComposeSeasonGrid("fs1", 7, 0.80, 8, false);     // tier 7 -> N=4, field=3, cast=2
    CHECK_EQ((long)grid.size(), 5);                              // 3 field + 2 cast (with NO cycling) -> not 8
    std::vector<std::string> names; for (const auto& g : grid) names.push_back(g.name);
    std::sort(names.begin(), names.end());
    CHECK(std::unique(names.begin(), names.end()) == names.end());   // unique names (none recycled)
    std::vector<std::string> ids; for (const auto& g : grid) if (!g.driver_id.empty()) ids.push_back(g.driver_id);
    std::sort(ids.begin(), ids.end());
    CHECK(std::unique(ids.begin(), ids.end()) == ids.end());     // UNIQUE driver_id: no cast repeated
}





// player feedback, Jul 2 — (1) CastSeedFromBase: cast seed by base_skill, independent of tier;
// (2) BuildGridXml [Block B, revised Jul 25; re-measured Jul 26]: band [floor, 1.0] derived from the per-class spread
// career_gridcurve (here, the old wrapper -> club defaults spreadPct=6.0/medianPct=2.4); non-linear shape
// (gamma), no longer two linear segments;
// (3) the apex driver (rk_lucia, base 0.97) seeds above the ENTIRE cast and heads up modern-era grids;
// (4) modern_only: Lucia NEVER gets a seat in period series (the guest slot passes to the next cast member).


static void test_season_persist() {
    using namespace career;
    { FILE* f = fopen("build\\sp_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of|level\r\n"
            "sp1|SE|S|INT|2024|sp|pp|2||5\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\sp_pts.psv", "wb");
      fputs("points_id|puntos|fl_point|fl_top_n|pole_point|nota\r\npp|25,18,15|0|0|0|x\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\sp_prof.psv", "wb");
      fputs("profile_id|campos\r\nsp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\sp_cal.psv", "wb");
      fputs("series_id|round|track_hash|track_name|fmt|laps|durationMin|hour|weather|note\r\n"
            "sp1|1|123|A|1|20|0|14|0|\r\nsp1|2|456|B|1|22|0|14|0|\r\n", f); fclose(f); }
    CHECK(LoadSeries("build\\sp_series.psv")); CHECK(LoadSeriesPoints("build\\sp_pts.psv"));
    CHECK(LoadProfiles("build\\sp_prof.psv")); CHECK(LoadSeriesCalendar("build\\sp_cal.psv"));
    SeasonState s = StartSeason("sp1", "EU");
    // the player ("Yo"/"Me") finishes 2nd (consistent with r.pos=2); "AI1" wins the round
    std::vector<ClassifiedEntry> cls = { {"AI1","",1,20,true,false,""}, {"Yo","",2,20,true,false,""} };
    CareerProgress prog; prog.frontier_phase = 5;
    RaceResult r; r.pos = 2; r.field = 2; r.finished = true; r.clean = false; r.race_phase = 5;
    SettleRound(s, prog, r, cls, "", 10000, 2000, true, 20, 0);   // 1 round raced

    CHECK(SaveSeason(s, "build\\season_test.sav"));
    SeasonState b;
    CHECK(LoadSeason(b, "build\\season_test.sav"));
    CHECK(b.series_id == "sp1" && b.branch == "EU" && b.round_idx == 1 && b.status == 0);
    CHECK((long)b.history.size() == 1 && b.history[0].pos == 2);
    auto ta = FinalTable(s.standings); auto tb = FinalTable(b.standings);
    CHECK(ta.size() == tb.size() && !tb.empty() && ta[0].name == tb[0].name && ta[0].total == tb[0].total);
    SeasonState c;
    CHECK(!LoadSeason(c, "build\\no_existe_season.sav"));
}

