static void test_season_finish() {
    using namespace career;
    // bonus scales by position and level
    SeasonOutcome champ = ChampionshipBonus(1, 20, 6);
    SeasonOutcome p3    = ChampionshipBonus(3, 20, 6);
    SeasonOutcome last  = ChampionshipBonus(20, 20, 6);
    CHECK(champ.xp > p3.xp && p3.xp > last.xp);            // decays by position
    CHECK(champ.money > p3.money && champ.rep > last.rep);
    CHECK(champ.xp > 0 && champ.money > 0 && champ.rep > 0);   // the 3 coins go to the champion
    SeasonOutcome lowTier = ChampionshipBonus(1, 20, 1);
    CHECK(champ.money > lowTier.money);                   // higher tier pays more

    // FinishSeason applies the bonus to prog and marks it finished
    { FILE* f = fopen("build\\se3_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of|level\r\n"
            "se3|SE|S|INT|2024|sp|pp|1||6\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\se3_pts.psv", "wb");
      fputs("points_id|puntos|fl_point|fl_top_n|pole_point|nota\r\npp|25,18,15|0|0|0|x\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\se3_prof.psv", "wb");
      fputs("profile_id|campos\r\nsp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\se3_cal.psv", "wb");
      fputs("series_id|round|track_hash|track_name|fmt|laps|durationMin|hour|weather|note\r\n"
            "se3|1|123|A|1|20|0|14|0|\r\n", f); fclose(f); }
    CHECK(LoadSeries("build\\se3_series.psv")); CHECK(LoadSeriesPoints("build\\se3_pts.psv"));
    CHECK(LoadProfiles("build\\se3_prof.psv")); CHECK(LoadSeriesCalendar("build\\se3_cal.psv"));
    SeasonState s = StartSeason("se3", "");
    std::vector<ClassifiedEntry> cls = { {"Yo","",1,20,true,false,""}, {"AI1","",2,20,true,false,""} };
    CareerProgress prog; prog.frontier_phase = 6;
    RaceResult r; r.pos = 1; r.field = 2; r.finished = true; r.clean = true; r.race_phase = 6;
    SettleRound(s, prog, r, cls, "", 10000, 2000, true, 20, 0);
    CHECK(SeasonComplete(s));
    long credBefore = prog.credits; int repBefore = prog.rep;
    SeasonOutcome out = FinishSeason(s, prog, "Yo");
    CHECK(out.player_pos == 1);                            // won the championship
    CHECK(prog.credits > credBefore && prog.rep > repBefore && out.xp > 0);
    CHECK(s.status == 1);                                  // finished
}

static void test_season_form_settle() {
    using namespace career;
    // (reuses se1 from an earlier test; reloaded here for independence)
    { FILE* f = fopen("build\\se2_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of|level\r\n"
            "se2|SE|S|INT|2024|sp|pp|2||3\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\se2_pts.psv", "wb");
      fputs("points_id|puntos|fl_point|fl_top_n|pole_point|nota\r\npp|25,18,15|0|0|0|x\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\se2_prof.psv", "wb");
      fputs("profile_id|campos\r\nsp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\se2_cal.psv", "wb");
      fputs("series_id|round|track_hash|track_name|fmt|laps|durationMin|hour|weather|note\r\n"
            "se2|1|123|A|1|20|0|14|0|\r\nse2|2|456|B|1|22|0|14|0|\r\n", f); fclose(f); }
    CHECK(LoadSeries("build\\se2_series.psv"));
    CHECK(LoadSeriesPoints("build\\se2_pts.psv"));
    CHECK(LoadProfiles("build\\se2_prof.psv"));
    CHECK(LoadSeriesCalendar("build\\se2_cal.psv"));

    SeasonState s = StartSeason("se2", "");
    CHECK(PlayerForm(s) > 0.69 && PlayerForm(s) < 0.71);   // 0.7 with no history

    // round 1: the player ("Yo") wins among 3
    std::vector<ClassifiedEntry> cls = {
        {"Yo","",1,20,true,false,""}, {"AI1","",2,20,true,false,""}, {"AI2","",3,20,true,false,""} };
    CareerProgress prog; prog.frontier_phase = 3;
    RaceResult r; r.pos = 1; r.field = 3; r.finished = true; r.clean = true; r.race_phase = 3;
    SettleReport rep = SettleRound(s, prog, r, cls, "", 10000, 2000, true, 20, 0);
    CHECK(s.round_idx == 1);                                // advanced
    CHECK((long)s.history.size() == 1 && s.history[0].pos == 1 && s.history[0].field == 3);
    CHECK(prog.credits != 0);                              // economy applied (small bonus)
    auto table = FinalTable(s.standings);
    CHECK(!table.empty() && table[0].name == "Yo" && table[0].total == 25);   // 1st = 25 pts
    // with 1 round (size<K) PlayerForm BLENDS local(=1.0, won out of 3) with careerForm(default 0.7),
    // weighted w=1/5=0.2 -> 0.2*1.0 + 0.8*0.7 = 0.76. With no explicit careerForm the default is 0.7.
    CHECK(PlayerForm(s) > 0.75 && PlayerForm(s) < 0.77);   // short history -> blends with 0.7
    // and if careerForm is 1.0 (player at peak career form), there's no pull downward -> 1.0
    CHECK(PlayerForm(s, 1.0) > 0.99);
    CHECK(!SeasonComplete(s));                             // 1 round remains
}

// (player feedback, Jul 24): a DNF has to be recorded as a DNF. Two links that
// were broken and disconnected: (1) SettleRound was throwing RaceResult::finished and saving the round as a normal finish
// (dnfFlag stayed false), so the standings showed "position N" and never a DNF; (2) from there
// hangs the calendar's DNF flag (CalSlot.dnf) and the sponsors' dnf_fine clause chain.
static void test_dnf_recorded_in_history() {
    using namespace career;
    { FILE* f = fopen("build\\dnf_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of|level\r\n"
            "dn1|SE|S|INT|2024|sp|pp|2||3\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\dnf_pts.psv", "wb");
      fputs("points_id|puntos|fl_point|fl_top_n|pole_point|nota\r\npp|25,18,15|0|0|0|x\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\dnf_prof.psv", "wb");
      fputs("profile_id|campos\r\nsp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\dnf_cal.psv", "wb");
      fputs("series_id|round|track_hash|track_name|fmt|laps|durationMin|hour|weather|note\r\n"
            "dn1|1|123|A|1|20|0|14|0|\r\ndn1|2|456|B|1|22|0|14|0|\r\n", f); fclose(f); }
    CHECK(LoadSeries("build\\dnf_series.psv")); CHECK(LoadSeriesPoints("build\\dnf_pts.psv"));
    CHECK(LoadProfiles("build\\dnf_prof.psv")); CHECK(LoadSeriesCalendar("build\\dnf_cal.psv"));

    std::vector<ClassifiedEntry> cls = {
        {"Yo","",8,20,false,false,""}, {"AI1","",1,20,true,false,""} };
    SeasonState s = StartSeason("dn1", "");
    CareerProgress prog; prog.frontier_phase = 3;
    // round 1: DNF (r.finished=false) with a final position of 8 -> the round is marked DNF, not "8th"
    { RaceResult r; r.pos = 8; r.field = 20; r.finished = false; r.race_phase = 3;
      SettleRound(s, prog, r, cls, "", 10000, 2000, true, 20, 0); }
    CHECK_EQ((long)s.history.size(), 1);
    CHECK(s.history[0].dnfFlag);                 // <- what was missing
    CHECK_EQ(s.history[0].pos, 8);               // the position is still stored (informational)
    // round 2: normal finish -> does NOT mark DNF (the next round isn't contaminated)
    { RaceResult r; r.pos = 3; r.field = 20; r.finished = true; r.race_phase = 3;
      SettleRound(s, prog, r, cls, "", 10000, 2000, true, 20, 0); }
    CHECK_EQ((long)s.history.size(), 2);
    CHECK(!s.history[1].dnfFlag);
    // the full chain through to the sponsor: a result with no finish sets f.dnf, which is what triggers the penalty
    { RaceResult r; r.pos = 8; r.field = 20; r.finished = false;
      RaceTelemetry tel{};
      CardFlags f = CardFlagsFrom(r, tel, /*isEnduranceEvent=*/false);
      CHECK(f.dnf); CHECK(!f.top10); CHECK(!f.clean); CHECK(!f.podium);
      std::vector<SignedCard> cs{ SignedCard{} };
      cs[0].card_id = "card_transair"; cs[0].slot = 0; cs[0].level = 0;
      cs[0].races_left = 99; cs[0].uses_left = 99;
      CardCosts cc{};
      auto rep = CardsSettle(cs, f, 0, cc);
      CHECK(rep.fines_total > 0);                // the dnf_fine clause charges for the DNF
    }
}

// ===================== CAREER form (recent_form) + nemesis_id =====================

// (a) SettleRound pushes samples into prog.recent_form across ALL series; CareerForm = their average; capped to
//     N=10 (drops the oldest); round-trips through SaveCareer/LoadCareer + back-compat (a save with no 'form' -> 0.7).
static void test_career_form_settle_persist() {
    using namespace career;
    // 2-round series, points pp (short calendar: we reuse round_idx, resetting via StartSeason per "season")
    { FILE* f = fopen("build\\cf_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of|level\r\n"
            "cf1|SE|S|INT|2024|sp|pp|2||3\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\cf_pts.psv", "wb");
      fputs("points_id|puntos|fl_point|fl_top_n|pole_point|nota\r\npp|25,18,15|0|0|0|x\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\cf_prof.psv", "wb");
      fputs("profile_id|campos\r\nsp|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\cf_cal.psv", "wb");
      fputs("series_id|round|track_hash|track_name|fmt|laps|durationMin|hour|weather|note\r\n"
            "cf1|1|123|A|1|20|0|14|0|\r\ncf1|2|456|B|1|22|0|14|0|\r\n", f); fclose(f); }
    CHECK(LoadSeries("build\\cf_series.psv")); CHECK(LoadSeriesPoints("build\\cf_pts.psv"));
    CHECK(LoadProfiles("build\\cf_prof.psv")); CHECK(LoadSeriesCalendar("build\\cf_cal.psv"));

    CareerProgress prog; prog.frontier_phase = 3;
    CHECK(CareerForm(prog) > 0.69 && CareerForm(prog) < 0.71);   // empty window -> 0.7

    std::vector<ClassifiedEntry> cls = {
        {"Yo","",1,11,true,false,""}, {"AI1","",2,11,true,false,""} };
    // "season 1": wins out of 11 -> q = (11-1)/(11-1) = 1.0
    { SeasonState s = StartSeason("cf1", "");
      RaceResult r; r.pos = 1; r.field = 11; r.finished = true; r.race_phase = 3;
      SettleRound(s, prog, r, cls, "", 10000, 2000, true, 20, 0); }
    CHECK_EQ((long)prog.recent_form.size(), 1);
    CHECK(CareerForm(prog) > 0.99);                              // 1 sample = 1.0

    // "season 2": last of 11 (pos=11) -> q = (11-11)/10 = 0.0  -> average of {1.0, 0.0} = 0.5
    { SeasonState s = StartSeason("cf1", "");
      RaceResult r; r.pos = 11; r.field = 11; r.finished = true; r.race_phase = 3;
      SettleRound(s, prog, r, cls, "", 10000, 2000, true, 20, 0); }
    CHECK_EQ((long)prog.recent_form.size(), 2);
    CHECK(CareerForm(prog) > 0.49 && CareerForm(prog) < 0.51);   // orientation: win=1, last=0 (NOT inverted)

    // cap N=10: 12 more races (winning) -> the window stays at 10, drops the old ones (the previous 2 fall off)
    for (int i = 0; i < 12; i++) {
        SeasonState s = StartSeason("cf1", "");
        RaceResult r; r.pos = 1; r.field = 11; r.finished = true; r.race_phase = 3;
        SettleRound(s, prog, r, cls, "", 10000, 2000, true, 20, 0);
    }
    CHECK_EQ((long)prog.recent_form.size(), 10);                 // capped
    CHECK(CareerForm(prog) > 0.99);                              // the last 10 are all wins

    // round-trip: recent_form persists through SaveCareer/LoadCareer (in order)
    SaveData sd; sd.prog = prog;
    const char* path = "build\\career_form.sav";
    CHECK(SaveCareer(sd, path));
    SaveData ld; CHECK(LoadCareer(ld, path));
    CHECK_EQ((long)ld.prog.recent_form.size(), 10);
    CHECK(CareerForm(ld.prog) > 0.99);

    // back-compat: a legacy save with NO 'form' lines -> empty window -> CareerForm 0.7
    { FILE* f = fopen("build\\career_form_legacy.sav", "wb");
      fputs("version 1\r\ncredits 2000\r\nrep 5\r\n", f); fclose(f); }
    SaveData L; CHECK(LoadCareer(L, "build\\career_form_legacy.sav"));
    CHECK_EQ((long)L.prog.recent_form.size(), 0);
    CHECK(CareerForm(L.prog) > 0.69 && CareerForm(L.prog) < 0.71);
    CHECK_EQ(L.prog.credits, 2000);
}

// (b) PlayerForm(s, careerForm): empty history -> careerForm (NOT 0.7); short history blends; full = local.
static void test_player_form_career_seed() {
    using namespace career;
    SeasonState s;   // no series/calendar: we only manipulate s.history to test the pure blend
    // empty history -> returns the passed-in careerForm (not the 0.7 default)
    CHECK(PlayerForm(s, 0.40) > 0.39 && PlayerForm(s, 0.40) < 0.41);
    CHECK(PlayerForm(s) > 0.69 && PlayerForm(s) < 0.71);          // no careerForm -> default 0.7 (compat)

    // 1 round won (field 11, pos 1 -> local = 1.0). careerForm = 0.0, K=5 -> w = 1/5 = 0.2
    //   blend = 0.2*1.0 + 0.8*0.0 = 0.2
    s.history.push_back(RoundOutcome{ 1, 1, 11 });
    double b1 = PlayerForm(s, 0.0);
    CHECK(b1 > 0.19 && b1 < 0.21);                                // short history leans on careerForm

    // 5 rounds won (size>=K) -> PURE local (1.0), ignores careerForm
    s.history.push_back(RoundOutcome{ 2, 1, 11 });
    s.history.push_back(RoundOutcome{ 3, 1, 11 });
    s.history.push_back(RoundOutcome{ 4, 1, 11 });
    s.history.push_back(RoundOutcome{ 5, 1, 11 });
    CHECK((long)s.history.size() == 5);
    double full = PlayerForm(s, 0.0);
    CHECK(full > 0.99);                                           // size>=K -> pure local, careerForm 0.0 ignored
}

