static void test_calendar_smoke() {
    career::CareerCalendar cc;
    CHECK_EQ(cc.year, 1);
    CHECK_EQ(cc.cursor_doy, 0);
    CHECK_EQ((int)cc.enrollments.size(), 0);
}



// 01/10 (jse67, 0.7.0): signed in the window a seat in a Larkspur (level 2) while in phase 1
// ("the window deliberately offers seats one level above") and the following year the series came out "locked":
// the calendar locked by level without looking at contracts. With an active contract, the level does not matter for THAT
// series (Josh's decision, 01/10); the other series of the level stay locked, and the gate lock does not change.


// Assumption of the time model: day-of-year is 1..366 WITHIN a single year, so a season can NOT cross the
// year boundary (Nov->Mar isn't representable: March would sort BEFORE November and PendingSlot/DnfPassedRounds would
// DNF it right at the start). Decision made Jul 20: this isn't modeled; this guard warns if someone authors a calendar
// that isn't monotonic, instead of letting it silently corrupt.






static void test_slots_conflict() {
    career::CalSlot lemans;   lemans.series_id   = "ivory_trophy_7202";   lemans.doy = 167; lemans.durationMin = 1440; lemans.valid = true; lemans.enrolled = true;
    career::CalSlot gp;       gp.series_id       = "drift_cup_1790"; gp.doy    = 167; gp.valid = true; gp.enrolled = true;
    career::CalSlot scb;      scb.series_id      = "falcon_series_9334";   scb.doy   = 173; scb.valid = true; scb.enrolled = true;
    career::CalSlot ivoryCup12573Other; ivoryCup12573Other.series_id = "ivory_trophy_7202";   ivoryCup12573Other.doy = 168; ivoryCup12573Other.valid = true; ivoryCup12573Other.enrolled = true;
    CHECK( career::SlotsConflict(lemans, gp));        // same weekend, different series -> conflicts
    CHECK(!career::SlotsConflict(lemans, scb));       // 6 days later -> no conflict
    CHECK(!career::SlotsConflict(lemans, ivoryCup12573Other));  // same series -> never conflicts (double-header)
    CHECK(!career::SlotsConflict(lemans, lemans));    // against itself (same series) -> no
    // travel nuance. Same day + SAME circuit at a different time -> you can race both;
    // same time -> conflicts; a DIFFERENT circuit the same day -> conflicts (no time to travel).
    career::CalSlot mSame;  mSame.series_id  = "aa"; mSame.doy  = 100; mSame.track_hash = 0x1234; mSame.hour = 10; mSame.valid = true; mSame.enrolled = true;
    career::CalSlot mLate;  mLate.series_id  = "bb"; mLate.doy  = 100; mLate.track_hash = 0x1234; mLate.hour = 15; mLate.valid = true; mLate.enrolled = true; // same circuit, +5h
    career::CalSlot mClash; mClash.series_id = "cc"; mClash.doy = 100; mClash.track_hash = 0x1234; mClash.hour = 10; mClash.valid = true; mClash.enrolled = true; // same circuit, SAME time
    career::CalSlot mAway;  mAway.series_id  = "dd"; mAway.doy  = 100; mAway.track_hash = 0x9999; mAway.hour = 15; mAway.valid = true; mAway.enrolled = true; // a DIFFERENT circuit, same day
    CHECK(!career::SlotsConflict(mSame, mLate));   // same day+circuit, different times -> you can do both
    CHECK( career::SlotsConflict(mSame, mClash));  // same day+circuit, SAME time -> conflicts
    CHECK( career::SlotsConflict(mSame, mAway));   // same day, DIFFERENT circuit -> conflicts (travel)
    // DURATION nuance: the same circuit on the same day conflicts if the TIME WINDOWS overlap (a different start time alone isn't enough).
    career::CalSlot longA; longA.series_id="la"; longA.doy=100; longA.track_hash=0x1234; longA.hour=13; longA.durationMin=360; longA.valid=true; longA.enrolled=true; // 6h starting at 13:00
    career::CalSlot nextH; nextH.series_id="nb"; nextH.doy=100; nextH.track_hash=0x1234; nextH.hour=14; nextH.durationMin=60;  nextH.valid=true; nextH.enrolled=true; // @14:00 (the 6h race is still running)
    CHECK( career::SlotsConflict(longA, nextH));   // the 6h race at 13:00 overlaps the one at 14:00 -> conflicts
    career::CalSlot lapsA; lapsA.series_id="lp"; lapsA.doy=100; lapsA.track_hash=0x1234; lapsA.hour=13; lapsA.laps=66;  lapsA.valid=true; lapsA.enrolled=true; // 66 laps (~132min) starting at 13:00
    career::CalSlot at15;  at15.series_id="at";  at15.doy=100;  at15.track_hash=0x1234;  at15.hour=15;  at15.durationMin=30; at15.valid=true;  at15.enrolled=true; // @15:00
    CHECK( career::SlotsConflict(lapsA, at15));    // the 66-lap race starting at 13:00 is still running at 15:00 -> conflicts (exactly the case a player reported)
    career::CalSlot shA; shA.series_id="sa"; shA.doy=100; shA.track_hash=0x1234; shA.hour=13; shA.durationMin=30; shA.valid=true; shA.enrolled=true; // 30min @13:00 -> ends ~14:00
    career::CalSlot shB; shB.series_id="sb"; shB.doy=100; shB.track_hash=0x1234; shB.hour=15; shB.durationMin=40; shB.valid=true; shB.enrolled=true; // @15:00
    CHECK(!career::SlotsConflict(shA, shB));       // short and well separated, same circuit -> VALID double-header
    // EstimatedRaceMinutes: time-based=exact; lap-based=positive scale; no data=default>0.
    career::CalSlot eT; eT.durationMin=90; CHECK_EQ(career::EstimatedRaceMinutes(eT), 90);
    career::CalSlot eL; eL.laps=66; int m66=career::EstimatedRaceMinutes(eL); CHECK(m66 >= 100 && m66 <= 180);
    career::CalSlot eD; CHECK(career::EstimatedRaceMinutes(eD) > 0);
}

// day-of-year (1..366) -> "DD Mon" (Gregorian, NOT leap-aware). Month boundaries and ranges.
static void test_doy_to_date() {
    CHECK(career::DoyToDate(1)   == "1 Jan");     // first day
    CHECK(career::DoyToDate(31)  == "31 Jan");    // end of January
    CHECK(career::DoyToDate(32)  == "1 Feb");     // 31+1
    CHECK(career::DoyToDate(59)  == "28 Feb");    // end of February (non-leap)
    CHECK(career::DoyToDate(60)  == "1 Mar");     // 31+28+1
    CHECK(career::DoyToDate(90)  == "31 Mar");
    CHECK(career::DoyToDate(91)  == "1 Apr");
    CHECK(career::DoyToDate(73)  == "14 Mar");    // 31+28+14 -> example from the design spec
    CHECK(career::DoyToDate(365) == "31 Dec");    // last day
    CHECK(career::DoyToDate(366) == "31 Dec");    // leap year -> treated as Dec 31
    CHECK(career::DoyToDate(0).empty());          // no date
    CHECK(career::DoyToDate(-5).empty());         // out of range
    CHECK(career::DoyToDate(400).empty());        // out of range
}

// The real time model's DateLabel renders an actual date with weekday (leap-aware).
static void test_date_label() {
    using namespace career;
    CHECK(DateLabel(2025, 166) == "Sun 15 Jun");   // doy166 = Jun 15, 2025 (non-leap) = Sunday
    CHECK(DateLabel(2028, 60)  == "Tue 29 Feb");    // 2028 leap year: doy 60 = Feb 29 = Tuesday
    CHECK(DateLabel(2025, 0).empty());
}

// WeekdayLabel gives the real (EN) weekday for a (year, doy).
static void test_weekday_label() {
    using namespace career;
    CHECK(WeekdayLabel(2025, 1)   == "Wed");   // Jan 1, 2025 = Wednesday
    CHECK(WeekdayLabel(2025, 166) == "Sun");   // Jun 15, 2025 = Sunday
    CHECK(WeekdayLabel(2025, 0).empty());
}

// WeeksToNextEvent = number of weeks (ceil) until the next pending slot with doy>cursor.
static void test_weeks_to_next_event() {
    auto mk = [](const char* id, int doy, bool enrolled, bool raced, bool dnf, bool locked, bool past)->career::CalSlot{
        career::CalSlot s; s.series_id=id; s.doy=doy; s.valid=true;
        s.enrolled=enrolled; s.raced=raced; s.dnf=dnf; s.locked=locked; s.past=past; return s; };
    std::vector<career::CalSlot> slots = {
        mk("a", 30, true,  false,false,false,false),   // pending, enrolled
        mk("b", 51, false, false,false,false,false),   // pending, open (future)
        mk("c", 20, false, false,false,false,true ),   // past -> ignore
        mk("d", 40, true,  true, false,false,false),   // already raced -> ignore
        mk("e", 45, false, false,false,true, false),   // blocked -> ignore
    };
    // cursor 16: next pending = doy 30 -> 14 days -> ceil(14/7)=2 weeks
    CHECK_EQ(career::WeeksToNextEvent(slots, 16), 2);
    // cursor 30: doy 30 does NOT count (strictly doy>cursor) -> next valid = 51 -> 21 days -> 3 weeks
    CHECK_EQ(career::WeeksToNextEvent(slots, 30), 3);
    // cursor 35: next = 51 -> 16 days -> ceil(16/7)=3
    CHECK_EQ(career::WeeksToNextEvent(slots, 35), 3);
    // cursor 60: nothing ahead (51 already passed) -> 0
    CHECK_EQ(career::WeeksToNextEvent(slots, 60), 0);
    // empty list -> 0
    CHECK_EQ(career::WeeksToNextEvent({}, 10), 0);
}





static void test_race_entry_outlay() {
    // A GUARANTEED payout to get you on the grid, per action.
    using career::EntryAction;
    // Renting: due + entry + carValue*rentPct% (same rounding as Settle)
    CHECK_EQ(career::RaceEntryOutlay(EntryAction::Rent, 600, 500, 28000, 16),
             600 + 500 + (long)(28000 * 16 / 100.0 + 0.5));            // 5580
    // Own car: due + entry + run-cost (2.5%)
    CHECK_EQ(career::RaceEntryOutlay(EntryAction::OwnCar, 600, 500, 28000, 16),
             600 + 500 + (long)(28000 * 0.025 + 0.5));                 // 1800
    // Buying: due + entry + run-cost + price(=carValue)
    CHECK_EQ(career::RaceEntryOutlay(EntryAction::Buy, 600, 500, 28000, 16),
             600 + 500 + (long)(28000 * 0.025 + 0.5) + 28000);         // 29800
    // factory/calibration seats pass due=entry=0 -> only the car's own cost
    CHECK_EQ(career::RaceEntryOutlay(EntryAction::Rent, 0, 0, 10000, 10),
             (long)(10000 * 10 / 100.0 + 0.5));                        // 1000
}

// (rev. 2, Aug 26, a deliberate design call): the collector car EXISTS — buying the Eskdale Gry320 costs its full 2.8M
// price — but RACING it costs like its class: the ECONOMIC value (CarItem.runValue, from which
// rental/tires/insurance/settle are derived) gets compressed against the class band. Within x3 it's untouched; beyond
// that, logarithmic compression that PRESERVES the class's price ordering.


static void test_calendar_inscription_save() {
    // inscription_paid persists per series; an old save (5 fields) -> counts as paid (back-compat).
    using namespace career;
    CHECK(LoadSeries(TESTDATA("series.psv")));
    CareerCalendar cc; CareerProgress prog; prog.credits = 1000000;
    Enroll(cc, "ivory_trophy_7202", prog);                 // inscription_paid=false
    Enroll(cc, "harbor_trophy_6546", prog);
    ChargeInscription(cc, "harbor_trophy_6546", prog);    // pays the 2nd -> inscription_paid=true
    // skin=team livery: latches car+skin in harbor_trophy_6546; ivory_trophy_7202 is left unset (-1/0)
    if (SeasonState* k0 = FindEnrollment(cc, "harbor_trophy_6546")) { k0->livery_ord = 3; k0->livery_veh = 1912720736; }
    const char* path = "build\\cal_inscription_test.sav";
    CHECK(SaveCalendar(cc, path));
    CareerCalendar cb; CHECK(LoadCalendar(cb, path));
    CHECK_EQ((int)cb.enrollments.size(), 2);
    const SeasonState* w = FindEnrollment(cb, "ivory_trophy_7202");
    const SeasonState* k = FindEnrollment(cb, "harbor_trophy_6546");
    CHECK(w && !w->inscription_paid);
    CHECK(k && k->inscription_paid);
    // the livery latch survives the round-trip; the unset series stays at -1/0
    CHECK(k && k->livery_ord == 3 && k->livery_veh == 1912720736);
    CHECK(w && w->livery_ord == -1 && w->livery_veh == 0);
    // back-compat: an old E line (5 fields, no flag) loads as PAID (the old model charged at enroll time)
    { FILE* f = fopen("build\\cal_oldfmt_test.sav", "wb");
      fputs("C|2025|80\r\nE|ivory_trophy_7202|EU|1|0|0\r\n", f); fclose(f); }
    CareerCalendar co; CHECK(LoadCalendar(co, "build\\cal_oldfmt_test.sav"));
    CHECK_EQ((int)co.enrollments.size(), 1);
    CHECK(co.enrollments[0].inscription_paid);
    // back-compat: an old save with no livery fields -> no latch (-1/0)
    CHECK(co.enrollments[0].livery_ord == -1 && co.enrollments[0].livery_veh == 0);
}

static void test_settle_entry_override() {
    career::CareerProgress p; p.credits = 0; p.frontier_phase = 4;
    career::RaceResult r; r.pos = 1; r.field = 20; r.finished = true; r.clean = false; r.race_phase = 4;
    // no override: entry = EntryForPhase(4) > 0
    career::SettleReport a = career::Settle(p, r, 30000, 8000, false, 0, 100000);
    CHECK(a.entry > 0);
    // override 0: no entry fee
    career::CareerProgress p2; p2.credits = 0; p2.frontier_phase = 4;
    career::SettleReport b = career::Settle(p2, r, 30000, 8000, false, 0, 100000, 0);
    CHECK_EQ(b.entry, 0);
    CHECK_EQ(b.credits_delta, a.credits_delta + a.entry);   // the net goes up by exactly what the entry fee used to be
}







// bug reported (a player): "calendar says today is 29 JUN... but in championship table there is DNF and
// date is 30 JUN." You race Sunday's round and Monday's round from another series comes out DNF without ever being run, with the
// clock still on Sunday. Root cause: weekendWindow was returning an EXTRA day after the race (hi = doy+trail+1) and
// SlotsConflict compares the intervals INCLUSIVELY -> two rounds on CONSECUTIVE days ALWAYS conflicted, even
// between two CLUB series whose documented footprint is "just the race day"; and a conflict doesn't warn, it DNFs
// (in ResolveAfterRace, step a).
// The test bites against the PRODUCTION CALENDAR and the EXACT pair from the report — juniper_cup_3635 (Sundays) +
// harbor_trophy_6546 (Mondays), the two series any new career starts with — which share three
// consecutive weekends (Apr 6/7, Jun 8/9, Jun 29/30): on every one of them a round was forced to drop out, no matter what.


// Running a PERIOD series (a memory) is "free time" — it doesn't move the clock, doesn't arm the latch
// for "one race per day", doesn't DNF past rounds, doesn't finish seasons.


// period conflict (player feedback, Jul 28): a memory is FREE TIME — it does NOT occupy the weekend. It doesn't conflict with anything in the
// live calendar (no warning icon on the card, no warning at launch, no DNF for the round enrolled that weekend), and
// it can't be the victim of a modern-era conflict either. Before, SlotsConflict was blind to era: the
// "free time" rule lived only in ResolveAfterRace's clock/latch section, so racing a memory from the
// same weekend would DNF your real race (and block (a) runs BEFORE that return).


static void test_owned_class_set() {
    career::SaveData s;
    CHECK(career::OwnedClassSet(s).empty());                 // no cars -> empty
    career::CarOwnership a; a.class_id = "Falcon_Masters"; s.owned.push_back(a);
    career::CarOwnership b; b.class_id = "Group C";        s.owned.push_back(b);
    career::CarOwnership c; c.class_id = "Falcon_Masters"; s.owned.push_back(c);  // duplicate class
    auto set = career::OwnedClassSet(s);
    CHECK_EQ((long)set.size(), 2);                           // dedup by class
    CHECK(set.count("Falcon_Masters") == 1);
    CHECK(set.count("Group C") == 1);
    CHECK(set.count("PINNACLE_CHALLENGE_4250") == 0);
}

static void test_owns_car_of_class() {
    CHECK(career::ClassPrefix("Falcon_Masters#759059246") == "Falcon_Masters");
    CHECK(career::ClassPrefix("Falcon_Masters") == "Falcon_Masters");
    career::SaveData s;
    CHECK(!career::OwnsCarOfClass(s, "Falcon_Masters"));
    career::CarOwnership c; c.class_id = "Falcon_Masters#759059246"; s.owned.push_back(c);   // purchase/gift format
    CHECK(career::OwnsCarOfClass(s, "Falcon_Masters"));                 // prefix matches
    CHECK(!career::OwnsClassId(s, "Falcon_Masters"));                    // EXACT doesn't match (correct)
    CHECK(career::OwnsClassId(s, "Falcon_Masters#759059246"));           // EXACT by specific id does
    auto set = career::OwnedClassSet(s);
    CHECK(set.count("Falcon_Masters") == 1);                            // OwnedClassSet returns the prefix
}



static void test_starter_memory_gift() {
    career::SaveData s;
    CHECK(!career::GrantStarterMemoryIfDue(s));                 // 0 races -> doesn't grant
    s.completed_races.insert("r1"); s.completed_races.insert("r2");
    CHECK(!career::GrantStarterMemoryIfDue(s));                 // 2 races -> no
    s.completed_races.insert("r3");                            // 3rd race
    CHECK(career::GrantStarterMemoryIfDue(s));                  // grants NOW
    CHECK(career::OwnsCarOfClass(s, career::kStarterMemoryClass)); // owns the F1'67 (by prefix)
    // curated gift: Highley Racing #1 (the '67 Model2), one of a kind on track
    const career::CarOwnership* g = nullptr;
    for (const auto& c : s.owned) if (career::ClassPrefix(c.class_id) == career::kStarterMemoryClass) { g = &c; break; }
    CHECK(g != nullptr);
    CHECK(g->class_id == "Falcon_Masters#759059246");   // keyed by car (purchase format)
    CHECK_EQ(g->vehid, 759059246);
    CHECK_EQ(g->livery, 0);   // livery = ORDINAL (index into CareerVehicleLiveryList), NOT the car number. Elmmoor Racing #1 = car number 50 = the lowest one => ordinal 0. (Using 50 directly as the ordinal fell out of range -> wrong skin.)
    CHECK(career::OwnsCarOfClass(s, "Falcon_Masters"));  // the gate recognizes it by prefix
    CHECK(s.claimed_events.count("gift_f167") == 1);           // marked
    size_t ownedAfter = s.owned.size();
    CHECK(!career::GrantStarterMemoryIfDue(s));                 // idempotent (already claimed)
    CHECK_EQ((long)s.owned.size(), (long)ownedAfter);          // doesn't duplicate the car
    s.completed_races.insert("r4");                           // 4th race
    CHECK(!career::GrantStarterMemoryIfDue(s));                 // still doesn't re-grant
}

// End-to-end: owning the gift car (purchase format class#veh) -> BuildMasterCalendar unlocks harbor_trophy_3430.
// This is the test that WOULD HAVE caught the ownership-key mismatch bug.


// ownership fix (real bug, Jul 21): OLD saves stored the F1'67 gift with the bare CLASS's class_id
// ("Falcon_Masters") instead of the per-car format ("Falcon_Masters#<veh>"). The garage resolved it by class (the
// car would show up), but PRE-RACE matches by EXACT id (CareerOwnsCar->OwnsClassId) -> the owned car came out
// as NOT-owned: greyed out, unselectable, no RACE button. LoadCareer normalizes every bare 'owned' entry with
// a valid vehid to the per-car format. It must run EVEN IF the save is already on the current version (MigrateSave
// early-returns in that case), which is why the fixture uses kSaveVersion.
static void test_owned_legacy_bare_class_normalized() {
    const char* path = "build/test_owned_bare.sav";
    { FILE* f = fopen(path, "wb"); CHECK(f != nullptr);
      if (f) { fprintf(f, "version %d\r\ncredits 24933\r\nowned Falcon_Masters 759059246 0 0.0000 1 50\r\n", career::kSaveVersion); fclose(f); } }
    career::SaveData d; CHECK(career::LoadCareer(d, path));
    CHECK_EQ((long)d.owned.size(), 1);
    // (1) normalized to the per-car format -> pre-race (EXACT OwnsClassId) recognizes the owned car.
    CHECK(d.owned.size() == 1 && d.owned[0].class_id == "Falcon_Masters#759059246");
    CHECK(career::OwnsClassId(d, "Falcon_Masters#759059246"));   // == the CareerOwnsCar check in pre-race
    CHECK_EQ(d.owned[0].vehid, 759059246);
    CHECK_EQ(d.owned[0].livery, 0);                             // the legacy car number 50 (wrongly stored as an ordinal) gets healed to ordinal 0 (Elmmoor Racing #1)
    CHECK(d.owned[0].insured);
    // (2) unlocking the series by PREFIX still holds (normalization doesn't touch the prefix).
    CHECK(career::OwnsCarOfClass(d, "Falcon_Masters"));
    CHECK(career::OwnedClassSet(d).count("Falcon_Masters") == 1);
    remove(path);
    // (3) idempotent / scoped: an entry ALREADY in per-car format is left untouched; a bare one with NO vehid (0) is left bare.
    const char* path2 = "build/test_owned_bare2.sav";
    { FILE* f = fopen(path2, "wb"); CHECK(f != nullptr);
      if (f) { fprintf(f, "version %d\r\nowned gt3_992#12345 12345 4 0.0000 1 -1\r\nowned LegacyClass 0 0 0.0000 0 -1\r\n", career::kSaveVersion); fclose(f); } }
    career::SaveData d2; CHECK(career::LoadCareer(d2, path2));
    CHECK_EQ((long)d2.owned.size(), 2);
    CHECK(d2.owned[0].class_id == "gt3_992#12345");   // already had a '#': untouched
    CHECK(d2.owned[1].class_id == "LegacyClass");      // vehid 0: no hash to append -> stays bare
    remove(path2);
}

static void test_starter_gift_pending() {
    career::SaveData s;
    CHECK(!career::StarterGiftPending(s));                 // not granted -> not pending
    s.claimed_events.insert("gift_f167");                  // granted
    CHECK(career::StarterGiftPending(s));                   // pending, not yet seen
    career::AckStarterGift(s);
    CHECK(s.claimed_events.count("gift_f167_seen") == 1);
    CHECK(!career::StarterGiftPending(s));                  // already seen -> not pending
    career::AckStarterGift(s);                              // idempotent
    CHECK_EQ((long)s.claimed_events.count("gift_f167_seen"), 1);
}



static void test_travel_lock_114bis() {
    // second case for "one race per day": after racing TODAY, the other races TODAY at a DIFFERENT circuit stay
    // travel_locked (you can't be in two places); the ones at the SAME circuit (venue double-header) do NOT. Robust:
    // scans the real calendar and picks a day with >=2 different circuits.
    CHECK(career::LoadSeries(TESTDATA("series.psv")));
    CHECK(career::LoadSeriesCalendar(TESTDATA("series_calendar.psv")));
    career::CareerCalendar cc;
    auto base = career::BuildMasterCalendar(cc, 7);   // frontier 7 = nothing blocked by level
    // player feedback, Jul 28: "one race per day" governs the LIVE calendar; period memories are EXEMPT
    // (free time, not travel — see test_memory_race_never_clashes). So the test's day/venue is picked
    // among MODERN series, and period slots are skipped in the checks below.
    auto isEra = [](const career::CalSlot& s) {
        const career::SeriesDef* d = career::SeriesById(s.series_id);
        return d && career::IsEraMemorySeries(*d);
    };
    int D = 0; long C = 0;
    for (auto& a : base) {
        if (a.track_hash == 0 || isEra(a)) continue;
        for (auto& b2 : base)
            if (b2.doy == a.doy && b2.track_hash != 0 && b2.track_hash != a.track_hash && !isEra(b2)) { D = a.doy; C = a.track_hash; break; }
        if (D) break;
    }
    CHECK(D != 0);   // the real calendar has days with multiple circuits
    // arms the latch: TODAY (cursor==D) you raced at circuit C
    cc.cursor_doy = D; cc.last_race_doy = D; cc.last_race_circuit = C;
    auto locked = career::BuildMasterCalendar(cc, 7);
    int nAwayLocked = 0, nHomeOpen = 0, nOtherDay = 0;
    for (auto& s : locked) {
        if (s.raced || s.dnf || isEra(s)) continue;   // memories follow their own rule (exempt)
        if (s.doy == D && s.track_hash == C)      { CHECK(!s.travel_locked); nHomeOpen++; }    // your venue: stays open (double-header)
        else if (s.doy == D && s.track_hash != 0) { CHECK(s.travel_locked);  nAwayLocked++; }  // another venue today: blocked by travel
        else if (s.doy != D && s.travel_locked)   nOtherDay++;                                  // other days: never
    }
    CHECK(nAwayLocked >= 1);
    CHECK(nHomeOpen  >= 1);
    CHECK_EQ(nOtherDay, 0);
    // self-limiting: if the clock has already advanced (cursor != last_race_doy), NOTHING stays travel_locked
    cc.cursor_doy = D + 1;
    auto advanced = career::BuildMasterCalendar(cc, 7);
    for (auto& s : advanced) CHECK(!s.travel_locked);
    // duration: if the race you ran occupies the WHOLE day (a huge window), even the double-header at your OWN
    // venue falls through (no time left). With the default window (0h) your venue's races stayed open (checked above).
    cc.cursor_doy = D; cc.last_race_hour = 0; cc.last_race_minutes = 24 * 60;
    auto allDay = career::BuildMasterCalendar(cc, 7);
    int homeLockedNow = 0;
    for (auto& s : allDay) { if (s.raced || s.dnf || isEra(s)) continue; if (s.doy == D && s.track_hash == C && s.travel_locked) homeLockedNow++; }
    CHECK(homeLockedNow >= 1);
    // latch + window persistence (round-trip)
    cc.cursor_doy = D; cc.last_race_doy = D; cc.last_race_circuit = C; cc.last_race_hour = 14; cc.last_race_minutes = 132;
    const char* p = "build\\cal_travel_114bis.sav";
    CHECK(career::SaveCalendar(cc, p));
    career::CareerCalendar cb; CHECK(career::LoadCalendar(cb, p));
    CHECK_EQ(cb.last_race_doy, D);
    CHECK_EQ((long)cb.last_race_circuit, C);
    CHECK_EQ(cb.last_race_hour, 14);
    CHECK_EQ(cb.last_race_minutes, 132);
}

