// 19/09 (tester: finished P9 in an event and was paid ₡51.104; then won their class and was paid nothing, while the
// pre-race kept promising ₡250.000). Josh's decision: THE DIFFERENCE IS PAID. A better finish pays what
// is missing up to what it is worth; an equal or worse one, 0. What was collected lives on a NEW line of the save (`evpaid`).
static void test_event_pays_the_difference() {
    using namespace career;
    const long bolsa = 250000;
    const long vale9 = PrizeFor(9, bolsa, 0), vale1 = PrizeFor(1, bolsa, 0);
    CHECK(vale9 > 0 && vale9 < vale1);
    CHECK_EQ(vale1, bolsa);

    // P9 and then P1: the first pays its own; the second, the DIFFERENCE (in total, what winning is worth)
    { SaveData s;
      CHECK_EQ(EventClaimCredits(s, "ev-mc", vale9), vale9);
      CHECK_EQ(EventClaimCredits(s, "ev-mc", vale1), vale1 - vale9);
      CHECK_EQ(s.event_paid["ev-mc"], vale1);
      CHECK_EQ(EventClaimCredits(s, "ev-mc", vale1), 0L); }       // repeating the win no longer pays

    // P1 and then P9: the worse finish pays nothing nor lowers what was collected
    { SaveData s;
      CHECK_EQ(EventClaimCredits(s, "ev-mc", vale1), vale1);
      CHECK_EQ(EventClaimCredits(s, "ev-mc", vale9), 0L);
      CHECK_EQ(s.event_paid["ev-mc"], vale1); }

    // each event has its own account; with no result worth anything, nothing is paid or recorded
    { SaveData s;
      CHECK_EQ(EventClaimCredits(s, "ev-a", 1000), 1000L);
      CHECK_EQ(EventClaimCredits(s, "ev-b", 400), 400L);
      CHECK_EQ(EventClaimCredits(s, "ev-c", 0), 0L);
      CHECK_EQ(EventClaimCredits(s, "", 500), 0L);
      CHECK_EQ((int)s.event_paid.size(), 2); }

    // save round-trip: the new line comes back whole (id with a space included, ) and a save without it
    // loads with NOTHING collected
    { SaveData a;
      a.claimed_events.insert("ev-mc");
      a.event_paid["ev-mc"] = vale9;
      a.event_paid["ev con espacio"] = 1234;
      const char* p = "build\\test_evpaid.sav";
      CHECK(SaveCareer(a, p));
      SaveData b; CHECK(LoadCareer(b, p));
      CHECK_EQ((int)b.event_paid.size(), 2);
      CHECK_EQ(b.event_paid["ev-mc"], vale9);
      CHECK_EQ(b.event_paid["ev con espacio"], 1234L);
      CHECK_EQ(EventClaimCredits(b, "ev-mc", vale1), vale1 - vale9);   // after reloading, it still pays the difference
      remove(p);
      SaveData viejo; viejo.claimed_events.insert("ev-mc");             // a save from before: without `evpaid`
      CHECK(SaveCareer(viejo, p));
      SaveData c; CHECK(LoadCareer(c, p));
      CHECK(c.event_paid.empty());
      CHECK(c.claimed_events.count("ev-mc") == 1);
      remove(p); }
}







