// ===================== Minimalist JSON parser + season-JSON adapter =====================

static void test_json_parser() {
    using namespace jsonm;
    std::string err;
    // nested object + array + escapes + numbers (negative/decimal/exponent) + bool/null + UTF-8 bytes
    const char* src =
        "{ \"a\": 1, \"b\": -42, \"c\": 3.5, \"d\": -1.25e2, "
        "\"s\": \"hi \\\"q\\\" \\\\ \\/ \\n \\t end\", "
        "\"u\": \"M\xC3\xB4naco\", "          // UTF-8 verbatim (o-circumflex)
        "\"arr\": [1, 2, [3, 4], {\"x\": true}], "
        "\"nest\": { \"deep\": { \"v\": null, \"flag\": false } }, "
        "\"neg0\": -0 }";
    ValuePtr v = Parse(src, &err);
    CHECK(v != nullptr);
    if (!v) { printf("  parse err: %s\n", err.c_str()); return; }
    CHECK(v->isObject());
    CHECK_EQ(v->memberInt("a"), 1);
    CHECK_EQ(v->memberInt("b"), -42);
    CHECK(v->memberNumber("c") > 3.49 && v->memberNumber("c") < 3.51);
    CHECK_EQ((long)v->memberNumber("d"), -125);
    CHECK(v->memberString("s") == "hi \"q\" \\ / \n \t end");      // escapes resolved
    CHECK(v->memberString("u") == "M\xC3\xB4naco");                // UTF-8 bytes intact
    const Value* arr = v->member("arr");
    CHECK(arr && arr->isArray() && arr->arr.size() == 4);
    CHECK(arr && arr->arr[2]->isArray() && arr->arr[2]->arr.size() == 2);
    CHECK(arr && arr->arr[3]->isObject() && arr->arr[3]->memberBool("x") == true);
    const Value* nest = v->member("nest");
    CHECK(nest && nest->member("deep") != nullptr);
    CHECK(nest && nest->member("deep")->member("v")->isNull());
    CHECK(nest && nest->member("deep")->memberBool("flag", true) == false);
    // has(): null/absent -> false; present non-null -> true
    CHECK(!nest->member("deep")->has("v"));        // v is null
    CHECK(v->has("a"));
    CHECK(!v->has("nope"));
    // defensive \uXXXX -> UTF-8 (e-acute = U+00E9 -> 0xC3 0xA9)
    ValuePtr u = Parse("{\"k\":\"caf\\u00e9\"}", &err);
    CHECK(u && u->memberString("k") == "caf\xC3\xA9");
    // empty arrays/objects + trailing whitespace
    ValuePtr e1 = Parse("{ \"a\": [], \"b\": {} }   \n  ", &err);
    CHECK(e1 && e1->member("a")->isArray() && e1->member("a")->arr.empty());
    CHECK(e1 && e1->member("b")->isObject() && e1->member("b")->obj.empty());
    // malformed input -> nullptr (no crash)
    CHECK(Parse("{ \"a\": }", &err) == nullptr);
    CHECK(Parse("[1, 2,", &err) == nullptr);
    CHECK(Parse("nul", &err) == nullptr);
    CHECK(Parse("{\"a\":1} garbage", &err) == nullptr);
}

