// ============================ Dynamic market offers ============================
// SeatsForSeries (seats per series based on classes.json's grid_kind) + GenerateOffers (combines
// seats + player state). Deterministic and pure. Loads the JSON data (tier + gates) and
// restores the PSV state at the end (same as the rest of the tests that touch the JSON path).

// helper: looks up a series' GenOffer by its series_id ("of_"+sid); nullptr if it wasn't offered.
static const market::GenOffer* findOffer(const std::vector<market::GenOffer>& v, const std::string& sid) {
    std::string oid = "of_" + sid;
    for (const auto& g : v) if (g.def.id == oid) return &g;
    return nullptr;
}



// ============================ Contract lifecycle ============================

// (a) Contract + declined_offers round-trip through SaveCareer/LoadCareer; a save WITHOUT those lines (legacy)
//     loads to an INACTIVE contract + an empty set (back-compat).


// (b) AcceptOffer: a NOT-held offer -> active contract, credits += signBonus exactly (the entry fee
//     is waived -> no extra charge), the series' entry is present; a 2nd accept for ANOTHER series also
//     signs (multi-contract), but a 2nd accept for the SAME series is REJECTED (duplicate).


// (c) ContractFactorySeat: true for the contracted works series, false in every other case.
// (Jul 21): this is the invariant CalUiFactorySeatForRace and the settle's 2 branches now use
// (calendar/season) to decide factory status -> with NO contract it must be false (own/loose car = own/rental).
static void test_contract_factory_seat() {
    using namespace career;
    SaveData save;
    // no contract -> always false
    CHECK(!ContractFactorySeat(save, "ivory_trophy_7202"));
    CHECK(!ContractFactorySeat(save, ""));

    // a works contract (kind 0) for ivory_trophy_7202
    save.contracts.assign(1, career::Contract{});
    save.contracts[0].active = true; save.contracts[0].kind = 0; save.contracts[0].series_id = "ivory_trophy_7202";
    CHECK(ContractFactorySeat(save, "ivory_trophy_7202"));     // same series, works -> true
    CHECK(!ContractFactorySeat(save, "pinnacle_series_4783"));   // different series -> false
    CHECK(!ContractFactorySeat(save, ""));            // empty series -> false

    // a CLIENT contract (kind 1) for the same series -> NOT a factory seat
    save.contracts[0].kind = 1;
    CHECK(!ContractFactorySeat(save, "ivory_trophy_7202"));
}

// test_sponsor_req_met / test_sponsor_trait_tier / test_sponsor_trait_cover retired — they exercised
// career::SponsorReqMet/TraitIsCoverage/SponsorTierBase/SponsorTraitCoverThisRace, all deleted with
// career_sponsor.{h,cpp} (the objective-sponsor catalog/gates). No replacement needed: the cards system
// (below) has its own dedicated test coverage.

// Living World: deal coverage<->income trade.
static void test_econ_income_per_race() {
    // q(R)=0.5 (rating 1600), coverage 0 -> base * (0.7 + 0.6*0.5) = base * 1.0
    CHECK_EQ(career::IncomePerRace(20000, 0.5, 0.0), 20000);
    // q(R)=1.0, coverage 0 -> base * 1.3
    CHECK_EQ(career::IncomePerRace(20000, 1.0, 0.0), 26000);
    // q(R)=0.0, coverage 0 -> base * 0.7
    CHECK_EQ(career::IncomePerRace(20000, 0.0, 0.0), 14000);
    // full coverage (1.0) at q=0.5: base*1.0*(1 - 1.0*0.45) = base*0.55
    CHECK_EQ(career::IncomePerRace(20000, 0.5, 1.0), 11000);
    // clamps: qR>1 treated as 1, coverage<0 as 0
    CHECK_EQ(career::IncomePerRace(20000, 5.0, -1.0), 26000);
    // wiring to RatingQuality: rating 1600 -> q=0.5 -> base*1.0
    CHECK_EQ(career::IncomePerRace(20000, career::RatingQuality(1600), 0.0), 20000);
}

// Living World: your-share of cost net of coverage.
static void test_econ_coverage_share() {
    CHECK_EQ(career::CoverageShare(10000, 4000), 6000);  // partial coverage -> you owe the rest
    CHECK_EQ(career::CoverageShare(10000, 0),     10000); // no coverage -> full cost
    CHECK_EQ(career::CoverageShare(10000, 10000), 0);     // fully covered
    CHECK_EQ(career::CoverageShare(10000, 12000), 0);     // over-coverage never goes negative
    CHECK_EQ(career::CoverageShare(0,     4000),  0);     // no cost -> no share
}

// Living World: the qualifier-entry money sink.
static void test_econ_qualifier_cost() {
    CHECK_EQ(career::QualifierEntryCost(1), 2000);
    CHECK_EQ(career::QualifierEntryCost(4), 25000);
    CHECK_EQ(career::QualifierEntryCost(7), 140000);
    CHECK_EQ(career::QualifierEntryCost(0), 2000);     // clamp low
    CHECK_EQ(career::QualifierEntryCost(99), 140000);  // clamp high
    // it's a heavier shot than the per-round entry of the same phase
    CHECK(career::QualifierEntryCost(4) > career::EntryForPhase(4));
}

// Living World: Settle applies sponsor coverage + per-race deal salary (additive defaulted params).
static void test_settle_coverage() {
    // baseline (no extra params) must be byte-identical to test_settle's numbers
    career::CareerProgress prog; prog.frontier_phase = 4; prog.rep = 150;
    career::RaceResult r; r.pos = 1; r.field = 20; r.finished = true; r.clean = true; r.race_phase = 4;
    career::SettleReport base = career::Settle(prog, r, 30000, 8000, true, 22, 30000);
    CHECK_EQ(base.credits_delta, 26900);   // unchanged: regression guard for the new defaulted params (no retainer)
    CHECK_EQ(base.coverage, 0);
    CHECK_EQ(base.deal_salary, 0);

    // now WITH coverage 5000 (sponsors cover part of entry+costs) + a per-race deal salary 12000
    career::CareerProgress p2; p2.frontier_phase = 4; p2.rep = 150;
    career::SettleReport s = career::Settle(p2, r, 30000, 8000, true, 22, 30000,
                                            /*entryOverride=*/-1, /*factorySeat=*/false,
                                            /*coverage=*/5000, /*dealSalary=*/12000);
    CHECK_EQ(s.entry, 4000);
    CHECK_EQ(s.costs, 6600);
    CHECK_EQ(s.coverage, 5000);
    CHECK_EQ(s.deal_salary, 12000);
    // net = prize + clean_bonus + salary(factory=0) + deal_salary - entry - costs + coverage
    //     = 30000 + 7500 + 0 + 12000 - 4000 - 6600 + 5000 = 43900   (no sponsor retainer)
    CHECK_EQ(s.credits_delta, 43900);
    CHECK_EQ(p2.credits, 43900);

    // coverage never makes you-share negative: huge coverage caps at (entry+costs)
    career::CareerProgress p3; p3.frontier_phase = 4; p3.rep = 150;
    career::SettleReport s3 = career::Settle(p3, r, 30000, 8000, true, 22, 30000, -1, false,
                                             /*coverage=*/999999, /*dealSalary=*/0);
    CHECK_EQ(s3.coverage, 10600);   // clamped to entry(4000)+costs(6600)
    // net = 30000 + 7500 - 4000 - 6600 + 10600 = 37500   (no sponsor retainer)
    CHECK_EQ(s3.credits_delta, 37500);
}

// Living World: signed-sponsor persistence (additive, back-compat).
static void test_signed_sponsor_save() {
    career::SaveData a;
    a.prog.credits = 50000; a.prog.frontier_phase = 3;
    career::SignedSponsor sp; sp.id = "sp_veltro"; sp.tier = career::ST_REGIONAL;
    career::SponsorTrait t1; t1.kind = career::TRAIT_TYRES; t1.cap_rounds = 6; t1.cap_value = 28000;
    career::SponsorTrait t2; t2.kind = career::TRAIT_MEDIA; t2.cap_rounds = 0; t2.cap_value = 0;
    sp.traits = { t1, t2 }; sp.rounds_used = { 2, 0 }; sp.value_used = { 9000, 0 };
    // (Apr 2): the v2-pivot per-SPONSOR objective fields, persisted via the additive sponsor_obj line.
    sp.obj_kind = "podiums"; sp.obj_goal = 3; sp.obj_progress = 1; sp.paid = true; sp.signed_year = 2027;
    a.signed_sponsors.push_back(sp);

    const char* path = "build/test_sponsor_save.sav";
    CHECK(career::SaveCareer(a, path));
    career::SaveData b;
    CHECK(career::LoadCareer(b, path));
    CHECK_EQ((int)b.signed_sponsors.size(), 1);
    if (b.signed_sponsors.empty()) return;   // guard: with no sponsor loaded, [0] would be an access violation instead of a readable FAIL
    CHECK(b.signed_sponsors[0].id == "sp_veltro");
    CHECK_EQ(b.signed_sponsors[0].tier, career::ST_REGIONAL);
    CHECK_EQ((int)b.signed_sponsors[0].traits.size(), 2);
    CHECK_EQ(b.signed_sponsors[0].traits[0].kind, career::TRAIT_TYRES);
    CHECK_EQ(b.signed_sponsors[0].traits[0].cap_rounds, 6);
    CHECK_EQ(b.signed_sponsors[0].traits[0].cap_value, 28000);
    CHECK_EQ(b.signed_sponsors[0].rounds_used[0], 2);
    CHECK_EQ(b.signed_sponsors[0].value_used[0], 9000);
    CHECK_EQ(b.signed_sponsors[0].traits[1].kind, career::TRAIT_MEDIA);
    // the objective fields survive the round-trip (the new additive sponsor_obj line)
    CHECK(b.signed_sponsors[0].obj_kind == "podiums");
    CHECK_EQ(b.signed_sponsors[0].obj_goal, 3);
    CHECK_EQ(b.signed_sponsors[0].obj_progress, 1);
    CHECK_EQ((int)b.signed_sponsors[0].paid, 1);
    CHECK_EQ(b.signed_sponsors[0].signed_year, 2027);

    // Regression test (the PRODUCTION sign path, career::SponsorDefToSigned, is retired — this now
    // constructs the SignedSponsor directly, mirroring what that converter used to emit): EMPTY coverage
    // traits (coverage dormant), so NO per-trait `sponsor` line is written and the tier was
    // carried ONLY on that (never-written) line -> it collapsed to 0=Local on reload (~45x low Elite payout +
    // corrupt capacity). Assert the tier still survives via the sponsor_obj line.
    {
        career::SaveData ea;
        career::SignedSponsor prod; prod.id = "sp torremocha"; prod.tier = career::ST_ELITE;
        prod.obj_kind = "damagefree"; prod.obj_goal = 5; prod.obj_progress = 0; prod.paid = false;
        prod.signed_year = 2031;
        CHECK_EQ((int)prod.traits.size(), 0);                 // production converter: NO coverage traits
        CHECK_EQ(prod.tier, career::ST_ELITE);
        ea.signed_sponsors.push_back(prod);
        const char* pp = "build/test_sponsor_prod.sav";
        CHECK(career::SaveCareer(ea, pp));
        career::SaveData eb;
        CHECK(career::LoadCareer(eb, pp));
        CHECK_EQ((int)eb.signed_sponsors.size(), 1);
        CHECK(eb.signed_sponsors[0].id == "sp torremocha");
        CHECK_EQ((int)eb.signed_sponsors[0].traits.size(), 0); // still no traits after reload
        // THE FIX: Elite reloads as Elite, NOT Local — tier persisted on the sponsor_obj line.
        CHECK_EQ(eb.signed_sponsors[0].tier, career::ST_ELITE);
        CHECK(eb.signed_sponsors[0].obj_kind == "damagefree");
        CHECK_EQ(eb.signed_sponsors[0].obj_goal, 5);
        CHECK_EQ(eb.signed_sponsors[0].signed_year, 2031);
    }

    // back-compat: a LEGACY 6-field sponsor_obj line (no tier field) still loads clean — tier stays at the
    // SignedSponsor default (0) when no preceding `sponsor` line set it (parts[6] empty -> tier untouched).
    {
        const char* p6 = "build/test_sponsor_obj_legacy6.sav";
        FILE* f = fopen(p6, "wb");
        CHECK(f != nullptr);
        fprintf(f, "version 3\r\n");  // v3 (post-migration): sponsors manually written for parser test
        fprintf(f, "sponsor_obj %s|%s|%d|%d|%d|%d\r\n", "sp_old6", "wins", 1, 0, 0, 2020); // 6 fields, no tier
        fclose(f);
        career::SaveData g6;
        CHECK(career::LoadCareer(g6, p6));
        CHECK_EQ((int)g6.signed_sponsors.size(), 1);
        CHECK(g6.signed_sponsors[0].obj_kind == "wins");
        CHECK_EQ(g6.signed_sponsors[0].tier, 0);              // no tier field -> safe default, no crash
        CHECK_EQ(g6.signed_sponsors[0].signed_year, 2020);
    }

    // back-compat: a save with NO sponsor lines loads to an empty vector (no crash, no spurious entries)
    career::SaveData c; c.prog.credits = 1;
    const char* p2 = "build/test_no_sponsor.sav";
    CHECK(career::SaveCareer(c, p2));
    career::SaveData d2;
    CHECK(career::LoadCareer(d2, p2));
    CHECK_EQ((int)d2.signed_sponsors.size(), 0);

    // back-compat: an OLD save with a per-trait `sponsor` line but NO `sponsor_obj` line loads to a
    // SignedSponsor with DEFAULT objective fields (objective absent -> defaults; old saves load clean).
    const char* p3 = "build/test_sponsor_legacy.sav";
    {
        FILE* f = fopen(p3, "wb");
        CHECK(f != nullptr);
        fprintf(f, "version 3\r\n");  // v3 (post-migration): sponsors manually written for parser test
        fprintf(f, "sponsor %s|%d|%d|%d|%ld|%d|%ld\r\n",
                "sp_legacy", career::ST_LOCAL, career::TRAIT_TRANSPORT, 4, 12000L, 1, 3000L);
        fclose(f);
    }
    career::SaveData e2;
    CHECK(career::LoadCareer(e2, p3));
    CHECK_EQ((int)e2.signed_sponsors.size(), 1);
    CHECK(e2.signed_sponsors[0].id == "sp_legacy");
    CHECK_EQ(e2.signed_sponsors[0].tier, career::ST_LOCAL);
    CHECK_EQ((int)e2.signed_sponsors[0].traits.size(), 1);
    CHECK(e2.signed_sponsors[0].obj_kind.empty());   // no sponsor_obj line -> default empty objective
    CHECK_EQ(e2.signed_sponsors[0].obj_goal, 0);
    CHECK_EQ(e2.signed_sponsors[0].obj_progress, 0);
    CHECK_EQ((int)e2.signed_sponsors[0].paid, 0);
    CHECK_EQ(e2.signed_sponsors[0].signed_year, 0);
}

// v3 migration — retire signed_sponsors with a refund of the acquisition cost.
static void test_card_migration_v3() {
    using namespace career;
    SaveData d{};
    d.prog.credits = 10000;
    SignedSponsor s1; s1.id = "sp_local_a"; s1.tier = 0;     // refund 2000
    SignedSponsor s2; s2.id = "sp_intl_b";  s2.tier = 3;     // refund 60000
    d.signed_sponsors = { s1, s2 };
    CHECK(MigrateSave(d, 2));                                // save v2 -> v3
    CHECK(d.signed_sponsors.empty());
    CHECK_EQ(d.prog.credits, 72000);                         // 10000 + 2000 + 60000
    // idempotence: a save already on v3 doesn't get touched again
    d.prog.credits = 500;
    CHECK(MigrateSave(d, kSaveVersion));
    CHECK_EQ(d.prog.credits, 500);
    // out-of-range tier clamps
    SaveData e{}; e.prog.credits = 0;
    SignedSponsor s3; s3.id = "x"; s3.tier = 99;
    e.signed_sponsors = { s3 };
    CHECK(MigrateSave(e, 2));
    CHECK_EQ(e.prog.credits, 130000);                        // clamps to elite
}

// Block C: v4 -> v5 migration — weather stops having TWO controls. The "Inherited" row from (bit
// kInhWeather) and wx_mode were deciding the same thing, and the bit silently won: with it set, choosing Random or
// Selection did nothing, and it was also wiping out the AUTHORED weather of a historical round. The bit is retired and its
// intent gets translated to the control that remains.
static void test_weather_inherit_migration_v5() {
    using namespace career;
    // (1) the bit set and wx_mode at its default -> translates to inherited and the bit gets cleared
    SaveData d{};
    d.prog.inherit_mask = kInhWeather | kInhHour;
    d.prog.wx_mode = 0;
    CHECK(MigrateSave(d, 4));
    CHECK_EQ(d.prog.wx_mode, 1);                                  // 1 = inherited from your Custom Race
    CHECK_EQ(d.prog.inherit_mask & kInhWeather, 0);               // the bit no longer exists
    CHECK(d.prog.inherit_mask & kInhHour);                        // the other fields are NOT touched

    // (2) whoever already picked a mode explicitly overrides the old bit
    SaveData e{};
    e.prog.inherit_mask = kInhWeather;
    e.prog.wx_mode = 2;                                           // Selection
    CHECK(MigrateSave(e, 4));
    CHECK_EQ(e.prog.wx_mode, 2);                                  // respected
    CHECK_EQ(e.prog.inherit_mask & kInhWeather, 0);

    // (3) with no bit, nothing gets invented: a save that never inherited weather stays on Random
    SaveData f{};
    f.prog.wx_mode = 0;
    CHECK(MigrateSave(f, 4));
    CHECK_EQ(f.prog.wx_mode, 0);

    // (4) idempotent: a save already on v5 doesn't get translated again
    SaveData g{};
    g.prog.inherit_mask = kInhWeather;                            // it shouldn't exist, but if it does, it's ignored
    g.prog.wx_mode = 0;
    CHECK(MigrateSave(g, kSaveVersion));
    CHECK_EQ(g.prog.wx_mode, 0);
    // The other half (that SettingsInheritBit no longer accepts the "weather" token) lives in career_overlay.cpp, which
    // is NOT part of this build; it's covered by the app's test, which checks that Settings doesn't render that row.
}

// Pure wallet/shop operations (buy/reroll/close/slot/bench/upgrade/sell)
static void test_card_ops() {
    using namespace career;
    SaveData d{};
    d.prog.credits = 20000; d.prog.frontier_phase = 3;       // 3 slots
    d.card_shop.open = true; d.card_shop.race_id = "rX"; d.card_shop.seed_base = 4;
    d.card_shop.offers = { "card_volt", "card_neumasport", "card_kronos" };

    CHECK(!CardOpBuy(d, "card_stratos"));                    // not in the offer
    CHECK(CardOpBuy(d, "card_volt"));                        // 8000
    CHECK_EQ(d.prog.credits, 12000);
    CHECK_EQ((int)d.cards.size(), 1);
    CHECK_EQ(d.cards[0].slot, 0);                            // first free slot
    CHECK_EQ(d.cards[0].races_left, 8);                      // life initialized
    CHECK_EQ(d.cards[0].invested, 8000);
    CHECK(!CardOpBuy(d, "card_neumasport"));                 // max 1 purchase/shop
    CHECK(!CardOpBuy(d, "card_volt"));                       // already purchased

    long rr = CardShopRerollCost(0, d.cards);                // 1200
    CHECK(CardOpReroll(d));
    CHECK_EQ(d.prog.credits, 12000 - rr);
    CHECK_EQ(d.card_shop.rerolls, 1);
    CHECK_EQ((int)d.card_shop.offers.size(), CardShopOfferCount(d.cards));
    for (const auto& o : d.card_shop.offers) CHECK(o != "card_volt");   // owned one excluded

    CHECK(CardOpShopClose(d));
    CHECK(!d.card_shop.open);
    CHECK(!CardOpBuy(d, "card_kronos"));                     // shop closed

    // slot/bench
    CHECK(CardOpBench(d, "card_volt"));  CHECK_EQ(d.cards[0].slot, -1);
    CHECK(CardOpSlot(d, "card_volt", 2)); CHECK_EQ(d.cards[0].slot, 2);
    CHECK(!CardOpSlot(d, "card_volt", 3));                   // career stage 3 -> slots 0..2
    // upgrade: volt isn't upgradable
    CHECK(!CardOpUpgrade(d, "card_volt"));
    // sale
    long credits0 = d.prog.credits;
    CHECK(CardOpSell(d, "card_volt"));
    CHECK_EQ(d.prog.credits, credits0 + 3200);               // 8000*0.40
    CHECK(d.cards.empty());

    // rollover: clause counters reset, everything else persists
    SignedCard tri; tri.card_id = "card_tribuna"; tri.slot = 0; tri.clause_miss = 2; tri.races_left = 4;
    d.cards.push_back(tri);
    CardOpSeasonReset(d);
    CHECK_EQ(d.cards[0].clause_miss, 0);
    CHECK_EQ(d.cards[0].races_left, 4);
}

// CardOpCede — regression test for the erase-on-cede logic extracted from MarketUiAccept. Seeds 2
// cards of the SAME rarity (0: neumasport + helicam) + 1 of a different rarity (1: volt, on the bench). Cedes one by
// id -> exactly that one disappears, the other two survive, credits UNTOUCHED (a cede isn't a sale).
// Rarity does NOT match -> false, wallet untouched. Nonexistent id -> false.
static void test_card_cede() {
    using namespace career;
    SaveData d{};
    d.prog.credits = 5000;
    SignedCard a; a.card_id = "card_neumasport"; a.slot = 0;   // rarity 0
    SignedCard b; b.card_id = "card_helicam";    b.slot = 1;   // rarity 0 (same rarity as 'a')
    SignedCard c; c.card_id = "card_volt";       c.slot = -1;  // rarity 1 (bench)
    d.cards = { a, b, c };

    CHECK(CardOpCede(d, "card_neumasport", 0));                // expected rarity 0 -> matches
    CHECK_EQ((int)d.cards.size(), 2);
    CHECK_EQ(d.prog.credits, 5000);                            // NEVER pays/refunds
    bool hasA = false, hasB = false, hasC = false;
    for (auto& sc : d.cards) {
        if (sc.card_id == "card_neumasport") hasA = true;
        if (sc.card_id == "card_helicam")    hasB = true;
        if (sc.card_id == "card_volt")       hasC = true;
    }
    CHECK(!hasA); CHECK(hasB); CHECK(hasC);                    // exactly the requested one disappears

    // rarity doesn't match -> false, nothing gets removed
    CHECK(!CardOpCede(d, "card_volt", 0));                     // volt is rarity 1, not 0
    CHECK_EQ((int)d.cards.size(), 2);
    CHECK_EQ(d.prog.credits, 5000);

    // nonexistent id -> false
    CHECK(!CardOpCede(d, "no_such_card", 0));
    CHECK_EQ((int)d.cards.size(), 2);
}

// GenerateCardEmails — dedicated card mail family (reuses the
// mailExists/emitMail dedup+persist idiom, family=2 same as sponsor mails). kind 0=purchase 1=clause
// 2=expiration/loss. Content-id embeds kind+card+year+day -> a repeat of the SAME event dedupes.
static void test_card_emails() {
    using namespace career;
    SaveData d{};
    auto v0 = GenerateCardEmails(d, "card_volt", 2026, 100, /*kind=*/0);   // compra
    CHECK(!v0.empty());
    // dedup by content-id: repeating doesn't duplicate
    auto v1 = GenerateCardEmails(d, "card_volt", 2026, 100, 0);
    CHECK(v1.empty());
    auto v2 = GenerateCardEmails(d, "card_volt", 2026, 108, /*kind=*/1);   // cláusula
    CHECK(!v2.empty());
    auto v3 = GenerateCardEmails(d, "card_volt", 2026, 115, /*kind=*/2);   // expiración
    CHECK(!v3.empty());
}

// Signed-card + card-shop persistence with round-trip.
static void test_card_save_roundtrip() {
    using namespace career;
    SaveData d{};
    SignedCard a; a.card_id = "card_neumasport"; a.level = 2; a.slot = 0;
    a.races_active = 7; a.invested = 5500;
    SignedCard b; b.card_id = "card_helicam"; b.slot = -1; b.uses_left = 2; b.invested = 2500;
    SignedCard c; c.card_id = "card_tribuna"; c.slot = 1; c.races_left = 4; c.clause_miss = 2; c.invested = 8000;
    d.cards = { a, b, c };
    d.card_shop.open = true; d.card_shop.race_id = "r_millvale_gt3";
    d.card_shop.seed_base = 12; d.card_shop.rerolls = 1; d.card_shop.bought = 1;
    d.card_shop.offers = { "card_volt", "card_kronos", "card_stratos" };
    d.card_shop.bought_ids = { "card_volt" };

    const char* path = "build/test_cards.sav";
    CHECK(career::SaveCareer(d, path));
    SaveData e{};
    CHECK(career::LoadCareer(e, path));
    CHECK_EQ((int)e.cards.size(), 3);
    CHECK(e.cards[0].card_id == "card_neumasport");
    CHECK_EQ(e.cards[0].level, 2); CHECK_EQ(e.cards[0].slot, 0);
    CHECK_EQ(e.cards[0].races_active, 7); CHECK_EQ(e.cards[0].invested, 5500);
    CHECK_EQ(e.cards[1].slot, -1); CHECK_EQ(e.cards[1].uses_left, 2);
    CHECK_EQ(e.cards[2].races_left, 4); CHECK_EQ(e.cards[2].clause_miss, 2);
    CHECK(e.card_shop.open);
    CHECK(e.card_shop.race_id == "r_millvale_gt3");
    CHECK_EQ(e.card_shop.seed_base, 12); CHECK_EQ(e.card_shop.rerolls, 1); CHECK_EQ(e.card_shop.bought, 1);
    CHECK_EQ((int)e.card_shop.offers.size(), 3);
    CHECK(e.card_shop.offers[1] == "card_kronos");
    CHECK_EQ((int)e.card_shop.bought_ids.size(), 1);
    remove(path);
    // a save with NO cards: loads to clean defaults
    SaveData f0{}; SaveCareer(f0, path);
    SaveData f1{}; CHECK(LoadCareer(f1, path));
    CHECK(f1.cards.empty()); CHECK(!f1.card_shop.open);
    remove(path);
}

// test_sponsor_coverage_for_race retired — exercised career::SponsorCoverageForRace, deleted with
// career_sponsor.{h,cpp} (the dormant v1 coverage engine's trait-cap math, never wired to production).

// ===== sponsor cards =====
static void test_card_helpers() {
    using namespace career;
    const CardDef* neu = CardById("card_neumasport");   // upgrade {1, after 5, 3000, v2 0.20}
    CHECK_EQ(CardMaxLevel(*neu), 2);
    CHECK(CardFxV(*neu, 1) == 0.10); CHECK(CardFxV(*neu, 2) == 0.20);
    const CardDef* heli = CardById("card_helicam");     // no upgrade
    CHECK_EQ(CardMaxLevel(*heli), 1);

    SignedCard sc; sc.card_id = "card_neumasport"; sc.level = 1; sc.races_active = 3; sc.invested = 2500;
    CardUpgradeInfo up;
    CHECK(CardUpgradeNext(sc, up));
    CHECK_EQ(up.to_level, 2); CHECK_EQ(up.cost, 3000); CHECK_EQ(up.need, 5); CHECK_EQ(up.have, 3); CHECK(!up.ready);
    sc.races_active = 7;
    CHECK(CardUpgradeNext(sc, up)); CHECK(up.ready); CHECK_EQ(up.have, 5);   // have clamps to need
    sc.level = 2;
    CHECK(!CardUpgradeNext(sc, up));                    // maxed out

    CHECK_EQ(CardSellValue(sc), 1000);                  // 2500*0.40 = 1000 (already a multiple of 10)
    sc.invested = 5500; CHECK_EQ(CardSellValue(sc), 2200);
    sc.invested = 2512; CHECK_EQ(CardSellValue(sc), 1000);   // round(1004.8/10)*10 = 1000

    std::vector<SignedCard> owned;
    SignedCard doble; doble.card_id = "card_doble"; doble.slot = -1; owned.push_back(doble);
    CHECK(!CardSpecialActive(owned, "shop.extra_buy"));      // on the bench does NOT count
    owned[0].slot = 0;
    CHECK(CardSpecialActive(owned, "shop.extra_buy"));
    CHECK_EQ(CardShopMaxBuys(owned), 2);                     // 1 base + extra_buy
    owned[0].slot = -1;
    CHECK_EQ(CardShopMaxBuys(owned), 1);

    SignedCard scout; scout.card_id = "card_scout21"; scout.slot = 0; owned.push_back(scout);
    CHECK_EQ(CardShopOfferCount(owned), 4);                  // 3 + extra_offer

    std::vector<SignedCard> none;
    CHECK_EQ(CardShopRerollCost(0, none), 1200);
    CHECK_EQ(CardShopRerollCost(1, none), 2400);
    CHECK_EQ(CardShopRerollCost(2, none), 4800);
    SignedCard box; box.card_id = "card_boxesco"; box.slot = 0;
    std::vector<SignedCard> freeR{ box };
    CHECK_EQ(CardShopRerollCost(0, freeR), 0);               // first reroll is free
    CHECK_EQ(CardShopRerollCost(1, freeR), 1200);            // the 2nd costs the same as the 1st paid one
    CHECK_EQ(CardShopRerollCost(2, freeR), 2400);

    CHECK_EQ(CardSlotsUnlocked(1), 2); CHECK_EQ(CardSlotsUnlocked(3), 3);
    CHECK_EQ(CardSlotsUnlocked(7), 6);
    CHECK_EQ(CardSlotsUnlocked(0), 2); CHECK_EQ(CardSlotsUnlocked(99), 6);   // clamp
}

static career::SignedCard mkCard(const char* id, int slot) {
    career::SignedCard sc; sc.card_id = id; sc.slot = slot;
    const career::CardDef* d = career::CardById(id);
    if (d) { sc.invested = career::CardCost(*d);
             if (d->life_kind == career::CARD_LIFE_RACES) sc.races_left = d->life_n;
             if (d->life_kind == career::CARD_LIFE_USES)  sc.uses_left  = d->life_n; }
    return sc;
}

static void test_cards_settle() {
    using namespace career;
    CardFlags f{}; f.win = f.podium = f.top8 = f.top10 = f.clean = true;

    // 1) additive -> multiplicative: volt (podium +2500) + helicam (top8 x2) on a 10000 prize
    {
        std::vector<SignedCard> cs{ mkCard("card_volt", 0), mkCard("card_helicam", 1) };
        CardCosts cc{};                                       // no costs
        auto rep = CardsSettle(cs, f, 10000, cc);
        CHECK_EQ(rep.bonus, 2500);
        CHECK(rep.mult == 2.0);
        CHECK_EQ(rep.prize_base, 10000);                      // echoes the received prizeBase
        CHECK_EQ(rep.prize_final, 25000);                     // (10000+2500)*2
        CHECK_EQ(rep.credits_delta, 15000);                   // delta over the base prize
        CHECK_EQ((int)cs.size(), 2);
        CHECK_EQ(cs[1].uses_left, 2);                         // helicam consumed 1 use (it triggered)
        CHECK_EQ(cs[0].races_left, 7);                        // volt ticked down 1 race
        CHECK_EQ(cs[0].races_active, 1);
    }
    // 2) capped, never-negative discounts: transair(0.60)+horizonte(0.25)+chicane(0.25) trips -> cap 0.75.
    // 0.7.0 (): it was stratos+transair+chicane; Stratos now carries a flat amount per race and muddied the saving.
    {
        std::vector<SignedCard> cs{ mkCard("card_horizonte", 0), mkCard("card_transair", 1), mkCard("card_chicane", 2) };
        CardCosts cc{}; cc.travel = 1000;
        auto rep = CardsSettle(cs, f, 0, cc);
        CHECK_EQ((int)rep.costs.size(), 1);
        CHECK(rep.costs[0].key == "travel");
        CHECK(rep.costs[0].disc == 0.75);                     // 1.25 capped to 0.75
        CHECK_EQ(rep.costs[0].final_, 250);
        CHECK_EQ(rep.credits_delta, 750);                     // savings
    }
    // 2b) the RENTAL discount is reflected in rent_base/rent_final (it doesn't travel through costs[])
    {
        std::vector<SignedCard> cs{ mkCard("card_pistasegura", 0) };   // rent -0.30
        CardCosts cc{}; cc.rent = 7000;
        auto rep = CardsSettle(cs, f, 0, cc);
        CHECK_EQ(rep.rent_base, 7000);
        CHECK(rep.rent_disc == 0.30);
        CHECK_EQ(rep.rent_final, 4900);                       // 7000*0.70
        CHECK_EQ(rep.credits_delta, 2100);                    // rental savings
    }
    // Residual fix (factory-seat gate, cost-parity pass 2, career_overlay.cpp): bucket goes to ZERO cost
    // (the overlay now leaves CardCosts.tyres/fuel at 0 when Settle did NOT charge for the car -- factorySeat, rep.costs
    // <= 0) must not generate a row OR a saving even with an active cost.tyres card (card_neumasport, "passive"
    // always fires). Pure engine invariant this gate depends on: "only entries with base > 0"
    // (career_cards.cpp ~191).
    {
        std::vector<SignedCard> cs{ mkCard("card_neumasport", 0) };  // COST_TYRES 0.10, trigger "passive"
        CardCosts cc{}; cc.tyres = 0;                          // factory seat: Settle did not charge for the car
        auto rep = CardsSettle(cs, f, 0, cc);
        CHECK_EQ((int)rep.costs.size(), 0);                   // no "tyres" row (base<=0 -> bucket skipped)
        CHECK_EQ(rep.credits_delta, 150);                     // 0.7.0 (): only the card's flat 150, no saving
    }
    // 3) frozen bench: Volt on the bench doesn't trigger, doesn't tick
    {
        std::vector<SignedCard> cs{ mkCard("card_volt", -1) };
        CardCosts cc{};
        auto rep = CardsSettle(cs, f, 10000, cc);
        CHECK_EQ(rep.bonus, 0);
        CHECK_EQ(cs[0].races_left, 8);
        CHECK_EQ(cs[0].races_active, 0);
    }
    // 4) uses are NOT consumed if it doesn't trigger: Helicam active but no top-8 finish
    {
        CardFlags mid{}; mid.top10 = true;                    // P9: neither a podium nor a top-8
        std::vector<SignedCard> cs{ mkCard("card_helicam", 0) };
        CardCosts cc{};
        auto rep = CardsSettle(cs, mid, 10000, cc);
        CHECK(rep.mult == 1.0);
        CHECK_EQ(cs[0].uses_left, 3);
    }
    // 5) lifetime expiry: Volt's last race -> expires and drops out of the vector
    {
        std::vector<SignedCard> cs{ mkCard("card_volt", 0) };
        cs[0].races_left = 1;
        CardCosts cc{};
        auto rep = CardsSettle(cs, f, 0, cc);
        CHECK_EQ((int)rep.expired.size(), 1);
        CHECK(rep.expired[0] == "card_volt");
        CHECK(cs.empty());
    }
    // 6) dnf_fine clause: Transair active + DNF -> 1500 fine
    {
        CardFlags dnf{}; dnf.dnf = true;
        std::vector<SignedCard> cs{ mkCard("card_transair", 0) };
        CardCosts cc{};
        auto rep = CardsSettle(cs, dnf, 0, cc);
        CHECK_EQ(rep.fines_total, 1500);
        CHECK_EQ(rep.credits_delta, -1500);
    }
    // 7) notop10_lose clause: Tribuna, 3 misses in a row -> lost; a top-10 resets it
    {
        CardFlags miss{};                                     // no top-10
        CardFlags hit{};  hit.top10 = true;
        std::vector<SignedCard> cs{ mkCard("card_tribuna", 0) };
        CardCosts cc{};
        CardsSettle(cs, miss, 0, cc); CHECK_EQ(cs[0].clause_miss, 1);
        CardsSettle(cs, hit,  0, cc); CHECK_EQ(cs[0].clause_miss, 0);   // reset
        CardsSettle(cs, miss, 0, cc);
        CardsSettle(cs, miss, 0, cc);
        auto rep = CardsSettle(cs, miss, 0, cc);
        CHECK_EQ((int)rep.lost.size(), 1);
        CHECK(cs.empty());
    }
    // 8) xp mult: Vector active -> xp_mult 1.25
    {
        std::vector<SignedCard> cs{ mkCard("card_vector", 0) };
        CardCosts cc{};
        auto rep = CardsSettle(cs, f, 0, cc);
        CHECK(rep.xp_mult == 1.25);
    }
}

// Cards v2 plumbing: EXTRA effects + rep.mult hook + llround rounding on negatives.
// CARD_DEFS is a mutable global vector -- synthetic "zz_test_*" cards get pushed onto the end and trimmed
// with resize() (isolation: doesn't interfere with test_card_catalog_integrity/test_card_shop_draw if that one
// ran before or after it in the same process).
static void test_card_extras() {
    using namespace career;
    size_t origSize = CARD_DEFS.size();

    // Dual risk/reward card: +20% prize (primary effect) but REP x0.8 and a flat -500/race fee (extras).
    CardDef dual;
    dual.id = "zz_test_dual"; dual.name = "Test Dual"; dual.tag_es = "t"; dual.tag_en = "t";
    dual.rarity = 0; dual.life_kind = CARD_LIFE_PERM; dual.life_n = 0; dual.trigger = "passive";
    dual.hook = CARD_HOOK_PRIZE_MULT; dual.v = 1.2;
    dual.extras = { CardFx{ CARD_HOOK_REP_MULT, 0.8 }, CardFx{ CARD_HOOK_INCOME_BONUS, -500.0 } };
    CARD_DEFS.push_back(dual);

    // negative llround: -2.5 must round to -3 (the (long)(x+0.5) bug truncated it to -2).
    CardDef fee1;
    fee1.id = "zz_test_fee1"; fee1.name = "Fee1"; fee1.tag_es = "t"; fee1.tag_en = "t";
    fee1.rarity = 0; fee1.life_kind = CARD_LIFE_PERM; fee1.life_n = 0; fee1.trigger = "passive";
    fee1.hook = CARD_HOOK_INCOME_BONUS; fee1.v = -2.5;
    CARD_DEFS.push_back(fee1);

    // fee bigger than the prize -> prize_final never drops below 0 (you lose at most the base prize).
    CardDef fee2;
    fee2.id = "zz_test_fee2"; fee2.name = "Fee2"; fee2.tag_es = "t"; fee2.tag_en = "t";
    fee2.rarity = 0; fee2.life_kind = CARD_LIFE_PERM; fee2.life_n = 0; fee2.trigger = "passive";
    fee2.hook = CARD_HOOK_INCOME_BONUS; fee2.v = -1500.0;
    CARD_DEFS.push_back(fee2);

    {
        std::vector<SignedCard> cs{ mkCard("zz_test_dual", 0) };
        CardFlags f{}; CardCosts cc{};
        auto rep = CardsSettle(cs, f, 1000, cc);
        CHECK(rep.mult == 1.2);
        CHECK(rep.rep_mult == 0.8);
        CHECK_EQ(rep.bonus, -500);
        CHECK_EQ(rep.prize_final, 600);      // round((1000-500)*1.2)
        CHECK_EQ(rep.credits_delta, -400);
        CHECK_EQ((int)rep.fired.size(), 1);
        CHECK(rep.fired[0] == "zz_test_dual");
    }
    {
        std::vector<SignedCard> cs{ mkCard("zz_test_fee1", 0) };
        CardFlags f{}; CardCosts cc{};
        auto rep = CardsSettle(cs, f, 100, cc);
        CHECK_EQ(rep.bonus, -3);             // llround(-2.5) == -3, NOT -2
        CHECK_EQ(rep.prize_final, 97);       // (100-3)*1.0
    }
    {
        std::vector<SignedCard> cs{ mkCard("zz_test_fee2", 0) };
        CardFlags f{}; CardCosts cc{};
        auto rep = CardsSettle(cs, f, 1000, cc);
        CHECK_EQ(rep.prize_final, 0);        // floor: (1000-1500) < 0 -> 0
        CHECK_EQ(rep.credits_delta, -1000);  // capped: you lose at most the base prize
    }
    CARD_DEFS.resize(origSize);
}

static void test_card_flags_from() {
    using namespace career;
    RaceResult r; r.pos = 1; r.field = 20; r.finished = true; r.clean = true;
    RaceTelemetry tel; tel.maxTyreWear = 0.30f; tel.maxComponentDamage = 0.05f; tel.fuelRemainFrac = 0.20f;
    CardFlags fl = CardFlagsFrom(r, tel, false);
    CHECK(fl.win && fl.podium && fl.top8 && fl.top10 && fl.clean);
    CHECK(fl.damagefree && fl.tyrewear && fl.fueluse);
    CHECK(!fl.endur && !fl.dnf);
    r.finished = false;
    fl = CardFlagsFrom(r, tel, true);
    CHECK(fl.dnf && !fl.win && !fl.endur);                    // endur requires finishing the race
    r.finished = true; r.pos = 9;
    fl = CardFlagsFrom(r, tel, true);
    CHECK(!fl.top8 && fl.top10 && fl.endur);
}

static void test_card_shop_draw() {
    using namespace career;
    std::vector<SignedCard> none;
    auto a = CardShopDraw(none, 3, "r01:5:0", 3);
    auto b = CardShopDraw(none, 3, "r01:5:0", 3);
    CHECK_EQ((int)a.size(), 3);
    CHECK(a == b);                                        // deterministic
    auto c = CardShopDraw(none, 3, "r01:5:1", 3);
    CHECK(a != c || true);                                // a different seed may differ (don't assert a hard inequality)
    // no duplicates within the offer
    CHECK(a[0] != a[1] && a[1] != a[2] && a[0] != a[2]);
    // all resolve in the catalog
    for (const auto& id : a) CHECK(CardById(id) != nullptr);
    // excludes owned cards: owning all 3 offered -> none reappears with the SAME seed
    std::vector<SignedCard> owned;
    for (const auto& id : a) { SignedCard sc; sc.card_id = id; owned.push_back(sc); }
    auto d = CardShopDraw(owned, 3, "r01:5:0", 3);
    for (const auto& id : d) for (const auto& sc : owned) CHECK(id != sc.card_id);
    // phase 1: never international/elite (weights 0)
    for (int k = 0; k < 20; k++) {
        auto o = CardShopDraw(none, 1, std::string("seed") + std::to_string(k), 3);
        for (const auto& id : o) CHECK(CardById(id)->rarity <= 2);
    }
    // pool exhausted: owning everything, the offer comes back empty
    std::vector<SignedCard> all;
    for (const auto& def : CARD_DEFS) { SignedCard sc; sc.card_id = def.id; all.push_back(sc); }
    CHECK(CardShopDraw(all, 4, "x:1:0", 3).empty());
}

static void test_card_catalog_integrity() {
    using namespace career;
    CHECK_EQ((int)CARD_DEFS.size(), 100);   // Catalog v2: 27 v1 cards + 73 v2 cards
    static const char* kTrig[] = { "passive","win","podium","top8","clean","damagefree","tyrewear","fueluse","endur" };
    static const char* kSpecial[] = { "shop.free_reroll","shop.extra_offer","shop.extra_buy","market.offer_quality","nego.leverage" };
    int perRarity[5] = { 0,0,0,0,0 };
    for (const auto& c : CARD_DEFS) {
        CHECK(!c.id.empty()); CHECK(!c.name.empty());
        CHECK(!c.tag_es.empty()); CHECK(!c.tag_en.empty());
        CHECK(c.rarity >= 0 && c.rarity <= 4); perRarity[c.rarity]++;
        CHECK(CardCost(c) > 0);
        CHECK(c.hook >= 0 && c.hook < CARD_HOOK_COUNT);
        bool trigOk = false; for (auto* t : kTrig) if (c.trigger == t) trigOk = true;
        CHECK(trigOk);
        if (c.life_kind != CARD_LIFE_PERM) CHECK(c.life_n > 0);
        if (c.hook == CARD_HOOK_SPECIAL) {
            bool spOk = false; for (auto* s : kSpecial) if (c.special_id == s) spOk = true;
            CHECK(spOk); CHECK(!c.special_es.empty()); CHECK(!c.special_en.empty());
        } else {
            CHECK(c.v > 0.0); CHECK(c.special_id.empty());
        }
        if (c.upgrade.levels > 0) { CHECK(c.upgrade.after > 0); CHECK(c.upgrade.cost > 0); CHECK(c.upgrade.v2 > 0.0); }
        // Catalog v2 invariants -- replaces v1's "xp.mult v>=1": now a multiplier for
        // REP/XP/prize can drop below 1 (the counterweight of a dual card), so the bound becomes a RANGE
        // (0,3] instead of a floor at 1. cost.* still triggers ONLY on "passive" (a discount can't depend
        // on a result); this applies EQUALLY to the main effect and to every extra (Catalog v2's "cost-hooks only
        // on the passive trigger, main effect and extras"). Every card WITH extras needs at least one
        // POSITIVE effect (otherwise it wouldn't be a card -- it would just be a penalty) in its main effect or extras.
        auto isCostHook = [](int h) {
            return h == CARD_HOOK_COST_TYRES || h == CARD_HOOK_COST_FUEL || h == CARD_HOOK_COST_TRAVEL
                || h == CARD_HOOK_COST_ENTRY || h == CARD_HOOK_COST_RENT;
        };
        auto isMultHook = [](int h) {
            return h == CARD_HOOK_PRIZE_MULT || h == CARD_HOOK_XP_MULT || h == CARD_HOOK_REP_MULT;
        };
        auto isPositive = [&](int h, double v) {
            if (h == CARD_HOOK_INCOME_BONUS) return v > 0.0;
            if (isCostHook(h))                return v > 0.0;   // discount > 0 = positive for the player
            if (isMultHook(h))                return v > 1.0;
            return h == CARD_HOOK_SPECIAL;                      // the 5 existing specials are always positive
        };
        CHECK(c.extras.size() <= 2);
        if (isCostHook(c.hook)) CHECK(c.trigger == "passive");
        if (isMultHook(c.hook)) {
            CHECK(c.v > 0.0 && c.v <= 3.0);
            if (c.upgrade.levels > 0) {
                CHECK(c.upgrade.v2 > 0.0 && c.upgrade.v2 <= 3.0);
                if (c.upgrade.levels > 1) CHECK(c.upgrade.v3 > 0.0 && c.upgrade.v3 <= 3.0);
            }
        }
        bool anyPositive = isPositive(c.hook, c.v);
        for (const auto& e : c.extras) {
            CHECK(e.hook >= 0 && e.hook < CARD_HOOK_COUNT);
            if (isCostHook(e.hook)) CHECK(c.trigger == "passive");
            if (isMultHook(e.hook)) CHECK(e.v > 0.0 && e.v <= 3.0);
            if (isPositive(e.hook, e.v)) anyPositive = true;
        }
        if (!c.extras.empty()) CHECK(anyPositive);
        CHECK(CardById(c.id) == &c);            // unique id + lookup resolves
    }
    CHECK_EQ(perRarity[0], 30); CHECK_EQ(perRarity[1], 25); CHECK_EQ(perRarity[2], 20);
    CHECK_EQ(perRarity[3], 15); CHECK_EQ(perRarity[4], 10);
    CHECK(CardById("no_such_card") == nullptr);
}

// Sponsor cards: world specials. market.offer_quality bumps the level fed to market::OfferTerms
// by +1 (monotone: same rating/kind/coverage, one level higher -> per_race >= before). nego.leverage sums a flat
// leverage_bonus onto career::NegoLeverageGive's raw give (+10 if the card is SLOTTED, wired at the overlay).
static void test_card_world_specials() {
    using namespace market;
    using namespace career;
    OfferTermsOut t0 = OfferTerms(1200.0, 2, 0, 0.5);
    OfferTermsOut t1 = OfferTerms(1200.0, 3, 0, 0.5);
    CHECK(t1.per_race >= t0.per_race);

    double g0 = NegoLeverageGive(0.6, 1);
    double g1 = NegoLeverageGive(0.6, 1, 10);
    CHECK(g1 == g0 + 10.0);

    // NegoBaseMargin forwards leverage_bonus to NegoLeverageGive too (the actual overlay call site: query.negotiate
    // reads v.baseMargin from NegoBaseMargin, not NegoLeverageGive directly).
    int m0 = NegoBaseMargin(0.6, 1, 1.0);
    int m1 = NegoBaseMargin(0.6, 1, 1.0, 10);
    CHECK(m1 >= m0);
}

// Sponsor cards: anti-inflation guard — 3 simulated seasons WITH vs WITHOUT
// cards (greedy policy: buys the first affordable offer in each post-race shop). Cards
// must ADD VALUE (withCards > without) but NOT multiply the economy (coarse bound withCards < without*3
// + 500000, see career_simrunner.cpp::SimRunCredits for the self-contained loop and the CardFlags mapping).
static void test_cards_econ_guard() {
    using namespace career;
    long withCards = 0, without = 0;
    SimRunCredits(3, /*useCards=*/true,  &withCards);
    SimRunCredits(3, /*useCards=*/false, &without);
    // determinism: repeating the same call gives the same total (no time/clock RNG in the loop)
    long withCards2 = 0;
    SimRunCredits(3, /*useCards=*/true, &withCards2);
    CHECK_EQ(withCards, withCards2);
    CHECK(withCards > without);                          // the cards add value...
    CHECK(withCards < without * 3 + 500000);              // ...but don't multiply the economy by x3

    // 19/09 (tester: +15 M in ONE race): the WORST possible stack. All slots of the highest phase filled
    // with the biggest prize multipliers in the catalog (at their maximum level) and a race that triggers
    // them all. With diminishing stacking the factor cannot exceed 1 + mejor_subida / (1 − DECAY), however many
    // cards pile up; chained it would have been the product of all of them.
    {
        const int slots = CardSlotsUnlocked(7);
        std::vector<std::pair<double, std::string>> mults;   // (v at its maximum level, id)
        for (const auto& d : CARD_DEFS) {
            if (d.hook != CARD_HOOK_PRIZE_MULT) continue;
            const int top = 1 + (d.upgrade.levels > 0 ? d.upgrade.levels : 0);
            mults.push_back({ CardFxV(d, top), d.id });
        }
        std::sort(mults.begin(), mults.end(), [](const std::pair<double, std::string>& a,
                                                 const std::pair<double, std::string>& b) { return a.first > b.first; });
        CHECK((int)mults.size() >= slots);
        std::vector<SignedCard> cs;
        double encadenado = 1.0;
        for (int i = 0; i < slots && i < (int)mults.size(); i++) {
            SignedCard sc = mkCard(mults[i].second.c_str(), i);
            const CardDef* d = CardById(mults[i].second);
            sc.level = 1 + (d && d->upgrade.levels > 0 ? d->upgrade.levels : 0);
            cs.push_back(sc);
            encadenado *= mults[i].first;
        }
        CardFlags todo{};
        todo.win = todo.podium = todo.top8 = todo.top10 = todo.clean = true;
        todo.damagefree = todo.tyrewear = todo.fueluse = todo.endur = true;
        const long W = 226600;
        CardCosts cc{};
        const CardsSettleReport rep = CardsSettle(cs, todo, W, cc);
        const double mejor = mults.empty() ? 0.0 : mults[0].first - 1.0;
        const double techo = 1.0 + mejor / (1.0 - bal::CARD_PRIZE_STACK_DECAY);
        CHECK(rep.mult <= techo + 1e-9);                                  // the factor has a natural ceiling
        CHECK(rep.prize_final <= (long)llround((double)W * techo) + 1);
        CHECK(rep.prize_final < (long)llround((double)W * encadenado)); // ...and stays far below the product
        printf("  [cartas] peor apilado: %d cartas de premio, factor %.4f (encadenadas habrían sido x%.1f) -> %ld sobre %ld\n",
               (int)cs.size(), rep.mult, encadenado, rep.prize_final, W);
    }
}

// 19/09 (tester: +15 M in ONE race, 226.600 × 2,5 × 1,6 × 3 × 2 × 2,8 = ×67). Josh's decision: prize
// multipliers stack ORGANICALLY, with diminishing returns and no hard cap. They are sorted
// by their increment (v − 1) from largest to smallest; the best counts in full, the next half, the next a
// quarter... A single card pays what it prints. Discounts (v < 1) keep multiplying. And each line of the
// money panel is what THAT card contributed: the sum matches the final prize exactly.
static void test_cards_prize_mult_stack() {
    using namespace career;
    CardFlags gana{}; gana.win = gana.podium = gana.top8 = gana.top10 = gana.clean = true;
    CardCosts cc{};
    const long W = 226600;
    auto cerca = [](long a, long b) { return labs(a - b) <= 1; };
    auto lineaDe = [](const CardsSettleReport& r, const char* id) -> long {
        for (const auto& in : r.income) if (in.id == id) return in.amount;
        return -1;
    };

    // (1) the FIVE real cards of the report, all triggering on a win
    { struct Esperada { const char* id; double v; } cinco[] = {
          { "card_petardo", 2.5 }, { "card_apexcrown", 1.6 }, { "card_everest", 3.0 },
          { "card_helicam", 2.0 }, { "card_vegasgrand", 2.8 } };
      std::vector<SignedCard> cs;
      for (int i = 0; i < 5; i++) {
          const CardDef* d = CardById(cinco[i].id);
          CHECK(d != nullptr);
          if (d) { CHECK(d->hook == CARD_HOOK_PRIZE_MULT); CHECK(fabs(d->v - cinco[i].v) < 1e-12); }
          cs.push_back(mkCard(cinco[i].id, i));
      }
      const CardsSettleReport rep = CardsSettle(cs, gana, W, cc);
      // increments 2 · 1,8 · 1,5 · 1,0 · 0,6 -> 2 + 0,9 + 0,375 + 0,125 + 0,0375 = 3,4375 -> ×4,4375 (was ×67,2)
      CHECK(fabs(rep.mult - 4.4375) < 1e-9);
      CHECK(cerca(rep.prize_final, 1005538));           // 226.600 × 4,4375 = 1.005.537,5 (before 15.227.520)
      long suma = 0;
      for (const auto& in : rep.income) suma += in.amount;
      CHECK_EQ(suma, rep.prize_final - rep.prize_base); // the lines add up EXACTLY to the final prize
      CHECK_EQ(rep.credits_delta, rep.prize_final - W);
      // each line is its real contribution, in order of increment
      CHECK_EQ(lineaDe(rep, "card_everest"), 453200L);  // ×3 in full:        226.600 × 2
      CHECK(cerca(lineaDe(rep, "card_vegasgrand"), 203940));   // ×2,8 at half: 226.600 × 0,9
      CHECK(cerca(lineaDe(rep, "card_petardo"), 84975));       // ×2,5 at a quarter
      CHECK(cerca(lineaDe(rep, "card_helicam"), 28325));       // ×2 at an eighth
      CHECK(cerca(lineaDe(rep, "card_apexcrown"), 8498));      // ×1,6 at a sixteenth
    }

    // (2) a SINGLE card pays exactly what it prints: all the prize ones in the catalog, against the usual
    // calculation (base × v rounded)
    { int vistas = 0;
      for (const auto& d : CARD_DEFS) {
          if (d.hook != CARD_HOOK_PRIZE_MULT || !d.extras.empty()) continue;
          CardFlags todo = gana; todo.damagefree = todo.tyrewear = todo.fueluse = todo.endur = true;
          std::vector<SignedCard> cs{ mkCard(d.id.c_str(), 0) };
          const CardsSettleReport rep = CardsSettle(cs, todo, W, cc);
          CHECK(rep.mult == d.v);
          CHECK_EQ(rep.prize_final, (long)llround((double)W * d.v));
          CHECK_EQ((int)rep.income.size(), 1);
          if (!rep.income.empty()) CHECK_EQ(rep.income[0].amount, rep.prize_final - W);
          vistas++;
      }
      CHECK(vistas >= 10); }

    // (3) discounts and fees: the −900 fee card from the report (DataMine) shows −900, not −899, and a prize
    // cut (Couture ×0,70) subtracts what it subtracts. Everything matches the total.
    { std::vector<SignedCard> cs{ mkCard("card_datamine", 0), mkCard("card_couture", 1), mkCard("card_everest", 2) };
      const CardsSettleReport rep = CardsSettle(cs, gana, 10000, cc);
      CHECK_EQ(lineaDe(rep, "card_datamine"), -900L);
      // (10.000 − 900) × 3 × 0,70 = 19.110: ×3 contributes +18.200, the ×0,70 removes 8.190
      CHECK_EQ(rep.prize_final, 19110L);
      long subida = 0, recorte = 0;
      for (const auto& in : rep.income) {
          if (in.id == "card_everest") subida = in.amount;
          if (in.id == "card_couture" && in.mult) recorte = in.amount;
      }
      CHECK_EQ(subida, 18200L);
      CHECK_EQ(recorte, -8190L);
      long suma = 0;
      for (const auto& in : rep.income) suma += in.amount;
      CHECK_EQ(suma, rep.prize_final - rep.prize_base);
      CHECK(fabs(rep.mult - 3.0 * 0.70) < 1e-12); }

    // (4) floor at 0: a fee larger than the prize only removes what there was; the increases no longer have anything to pull from
    { std::vector<SignedCard> cs{ mkCard("card_datamine", 0), mkCard("card_everest", 1) };
      const CardsSettleReport rep = CardsSettle(cs, gana, 500, cc);
      CHECK_EQ(rep.prize_final, 0L);
      CHECK_EQ(lineaDe(rep, "card_datamine"), -500L);
      CHECK_EQ(lineaDe(rep, "card_everest"), 0L);
      CHECK_EQ(rep.credits_delta, -500L); }
}

// RED-scaffold tests for the objective-sponsor catalog/gates/payout — test_sponsor_
// objective_eval / test_sponsor_payout_once / test_sponsor_announce_mail_dedup / test_sponsor_livery_capacity /
// test_sponsor_status_derive / test_sponsor_solvency_gate / test_sponsor_start_from_zero /
// test_sponsor_catalog_integrity — are RETIRED (they exercised career_sponsor.{h,cpp} symbols, all deleted).
// test_settle_sponsor_payout_in_net SURVIVES below: it only exercises the general career::Settle/SettleReport
// plumbing (sponsor_payout as a distinct additive term), unrelated to the deleted catalog.

// The thematic fixed payout is carried in a DISTINCT SettleReport.sponsor_payout field
// summed into credits_delta in the PURE engine. Asserts the displayed MONEY lines sum to net.
// the old REP-tier retainer (s.sponsor) is GONE — sponsor_payout (the cards' thematic payout) is
// now the ONLY sponsor income term, so this test also pins that a settle brings NO sponsor money on its own.
static void test_settle_sponsor_payout_in_net() {
    using namespace career;
    CareerProgress prog;
    RaceResult r; r.pos = 3; r.field = 20; r.finished = true; r.clean = true; r.race_phase = 1;
    // Settle with no payout: net = prize + clean_bonus + salary + deal - entry - costs + coverage.
    SettleReport base = Settle(prog, r, /*winnerPrize=*/40000, /*floorPrize=*/1000,
                               /*rented=*/false, /*rentPct=*/0, /*carValue=*/50000);
    CHECK_EQ(base.sponsor_payout, 0L);   // no thematic payout was set -> additive default 0
    // The pure net invariant holds WITHOUT the payout (additive 0 leaves old behavior unchanged).
    long expectBase = base.prize + base.clean_bonus + base.salary + base.deal_salary
                    - base.entry - base.costs + base.coverage + base.sponsor_payout;
    CHECK_EQ(base.credits_delta, expectBase);
    // Now set a DISTINCT thematic payout (the overlay does this post-Settle) and re-derive net: the payout is a
    // SEPARATE term added on top.
    SettleReport rep = base;
    rep.sponsor_payout = 38000;     // a tier-2 podium payout, say
    rep.credits_delta  = rep.prize + rep.clean_bonus + rep.salary + rep.deal_salary
                       - rep.entry - rep.costs + rep.coverage + rep.sponsor_payout;
    CHECK_EQ(rep.credits_delta, expectBase + 38000);       // displayed MONEY lines sum to net, payout included
}

// 0.7.0: Ceramik Coats cost 8.000 and paid at most
// 5.100 winning it three times. This test measures ALL the cards against their maximum realistic payout and fails if any
// does not earn money in its best case, unless it is in CARD_ROI_BY_DESIGN with its reason.
//
// The best realistic case, with the real settle (CardsSettle) and the card alone in a slot:
//  Reference phase = where the shop draws that rarity with the most weight (CARD_WEIGHTS_BY_PHASE; tie -> the
//    lowest phase). Local 1, regional 2, national 5, international 7, elite 7.
//  Economy of that phase = medians of docs/ams2_series_econ.psv (winner's prize, rent, car
//    price); entry = ENTRY_BY_PHASE; travel = the intercontinental leg (the most expensive, the best case for a
//    travel discount); tyres and fuel = OwnedRaceCosts of the median car at COST_REF_LAPS.
//  Everything goes right in every race: you win, clean, no damage, tyres and fuel looked after, and the race
//    counts as endurance. No fines or clauses.
//  It is tested renting and with an owned car, and without upgrading or upgrading as soon as possible; the best rules.
//  Life: those of races or uses, until they expire. The permanent ones, two seasons (kPermHorizon = 20
//    races; the median season of series.psv has 10 rounds). A permanent card that does not pay for itself in two
//    perfect seasons in the phase where it appears most is a trap even if in theory it pays off some day.


// ===================== RED Nyquist scaffolds (Wave 0) =====================
// Team economy and the living seat market. Each asserts the FINAL contract of a
// target behavior via the now-declared pure signatures (frozen ahead of time) so the harness
// COMPILES+LINKS and fails at RUNTIME against the RED stubs. The owning slice (named per test) flips
// each one green, following the same pattern as earlier slices. NOTE: the additive SAVE fields + the extended Settle/SettleRound
// SIGNATURES are REAL already — only the economy/seat BODIES are stubbed; the regression guard
// (test_phase41_settle_regression) proves the defaulted signature change is byte-identical.
//   test_coverage_profile_per_type and test_settleround_coverage: implemented in a later slice
//   test_insurance_premium / test_deductible_damage_share and test_qualifier_sink: implemented in a later slice
//   test_travel_legs and test_multicontract_aggregate / test_exclusivity_gate: implemented in a later slice
//   test_car_by_contract and test_seat_model / test_seat_occupancy_save: implemented in a later slice
//   test_open_seat_offers and test_elo_displacement / test_paydriver_seat: implemented in a later slice
//   test_job_security: implemented in a later slice

// REGRESSION GUARD: a bare Settle(...)/SettleRound(...) with NO new args yields the pre-change
// credits_delta (the defaulted signature change is byte-identical). This MUST pass NOW (not RED).
static void test_phase41_settle_regression() {
    using namespace career;
    // Same inputs as test_settle_coverage's baseline -> the known pre-change net (regression anchor).
    CareerProgress prog; prog.frontier_phase = 4; prog.rep = 150;
    RaceResult r; r.pos = 1; r.field = 20; r.finished = true; r.clean = true; r.race_phase = 4;
    SettleReport base = Settle(prog, r, 30000, 8000, true, 22, 30000);
    CHECK_EQ(base.credits_delta, 26900);   // unchanged by the new defaulted deductible/travel/resultBonus params
    CHECK_EQ(base.deductible, 0);
    CHECK_EQ(base.travel, 0);
    CHECK_EQ(base.result_bonus, 0);
    // With the new terms supplied: net shifts by exactly + resultBonus - deductible - travel.
    CareerProgress p2; p2.frontier_phase = 4; p2.rep = 150;
    SettleReport s = Settle(p2, r, 30000, 8000, true, 22, 30000, -1, false, /*coverage=*/0, /*dealSalary=*/0,
                            /*deductible=*/3000, /*travel=*/1500, /*resultBonus=*/4000);
    CHECK_EQ(s.deductible, 3000);
    CHECK_EQ(s.travel, 1500);
    CHECK_EQ(s.result_bonus, 4000);
    CHECK_EQ(s.credits_delta, 26900 + 4000 - 3000 - 1500);   // 26400
}

// Variable per-contract salary: SeriesSalaryAnchor(level) is the credits-per-race
// anchor per series LEVEL (1..7), a compressed geometric curve (bal::SALARY_ANCHOR_BASE/GROWTH). Monotonic
// by level, clamped at the edges, and bounded by bal::SALARY_CAP (the later per-team band is never used here).
static void test_salary_anchor() {
    using namespace career;
    long l1 = SeriesSalaryAnchor(1);
    long l4 = SeriesSalaryAnchor(4);
    long l7 = SeriesSalaryAnchor(7);
    CHECK(l1 > 0);
    CHECK(l4 > l1);                 // monotonic by level (the anchor, before the band)
    CHECK(l7 > l4);
    CHECK_EQ(SeriesSalaryAnchor(0), SeriesSalaryAnchor(1));   // low clamp
    CHECK_EQ(SeriesSalaryAnchor(99), SeriesSalaryAnchor(7));  // high clamp
    CHECK(l7 <= bal::SALARY_CAP);   // within the compressed range
}

// Variable salary: TeamSalaryBand derives a team's multiplier band
// from the field's live ELO (percentile of the team's AVERAGE rating within the field's [worst..best] range ->
// center in [SALARY_TEAM_MIN_CENTER..MAX_CENTER]; band = center ± SALARY_BAND_HALFWIDTH). Fixtures loaded
// EXACTLY like test_seat_model: seat tests load their own PSVs, the runner doesn't do it
// for them. Series: ivory_trophy_7202 (the SAME one test_seat_model proves resolvable with occupants via a
// pinned roster; "onyx_cup_4742" isn't guaranteed in the harness). Adjusted from the original plan:
// agedRatingFor (an EXACT mirror of WeakestIncumbentRating, same file) does NOT read save.driver_ratings —
// it derives the rating from skill(roster)+birth_year+rival_form. Seeding driver_ratings would have no effect
// on TeamSalaryBand; instead we seed save.rival_form (the delta agedRatingFor DOES consult) with
// an extreme offset (±1.0 -> ±700 over the seed band 1200..1900) so the 'strong' team
// ends up deterministically far above the field and 'weak' far below, without depending on the randomness of the
// real PSV skills (which already vary on their own and would make the test flaky).


// Variable salary: SalaryFor resolves the FINAL NUMBER = clamp(anchor(level) *
// position-in-band, FLOOR, CAP). Correction from the original plan: with
// teamLabel="" (the case this test exercises) TeamSalaryBand falls back to resolved=false and returns minMult=maxMult=0
// (only centerMult is meaningful) -- SalaryFor derives the band range from centerMult ± SALARY_BAND_
// HALFWIDTH instead of the raw min/maxMult (also valid for a RESOLVED band: there min=center-HALF/max=center+
// HALF anyway, so it's byte-identical in that case). The draft's LoadTestFixtures() doesn't exist as a
// real helper (same as test_team_salary_band above): each test loads its own PSVs explicitly; in
// this test it isn't even needed -- teamLabel="" never matches any real team_label, so TeamSalaryBand
// ALWAYS falls back to the mid-center (resolved=false) whether the series is loaded or not.
static void test_salary_for() {
    using namespace career;
    SaveData s;   // with no ratings seeded -> TeamSalaryBand falls back to the mid-center (resolved=false) for everyone
    // ordering by level (same team/rating/neutral salaryPct): a higher level pays more
    long lo = SalaryFor("keystone_championship", "", 1, 1500.0, 50, s, 2025);
    long hi = SalaryFor("onyx_cup_4742",        "", 5, 1500.0, 50, s, 2025);
    CHECK(hi > lo);
    CHECK(lo >= bal::SALARY_FLOOR);
    CHECK(hi <= bal::SALARY_CAP);
    // non-monotonicity: L1 with a HIGH band beats L2 with a LOW band (we force the field-rating multipliers).
    // (at the formula level: anchor(1)*maxCenterBand > anchor(2)*minCenterBand with the proposed defaults.)
    long l1top = (long)(SeriesSalaryAnchor(1) * (bal::SALARY_TEAM_MAX_CENTER) + 0.5);
    long l2bot = (long)(SeriesSalaryAnchor(2) * (bal::SALARY_TEAM_MIN_CENTER) + 0.5);
    CHECK(l1top > l2bot);   // documents the non-monotonicity with the chosen constants
    // salaryPct raises the salary within the band (bounded)
    long neutral = SalaryFor("onyx_cup_4742", "", 5, 1500.0, 50, s, 2025);
    long pushed  = SalaryFor("onyx_cup_4742", "", 5, 1500.0, 80, s, 2025);
    CHECK(pushed >= neutral);
}

// Variable salary: heal on load — LoadCareer re-derives per_race for every
// ACTIVE salaried contract (salary_dir>0) to the variable model (SalaryFor), so a legacy save (a flat/
// old per_race figure) gets a coherent number without re-signing. Idempotent (SalaryFor is deterministic: same inputs ->
// same output, so loading twice doesn't move the number again). The test loads the series catalog
// (same idiom as test_seat_model/test_team_salary_band: each test brings its own PSVs, the runner doesn't do it
// for them) so SeriesById("onyx_cup_4742") resolves a real level (NOT hardcoded: it's read from the same SeriesDef
// the heal consults, so the test's 'expected' value and the heal share the same source).
// helper: builds a save with ONE works/factory contract for onyx_cup_4742 with per_race=150000 (a "signed"
// figure deliberately different from what SalaryFor would give). Used by the two freeze-vs-legacy tests.
static void seedSalaryContractSave(const char* path) {
    using namespace career;
    SaveData out;
    out.prog.rating = 1500.0;
    out.contracts.assign(1, Contract{});
    Contract& c = out.contracts[0];
    c.active = true; c.series_id = "onyx_cup_4742"; c.team_id = "";      // empty team -> mid-center band
    c.kind = bal::CONTRACT_WORKS; c.archetype = ARCH_FACTORY_PROGRAM;
    c.per_race = 150000;   // SIGNED figure (flat; != what SalaryFor would give -> the freeze/heal is observable)
    CHECK(SaveCareer(out, path));   // writes the "version <kSaveVersion>" line (v4)
}

// A v4 save (kSaveVersion) does NOT re-derive per_race on reload -> it stays
// FROZEN at the value fixed when signed. Strong witness: SalaryFor would give a DIFFERENT figure (derived != 150000), but
// LoadCareer keeps 150000. Before this fix (heal on every load) rc->per_race would be 'derived' -> this test was RED.


// The salary migration to the variable model is ONE-SHOT LEGACY -> it runs ONLY for saves with
// fileVersion < kSaveVersion. We simulate a legacy save by lowering its version line and verify the heal
// re-derives per_race once.


// ContractCoverageProfile maps a contract kind+archetype onto a per-type profile
// (coverage fractions + salary dir + exclusivity + damage_share). A privateer (self-funded) profile must
// differ from a factory (works) profile. Assert PER-TYPE correctness (each type's fractions +
// each type's Settle net match its DEFINITION), NEVER a cross-type ranking.
static void test_coverage_profile_per_type() {
    using namespace career;
    // the 6 contract types resolve to distinct indices via the archetype->type mapping ---
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_CUSTOMER, ARCH_SELF_FUNDED_ENTRY), 0);  // Self-funded
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_PAY_DRIVER, ARCH_WILDCARD),        1);  // Pay-per-event
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT),     2);  // Co-pay
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_CUSTOMER, ARCH_OPEN_VACANCY),      3);  // Covered/semi-pro
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_WORKS,    ARCH_DIRECT_OFFER),      4);  // Paid-pro
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_WORKS,    ARCH_FACTORY_PROGRAM),   5);  // Factory/works
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_WORKS,    ARCH_ACADEMY_PROMOTION), 4);  // Academy promotion to works -> Paid-pro
    // clamp/safe-degrade: an out-of-range archetype -> privateer type 0
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_WORKS, 99), 0);
    CHECK_EQ(ContractTypeIndex(bal::CONTRACT_WORKS, -1), 0);

    int tSelf = ContractTypeIndex(bal::CONTRACT_CUSTOMER, ARCH_SELF_FUNDED_ENTRY);
    int tFact = ContractTypeIndex(bal::CONTRACT_WORKS,    ARCH_FACTORY_PROGRAM);
    CHECK(tSelf != tFact);
    CoverageProfile self = ContractCoverageProfile(bal::CONTRACT_CUSTOMER, ARCH_SELF_FUNDED_ENTRY);
    CoverageProfile fact = ContractCoverageProfile(bal::CONTRACT_WORKS,    ARCH_FACTORY_PROGRAM);
    // per-type EXACT fractions (read straight from the bal:: rows; privateer 0 vs factory 5) ---
    CHECK_EQ(self.seat_entry_cov,    bal::COVERAGE_SEAT_ENTRY[0]);    // 0.0 — privateer pays everything
    CHECK_EQ(self.consumables_cov,   bal::COVERAGE_CONSUMABLES[0]);   // 0.0
    CHECK_EQ(self.damage_share_base, bal::COVERAGE_DAMAGE_SHARE_BASE[0]); // 1.0 — full deductible
    CHECK_EQ(self.salary_dir,        0);                              // no salary
    CHECK(!self.exclusive);   // self-funded is NOT exclusive (stacks)
    CHECK(self.fixes_car);    // 20/07: any signed contract fixes the team's car (including type 0)
    CHECK_EQ(fact.seat_entry_cov,    bal::COVERAGE_SEAT_ENTRY[5]);    // 1.0 — fully covered
    CHECK_EQ(fact.consumables_cov,   bal::COVERAGE_CONSUMABLES[5]);   // 1.0
    CHECK_EQ(fact.damage_share_base, bal::COVERAGE_DAMAGE_SHARE_BASE[5]); // 0.1 — shielded
    CHECK(fact.salary_dir > 0);                                       // factory pays a salary
    CHECK(fact.exclusive);                                            // exclusive seat
    CHECK(fact.fixes_car);                                            // a factory ("marca") deal fixes the car
    // privateer eats everything, factory shielded (the type DEFINITION, not a ranking claim)
    CHECK(self.damage_share_base > fact.damage_share_base);
    CHECK(fact.seat_entry_cov > self.seat_entry_cov);
    // the copago type carries a finite damage cap; the others are uncapped (per-type definition)
    CoverageProfile copago = ContractCoverageProfile(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT);
    CHECK_EQ(copago.damage_cap, bal::COVERAGE_DAMAGE_CAP[2]);         // 8000
    CHECK_EQ(self.damage_cap,   0);
    CHECK_EQ(fact.damage_cap,   0);

    // PER-TYPE Settle net correctness (assert each type's net matches its DEFINITION) ---
    // Same race (P1/20, clean, phase 4, owned car carValue 30000). For each type, derive coverage from its
    // profile over the per-race car cost (the seat/consumables the team covers) + its salary, and assert the
    // exact net. NO cross-type ranking is asserted — each net is checked against its own definition.
    RaceResult r; r.pos = 1; r.field = 20; r.finished = true; r.clean = true; r.race_phase = 4;
    const long carVal = 30000;
    // type 0 (Self-funded): zero coverage, zero deal salary -> net == the self-funded baseline.
    { CareerProgress p; p.frontier_phase = 4; p.rep = 150;
      SettleReport s = Settle(p, r, 30000, 8000, false, 0, carVal, -1, false,
                              /*coverage=*/0, /*dealSalary=*/0);
      CHECK_EQ(s.coverage, 0);
      CHECK_EQ(s.deal_salary, 0);
      // net = prize + clean_bonus - entry - costs (no coverage, no salary)
      CHECK_EQ(s.credits_delta, s.prize + s.clean_bonus - s.entry - s.costs); }
    // type 5 (Factory): full coverage of (entry+costs) + a per-race salary -> net == baseline + salary + cov.
    { CareerProgress p; p.frontier_phase = 4; p.rep = 150;
      CoverageProfile pf = ContractCoverageProfile(bal::CONTRACT_WORKS, ARCH_FACTORY_PROGRAM);
      long runCost = (long)(carVal * 0.0 + 0.5);   // factorySeat would zero costs; here test the coverage clamp path
      (void)runCost;
      // model the covered seat as: coverage covers the full per-race car cost (consumables) the privateer ate.
      SettleReport sf = Settle(p, r, 30000, 8000, false, 0, carVal, -1, /*factorySeat=*/false,
                               /*coverage=*/999999 /*clamped to entry+costs*/, /*dealSalary=*/bal::COVERAGE_SALARY_BASE[5]);
      CHECK_EQ(sf.coverage, sf.entry + sf.costs);                    // clamped: team covers your full out-of-pocket
      CHECK_EQ(sf.deal_salary, bal::COVERAGE_SALARY_BASE[5]);
      // net = prize + clean_bonus + deal_salary - entry - costs + coverage
      //     = prize + clean_bonus + deal_salary (entry+costs fully offset by coverage)
      CHECK_EQ(sf.credits_delta, sf.prize + sf.clean_bonus + sf.deal_salary); }

    // Presentation facets == the Settle-time profile (presentation == reality) ---
    // DeriveOfferPresentation reads the SAME ContractCoverageProfile fractions -> the per-category covered
    // booleans must agree with the profile bucketed at the display threshold, and the typeLabel must be the
    // ContractTypeIndex. (The facets can never diverge from the economic reality.)
    {
      OfferPresentationFacets pSelf = DeriveOfferPresentation(bal::CONTRACT_CUSTOMER, ARCH_SELF_FUNDED_ENTRY, nullptr);
      OfferPresentationFacets pFact = DeriveOfferPresentation(bal::CONTRACT_WORKS,    ARCH_FACTORY_PROGRAM,   nullptr);
      // typeLabel == ContractTypeIndex (presentation maps the same type the economy uses)
      CHECK_EQ(pSelf.typeLabel, ContractTypeIndex(bal::CONTRACT_CUSTOMER, ARCH_SELF_FUNDED_ENTRY));  // 0
      CHECK_EQ(pFact.typeLabel, ContractTypeIndex(bal::CONTRACT_WORKS,    ARCH_FACTORY_PROGRAM));     // 5
      // privateer (type 0): the team covers NOTHING -> every category reads "you pay"
      CHECK(!pSelf.seatEntryCovered); CHECK(!pSelf.consumablesCovered);
      CHECK(!pSelf.damageCovered);    CHECK(!pSelf.travelCovered);
      CHECK_EQ(pSelf.salaryDir, 0);                                  // no salary
      // factory (type 5): the team covers EVERYTHING -> every category reads "covered"; team pays a salary
      CHECK(pFact.seatEntryCovered);  CHECK(pFact.consumablesCovered);
      CHECK(pFact.damageCovered);     CHECK(pFact.travelCovered);
      CHECK(pFact.salaryDir > 0);
      // the booleans agree with the SAME profile bucketed at the display threshold (presentation == reality)
      CoverageProfile prSelf = ContractCoverageProfile(bal::CONTRACT_CUSTOMER, ARCH_SELF_FUNDED_ENTRY);
      CoverageProfile prFact = ContractCoverageProfile(bal::CONTRACT_WORKS,    ARCH_FACTORY_PROGRAM);
      CHECK_EQ(pSelf.seatEntryCovered, prSelf.seat_entry_cov >= bal::COVERAGE_PRESENT_THRESHOLD);
      CHECK_EQ(pFact.travelCovered,    prFact.travel_cov     >= bal::COVERAGE_PRESENT_THRESHOLD);
      // the exposed raw fractions equal the profile fractions exactly (no terms -> bare profile)
      CHECK_EQ(pSelf.seatEntryFrac, prSelf.seat_entry_cov);
      CHECK_EQ(pFact.damageFrac,    prFact.damage_cov);
    }

    // A more-coverage negotiated package RAISES the shown coverage ---
    // The Copago type (idx 2) has a PARTIAL consumables fraction (0.3 < threshold -> "you pay" at base). A
    // more-coverage package (salaryPct below neutral 50) lifts the shown fractions toward full; a strong
    // more-coverage pick flips consumables to "covered". A neutral package (salaryPct 50) leaves it unchanged;
    // a MORE-salary package (salaryPct > 50) does NOT lower it below the type floor.
    {
      OfferPresentationFacets base = DeriveOfferPresentation(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT, nullptr);
      DealTerms neutral; neutral.salaryPct = 50;                     // neutral 50/50 -> unchanged
      OfferPresentationFacets pNeutral = DeriveOfferPresentation(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT, &neutral);
      CHECK_EQ(pNeutral.consumablesFrac, base.consumablesFrac);     // no lift at neutral
      DealTerms moreCover; moreCover.salaryPct = 0;                  // full "More coverage" pick -> max lift
      OfferPresentationFacets pCover = DeriveOfferPresentation(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT, &moreCover);
      CHECK(pCover.consumablesFrac > base.consumablesFrac);         // the shown coverage was RAISED
      CHECK(pCover.seatEntryFrac   >= base.seatEntryFrac);          // every category raised (or already full)
      DealTerms moreSalary; moreSalary.salaryPct = 100;             // more salary, less coverage -> no lower
      OfferPresentationFacets pSalary = DeriveOfferPresentation(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT, &moreSalary);
      CHECK_EQ(pSalary.consumablesFrac, base.consumablesFrac);      // never below the type floor (display-only)
    }
}

// SettleRound applies a profile-derived coverage end-to-end so a COVERED race nets strictly more
// than a self-funded one (same race, coverage 0 vs >0). The signature now CARRIES coverage; what's still RED
// is the profile that supplies it — here we assert the engine-side contract directly via SettleRound.
static void test_settleround_coverage() {
    using namespace career;
    // self-contained fixture (mirrors test_season_persist) so SettleRound actually runs (a real calendar).
    { FILE* f = fopen("build\\cov_series.psv", "wb");
      fputs("series_id|class_name|display|region|era|profile_id|points_id|rounds|branch_of|level\r\n"
            "covsr|CV|CovS|INT|2024|cov|cp|2||4\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\cov_pts.psv", "wb");
      fputs("points_id|puntos|fl_point|fl_top_n|pole_point|nota\r\ncp|25,18,15|0|0|0|x\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\cov_prof.psv", "wb");
      fputs("profile_id|campos\r\ncov|ai=88-106\r\n", f); fclose(f); }
    { FILE* f = fopen("build\\cov_cal.psv", "wb");
      fputs("series_id|round|track_hash|track_name|fmt|laps|durationMin|hour|weather|note\r\n"
            "covsr|1|123|A|1|20|0|14|0|\r\ncovsr|2|456|B|1|22|0|14|0|\r\n", f); fclose(f); }
    CHECK(LoadSeries("build\\cov_series.psv")); CHECK(LoadSeriesPoints("build\\cov_pts.psv"));
    CHECK(LoadProfiles("build\\cov_prof.psv")); CHECK(LoadSeriesCalendar("build\\cov_cal.psv"));
    std::vector<ClassifiedEntry> cls = { {"AI1","",1,20,true,false,""}, {"Yo","",5,20,true,false,""} };
    RaceResult r; r.pos = 5; r.field = 20; r.finished = true; r.clean = true; r.race_phase = 4;
    // self-funded leg: no coverage threaded.
    CareerProgress p0; p0.frontier_phase = 4; p0.rep = 150;
    SeasonState s0 = StartSeason("covsr", "");
    SettleReport selfNet = SettleRound(s0, p0, r, cls, "", 30000, 8000, true, 22, 30000);
    // covered leg: thread a real coverage (the profile would supply this) -> net must be strictly higher.
    CareerProgress p1; p1.frontier_phase = 4; p1.rep = 150;
    SeasonState s1 = StartSeason("covsr", "");
    SettleReport covNet = SettleRound(s1, p1, r, cls, "", 30000, 8000, true, 22, 30000, -1, false,
                                      /*coverage=*/5000, /*dealSalary=*/0);
    CHECK_EQ(selfNet.coverage, 0);
    CHECK_EQ(covNet.coverage, 5000);                    // SettleRound no longer DROPS coverage (closes that gap)
    CHECK(covNet.credits_delta > selfNet.credits_delta);
    // ENTRY-ONCE GUARD: the covered-vs-self-funded net delta == the coverage exactly. If entry were
    // re-charged when coverage applied, the delta would be coverage minus a double-charged entry (< coverage).
    CHECK_EQ(covNet.credits_delta - selfNet.credits_delta, 5000);
    // result_bonus is ADDED at a qualifying finish (and 0 otherwise) — threaded through SettleRound.
    CareerProgress p2; p2.frontier_phase = 4; p2.rep = 150;
    SeasonState s2 = StartSeason("covsr", "");
    SettleReport bonusNet = SettleRound(s2, p2, r, cls, "", 30000, 8000, true, 22, 30000, -1, false,
                                        /*coverage=*/5000, /*dealSalary=*/0,
                                        /*deductible=*/0, /*travel=*/0, /*resultBonus=*/3000);
    CHECK_EQ(bonusNet.result_bonus, 3000);
    CHECK_EQ(bonusNet.credits_delta - covNet.credits_delta, 3000);   // bonus adds exactly, on top of coverage
    // GREEN: a real ContractCoverageProfile drives the coverage from the contract type (the overlay
    // resolves ContractForSeries -> profile -> coverage at both live Settle sites; here we assert the profile
    // that supplies it is non-degenerate for a covered (copago) type).
    CoverageProfile prof = ContractCoverageProfile(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT);
    CHECK(prof.seat_entry_cov > 0.0);                   // the copago type covers part of the seat/entry
}

// The season insurance premium is priced by phase × type × past-season cleanliness
// (cleaner season -> cheaper), charged ONCE per held contract at rollover (premium_year guard), solvency-gated.
static void test_insurance_premium() {
    using namespace career;
    // tunable bands exist (direction sanity) ---
    CHECK(bal::INSURANCE_PREMIUM_BY_PHASE[3] > bal::INSURANCE_PREMIUM_BY_PHASE[0]);  // higher phase costs more
    CHECK(bal::INSURANCE_CLEAN_MULT_MAX > bal::INSURANCE_CLEAN_MULT_MIN);            // dirty pays more than clean

    // pure helper: priced by phase × type × cleanliness, every magnitude from bal:: (no literal here) ---
    // higher phase -> more expensive (same type, same cleanliness).
    long premLo = InsurancePremiumForContract(/*phase=*/1, /*type=*/0, /*cleanliness=*/70.0);
    long premHi = InsurancePremiumForContract(/*phase=*/4, /*type=*/0, /*cleanliness=*/70.0);
    CHECK(premHi > premLo);
    // dirtier past season -> a HIGHER premium (cleanliness is INVERSE to price).
    long premClean = InsurancePremiumForContract(4, 0, /*cleanliness=*/100.0);
    long premDirty = InsurancePremiumForContract(4, 0, /*cleanliness=*/0.0);
    CHECK(premDirty > premClean);
    // a more-covered type (lower damage_share_base) pays LESS than a privateer for the same phase/cleanliness.
    long premPriv = InsurancePremiumForContract(4, /*type=*/0, 70.0);   // privateer (share base 1.0)
    long premFact = InsurancePremiumForContract(4, /*type=*/5, 70.0);   // factory  (share base 0.1)
    CHECK(premPriv > premFact);
    CHECK(premFact > 0);                                                // mandatory: covered types still pay
    // EXACT magnitude against the named bal:: tunables (no magic number, the formula is the contract).
    {
        double dirty = 1.0 - 70.0/100.0;
        double cm = bal::INSURANCE_CLEAN_MULT_MIN + (bal::INSURANCE_CLEAN_MULT_MAX - bal::INSURANCE_CLEAN_MULT_MIN)*dirty;
        long expect = (long)llround((double)bal::INSURANCE_PREMIUM_BY_PHASE[3] * bal::COVERAGE_DAMAGE_SHARE_BASE[0] * cm);
        CHECK_EQ(premPriv, expect);
    }

    // integration: charged ONCE per held contract at rollover, guarded, solvency-blocked ---
    // a held works contract on falcon_series_9334 (level 5) -> a premium is charged exactly once per season.
    { CareerCalendar cc; cc.year = 2030; CareerProgress prog; prog.credits = 1000000; prog.frontier_phase = 7;
      prog.cleanliness = 60.0;
      SaveData save; save.current_world_year = 2030;
      Contract c; c.series_id = "falcon_series_9334"; c.kind = bal::CONTRACT_WORKS; c.archetype = ARCH_DIRECT_OFFER;
      c.active = true; c.seasons_total = 3; c.seasons_left = 3; c.signed_year = 2030;
      save.contracts.push_back(c);
      // NOTE: NO Enroll here. The premium loop iterates save.contracts directly (independent of cc.enrollments),
      // so a held contract is billed without an active enrollment. We deliberately skip Enroll so the ONLY credit
      // movement during this rollover is the premium itself — an Enroll'd season would also be FinalizeSeason'd
      // here and pay out prize money, swamping the premium and breaking the exact-delta invariant below.
      long before = prog.credits;
      RolloverReport rep = RolloverYearReport(cc, prog, save, "Jugador");
      CHECK(rep.insurance_premium > 0);                          // a premium was billed this rollover
      CHECK_EQ(before - prog.credits, rep.insurance_premium);    // credits dropped by exactly the premium
      // the surviving contract was stamped with the season it was billed (premium_year guard).
      bool found = false;
      for (const auto& cc2 : save.contracts) if (cc2.series_id == "falcon_series_9334") { found = true; CHECK_EQ(cc2.premium_year, 2030); }
      CHECK(found);
      // a SECOND rollover in the SAME season does NOT re-charge (the guard holds; world year advanced so the
      // stamp differs only when the season changes -> here the first rollover advanced the world to 2031, so a
      // genuine new season IS billed again — assert the once-per-season semantics directly via the guard below).
    }
    // once-per-season guard in isolation: a contract already stamped for this world year is NOT re-billed.
    { CareerCalendar cc; cc.year = 2030; CareerProgress prog; prog.credits = 1000000; prog.frontier_phase = 7;
      prog.cleanliness = 60.0;
      SaveData save; save.current_world_year = 2030;
      Contract c; c.series_id = "falcon_series_9334"; c.kind = bal::CONTRACT_WORKS; c.archetype = ARCH_DIRECT_OFFER;
      c.active = true; c.seasons_total = 3; c.seasons_left = 3; c.signed_year = 2030;
      c.premium_year = 2030;                                     // ALREADY billed this season
      save.contracts.push_back(c);
      // NOTE: NO Enroll here (same reason as above) — isolate the premium step so "credits unchanged" measures the
      // guard alone, not a finalized season's payout. The contract is held + already stamped -> the guard must skip.
      long before = prog.credits;
      RolloverReport rep = RolloverYearReport(cc, prog, save, "Jugador");
      CHECK_EQ(rep.insurance_premium, 0);                        // guard held: no re-charge
      CHECK_EQ(prog.credits, before);                            // credits unchanged
    }
    // solvency block: the premium is a hard solvency gate — a player who can't afford it is NOT
    // charged into the red. Asserted directly on the charge step's invariant: with funds BELOW the premium the
    // step must skip (no charge, contract unstamped) — exercised here on a broke player whose tiny credits the
    // season-end payouts (FinalizeSeason) cannot lift above the premium, so the gate stays closed and the core
    // safety property (credits never go negative) holds regardless.
    { CareerCalendar cc; cc.year = 2030; CareerProgress prog; prog.credits = 5; prog.frontier_phase = 7;
      prog.cleanliness = 60.0;
      SaveData save; save.current_world_year = 2030;
      Contract c; c.series_id = "falcon_series_9334"; c.kind = bal::CONTRACT_WORKS; c.archetype = ARCH_DIRECT_OFFER;
      c.active = true; c.seasons_total = 3; c.seasons_left = 3; c.signed_year = 2030;
      save.contracts.push_back(c);
      // NOTE: no Enroll here -> no season payout funds the player; credits stay at 5 (< any premium).
      RolloverReport rep = RolloverYearReport(cc, prog, save, "Jugador");
      CHECK_EQ(rep.insurance_premium, 0);                        // can't pay -> skipped (no charge billed)
      CHECK(prog.credits >= 0);                                  // never went negative (the core safety property)
      CHECK_EQ(prog.credits, 5);                                 // unchanged: the broke player wasn't billed
      for (const auto& cc2 : save.contracts) if (cc2.series_id == "falcon_series_9334") CHECK_EQ(cc2.premium_year, 0); // unstamped
    }
}

// the per-race deductible scales with the type's damage_share_base AND the race damage severity,
// is ALWAYS the player's (>0 on a real incident, never covered), and is SMALLER for more-covered types.
static void test_deductible_damage_share() {
    using namespace career;
    long dPriv = DeductibleForRace(/*typeIndex=*/0, /*severity=*/1.0);   // privateer, full severity
    long dFact = DeductibleForRace(/*typeIndex=*/5, /*severity=*/1.0);   // factory, full severity
    CHECK(dPriv > 0);                 // RED: stub -> 0 (a real incident must charge the player)
    CHECK(dPriv > dFact);             // RED: stub -> both 0 (covered types eat a smaller share)
    CHECK_EQ(DeductibleForRace(0, 0.0), 0);   // no severity -> no deductible (this passes even on the stub)
    // the optional damage-responsibility reducer LOWERS the deductible when present.
    CHECK(DeductibleForRace(0, 1.0, /*reducer=*/0.5) < dPriv);   // RED: stub -> both 0 (not <)
}

// the qualifier/dream-race entry sink is charged (solvency-gated) at the gate. The
// cost fn is REAL (QualifierEntryCost, reuses QUALIFIER_ENTRY_BY_PHASE — no new constant). The debit itself is
// wired into the overlay's GateUnlockOnResult flow (visually verified there); here we assert the PURE contract that
// wiring MUST honor: the debit equals QualifierEntryCost(phase) exactly, drops credits by exactly that amount,
// and a player with credits < cost is BLOCKED with NO debit (never negative) — the Enroll solvency idiom.
static void test_qualifier_sink() {
    using namespace career;
    CHECK_EQ(QualifierEntryCost(4), bal::QUALIFIER_ENTRY_BY_PHASE[3]);   // cost fn is live (reuses the table)
    CHECK_EQ(QualifierEntryCost(0), bal::QUALIFIER_ENTRY_BY_PHASE[0]);   // clamps phase 0 -> 1 (no UB)
    CHECK_EQ(QualifierEntryCost(9), bal::QUALIFIER_ENTRY_BY_PHASE[6]);   // clamps phase 9 -> 7
    // SOLVENT: the gate debit drops credits by EXACTLY QualifierEntryCost(phase) (the overlay's gate flow).
    {
        int phase = 4;
        long cost = QualifierEntryCost(phase);
        CareerProgress prog; prog.credits = cost + 10000;
        long before = prog.credits;
        // the solvency-gated debit the overlay applies at the gate (mirror Enroll's credits<ins block):
        bool charged = false;
        if (prog.credits >= cost) { prog.credits -= cost; charged = true; }   // pay -> unlock
        CHECK(charged);                                  // solvent -> charged
        CHECK_EQ(before - prog.credits, cost);           // dropped by EXACTLY the qualifier cost
        CHECK(prog.credits >= 0);                        // never negative
    }
    // INSOLVENT: credits < cost -> BLOCKED, no debit, no negative credits, gate stays locked.
    {
        int phase = 6;
        long cost = QualifierEntryCost(phase);
        CareerProgress prog; prog.credits = cost - 1;    // one short
        long before = prog.credits;
        bool charged = false, unlocked = false;
        if (prog.credits >= cost) { prog.credits -= cost; charged = true; unlocked = true; }
        CHECK(!charged);                                 // insolvent -> NOT charged
        CHECK(!unlocked);                                // gate stays locked
        CHECK_EQ(prog.credits, before);                  // unchanged (no partial debit)
        CHECK(prog.credits >= 0);                        // never negative
    }
}

// the travel A->B leg cost tiers by country/continent proxy: same country < same continent <
// cross-continent. RED: the stub returns 0 for every leg.
static void test_travel_legs() {
    using namespace career;
    // tiers by country/continent, ordered (type 0 = privateer, no coverage)
    long sameCountry  = TravelLegCost(0, "EU", "Italy",  "EU", "Italy");
    long sameContinent= TravelLegCost(0, "EU", "Italy",  "EU", "France");
    long crossCont    = TravelLegCost(0, "EU", "Italy",  "SA", "Brazil");
    CHECK(sameCountry  > 0);
    CHECK(sameContinent > sameCountry);
    CHECK(crossCont    > sameContinent);
    // FIX: REALISTIC personal-travel magnitudes — a cross-continent trip is on the order of thousands,
    // not tens of thousands (a rookie with ~10k can afford it). The base no longer scales by phase.
    CHECK(crossCont <= 5000);   // realistic (Spain->Brazil ~1.5-2.5k, not 25k)
    CHECK_EQ(crossCont, bal::TRAVEL_CROSS_CONTINENT);   // type 0, no coverage -> full base cost
}

// multiple concurrent contracts aggregate their per-race economy ACROSS the season,
// each race resolving to its owning contract — and the season grand total equals the sum of the per-contract
// per-race nets with NO cross-contamination of coverage between contracts (AggregateSeasonEconomy).
static void test_multicontract_aggregate() {
    using namespace career;
    SaveData save;
    // two concurrent contracts of different series (no cap on stacking); each resolves to its own type.
    Contract a; a.active = true; a.series_id = "ivory_trophy_7202";  a.kind = bal::CONTRACT_CUSTOMER;
    Contract b; b.active = true; b.series_id = "gt3_nimbus_masters_5890";  b.kind = bal::CONTRACT_PAY_DRIVER;
    save.contracts = { a, b };
    CHECK_EQ(ActiveContractCount(save), 2);                 // the multi-contract substrate is live
    CHECK(ContractForSeries(save, "ivory_trophy_7202") != nullptr);  // per-race resolves to the owning contract
    CHECK(ContractForSeries(save, "gt3_nimbus_masters_5890") != nullptr);
    // A 2-contract season: 2 races on ivory_trophy_7202 (covered customer) + 1 race on gt3_nimbus_masters_5890 (pay-driver rental).
    // Each per-race net is its credits_delta; the aggregation must bucket each race under its OWN contract.
    std::vector<SeasonRaceEconomy> season;
    SettleReport r1{}; r1.prize = 30000; r1.coverage = 5000; r1.costs = 8000; r1.credits_delta = 27000;
    SettleReport r2{}; r2.prize = 20000; r2.coverage = 4000; r2.costs = 6000; r2.credits_delta = 18000;
    SettleReport r3{}; r3.prize = 12000; r3.coverage = 0;    r3.costs = 9000; r3.result_bonus = 2000; r3.credits_delta = 5000;
    season.push_back({ "ivory_trophy_7202", r1 });
    season.push_back({ "gt3_nimbus_masters_5890", r3 });   // interleave to prove grouping is by key, not order
    season.push_back({ "ivory_trophy_7202", r2 });
    SeasonEconomyReport agg = AggregateSeasonEconomy(season);
    // two distinct contract buckets, first-seen order (ivory_trophy_7202 then gt3_nimbus_masters_5890)
    CHECK_EQ((int)agg.per_contract.size(), 2);
    CHECK(agg.per_contract[0].contract_key == std::string("ivory_trophy_7202"));
    CHECK(agg.per_contract[1].contract_key == std::string("gt3_nimbus_masters_5890"));
    // per-contract subtotals sum ONLY that contract's races (no cross-contamination)
    CHECK_EQ(agg.per_contract[0].races, 2);
    CHECK_EQ(agg.per_contract[0].net, 27000 + 18000);       // ivory_trophy_7202 season net
    CHECK_EQ(agg.per_contract[0].coverage, 5000 + 4000);    // its coverage only
    CHECK_EQ(agg.per_contract[1].races, 1);
    CHECK_EQ(agg.per_contract[1].net, 5000);                // gt3_nimbus_masters_5890 season net
    CHECK_EQ(agg.per_contract[1].result_bonus, 2000);       // its result bonus only
    CHECK_EQ(agg.per_contract[0].result_bonus, 0);          // ivory_trophy_7202 carries NONE of gt3's bonus
    // the invariant: season grand net == sum of all per-race nets == sum of per-contract nets
    CHECK_EQ(agg.season_net, 27000 + 18000 + 5000);
    CHECK_EQ(agg.season_net, agg.per_contract[0].net + agg.per_contract[1].net);
}

// holding an EXCLUSIVE contract blocks signing another (thin gate at sign). The
// exclusivity flag is REAL (CoverageProfile.exclusive + Contract.exclusive persisted); the gate is the pure
// AnyExclusiveContractHeld predicate that AcceptOffer consults before signing.
static void test_exclusivity_gate() {
    using namespace career;
    // a factory profile is exclusive; a customer profile is not (per the type table).
    CoverageProfile fact = ContractCoverageProfile(bal::CONTRACT_WORKS, ARCH_FACTORY_PROGRAM);
    CoverageProfile cust = ContractCoverageProfile(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT);
    CHECK(fact.exclusive);    // factory (type 5) is exclusive
    CHECK(!cust.exclusive);   // copago/customer (type 2) is NOT exclusive (open/low types stack)
    // the gate: no contract held -> nothing exclusive; an exclusive factory contract held -> blocks new signs.
    SaveData empty;
    CHECK(!AnyExclusiveContractHeld(empty));                 // no contracts -> no block
    SaveData openHeld;                                       // a NON-exclusive (customer) contract still stacks
    { Contract c; c.active = true; c.series_id = "gt3_nimbus_masters_5890"; c.kind = bal::CONTRACT_CUSTOMER;
      c.archetype = ARCH_CUSTOMER_SEAT; openHeld.contracts.push_back(c); }
    CHECK(!AnyExclusiveContractHeld(openHeld));              // open/low type -> NO-CAP stacking allowed
    SaveData exclHeld;                                       // an EXCLUSIVE (factory) contract blocks the next sign
    { Contract c; c.active = true; c.series_id = "ivory_trophy_7202"; c.kind = bal::CONTRACT_WORKS;
      c.archetype = ARCH_FACTORY_PROGRAM; exclHeld.contracts.push_back(c); }
    CHECK(AnyExclusiveContractHeld(exclHeld));               // exclusive held -> AcceptOffer refuses another
    // the persisted-flag mirror also blocks (a save that carries Contract.exclusive even if the mapping shifts).
    SaveData flagHeld;
    { Contract c; c.active = true; c.series_id = "f1_2008"; c.exclusive = true; flagHeld.contracts.push_back(c); }
    CHECK(AnyExclusiveContractHeld(flagHeld));

    // (24/08): the gate AcceptOffer consults is PER SEASON — the same lesson as the series+season
    // duplicate check: an exclusive contract that ENDS this season doesn't veto signing for the
    // NEXT one. With the window's offers pointing at the new year, a single exclusive contract left ALL
    // market Accepts dead (Decline still worked) and the player could never change teams again.
    SaveData exclNow;                                        // exclusive contract for the current year, 1 season
    { Contract c; c.active = true; c.series_id = "ivory_trophy_7202"; c.kind = bal::CONTRACT_WORKS;
      c.archetype = ARCH_FACTORY_PROGRAM; c.signed_year = 2027; c.seasons_total = 1; exclNow.contracts.push_back(c); }
    CHECK(AnyExclusiveContractHeldFor(exclNow, 2027));       // same season -> vetoes (genuine commitment)
    CHECK(!AnyExclusiveContractHeldFor(exclNow, 2028));      // the next one -> a normal transfer, does NOT veto
    exclNow.contracts[0].seasons_total = 2;                  // multi-year: also covers 2028
    CHECK(AnyExclusiveContractHeldFor(exclNow, 2028));
    CHECK(!AnyExclusiveContractHeldFor(exclNow, 2029));
    // legacy with no signed_year stamped (0): conservative — always vetoes, like the old gate
    CHECK(AnyExclusiveContractHeldFor(exclHeld, 2027));

    // E2E the bug lived in AcceptOffer, not just in the helper. With an exclusive contract that ENDS this year,
    // the SAME-season offer stays vetoed, but the NEXT one (the December transfer) SIGNS.
    SaveData xfer; CareerCalendar ccX;
    { Contract c; c.active = true; c.series_id = "ivory_trophy_7202"; c.kind = bal::CONTRACT_WORKS;
      c.archetype = ARCH_FACTORY_PROGRAM; c.signed_year = 2027; c.seasons_total = 1; xfer.contracts.push_back(c); }
    market::OfferDef xo; xo.id = "of_gt3_nimbus_masters_5890"; xo.team = "Rival Works"; xo.direct = true;
    xo.contractKind = bal::CONTRACT_WORKS; xo.archetype = ARCH_FACTORY_PROGRAM; xo.clsId = "gt3";
    CHECK(!AcceptOffer(xo, xfer, ccX, /*year=*/2027));   // misma temporada: el exclusivo veta
    CHECK(AcceptOffer(xo, xfer, ccX, /*year=*/2028));    // la siguiente: firma (antes moría en silencio)
    CHECK(ContractForSeries(xfer, "gt3_nimbus_masters_5890") != nullptr);
}

// AcceptRejectReason — the WHY behind each of AcceptOffer's blocks, in the same order. It's not a mirror that
// can drift out of sync: AcceptOffer CALLS this function as its block of checks, so here we verify
// (a) each key against its fixture and (b) reason<->signing coherence (empty reason iff AcceptOffer signs).
static void test_accept_reject_reason() {
    using namespace career;
    market::OfferDef of; of.id = "of_harbor_trophy_6546"; of.team = "Equipo";
    SaveData save; save.prog.credits = 1000;
    // clean -> "" (would sign)
    CHECK(AcceptRejectReason(of, save, 2027).empty());
    // malformed offer (no derivable series) -> refused
    market::OfferDef bad;   // empty id -> seriesIdOfOffer gives ""
    CHECK(AcceptRejectReason(bad, save, 2027) == "refused");
    // series+season duplicate -> already; the NEXT season doesn't trip it (transfer, per the season-boundary fix)
    { Contract c; c.active = true; c.series_id = "harbor_trophy_6546"; c.kind = bal::CONTRACT_CUSTOMER;
      c.archetype = ARCH_CUSTOMER_SEAT; c.signed_year = 2027; c.seasons_total = 1; save.contracts.push_back(c); }
    CHECK(AcceptRejectReason(of, save, 2027) == "already");
    CHECK(AcceptRejectReason(of, save, 2028).empty());
    // an exclusive contract covering the destination season -> exclusive (a different series, so it doesn't collide with already);
    // once the exclusive contract has ended, it stops vetoing
    market::OfferDef of2; of2.id = "of_harbor_masters_2241"; of2.team = "Otro";
    { Contract ex; ex.active = true; ex.series_id = "ivory_trophy_7202"; ex.kind = bal::CONTRACT_WORKS;
      ex.archetype = ARCH_FACTORY_PROGRAM; ex.signed_year = 2027; ex.seasons_total = 1; save.contracts.push_back(ex); }
    CHECK(AcceptRejectReason(of2, save, 2027) == "exclusive");
    CHECK(AcceptRejectReason(of2, save, 2028).empty());
    // insolvent buy-in -> afford; with exactly enough credits it passes (the check is '<', not '<=')
    of2.buy_in = 5000;
    CHECK(AcceptRejectReason(of2, save, 2028) == "afford");
    save.prog.credits = 5000;
    CHECK(AcceptRejectReason(of2, save, 2028).empty());
    // ORDER of the checks: in the duplicate's season, "already" wins even with no credits either
    of.buy_in = 999999; save.prog.credits = 0;
    CHECK(AcceptRejectReason(of, save, 2027) == "already");
    // reason<->signing coherence on a LIVE save: where there's a reason AcceptOffer refuses, where there isn't, it signs
    CareerCalendar cc; cc.year = 2028;
    CHECK(!AcceptOffer(of, save, cc, 2027));                       // "already" -> doesn't sign
    of2.buy_in = 0;
    CHECK(AcceptRejectReason(of2, save, 2028).empty());
    CHECK(AcceptOffer(of2, save, cc, 2028));                       // no reason -> signs
}

// (updated 20/07, user decision): the contract TYPE governs the car — ANY SIGNED contract
// (all types 0-5, incl. self-funded/pay-driver) FIXES the team's car (no selection); the player only
// chooses when racing with NO contract (a true privateer — that path never reaches CoverageProfile). Driven by
// CoverageProfile.fixes_car AND the AcceptOffer car-binding: a signed contract carries team_car (the car-set
// infra applies it, the garage hides the picker). (test_contract_fixes_car covers the full type matrix directly.)
static void test_car_by_contract() {
    using namespace career;
    CoverageProfile fact = ContractCoverageProfile(bal::CONTRACT_WORKS,    ARCH_FACTORY_PROGRAM);
    CoverageProfile self = ContractCoverageProfile(bal::CONTRACT_CUSTOMER, ARCH_SELF_FUNDED_ENTRY);
    CHECK(fact.fixes_car);     // a factory ("marca") deal fixes the car
    CHECK(self.fixes_car);     // 20/07: self-funded (type 0) ALSO fixes the team's car
    // AcceptOffer binds the car for a team seat and leaves the privateer free. Build a fresh calendar + save.
    CareerCalendar cc;
    // (a) marca/works offer -> contract carries team_car (no player picker).
    SaveData mSave;
    market::OfferDef mo; mo.id = "of_ivory_trophy_7202"; mo.team = "Factory"; mo.direct = true;
    mo.contractKind = bal::CONTRACT_WORKS; mo.archetype = ARCH_FACTORY_PROGRAM; mo.clsId = "pemberton_zel121";
    CHECK(AcceptOffer(mo, mSave, cc, /*year=*/2025));
    const Contract* mc = ContractForSeries(mSave, "ivory_trophy_7202");
    CHECK(mc != nullptr);
    CHECK(!mc->team_car.empty());     // marca FIXES the car (team_car bound at sign)
    CHECK(mc->exclusive);             // a factory seat is exclusive
    // (a2, following a fix after review): a CUSTOMER/copago offer (ARCH_CUSTOMER_SEAT, type 2) through
    // AcceptOffer ALSO fixes the car, end-to-end. AcceptOffer resolves CoverageProfile generically from
    // (kind, archetype) — it is NOT special-cased by kind — so this closes the E2E gap left when the earlier
    // archetype swap in (b) below stopped exercising type 2 via AcceptOffer (test_contract_fixes_car only
    // checks the CoverageProfile table directly, not the AcceptOffer binding). Distinct series id vs (a)/(b).
    SaveData custSave; CareerCalendar ccCust;
    market::OfferDef co; co.id = "of_merrowdown_myr373"; co.team = "Customer Racing"; co.direct = false;
    co.contractKind = bal::CONTRACT_CUSTOMER; co.archetype = ARCH_CUSTOMER_SEAT; co.clsId = "merrowdown_myr373";
    CHECK(AcceptOffer(co, custSave, ccCust, /*year=*/2025));
    const Contract* custC = ContractForSeries(custSave, "merrowdown_myr373");
    CHECK(custC != nullptr);
    CHECK(!custC->team_car.empty());  // copago/customer (type 2) also fixes car+skin via AcceptOffer
    // (b) PAY-DRIVER / self-funded seat (type 0) -> 20/07: ALSO fixes the team's car (a pay-driver
    // drives the team's car, even though they pay for everything). AcceptOffer binds team_car the same as works/customer. It's still
    // NOT exclusive (stacks). CONTRACT_PAY_DRIVER + ARCH_SELF_FUNDED_ENTRY resolves to type 0 regardless of kind.
    SaveData pSave; CareerCalendar cc2;
    market::OfferDef po; po.id = "of_gt3_nimbus_masters_5890"; po.team = "Privateer"; po.direct = false;
    po.contractKind = bal::CONTRACT_PAY_DRIVER; po.archetype = ARCH_SELF_FUNDED_ENTRY; po.clsId = "gt3";
    CHECK(AcceptOffer(po, pSave, cc2, /*year=*/2025));
    const Contract* pc = ContractForSeries(pSave, "gt3_nimbus_masters_5890");
    CHECK(pc != nullptr);
    CHECK(!pc->team_car.empty());     // 20/07: the signed seat fixes the team's car (team_car bound at signing)
    CHECK(!pc->exclusive);            // open/low type -> stacks (NO-CAP)
    // (c) a bought car persists in SaveData.owned across a save/reload (a collectible, no sell path).
    SaveData oSave;
    CarOwnership car; car.class_id = "gt3_992"; car.vehid = 12345; car.races = 4;
    oSave.owned.push_back(car);
    const char* path = "build/test_owned_car.sav";
    CHECK(SaveCareer(oSave, path));
    SaveData oBack;
    CHECK(LoadCareer(oBack, path));
    bool kept = false;
    for (const auto& c : oBack.owned) if (c.class_id == "gt3_992" && c.vehid == 12345) { kept = true; break; }
    CHECK(kept);   // the collectible survives a save/reload (kept forever; the save has no sell/remove path)
}

// + 20/07 (user decision): EVERY signed contract (types 0-5, incl. self-funded/pay-driver)
// fixes the team's car+skin; the player only chooses with NO contract (a true privateer, that path never reaches here). Before, type
// 0 allowed a choice; now a pay-driver drives the team's car (realism).
static void test_contract_fixes_car() {
    using namespace career;
    // self-funded / pay-driver (type 0) NOW fixes the team's car (20/07)
    CHECK( ContractCoverageProfile(bal::CONTRACT_PAY_DRIVER, ARCH_SELF_FUNDED_ENTRY).fixes_car);
    // copago/customer (type 2) now fixes it too (changed)
    CHECK( ContractCoverageProfile(bal::CONTRACT_CUSTOMER, ARCH_CUSTOMER_SEAT).fixes_car);
    // factory (type 5) still fixes it
    CHECK( ContractCoverageProfile(bal::CONTRACT_WORKS, ARCH_FACTORY_PROGRAM).fixes_car);
    // the authoritative helper mirrors the table (the same source of truth the lock/seat/preview screens gate on)
    CHECK( ContractFixesCar(bal::CONTRACT_PAY_DRIVER, ARCH_SELF_FUNDED_ENTRY));
    CHECK( ContractFixesCar(bal::CONTRACT_CUSTOMER,   ARCH_CUSTOMER_SEAT));
    CHECK( ContractFixesCar(bal::CONTRACT_WORKS,      ARCH_FACTORY_PROGRAM));
}

// car-fix regression (20/07): the decision "does the seat FIX the car?" MUST survive a save/load. A
// CUSTOMER/copago seat (kind=CUSTOMER, archetype=ARCH_CUSTOMER_SEAT -> type 2 -> fixes_car) is persisted and reloaded; the
// A reloaded contract must still be recognized as car-fixing via the PERSISTED kind+archetype fields
// (ContractFixesCar), EVEN THOUGH team_car is NOT serialized and comes back EMPTY. This fixes the real bug (GARROWBY_HEX394/juniper_cup_3635): the
// pre-race gates (CareerSeatLockForSeries / CalUiContractSeat, in career_overlay.cpp — outside this harness)
// gate on fixes_car, NOT on team_car.empty(). The check on empty team_car documents why: if someone goes back to
// gating on team_car in the future, this test explains that the field doesn't persist and breaks the car pre-fill.
static void test_contract_seat_survives_reload() {
    using namespace career;
    // in-memory state right after signing a customer/copago seat (AcceptOffer binds team_car -> covered by
    // test_car_by_contract; here we ISOLATE the PERSISTENCE gap).
    SaveData out;
    out.contracts.assign(1, Contract{});
    Contract& c = out.contracts[0];
    c.active = true; c.series_id = "garrowby_hex394"; c.team_id = "Lumen Motorsport";
    c.kind = bal::CONTRACT_CUSTOMER; c.archetype = ARCH_CUSTOMER_SEAT;   // type 2 -> fixes_car
    c.team_car = "garrowby_hex394"; c.team_livery = "";                             // bound at signing (in memory ONLY)
    CHECK(ContractFixesCar(c.kind, c.archetype));                       // the type fixes the car
    CHECK(!c.team_car.empty());                                        // ...and team_car is set in memory

    const char* path = "build/test_seat_reload.sav";
    CHECK(SaveCareer(out, path));
    SaveData in;
    CHECK(LoadCareer(in, path));
    const Contract* re = ContractForSeries(in, "garrowby_hex394");
    CHECK(re != nullptr);
    CHECK_EQ(re->kind, bal::CONTRACT_CUSTOMER);        // kind persists
    CHECK_EQ(re->archetype, ARCH_CUSTOMER_SEAT);       // archetype persists (-> fixes_car is recoverable)
    CHECK(re->team_car.empty());                       // team_car is NOT serialized -> comes back empty (the trap)
    CHECK(ContractFixesCar(re->kind, re->archetype));  // the fix: the car-fixed decision survives the reload
    remove(path);
}

