// Academy pipeline: a cohort driver does NOT have real brand affinity. brandAff (f[3]) must be
// 0.0 even if their homage contains the team's label as a substring (the old homage.find(teamLabel) tautology).
static void test_cohort_brandaff_no_tautology() {
    using namespace career;
    RosterDriver rd;
    rd.id = "rk_test_tauto";
    rd.homage = "Halyard Racing Team";   // a homage that CONTAINS the label "Halyard Racing" as a substring
    rd.base_skill = 0.5; rd.country = "ES"; rd.birth_year = 2004;
    SaveData save;
    CandidateFactors f = CohortCandidateFactors(rd, save, "Falcon_Cup_6341", "Halyard Racing", "", 2025);
    CHECK_EQ(f.f[3], 0.0);   // BEFORE: 1.0 from the tautology; NOW: 0.0 (no real brand affinity)
    CandidateFactors g = CohortCandidateFactors(rd, save, "Falcon_Cup_6341", "", "", 2025);
    CHECK_EQ(g.f[3], 0.0);   // an empty label still gives 0.0 (no regression)
}

