// save round-trip — additive 'subride' line (write-only-when state != 0); a save with no active
// substitution stays byte-identical (back-compat).
static void test_subride_save_roundtrip() {
    using namespace career;
    SaveData d{};
    // 6th field team_label — WITH A SPACE (never '|'); proves the final segment round-trips intact.
    d.sub_ride = SubRide{ "pinnacle_series_4783", 2, 12345, 8750, 1, "Team Falken Motorsport" };
    const char* path = "build/test_subride.sav";
    CHECK(SaveCareer(d, path));
    SaveData e{};
    CHECK(LoadCareer(e, path));
    CHECK(e.sub_ride.series_id == "pinnacle_series_4783");
    CHECK_EQ(e.sub_ride.seat_idx, 2);
    CHECK_EQ(e.sub_ride.event_absday, 12345);
    CHECK_EQ(e.sub_ride.fee, 8750);
    CHECK_EQ(e.sub_ride.state, 1);
    CHECK(e.sub_ride.team_label == "Team Falken Motorsport");   // the label with a space survives the round-trip
    remove(path);
    // save with NO active substitution: loads to clean defaults (back-compat, no 'subride' line)
    SaveData f0{}; CHECK(SaveCareer(f0, path));
    SaveData f1{}; CHECK(LoadCareer(f1, path));
    CHECK(f1.sub_ride.series_id.empty());
    CHECK_EQ(f1.sub_ride.state, 0);
    remove(path);
}

// SubRideSettle — the pure helper that charges the fee and records the warmth when the substitution is settled.
// (a) fee ONCE (2nd call 0), (b) warmth ONLY in the front half, (c) no-op if not ACCEPTED (state!=2).
static void test_subride_settle() {
    using namespace career;
    // (a) ACCEPTED + P1/20 (front half): fee + warmth + cleanup; 2nd call -> 0, no double marking.
    SaveData s{}; s.current_world_year = 2027;
    s.sub_ride = SubRide{ "pinnacle_series_4783", 2, 12345, 8750, /*state=*/2, "Team Falken" };
    long fee = SubRideSettle(s, /*pos=*/1, /*field=*/20);
    CHECK_EQ(fee, 8750);
    CHECK_EQ(s.sub_ride.state, 0);                 // consumed
    CHECK(s.sub_ride.series_id.empty());
    CHECK_EQ((int)s.rel_marks.size(), 1);          // warmth recorded toward the covered team
    CHECK(s.rel_marks[0].team == "Team Falken");
    CHECK_EQ(s.rel_marks[0].year, 2027);
    CHECK_EQ(s.rel_marks[0].delta_x1000, bal::MK_PRESS_MARK_X1000);
    long again = SubRideSettle(s, 1, 20);          // already consumed -> no double charge or second mark
    CHECK_EQ(again, 0);
    CHECK_EQ((int)s.rel_marks.size(), 1);

    // (a') the half's boundary: P10/20 (exactly halfway) -> warmth YES; P11/20 -> warmth NO.
    { SaveData a{}; a.current_world_year = 2027;
      a.sub_ride = SubRide{ "pinnacle_series_4783", 0, 1, 1000, 2, "Team Falken" };
      CHECK_EQ(SubRideSettle(a, 10, 20), 1000); CHECK_EQ((int)a.rel_marks.size(), 1); }   // 10*2 <= 20
    { SaveData a{}; a.current_world_year = 2027;
      a.sub_ride = SubRide{ "pinnacle_series_4783", 0, 1, 1000, 2, "Team Falken" };
      CHECK_EQ(SubRideSettle(a, 11, 20), 1000); CHECK_EQ((int)a.rel_marks.size(), 0); }   // 11*2 > 20

    // (b) BACK half (P15/20): fee yes (the commitment is to race), no warmth.
    SaveData s2{}; s2.current_world_year = 2027;
    s2.sub_ride = SubRide{ "pinnacle_series_4783", 2, 12345, 8750, 2, "Team Falken" };
    CHECK_EQ(SubRideSettle(s2, /*pos=*/15, /*field=*/20), 8750);
    CHECK_EQ((int)s2.rel_marks.size(), 0);
    CHECK_EQ(s2.sub_ride.state, 0);

    // (b') DNF (pos<=0): fee yes, no warmth (the pos>0 guard rejects the misleading pos*2<=field with pos=0).
    SaveData s2b{}; s2b.current_world_year = 2027;
    s2b.sub_ride = SubRide{ "pinnacle_series_4783", 2, 12345, 8750, 2, "Team Falken" };
    CHECK_EQ(SubRideSettle(s2b, /*pos=*/0, /*field=*/20), 8750);
    CHECK_EQ((int)s2b.rel_marks.size(), 0);

    // (c) NOT accepted (state==1, only offered): 0 and touches NOTHING (no fee, no warmth, no state).
    SaveData s3{};
    s3.sub_ride = SubRide{ "pinnacle_series_4783", 2, 12345, 8750, /*state=*/1, "Team Falken" };
    CHECK_EQ(SubRideSettle(s3, 1, 20), 0);
    CHECK_EQ(s3.sub_ride.state, 1);                // intact
    CHECK_EQ((int)s3.rel_marks.size(), 0);
}

// the REAL mail the draw emits — family 7 (INVITE) subtype 0, payload_key "invite_sub", sender
// the seat's principal team (role inbox_role_teamprincipal), content-derived id "subride_<sid>_<absday>".
// real render (TR+MailInterpolate, same idiom as test_rival_duel_mail_render): no orphaned placeholders
// or punctuation gaps left by an empty param.


// review: a series with the player's own ACTIVE contract -> excluded from candidates (nobody to substitute
// in your own team). With ALL series in the orbit under the player's own contract, the draw has no viable
// candidate -> no draw even if the % gate would hit. Control: WITHOUT those contracts, the SAME seed/week DOES draw.


// review (softlock): a dedup hit in mailExists (mail id ALREADY used) must NOT pin
// sub_ride with no mail. Fixture: an ACTIVE contract in ALL the other series in the orbit (see above)
// leaves nimbus_masters_6505 as the ONLY possible candidate, isolating the wrap's dedup bug to a different series.
// (engine migration to PROJECTED dates): harbor_trophy_6546 is NOT used here (as this fixture did before
// this migration) because harbor_trophy_6546 defines the opener for the ENTIRE level-1 orbit (RookieOpenerDoy) -- at frontier_phase=1 and
// a cursor near the start of the year, its PROJECTED round-1 always coincides with NextEventAbsDay/BuildMasterCalendar
// (already migrated to ProjectSeason) -> harbor_trophy_6546 gets excluded by the "doesn't collide with your own next
// event" rule (career_contract.cpp, SubRideWeeklyDraw). Before this migration, subNextRound read the RAW calendar (a day-of-year
// different from the projected one BuildMasterCalendar already used) and that 1-day inconsistency hid the collision —
// this test used to pass by a coincidence of the very desync this migration closes. nimbus_masters_6505 (same
// orbit, round-1 later than harbor_trophy_6546's) doesn't coincide with the player's own next event and remains a
// valid candidate (a seat occupied with a real label) to test the dedup/softlock without depending on that
// coincidence.


// review: the emitted mail's id is threaded through the optional out-param (RunWorldTick dumps it
// into res.generated_mail_ids, same as newMail from GenerateCareerEmails / EmitNegoMail).


// 18/09 — THE DRAW IS STILL WEEKLY EVEN THOUGH THE PULSE IS DAILY.
//
// It is the only phase of the pulse that depended on the rhythm and not on the date: the gate is decided by weekly bucket
// (`career_seed|year|week`), so with a daily pulse the same week was drawn seven times. The gate
// would not open more often — the hash is the same all seven days — but within a winning week
// there would be seven attempts to find a candidate instead of one, and the real substitution rate would go
// above the 4 % design. The cure is to anchor it to the CALENDAR: it is drawn on the day each bucket opens.
static void test_subride_un_intento_por_semana() {
    using namespace career;
    CHECK(LoadSeries(TESTDATA("series.psv")));
    CHECK(LoadSeriesCalendar(TESTDATA("series_calendar.psv")));
    CHECK(LoadRoster(TESTDATA("series_roster.psv")));

    const int year = 2026, week = 3;                  // bucket 3 = doys 21..27; its opening day is 21
    unsigned long hitSeed = 0, missSeed = 0;
    subrideFindSeeds(year, week, hitSeed, missSeed);
    CHECK(hitSeed != 0);                              // a seed that DOES pass that bucket's % gate

    auto fixture = [&](SaveData& s2) {
        s2.career_seed = hitSeed; s2.prog.frontier_phase = 1; s2.prog.rating = ReqRepRating(1, true);
    };

    // the day the bucket OPENS does draw
    { SaveData s2; fixture(s2);
      CareerCalendar cc; cc.year = year; cc.cursor_doy = week * 7;   // doy 21
      CHECK(SubRideWeeklyDraw(s2, cc, "Alex Doe"));
      CHECK_EQ(s2.sub_ride.state, 1); }

    // the other SIX days of the SAME bucket do not: same seed, same key, same open gate — the only thing
    // that stops them is the anchor. Without it, each of these would be one more attempt of the same week.
    for (int doy = week * 7 + 1; doy <= week * 7 + 6; doy++) {
        SaveData s2; fixture(s2);
        CareerCalendar cc; cc.year = year; cc.cursor_doy = doy;
        CHECK(!SubRideWeeklyDraw(s2, cc, "Alex Doe"));
        CHECK_EQ(s2.sub_ride.state, 0);
    }

    // and bucket 0 keeps its attempt: it starts on doy 1 because the day of the year runs from 1, not from 0.
    { unsigned long h0 = 0, m0 = 0;
      subrideFindSeeds(year, /*week=*/0, h0, m0);
      CHECK(h0 != 0);
      SaveData s2; s2.career_seed = h0; s2.prog.frontier_phase = 1; s2.prog.rating = ReqRepRating(1, true);
      CareerCalendar cc; cc.year = year; cc.cursor_doy = 1;
      CHECK(SubRideWeeklyDraw(s2, cc, "Alex Doe")); }
}

// review, integration: RunWorldTick forwards the substitution mail's id to
// res.generated_mail_ids -- it stops being an "isolated" pulse the UI can't drain. Same fixture as
// test_advance_week (LoadCareerDataFromJson + high frontier_phase/rep/rating) so RunWorldTick runs
// in full (GenerateOffers/GenerateCareerEmails included) without missing data.


// ============================ Inbox redesign: INVITE actions/expirations ============================

// MailActionsFor family INVITE (7): sub (0) offers accept/decline (reusing the same labels); event (1) only
// offers Dismiss. Already answered -> no actions (a guard common to ALL families, the first line of MailActionsFor).
static void test_invite_actions_by_subtype() {
    using namespace career;
    SaveData s;
    GeneratedEmail sub; sub.id = "subride_x_1"; sub.family = 7; sub.subtype = 0;
    auto subActs = MailActionsFor(sub, s);
    CHECK_EQ((int)subActs.size(), 2);
    CHECK(std::string(subActs[0].label_key) == "inbox_act_accept");  CHECK_EQ(subActs[0].choice, 1);
    CHECK(std::string(subActs[1].label_key) == "inbox_act_decline"); CHECK_EQ(subActs[1].choice, 2);

    GeneratedEmail ev; ev.id = "evinv_x"; ev.family = 7; ev.subtype = 1;
    auto evActs = MailActionsFor(ev, s);
    CHECK_EQ((int)evActs.size(), 1);
    CHECK(std::string(evActs[0].label_key) == "inbox_act_ignore"); CHECK_EQ(evActs[0].choice, 2);

    sub.answered = 1; CHECK(MailActionsFor(sub, s).empty());
    ev.answered = 1;  CHECK(MailActionsFor(ev, s).empty());
}

// MailResolvedKey family INVITE (7): sub accept/decline; event only Dismissed (choice 2); choice 0 (closed
// by expiry) -> no resolution (same rule/idiom as OFFER/PRESS); unanswered -> nothing.
static void test_invite_resolved_key() {
    using namespace career;
    GeneratedEmail sub; sub.family = 7; sub.subtype = 0; sub.answered = 1;
    sub.choice = 1; CHECK(std::string(MailResolvedKey(sub)) == "invite_sub_res_accept");
    sub.choice = 2; CHECK(std::string(MailResolvedKey(sub)) == "invite_sub_res_decline");
    sub.choice = 0; CHECK(MailResolvedKey(sub) == nullptr);

    GeneratedEmail ev; ev.family = 7; ev.subtype = 1; ev.answered = 1;
    ev.choice = 2; CHECK(std::string(MailResolvedKey(ev)) == "invite_event_res_ignored");
    ev.choice = 0; CHECK(MailResolvedKey(ev) == nullptr);

    sub.answered = 0; CHECK(MailResolvedKey(sub) == nullptr);   // unanswered -> nothing
}

// ApplySubRideAnswer: accept (state 1->2, the rest of the fields kept -> the next step builds on that data), decline
// (sub_ride -> {} = state 0, frees the gate), and a defensive NO-OP if the mail doesn't match the
// ACTIVE substitution (reconstructed id doesn't match) or if there's no active offer left to resolve (state 0 or already 2/accepted).
static void test_apply_subride_answer() {
    using namespace career;
    // accept
    {
        SaveData s; s.sub_ride = SubRide{"pinnacle_series_4783", 2, 12345, 8750, 1};
        GeneratedEmail m; m.id = "subride_pinnacle_series_4783_12345";
        CHECK_EQ(ApplySubRideAnswer(s, m, 1), 0);
        CHECK_EQ(s.sub_ride.state, 2);
        CHECK(s.sub_ride.series_id == "pinnacle_series_4783");
        CHECK_EQ(s.sub_ride.event_absday, 12345);
        CHECK_EQ(s.sub_ride.fee, 8750);
    }
    // decline
    {
        SaveData s; s.sub_ride = SubRide{"pinnacle_series_4783", 2, 12345, 8750, 1};
        GeneratedEmail m; m.id = "subride_pinnacle_series_4783_12345";
        CHECK_EQ(ApplySubRideAnswer(s, m, 2), 0);
        CHECK_EQ(s.sub_ride.state, 0);
        CHECK(s.sub_ride.series_id.empty());
    }
    // mismatch: id of ANOTHER substitution (an old, already-closed one) -> defensive no-op, ACTIVE sub_ride untouched
    {
        SaveData s; s.sub_ride = SubRide{"pinnacle_series_4783", 2, 12345, 8750, 1};
        GeneratedEmail m; m.id = "subride_harbor_trophy_6546_999";
        CHECK_EQ(ApplySubRideAnswer(s, m, 1), 0);
        CHECK_EQ(s.sub_ride.state, 1);
        CHECK(s.sub_ride.series_id == "pinnacle_series_4783");
    }
    // no active offer (state 0, default) -> no-op even if the id "matches" by coincidence
    {
        SaveData s;
        GeneratedEmail m; m.id = "subride__0";
        CHECK_EQ(ApplySubRideAnswer(s, m, 1), 0);
        CHECK_EQ(s.sub_ride.state, 0);
    }
    // already ACCEPTED (state 2) -> no-op, a second choice can't re-resolve what's already resolved
    {
        SaveData s; s.sub_ride = SubRide{"pinnacle_series_4783", 2, 12345, 8750, 2};
        GeneratedEmail m; m.id = "subride_pinnacle_series_4783_12345";
        CHECK_EQ(ApplySubRideAnswer(s, m, 2), 0);
        CHECK_EQ(s.sub_ride.state, 2);
    }
}

// EmitEventInviteMail: real construction (family/subtype/tag/payload_key/sender), title localized AT
// EMIT TIME (GetLang), ADDITIVE params event_id/ends_at (consumed by query.inbox/expirations), dedup by
// id "evinv_<eventId>" and a render-assert (TR+MailInterpolate, same idiom as test_subride_mail_render).
static void test_emit_event_invite_mail() {
    using namespace career;
    SpecialEventDef ev; ev.id = "ev-mc"; ev.title_en = "Blackgate Speedway Classic"; ev.title_es = "Clasico de Blackgate Speedway";
    ev.reward_credits = 40000; ev.ends_at = 1234567890;

    SetLang(0);   // English
    SaveData s;
    EmitEventInviteMail(s, ev, /*year=*/2026, /*day=*/50, "Alex Doe");
    CHECK_EQ((int)s.emails.size(), 1);
    const GeneratedEmail m = s.emails[0];
    CHECK(m.id == "evinv_ev-mc");
    CHECK_EQ(m.family, 7);
    CHECK_EQ(m.subtype, 1);
    CHECK_EQ(m.tag, 2);
    CHECK_EQ(m.day, 50);
    CHECK_EQ(m.year, 2026);   // fix for "mail with an absurd date across a year boundary": year travels alongside day
    CHECK(m.payload_key == "invite_event");
    CHECK(m.from_name == "Career Engine Events");
    CHECK(m.from_role_key == "inbox_role_organizer");

    MailParams p = MailParamsDecode(m.params);
    std::string title, eventId, endsAt, reward, player;
    for (const auto& kv : p) {
        if (kv.first == "title") title = kv.second;
        else if (kv.first == "event_id") eventId = kv.second;
        else if (kv.first == "ends_at") endsAt = kv.second;
        else if (kv.first == "reward") reward = kv.second;
        else if (kv.first == "player") player = kv.second;
    }
    CHECK(title == "Blackgate Speedway Classic");        // GetLang()==0 -> title_en
    CHECK(eventId == "ev-mc");
    CHECK(endsAt == "1234567890");
    CHECK(!reward.empty());
    CHECK(player == "Alex");

    // Spanish locale -> title_es (localized AT EMIT TIME, persisted, not re-localized on read)
    SaveData s2;
    SetLang(1);
    EmitEventInviteMail(s2, ev, 2026, 50, "Alex Doe");
    std::string titleEs;
    for (const auto& kv : MailParamsDecode(s2.emails[0].params)) if (kv.first == "title") titleEs = kv.second;
    CHECK(titleEs == "Clasico de Blackgate Speedway");
    SetLang(0);   // restore (don't interfere with other bilingual tests)

    // dedup: a 2nd call with the SAME event doesn't re-emit (one invite per event, never repeated)
    EmitEventInviteMail(s, ev, 2026, 60, "Alex Doe");
    CHECK_EQ((int)s.emails.size(), 1);

    // render-assert: real interpolated body with no orphaned placeholders or punctuation gaps
    std::string bodyKey = MailBodyKey(m.payload_key, m.variant);
    std::string rendered = MailInterpolate(TR(bodyKey.c_str()), p);
    CHECK(rendered.find('{') == std::string::npos);
    CHECK(rendered.find(", ,") == std::string::npos);
    CHECK(rendered.find(" .") == std::string::npos);
}

// Expiry sync (GenerateCareerEmails, alongside the OFFER sync): family INVITE (7) subtype 1 (event)
// closes on its own (choice 0, no resolution) via 3 independent paths — claimed (claimed_events), removed from the
// registry (with the registry actually populated), or real expiry (ends_at). An EMPTY registry (typical of a
// standalone test/race pulse that never loaded the overlay's registry) NEVER closes on its own — this avoids the trap
// of confusing "not loaded" with "genuinely removed", which would close ALL invitations.
static void test_invite_event_expiry() {
    using namespace career;
    ResetSpecialEventsForTest();
    EmailGenContext ctx; ctx.year = 2026; ctx.day = 100;
    std::vector<market::GenOffer> none;

    // (a) claimed (claimed_events) -> closes even if the registry is empty and ends_at is in the future.
    {
        SaveData s;
        GeneratedEmail e; e.id = "evinv_ev-claimed"; e.family = 7; e.subtype = 1;
        e.params = MailParamsEncode({{"event_id","ev-claimed"},{"ends_at","4102444800"}});
        s.emails.push_back(e);
        s.claimed_events.insert("ev-claimed");
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.emails[0].answered, 1); CHECK_EQ(s.emails[0].choice, 0);
    }
    // (b) expired by the clock (ends_at in the past, 1970) -> closes even if the registry is empty/unclaimed.
    {
        SaveData s;
        GeneratedEmail e; e.id = "evinv_ev-late"; e.family = 7; e.subtype = 1;
        e.params = MailParamsEncode({{"event_id","ev-late"},{"ends_at","1"}});
        s.emails.push_back(e);
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.emails[0].answered, 1); CHECK_EQ(s.emails[0].choice, 0);
    }
    // (c) EMPTY registry + no claim + future ends_at -> does NOT close (the key regression here).
    {
        SaveData s;
        GeneratedEmail e; e.id = "evinv_ev-live"; e.family = 7; e.subtype = 1;
        e.params = MailParamsEncode({{"event_id","ev-live"},{"ends_at","4102444800"}});
        s.emails.push_back(e);
        CHECK_EQ(SpecialEventRegistryCount(), 0);   // covers the "registry not loaded" scenario
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.emails[0].answered, 0);
    }
    // (d) POPULATED registry (with ANOTHER event) and the id does NOT appear -> "removed from registry" -> closes.
    {
        SaveData s;
        GeneratedEmail e; e.id = "evinv_ev-gone"; e.family = 7; e.subtype = 1;
        e.params = MailParamsEncode({{"event_id","ev-gone"},{"ends_at","4102444800"}});
        s.emails.push_back(e);
        std::vector<SpecialEventDef> reg; SpecialEventDef other; other.id = "ev-other"; reg.push_back(other);
        SetSpecialEventRegistry(reg);
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.emails[0].answered, 1); CHECK_EQ(s.emails[0].choice, 0);
        ResetSpecialEventsForTest();
    }
    // (e) registry populated AND the id IS there -> still alive.
    {
        SaveData s;
        GeneratedEmail e; e.id = "evinv_ev-still"; e.family = 7; e.subtype = 1;
        e.params = MailParamsEncode({{"event_id","ev-still"},{"ends_at","4102444800"}});
        s.emails.push_back(e);
        std::vector<SpecialEventDef> reg; SpecialEventDef mine; mine.id = "ev-still"; reg.push_back(mine);
        SetSpecialEventRegistry(reg);
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.emails[0].answered, 0);
        ResetSpecialEventsForTest();
    }
}

// Expiry sync — family INVITE (7) subtype 0 (sub). state==1 (offered, unanswered) with the round
// ALREADY past -> closes (choice 0) + frees sub_ride (the "one substitution at a time" gate); before the round ->
// still alive. state==2 (accepted) with the round past -> "race lost, no penalty": the mail, ALREADY
// answered (choice 1), stays INTACT, only sub_ride is cleared; before the round -> sub_ride is kept.
static void test_invite_sub_expiry() {
    using namespace career;
    const int absday = career::dateutil::AbsDayFromYearDoy(2026, 100);
    std::vector<market::GenOffer> none;

    // (a) unanswered + date past -> closes + frees sub_ride
    {
        SaveData s; s.sub_ride = SubRide{"pinnacle_series_4783", 2, absday, 8750, 1};
        GeneratedEmail e; e.id = "subride_pinnacle_series_4783_" + std::to_string(absday); e.family = 7; e.subtype = 0;
        s.emails.push_back(e);
        EmailGenContext ctx; ctx.year = 2026; ctx.day = 110;
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.emails[0].answered, 1); CHECK_EQ(s.emails[0].choice, 0);
        CHECK_EQ(s.sub_ride.state, 0); CHECK(s.sub_ride.series_id.empty());
    }
    // (b) unanswered, round STILL hasn't passed (same day) -> still alive.
    {
        SaveData s; s.sub_ride = SubRide{"pinnacle_series_4783", 2, absday, 8750, 1};
        GeneratedEmail e; e.id = "subride_pinnacle_series_4783_" + std::to_string(absday); e.family = 7; e.subtype = 0;
        s.emails.push_back(e);
        EmailGenContext ctx; ctx.year = 2026; ctx.day = 100;   // same day -> hasn't passed yet
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.emails[0].answered, 0); CHECK_EQ(s.sub_ride.state, 1);
    }
    // (c) ALREADY ACCEPTED (state 2), round past -> mail (already answered) intact, sub_ride cleared with NO penalty.
    {
        SaveData s; s.sub_ride = SubRide{"pinnacle_series_4783", 2, absday, 8750, 2};
        GeneratedEmail e; e.id = "subride_pinnacle_series_4783_" + std::to_string(absday); e.family = 7; e.subtype = 0;
        e.answered = 1; e.choice = 1;
        s.emails.push_back(e);
        EmailGenContext ctx; ctx.year = 2026; ctx.day = 110;
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.emails[0].answered, 1); CHECK_EQ(s.emails[0].choice, 1);   // intact
        CHECK_EQ(s.sub_ride.state, 0);                                        // clean -> frees the gate
    }
    // (d) ACCEPTED, round NOT YET past -> sub_ride is kept (the substitution still stands).
    {
        SaveData s; s.sub_ride = SubRide{"pinnacle_series_4783", 2, absday, 8750, 2};
        EmailGenContext ctx; ctx.year = 2026; ctx.day = 100;
        GenerateCareerEmails(s, none, ctx);
        CHECK_EQ(s.sub_ride.state, 2);
    }
}

// query.inbox — family INVITE (7): eventId (subtype 1) + deadlineWeeks (both subtypes). Same
// pattern as offerId/deadlineWeeks for family 0: only while the mail is still UNANSWERED.
static void test_capi_inbox_invite_fields() {
    static career::SaveData s_save; static career::CareerCalendar s_cal;
    s_save = career::SaveData{}; s_cal = career::CareerCalendar{};
    s_cal.year = 2026; s_cal.cursor_doy = 100;

    { career::GeneratedEmail e; e.id = "evinv_ev-x"; e.family = 7; e.subtype = 1;
      e.params = career::MailParamsEncode({{"event_id","ev-x"},{"ends_at","4102444800"}});
      s_save.emails.push_back(e); }

    // the id MUST reconstruct save.sub_ride's for the field to appear (same defensive idiom as
    // ApplySubRideAnswer) — avoids exposing a deadline for a substitution that isn't the ACTIVE one anymore.
    int absday = career::dateutil::AbsDayFromYearDoy(2026, 200);   // round ahead of the cursor (day-of-year 100)
    s_save.sub_ride = career::SubRide{"pinnacle_series_4783", 2, absday, 8750, 1};
    { career::GeneratedEmail e; e.id = "subride_pinnacle_series_4783_" + std::to_string(absday); e.family = 7; e.subtype = 0;
      s_save.emails.push_back(e); }

    capi::SetCareerStateProvider([]() {
        capi::CareerStateView v; v.loaded = true; v.save = &s_save; v.calendar = &s_cal;
        v.playerName = "Alex"; return v; });
    capi::HandlerResult r = capi::QueryInbox(nullptr);
    CHECK(r.ok);
    CHECK(r.payload.find("\"eventId\":\"ev-x\"") != std::string::npos);
    CHECK(r.payload.find("\"deadlineWeeks\":") != std::string::npos);   // both mails carry it (>0, future)

    // answered (Dismissed) -> neither eventId nor deadlineWeeks from the event mail (the decision is no longer on the table)
    s_save.emails[0].answered = 1; s_save.emails[0].choice = 2;
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"eventId\"") == std::string::npos);
    capi::SetCareerStateProvider(nullptr);
}

// query.inbox — subReady: sub_ride ACCEPTED (state==2) + TODAY <= event_absday
// (SAME condition as SubRideArm, screen_calendar.cpp). The mail is already ANSWERED (choice==1) by
// the time this can be true — unlike eventId/deadlineWeeks, which only live while the
// mail is still unanswered. The original [absday-1, absday] window was unreachable with
// cmd.time.advanceToNextEvent (it skips other people's events, never lands exactly there); now it opens on
// ACCEPTANCE, so "too soon" no longer exists once accepted — only "not yet accepted" (state==1)
// and "already expired" (the round is past and RunWorldTick cleared sub_ride) still give subReady false.
static void test_capi_inbox_subready() {
    static career::SaveData s_save; static career::CareerCalendar s_cal;
    s_cal.year = 2026;
    const int absday = career::dateutil::AbsDayFromYearDoy(2026, 200);   // day-of-year 200: window [199,200] without crossing a year boundary

    auto mkAcceptedMail = [&]() {
        career::GeneratedEmail e; e.id = "subride_pinnacle_series_4783_" + std::to_string(absday);
        e.family = 7; e.subtype = 0; e.answered = 1; e.choice = 1;
        return e;
    };
    capi::SetCareerStateProvider([]() {
        capi::CareerStateView v; v.loaded = true; v.save = &s_save; v.calendar = &s_cal;
        v.playerName = "Alex"; return v; });

    // (a) the eve of the round (event_absday-1) -> subReady:true
    s_save = career::SaveData{};
    s_save.sub_ride = career::SubRide{"pinnacle_series_4783", 2, absday, 8750, 2};
    s_save.emails.push_back(mkAcceptedMail());
    s_cal.cursor_doy = 199;
    capi::HandlerResult r = capi::QueryInbox(nullptr);
    CHECK(r.ok);
    CHECK(r.payload.find("\"subReady\":true") != std::string::npos);

    // (b) the day of the round itself (event_absday) -> subReady:true (inclusive edge)
    s_cal.cursor_doy = 200;
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"subReady\":true") != std::string::npos);

    // (c) review: days before but ALREADY ACCEPTED -> subReady:true (the window opens at
    // acceptance, not the eve; the old "too soon" case no longer exists once accepted)
    s_cal.cursor_doy = 198;
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"subReady\":true") != std::string::npos);

    // (d) sub_ride only OFFERED (state 1, not accepted) -> no subReady even if the window matches
    {
        career::SaveData s2; s2.sub_ride = career::SubRide{"pinnacle_series_4783", 2, absday, 8750, 1};
        career::GeneratedEmail e; e.id = "subride_pinnacle_series_4783_" + std::to_string(absday);
        e.family = 7; e.subtype = 0;   // unanswered -> not even choice==1
        s2.emails.push_back(e);
        s_save = s2; s_cal.cursor_doy = 200;
        r = capi::QueryInbox(nullptr);
        CHECK(r.payload.find("\"subReady\"") == std::string::npos);
    }

    // (e) the mail's id doesn't match the live sub_ride (defensive, same idiom as deadlineWeeks) -> no subReady
    {
        career::SaveData s3; s3.sub_ride = career::SubRide{"pinnacle_series_4783", 2, absday, 8750, 2};
        career::GeneratedEmail e; e.id = "subride_otra_serie_" + std::to_string(absday);
        e.family = 7; e.subtype = 0; e.answered = 1; e.choice = 1;
        s3.emails.push_back(e);
        s_save = s3; s_cal.cursor_doy = 200;
        r = capi::QueryInbox(nullptr);
        CHECK(r.payload.find("\"subReady\"") == std::string::npos);
    }

    // (f) review: round ALREADY PASSED (absday+1) -> no subReady (expired; the real state==2
    // would already have been cleared by RunWorldTick, but the gate alone must also reject the day after)
    {
        career::SaveData s4; s4.sub_ride = career::SubRide{"pinnacle_series_4783", 2, absday, 8750, 2};
        s4.emails.push_back(mkAcceptedMail());
        s_save = s4; s_cal.cursor_doy = 201;
        r = capi::QueryInbox(nullptr);
        CHECK(r.payload.find("\"subReady\"") == std::string::npos);
    }

    capi::SetCareerStateProvider(nullptr);
}

// Results: the championship table shown after a race is the one for the SERIES RACED. The real bug: the player
// raced Formula Vee and the screen showed the TSI table, because it resolved by "the last enrollment with
// a populated classification" (the one SELECTED in the UI), not the settled race. Case (a) reproduces
// exactly that: tsi comes AFTER fvee in enrollments, so the old rule would have returned tsi.
static void test_standings_for_race() {
    auto mkStandings = [](const char* who, int pts) {
        career::Standings s;
        s.drivers[who].push_back(career::DriverRound{1, 1, pts, false, false});
        return s;
    };
    career::CareerCalendar cal;
    { career::SeasonState e; e.series_id = "drift_masters_3348"; e.standings = mkStandings("Alex", 25); cal.enrollments.push_back(e); }
    { career::SeasonState e; e.series_id = "tsi_g1";  e.standings = mkStandings("Otro", 18); cal.enrollments.push_back(e); }

    // (a) the series actually raced wins even if it's NOT the last enrollment with a table
    const career::SeasonState* got = career::StandingsForRace(cal, "drift_masters_3348");
    CHECK(got != nullptr);
    CHECK(got && got->series_id == "drift_masters_3348");

    // (b) a standalone race (no series) -> no championship, instead of pulling in another series' table
    CHECK(career::StandingsForRace(cal, "") == nullptr);

    // (c) a raced series that isn't enrolled (e.g. a trial) -> no championship
    CHECK(career::StandingsForRace(cal, "pinnacle_series_4783") == nullptr);

    // (d) enrolled but still no classification (round 0) -> no panel, not an empty table
    { career::SeasonState e; e.series_id = "p1_g2"; cal.enrollments.push_back(e); }
    CHECK(career::StandingsForRace(cal, "p1_g2") == nullptr);
}

// THE PRIVATEER RULE (user, 28/07): being a privateer isn't penalized; changing teams from A to B MID-SEASON
// is. Case (c) was the broken one: with the old rule, changing identity in a
// NEW season (without having raced yet) also charged -3 REP and the compensation, because it compared
// against the save's DURABLE pick instead of the season's latch.
static void test_mid_season_identity_switch() {
    // (a) you already raced with team A and switch to B -> divorce
    CHECK(career::IsMidSeasonIdentitySwitch(1111, 3, 2222, 5) == true);
    // (b) same identity -> nothing happens (later rounds of the season)
    CHECK(career::IsMidSeasonIdentitySwitch(1111, 3, 1111, 3) == false);
    // (c) new season with no latch: the transfer is free, no cost
    CHECK(career::IsMidSeasonIdentitySwitch(0, -1, 2222, 5) == false);
    // (d) only the skin changes (same car, different team) -> that's also a change
    CHECK(career::IsMidSeasonIdentitySwitch(1111, 3, 1111, 4) == true);
    // (e) no concrete new identity (contract/measurement) -> nothing to penalize
    CHECK(career::IsMidSeasonIdentitySwitch(1111, 3, 0, -1) == false);
    CHECK(career::IsMidSeasonIdentitySwitch(1111, 3, 2222, -1) == false);
}

// query.standings with no seriesId: defaults to the series of the LAST raced race that's still enrolled. It used to
// start from the 1st active contract, which with two open contracts returned the wrong championship.
static void test_capi_standings_default_series() {
    static career::SaveData s_save; static career::CareerCalendar s_cal;
    s_save = career::SaveData{}; s_cal = career::CareerCalendar{};
    s_cal.year = 2026;
    auto mkStandings = [](const char* who, int pts) {
        career::Standings s;
        s.drivers[who].push_back(career::DriverRound{1, 1, pts, false, false});
        return s;
    };
    { career::SeasonState e; e.series_id = "tsi_g1";  e.standings = mkStandings("Otro", 18); s_cal.enrollments.push_back(e); }
    { career::SeasonState e; e.series_id = "drift_masters_3348"; e.standings = mkStandings("Alex", 25); s_cal.enrollments.push_back(e); }
    { career::Contract c; c.series_id = "tsi_g1"; c.active = true; s_save.contracts.push_back(c); }
    { career::Contract c; c.series_id = "drift_masters_3348"; c.active = true; s_save.contracts.push_back(c); }

    capi::SetCareerStateProvider([]() {
        capi::CareerStateView v; v.loaded = true; v.save = &s_save; v.calendar = &s_cal;
        v.playerName = "Alex"; return v; });

    // (a) last raced = fvee, first active contract = tsi -> fvee wins
    { career::RaceLogEntry e; e.series_id = "drift_masters_3348"; s_save.race_log.push_back(e); }
    capi::HandlerResult r = capi::QueryStandings(nullptr);
    CHECK(r.ok);
    CHECK(r.payload.find("\"seriesId\":\"drift_masters_3348\"") != std::string::npos);

    // (b) the LAST one governs, not the first in the log
    { career::RaceLogEntry e; e.series_id = "tsi_g1"; s_save.race_log.push_back(e); }
    r = capi::QueryStandings(nullptr);
    CHECK(r.payload.find("\"seriesId\":\"tsi_g1\"") != std::string::npos);

    // (c) the last one was standalone / from an unenrolled series -> skipped, keeps looking backward
    { career::RaceLogEntry e; s_save.race_log.push_back(e); }                       // no series
    { career::RaceLogEntry e; e.series_id = "pinnacle_series_4783"; s_save.race_log.push_back(e); }  // not enrolled
    r = capi::QueryStandings(nullptr);
    CHECK(r.payload.find("\"seriesId\":\"tsi_g1\"") != std::string::npos);

    // (d) no races run -> falls back to the active contract (the usual behavior)
    s_save.race_log.clear();
    r = capi::QueryStandings(nullptr);
    CHECK(r.payload.find("\"seriesId\":\"tsi_g1\"") != std::string::npos);

    capi::SetCareerStateProvider(nullptr);
}

// pay-driver/Latifi — upper-tier backmarker BUY-IN seats appear via money_norm; the buy-in
// is debited at signing (solvency-gated). With money_norm>0 an ABOVE-PACE open seat (player under its bar)
// surfaces as a CONTRACT_PAY_DRIVER offer carrying buy_in>0; with money_norm=0 none. AcceptOffer debits the
// buy-in (no negative credits; insolvent -> sign blocked).


// payDriverEligible now also applies to WORKS seats, with a skill
// floor (MK_PAYDRIVER_SKILL_FLOOR). Series "merrowdown_myr373" (Juniper Masters 12614, closed grid, tier 7): reqRep works =
// ReqRepRating(7,true) = 1950*1.15 = 2242.5 -> seat.reqRep=2243 -> seatBarQ = RatingQuality(2243) ~= 0.9119.
// rating=2000 -> payQ = RatingQuality(2000) ~= 0.8107, which falls in [seatBarQ-FLOOR, seatBarQ) = [0.7619, 0.9119):
// below the bar but WITHIN the floor. With budget (money_norm>0) a CONTRACT_PAY_DRIVER offer should surface
// carrying buy_in>0; with no budget (money_norm==0), no pay-driver offer at all.


// bidirectional job security — an UNPROTECTED underperformer LOSES the seat at rollover
// (not renewed / replaced); a protected one (guaranteed_seat / anti_replace) or an on-target one KEEPS it.
// (a) the pure predicate; (b) the rollover INTEGRATION (PlayerLosesSeat gates BuildRenewalOffer + frees the
// seat into seat_occupant + records the job loss). Mid-season loss stays the existing no-show/breach path.


// (d) BreakContract: rep drops 10 (floor 0) and the contract becomes inactive (seat freed).
static void test_break_contract() {
    using namespace career;
    // normal case: rep 50 -> 40, clean contract
    SaveData a;
    a.prog.rep = 50;
    a.contracts.assign(1, career::Contract{});
    a.contracts[0].active = true; a.contracts[0].series_id = "ivory_trophy_7202"; a.contracts[0].kind = 0;
    BreakContract(a);
    CHECK_EQ(a.prog.rep, 50 + career::bal::REP_BROKEN_CONTRACT);   // 40
    CHECK(a.contracts.empty());                                   // seat freed (vector emptied)

    // floor at 0: rep 4 - 10 -> 0 (not negative)
    SaveData b;
    b.prog.rep = 4;
    b.contracts.assign(1, career::Contract{});
    b.contracts[0].active = true; b.contracts[0].series_id = "x";
    BreakContract(b);
    CHECK_EQ(b.prog.rep, 0);
    CHECK(b.contracts.empty());

    // no-op if there's no contract: rep untouched
    SaveData c; c.prog.rep = 33;
    BreakContract(c);
    CHECK_EQ(c.prog.rep, 33);
    CHECK(c.contracts.empty());
}

// ============================ market dynamics ============================

// helper: a minimal OfferDef with id "of_<sid>" + team (the only fields OfferConflicts/RecordCourting consume).
static market::OfferDef mkOffer(const std::string& sid, const std::string& team = "") {
    market::OfferDef o{};
    o.id   = "of_" + sid;
    o.team = team.empty() ? ("Team " + sid) : team;
    return o;
}

// 18/09 (Josh's decision) — two signings in the SAME window no longer clash silently. In the window the
// next season is signed, and what is signed there is not enrolled until January: the warning only looked at this year's enrollments
// and saw nothing. Now, with a IVORY_CUP_12573 contract signed for next year, the MERROWDOWN_MYR373 offer (which shares
// its weekends) warns of the clash; and a contract that does NOT cover that season does not count.


// (a) OfferConflicts: projects the offer's series calendar against enrollments (via ConflictsFor).
//     Returns the enrolled series_ids that overlap; empty if there's no clash.


// (b) Courting: round-trip Save/Load + back-compat (no lines -> empty); RecordCourting adds 1 per held,
//     idempotent on repeat.


// (c) AdvanceWeek: bumps the cursor by 7*weeks; a series whose round-1 fell behind the cursor lands in
//     expired_offers/expired_offer_ids; live held offers log courting. Doesn't touch contracts. Crossing the year
//     AUTO-rolls (no longer capped at 365); the specific wrap is covered in test_advance_time_autoroll.


// (engine migration to PROJECTED dates): RunWorldTick's offer-expiry window
// (AdvanceWeek, career_contract.cpp) used to resolve each series' opener (round 1) via the
// RAW CalendarForSeries (reference calendar, kStartYear=2025), not via ProjectSeason/
// CalendarForSeriesInYear (dates re-aligned to the CURRENT YEAR, cc.year). At kStartYear both agree
// (RealignDoy is the identity there); the divergence only shows up from the 2nd season onward. It locates
// PROGRAMMATICALLY (same search idiom as test_pending_slot_projected_year/test_calendar_in_year) a
// a real (series, year, cursor) where the RAW opener and the PROJECTED one land on DIFFERENT SIDES of the
// MK_OFFER_HORIZON_DOY window -> the "expired"/"still valid" decision changes depending on which calendar is consulted. RED today: the
// engine uses CalendarForSeries (raw) -> the observed result is rawExpired, not projExpired.


// AdvanceWeek's INTERNAL pulse now uses the LIVING-WORLD form GenerateOffers(in,&save) (previously
// the legacy GenerateOffers(in), with no save). Differential test: ivory_trophy_7202 (CLOSED tier-7, series_access.psv) with a
// "freshly born" save (NO seat_occupant -> grid filled from the roster, see test_open_seat_offers) and
// frontier_phase=1 (7 > 1 -> the `sd.level <= in.frontier_phase` guard turns off the ELO displacement
// scan for this series, career_market.cpp). In the SEEDED form the
// (`!anyOpenSeat && !displaceSeries && sd.closed -> continue`) gate discards ivory_trophy_7202 BEFORE computing held/courting.
// The LEGACY form (pre-fix) ignores occupancy entirely and would have left held=true (metRep && xpLocked)
// > a courting trail. If AdvanceWeek reverts to the legacy form this assert catches it.
// fixture NOTE: LoadCareerDataFromJson resolves series_access.psv via paths::Data (the data root), which can
// get re-pointed by a SetRootsForTest from ANOTHER test that ran earlier in the same process (paths::g_root is
// global). We reload series_access.psv here with the ABSOLUTE path (same pattern as test_open_seat_offers) so
// sd.closed comes out correct WITHOUT depending on the full suite's run order.


// The real time model's AdvanceDays advances by DAYS with a leap-aware year boundary.


// Atenea's birthday greeting when the player's BIRTHDAY is crossed in AdvanceDays.


// The real time model's AdvanceToDate jumps to an exact abs_day, crossing years (rollover).


// 18/09 — THE LONG JUMP ATE THE SIGNING WINDOW WITHOUT OPENING IT.
//
// `AdvanceToDate` moved the cursor in one go and gave ONE pulse, the arrival day's. Since the window is only
// sealed if the clock is INSIDE it when a pulse falls, a jump that started before 1 September and
// landed past the decision week never sealed it: the world skipped its own silly season in
// silence, and on top of that the decision week later resolved a window that had never been opened.
//
// With the daily pulse every day along the way gets its own, so the days inside the window
// seal it as they pass. This is what the lock pins: jump over the ENTIRE window and it still ends up
// sealed for the destination season.


// 18/09 (Josh's decision) — "the only window for moves will be until 31 December, after that everything
// is sealed". The preseason opening used to open tail seats in January-March, with the market closed.
// This pins that the pulse no longer opens anything on a day when the opening, called bare, WOULD have opened:
// i.e. what stops it is the sealing and not that the day happened to be a quiet one.
static int contarAbiertos(const career::SaveData& sv) {
    int n = 0;
    for (const auto& kv : sv.seat_occupant) if (kv.second == career::kSeatOpen) n++;
    return n;
}


// 18/09 — THE WINTER REPORT SURVIVES SAVE AND LOAD, signings included. There was no round-trip test
// since the report started being saved (17/09). And it pins the save rule: a line that already
// exists does not change shape — "rollyear" stays with three integers and the total signings goes in "rollmovtot".
static void test_parte_del_invierno_ida_y_vuelta() {
    using namespace career;
    SaveData a;
    auto& ls = a.last_rollover;
    ls.year = 2027; ls.total_retires = 12; ls.total_promos = 34; ls.total_moves = 56;
    { SaveData::RolloverSaved::Retire r; r.name = "Roberto Moreno"; r.age = 66; r.reason = "Age"; ls.retires.push_back(r); }
    { SaveData::RolloverSaved::Promo pr; pr.name = "Pietro Fittipaldi"; pr.from_tier = 2; pr.to_tier = 3; ls.promos.push_back(pr); }
    { SaveData::RolloverSaved::Move m; m.name = "Lucia Vega"; m.from = "Iron Lynx \xC2\xB7 GT3"; m.to = "AF Corse \xC2\xB7 GT3"; ls.moves.push_back(m); }
    CHECK(SaveCareer(a, "build/test_parte_invierno.sav"));

    SaveData b; CHECK(LoadCareer(b, "build/test_parte_invierno.sav"));
    CHECK_EQ(b.last_rollover.year, 2027);
    CHECK_EQ(b.last_rollover.total_retires, 12);
    CHECK_EQ(b.last_rollover.total_promos, 34);
    CHECK_EQ(b.last_rollover.total_moves, 56);
    CHECK_EQ((int)b.last_rollover.retires.size(), 1);
    CHECK_EQ((int)b.last_rollover.promos.size(), 1);
    CHECK_EQ((int)b.last_rollover.moves.size(), 1);
    if (!b.last_rollover.moves.empty()) {
        CHECK(b.last_rollover.moves[0].name == "Lucia Vega");
        CHECK(b.last_rollover.moves[0].from == "Iron Lynx \xC2\xB7 GT3");
        CHECK(b.last_rollover.moves[0].to == "AF Corse \xC2\xB7 GT3");
    }

    // the shape of the lines: "rollyear" with THREE integers, as it was born; the total signings, separate
    std::string txt;
    { FILE* f = fopen("build/test_parte_invierno.sav", "rb");
      if (f) { char buf[4096]; size_t n; while ((n = fread(buf, 1, sizeof buf, f)) > 0) txt.append(buf, n); fclose(f); } }
    CHECK(txt.find("rollyear 2027 12 34\r\n") != std::string::npos);
    CHECK(txt.find("rollmovtot 56\r\n") != std::string::npos);
}

// The real time model's AdvanceToNextEvent lands on the next round on your schedule.
// NextEventAbsDay looks for the next REACHABLE round across the ENTIRE reachable calendar (enrolled or OPEN in
// the future, same filter as WeeksToNextEvent) — not just yours. With a high frontier_phase (e.g. 7, as in
// test_advance_week) several tier-6 series share a window and one you're NOT enrolled in can have an earlier
// date than yours, so that fixture wouldn't isolate "your" round. Here frontier_phase=1 only opens the
// tier-1 (rookie) series; harbor_trophy_6546 (docs/career/seasons/harbor_trophy_6546.json, round-1 day-of-year=55) is the
// earliest in that cohort (the rest: onyx_masters/garrowby_hex394 day 68, onyx_masters_12204/drift_masters_3348 days 74/75, ...) -> enrolled there,
// it's unambiguously the next reachable round.


// NextEventAbsDay: at year end, with all this year's openers already past, "next event" rolls to the first
// opener of the following year (a regression check on the year+1 fallback, which used to die by reusing this year's 'past' state).
// the year+1 fallback now RE-PROJECTS the 2026 calendar
// (ProjectSeason re-aligns the days-of-year per year -> RealignDoy), so the literal day 55 of 2025 is NO LONGER
// harbor_trophy_6546's real 2026 opener (it re-aligns to a different nearby day). And the landing now subtracts the
// winning series' footprint.lead — 0 for harbor_trophy_6546 (club level), so the value doesn't change for that reason,
// but it DOES change from the re-alignment. The expected day is computed from the same projector (ProjectSeason)
// instead of a hardcoded literal, so it doesn't go stale the next time the calendar gets re-curated.


// (time jumps): NextEventAbsDayForSeries (filtered to ONE series) and NextEventAbsDayOnOrAfter (a date
// selector) replicate EXACTLY the filter/landing of NextEventAbsDay (above), only the SELECTION criterion changes.
// REAL data (docs/series.psv + series_calendar.psv) — the calendar alone is enough to exercise
// BuildMasterCalendar+FootprintForSeries, without careerproof's full JSON.
// ivory_trophy_7202 is GATED by its qualifier (drift_masters_9129.unlocks=="ivory_trophy_7202" in series.psv) -> without its gate in
// unlocked_gates, BuildMasterCalendar blocks it ENTIRELY (gate_locked, career_calendar.cpp ~L234: gatePassed
// requires unlockedGates!=nullptr). That's why this test's gate set explicitly includes "ivory_trophy_7202" (the
// DESTINATION championship's id, not the qualifier's — that's how it's stored in SaveData::unlocked_gates, career_save.cpp).


// BUG reported in-game: "pick a date in the selector and the dialog says 'no race to jump to'".
// Cause: NextEventAbsDayOnOrAfter (above) only re-projected cc.year+1 as a fallback; the UI's date
// picker (<input type="date">, Calendar.tsx, with NO max attribute) lets you pick ANY date, so a
// target 2-3+ years out found no candidate in either of the two years checked and returned -1.
// (a) reproduces the bug with REAL data: target = Jan 1 of kStartYear+3. (b) non-regression: a target within the
// current year still returns EXACTLY what it did before (E == NextEventAbsDay, a property already covered
// in test_next_event_variants block (4) too, revalidated here after the fix). Same fixture as
// test_next_event_variants (series.psv + series_calendar.psv, ivory_trophy_7202's gate open).
static void test_next_event_onorafter_multiyear_bugfix() {
    using namespace career;
    CHECK(LoadSeries(TESTDATA("series.psv")));
    CHECK(LoadSeriesCalendar(TESTDATA("series_calendar.psv")));
    CareerCalendar cc; cc.year = kStartYear; cc.cursor_doy = 0;
    std::set<std::string> gates; gates.insert("ivory_trophy_7202");

    // (a) THE BUG: a target 3 years out (a date the year+1 fallback never reached) -> before the fix
    // returns -1; after the fix it must find the first reachable round of ANY series whose landing
    // (day-of-year - footprint.lead) falls on/after that date, no matter how many years it has to look.
    const int targetFar = career::dateutil::AbsDayFromYearDoy(kStartYear + 3, 1);
    int resultFar = NextEventAbsDayOnOrAfter(cc, targetFar, 7, &gates);
    CHECK(resultFar > 0);                 // BEFORE the fix: -1 (RED)
    CHECK(resultFar >= targetFar);        // selection criterion: the landing NEVER falls before the target
    int outYearFar = 0, outDoyFar = 0;
    career::dateutil::YearDoyFromAbsDay(resultFar, outYearFar, outDoyFar);
    CHECK(outYearFar >= kStartYear + 3);  // the result's year has to reach (or exceed) the target's

    // (b) NON-REGRESSION: target == the landing of a known GLOBAL event (E, same criterion as NextEventAbsDay)
    // within the current year -> still returns the SAME E (the current-year path doesn't change with this fix).
    int E = NextEventAbsDay(cc, 7, &gates);
    CHECK(E > 0);
    CHECK_EQ(NextEventAbsDayOnOrAfter(cc, E, 7, &gates), E);
}

// Capacity feature: NextEventAbsDayEnrolled — a variant of NextEventAbsDay that only counts series the
// player is ENROLLED in (s.enrolled), to distinguish "next available event" (NextEventAbsDay,
// any open series) from "next event you're enrolled in". Fixture with REAL data (same
// idiom as test_advance_to_next_event): frontier_phase=1 (only tier-1 rookie reachable), cursor_doy=20.
// harbor_trophy_6546 (round-1 day=55) is the EARLIEST opening of the WHOLE tier-1 cohort (verified against
// series.psv+series_calendar.psv: keystone_championship 102, beacon_cup 75, onyx_masters 68, lantern_masters_2733 96, drift_masters_3348 75,
// ember_trophy_3389 95, juniper_cup_3635 96, garrowby_hex394 68, harbor_trophy_6546 55, aurora_trophy_11261/granite_championship_11220 81, onyx_masters_12204 74) — so enrolling
// ONLY in onyx_masters_12204 (day=74, NOT the earliest), NextEventAbsDay (global) must return harbor_trophy_6546 (open, not
// enrolled, not past) while NextEventAbsDayEnrolled must return onyx_masters_12204 (the only enrolled series):
// a real divergence, not a fabricated one.


// ("Next available" was landing you somewhere you couldn't race): the NextEventAbsDay* family used to pick slots from
// CLOSED-grid series (series_access, SeriesDef.closed) with no contract — the jump led to an event
// the calendar's own launch check was going to reject (CanEnterSeries). The filter now shares that SAME predicate: a
// closed series is only a destination with an ACTIVE contract (or an existing enrollment); save==nullptr = fail-open (pure
// projections keep the previous behavior). Deterministic synthetic setup: two level-1 series with the CLOSED one opening
// BEFORE (day 100) the OPEN one (day 130); cursor past year 1's compressed decision week (same
// precaution measured in test_next_event_absday_enrolled — otherwise the destination would be the decision week itself).
static void test_jump_skips_closed_series_without_contract() {
    using namespace career;
    std::vector<SeriesDef> defs;
    { SeriesDef s; s.id = "t323_closed"; s.class_name = "GARROWBY_HEX394"; s.display = "Cerrada"; s.level = 1;
      s.kind = "champ"; s.closed = true;  s.rounds = 1; defs.push_back(s); }
    { SeriesDef s; s.id = "t323_open";   s.class_name = "GARROWBY_HEX394"; s.display = "Abierta"; s.level = 1;
      s.kind = "champ"; s.closed = false; s.rounds = 1; defs.push_back(s); }
    ReplaceSeries(defs);
    std::vector<CalRound> cal;
    { CalRound r; r.series_id = "t323_closed"; r.round = 1; r.doy = 100; r.track_name = "Pista A"; r.track_hash = 111; cal.push_back(r); }
    { CalRound r; r.series_id = "t323_open";   r.round = 1; r.doy = 130; r.track_name = "Pista B"; r.track_hash = 222; cal.push_back(r); }
    ReplaceCalendar(cal);

    CareerCalendar cc; cc.year = kStartYear;
    cc.cursor_doy = market::MarketY1DecisionDoy(kStartYear) + bal::MK_DECISION_WEEK_DAYS;
    std::set<std::string> gates;
    SaveData save;   // no contracts

    const int closedAbs = career::dateutil::AbsDayFromYearDoy(kStartYear, 100) - FootprintForSeries("t323_closed").lead;
    const int openAbs   = career::dateutil::AbsDayFromYearDoy(kStartYear, 130) - FootprintForSeries("t323_open").lead;

    // (a) no contract: the closed one is NOT a destination — falls back to the open one even though it opens later; asking for it explicitly
    // returns "no destination" (-1, the family's usual idiom); the schedule lookahead announces the OPEN one
    CHECK_EQ(NextEventAbsDay(cc, 1, &gates, &save), openAbs);
    CHECK_EQ(NextEventAbsDayOnOrAfter(cc, closedAbs, 1, &gates, &save), openAbs);
    CHECK_EQ(NextEventAbsDayForSeries(cc, "t323_closed", 1, &gates, &save), -1);
    { NextEventInfo inf = NextEventLookahead(save, cc, 1); CHECK(inf.track == "Pista B"); }

    // (b) with an ACTIVE contract for the closed one, it becomes the natural destination again (opens earlier)
    { Contract c; c.active = true; c.series_id = "t323_closed"; save.contracts.push_back(c); }
    CHECK_EQ(NextEventAbsDay(cc, 1, &gates, &save), closedAbs);
    CHECK_EQ(NextEventAbsDayForSeries(cc, "t323_closed", 1, &gates, &save), closedAbs);
    { NextEventInfo inf = NextEventLookahead(save, cc, 1); CHECK(inf.track == "Pista A"); }

    // (c) backward compat: with no save (nullptr) the access filter doesn't apply — fail-open, previous behavior
    CHECK_EQ(NextEventAbsDay(cc, 1, &gates, nullptr), closedAbs);

    // restore the real catalog for the rest of the suite (same idiom as the other fixtures in this section)
    CHECK(LoadSeries(TESTDATA("series.psv")));
    CHECK(LoadSeriesCalendar(TESTDATA("series_calendar.psv")));
    CHECK(LoadSeriesAccess(TESTDATA("series_access.psv")));
}

