// C1 (): each rule switched off lets ITS event through; switched on, it turns it into a stop. Pure: snapshot
// from before + save from after, no clock.
// 18/09 (Josh's decision) — the NORMAL market offer also warns the eve before it expires, as the window
// slots already did. It expires the day MK_OFFER_TTL_DAYS have elapsed since you saw it, so the eve
// is the day before. It stops with "offers" ticked; without it it stays in the summary. And only when it applies: not two days
// before, not if you declined it, not if you already signed that series, not with the market closed.
// 18/09 (Josh's decision) — THE STANDINGS ROW KNOWS WHO IT IS. There are two real Joao Barbosas
// (Brazilian and Portuguese) and resolving the row by name picked the first one (the Brazilian). The results already
// carried the id and the table threw it away; now it keeps it, and it survives save, load and rename.
static void test_standings_fila_con_id_homonimos() {
    using namespace career;
    Standings st; st.node_id = "gt3_test"; st.points_system = "f1_2019";
    RoundScore a; a.name = "Joao Barbosa"; a.driver_id = "rd_joao_barbosa_prt"; a.pos = 1; a.points = 25;
    RoundScore b; b.name = "Otro Piloto"; b.pos = 2; b.points = 18;   // no id: the row does not invent one
    ApplyRound(st, 1, { a, b });
    auto idDe = [](const std::vector<StandingRow>& t, const std::string& n) {
        for (const auto& r : t) if (r.name == n) return r.id; return std::string("?"); };
    CHECK(idDe(FinalTable(st), "Joao Barbosa") == "rd_joao_barbosa_prt");   // not the Brazilian by name
    CHECK(idDe(FinalTable(st), "Otro Piloto").empty());
    CHECK(idDe(StandingsTable(st), "Joao Barbosa") == "rd_joao_barbosa_prt");
    { bool ok = false; for (const auto& r : ChampStandings(st)) if (r.name == "Joao Barbosa") ok = (r.id == "rd_joao_barbosa_prt");
      CHECK(ok); }

    CHECK(SaveStandings(st, "build/test_standings_ids.sav"));
    Standings cargada; CHECK(LoadStandings(cargada, "build/test_standings_ids.sav"));
    CHECK(idDe(FinalTable(cargada), "Joao Barbosa") == "rd_joao_barbosa_prt");

    CHECK(RenameDriverInStandings(cargada, "Joao Barbosa", "J. Barbosa"));
    CHECK(idDe(FinalTable(cargada), "J. Barbosa") == "rd_joao_barbosa_prt");  // the id travels with the row
}

// 18/09 (Josh) — "when offers are about to expire, if they have not been explicitly rejected, the notification must be
// shown again plus a flag on each contract". An offer's deadline is computed in ONE place
// (OfferDeathAbs): the earliest of its TTL, its negotiation's deadline and the market close. The last day is
// decided by OffersOnLastDay, and on that day its mail goes back to unread.
static void test_offer_plazo_y_ultimo_dia() {
    using namespace career;
    const int anio = kStartYear + 2;
    const int ttl = bal::MK_OFFER_TTL_DAYS;
    const int sep = market::MarketWindowOpenDoy(anio) + 10;                 // market open, close far off
    const int hoy = career::dateutil::AbsDayFromYearDoy(anio, sep);

    // (1) the TTL: 28 days from when you saw it; unsealed, from today
    { SaveData s; s.offer_first_seen["of_gt4_test"] = hoy - 5;
      CHECK_EQ(OfferDeathAbs(s, "of_gt4_test", hoy), hoy - 5 + ttl);
      CHECK_EQ(OfferDeathAbs(s, "of_sin_ver", hoy), hoy + ttl); }

    // (2) a negotiation thread with a shorter deadline rules: NegoTick withdraws it the day AFTER the deadline
    { SaveData s; s.offer_first_seen["of_gt4_test"] = hoy - 5;
      Negotiation n; n.offer.id = "of_gt4_test"; n.state = NEGO_TH_COUNTERED; n.deadline_day = hoy + 3;
      s.negotiations.push_back(n);
      CHECK_EQ(OfferDeathAbs(s, "of_gt4_test", hoy), hoy + 4);
      // you shook hands: the signing reservation rules
      s.negotiations[0].state = NEGO_TH_ACCEPTED_PENDING; s.negotiations[0].reserve_day = hoy;
      CHECK_EQ(OfferDeathAbs(s, "of_gt4_test", hoy), hoy + 1);
      auto u = OffersOnLastDay(s, hoy);
      CHECK_EQ((long)u.size(), 1);
      // a CLOSED thread no longer sets a deadline
      s.negotiations[0].state = 10;
      CHECK_EQ(OfferDeathAbs(s, "of_gt4_test", hoy), hoy - 5 + ttl); }

    // (3) the market close: 31 December is the last day of EVERY live offer, even if you just saw it
    { const int fin = career::dateutil::DaysInYear(anio);
      CHECK_EQ(market::DaysToMarketClose(anio, fin, kStartYear), 1);
      CHECK_EQ(market::DaysToMarketClose(anio, fin - 1, kStartYear), 2);
      CHECK_EQ(market::DaysToMarketClose(anio, 100, kStartYear), 0);          // in mid-season it is already closed
      const int nochevieja = career::dateutil::AbsDayFromYearDoy(anio, fin);
      SaveData s; s.offer_first_seen["of_gt4_test"] = nochevieja - 1;
      CHECK_EQ(OfferDeathAbs(s, "of_gt4_test", nochevieja), nochevieja + 1);
      CHECK_EQ((long)OffersOnLastDay(s, nochevieja).size(), 1); }
    // year 1 closes at the end of its February decision week
    { const int y1 = market::MarketY1DecisionDoy(kStartYear);
      CHECK_EQ(market::DaysToMarketClose(kStartYear, 1, kStartYear), y1 + bal::MK_DECISION_WEEK_DAYS - 1); }

    // (4) who is on their last day: the eve yes, two days before no; not rejected, not withdrawn, not signed
    { SaveData s; s.offer_first_seen["of_gt4_test"] = hoy - (ttl - 1);
      CHECK_EQ((long)OffersOnLastDay(s, hoy).size(), 1);
      CHECK_EQ((long)OffersOnLastDay(s, hoy - 1).size(), 0);
      SaveData r = s; r.declined_offers.insert("of_gt4_test");  CHECK_EQ((long)OffersOnLastDay(r, hoy).size(), 0);
      SaveData w = s; w.withdrawn_offers.insert("of_gt4_test"); CHECK_EQ((long)OffersOnLastDay(w, hoy).size(), 0);
      SaveData f = s; Contract c; c.active = true; c.series_id = "gt4_test"; c.team_id = "Equipo"; f.contracts.push_back(c);
      CHECK_EQ((long)OffersOnLastDay(f, hoy).size(), 0);
      // left the market without expiring (someone else took the seat): with today's pulse in front, it does not count
      SaveData g = s; g.live_offers_day = hoy;                   CHECK_EQ((long)OffersOnLastDay(g, hoy).size(), 0);
      g.live_offer_ids.insert("of_gt4_test");                    CHECK_EQ((long)OffersOnLastDay(g, hoy).size(), 1);
      // ...but a pulse from ANOTHER day is no good for filtering
      SaveData h = s; h.live_offers_day = hoy - 1;               CHECK_EQ((long)OffersOnLastDay(h, hoy).size(), 1); }

    // (5) the warning: that day the offer's mail goes back to unread. Only that offer's, and only if unanswered.
    { SaveData s; s.offer_first_seen["of_gt4_test"] = hoy - (ttl - 1);
      auto correo = [](const char* id, const char* key) {
          GeneratedEmail e; e.id = id; e.family = 0; e.payload_key = key; e.read = 1; e.year = kStartYear + 2; return e; };
      s.emails.push_back(correo("offer_of_gt4_test", "of_gt4_test"));
      GeneratedEmail respondido = correo("offer_of_gt4_test_b", "of_gt4_test"); respondido.answered = 1; respondido.choice = 2;
      s.emails.push_back(respondido);
      s.emails.push_back(correo("renew_of_gt4_test", "of_gt4_test"));             // a renewal does not live in the market
      s.emails.push_back(correo("offer_of_otra", "of_otra"));                      // another offer, no rush
      CHECK_EQ(ReopenOfferMailsOnLastDay(s, hoy), 1);
      CHECK_EQ(s.emails[0].read, 0);
      CHECK_EQ(s.emails[1].read, 1);
      CHECK_EQ(s.emails[2].read, 1);
      CHECK_EQ(s.emails[3].read, 1);
      CHECK_EQ(ReopenOfferMailsOnLastDay(s, hoy), 0);                               // it was already unread
      // one day before touches nothing
      s.emails[0].read = 1;
      CHECK_EQ(ReopenOfferMailsOnLastDay(s, hoy - 1), 0);
      CHECK_EQ(s.emails[0].read, 1); }
}





