// in-game fix (bug 2a): the OFFER mail (Family A) freezes "negotiable" AT EMIT TIME, the SAME source as
// query.market (career::NegoNegotiable, career_nego_thread.cpp) -- tests both branches with fixtures
// built on each side of the real threshold (without repeating the bal::NEGO_IMPORTANCE_THRESH magic number: it
// compares against the predicate itself before emitting, so the test doesn't drift if the threshold changes).
static void test_inbox_offer_mail_negotiable_param() {
    career::SaveData s; s.mailnarr.onboard_stage = 3;
    std::vector<market::GenOffer> offers;
    { market::GenOffer go; go.def.id = "of_garrowby_hex394"; go.def.direct = true; go.def.team = "Aguila GT";
      go.def.perRace = 0; go.def.signBonus = 0; go.held = false; offers.push_back(go); }         // low economy -> NOT negotiable
    { market::GenOffer go; go.def.id = "of_gt6"; go.def.direct = true; go.def.team = "Halcon Racing";
      go.def.perRace = 10000; go.def.signBonus = 50000; go.held = false; offers.push_back(go); } // high economy -> IS negotiable
    CHECK(!career::NegoNegotiable(offers[0].def));    // guard: the fixture really does fall on each side of the threshold
    CHECK(career::NegoNegotiable(offers[1].def));
    career::EmailGenContext ctx; ctx.year = 2026;
    career::GenerateCareerEmails(s, offers, ctx);
    auto findParam = [&](const std::string& id, const std::string& key) -> std::string {
        for (const auto& e : s.emails) if (e.id == id)
            for (const auto& kv : career::MailParamsDecode(e.params)) if (kv.first == key) return kv.second;
        return std::string();
    };
    CHECK(findParam("offer_of_garrowby_hex394", "negotiable") == "0");
    CHECK(findParam("offer_of_gt6", "negotiable") == "1");
}

