// (c) SaveData.player round-trips through SaveCareer/LoadCareer; a save WITHOUT the player line -> empty identity.
static void test_player_identity_save() {
    using namespace career;
    const char* path = "build\\career_pid.sav";

    SaveData d;
    d.prog.credits = 12345;
    d.player.player_id   = "player";
    d.player.name        = "Josh Bowman-Vega";   // name WITH spaces (the pipe encoding must survive)
    d.player.nationality = "GBR";
    d.player.number      = 7;
    d.player.surname     = "Bowman-Vega";          // onboarding: the pipe block carries surname/sex/date + nationality
    d.player.sex         = "male";
    d.player.birth_year  = 1998; d.player.birth_month = 4; d.player.birth_day = 22;
    CHECK(SaveCareer(d, path));

    SaveData r;
    CHECK(LoadCareer(r, path));
    CHECK(r.player.player_id   == "player");
    CHECK(r.player.name        == "Josh Bowman-Vega");
    CHECK(r.player.nationality == "GBR");
    CHECK_EQ(r.player.number, 7);
    CHECK(r.player.surname     == "Bowman-Vega");   // the onboarding fields also round-trip alongside nationality
    CHECK(r.player.sex         == "male");
    CHECK_EQ(r.player.birth_year, 1998);
    CHECK_EQ(r.player.birth_month, 4);
    CHECK_EQ(r.player.birth_day, 22);
    CHECK_EQ(r.prog.credits, 12345);              // the rest of the save intact

    // back-compat: a save WITHOUT the 'player' line loads to an empty identity (doesn't break).
    const char* legacy = "build\\career_pid_legacy.sav";
    { FILE* f = fopen(legacy, "wb");
      fputs("version 1\r\ncredits 999\r\nrep 3\r\n", f); fclose(f); }
    SaveData L;
    CHECK(LoadCareer(L, legacy));
    CHECK(L.player.player_id.empty());
    CHECK(L.player.name.empty());
    CHECK(L.player.nationality.empty());
    CHECK_EQ(L.player.number, 0);
    CHECK_EQ(L.prog.credits, 999);                // known fields still load

    // a save without identity does NOT write the player line (byte-identical format to before) -> reloads empty
    SaveData empty; empty.prog.credits = 50;
    const char* noid = "build\\career_pid_noid.sav";
    CHECK(SaveCareer(empty, noid));
    SaveData back; CHECK(LoadCareer(back, noid));
    CHECK(back.player.name.empty());
    CHECK_EQ(back.prog.credits, 50);
}

// (d) RoundScore / ClassifiedEntry carry a driver_id field (compiles + propagates from Classify->ScoreRound).
static void test_driver_id_in_scoring() {
    using namespace career;
    std::vector<ParticipantSnap> grid;
    { ParticipantSnap p; p.name = "Alpha"; p.driver_id = "rd_alpha"; p.pos = 1; p.laps = 10;
      p.raceState = RS_FINISHED; p.active = true; grid.push_back(p); }
    { ParticipantSnap p; p.name = "Beta"; p.driver_id = "rd_beta"; p.pos = 2; p.laps = 10;
      p.raceState = RS_FINISHED; p.active = true; grid.push_back(p); }

    auto cls = Classify(grid);
    CHECK_EQ((long)cls.size(), 2);
    // ClassifiedEntry propagates driver_id from ParticipantSnap
    CHECK(cls[0].driver_id == "rd_alpha");
    CHECK(cls[1].driver_id == "rd_beta");

    PointsSystem sys; sys.points = {25,18};
    auto scores = ScoreRound(cls, sys, 1.0, /*flName=*/"");
    CHECK_EQ((long)scores.size(), 2);
    // RoundScore propagates driver_id from ClassifiedEntry (rides alongside; name is still the key)
    CHECK(scores[0].driver_id == "rd_alpha");
    CHECK(scores[0].name == "Alpha");
    CHECK(scores[1].driver_id == "rd_beta");
}

