#ifndef AMS2_PUBLIC_EXPORT_BUILD
static void test_wsf_handshake() {
    // official RFC6455 test vector
    std::string resp = wsf::BuildHandshakeResponse("dGhlIHNhbXBsZSBub25jZQ==");
    CHECK(resp.find("HTTP/1.1 101") == 0);
    CHECK(resp.find("Sec-WebSocket-Accept: s3pPLMBiTxaQ9kYGzzhZRbK+xOo=\r\n") != std::string::npos);
    CHECK(resp.rfind("\r\n\r\n") == resp.size() - 4);
    std::string req = "GET / HTTP/1.1\r\nHost: x\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n";
    CHECK(wsf::ExtractWebSocketKey(req) == "dGhlIHNhbXBsZSBub25jZQ==");
    CHECK(wsf::ExtractWebSocketKey("GET / HTTP/1.1\r\n\r\n") == "");
}
#endif

#ifndef AMS2_PUBLIC_EXPORT_BUILD
static void test_wsf_decode() {
    // RFC vector: "Hello" masked with {0x37,0xfa,0x21,0x3d}
    const uint8_t hello[] = {0x81,0x85,0x37,0xfa,0x21,0x3d,0x7f,0x9f,0x4d,0x51,0x58};
    std::string payload; uint8_t op = 0;
    CHECK_EQ(wsf::DecodeFrame(hello, sizeof(hello), payload, op), (int)sizeof(hello));
    CHECK(payload == "Hello");
    CHECK_EQ(op, 0x1);
    // incomplete buffer -> 0 (wait for more bytes)
    CHECK_EQ(wsf::DecodeFrame(hello, 5, payload, op), 0);
    CHECK_EQ(wsf::DecodeFrame(hello, 1, payload, op), 0);
    // unmasked client frame -> protocol error
    const uint8_t unmasked[] = {0x81,0x05,'H','e','l','l','o'};
    CHECK_EQ(wsf::DecodeFrame(unmasked, sizeof(unmasked), payload, op), -1);
    // 16-bit extended: 200 bytes with a null mask
    std::string frame; frame.push_back((char)0x81); frame.push_back((char)(0x80|126));
    frame.push_back((char)0); frame.push_back((char)200);
    frame.append(4, '\0'); frame.append(200, 'a');
    CHECK_EQ(wsf::DecodeFrame((const uint8_t*)frame.data(), frame.size(), payload, op), (int)frame.size());
    CHECK_EQ((int)payload.size(), 200);
    CHECK(payload[0] == 'a' && payload[199] == 'a');
    // close opcode passes through as-is
    const uint8_t closef[] = {0x88,0x80,0x01,0x02,0x03,0x04};
    CHECK_EQ(wsf::DecodeFrame(closef, sizeof(closef), payload, op), (int)sizeof(closef));
    CHECK_EQ(op, 0x8);
}
#endif

#ifndef AMS2_PUBLIC_EXPORT_BUILD
static void test_wsf_encode() {
    std::string f = wsf::EncodeFrame("Hello", 0x1);
    CHECK_EQ((int)f.size(), 7);
    CHECK_EQ((uint8_t)f[0], 0x81);
    CHECK_EQ((uint8_t)f[1], 0x05);
    CHECK(f.substr(2) == "Hello");
    // 16-bit extended
    std::string mid(300, 'b');
    std::string fm = wsf::EncodeFrame(mid, 0x1);
    CHECK_EQ((uint8_t)fm[1], 126);
    CHECK_EQ((((int)(uint8_t)fm[2]) << 8) | (int)(uint8_t)fm[3], 300);
    CHECK_EQ((int)fm.size(), 4 + 300);
    // empty close
    std::string fc = wsf::EncodeFrame("", 0x8);
    CHECK_EQ((uint8_t)fc[0], 0x88);
    CHECK_EQ((uint8_t)fc[1], 0);
    // round-trip encode->decode (re-masking by hand with a null key)
    std::string enc = wsf::EncodeFrame("roundtrip", 0x1);
    std::string masked; masked.push_back(enc[0]); masked.push_back((char)((uint8_t)enc[1] | 0x80));
    masked.append(4, '\0'); masked.append(enc.substr(2));
    std::string out2; uint8_t op2 = 0;
    CHECK_EQ(wsf::DecodeFrame((const uint8_t*)masked.data(), masked.size(), out2, op2), (int)masked.size());
    CHECK(out2 == "roundtrip");
}
#endif

#ifndef AMS2_PUBLIC_EXPORT_BUILD
static void test_ws_server_echo() {
    // real integration: server on an ephemeral port + a raw WinSock client
    WsServer srv;
    bool started = srv.Start(0, [&](const std::string& s) { srv.SendText("echo:" + s); });
    CHECK(started);
    CHECK(srv.Port() != 0);

    WSADATA wsa; WSAStartup(MAKEWORD(2, 2), &wsa);
    SOCKET c = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    DWORD tmo = 3000;
    setsockopt(c, SOL_SOCKET, SO_RCVTIMEO, (const char*)&tmo, sizeof(tmo));
    sockaddr_in a{}; a.sin_family = AF_INET; a.sin_port = htons(srv.Port());
    inet_pton(AF_INET, "127.0.0.1", &a.sin_addr);
    CHECK_EQ(connect(c, (sockaddr*)&a, sizeof(a)), 0);

    // HTTP upgrade handshake (key from the RFC vector)
    std::string req = "GET / HTTP/1.1\r\nHost: 127.0.0.1\r\nUpgrade: websocket\r\n"
                      "Connection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
                      "Sec-WebSocket-Version: 13\r\n\r\n";
    send(c, req.data(), (int)req.size(), 0);
    std::string resp; char buf[2048];
    while (resp.find("\r\n\r\n") == std::string::npos) {
        int n = recv(c, buf, sizeof(buf), 0);
        if (n <= 0) break;
        resp.append(buf, (size_t)n);
    }
    CHECK(resp.find("101") != std::string::npos);
    CHECK(resp.find("s3pPLMBiTxaQ9kYGzzhZRbK+xOo=") != std::string::npos);

    // masked text frame "hola" -> the server must return "echo:hola" unmasked
    const uint8_t mask[4] = {0x11, 0x22, 0x33, 0x44};
    std::string payload = "hola";
    std::string f; f.push_back((char)0x81); f.push_back((char)(0x80 | (uint8_t)payload.size()));
    f.append((const char*)mask, 4);
    for (size_t i = 0; i < payload.size(); ++i) f.push_back((char)(payload[i] ^ mask[i & 3]));
    send(c, f.data(), (int)f.size(), 0);

    std::string expected = "echo:hola";
    std::string in;
    while (in.size() < 2 + expected.size()) {
        int n = recv(c, buf, sizeof(buf), 0);
        if (n <= 0) break;
        in.append(buf, (size_t)n);
    }
    CHECK(in.size() >= 2 + expected.size());
    if (in.size() >= 2 + expected.size()) {
        CHECK_EQ((uint8_t)in[0], 0x81);
        CHECK_EQ((uint8_t)in[1], (int)expected.size());
        CHECK(in.substr(2, expected.size()) == expected);
    }
    CHECK(srv.HasClient());

    // client drops -> the server notices and frees the slot
    closesocket(c);
    for (int i = 0; i < 200 && srv.HasClient(); ++i) Sleep(10);
    CHECK(!srv.HasClient());
    srv.Stop();
    WSACleanup();
}
#endif

// Single-client robustness: a NEW connection evicts the previous one (the app reloaded/reopened) instead
// of being rejected. Before this, reconnecting after an HMR reload used to get stuck at "no connection" until the
// old socket timed out. Here: A connects+handshakes; B connects+handshakes -> B wins, A gets closed.
#ifndef AMS2_PUBLIC_EXPORT_BUILD
static void test_ws_server_new_client_wins() {
    WsServer srv;
    CHECK(srv.Start(0, [&](const std::string& s) { srv.SendText("echo:" + s); }));
    CHECK(srv.Port() != 0);
    WSADATA wsa; WSAStartup(MAKEWORD(2, 2), &wsa);

    auto hsConnect = [&](uint16_t port) -> SOCKET {
        SOCKET s = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        DWORD tmo = 3000; setsockopt(s, SOL_SOCKET, SO_RCVTIMEO, (const char*)&tmo, sizeof(tmo));
        sockaddr_in a{}; a.sin_family = AF_INET; a.sin_port = htons(port);
        inet_pton(AF_INET, "127.0.0.1", &a.sin_addr);
        if (connect(s, (sockaddr*)&a, sizeof(a)) != 0) { closesocket(s); return INVALID_SOCKET; }
        std::string req = "GET / HTTP/1.1\r\nHost: 127.0.0.1\r\nUpgrade: websocket\r\n"
                          "Connection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
                          "Sec-WebSocket-Version: 13\r\n\r\n";
        send(s, req.data(), (int)req.size(), 0);
        std::string resp; char b[2048];
        while (resp.find("\r\n\r\n") == std::string::npos) {
            int n = recv(s, b, sizeof(b), 0); if (n <= 0) break; resp.append(b, (size_t)n);
        }
        if (resp.find("101") == std::string::npos) { closesocket(s); return INVALID_SOCKET; }
        return s;
    };
    auto sendMasked = [](SOCKET s, const std::string& payload) {
        const uint8_t mask[4] = {0x11, 0x22, 0x33, 0x44};
        std::string f; f.push_back((char)0x81); f.push_back((char)(0x80 | (uint8_t)payload.size()));
        f.append((const char*)mask, 4);
        for (size_t i = 0; i < payload.size(); ++i) f.push_back((char)(payload[i] ^ mask[i & 3]));
        send(s, f.data(), (int)f.size(), 0);
    };

    SOCKET A = hsConnect(srv.Port());
    CHECK(A != INVALID_SOCKET);
    for (int i = 0; i < 200 && !srv.HasClient(); ++i) Sleep(10);
    CHECK(srv.HasClient());

    // second client connects -> must WIN the slot (evict A, adopt B)
    SOCKET B = hsConnect(srv.Port());
    CHECK(B != INVALID_SOCKET);
    for (int i = 0; i < 200 && !srv.HasClient(); ++i) Sleep(10);
    CHECK(srv.HasClient());

    // B is the active client: its frame comes back as an echo
    sendMasked(B, "bee");
    std::string expected = "echo:bee"; std::string in; char buf[2048];
    for (int i = 0; i < 200 && in.size() < 2 + expected.size(); ++i) {
        int n = recv(B, buf, sizeof(buf), 0); if (n > 0) in.append(buf, (size_t)n); else break;
    }
    CHECK(in.size() >= 2 + expected.size());
    if (in.size() >= 2 + expected.size()) CHECK(in.substr(2, expected.size()) == expected);

    // A was evicted: the server closed its socket -> recv returns 0 (EOF)
    int na = recv(A, buf, sizeof(buf), 0);
    CHECK(na <= 0);

    closesocket(A); closesocket(B);
    srv.Stop(); WSACleanup();
}
#endif

static void test_jsonw() {
    jsonw::Writer w;
    w.BeginObject();
    w.KS("a", "x\"y\\z\n");
    w.KI("n", 42);
    w.KN("d", 1.5);
    w.KB("t", true);
    w.Key("arr"); w.BeginArray(); w.I(1); w.I(2); w.EndArray();
    w.Key("o"); w.BeginObject(); w.KS("k", "v"); w.EndObject();
    w.EndObject();
    // what was written must re-parse with json_min and keep its values
    auto v = jsonm::Parse(w.Str());
    CHECK(v && v->isObject());
    CHECK(v->memberString("a") == "x\"y\\z\n");
    CHECK_EQ(v->memberInt("n"), 42);
    CHECK(v->memberNumber("d") == 1.5);
    CHECK(v->memberBool("t"));
    const jsonm::Value* arr = v->member("arr");
    CHECK(arr && arr->isArray() && arr->arr.size() == 2 && arr->arr[1]->asInt() == 2);
    CHECK(v->member("o") && v->member("o")->memberString("k") == "v");
}
