    if (!g_apiqInstalled) return;
    career::ReplaceSeries(g_apiqSeriesBackup);
    capi::SetCareerStateProvider(nullptr);
    capi::SetProfileViewProvider(nullptr);
    capi::SetMemoriesInputsProvider(nullptr);
