// cmd.identity.submit -- handler validates the gate (first>=2, last>=2, sex, nat, DOB) + synthetic executor.
static void test_api_cmd_identity() {
    static std::string s_first, s_last, s_sex, s_nat; static int s_y, s_m, s_d; static bool s_called;
    s_first.clear(); s_last.clear(); s_sex.clear(); s_nat.clear(); s_y = s_m = s_d = 0; s_called = false;
    capi::SetIdentityCmds([](const std::string& f, const std::string& l, const std::string& sx, const std::string& n, int y, int m, int d) {
        s_first = f; s_last = l; s_sex = sx; s_nat = n; s_y = y; s_m = m; s_d = d; s_called = true; return true; });
    capi::ApiCore core; capi::RegisterCareerQueries(core);
    // valid -> ok + executor receives everything
    auto rv = apiq_call(core, "cmd.identity.submit", "{\"first\":\"Alex\",\"last\":\"Bravo\",\"sex\":\"male\",\"nationality\":\"BR\",\"year\":1998,\"month\":5,\"day\":12}");
    CHECK(rv && rv->memberString("kind") == "result" && rv->member("payload")->memberBool("ok"));
    CHECK(s_called && s_first == "Alex" && s_last == "Bravo" && s_sex == "male" && s_nat == "BR" && s_y == 1998 && s_m == 5 && s_d == 12);
    // short name -> bad_params
    auto rb = apiq_call(core, "cmd.identity.submit", "{\"first\":\"A\",\"last\":\"Bravo\",\"sex\":\"male\",\"nationality\":\"BR\",\"year\":1998,\"month\":5,\"day\":12}");
    CHECK(rb && rb->memberString("kind") == "error" && rb->memberString("code") == "bad_params");
    // invalid sex -> bad_params
    auto rs = apiq_call(core, "cmd.identity.submit", "{\"first\":\"Alex\",\"last\":\"Bravo\",\"sex\":\"x\",\"nationality\":\"BR\",\"year\":1998,\"month\":5,\"day\":12}");
    CHECK(rs && rs->memberString("code") == "bad_params");
    // incomplete DOB -> bad_params
    auto rd = apiq_call(core, "cmd.identity.submit", "{\"first\":\"Alex\",\"last\":\"Bravo\",\"sex\":\"male\",\"nationality\":\"BR\",\"year\":1998,\"month\":0,\"day\":12}");
    CHECK(rd && rd->memberString("code") == "bad_params");
    // no executor -> not_ready
    capi::SetIdentityCmds(nullptr);
    auto rn = apiq_call(core, "cmd.identity.submit", "{\"first\":\"Alex\",\"last\":\"Bravo\",\"sex\":\"male\",\"nationality\":\"BR\",\"year\":1998,\"month\":5,\"day\":12}");
    CHECK(rn && rn->memberString("code") == "not_ready");
}

// Inbox commands -- injected executor (SetMarketCmds pattern), typed errors.
// Note: ApiCore's error envelope is FLAT (code sits alongside "kind", not nested under "error" -- see MakeError
// in career_api_core.cpp and the pattern used by test_api_queries_not_ready); read via r->memberString("code").
static void test_capi_inbox_cmds() {
    static career::SaveData s_save; s_save = career::SaveData{};
    { career::GeneratedEmail e; e.id = "m1"; e.family = 1; s_save.emails.push_back(e); }
    static int saves = 0; saves = 0;
    capi::SetInboxCmds(
        [](const std::string& id) { bool ch = career::MailMarkRead(s_save, id); if (ch) saves++; return true; },
        [](const std::string& id, int choice) { int rc = career::MailAnswer(s_save, id, choice); if (rc == 0) saves++; return rc; });
    capi::ApiCore core; capi::RegisterCareerQueries(core);
    auto r1 = apiq_call(core, "cmd.inbox.markRead", "{\"id\":\"m1\"}");
    CHECK(r1 && r1->memberString("kind") == "result");
    CHECK_EQ(s_save.emails[0].read, 1);
    CHECK_EQ(saves, 1);
    auto r2 = apiq_call(core, "cmd.inbox.markRead", "{\"id\":\"m1\"}");   // idempotent: ok, without re-saving
    CHECK(r2 && r2->memberString("kind") == "result");
    CHECK_EQ(saves, 1);
    auto r3 = apiq_call(core, "cmd.inbox.answer", "{\"id\":\"m1\",\"choice\":0}");
    CHECK(r3 && r3->memberString("kind") == "error");                     // family with no actions
    CHECK(r3 && r3->memberString("code") == "not_answerable");
    auto r4 = apiq_call(core, "cmd.inbox.answer", "{\"id\":\"zz\",\"choice\":0}");
    CHECK(r4 && r4->memberString("code") == "not_found");
    capi::SetInboxCmds(nullptr, nullptr);   // cleans up for other tests
}

// 18/09 — "mark all as read": marks them all, says how many, and the exec saves ONCE (none if there
// was nothing). Without exec, not_ready like the rest of the inbox commands.
static void test_capi_inbox_mark_all() {
    static career::SaveData s_save; s_save = career::SaveData{};
    for (const char* id : { "a", "b", "c" }) { career::GeneratedEmail e; e.id = id; e.family = 1; s_save.emails.push_back(e); }
    s_save.emails[1].read = 1;                                  // one already read
    static int saves = 0; saves = 0;
    capi::ApiCore core; capi::RegisterCareerQueries(core);
    capi::SetInboxMarkAllCmd(nullptr);
    auto r0 = apiq_call(core, "cmd.inbox.markAllRead", "{}");
    CHECK(r0 && r0->memberString("code") == "not_ready");
    capi::SetInboxMarkAllCmd([]() { int n = career::MailMarkAllRead(s_save); if (n > 0) saves++; return n; });
    auto r1 = apiq_call(core, "cmd.inbox.markAllRead", "{}");
    CHECK(r1 && r1->memberString("kind") == "result");
    const jsonm::Value* p1 = r1 ? r1->member("payload") : nullptr;
    CHECK(p1 && p1->memberInt("marked", -1) == 2);             // two unread
    for (const auto& e : s_save.emails) CHECK_EQ(e.read, 1);
    CHECK_EQ(saves, 1);                                         // one save for both
    auto r2 = apiq_call(core, "cmd.inbox.markAllRead", "{}");   // again: nothing to mark, nothing to save
    const jsonm::Value* p2 = r2 ? r2->member("payload") : nullptr;
    CHECK(p2 && p2->memberInt("marked", -1) == 0);
    CHECK_EQ(saves, 1);
    capi::SetInboxMarkAllCmd(nullptr);
}

