// Bridge: query.inbox interleaves the thread -- persisted emails gain negId/you:false
// and the PLAYER's proposals (who=0/kind=0 in negotiations[].history) are SYNTHESIZED when serving,
// never persisted as an email (calling it twice doesn't grow save.emails). Harness: the same synthetic
// CareerStateProvider (CareerStateView.loaded/save/calendar) the apiq_* tests use (grep "QueryInbox" -> this pattern).
static void test_capi_inbox_thread() {
    static career::SaveData s_save;
    static career::CareerCalendar s_cal;
    s_save = career::SaveData{};
    s_cal = career::CareerCalendar{};
    s_cal.year = 2025; s_cal.cursor_doy = 50;
    // Realistic neg_id -- the engine builds it as "neg_"+offer.id+"_"+year+"_"+absDay (two trailing
    // numeric groups, see career_nego_thread.cpp). absDay = 2025*365+35 = 739160.
    const std::string NEG = "neg_of_x_2025_739160";
    // 1 persisted email with a thread (the team's response, exactly as EmitNegoMail leaves it)
    { career::GeneratedEmail e; e.id = NEG + "_counter_r1"; e.day = 40; e.family = career::NEGO_MAIL_FAMILY;
      e.payload_key = "nego_counter"; e.variant = 0; e.neg_id = NEG;
      s_save.emails.push_back(e); }
    // 1 negotiation with 1 history round: who=0/kind=0 = a proposal SENT by the player
    { career::Negotiation n; n.neg_id = NEG; n.offer.id = "of_x"; n.offer.team = "Falcon Racing";
      career::NegoRoundLog h; h.day = 2025 * 365 + 35; h.who = 0; h.kind = 0;   // absolute day (continuous clock)
      n.history.push_back(h);
      s_save.negotiations.push_back(n); }
    // a thread with NO persisted email (pruned/purged, e.g. after rollover) -> the guard must
    // skip it entirely; without that, this "sent by the player" round would render an orphaned "you" entry.
    { career::Negotiation n; n.neg_id = "neg_of_orphan_2025_739160"; n.offer.id = "of_orphan"; n.offer.team = "Orphan Racing";
      career::NegoRoundLog h; h.day = 2025 * 365 + 35; h.who = 0; h.kind = 0;
      n.history.push_back(h);
      s_save.negotiations.push_back(n); }
    capi::SetCareerStateProvider([]() {
        capi::CareerStateView v;
        v.loaded = true; v.save = &s_save; v.calendar = &s_cal; v.playerName = "Alex Bravo";
        return v;
    });
    capi::HandlerResult r = capi::QueryInbox(nullptr);
    CHECK(r.ok);
    CHECK(r.payload.find("\"negId\":\"neg_of_x_2025_739160\"") != std::string::npos);   // persisted email + synthetic entry
    // offerId is taken from the LIVE negotiation by neg_id (it cannot be derived client-side from neg_id).
    // Appears in BOTH: the thread's persisted email AND the synthetic "you" entry.
    CHECK(r.payload.find("\"offerId\":\"of_x\"") != std::string::npos);
    CHECK(r.payload.find("\"you\":true") != std::string::npos);                 // synthesized player entry
    CHECK(r.payload.find("\"kind\":\"nego\"") != std::string::npos);            // MailKind(3) -> "nego"
    CHECK(r.payload.find("\"id\":\"neg_of_x_2025_739160_you_r1\"") != std::string::npos);
    CHECK(r.payload.find("\"from\":\"inbox_you\"") != std::string::npos);
    CHECK(r.payload.find("\"subject\":\"nego_you_subj\"") != std::string::npos);
    CHECK(r.payload.find("\"body\":\"nego_you\"") != std::string::npos);
    CHECK(r.payload.find("\"series\":\"") != std::string::npos);               // {series} param in nego_you_subj
    // with no persisted email for "of_orphan" -> neither its negId nor its "you" entry (nor offerId) show up
    CHECK(r.payload.find("neg_of_orphan_2025") == std::string::npos);
    CHECK(r.payload.find("of_orphan") == std::string::npos);
    // synthesis does NOT persist (same no-persist rule as elsewhere): 2 more calls and save.emails doesn't grow
    size_t before = s_save.emails.size();
    capi::QueryInbox(nullptr);
    capi::QueryInbox(nullptr);
    CHECK(s_save.emails.size() == before);
    capi::SetCareerStateProvider(nullptr);   // cleans up so it doesn't interfere with other tests (test_api_queries_not_ready)
}

// fix for "nonsensical date on an email when crossing into a new year" (auditing the OTHER emitter, career_api_queries.cpp
// this time): the SYNTHESIZED "you" entries in a negotiation thread's history (NegoRoundLog.h.day)
// carry their OWN real absolute date (career_dateutil, not an approximate year*365+doy) -- before this fix the
// emitter ignored that data and rendered the calendar's CURRENT year (cal.year), the SAME underlying bug as
// GeneratedEmail.day, but here on a structure that ALREADY carried the year with it (h.day is absolute), needing
// no new field at all -- just stop discarding it and derive it with dateutil::YearDoyFromAbsDay.
static void test_capi_inbox_nego_you_year_from_own_date() {
    static career::SaveData s_save; static career::CareerCalendar s_cal;
    s_save = career::SaveData{}; s_cal = career::CareerCalendar{};
    s_cal.year = 2027; s_cal.cursor_doy = 50;              // "today": the CURRENT year, much later than the proposal's
    int absDay = career::dateutil::AbsDayFromYearDoy(2025, 35);   // the actual proposal was made in 2025, doy 35
    const std::string NEG = "neg_of_yy_2025_" + std::to_string(absDay);
    { career::GeneratedEmail e; e.id = NEG + "_counter_r1"; e.day = 40; e.family = career::NEGO_MAIL_FAMILY;
      e.payload_key = "nego_counter"; e.variant = 0; e.neg_id = NEG;
      s_save.emails.push_back(e); }
    { career::Negotiation n; n.neg_id = NEG; n.offer.id = "of_yy"; n.offer.team = "Falcon Racing";
      career::NegoRoundLog h; h.day = absDay; h.who = 0; h.kind = 0;
      n.history.push_back(h);
      s_save.negotiations.push_back(n); }
    capi::SetCareerStateProvider([]() {
        capi::CareerStateView v;
        v.loaded = true; v.save = &s_save; v.calendar = &s_cal; v.playerName = "Alex Bravo";
        return v;
    });
    capi::HandlerResult r = capi::QueryInbox(nullptr);
    CHECK(r.ok);
    jsonm::ValuePtr p = jsonm::Parse(r.payload);
    const jsonm::Value* ms = p ? p->member("messages") : nullptr;
    const jsonm::Value* found = nullptr;
    if (ms && ms->isArray())
        for (auto& mv : ms->arr)
            if (mv->memberBool("you") && mv->memberString("id") == (NEG + "_you_r1")) { found = mv.get(); break; }
    CHECK(found != nullptr);
    // the proposal was made in 2025 -- it must report 2025, NEVER the current year (2027, cal.year).
    if (found) { CHECK_EQ(found->memberInt("year"), 2025); CHECK_EQ(found->memberInt("week"), 5); }   // doy 35 -> week 5
    capi::SetCareerStateProvider(nullptr);
}

