// the offer email carries offerId (opens the embedded composer) and deadlineWeeks (TTL).
static void test_capi_inbox_offer_fields() {
    static career::SaveData s_save; static career::CareerCalendar s_cal;
    s_save = career::SaveData{}; s_cal = career::CareerCalendar{};
    // 09/08: the clock moves from day 40 (Feb 9) to day 300 (Oct 27) because day 40 falls in a CLOSED MARKET, and an
    // offer with the market closed no longer offers anything (MailOfferExpired). The fixture's date was arbitrary --
    // what this test checks is that a LIVE offer email carries offerId and deadlineWeeks, so it's
    // given a date INSIDE the signing window, which is when a live offer can exist. The
    // out-of-window case is covered at the end of this same test, which nobody used to check before.
    s_cal.year = 2026; s_cal.cursor_doy = 300;
    { career::GeneratedEmail e; e.id = "offer_of_gt3"; e.family = 0; e.payload_key = "of_gt3";
      // offerId now requires the "negotiable"=="1" param (a strict gate) -- this email
      // simulates an offer already patched up by the sync, with the gate open.
      e.params = career::MailParamsEncode({{"negotiable", "1"}});
      e.year = 2026;   // the year the email ARRIVED: that's what decides whether its window has already closed
      s_save.emails.push_back(e); }
    s_save.offer_first_seen["of_gt3"] = career::NegoAbsDay(2026, 290);   // viewed 10 days ago (TTL 28 -> about 2-3 weeks left)
    { career::GeneratedEmail e; e.id = "court_y_2026"; e.family = 0; e.payload_key = "courting";
      e.subtype = career::bal::MK_MAIL_SUBTYPE_COURTING; s_save.emails.push_back(e); }
    capi::SetCareerStateProvider([]() {
        capi::CareerStateView v; v.loaded = true; v.save = &s_save; v.calendar = &s_cal;
        v.playerName = "Alex"; return v; });
    capi::HandlerResult r = capi::QueryInbox(nullptr);
    CHECK(r.ok);
    CHECK(r.payload.find("\"offerId\":\"of_gt3\"") != std::string::npos);
    CHECK(r.payload.find("\"deadlineWeeks\":") != std::string::npos);
    CHECK(r.payload.find("\"nav\":\"market\"") != std::string::npos);   // courtship -> CTA to Market
    // A decline made from the MARKET (declined_offers) turns off Negotiate+chip
    // instantly, even if the email hasn't been answered (MailActionsFor becomes empty -> the gate closes).
    s_save.declined_offers.insert("of_gt3");
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"offerId\"") == std::string::npos);
    CHECK(r.payload.find("\"deadlineWeeks\"") == std::string::npos);
    s_save.declined_offers.clear();   // restores it for the "answered" case below
    // the answered one loses offerId/deadline (there's nothing left to act on)
    s_save.emails[0].answered = 1; s_save.emails[0].choice = 2;
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"offerId\"") == std::string::npos);
    CHECK(r.payload.find("\"deadlineWeeks\"") == std::string::npos);

    // 09/08 -- AN EXPIRED OFFER SAYS SO, AND STOPS OFFERING THE BUTTON. A player reported that the email
    // kept showing "Accept" long after the offer stopped being valid, so pressing it did nothing and there was
    // no way to know why. The four expiry paths, each through its own route (see MailOfferExpired).
    s_save.emails[0].answered = 0; s_save.emails[0].choice = 0;   // back to unanswered
    // (1) deadline elapsed (TTL) -- sealed by LapseExpiredOffers when the clock ticks
    s_save.lapsed_offers.insert("of_gt3");
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"expired\":true") != std::string::npos);   // SAYS so
    CHECK(r.payload.find("\"expiredReason\":\"lapsed\"") != std::string::npos);   // and says WHY
    CHECK(r.payload.find("\"actions\"") == std::string::npos);        // and offers no button
    CHECK(r.payload.find("\"offerId\"") == std::string::npos);        // nor the negotiate CTA
    CHECK_EQ(career::MailAnswer(s_save, "offer_of_gt3", 1), 3);       // answering it returns not_answerable
    s_save.lapsed_offers.clear();
    // (2) its season has already started (you let it pass)
    s_save.expired_offers.insert("of_gt3");
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"expiredReason\":\"season_started\"") != std::string::npos);
    s_save.expired_offers.clear();
    // (3) the team withdrew it -- it's neither your fault nor the clock's, so it's counted separately
    s_save.withdrawn_offers.insert("of_gt3");
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"expiredReason\":\"withdrawn\"") != std::string::npos);
    s_save.withdrawn_offers.clear();
    // (4) ITS WINDOW HAS ALREADY CLOSED: the email is from a season EARLIER than the clock's.
    //     The criterion is the email's YEAR, NOT the market phase. The first version checked the phase, and that
    //     flagged as expired ANY pending offer during the eight months the market stays closed --
    //     even a brand-new one. A player noticed right away: "now everything comes up expired for me". The two
    //     checks below are what stop that from slipping through again.
    s_cal.year = 2027;                                                // the clock advances a year...
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"expiredReason\":\"window_over\"") != std::string::npos);   // ...and the 2026 one dies
    CHECK(r.payload.find("\"actions\"") == std::string::npos);
    // CHECK 1: with the market CLOSED (February) but the offer from THIS SAME year, it does NOT expire. This is
    //   exactly the case the phase-based version broke, and the one that triggered the report.
    s_cal.year = 2026; s_cal.cursor_doy = 40;                         // February 9: market closed
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"expired\":true") == std::string::npos);   // still alive
    CHECK(r.payload.find("\"actions\"") != std::string::npos);        // with its buttons too
    // CHECK 2: a reason belonging to the offer itself overrides the calendar's.
    s_cal.year = 2027;
    s_save.lapsed_offers.insert("of_gt3");
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"expiredReason\":\"lapsed\"") != std::string::npos);
    s_save.lapsed_offers.clear();
    // ...and back in its own year the offer comes alive again: expiry reason (4) is NOT a sticky save state.
    s_cal.year = 2026; s_cal.cursor_doy = 300;
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"expired\":true") == std::string::npos);
    CHECK(r.payload.find("\"actions\"") != std::string::npos);
    // and DECLINING isn't expiring: it has its own outcome and must not read as "you missed the deadline".
    s_save.declined_offers.insert("of_gt3");
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("\"expired\":true") == std::string::npos);
    s_save.declined_offers.clear();

    // THE SILENT EMAIL (reported 09/08 with a real Greywick Motors email). When the offer vanishes from the
    // live market, the sync closes it with answered=1 and choice left at 0 (career_contract.cpp). That is NOT
    // a decision the player made, yet it used to switch off all three surfaces at once: no buttons (because of answered), no
    // outcome (MailResolvedKey only maps choice 1/2), and no expiry notice (the answered guard used to
    // discard it). The email would sit blank and look broken. On top of that, rollover clears lapsed/expired/
    // withdrawn every year, so one that survives the year change doesn't even keep its specific reason:
    // hence the need for a last resort that at least says it's gone.
    {
        career::GeneratedEmail mudo;
        mudo.id = "offer_of_greywick_motors"; mudo.family = 0; mudo.payload_key = "of_greywick_motors";
        mudo.answered = 1; mudo.choice = 0;             // closed by the sync, no decision made
        s_save.emails.push_back(mudo);
        r = capi::QueryInbox(nullptr);
        CHECK(r.payload.find("\"expiredReason\":\"gone\"") != std::string::npos);   // no longer sits silent
        // ...and a REAL decision still keeps its own outcome, which is NOT an expiry.
        s_save.emails.back().choice = 2;                // rejected by the player
        r = capi::QueryInbox(nullptr);
        CHECK(r.payload.find("\"expiredReason\":\"gone\"") == std::string::npos);
        s_save.emails.pop_back();
    }

    // WHAT THIS FIX MUST NOT BREAK: RENEWAL. It doesn't live in the market -- it's signed on top of your
    // current contract, and the final one arrives in JANUARY, with the market shut tight. If expiry reason
    // (4) applied to it, it would remove the button at the one moment it actually matters, and the player would
    // be left never able to renew. It's checked on the worst possible day: February, market closed.
    s_cal.cursor_doy = 40;
    { career::GeneratedEmail e; e.id = "renew_of_gt3_2027"; e.family = 0; e.payload_key = "of_gt3_ren";
      s_save.emails.push_back(e); }
    r = capi::QueryInbox(nullptr);
    CHECK(r.payload.find("renew_of_gt3_2027") != std::string::npos);
    CHECK(r.payload.find("\"actions\"") != std::string::npos);   // renewal STILL offers its buttons
    CHECK_EQ(career::MailAnswer(s_save, "renew_of_gt3_2027", 1), 0);   // and can genuinely be answered
    s_save.emails.pop_back();
    s_cal.cursor_doy = 300;
    capi::SetCareerStateProvider(nullptr);
}

// "negotiable" is a STRICT GATE on offerId (negotiation composer, the "Negotiate"
// CTA) -- "1" opens it; "0" or ABSENT (an email issued before the fix, not yet patched by the sync
// step) closes it. Accept/Decline (MailActionsFor) NEVER depend on this param and stay live in all three cases.
static void test_capi_inbox_offer_negotiable_gate() {
    static career::SaveData s_save; static career::CareerCalendar s_cal;
    s_save = career::SaveData{}; s_cal = career::CareerCalendar{};
    s_cal.year = 2026; s_cal.cursor_doy = 300;   // 09/08: inside the window (see the note in the test above)
    { career::GeneratedEmail e; e.id = "offer_of_neg"; e.family = 0; e.payload_key = "of_neg";
      e.params = career::MailParamsEncode({{"negotiable", "1"}}); s_save.emails.push_back(e); }
    { career::GeneratedEmail e; e.id = "offer_of_nonneg"; e.family = 0; e.payload_key = "of_nonneg";
      e.params = career::MailParamsEncode({{"negotiable", "0"}}); s_save.emails.push_back(e); }
    { career::GeneratedEmail e; e.id = "offer_of_legacy"; e.family = 0; e.payload_key = "of_legacy";
      s_save.emails.push_back(e); }   // an OLD email, issued before the fix -> still without the param
    capi::SetCareerStateProvider([]() {
        capi::CareerStateView v; v.loaded = true; v.save = &s_save; v.calendar = &s_cal;
        v.playerName = "Alex"; return v; });
    capi::HandlerResult r = capi::QueryInbox(nullptr);
    CHECK(r.ok);
    CHECK(r.payload.find("\"offerId\":\"of_neg\"") != std::string::npos);
    CHECK(r.payload.find("\"offerId\":\"of_nonneg\"") == std::string::npos);
    CHECK(r.payload.find("\"offerId\":\"of_legacy\"") == std::string::npos);
    capi::SetCareerStateProvider(nullptr);
}

