    // start -> {ok, launched}
    s_ret = true;
    auto rs = apiq_call(core, "cmd.tryout.start", "{}");
    CHECK(rs && rs->member("payload")->memberBool("ok") && rs->member("payload")->memberBool("launched") && s_started);
    // clear -> {ok}
    auto rc = apiq_call(core, "cmd.tryout.clear", "{}");
    CHECK(rc && rc->member("payload")->memberBool("ok") && s_cleared);
