// query.race_config (debug): the last launch's handoff travels RAW -- untranslated engine sentinels
// (the app decides what counts as "Inherited") -- and the `inherited` tokens are the SAME ones query.settings uses. With no
// provider (or no launch this session) -> not_ready, which is how the UI knows there's nothing to render.


// query.telemetry.race had NO test with an assertion at all --
// it was only exercised through --dump-api-fixtures. The central invariant here (aiBase+trim==
// aiEffective when `signal.valid`) and the two new/fixed keys (classAi, windowN) were left with no
// safety net. Reuses the same synthetic stub (g_apiqTelemetryView) that builds the fixture.
static void test_api_queries_telemetry_race() {
    apiq_install_state();
    capi::ApiCore core; capi::RegisterCareerQueries(core);
    auto r = apiq_call(core, "query.telemetry.race");
    CHECK(r && r->memberString("kind") == "result");
    const jsonm::Value* p = r ? r->member("payload") : nullptr;
    CHECK(p && p->isObject());
    if (!p) return;
    // (there's no "loaded" key in the payload: not_ready already filters it above -- kind=="result" is the proof)
    CHECK(p->memberString("raceId") == "gt3_sprint#4");
    const jsonm::Value* d = p->member("difficulty");
    CHECK(d && d->isObject());
    if (d) {
        // the invariant validated here: in the `signal.valid` case (see below) base+trim has to
        // equal effective EXACTLY -- if anyone ever decouples the two numbers, this check screams.
        CHECK_EQ(d->memberInt("base") + d->memberInt("trim"), d->memberInt("effective"));
        CHECK_EQ(d->memberInt("classAi"), 93);     // the category's absolute value after the race
        CHECK_EQ(d->memberInt("windowN"), 5);      // the CATEGORY's window, not the dead recent_gap buffer
        CHECK(fabs(d->memberNumber("classDelta") - 1.25) < 1e-9);   // delta vs. the overall figure, not an absolute
    }
    const jsonm::Value* sig = p->member("signal");
    CHECK(sig && sig->memberBool("valid"));   // the case that makes the identity above enforceable
}

