// query.cards -- handler called DIRECTLY (no ApiCore), like the
// rest of the thin handlers: no provider -> not_ready. With a provider, the signed card travels with its FULL
// DEF embedded (the real career::CARD_DEFS catalog, the app does NOT hardcode it) + its live state (level/slot/
// life/upgrade/sale/fx); the shop offer also embeds its DEF. slotsUnlocked = CardSlotsUnlocked(phase).
static void test_query_cards_handler() {
    using namespace career;
    capi::SetCardsViewProvider(nullptr);
    auto r0 = capi::QueryCards(nullptr);
    CHECK(!r0.ok);                                           // not_ready with no provider
    capi::SetCardsViewProvider([]() {
        capi::CardsView v; v.loaded = true; v.phase = 3; v.credits = 15000;
        SignedCard sc; sc.card_id = "card_neumasport"; sc.level = 1; sc.slot = 0;
        sc.races_active = 5; sc.invested = 2500;
        v.cards.push_back(sc);
        v.shop.open = true; v.shop.race_id = "rX"; v.shop.offers = { "card_volt" };
        v.shop.bought_ids = { "card_volt" };
        return v;
    });
    auto r1 = capi::QueryCards(nullptr);
    CHECK(r1.ok);
    CHECK(r1.payload.find("card_neumasport") != std::string::npos);
    CHECK(r1.payload.find("NeumaSport") != std::string::npos);      // embedded def
    CHECK(r1.payload.find("card_volt") != std::string::npos);       // offer
    CHECK(r1.payload.find("\"boughtIds\"") != std::string::npos);   // purchases from this shop
    CHECK(r1.payload.find("\"slotsUnlocked\":3") != std::string::npos);
    CHECK(r1.payload.find("\"ready\":true") != std::string::npos);  // upgrade ready (5/5 active)
    // card_neumasport has no extras -> "fxExtra":[] (empty array,
    // the field is NEVER omitted).
    CHECK(r1.payload.find("\"fxExtra\":[]") != std::string::npos);
    // 0.7.0 (): the upgrade travels with its per-level magnitude (tyresport N2 = 0.20) for the app's hover.
    CHECK(r1.payload.find("\"v2\":0.2") != std::string::npos);
    CHECK(r1.payload.find("\"v3\":0") != std::string::npos);
    capi::SetCardsViewProvider(nullptr);
}

