// 0.7.0 (thread "Progression / career speed") — cmd.settings.setReward: the career pace is changed from
// Settings with the SAME vocabulary as the create-career card. Through the dispatcher (so it is also tested
// that it is registered): valid token -> executor with 0/1/2 and echo {ok, mode, mult}; unknown token or
// missing -> bad_params without calling the executor; executor that could not persist -> ok:false in the payload.
static void test_api_cmd_settings_reward() {
    static int s_mode = -1; static bool s_ok = true;
    s_mode = -1; s_ok = true;
    capi::SetSettingsCmds8([](int m) { s_mode = m; return s_ok; });
    capi::ApiCore core;
    capi::RegisterCareerQueries(core);
    auto r = apiq_call(core, "cmd.settings.setReward", "{\"mode\":\"hard\"}");
    CHECK(r && r->memberString("kind") == "result");
    const jsonm::Value* p = r ? r->member("payload") : nullptr;
    CHECK(p && p->memberBool("ok") && p->memberString("mode") == "hard");
    CHECK(p && fabs(p->memberNumber("mult") - 0.75) < 1e-9);
    CHECK_EQ(s_mode, 2);
    auto re = apiq_call(core, "cmd.settings.setReward", "{\"mode\":\"easy\"}");
    CHECK(re && re->member("payload") && fabs(re->member("payload")->memberNumber("mult") - 1.25) < 1e-9);
    CHECK_EQ(s_mode, 0);
    // tokens that are NOT a pace: the AI's ("medium"), empty, number, missing -> bad_params, nothing applied
    for (const char* bad : { "{\"mode\":\"medium\"}", "{\"mode\":\"\"}", "{\"mode\":1}", "{}" }) {
        s_mode = -1;
        auto rb = apiq_call(core, "cmd.settings.setReward", bad);
        CHECK(rb && rb->memberString("kind") == "error" && rb->memberString("code") == "bad_params");
        CHECK_EQ(s_mode, -1);
    }
    // the executor could not leave save and profile.json in agreement -> the response says so (the app refreshes)
    s_ok = false;
    auto rf = apiq_call(core, "cmd.settings.setReward", "{\"mode\":\"normal\"}");
    CHECK(rf && rf->memberString("kind") == "result" && rf->member("payload") && !rf->member("payload")->memberBool("ok", true));
    // no executor -> not_ready
    capi::SetSettingsCmds8(capi::SettingsSetRewardExec());
    auto rn = apiq_call(core, "cmd.settings.setReward", "{\"mode\":\"easy\"}");
    CHECK(rn && rn->memberString("kind") == "error" && rn->memberString("code") == "not_ready");
}

// 0.7.0 — the pace lives in career.sav AND in profile.json, and on load profile.json RULES. The failure this
// pins: changing it in Settings touching only the save works until restart, and then the old one comes back without
// saying anything. ProfileRewardModeSync rewrites the token keeping the rest of the file, does not create one that did not
// exist, and if it cannot write it says so, so the save does not stay ahead.
static void test_profile_reward_mode_sync() {
    using namespace career;
    const std::string dir = "build/test_reward_profile";
    paths::CreateDir(dir);
    const std::string pj = dir + "/profile.json";
    auto put = [&](const std::string& body) { FILE* f = fopen(pj.c_str(), "wb"); if (f) { fwrite(body.data(), 1, body.size(), f); fclose(f); } };
    auto slurp = [&]() { std::string s; FILE* f = fopen(pj.c_str(), "rb"); if (f) { char b[512]; size_t n; while ((n = fread(b, 1, sizeof b, f)) > 0) s.append(b, n); fclose(f); } return s; };

    // read: the three tokens, and -1 for what does not seed (no field, odd token, missing or broken file)
    put("{\"name\":\"Save 1\",\"mode\":\"career\",\"difficulty\":\"easy\"}\n");
    CHECK_EQ(ProfileRewardModeRead(pj), 0);
    put("{\"name\":\"Save 1\",\"mode\":\"career\"}\n");
    CHECK_EQ(ProfileRewardModeRead(pj), -1);
    put("{\"name\":\"Save 1\",\"difficulty\":\"extreme\"}\n");
    CHECK_EQ(ProfileRewardModeRead(pj), -1);
    CHECK_EQ(ProfileRewardModeRead(dir + "/nope.json"), -1);

    // rewrite: changes ONLY difficulty; name with quotes and accents, mode and an unknown field intact
    put("{\"name\":\"Jos\xC3\xA9 \\\"el r\xC3\xA1pido\\\"\",\"mode\":\"sandbox\",\"difficulty\":\"easy\",\"extra\":{\"n\":3,\"on\":true}}\n");
    CHECK(ProfileRewardModeSync(pj, 2));
    CHECK_EQ(ProfileRewardModeRead(pj), 2);
    { auto v = jsonm::ParseFile(pj.c_str());
      CHECK(v && v->memberString("name") == "Jos\xC3\xA9 \"el r\xC3\xA1pido\"");
      CHECK(v && v->memberString("mode") == "sandbox");
      CHECK(v && v->member("extra") && v->member("extra")->memberInt("n") == 3 && v->member("extra")->memberBool("on")); }
    CHECK(!paths::FileExists(pj + ".tmp"));   // the temp file does not stay lying around
    // already matches -> true and the file is NOT rewritten (same bytes)
    { const std::string before = slurp(); CHECK(ProfileRewardModeSync(pj, 2)); CHECK(slurp() == before); }
    // no profile.json (legacy profile) or broken: nothing to seed over it -> true, and it is NOT created or touched
    CHECK(ProfileRewardModeSync(dir + "/nope.json", 0));
    CHECK(!paths::FileExists(dir + "/nope.json"));
    put("{roto");
    CHECK(ProfileRewardModeSync(pj, 0));
    CHECK(slurp() == "{roto");

    // cannot be written (the .tmp is occupied by a directory) -> false and the original stays as it was
    put("{\"name\":\"Save 1\",\"mode\":\"career\",\"difficulty\":\"normal\"}\n");
    paths::CreateDir(pj + ".tmp");
    CHECK(!ProfileRewardModeSync(pj, 0));
    CHECK_EQ(ProfileRewardModeRead(pj), 1);
    paths::RemoveDirIfEmpty(pj + ".tmp");

    // the real case: Settings changes from Easy to Hard and restarts. Startup loads the save and then
    // seeds from profile.json (the overlay's ProfileSeedRewardMode): it has to come out Hard.
    const std::string sav = dir + "/career.sav";
    put("{\"name\":\"Save 1\",\"mode\":\"career\",\"difficulty\":\"easy\"}\n");
    { SaveData d; d.prog.reward_mode = 0; CHECK(SaveCareer(d, sav.c_str()));
      CHECK(ProfileRewardModeSync(pj, 2)); d.prog.reward_mode = 2; CHECK(SaveCareer(d, sav.c_str())); }
    { SaveData d; CHECK(LoadCareer(d, sav.c_str()));
      const int seeded = ProfileRewardModeRead(pj); if (seeded >= 0) d.prog.reward_mode = seeded;
      CHECK_EQ(d.prog.reward_mode, 2); }

    paths::RemoveFile(sav); paths::RemoveFile(pj); paths::RemoveDirIfEmpty(dir);
}

// query.profiles + cmd.profile.* -- thin handler (parse+response) + synthetic provider/executors.
static void test_api_profiles() {
    static std::string s_created, s_mode, s_selected, s_deleted;
    static bool s_fail = false;
    s_created.clear(); s_mode.clear(); s_selected.clear(); s_deleted.clear(); s_fail = false;
    capi::SetProfilesProvider([]{
        capi::ProfilesView v; v.active = "default";
        capi::ProfileEntry a; a.slug = "default"; a.name = "Default"; a.mode = "career"; v.profiles.push_back(a);
        capi::ProfileEntry b; b.slug = "libre";   b.name = "Libre";   b.mode = "sandbox"; v.profiles.push_back(b);
        return v; });
    capi::SetProfileCmds(
        [](const std::string& n, const std::string& m, std::string& os, std::string& oe) {
            if (s_fail) { oe = "exists"; return false; }
            s_created = n; s_mode = m; os = "slug_" + n; return true; },
        [](const std::string& s, std::string& oe) {
            if (s_fail) { oe = "not_found"; return false; }
            s_selected = s; return true; },
        [](const std::string& s, std::string& oe) {
            if (s_fail) { oe = "active"; return false; }
            s_deleted = s; return true; });
    capi::ApiCore core; capi::RegisterCareerQueries(core);
    // query.profiles: active + list with slug/name/mode
    auto rq = apiq_call(core, "query.profiles", "{}");
    CHECK(rq && rq->memberString("kind") == "result");
    const jsonm::Value* pl = rq ? rq->member("payload") : nullptr;
    CHECK(pl && pl->memberString("active") == "default");
    const jsonm::Value* arr = pl ? pl->member("profiles") : nullptr;
    CHECK(arr && arr->isArray() && arr->arr.size() == 2);
    if (arr && arr->arr.size() == 2) {
        CHECK(arr->arr[0]->memberString("slug") == "default" && arr->arr[0]->memberString("mode") == "career");
        CHECK(arr->arr[1]->memberString("name") == "Libre"   && arr->arr[1]->memberString("mode") == "sandbox");
    }
    // create: defaults to mode "career"; respects an explicit mode; returns the executor's slug
    auto rc = apiq_call(core, "cmd.profile.create", "{\"name\":\"Mi Piloto\"}");
    CHECK(rc && rc->memberString("kind") == "result" && rc->member("payload")->memberBool("ok"));
    CHECK(rc && rc->member("payload")->memberString("slug") == "slug_Mi Piloto");
    CHECK(s_created == "Mi Piloto" && s_mode == "career");
    auto rc2 = apiq_call(core, "cmd.profile.create", "{\"name\":\"Libre\",\"mode\":\"sandbox\"}");
    CHECK(rc2 && rc2->member("payload")->memberBool("ok"));
    CHECK(s_mode == "sandbox");
    // invalid create: no name / unknown mode -> bad_params (executor NOT called)
    s_created.clear();
    auto rcb = apiq_call(core, "cmd.profile.create", "{}");
    CHECK(rcb && rcb->memberString("kind") == "error" && rcb->memberString("code") == "bad_params");
    auto rcm = apiq_call(core, "cmd.profile.create", "{\"name\":\"x\",\"mode\":\"nope\"}");
    CHECK(rcm && rcm->memberString("kind") == "error" && rcm->memberString("code") == "bad_params");
    CHECK(s_created.empty());
    // select / delete: ok echo + executor called; no slug -> bad_params
    auto rs = apiq_call(core, "cmd.profile.select", "{\"slug\":\"libre\"}");
    CHECK(rs && rs->member("payload")->memberBool("ok") && s_selected == "libre");
    auto rd = apiq_call(core, "cmd.profile.delete", "{\"slug\":\"viejo\"}");
    CHECK(rd && rd->member("payload")->memberBool("ok") && s_deleted == "viejo");
    auto rsb = apiq_call(core, "cmd.profile.select", "{}");
    CHECK(rsb && rsb->memberString("code") == "bad_params");
    // executor returns false -> rejected with the executor's reason
    s_fail = true;
    auto rr = apiq_call(core, "cmd.profile.select", "{\"slug\":\"x\"}");
    CHECK(rr && rr->memberString("kind") == "error" && rr->memberString("code") == "rejected" && rr->memberString("message") == "not_found");
    auto rrd = apiq_call(core, "cmd.profile.delete", "{\"slug\":\"default\"}");
    CHECK(rrd && rrd->memberString("code") == "rejected" && rrd->memberString("message") == "active");
    // no provider/executors -> not_ready
    capi::SetProfilesProvider(nullptr);
    capi::SetProfileCmds(nullptr, nullptr, nullptr);
    auto rn = apiq_call(core, "query.profiles", "{}");
    CHECK(rn && rn->memberString("code") == "not_ready");
    auto rn2 = apiq_call(core, "cmd.profile.create", "{\"name\":\"x\"}");
    CHECK(rn2 && rn2->memberString("code") == "not_ready");
}

// per-id commands (cmd.market.accept|decline) -- synthetic executor logs the id. (The sibling
// cmd.sponsors.sign was retired together with query.sponsors; this test now only covers market.)
static void test_api_cmd_actions() {
    static std::string s_accepted, s_declined;
    s_accepted.clear(); s_declined.clear();
    // the accept executor returns the REASON ("" = signed); the handler emits it as code on failure.
    capi::SetMarketCmds(
        [](const std::string& id) -> std::string { s_accepted = id; return std::string(); },
        [](const std::string& id) { s_declined = id; return true; });
    capi::ApiCore core; capi::RegisterCareerQueries(core);
    auto ra = apiq_call(core, "cmd.market.accept", "{\"offerId\":\"off_direct\"}");
    CHECK(ra && ra->memberString("kind") == "result" && ra->member("payload")->memberString("offerId") == "off_direct");
    CHECK(ra && ra->member("payload")->memberBool("ok"));
    CHECK(ra && ra->member("payload")->memberString("code").empty());   // on success, code is NOT sent
    CHECK(s_accepted == "off_direct");
    auto rd = apiq_call(core, "cmd.market.decline", "{\"offerId\":\"off_open\"}");
    CHECK(rd && rd->memberString("kind") == "result");
    CHECK(s_declined == "off_open");
    // engine rejection -> {ok:false, offerId, code} (before this, the "no" travelled silently and the app said nothing)
    capi::SetMarketCmds(
        [](const std::string&) -> std::string { return std::string("afford"); },
        [](const std::string& id) { s_declined = id; return true; });
    auto rr = apiq_call(core, "cmd.market.accept", "{\"offerId\":\"off_caro\"}");
    CHECK(rr && rr->memberString("kind") == "result");
    CHECK(rr && !rr->member("payload")->memberBool("ok"));
    CHECK(rr && rr->member("payload")->memberString("code") == "afford");
    CHECK(rr && rr->member("payload")->memberString("offerId") == "off_caro");
    // missing offerId -> bad_params
    auto rb = apiq_call(core, "cmd.market.accept", "{}");
    CHECK(rb && rb->memberString("kind") == "error" && rb->memberString("code") == "bad_params");
    // no executor -> not_ready
    capi::SetMarketCmds(nullptr, nullptr);
    auto rn = apiq_call(core, "cmd.market.accept", "{\"offerId\":\"x\"}");
    CHECK(rn && rn->memberString("kind") == "error" && rn->memberString("code") == "not_ready");
}

// F5: cmd.contract.break — synthetic executor records the break. C1: cmd.time.advanceWeek RETIRED (the clock
// now moves with cmd.time.advance, see test_cmd_time_advance_matches_preview), so SetLifecycleCmds
// was left with a single parameter and this test only covers the break.
static void test_api_cmd_lifecycle() {
    static bool s_broke;
    s_broke = false;
    capi::SetLifecycleCmds([]() { s_broke = true; });
    capi::ApiCore core; capi::RegisterCareerQueries(core);
    // break -> ok + executor invoked
    auto rb = apiq_call(core, "cmd.contract.break", "{}");
    CHECK(rb && rb->memberString("kind") == "result" && rb->member("payload")->memberBool("ok") && s_broke);
    // no executor -> not_ready
    capi::SetLifecycleCmds(nullptr);
    auto rn2 = apiq_call(core, "cmd.contract.break", "{}");
    CHECK(rn2 && rn2->memberString("kind") == "error" && rn2->memberString("code") == "not_ready");
}

// dump-api-fixtures <dir>: writes ONLY each query's payload (using the tests' synthetic state)
// into <dir>/{career_state,standings,inbox,profile,memories,calendar,results}.json -- the UI's mocks.
static int apiq_dump_fixtures(const char* dir) {
    apiq_install_state();
    CreateDirectoryA(dir, nullptr);   // idempotent: no-op if it already exists
    // params = the query's JSON (nullptr = no params). The profile needs this, since its payload changes with full=true.
    struct Q { const char* file; capi::HandlerResult (*fn)(const jsonm::Value*); const char* params = nullptr; };
    const Q qs[23] = {
        { "career_state.json", &capi::QueryCareerState },
        { "standings.json",    &capi::QueryStandings },
        { "inbox.json",        &capi::QueryInbox },
        { "profile.json",      &capi::QueryProfile },
        // the profile is dumped TWICE because it has two distinct contractual payloads -- the panel's
        // (no params) and the "see all" modal's (full=true, which adds worldRanking.all). Without the second one, the
        // app had nowhere to get the full table from, and someone had hand-written it into profile.json.
        { "profile.full.json", &capi::QueryProfile, "{\"full\":true}" },
        { "memories.json",     &capi::QueryMemories },
        { "calendar.json",     &capi::QueryCalendar },
        { "results.json",      &capi::QueryResults },
        { "times.json",        &capi::QueryTimes },
        { "tree.json",         &capi::QueryTree },
        { "settings.json",     &capi::QuerySettings },
        { "garage.json",       &capi::QueryGarage },
        { "market.json",       &capi::QueryMarket },
        { "hub.json",          &capi::QueryHub },
        { "identity.json",     &capi::QueryIdentity },
        { "negotiate.json",    &capi::QueryNegotiate },
        { "season.json",       &capi::QuerySeason },
        { "prerace.json",      &capi::QueryPrerace },
        { "tryout.json",       &capi::QueryTryout },
        { "rollover.json",     &capi::QueryRollover },
        { "race_config.json",  &capi::QueryRaceConfig },
        { "telemetry_race.json", &capi::QueryTelemetryRace },   // schema consumed by the backend
        { "time_preview.json", &capi::QueryTimePreview, "{}" },   // C1: the clock with stops, no params
    };
    for (const Q& q : qs) {
        jsonm::ValuePtr pv = q.params ? jsonm::Parse(q.params) : nullptr;
        capi::HandlerResult r = q.fn(pv.get());
        if (!r.ok) { printf("FIXTURE FAIL %s: %s (%s)\n", q.file, r.code.c_str(), r.message.c_str()); return 1; }
        std::string path = std::string(dir) + "\\" + q.file;
        FILE* f = fopen(path.c_str(), "wb");
        if (!f) { printf("FIXTURE FAIL no se pudo abrir %s\n", path.c_str()); return 1; }
        fwrite(r.payload.data(), 1, r.payload.size(), f);
        fputc('\n', f);
        fclose(f);
        printf("fixture -> %s (%zu bytes)\n", path.c_str(), r.payload.size());
    }
    apiq_restore();
    return 0;
}

// dump-strings <dir>: dumps the engine's string table (strings.cpp) as a flat i18n bundle
// {key: text} into <dir>/engine.{en,es}.json. The app loads them as a fallback so t() can resolve
// the keys the engine emits (inbox from/subject, times, championships...). One language per file.
static int dump_strings(const char* dir) {
    CreateDirectoryA(dir, nullptr);   // idempotent
    struct Ctx { jsonw::Writer en; jsonw::Writer es; std::set<std::string> keys; } ctx;
    ctx.en.BeginObject();
    ctx.es.BeginObject();
    ForEachString([](const char* k, const char* en, const char* es, void* p) {
        Ctx* c = (Ctx*)p;
        // The table carries DUPLICATE keys, and JSON.parse keeps the LAST one, while
        // TR() resolves the FIRST -- the bundle was serving the app STALE text for 12 keys. First-wins,
        // like TR, so the app and the engine say the same thing.
        if (!c->keys.insert(k).second) return;
        c->en.KS(k, en);
        c->es.KS(k, es);
    }, &ctx);
    // MERGE, not overwrite (defuses the trip-wire in locales.test.ts): the bundle carries keys
    // the app uses EXCLUSIVELY (mkt_watching/off_contested/seatwatch_*, which never went through strings.cpp), and the
    // flat dump used to wipe them out -- it happened before and again just now. Every key already in the file
    // that the table doesn't provide is kept; for the ones the table does provide, strings.cpp wins.
    auto keepExtras = [&](jsonw::Writer& w, const char* file) {
        std::string path = std::string(dir) + "\\" + file;
        if (auto old = jsonm::ParseFile(path.c_str()))
            for (const auto& kv : old->obj)
                if (!ctx.keys.count(kv.first) && kv.second && kv.second->isString())
                    w.KS(kv.first.c_str(), kv.second->str.c_str());
    };
    keepExtras(ctx.en, "engine.en.json");
    keepExtras(ctx.es, "engine.es.json");
    ctx.en.EndObject();
    ctx.es.EndObject();
    auto writeFile = [&](const char* file, const std::string& data) -> bool {
        std::string path = std::string(dir) + "\\" + file;
        FILE* f = fopen(path.c_str(), "wb");
        if (!f) { printf("STRINGS FAIL no se pudo abrir %s\n", path.c_str()); return false; }
        fwrite(data.data(), 1, data.size(), f); fputc('\n', f); fclose(f);
        printf("strings -> %s (%zu bytes)\n", path.c_str(), data.size());
        return true;
    };
    if (!writeFile("engine.en.json", ctx.en.Str())) return 1;
    if (!writeFile("engine.es.json", ctx.es.Str())) return 1;
    return 0;
}

// dump-grids <file.psv>: builds each class's PRODUCTION grid and dumps one driver per
// line, with the talent that enters the band and the race_skill that comes out in the XML. It's not a test: it's the
// instrument used to tune the talent ladder without guessing. Same load and same numbers as
// test_the_car_share_is_discounted_exactly_once (PRODUCTION size and level, spread distributed with the car),
// so what's measured here is what actually ships to the game, not a lab-only grid.
static int dump_grids(const char* outPath) {
    using namespace career;
    std::string R = TESTDATA("");
    auto P = [&](const char* f) { return std::string(R) + f; };
    struct { const char* name; bool ok; } loads[] = {
        { "ams2_liveries.psv",              LoadLiveries(P("ams2_liveries.psv").c_str()) },
        { "series.psv",                     LoadSeries(P("series.psv").c_str()) },
        { "series_config_profiles.psv",     LoadProfiles(P("series_config_profiles.psv").c_str()) },
        { "series_fields.psv",              LoadFields(P("series_fields.psv").c_str()) },
        { "series_roster.psv",              LoadRoster(P("series_roster.psv").c_str()) },
        { "series_rosters.psv",             LoadSeriesRosters(P("series_rosters.psv").c_str()) },
        { "class_pace_curve.psv",           LoadClassPace(P("career\\class_pace_curve.psv").c_str()) },
        { "f3_authored_profiles.psv",       LoadAuthoredProfiles(P("career\\f3_authored_profiles.psv").c_str()) },
    };
    for (const auto& l : loads)
        if (!l.ok) { printf("DUMP-GRIDS FAIL: no se pudo cargar %s\n", l.name); return 1; }

    // THE LIVE PATH, not the static one. In-game, `PregenAllAi` calls SeedAllDrivers and passes
    // `&g_save.driver_ratings`, so each driver's talent comes from RatingQuality(elo), NOT from the
    // `series_fields` curve. Measuring without ratings measures a different grid: with them, 30 classes come out with the ace
    // pulled away, and without them only 12 do. The dump seeds the same way the game does, so what's measured is what's played.
    std::map<std::string, double> ratings;
    const int seeded = SeedAllDrivers(ratings);
    SaveData dumpSave;   // empty save = YEAR 1 with no signings: seats come out DERIVED from the data

    FILE* f = fopen(outPath, "wb");
    if (!f) { printf("DUMP-GRIDS FAIL: no se pudo abrir %s\n", outPath); return 1; }
    fprintf(f, "# class|series|grid|kind|name|talent|race_skill|qualifying|ref_span|spread_used|median_used|rating"
               "|aggression|defending|blue_flag|wet|tyre|fuel\n");
    std::set<std::string> seen;
    int classes = 0, drivers = 0;
    for (const auto& s : AllSeries()) {
        const ClassPace cp = ClassPaceFor(s.class_name);
        if (!cp.found) continue;
        if (!seen.insert(s.class_name).second) continue;      // one series per class, the first one
        const int gs = GridSizeForClassName(s.class_name);
        if (gs < 8) continue;
        // 09/08 -- AND THE LIVE-WORLD BRIDGE, which the dump also skipped until today. Production
        // (PregenAllAi) composes with `SeatOccupantsByLivery`, and without it the dump was measuring a grid nobody
        // races: this is the THIRD time this gap has fooled a measurement. With an empty save, the map comes out
        // DERIVED (no persisted overrides), which is exactly year 1 -- the case a player complained about
        // after seeing an academy driver in the 2025 F1 grid.
        const std::vector<SeatRow> asientos = SeatRowsForSeries(dumpSave, s.id);
        auto grid = ComposeSeasonGrid(s.id, s.level, 0.0, gs, false, EmptyRivalForm(), nullptr, &ratings,
                                      ClassRole::SingleClass, asientos.empty() ? nullptr : &asientos);
        if ((int)grid.size() < 8) continue;
        // the SAME car/driver assignment the production writer makes (WriteSeasonGridXml)
        const double spreadDriver = DriverSpreadPct(s.id, s.class_name, cp.spread_dry);
        const double shrink = (cp.spread_dry > 0.0) ? (spreadDriver / cp.spread_dry) : 1.0;
        const double medianUsed = cp.median_dry * shrink;
        // talent is recorded BEFORE BuildGridXml overwrites race_skill/qualifying with the band
        std::vector<double> talents; talents.reserve(grid.size());
        for (const auto& d : grid) talents.push_back(d.talent);
        std::string xml = BuildGridXml(grid, spreadDriver, medianUsed);
        // the XML comes out in the SAME order as `grid`, so the i-th <race_skill> is the i-th driver
        std::vector<double> rs, qs;
        auto scrape = [&xml](const char* tag, std::vector<double>& out) {
            const std::string open = std::string("<") + tag + ">";
            for (size_t p = xml.find(open); p != std::string::npos; p = xml.find(open, p + 1)) {
                size_t a = p + open.size(), b = xml.find('<', a);
                if (b == std::string::npos) break;
                out.push_back(atof(xml.substr(a, b - a).c_str()));
            }
        };
        scrape("race_skill", rs);
        scrape("qualifying_skill", qs);
        if (rs.size() != grid.size() || qs.size() != grid.size()) {
            printf("DUMP-GRIDS FAIL: %s escribio %zu skills para %zu pilotos\n",
                   s.class_name.c_str(), rs.size(), grid.size());
            fclose(f); return 1;
        }
        for (size_t i = 0; i < grid.size(); i++) {
            const auto itR = ratings.find(grid[i].driver_id);
            fprintf(f, "%s|%s|%d|%s|%s|%.6f|%.6f|%.6f|%.4f|%.4f|%.4f|%.1f|%.4f|%.4f|%.4f|%.4f|%.4f|%.4f\n",
                    s.class_name.c_str(), s.id.c_str(), (int)grid.size(),
                    grid[i].kind.empty() ? "?" : grid[i].kind.c_str(), grid[i].name.c_str(),
                    talents[i], rs[i], qs[i], cp.talent_ref_span, spreadDriver, medianUsed,
                    itR == ratings.end() ? 0.0 : itR->second,
                    grid[i].aggression, grid[i].defending, grid[i].blue_flag_conceding,
                    grid[i].wet_skill, grid[i].tyre_management, grid[i].fuel_management);
            drivers++;
        }
        classes++;
    }
    fclose(f);
    printf("grids -> %s (%d clases, %d pilotos, %d ratings sembrados)\n", outPath, classes, drivers, seeded);
    return 0;
}

// Mail-channel utilities (career_mail.h).


// Save round-trip with GeneratedEmail's new fields + back-compat for the old 9-field line.
static void test_mail_save_roundtrip() {
    using namespace career;
    const char* path = "build/test_mail_save.txt";
    {
        SaveData d;
        GeneratedEmail e;
        e.id = "ms_firstpodium"; e.tag = 1; e.day = 42; e.family = 1; e.read = 1; e.subtype = 2;
        e.payload_key = "ms_firstpodium"; e.variant = 2; e.year = 2027;
        e.params = MailParamsEncode({ {"player","Ana"}, {"track","Northstead | Rio Hondo"} });
        e.from_name = "Atenea Montero"; e.from_role_key = "inbox_role_manager";
        d.emails.push_back(e);
        GeneratedEmail legacy;                       // an "old" email re-saved: new fields empty
        legacy.id = "old_mail"; legacy.payload_key = "ms_repband"; legacy.family = 1; legacy.day = 7;
        d.emails.push_back(legacy);
        CHECK(SaveCareer(d, path));
    }
    {
        SaveData d;
        CHECK(LoadCareer(d, path));
        CHECK_EQ((long)d.emails.size(), 2L);
        const GeneratedEmail& e = d.emails[0];
        CHECK(e.id == "ms_firstpodium");
        CHECK_EQ((long)e.variant, 2L);
        CHECK(e.from_name == "Atenea Montero");
        CHECK(e.from_role_key == "inbox_role_manager");
        // fix for "nonsensical date on an email when crossing into a new year": the issuance YEAR (2027) round-trips just
        // like the rest of the additive fields (variant/from_name/...), field 15 of the 'email' line.
        CHECK_EQ(e.year, 2027);
        MailParams p = MailParamsDecode(e.params);
        CHECK_EQ((long)p.size(), 2L);
        CHECK(p[1].second == "Northstead | Rio Hondo");  // the value's pipe character survives the pipe-delimited format
        const GeneratedEmail& l = d.emails[1];
        CHECK_EQ((long)l.variant, 0L);
        CHECK(l.params.empty()); CHECK(l.from_name.empty()); CHECK(l.from_role_key.empty());
        CHECK_EQ(l.year, 0);   // an email without an explicit year -> 0 (unknown), it doesn't invent a year
    }
    // back-compat: a 14-field save line (PRE-fix format, no 'year') loads with year=0
    // (unknown) WITHOUT losing the email -- the API emitter falls back to the CURRENT year only in that one case. ----
    {
        const char* path14 = "build/test_mail_save_14field.txt";
        FILE* f14 = fopen(path14, "wb");
        CHECK(f14 != nullptr);
        if (f14) {
            fprintf(f14, "version 2\r\n");
            // the SAME format SaveCareer used to write before this fix: 14 fields, no trailing year.
            fprintf(f14, "email %s|%d|%d|%d|%d|%d|%d|%d|%s|%d|%s|%s|%s|%s\r\n",
                    "ms_titlefight_gt3_2026", 1, 100, 1, 0, 0, 0, 4, "ms_titlefight",
                    1, "", "Atenea Montero", "inbox_role_manager", "");
            fclose(f14);
        }
        SaveData d14;
        CHECK(LoadCareer(d14, path14));
        CHECK_EQ((long)d14.emails.size(), 1L);              // the email is NOT lost
        if (!d14.emails.empty()) {
            CHECK(d14.emails[0].id == "ms_titlefight_gt3_2026");
            CHECK_EQ((long)d14.emails[0].variant, 1L);      // the previous fields (13/14) remain intact
            CHECK(d14.emails[0].from_name == "Atenea Montero");
            CHECK_EQ(d14.emails[0].year, 0);                // no 15th field -> year=0 (unknown, NOT invented)
        }
    }
    // back-compat: an OLD save line (9 fields) loads with defaults ----
    {
        FILE* f = fopen("build/test_mail_save_old.txt", "wb");
        CHECK(f != nullptr);
        fprintf(f, "version 2\r\n");
        fprintf(f, "email ms_firstwin|2|10|1|0|0|0|3|ms_firstwin\r\n");
        fclose(f);
        SaveData d;
        CHECK(LoadCareer(d, "build/test_mail_save_old.txt"));
        CHECK_EQ((long)d.emails.size(), 1L);
        CHECK(d.emails[0].payload_key == "ms_firstwin");
        CHECK_EQ((long)d.emails[0].variant, 0L);
        CHECK(d.emails[0].from_name.empty());
    }
    // a legacy save WITH credits but WITHOUT a 'mailnarr' line (from before that field existed) -> the
    // first season close must not report the entire balance as {net}; LoadCareer seeds
    // season_start_credits from prog.credits when there's no mailnarr line to carry it. ----
    {
        FILE* f = fopen("build/test_mail_save_legacy_credits.txt", "wb");
        CHECK(f != nullptr);
        fprintf(f, "version 2\r\n");
        fprintf(f, "credits 45000\r\n");
        fprintf(f, "email ms_firstwin|2|10|1|0|0|0|3|ms_firstwin\r\n");
        fclose(f);
        SaveData d;
        CHECK(LoadCareer(d, "build/test_mail_save_legacy_credits.txt"));
        CHECK_EQ(d.prog.credits, 45000L);
        CHECK_EQ(d.mailnarr.season_start_credits, 45000L);   // seeded from prog.credits (no mailnarr line)
    }
}

