// beef -- round-trip + yearly decay (a year with no rivalry -> -1; hits 0 and it's cleared).
static void test_beef_roundtrip_decay() {
    career::SaveData s;
    s.beef["drv_a"] = {2, 2026, 14};
    s.beef["drv_b"] = {1, 2025, 3};    // old year -> will decay
    const char* p = "build/test_beef.sav";
    career::SaveCareer(s, p);
    career::SaveData l; CHECK(career::LoadCareer(l, p));
    CHECK_EQ((int)l.beef.size(), 2);
    CHECK_EQ(l.beef["drv_a"].level, 2);
    CHECK_EQ(l.beef["drv_a"].last_race_idx, 14);
    // decay: pure helper (called by RolloverYearReport with from_year)
    career::BeefDecayAtRollover(l, 2026);
    CHECK_EQ(l.beef.count("drv_b"), (size_t)0);   // 1 -> 0 -> cleared
    CHECK_EQ(l.beef["drv_a"].level, 2);           // 2026 == from_year -> untouched
    career::BeefDecayAtRollover(l, 2027);
    CHECK_EQ(l.beef["drv_a"].level, 1);
}

