// Settle emitter -- title fight with a REAL signal from standings. Signed by the journalist;
// respects the one-at-a-time rule and the rounds window. Render-assert (same pattern as test_rival_duel_mail_render).
static void test_press_titlefight_mail() {
    using namespace career;
    std::vector<market::GenOffer> none;
    // (1) P2 with 2 rounds left in a beat that has a result -> press_tf (family 6, subtype 1), from the journalist.
    {
        SaveData s; s.mailnarr.onboard_stage = 3;
        EmailGenContext ctx; ctx.year = 2026; ctx.day = 200; ctx.has_race_result = true;
        ctx.player = "Ana"; ctx.series_display = "GT3 Europe";
        ctx.press_series = "onyx_cup_4742"; ctx.press_standing_pos = 2; ctx.press_rounds_left = 2;
        GenerateCareerEmails(s, none, ctx);
        const GeneratedEmail* m = nullptr;
        for (const auto& e : s.emails) if (e.id.rfind("press_tf_", 0) == 0) m = &e;
        CHECK(m != nullptr);
        if (m) {
            CHECK_EQ(m->family, 6);
            CHECK_EQ(m->subtype, 1);
            CHECK(m->from_name == "Dario Quesada");                 // MailPressName()
            CHECK(m->from_role_key == "inbox_role_press");
            MailParams p = MailParamsDecode(m->params);
            bool hasPos = false;                                    // {pos} = position in the OVERALL standings, not the last race's
            for (const auto& kv : p) if (kv.first == "pos" && kv.second == "2") hasPos = true;
            CHECK(hasPos);
            std::string bodyKey = MailBodyKey(m->payload_key, m->variant);
            std::string rendered = MailInterpolate(TR(bodyKey.c_str()), p);
            CHECK(rendered.find('{') == std::string::npos);        // no orphaned placeholders
            CHECK(rendered.find(", ,") == std::string::npos);
            CHECK(rendered.find(" .") == std::string::npos);
        }
    }
    // (2) one at a time: with another unanswered family-6 interview already seeded, it does NOT fire.
    {
        SaveData s; s.mailnarr.onboard_stage = 3;
        GeneratedEmail pend; pend.id = "press_fw_2026"; pend.family = 6; pend.subtype = 0; pend.answered = 0;
        s.emails.push_back(pend);
        EmailGenContext ctx; ctx.year = 2026; ctx.day = 200; ctx.has_race_result = true;
        ctx.player = "Ana"; ctx.series_display = "GT3 Europe";
        ctx.press_series = "onyx_cup_4742"; ctx.press_standing_pos = 2; ctx.press_rounds_left = 2;
        GenerateCareerEmails(s, none, ctx);
        bool tf = false; for (const auto& e : s.emails) if (e.id.rfind("press_tf_", 0) == 0) tf = true;
        CHECK(!tf);
    }
    // (3) outside the rounds window (rounds_left = 0) -> does NOT fire.
    {
        SaveData s; s.mailnarr.onboard_stage = 3;
        EmailGenContext ctx; ctx.year = 2026; ctx.day = 200; ctx.has_race_result = true;
        ctx.player = "Ana"; ctx.series_display = "GT3 Europe";
        ctx.press_series = "onyx_cup_4742"; ctx.press_standing_pos = 2; ctx.press_rounds_left = 0;
        GenerateCareerEmails(s, none, ctx);
        bool tf = false; for (const auto& e : s.emails) if (e.id.rfind("press_tf_", 0) == 0) tf = true;
        CHECK(!tf);
    }
}

// Settle emitter -- first win + rival variant. With a resolved nemesis -> rival params +
// variant in {0,1}; with no rival or beef -> variant forced to v0 and no rival in the params. Render-assert in both.


// Rollover emitters -- title won (press_tw), being fired (press_jl, respecting one-at-a-time)
// and preseason power ranking (press_ranking with a numeric {rank} + {leader}). Each block gets its own rollover.
// Two more cases: rank==1 -> no ranking; and title+firing in the same rollover ->
// the title takes the press slot, the firing's press mail is dropped, Atenea's stays untouched).


// Atenea's catalog is complete -- every event has a _subj + >=2 variants; no hardcoded names.
static void test_mail_catalog() {
    using namespace career;
    const char* keys[] = { "ms_repband", "ms_firstpodium", "ms_firstwin", "ms_titlefight", "ms_finalseason",
                           "job_lost", "ob_intro", "ob_first_race", "ob_first_goal",
                           "season_preview", "season_close", "ms_hotstreak", "ms_coldstreak",
                           "sp_mail_card_buy", "sp_mail_card_clause", "sp_mail_card_expire" };
    for (const char* k : keys) {
        CHECK(TRHas((std::string(k) + "_subj").c_str()));
        CHECK(MailVariantCount(k) >= 2);
        CHECK(TRHas(k));                                  // bare key = fallback for old saves
    }
    CHECK(TRHas("inbox_role_manager"));
    CHECK(TRHas("inbox_role_teamprincipal"));
    CHECK(TRHas("inbox_offer_subj"));
    CHECK(TRHas("inbox_offer_body"));
    // Style rule: no hardcoded player name is allowed in any email key.
    struct ScanCtx { int bad = 0; } sc;
    ForEachString([](const char* k, const char* en, const char* es, void* p) {
        ScanCtx* c = (ScanCtx*)p;
        bool mailKey = !strncmp(k, "ms_", 3) || !strncmp(k, "ob_", 3) || !strncmp(k, "season_", 7)
                    || !strncmp(k, "sp_mail_", 8) || !strncmp(k, "job_lost", 8) || !strncmp(k, "inbox_offer", 11);
        if (mailKey && (strstr(en, "Josh") || strstr(es, "Josh"))) c->bad++;
    }, &sc);
    CHECK_EQ((long)sc.bad, 0L);
}

