// Onboarding arc -- intro on creation, first_race on the first settle, first_goal on progression.


// One-shot streaks per season + a cap of 2 Atenea emails per beat (priority-ordered).


// Damage invoice -- only if the deductible crosses the threshold; tone driven by cleanliness.

// Clean-race streak -- fires EXACTLY when it hits the threshold, once a year.
static void test_ops_cleanstreak_mail() {
    career::SaveData s; s.mailnarr.onboard_stage = 3; s.mailnarr.consec_clean = career::bal::MK_MAIL_CLEAN_STREAK;
    std::vector<market::GenOffer> offers; career::EmailGenContext ctx;
    ctx.year = 2026; ctx.day = 50; ctx.has_race_result = true;
    career::GenerateCareerEmails(s, offers, ctx);
    bool found = false; for (const auto& e : s.emails) if (e.id == "ops_cleanstreak_2026") found = true;
    CHECK(found);
    size_t n = s.emails.size();
    career::GenerateCareerEmails(s, offers, ctx);          // same year -> dedup
    CHECK_EQ((int)s.emails.size(), (int)n);
    // consec_clean crossed the threshold but this beat did NOT come from a race (AdvanceWeek
    // with no result) -> without has_race_result the beat does NOT fire (avoids re-firing what the P2 cap already dropped
    // during the real settle).
    career::SaveData s2; s2.mailnarr.onboard_stage = 3; s2.mailnarr.consec_clean = career::bal::MK_MAIL_CLEAN_STREAK;
    career::EmailGenContext c2; c2.year = 2026; c2.day = 55; c2.has_race_result = false;
    career::GenerateCareerEmails(s2, offers, c2);
    for (const auto& e : s2.emails) CHECK(e.id != "ops_cleanstreak_2026");
}
// FillSettleContractCtx attributes team_display/per_race to the contract of THE SERIES
// that was raced in multi-contract careers (save.contracts can have 0..N active at once, career_save.h),
// not to the "first active one" (which used to mix up TEAMOPS from different series). final_series keeps its OWN rule
// (seasons_left==1), independent of which series was raced.
static void test_ops_damage_contract_attribution() {
    using namespace career;
    SaveData s;
    Contract ca; ca.active = true; ca.series_id = "gt3"; ca.team_id = "Alpha"; ca.per_race = 1000; ca.seasons_left = 2;
    Contract cb; cb.active = true; cb.series_id = "f3";  cb.team_id = "Beta";  cb.per_race = 500;  cb.seasons_left = 1;
    s.contracts.push_back(ca);
    s.contracts.push_back(cb);

    // the race happened in "gt3" -> team_display/per_race come from the Alpha contract, NOT Beta (which would come out "first
    // active" if read in vector order under the old bug, and it's ALSO the last-season one).
    EmailGenContext ctx;
    FillSettleContractCtx(s, "gt3", ctx);
    CHECK(ctx.team_display == "Alpha");
    CHECK_EQ((long)ctx.per_race, 1000L);
    CHECK(ctx.final_series == "f3");     // final_series is its OWN rule (seasons_left==1), not the series that was raced

    // no contract for that series (a privateer entry in a third series) -> team_display/per_race empty/0; final_series
    // doesn't depend on the series that was raced, and still detects the last-season contract.
    EmailGenContext ctx2;
    FillSettleContractCtx(s, "lantern_masters_7489", ctx2);
    CHECK(ctx2.team_display.empty());
    CHECK_EQ((long)ctx2.per_race, 0L);
    CHECK(ctx2.final_series == "f3");

    // empty raceSeriesId (a standalone race, no series) -> still no match.
    EmailGenContext ctx3;
    FillSettleContractCtx(s, "", ctx3);
    CHECK(ctx3.team_display.empty());
    CHECK_EQ((long)ctx3.per_race, 0L);
}

