// Shared scaffolding for the 4 availability combinations of {best}/{nemesis} --
// identical to test_mail_season_beats except the caller seeds (or not) nemesis_id/last_notable_track.
namespace {
void seasonCloseScaffold(career::CareerCalendar& cc, career::CareerProgress& prog, career::SaveData& save) {
    using namespace career;
    prog.credits = 1000000; save.player.name = "Ana Torres"; cc.year = 5;
    Enroll(cc, "falcon_series_9334", prog);
    save.contracts.assign(1, Contract{});
    save.contracts[0].active = true; save.contracts[0].series_id = "falcon_series_9334";
    save.contracts[0].seasons_total = 2; save.contracts[0].seasons_left = 2; save.contracts[0].signed_year = 5;
    SeasonState* e = FindEnrollment(cc, "falcon_series_9334");
    while (e && !SeasonEnded(*e)) ApplyDnf(*e, "Jugador");
    if (e) e->status = 1;
    save.completed_seasons.push_back(CompletedSeason{ "falcon_series_9334", 3, 5, 10, "team_prev" });
    save.mailnarr.season_start_credits = 900000;
    prog.credits = 1000000;
}
}

// only {nemesis} available (a rookie with a rival already identified but with NO podium/win yet -- a common case
// the original bug broke by forcing v2, which requires {best}): it must force season_close_v1 (the only one that only
// needs {nemesis}), with no {best} in the params. Includes the ONLY interpolation assertion in this family of
// tests (same pattern as test_mail_utils/MailInterpolate): resolves the real key, translates and substitutes, and checks
// that the rendered text leaves no trace of a broken template.


// only {best} available (a season with a podium/win but no rival identified yet): it must force
// season_close_v2 (the only one that only needs {best}), with no {nemesis} in the params.


// NEITHER {best} NOR {nemesis} available (a rookie with no podium and no rival yet): before this fix it
// used to force v2 anyway, and MailInterpolate left "Your best day, , was..." (placeholder erased, not substituted).
// Now it forces season_close_v3 (no data tokens, see strings.cpp) -- the email must ALWAYS go out (the
// season close is a ritual). Same scaffolding pattern as test_mail_season_beats.
static void test_season_close_variant_forced_no_data() {
    using namespace career;
    CareerCalendar cc; CareerProgress prog; SaveData save;
    seasonCloseScaffold(cc, prog, save);
    // save.nemesis_id/mailnarr.last_notable_track stay at their empty default -> {best}/{nemesis} don't resolve.
    RolloverYear(cc, prog, save, "Ana Torres");
    const GeneratedEmail* closeMail = nullptr;
    for (const auto& e2 : save.emails) if (e2.id == "season_close_falcon_series_9334_5") closeMail = &e2;
    CHECK(closeMail != nullptr);
    if (closeMail) {
        CHECK_EQ((long)closeMail->variant, 3L);           // season_close_v3 forced (no data)
        MailParams cp = MailParamsDecode(closeMail->params);
        for (const auto& kv : cp) { CHECK(kv.first != "best"); CHECK(kv.first != "nemesis"); }
    }
}

// INTEL block + rollover nemesis. Tests the IntelRolloverMails HELPER DIRECTLY
// (single source of truth, without assembling a full rollover -- save/h2h/nemesis/seat/rep are seeded by hand).
// Every emitted-email test ends with a render-assert (TR + MailInterpolate, no orphaned '{' or commas/periods).

// A retirement with enough h2h history emits intel_retire with {w}/{l}; a retirement with NO h2h and
// out of orbit generates neither its own email nor a summary headline (empty pool -> no intel_market either).
static void test_intel_retire_mail() {
    using namespace career;
    SaveData save; save.player.name = "Ana Torres"; save.prog.frontier_phase = 3;
    save.h2h["rk_lucia"] = H2H{3, 2};        // w+l=5 >= MK_INTEL_RETIRE_MIN_H2H(4) -> intel_retire email
    RolloverReport rep;
    { RolloverRetirement r; r.driver_id = "rk_lucia"; r.name = "Lucia Vega"; r.age = 41; r.reason = "Age";
      rep.retirements.push_back(r); }
    // a retirement with NO h2h, an id that does NOT resolve in DriverById (tier_max unknown -> out of orbit): no email, no headline.
    { RolloverRetirement r; r.driver_id = "rd_unknown_zzz"; r.name = "Nadie"; r.age = 39; r.reason = "Age";
      rep.retirements.push_back(r); }
    std::map<std::string,std::string> seatsBefore = save.seat_occupant;   // no signings
    IntelRolloverMails(save, rep, seatsBefore, 2026, 90);

    const GeneratedEmail* retireMail = nullptr; const GeneratedEmail* marketMail = nullptr; int unknownRetire = 0;
    for (const auto& e : save.emails) {
        if (e.id == "intel_retire_rk_lucia_2026") retireMail = &e;
        if (e.id == "intel_market_2026") marketMail = &e;
        if (e.id == "intel_retire_rd_unknown_zzz_2026") unknownRetire++;
    }
    CHECK(retireMail != nullptr);            // retirement with history -> email
    CHECK_EQ((long)unknownRetire, 0L);       // retirement with no h2h -> no email of its own
    CHECK(marketMail == nullptr);            // ...and out of orbit -> no headline -> no summary
    if (retireMail) {
        CHECK_EQ((long)retireMail->family, 4L);      // INTEL
        CHECK_EQ((long)retireMail->subtype, 0L);
        CHECK(retireMail->from_name == "Atenea Montero");
        MailParams p = MailParamsDecode(retireMail->params);
        auto findP = [&](const std::string& k){ for (auto& kv : p) if (kv.first == k) return kv.second; return std::string(); };
        CHECK(findP("driver") == "Lucia Vega");
        CHECK(findP("w") == "3");
        CHECK(findP("l") == "2");
        std::string bodyKey = MailBodyKey(retireMail->payload_key, retireMail->variant);
        std::string rendered = MailInterpolate(TR(bodyKey.c_str()), p);
        CHECK(rendered.find('{') == std::string::npos);
        CHECK(rendered.find(" .") == std::string::npos);
        CHECK(rendered.find(", ,") == std::string::npos);
    }
}

