// intel_promo dropped. 2 headlines -> variant v0/v1 with {m1}+{m2}; 1 headline -> v2 forced, {m1} only.


// Nemesis email at closing -- respect (w>l) signs with their own name {driver}; needling (w<=l)
// with no {driver}. Family RIVAL (5, tag 2, role inbox_role_rival), does NOT count against the INTEL cap.


// Read/answer mechanics -- single source of truth in career_mail.
static void test_inbox_mark_read() {
    career::SaveData s;
    career::GeneratedEmail e; e.id = "m1"; e.family = 1; e.read = 0;
    s.emails.push_back(e);
    CHECK(career::MailMarkRead(s, "m1"));            // unread -> true (it changed; the caller persists it)
    CHECK_EQ(s.emails[0].read, 1);
    CHECK(!career::MailMarkRead(s, "m1"));           // already read -> false (idempotent, don't re-save)
    CHECK(!career::MailMarkRead(s, "nope"));         // nonexistent id -> false
}
static void test_inbox_answer_guards() {
    career::SaveData s;
    career::GeneratedEmail e; e.id = "m1"; e.family = 1; e.read = 1;
    s.emails.push_back(e);
    CHECK_EQ(career::MailAnswer(s, "nope", 0), 1);   // not_found
    CHECK_EQ(career::MailAnswer(s, "m1", 0), 3);     // family with no actions -> not_answerable
    CHECK_EQ(s.emails[0].answered, 0);               // no side effects
    s.emails[0].answered = 1;
    CHECK_EQ(career::MailAnswer(s, "m1", 0), 2);     // already_answered wins over not_answerable
}
static void test_inbox_pending_decisions() {
    career::SaveData s;
    { career::GeneratedEmail e; e.id="a"; e.family=1; e.read=0; s.emails.push_back(e); }               // unread
    { career::GeneratedEmail e; e.id="b"; e.family=1; e.read=1; s.emails.push_back(e); }               // read flavor
    { career::GeneratedEmail e; e.id="c"; e.family=0; e.read=1; e.answered=0; s.emails.push_back(e); } // OFFER unanswered
    { career::GeneratedEmail e; e.id="d"; e.family=0; e.read=1; e.answered=1; s.emails.push_back(e); } // OFFER resolved
    CHECK_EQ(career::MailPendingDecisions(s), 2);    // a + c
    CHECK(career::MailActionablePending(s.emails[2], s));
    CHECK(!career::MailActionablePending(s.emails[3], s));
}
// Ghost badge fix: the EVENT invite (family 7 subtype 1) only counts while it's
// UNREAD -- once read it stops being a "pending decision" (there's nothing to accept in the email; the Ignore button
// stays available but doesn't inflate the badge). The SUBSTITUTION invite (subtype 0) IS a real
// decision (accept/decline the seat) and keeps counting until it's answered.
static void test_inbox_event_invite_not_pending_once_read() {
    career::SaveData s;
    { career::GeneratedEmail e; e.id="evinv_x"; e.family=7; e.subtype=1; e.read=0; s.emails.push_back(e); }  // unread
    { career::GeneratedEmail e; e.id="evinv_y"; e.family=7; e.subtype=1; e.read=1; s.emails.push_back(e); }  // read
    { career::GeneratedEmail e; e.id="subinv_z"; e.family=7; e.subtype=0; e.read=1; s.emails.push_back(e); } // substitution read, unanswered
    CHECK(career::MailActionablePending(s.emails[0], s));            // unread -> counts
    CHECK(!career::MailActionablePending(s.emails[1], s));           // read -> out of the badge
    CHECK(!career::MailActionsFor(s.emails[1], s).empty());          // but the Ignore button is still there
    CHECK(career::MailActionablePending(s.emails[2], s));            // the SUBSTITUTION is still a real decision
    CHECK_EQ(career::MailPendingDecisions(s), 2);                    // evinv_x + subinv_z
}
