// cmd.skins.status (full dispatch via ApiCore/apiq_call) -> {ok, installed_overrides,
// packs:[{slug,title,url,detected,detected_entries}]}. Test catalog in a temp dir, with
// paths::SetRootsForTest pointing "data" at that dir (the handler reads paths::Data("skins\\recommended_skins.json")).
// 2 packs: one with 1/2 entries detected (skin injected via SetSkinForTest), another with no match at all.
// Second half: catalog file ABSENT -> a "graceful" response {ok:true, packs:[]}, never an error.
static void test_api_skins_status() {
    char tmp[MAX_PATH], base[MAX_PATH];
    GetTempPathA(MAX_PATH, tmp);
    snprintf(base, sizeof(base), "%s\\ams2skinsstatus_%lu", tmp, (unsigned long)GetTickCount());
    std::string dataDir = base;
    std::string skinsDir = dataDir + "\\skins";
    auto mkdirs = [](const std::string& p){ std::string a; for(char c:p){ a+=c; if(c=='\\') CreateDirectoryA(a.c_str(),nullptr);} CreateDirectoryA(a.c_str(),nullptr); };
    auto writef = [](const std::string& p, const std::string& s){ FILE* f=fopen(p.c_str(),"wb"); if(f){fwrite(s.data(),1,s.size(),f);fclose(f);} };
    mkdirs(skinsDir);
    writef(skinsDir + "\\recommended_skins.json",
        "{\"version\":1,\"packs\":[\n"
        "{\"slug\":\"pack-detected\",\"title\":\"Pack Detected\",\"url\":\"https://example.com/a\","
        "\"author\":\"Jane Doe\",\"season_year\":\"2023\",\"series\":[\"Onyx_Cup_4824\",\"Pemberton_Zel121\"],\"entries\":[\n"
        " {\"vehicle\":\"brackenridge_m4_gt3\",\"livery_id\":51,\"skin_name\":\"Paul Miller Racing #1\"},\n"
        " {\"vehicle\":\"brackenridge_m4_gt3\",\"livery_id\":52,\"skin_name\":\"Turner Motorsports #95\"}\n"
        "]},\n"
        "{\"slug\":\"pack-missing\",\"title\":\"Pack Missing\",\"url\":\"https://example.com/b\","
        "\"author\":\"John Roe\",\"season_year\":\"2024\",\"series\":[\"Pemberton_Zel121\"],\"entries\":[\n"
        " {\"vehicle\":\"halcyon_a424\",\"livery_id\":10,\"skin_name\":\"Nope\"}\n"
        "]},\n"
        // pack collision: the SAME slot (brackenridge_m4_gt3,51) as pack-detected but a DIFFERENT skin_name -> must NOT detect
        // (regression guard for the 2024-vs-2025 false positive: installing one pack doesn't flag another one on the same car/slot).
        "{\"slug\":\"pack-collision\",\"title\":\"Pack Collision\",\"url\":\"https://example.com/c\","
        "\"author\":\"Zoe\",\"season_year\":\"2025\",\"series\":[\"Onyx_Cup_4824\"],\"entries\":[\n"
        " {\"vehicle\":\"brackenridge_m4_gt3\",\"livery_id\":51,\"skin_name\":\"Different Team #9\"}\n"
        "]}\n"
        "]}");

    career::ResetSkinsForTest();
    career::SetSkinForTest("brackenridge_m4_gt3", 51, "Paul Miller Racing #1");   // 1 of pack 1's 2 entries
    paths::SetRootsForTest(dataDir, "", "", "");

    capi::ApiCore core;
    capi::RegisterCareerQueries(core);
    auto r = apiq_call(core, "cmd.skins.status");
    CHECK(r && r->memberString("kind") == "result");
    const jsonm::Value* payload = r ? r->member("payload") : nullptr;
    CHECK(payload && payload->memberBool("ok"));
    CHECK(payload && payload->memberInt("installed_overrides") == 1);
    const jsonm::Value* packs = payload ? payload->member("packs") : nullptr;
    CHECK(packs && packs->isArray() && packs->arr.size() == 3);
    if (packs && packs->arr.size() == 3) {
        const jsonm::Value* p0 = packs->arr[0].get();
        CHECK(p0 && p0->memberString("slug")  == std::string("pack-detected"));
        CHECK(p0 && p0->memberString("title") == std::string("Pack Detected"));
        CHECK(p0 && p0->memberString("url")   == std::string("https://example.com/a"));
        CHECK(p0 && p0->memberBool("detected") == true);
        CHECK(p0 && p0->memberInt("detected_entries") == 1);
        // Enrichment: author/season_year/series[]/sample_vehicle/sample_livery_id
        CHECK(p0 && p0->memberString("author") == std::string("Jane Doe"));
        CHECK(p0 && p0->memberString("season_year") == std::string("2023"));
        const jsonm::Value* s0 = p0 ? p0->member("series") : nullptr;
        CHECK(s0 && s0->isArray() && s0->arr.size() == 2);
        CHECK(s0 && s0->arr.size() == 2 && s0->arr[0]->str == std::string("Onyx_Cup_4824"));
        CHECK(s0 && s0->arr.size() == 2 && s0->arr[1]->str == std::string("Pemberton_Zel121"));
        CHECK(p0 && p0->memberString("sample_vehicle") == std::string("brackenridge_m4_gt3"));
        CHECK(p0 && p0->memberInt("sample_livery_id") == 51);
        CHECK(p0 && p0->memberInt("entries_total") == 2);
        const jsonm::Value* p1 = packs->arr[1].get();
        CHECK(p1 && p1->memberString("slug") == std::string("pack-missing"));
        CHECK(p1 && p1->memberBool("detected") == false);
        CHECK(p1 && p1->memberInt("detected_entries") == 0);
        CHECK(p1 && p1->memberString("author") == std::string("John Roe"));
        CHECK(p1 && p1->memberString("sample_vehicle") == std::string("halcyon_a424"));
        CHECK(p1 && p1->memberInt("sample_livery_id") == 10);
        CHECK(p1 && p1->memberInt("entries_total") == 1);
        // pack collision: same (brackenridge_m4_gt3,51) as pack-detected but a different skin_name -> NOT detected
        // (the installed skin is "Paul Miller Racing #1", not "Different Team #9"). Fix for the false positive.
        const jsonm::Value* p2 = packs->arr[2].get();
        CHECK(p2 && p2->memberString("slug") == std::string("pack-collision"));
        CHECK(p2 && p2->memberBool("detected") == false);
        CHECK(p2 && p2->memberInt("detected_entries") == 0);
    }

    // missing catalog file -> graceful: ok:true, packs:[] (never an error; installed_overrides untouched)
    paths::ResetForTest();
    std::string emptyDir = dataDir + "_empty";
    mkdirs(emptyDir);
    paths::SetRootsForTest(emptyDir, "", "", "");
    auto r2 = apiq_call(core, "cmd.skins.status");
    CHECK(r2 && r2->memberString("kind") == "result");
    const jsonm::Value* payload2 = r2 ? r2->member("payload") : nullptr;
    CHECK(payload2 && payload2->memberBool("ok"));
    CHECK(payload2 && payload2->memberInt("installed_overrides") == 1);
    const jsonm::Value* packs2 = payload2 ? payload2->member("packs") : nullptr;
    CHECK(packs2 && packs2->isArray() && packs2->arr.empty());

    paths::ResetForTest();
    career::ResetSkinsForTest();   // hygiene for future tests
}

// DOMINANCE. Two packs for the SAME car sharing a slot with the
// SAME skin_name (e.g. "Max Verstappen #1" identical in the 2024 and 2025 pack because the driver didn't change
// teams): installing ONE attributes the shared slot ONLY to the pack with MORE total matches (the
// one actually installed). The other must NOT come out "detected" just because the names are shared.


// parseOverrideFile captures <PREVIEWIMAGE PATH="..."> per slot + cmd.skins.installed
// dumps the installed slots with their preview_rel. A REAL override is written (with and without PREVIEWIMAGE) in a
// temp dir and scanned with ScanInstalledSkins (exercises the real parser, not SetSkinForTest).


// Candidate factor catalog + player/cohort extraction (career_candidate).


// the occupant resolver reads the live world: who drives TODAY for that team in that class.
static void test_team_occupant_ids() {
    using namespace career;
    SaveData save;
    // A real series with seats is picked and the label of its first occupied seat is used, instead of
    // hardcoding a team name: names come from livery_team_equiv.psv and change with the data.
    const SeriesDef* sd = nullptr;
    std::string etiqueta, ocupante;
    for (const auto& s : AllSeries()) {
        if (IsEraMemorySeries(s)) continue;
        for (const auto& x : SeatsForClass(s.id, save))
            if (!x.occupant_id.empty() && !x.team_label.empty()) { etiqueta = x.team_label; ocupante = x.occupant_id; break; }
        if (!etiqueta.empty()) { sd = &s; break; }
    }
    CHECK(sd != nullptr);            // without this the rest wouldn't prove anything: the data has to be loaded
    if (!sd) return;

    std::set<std::string> ids = TeamOccupantIds(save, sd->class_name, etiqueta);
    CHECK(ids.count(ocupante) == 1);                             // the occupant comes out
    CHECK(TeamOccupantIds(save, sd->class_name, "").empty());    // empty label -> EMPTY set, not everyone
    CHECK(TeamOccupantIds(save, "", etiqueta).empty());          // empty class, same result
    // and it does NOT return the entire world: a team has a handful of seats, not the whole grid. If this
    // grew without limit, brandAff would be 1.0 for everyone and we'd be back to a step function from the other side.
    CHECK(ids.size() < 12);
}

// brandAff used to be FIXED at 0.0 for the whole cohort while the player got 1.0 or 0.0
// depending on their history. With a weight of up to 0.30, that column was a step function, not a comparison. The data
// needed to fix it already exists: a driver who OCCUPIES a seat at that team has affinity with it, and that's
// read from seat_occupant instead of being made up.
static void test_cohort_brand_affinity() {
    using namespace career;
    SaveData save;
    RosterDriver rd; rd.id = "rd_ana"; rd.name = "Ana Ferrer"; rd.base_skill = 0.7; rd.birth_year = 2000;

    // no occupant information -> 0.0, same as before (backward compatible)
    CandidateFactors sinInfo = CohortCandidateFactors(rd, save, "GT3", "Alpha Corse", "", 2026);
    CHECK(sinInfo.f[3] == 0.0);

    // occupies a seat at Alpha Corse -> has affinity with Alpha Corse
    std::set<std::string> ocupantesAlpha; ocupantesAlpha.insert("rd_ana");
    CandidateFactors conAlpha = CohortCandidateFactors(rd, save, "GT3", "Alpha Corse", "", 2026, &ocupantesAlpha);
    CHECK(conAlpha.f[3] == 1.0);

    // ...and NOT with another team: the set is per-team, not a global "has a team" flag
    std::set<std::string> ocupantesBeta; ocupantesBeta.insert("rd_otro");
    CandidateFactors conBeta = CohortCandidateFactors(rd, save, "GT3", "Beta Racing", "", 2026, &ocupantesBeta);
    CHECK(conBeta.f[3] == 0.0);

    // the rest of the columns don't move when the set is passed in (change SCOPED to f[3])
    for (int i = 0; i < bal::CANDFIT_FACTOR_COUNT; i++)
        if (i != 3) CHECK(conAlpha.f[i] == sinInfo.f[i]);

    // and it shows in the SCORE, not just the column: if the affinity never reached TeamCandidateFit, the table
    // would stay unchanged and this work would have been for nothing. It looks for a team whose personality weighs
    // brandAff, because for the ones that weight it at zero the score can't move (and that's correct).
    std::string equipoConMarca;
    for (int i = 0; i < 500 && equipoConMarca.empty(); i++) {
        const std::string lbl = "Marca " + std::to_string(i);
        if (bal::CANDFIT_W[TeamPersonality(lbl)][3] > 0.0) equipoConMarca = lbl;
    }
    CHECK(!equipoConMarca.empty());
    std::set<std::string> ocupa; ocupa.insert(rd.id);
    const CandidateFactors sin = CohortCandidateFactors(rd, save, "GT3", equipoConMarca, "", 2026);
    const CandidateFactors con = CohortCandidateFactors(rd, save, "GT3", equipoConMarca, "", 2026, &ocupa);
    CHECK(TeamCandidateFit(con, equipoConMarca, rd.id, 2026) > TeamCandidateFit(sin, equipoConMarca, rd.id, 2026));
}

// budget used to be FIXED at 0.0 for the cohort against the player's 1.0. But handing it out with no
// cap is WORSE: a rival's score is the MAXIMUM over dozens of drivers, and the max of a uniform
// distribution saturates to 1, so a loaded rival always shows up. Measured: 36 losses out of 36, and offers dropping from 60 to 24.
// The cap keeps money as a real player advantage without turning it into a lottery.
static void test_cohort_budget_bounded() {
    using namespace career;
    SaveData save;
    CHECK(bal::CANDFIT_COHORT_BUDGET_CAP > 0.0);
    CHECK(bal::CANDFIT_COHORT_BUDGET_CAP < 1.0);   // with a cap of 1.0 we're back to the max problem

    double minv = 2.0, maxv = -1.0, suma = 0.0;
    const int N = 400;
    for (int i = 0; i < N; i++) {
        RosterDriver rd; rd.id = "rd_" + std::to_string(i); rd.base_skill = 0.5; rd.birth_year = 1998;
        double b = CohortCandidateFactors(rd, save, "GT3", "Alpha Corse", "", 2026).f[7];
        CHECK(b >= 0.0 && b <= bal::CANDFIT_COHORT_BUDGET_CAP);   // never above the cap
        if (b < minv) minv = b;
        if (b > maxv) maxv = b;
        suma += b;
    }
    // genuinely SPREAD OUT: if everyone brought the same amount, money would stop distinguishing one rival from
    // another, and we'd be back to one repeated dispute.
    CHECK(maxv - minv > bal::CANDFIT_COHORT_BUDGET_CAP * 0.5);
    const double media = suma / N;
    CHECK(media > 0.0 && media < bal::CANDFIT_COHORT_BUDGET_CAP);

    // DETERMINISTIC by id: the same driver brings the same budget for the whole career, not a new one every refresh
    RosterDriver a; a.id = "rd_ana"; a.base_skill = 0.6; a.birth_year = 2001;
    const double b1 = CohortCandidateFactors(a, save, "GT3", "Alpha Corse", "", 2026).f[7];
    const double b2 = CohortCandidateFactors(a, save, "GT4", "Beta Racing",  "", 2030).f[7];
    CHECK(b1 == b2);   // it doesn't depend on the team, the class, or the year: it's THEIRS

    // two different drivers don't bring the same amount (or the spread isn't spreading)
    RosterDriver c; c.id = "rd_caio"; c.base_skill = 0.6; c.birth_year = 2001;
    CHECK(CohortCandidateFactors(c, save, "GT3", "Alpha Corse", "", 2026).f[7] != b1);

    // and the budget draw is NOT correlated with the score-noise draw: both start from the driver's
    // id, and without its own seed a driver lucky in one would be lucky in the other too, and money would stop
    // being an independent column. Checked via the tail: among those with the fattest budget, there has
    // to be a mix from both sides of the noise, not all from the same one.
    int ricosConRuidoAlto = 0, ricosConRuidoBajo = 0;
    for (int i = 0; i < N; i++) {
        RosterDriver rd; rd.id = "rd_" + std::to_string(i); rd.base_skill = 0.5; rd.birth_year = 1998;
        const CandidateFactors f = CohortCandidateFactors(rd, save, "GT3", "Alpha Corse", "", 2026);
        if (f.f[7] < bal::CANDFIT_COHORT_BUDGET_CAP * 0.75) continue;   // only the top quarter
        CandidateFactors cero;                                          // everything at 0: the score is pure noise
        (TeamCandidateFit(cero, "Alpha Corse", rd.id, 2026) > bal::CANDFIT_NOISE_W * 0.5)
            ? ricosConRuidoAlto++ : ricosConRuidoBajo++;
    }
    CHECK(ricosConRuidoAlto > 0 && ricosConRuidoBajo > 0);
}

// Behavioral guard -- different team personalities rank the
// same pair of candidates DIFFERENTLY (TeamCandidateFit isn't a single score blind to who's asking).
static void test_team_candidate_fit() {
    using namespace career;
    // two candidates: A = young+clean, weak on skill; B = veteran, strong on skill.
    CandidateFactors A; A.f[0]=0.4; A.f[1]=0.95; A.f[6]=0.95;   // low skill, high clean/youth
    CandidateFactors B; B.f[0]=0.95; B.f[1]=0.5; B.f[6]=0.1;    // high skill, older
    // Brute-forces a teamLabel that seeds "cantera_joven"(1) and another "meritocratico"(0).
    std::string youthTeam, meritTeam;
    for (int i = 0; i < 500 && (youthTeam.empty() || meritTeam.empty()); ++i) {
        std::string t = "T" + std::to_string(i);
        int p = TeamPersonality(t);
        if (p == 1 && youthTeam.empty()) youthTeam = t;         // cantera_joven
        if (p == 0 && meritTeam.empty()) meritTeam = t;         // meritocratico
    }
    CHECK(!youthTeam.empty() && !meritTeam.empty());
    // cantera_joven prefers A (young+clean) over B; meritocratico prefers B (skill) over A.
    CHECK(TeamCandidateFit(A, youthTeam, "a", 2025) > TeamCandidateFit(B, youthTeam, "b", 2025));
    CHECK(TeamCandidateFit(B, meritTeam, "b", 2025) > TeamCandidateFit(A, meritTeam, "a", 2025));
    // deterministic: same input -> same score.
    CHECK(TeamCandidateFit(A, youthTeam, "a", 2025) == TeamCandidateFit(A, youthTeam, "a", 2025));
}

// Seat contest -- the player only wins if they're the STRONGEST candidate (within a
// MK_SEAT_CONTEST_MARGIN tolerance). Extreme fixtures: a very strong player vs. a mediocre cohort -> ALWAYS wins (regardless of
// team personality); a very weak player vs. a strong cohort -> loses.
static void test_player_wins_seat() {
    using namespace career;
    SaveData save;
    save.player.birth_year = 2004; save.prog.cleanliness = 95.0; save.prog.rating = 2200; save.prog.rep = 250;
    // a very strong player (rating 2200) -> beats a mediocre cohort under ANY personality.
    std::vector<RosterDriver> weak;
    { RosterDriver r; r.id="rd_w"; r.country="IT"; r.archetype="variable"; r.base_skill=0.6; r.birth_year=1980; weak.push_back(r); }
    CHECK(PlayerWinsSeat(save, "GT3", "Team X", "", 0.0, 2025, weak));
    // a very weak player (rating 1150) against a strong cohort -> loses.
    SaveData weakSave; weakSave.player.birth_year=1975; weakSave.prog.rating=1150; weakSave.prog.cleanliness=40.0;
    std::vector<RosterDriver> strong;
    { RosterDriver r; r.id="rd_s"; r.country="IT"; r.archetype="metronomo"; r.base_skill=0.98; r.birth_year=2000; strong.push_back(r); }
    CHECK(!PlayerWinsSeat(weakSave, "GT3", "Team X", "", 0.0, 2025, strong));
}

// the seat contest used to be calculated IN FULL and then thrown away: PlayerWinsSeat returned a yes/no
// and with it, who you were actually competing against got lost -- exactly what needs to be shown. RankSeatCandidates
// returns the table; the verdict comes from it, so the two can never drift apart.
static void test_rank_seat_candidates() {
    using namespace career;
    SaveData save;
    save.player.name = "Alex"; save.player.surname = "Vega";
    save.player.birth_year = 2004; save.prog.cleanliness = 95.0; save.prog.rating = 2200; save.prog.rep = 250;
    // This fixture used to call itself "a very strong player" and beat Ana Ferrer by +0.00058 --
    // a tie decided by noise, not merit. It passed by sheer luck: ANY column that moved would
    // flip it, and the budget one did. The cause was that a driver with 2200 rating and 250 reputation had
    // NOT A SINGLE race in GT3, so seriesExp was 0 while the incumbent cohort scored 1.0. With the class
    // actually raced, the margin becomes +0.096, and the word "very strong" in the comment is finally true.
    save.class_stats["GT3"].races = (int)bal::CANDFIT_EXP_REF;

    std::vector<RosterDriver> cohort;
    { RosterDriver r; r.id="rd_b"; r.name="Bruno Melo";  r.country="IT"; r.archetype="variable";  r.base_skill=0.60; r.birth_year=1980; cohort.push_back(r); }
    { RosterDriver r; r.id="rd_a"; r.name="Ana Ferrer";  r.country="IT"; r.archetype="metronomo"; r.base_skill=0.92; r.birth_year=2001; cohort.push_back(r); }
    { RosterDriver r; r.id="rd_c"; r.name="Caio Duarte"; r.country="BR"; r.archetype="rapido";    r.base_skill=0.75; r.birth_year=1995; cohort.push_back(r); }

    std::vector<SeatCandidate> rank = RankSeatCandidates(save, "GT3", "Team X", "", 0.0, 2025, cohort);
    CHECK_EQ((int)rank.size(), 4);                       // the three from the cohort PLUS the player
    // sorted best score to worst, no exceptions
    for (size_t i = 1; i < rank.size(); i++) CHECK(rank[i-1].fit >= rank[i].fit);
    // the player appears ONCE, flagged, and with their display name (not the id)
    int players = 0; std::string playerName;
    for (const auto& c : rank) if (c.is_player) { players++; playerName = c.name; }
    CHECK_EQ(players, 1);
    CHECK(playerName == "Alex Vega");
    // rivals arrive WITH A NAME, which is what gets rendered
    bool vistoAna = false;
    for (const auto& c : rank) if (c.id == "rd_a") vistoAna = (c.name == "Ana Ferrer");
    CHECK(vistoAna);

    // DETERMINISTIC and independent of input order: shuffling the cohort gives the SAME table. Without the
    // id tiebreaker, two equal scores came out in whatever order they arrived, and the "main" rival would shift around.
    std::vector<RosterDriver> shuffled;
    shuffled.push_back(cohort[2]); shuffled.push_back(cohort[0]); shuffled.push_back(cohort[1]);
    std::vector<SeatCandidate> rank2 = RankSeatCandidates(save, "GT3", "Team X", "", 0.0, 2025, shuffled);
    CHECK_EQ((int)rank2.size(), 4);
    for (size_t i = 0; i < rank.size() && i < rank2.size(); i++) {
        CHECK(rank[i].id == rank2[i].id);
        CHECK(rank[i].fit == rank2[i].fit);
    }

    // THE VERDICT COMES FROM THE TABLE: with this very strong player they rank first AND win the seat. The two
    // paths have to agree, or the screen would show one thing while the engine did another.
    CHECK(rank[0].is_player);
    CHECK(PlayerWinsSeat(save, "GT3", "Team X", "", 0.0, 2025, cohort));

    // and the reverse: a weak player does NOT rank first and does not win either
    SaveData weakSave; weakSave.player.name="Nadie"; weakSave.player.birth_year=1975;
    weakSave.prog.rating=1150; weakSave.prog.cleanliness=40.0;
    std::vector<SeatCandidate> weakRank = RankSeatCandidates(weakSave, "GT3", "Team X", "", 0.0, 2025, cohort);
    CHECK(!weakRank.empty() && !weakRank[0].is_player);
    CHECK(!PlayerWinsSeat(weakSave, "GT3", "Team X", "", 0.0, 2025, cohort));

    // with no known rivals the player is left alone in the table and wins: ABSENCE cannot penalize them
    std::vector<SeatCandidate> alone = RankSeatCandidates(weakSave, "GT3", "Team X", "", 0.0, 2025, {});
    CHECK_EQ((int)alone.size(), 1);
    CHECK(alone[0].is_player);
    CHECK(PlayerWinsSeat(weakSave, "GT3", "Team X", "", 0.0, 2025, {}));
}

// the place that shows the rival (GenerateOffers) needs the verdict AND the name from the SAME
// table. If it ranked separately from the verdict, the screen could end up saying one thing while the engine did another.
// This locks in that link: PlayerWinsRankedSeat over the table == PlayerWinsSeat, always; and the rival is the first
// non-player entry in the sorted table.
static void test_ranked_seat_verdict_and_rival() {
    using namespace career;
    SaveData save;
    save.player.name = "Alex"; save.player.surname = "Vega";
    save.player.birth_year = 2004; save.prog.cleanliness = 95.0; save.prog.rating = 2200; save.prog.rep = 250;
    save.class_stats["GT3"].races = (int)bal::CANDFIT_EXP_REF;   // same reason as in test_rank_seat_candidates

    std::vector<RosterDriver> cohort;
    { RosterDriver r; r.id="rd_b"; r.name="Bruno Melo";  r.country="IT"; r.archetype="variable";  r.base_skill=0.60; r.birth_year=1980; cohort.push_back(r); }
    { RosterDriver r; r.id="rd_a"; r.name="Ana Ferrer";  r.country="IT"; r.archetype="metronomo"; r.base_skill=0.92; r.birth_year=2001; cohort.push_back(r); }
    { RosterDriver r; r.id="rd_c"; r.name="Caio Duarte"; r.country="BR"; r.archetype="rapido";    r.base_skill=0.75; r.birth_year=1995; cohort.push_back(r); }

    SaveData weakSave; weakSave.player.name="Nadie"; weakSave.player.birth_year=1975;
    weakSave.prog.rating=1150; weakSave.prog.cleanliness=40.0;

    // the verdict does NOT change by pulling it from the table: same yes/no across all three scenarios (wins, loses, alone)
    struct Caso { const SaveData* sv; const std::vector<RosterDriver>* co; };
    std::vector<RosterDriver> vacia;
    Caso casos[3] = { { &save, &cohort }, { &weakSave, &cohort }, { &weakSave, &vacia } };
    for (const Caso& c : casos) {
        std::vector<SeatCandidate> rk = RankSeatCandidates(*c.sv, "GT3", "Team X", "", 0.0, 2025, *c.co);
        CHECK(PlayerWinsRankedSeat(rk) == PlayerWinsSeat(*c.sv, "GT3", "Team X", "", 0.0, 2025, *c.co));
    }

    // the rival is the best one who ISN'T you. With a strong player ranking first, the rival is 2nd in the table.
    std::vector<SeatCandidate> rank = RankSeatCandidates(save, "GT3", "Team X", "", 0.0, 2025, cohort);
    CHECK(rank[0].is_player);
    const SeatCandidate* riv = TopRivalInRank(rank);
    CHECK(riv != nullptr);
    CHECK(!riv->is_player);
    CHECK(riv->id == rank[1].id);
    // and it's the BEST one in the cohort, not just anyone
    for (const auto& c : rank) if (!c.is_player) CHECK(riv->fit >= c.fit);

    // with a weak player the rival is still whoever ranks first in the table (which by then isn't the player)
    std::vector<SeatCandidate> weakRank = RankSeatCandidates(weakSave, "GT3", "Team X", "", 0.0, 2025, cohort);
    const SeatCandidate* weakRiv = TopRivalInRank(weakRank);
    CHECK(weakRiv != nullptr);
    CHECK(weakRiv->id == weakRank[0].id);

    // competing alone -> no rival to show (and none is invented)
    std::vector<SeatCandidate> alone = RankSeatCandidates(weakSave, "GT3", "Team X", "", 0.0, 2025, {});
    CHECK(TopRivalInRank(alone) == nullptr);
}

// "you're being watched": the contest used to have TWO outcomes (you get it / silence). The band carves out a third
// one WITHIN the silence: you stay close and the team watches you for a few races. What you WIN today can't change.
static void test_classify_ranked_seat() {
    using namespace career;
    auto mk = [](double playerFit, double cohortFit) {
        std::vector<SeatCandidate> rk;
        SeatCandidate p; p.id = "player"; p.is_player = true; p.fit = playerFit; rk.push_back(p);
        SeatCandidate c; c.id = "rd_x";   c.fit = cohortFit;  rk.push_back(c);
        return rk;
    };
    // HARD INVARIANT: WON is exactly PlayerWinsRankedSeat. If the two ever drifted apart, the band would be taking away
    // offers from people who currently have them, which is exactly what this change must NOT do.
    const double pares[6][2] = { {0.50,0.50}, {0.60,0.50}, {0.45,0.50}, {0.40,0.50}, {0.42,0.50}, {0.00,0.00} };
    for (const auto& pr : pares) {
        std::vector<SeatCandidate> rk = mk(pr[0], pr[1]);
        CHECK((ClassifyRankedSeat(rk) == SEAT_CONTEST_WON) == PlayerWinsRankedSeat(rk));
    }
    CHECK_EQ(ClassifyRankedSeat(mk(0.50, 0.50)), (int)SEAT_CONTEST_WON);     // a tie -> the seat is yours
    CHECK_EQ(ClassifyRankedSeat(mk(0.60, 0.50)), (int)SEAT_CONTEST_WON);
    CHECK_EQ(ClassifyRankedSeat(mk(0.45, 0.50)), (int)SEAT_CONTEST_WATCH);   // 0.05 below -> within the band
    CHECK_EQ(ClassifyRankedSeat(mk(0.40, 0.50)), (int)SEAT_CONTEST_LOST);    // 0.10 below -> outside
    // the band's EXACT edge (0.08) counts as observation, not as a loss
    CHECK_EQ(ClassifyRankedSeat(mk(0.50 - bal::MK_SEAT_WATCH_BAND, 0.50)), (int)SEAT_CONTEST_WATCH);
    // with nobody up against you there's no contest to lose (bestCohort starts at 0: absence doesn't penalize)
    std::vector<SeatCandidate> solo; { SeatCandidate p; p.id="player"; p.is_player=true; p.fit=0.01; solo.push_back(p); }
    CHECK_EQ(ClassifyRankedSeat(solo), (int)SEAT_CONTEST_WON);
}

// the lifecycle of an observation period. What gives it meaning is that it resolves with your data from BACK THEN
// and that losing it COSTS something (the seat closes for a while); otherwise it would just be decoration.
static void test_seat_watch_lifecycle() {
    using namespace career;
    SaveData save;
    save.class_stats["GT3"].races = 5;
    const int day0 = 739000;

    // The list of contenders gets sealed; the first one is the main rival (the one that's shown)
    std::vector<SeatContender> lista;
    { SeatContender c; c.id = "rd_ana";  c.name = "Ana Ferrer";  lista.push_back(c); }
    { SeatContender c; c.id = "rd_caio"; c.name = "Caio Duarte"; lista.push_back(c); }
    CHECK(SeatWatchOpen(save, "gt3_eu", "GT3", "Alpha Corse", lista, day0));
    CHECK_EQ((int)save.seat_watches.size(), 1);
    const SeatWatch* w = FindSeatWatch(save, "gt3_eu", "Alpha Corse");
    CHECK(w != nullptr);
    CHECK(w->rival_name == "Ana Ferrer");
    // The list stays SEALED, and the main rival is its first entry (not a separate field that could drift)
    CHECK_EQ((int)w->contenders.size(), 2);
    CHECK(w->contenders[0].id == "rd_ana" && w->contenders[1].id == "rd_caio");
    CHECK(w->rival_id == w->contenders[0].id);
    CHECK_EQ(w->races_at_open, 5);                       // freezes WHERE you stood, not a separate counter
    CHECK_EQ(SeatWatchRacesLeft(save, *w), bal::MK_SEAT_WATCH_RACES);
    CHECK(!SeatWatchDue(save, *w, day0));

    // opening it twice does NOT reset the deadline: the board refreshes constantly, and that would hand out an endless window
    CHECK(!SeatWatchOpen(save, "gt3_eu", "GT3", "Alpha Corse", lista, day0 + 10));
    CHECK_EQ((int)save.seat_watches.size(), 1);
    CHECK_EQ(FindSeatWatch(save, "gt3_eu", "Alpha Corse")->opened_day, day0);

    // A player noted on 28/07: you get observed while racing ANYWHERE -- usually NOT in their series (they're watching
    // from above while you compete in your own). Counting only races in their class, a GT3 team watching
    // you while you race in F4 would never have seen a single race, and the window would never have counted down.
    save.class_stats["F4"].races = 1;
    CHECK_EQ(SeatWatchRacesLeft(save, *FindSeatWatch(save, "gt3_eu", "Alpha Corse")), bal::MK_SEAT_WATCH_RACES - 1);
    save.class_stats["F4"].races = 0;

    // race in the class -> the window counts down on its own (derived, not incremented)
    save.class_stats["GT3"].races = 7;
    CHECK_EQ(SeatWatchRacesLeft(save, *FindSeatWatch(save, "gt3_eu", "Alpha Corse")), bal::MK_SEAT_WATCH_RACES - 2);
    CHECK(!SeatWatchDue(save, *FindSeatWatch(save, "gt3_eu", "Alpha Corse"), day0 + 20));
    save.class_stats["GT3"].races = 5 + bal::MK_SEAT_WATCH_RACES;
    CHECK_EQ(SeatWatchRacesLeft(save, *FindSeatWatch(save, "gt3_eu", "Alpha Corse")), 0);
    CHECK(SeatWatchDue(save, *FindSeatWatch(save, "gt3_eu", "Alpha Corse"), day0 + 20));

    // it also expires by DAYS: with no contract in the class you don't race in it, and the window would never count down
    SaveData parado;
    CHECK(SeatWatchOpen(parado, "gt3_eu", "GT3", "Alpha Corse", lista, day0));
    CHECK(!SeatWatchDue(parado, parado.seat_watches[0], day0 + bal::MK_SEAT_WATCH_MAX_DAYS - 1));
    CHECK(SeatWatchDue(parado, parado.seat_watches[0], day0 + bal::MK_SEAT_WATCH_MAX_DAYS));

    // losing it CLOSES the seat for a while (and only that seat: not the whole series, not another team)
    const int dayClose = day0 + 20;
    SeatWatchClose(*FindSeatWatch(save, "gt3_eu", "Alpha Corse"), false, dayClose);
    CHECK(FindSeatWatch(save, "gt3_eu", "Alpha Corse") == nullptr);       // no longer live
    CHECK(SeatWatchOnCooldown(save, "gt3_eu", "Alpha Corse", dayClose));
    CHECK(SeatWatchOnCooldown(save, "gt3_eu", "Alpha Corse", dayClose + bal::MK_SEAT_WATCH_COOLDOWN_DAYS - 1));
    CHECK(!SeatWatchOnCooldown(save, "gt3_eu", "Alpha Corse", dayClose + bal::MK_SEAT_WATCH_COOLDOWN_DAYS));
    CHECK(!SeatWatchOnCooldown(save, "gt3_eu", "Beta Racing", dayClose));  // another team in the same series: free
    CHECK(!SeatWatchOnCooldown(save, "onyx_cup_5193", "Alpha Corse", dayClose));  // the same team in another series: free

    // WINNING it cools nothing down: the seat is yours, there's no door to close
    SaveData ganada; ganada.class_stats["GT3"].races = 5;
    CHECK(SeatWatchOpen(ganada, "gt3_eu", "GT3", "Alpha Corse", lista, day0));
    SeatWatchClose(*FindSeatWatch(ganada, "gt3_eu", "Alpha Corse"), true, dayClose);
    CHECK(!SeatWatchOnCooldown(ganada, "gt3_eu", "Alpha Corse", dayClose));

    // closing it twice doesn't rewrite the verdict (a board refresh can't turn a loss into a win)
    SeatWatchClose(save.seat_watches[0], true, dayClose + 5);
    CHECK_EQ(save.seat_watches[0].state, 2);
    CHECK_EQ(save.seat_watches[0].resolved_day, dayClose);

    // pruning drops closed ones that no longer matter; LIVE ones are never touched no matter how much time passes
    CHECK_EQ(SeatWatchPrune(save, dayClose + 1), 0);
    CHECK_EQ(SeatWatchPrune(save, dayClose + bal::MK_SEAT_WATCH_COOLDOWN_DAYS), 1);
    CHECK_EQ((int)save.seat_watches.size(), 0);
    CHECK_EQ(SeatWatchPrune(parado, day0 + 100000), 0);
    CHECK_EQ((int)parado.seat_watches.size(), 1);
}

// A player's feedback: "first the drivers contesting the seat are chosen, and only then does the
// best one take it in the end". ShortlistFromRank is that selection: the N best who aren't you, in order.
static void test_shortlist_from_rank() {
    using namespace career;
    std::vector<SeatCandidate> rank;
    { SeatCandidate c; c.id="rd_a"; c.name="A"; c.fit=0.90; rank.push_back(c); }
    { SeatCandidate p; p.id="player"; p.name="Yo"; p.fit=0.80; p.is_player=true; rank.push_back(p); }
    { SeatCandidate c; c.id="rd_b"; c.name="B"; c.fit=0.70; rank.push_back(c); }
    { SeatCandidate c; c.id="rd_c"; c.name="C"; c.fit=0.60; rank.push_back(c); }
    { SeatCandidate c; c.id="rd_d"; c.name="D"; c.fit=0.50; rank.push_back(c); }

    std::vector<SeatContender> sl = ShortlistFromRank(rank);
    CHECK_EQ((int)sl.size(), bal::MK_SEAT_WATCH_SHORTLIST);
    CHECK(sl[0].id == "rd_a" && sl[1].id == "rd_b" && sl[2].id == "rd_c");   // the best ones, in order
    CHECK(sl[0].name == "A");                                               // with a name, which is what gets shown
    for (const auto& c : sl) CHECK(c.id != "player");                       // you don't compete against yourself
    // the weakest one is left OUT: the contest isn't "the whole cohort", it's a trio
    for (const auto& c : sl) CHECK(c.id != "rd_d");

    // fewer contenders than slots -> the list is whatever there is (nothing is padded in)
    std::vector<SeatCandidate> corta;
    { SeatCandidate p; p.id="player"; p.is_player=true; p.fit=0.80; corta.push_back(p); }
    { SeatCandidate c; c.id="rd_x"; c.name="X"; c.fit=0.70; corta.push_back(c); }
    CHECK_EQ((int)ShortlistFromRank(corta).size(), 1);
    // competing alone -> empty list (and SeatWatchOpen accepts it: you get watched with nobody up against you)
    std::vector<SeatCandidate> solo;
    { SeatCandidate p; p.id="player"; p.is_player=true; p.fit=0.10; solo.push_back(p); }
    CHECK_EQ((int)ShortlistFromRank(solo).size(), 0);
    SaveData s;
    CHECK(SeatWatchOpen(s, "gt3_eu", "GT3", "Alpha Corse", ShortlistFromRank(solo), 739000));
    CHECK(s.seat_watches[0].rival_id.empty() && s.seat_watches[0].contenders.empty());
}

// The window's SEALED KEYS survive save/load, and a save that doesn't
// carry them still loads cleanly. This guarantee isn't just an aspiration: a twenty-season career
// can't be broken because we changed the market. What gets sealed is the seat's IDENTITY
// (series|team) and its state; the details keep being derived live, the same pattern as the sealed
// trio above -- it gives the stability of a snapshot without actually being one, which would age badly as the world moves.


// OPENING THE WINDOW seals the keys. Up to this point the structure existed and nothing was
// filling it in. The seats in play are the ones whose contracts EXPIRE this year (expiry derived from
// an earlier rule), filtered down to what's within the player's reach -- it asks for "few and readable", not the whole world.


// phase 2b: THE COHORT'S SKILL DOES NOT COME FROM A FLAT MAPPING. Without this the cohort fell to
// (1200 + base_skill x 700), which ignores the category: base_skill is the rank WITHIN the grid, not a
// absolute level, so a karting kid with 0.97 scored 1879 -- a world-champion rating -- and would
// steamroll the player in their own feeder series. It's the same bug that an earlier fix addressed for the skill floor,
// left alive in this other doorway. Measured before the fix: 0 seats won out of 23 at the start.
//
// 17/09 — AND THE PRECEDENCE HAS THREE STEPS, NOT TWO. This test measured them all with `rk_lucia`, taking
// for granted --without saying so-- that the STATIC world does not seat her anywhere: with no seat, `BaseTalent`
// returned 0 and `agedRatingFor` fell into its by-seat branch, which is the only one that looks at the tier it is passed.
// Since the cohort is distributed by rotation, Lucia occupies EIGHT slots and has talent of her own, so her
// number no longer depends on the series being contested: 1485 in karting and 1485 in Pemberton_Zel121. The old claim
// ("the same 0.97 cannot be worth the same in the nursery as in the elite") stopped being true FOR HER.
//
// And it is not a hole: it is the doctrine of `BaseTalent` --"their talent has to be THEIRS, not that of the seat they
//  occupy today"-- finally reaching this gate. The 1485 is not just any number either: it is EXACTLY her
//  `CohortAnchoredSeed`, i.e. what `SeedAllDrivers` writes to `driver_ratings` when the game starts.
//  The static derivation and the official seeding now say the SAME, which did not happen before. And in production this
//  path is not even stepped on: the first branch (`driver_ratings`) always wins, because the cohort is seeded from
//  minute zero of the career. What changes here is the fallback, not what the player sees.
//
// The ladder the test defended still exists, but it lives where it belongs: in AGAINST WHOM the seat is contested
// (the occupants of that class and the `DemandForClass` bar), not in re-scoring the same
// person depending on the door they call through. So the THREE steps are measured, each with the subject that
// really goes through it.


// ONE DRIVER, ONE SEAT. Whoever is already staying put next season can't also be
// contesting you for another seat. The cohort was occupying SEVERAL seats at once (measured at 1.61 per occupant), and the
// market ranked the whole cohort against the player for every single seat. It's not that they were too good -- being
// monsters from day one is a deliberate design choice -- the problem was that they were
// everywhere at once, which doesn't happen in real life.


// THE COMPRESSED YEAR-1 CYCLE, end to end. This is the answer to "how does the player
// get contracts in their first season": no AI contract expires in year one, so under the
// normal calendar they'd wait until September. Year 1 has its own decision week in February, and its
// supply is the preseason seats that already open when the career is created, not expiries.


// THE CAREER IS BORN BEFORE ITS OWN WINDOW. This is the test that was missing, and it's why the
// compressed year-1 cycle -- tested, green, and complete -- was UNREACHABLE in production: the earlier tests
// used synthetic doys ("a day in January", "February 15th") and none of them compared those against the day
// a career actually starts on. Measured on 05/08: the career was born on RookieOpenerDoy (doy 55, the earliest
// level-1 opener), while year 1's decision week falls on doy 46. Nine days late: the player
// showed up with their silly season already resolved and never saw a single seat.
//
// The correct shape of year 1, and what this test locks in: YOU'RE BORN -> window open -> decision week ->
// YOUR FIRST RACE. In that order, with no overlap.


// THE MARKET'S HEARTBEAT. What plugs the window into the clock -- until this fix nobody called
// OpenTransferWindow or ResolveDecisionWeek in production, so the silly season was written, tested,
// and dead. This covers the three things the heartbeat has to guarantee: that it opens, that it resolves, and that it resolves
// EVEN WHEN the player skips past the week with a clock jump (the world doesn't wait for you).


// SOUNDING YOU OUT -- the team reaching out to YOU. Until now the only way into a seat
// was applying, so nothing ever produced the BEING-SOUNDED-OUT state: half the charm of a silly season
// being called -- simply didn't exist in the game.


// SIGNING an OFFERED seat. It's the last step of the year-1 cycle, and without it everything before
// was just decoration: the decision week left seats in the OFFERED state with no way to actually take them.


// THE MARKET'S DATES ON THE CALENDAR. Until now the market had a calendar that only
// the engine knew about: the player saw eight blank preseason weeks with a decisive date hidden inside and
// nothing marking it. Plus the skip warning, which stops you from missing it without noticing.
static void test_market_marks_and_skip_warning() {
    using namespace career;
    using namespace career::dateutil;
    const int y1 = kStartYear;

    // year 1's markers: TWO windows and TWO decision weeks (the compressed cycle + the usual one) --
    std::vector<market::MarketMark> m1 = market::MarketMarksForYear(y1, y1);
    CHECK_EQ((int)m1.size(), 4);
    if (m1.size() < 4) return;
    CHECK_EQ(m1[0].kind, (int)market::MARK_WINDOW_OPEN);
    CHECK_EQ(m1[0].doy, 1);                                   // you're born with the window already open
    CHECK_EQ(m1[1].kind, (int)market::MARK_DECISION_WEEK);
    CHECK_EQ(m1[1].doy, market::MarketY1DecisionDoy(y1));
    CHECK_EQ(m1[1].days, bal::MK_DECISION_WEEK_DAYS);
    CHECK_EQ(m1[2].doy, market::MarketWindowOpenDoy(y1));      // September: year 2's window
    CHECK_EQ(m1[3].doy, market::MarketDecisionDoy(y1));
    // the December one lands at year's end (there's no following season to roll the clock back into)
    CHECK_EQ(m1[3].doy + m1[3].days - 1, DaysInYear(y1));
    // sorted by date, which is how they're rendered
    for (size_t i = 1; i < m1.size(); i++) CHECK(m1[i].doy > m1[i-1].doy);

    // any ordinary year: only the usual two -----------------------------------------------------
    std::vector<market::MarketMark> m3 = market::MarketMarksForYear(y1 + 2, y1);
    CHECK_EQ((int)m3.size(), 2);

    // THE WARNING: "go to the next race" swallows February's week ------------------------------
    // This is the REAL case of a new career: you're born on January 1st and the calendar's first event is on
    // doy 55. The jump skips right over February 15th without landing on it.
    const int hoy    = AbsDayFromYearDoy(y1, kCareerStartDoy);
    const int carrera = AbsDayFromYearDoy(y1, 55);
    const int aviso = market::DecisionWeekSkippedBetween(hoy, carrera, y1);
    CHECK(aviso != 0);
    CHECK_EQ(aviso, AbsDayFromYearDoy(y1, market::MarketY1DecisionDoy(y1)));

    // VERIFIED SABOTAGE: landing INSIDE the week isn't skipping it -- you arrive on time, and warning there
    // would be crying wolf. If the predicate used ">= start" instead of "> end", this would trigger a false alarm.
    const int dentro = AbsDayFromYearDoy(y1, market::MarketY1DecisionDoy(y1) + 2);
    CHECK_EQ(market::DecisionWeekSkippedBetween(hoy, dentro, y1), 0);
    // ...and falling short doesn't warn either
    CHECK_EQ(market::DecisionWeekSkippedBetween(hoy, AbsDayFromYearDoy(y1, 30), y1), 0);

    // a jump that CROSSES THE YEAR swallows December's week, which is the one that hurts the most
    const int dic = market::DecisionWeekSkippedBetween(AbsDayFromYearDoy(y1 + 1, 300),
                                                       AbsDayFromYearDoy(y1 + 2, 40), y1);
    CHECK_EQ(dic, AbsDayFromYearDoy(y1 + 1, market::MarketDecisionDoy(y1 + 1)));

    // a jump backward or to the same day warns of nothing
    CHECK_EQ(market::DecisionWeekSkippedBetween(carrera, hoy, y1), 0);
    CHECK_EQ(market::DecisionWeekSkippedBetween(hoy, hoy, y1), 0);

    // the markers reach query.calendar, labeled PER DAY ---------------------------------------
    // The seven days of decision week come out blank on the calendar, and a blank day reads
    // as "free". Each marker carries its own TR key so those rows can say what they actually are.
    static capi::CalendarView s_cv;
    s_cv = capi::CalendarView{};
    s_cv.loaded = true; s_cv.calibrated = true;
    s_cv.year = y1; s_cv.cursorDoy = kCareerStartDoy; s_cv.frontierPhase = 1;
    capi::SetCalendarViewProvider([]() { return s_cv; });
    capi::HandlerResult r = capi::QueryCalendar(nullptr);
    CHECK(r.ok);
    CHECK(r.payload.find("\"marketMarks\"") != std::string::npos);
    CHECK(r.payload.find("\"kind\":\"decision\"") != std::string::npos);
    CHECK(r.payload.find("\"kind\":\"window\"") != std::string::npos);
    // a TR key, NOT raw text: if "Decision week" came out bare here, the screen would be monolingual and the
    // engine would be deciding the language, which is exactly what the project stopped doing once it went bilingual EN/ES.
    CHECK(r.payload.find("\"dayLabelKey\":\"cal_day_decision\"") != std::string::npos);
    // the date goes as "Feb 15" (month day), the same format the calendar slots use and the one the
    // date column knows how to split. DoyToDate gives "15 Feb", which would have painted the number as the month and the month as the day.
    CHECK(r.payload.find("\"date\":\"Feb 15\"") != std::string::npos);
    CHECK(r.payload.find("\"date\":\"15 Feb\"") == std::string::npos);
    CHECK(r.payload.find("\"labelKey\":\"cal_mark_decision\"") != std::string::npos);
    CHECK(r.payload.find("Semana de") == std::string::npos);
    CHECK(r.payload.find("Decision week") == std::string::npos);
    capi::SetCalendarViewProvider(nullptr);
}

// query.paddock -- the Paddock tab reads from here. Everything it returns is DERIVED (clock
// phase, series display, occupant, expiry); the only thing persisted is the sealed key and its state.
static void test_capi_paddock() {
    using namespace career;
    static SaveData s_save;
    static CareerCalendar s_cal;
    s_save = SaveData{};
    s_cal = CareerCalendar{};
    CHECK(LoadSeries(TESTDATA("series.psv")));

    s_cal.year = kStartYear;
    s_cal.cursor_doy = kCareerStartDoy;
    s_save.window_year = kStartYear;
    { WindowSeat w; w.series_id = "beacon_cup"; w.team_label = "Tipco";
      w.state = WSEAT_FREE;     w.applied = 0; s_save.window_seats.push_back(w); }
    { WindowSeat w; w.series_id = "onyx_masters";   w.team_label = "Pog Racing";
      w.state = WSEAT_REJECTED; w.applied = 1; w.winner_name = "Bruno Salgado";
      s_save.window_seats.push_back(w); }

    capi::SetCareerStateProvider([]() {
        capi::CareerStateView v; v.loaded = true; v.save = &s_save; v.calendar = &s_cal;
        v.playerName = "Alex"; return v; });

    // provider for the seat's car (in production the overlay registers it with ResolveTeamSeat).
    // Deliberately not deterministic: only Tipco resolves -- the other seat must come out WITHOUT the fields, not with gaps.
    capi::SetPaddockSeatCarProvider([](const std::string& sid, const std::string& team,
                                       std::string& cn, std::string& cs, int& nn) -> bool {
        if (team != "Tipco") return false;
        cn = "Northcliff 1.6"; cs = "northcliff"; nn = 3; return true;
    });

    capi::HandlerResult r = capi::QueryPaddock(nullptr);
    CHECK(r.ok);
    // January 1st of year 1 is WINDOW (compressed cycle), and you sign for THIS year
    CHECK(r.payload.find("\"phase\":\"window\"") != std::string::npos);
    // Tipco's seat carries its car; Pog Racing's (provider says no) doesn't carry the fields
    CHECK(r.payload.find("\"carName\":\"Northcliff 1.6\"") != std::string::npos);
    CHECK(r.payload.find("\"carSlug\":\"northcliff\"") != std::string::npos);
    CHECK(r.payload.find("\"liveryNN\":3") != std::string::npos);
    { size_t n = 0; for (size_t p = r.payload.find("\"carName\""); p != std::string::npos; p = r.payload.find("\"carName\"", p + 1)) n++;
      CHECK_EQ((long)n, 1L); }
    CHECK(r.payload.find("\"targetYear\":2025") != std::string::npos);
    CHECK(r.payload.find("\"windowYear\":2025") != std::string::npos);
    // states come out with the SAME token the design uses (PD_SEAT_STATUS), not the engine's raw integer
    CHECK(r.payload.find("\"status\":\"free\"") != std::string::npos);
    CHECK(r.payload.find("\"status\":\"rejected\"") != std::string::npos);
    CHECK(r.payload.find("\"winnerName\":\"Bruno Salgado\"") != std::string::npos);
    CHECK(r.payload.find("\"applied\":true") != std::string::npos);
    // the series display is derived (it doesn't travel inside the sealed key)
    { const SeriesDef* sd = SeriesById("beacon_cup");
      if (sd) CHECK(r.payload.find("\"seriesDisplay\":\"" + sd->display + "\"") != std::string::npos); }

    // VERIFIED SABOTAGE: in the middle of June the phase is NOT window. If the handler returned a fixed phase, or
    // misread the clock, this would still say "window" and the screen would headline a silly season that doesn't exist.
    s_cal.cursor_doy = career::dateutil::DoyFromYmd(kStartYear, 6, 15);
    r = capi::QueryPaddock(nullptr);
    CHECK(r.ok);
    CHECK(r.payload.find("\"phase\":\"season\"") != std::string::npos);
    CHECK(r.payload.find("\"phase\":\"window\"") == std::string::npos);

    // with no career loaded -> not_ready, not an empty paddock that looks like "no seats available"
    capi::SetCareerStateProvider(nullptr);
    r = capi::QueryPaddock(nullptr);
    CHECK(!r.ok);
    CHECK(r.code == "not_ready");
    capi::SetPaddockSeatCarProvider(nullptr);   // leaves the record clean for the rest of the suite
}

// cmd.paddock.apply -- applying from the app. The executor is the same path the
// overlay will use (ApplyToWindowSeat + persist), so what's tested here is the whole trip, not just the seam.
static void test_capi_paddock_apply() {
    using namespace career;
    static SaveData s_save;
    s_save = SaveData{};
    s_save.window_year = 2027;
    { WindowSeat w; w.series_id = "beacon_cup"; w.team_label = "Tipco"; w.state = WSEAT_FREE;
      s_save.window_seats.push_back(w); }

    capi::SetPaddockCmds([](const std::string& sid, const std::string& team) -> bool {
        return ApplyToWindowSeat(s_save, sid, team); }, nullptr);

    auto p = jsonm::Parse("{\"seriesId\":\"beacon_cup\",\"team\":\"Tipco\"}");
    capi::HandlerResult r = capi::CmdPaddockApply(p.get());
    CHECK(r.ok);
    CHECK(r.payload.find("\"applied\":true") != std::string::npos);
    CHECK_EQ(s_save.window_seats[0].state, (int)WSEAT_DISPUTED);
    CHECK_EQ(s_save.window_seats[0].applied, 1);

    // repeating it does NOT count as a second application (you're already in)
    r = capi::CmdPaddockApply(p.get());
    CHECK(r.payload.find("\"applied\":false") != std::string::npos);

    // VERIFIED SABOTAGE: a seat that doesn't exist in the window can't be applied to. Without this, the app
    // could "sign you up" for any team it dreamed up and the engine would swallow it.
    { auto q = jsonm::Parse("{\"seriesId\":\"beacon_cup\",\"team\":\"Equipo Que No Existe\"}");
      r = capi::CmdPaddockApply(q.get());
      CHECK(r.payload.find("\"applied\":false") != std::string::npos); }

    // incomplete params -> bad_params (not a silent "not applied")
    { auto z = jsonm::Parse("{\"seriesId\":\"beacon_cup\"}");
      r = capi::CmdPaddockApply(z.get());
      CHECK(!r.ok);
      CHECK(r.code == "bad_params"); }

    capi::SetPaddockCmds(nullptr, nullptr);
}

// APPLYING. You can go for any seat in play even if nobody sounded you out; what
// you don't get is preferential treatment. And NO requirement is checked when you apply, which is exactly what
// turns a wall into a season-long goal: you fight for a seat whose reputation you don't have yet, and if by
// December you haven't gotten there, that seat drops you.


// DECISION WEEK. Everything resolves at once, and a rejected seat comes back
// with the NAME of whoever took it -- without that, December's screen can't tell you why, which is
// half of what it's meant to show. And this is WHERE the seat's requirement gets checked, not when applying.


// 19/09 (Josh's decision, "real drivers from the pool"). With the "one driver, one seat" fix the cohort
// RUNS OUT: measured in the simulator, 17 of 41 lost slots were left with nobody and, in the decision week, the
// table handed you the slot by default. Now, without a cohort, the team signs a REAL person from the pool through
// the same chain that fills the winter gaps. With PRODUCTION data (the pool, the reserve and the curated
// origin only exist there), at the highest level, which is where the free cohort is shortest:
//   (1) slots offered and not signed, more than the free cohort -> ALL with someone, distinct, seated, and the
//       pool people had no live seat and are not retired; their contract starts in the destination year and, if they never
//       raced, their ELO is re-anchored to the level's band (D4);
//   (2) the decision week with a weak player -> all lost WITH a name, distinct, the pool ones with no seat;
//   (3) the rare case of there being NOBODY (pool off): the slot closes with no name and without touching the seat, and
//       in the decision week there is no rival to name.


// The market had no calendar. Seats used to open PER SERIES, MK_PRESEASON_LEAD
// days before each one's opener, and with multi-contract careers across different calendars that's unreadable: every series
// with its own tiny window. The design wants it by DATE and global -- season runs until August 31st, signing
// window from September 1st to December 14th, decision week on the 15th. It's defined by MONTH AND DAY, not by
// a fixed doy on purpose: the clock is a real Gregorian one (career_dateutil.h), and in a leap year that same September
// 1st falls a day later, so a hardcoded doy 244 would drift out of alignment every four years.
static void test_market_window_calendar() {
    using namespace career;
    using namespace career::dateutil;

    // dates come from the real calendar, not from a fixed day-of-year constant
    CHECK_EQ(market::MarketWindowOpenDoy(2025), DoyFromYmd(2025, bal::MK_WINDOW_OPEN_MONTH, bal::MK_WINDOW_OPEN_DAY));
    CHECK_EQ(market::MarketDecisionDoy(2025),   DoyFromYmd(2025, bal::MK_DECISION_MONTH,    bal::MK_DECISION_DAY));
    // leap year: 2028 has a February 29th, so September 1st falls on a HIGHER doy. If this were a
    // fixed constant, the window would open on August 31st once every four years.
    CHECK(IsLeapYear(2028) && !IsLeapYear(2025));
    CHECK_EQ(market::MarketWindowOpenDoy(2028), market::MarketWindowOpenDoy(2025) + 1);

    // the THREE phases of the year, and their exact boundaries
    CHECK_EQ(market::MarketPhaseFor(2025, 1), (int)market::MARKET_PADDOCK);
    CHECK_EQ(market::MarketPhaseFor(2025, DoyFromYmd(2025, 8, 31)), (int)market::MARKET_PADDOCK);
    CHECK_EQ(market::MarketPhaseFor(2025, DoyFromYmd(2025, 9,  1)), (int)market::MARKET_WINDOW);   // the day it opens is ALREADY the window
    CHECK_EQ(market::MarketPhaseFor(2025, DoyFromYmd(2025, 12, 14)), (int)market::MARKET_WINDOW);
    CHECK_EQ(market::MarketPhaseFor(2025, DoyFromYmd(2025, 12, 15)), (int)market::MARKET_DECISION);
    CHECK_EQ(market::MarketPhaseFor(2025, DaysInYear(2025)), (int)market::MARKET_DECISION);        // Dec 31st is still closed
    // the boundary also shifts in a leap year: August 31st, 2028 is still paddock, and September 1st is window
    CHECK_EQ(market::MarketPhaseFor(2028, DoyFromYmd(2028, 8, 31)), (int)market::MARKET_PADDOCK);
    CHECK_EQ(market::MarketPhaseFor(2028, DoyFromYmd(2028, 9,  1)), (int)market::MARKET_WINDOW);

    // an out-of-range doy doesn't crash or invent a phase: it's clamped to the year's edges
    CHECK_EQ(market::MarketPhaseFor(2025, 0),    (int)market::MARKET_PADDOCK);
    CHECK_EQ(market::MarketPhaseFor(2025, 9999), (int)market::MARKET_DECISION);

    // YEAR 1 RUNS AN EARLIER, COMPRESSED CYCLE. A new career is born in preseason, and no
    // AI contract expires in its first year (they run 1 to 3 years FROM the start), so under the
    // normal calendar the player would wait until September for their first silly season. Year 1 has its own in
    // February: exhibitions in January, you decide in February, and you enter your first season with contested seats.
    const int y1 = 2025;
    CHECK_EQ(market::MarketPhaseFor(y1, 1, y1), (int)market::MARKET_WINDOW);                       // day one: already open
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 2, 14), y1), (int)market::MARKET_WINDOW);
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 2, 15), y1), (int)market::MARKET_DECISION); // its week
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 2, 15) + bal::MK_DECISION_WEEK_DAYS - 1, y1), (int)market::MARKET_DECISION);
    // and that week CLOSES: otherwise year 1 would never return to the paddock and the season would never start
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 2, 15) + bal::MK_DECISION_WEEK_DAYS, y1), (int)market::MARKET_PADDOCK);
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 6, 1), y1), (int)market::MARKET_PADDOCK);   // normal season

    // MARCH 9 -- the specific case that exposed it. Seen in-game on 06/08: contracts could be signed.
    // The phase was CORRECT (paddock); what failed was that the offers board wasn't checking it. This anchors
    // the exact day so that if anyone ever moves the dates, it's obvious this exact symptom breaks.
    CHECK_EQ(market::MarketPhaseFor(y1,     DoyFromYmd(y1,     3, 9), y1), (int)market::MARKET_PADDOCK);
    CHECK_EQ(market::MarketPhaseFor(y1 + 1, DoyFromYmd(y1 + 1, 3, 9), y1), (int)market::MARKET_PADDOCK);
    // ...and inside the window it SHOULD, which is the other half: a lock that's always shut isn't a schedule
    CHECK_EQ(market::MarketPhaseFor(y1 + 1, DoyFromYmd(y1 + 1, 10, 1), y1), (int)market::MARKET_WINDOW);

    // AND THE COUNTDOWNS HAVE TO WATCH THAT SAME CYCLE. They didn't: they had no `firstYear` parameter
    // while MarketPhaseFor did, so in a freshly started career the screen used to say "348 days left"
    // for decision week -- counting to December 15th -- when the one actually arriving was February's,
    // 45 days out. Seen in-game on 06/08. And it's not a decorative number: it's what the player uses to decide whether there's
    // enough time to prove something before the seats get handed out.
    const int y1feb = DoyFromYmd(y1, 2, 15);
    CHECK_EQ(market::DaysToDecisionWeek(y1, 1, y1), (long)(y1feb - 1));        // January 1st -> to FEBRUARY's
    CHECK(market::DaysToDecisionWeek(y1, 1, y1) < 60);                          // ...which is ~45 days, not 348
    CHECK_EQ(market::DaysToDecisionWeek(y1, y1feb, y1), 0L);                    // the day itself
    // once February's has passed, year 1 falls back to the normal calendar and the countdown points to December, as usual
    CHECK_EQ(market::DaysToDecisionWeek(y1, DoyFromYmd(y1, 6, 1), y1),
             (long)market::DaysToDecisionWeek(y1, DoyFromYmd(y1, 6, 1)));
    // with no firstYear, the usual behavior stays INTACT (old callers don't change)
    CHECK_EQ(market::DaysToDecisionWeek(y1, 1), (long)(DoyFromYmd(y1, 12, 15) - 1));
    // and in a year that ISN'T the first, February doesn't matter at all
    CHECK_EQ(market::DaysToDecisionWeek(y1 + 1, 1, y1), (long)(DoyFromYmd(y1 + 1, 12, 15) - 1));

    // year 1's window is OPEN from day one: counting to September would be sending the player to
    // wait for a door that's already right in front of them.
    CHECK_EQ(market::DaysToMarketWindow(y1, 1, y1), 0L);
    CHECK_EQ(market::DaysToMarketWindow(y1, y1feb - 1, y1), 0L);
    CHECK(market::DaysToMarketWindow(y1, 1) > 200);                             // with no firstYear, the usual
    CHECK(market::DaysToMarketWindow(y1, DoyFromYmd(y1, 6, 1), y1) > 0);        // once February has passed, to September
    // once February passes, year 1 FALLS BACK to the usual calendar: year 2's window opens in September
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 9,  1), y1), (int)market::MARKET_WINDOW);
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 12, 15), y1), (int)market::MARKET_DECISION);
    // the special case is ONLY for year 1: the same day in year 2 is season, not window
    CHECK_EQ(market::MarketPhaseFor(y1 + 1, DoyFromYmd(y1 + 1, 1, 10), y1), (int)market::MARKET_PADDOCK);
    CHECK_EQ(market::MarketPhaseFor(y1 + 1, DoyFromYmd(y1 + 1, 2, 15), y1), (int)market::MARKET_PADDOCK);
    // with no firstYear (old callers) there's NO special case: the usual behavior, byte for byte
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 1, 10)), (int)market::MARKET_PADDOCK);
    CHECK_EQ(market::MarketPhaseFor(y1, DoyFromYmd(y1, 2, 15)), (int)market::MARKET_PADDOCK);

    // countdown for the calendar warning: "you're about to skip offers week" needs to know how much time is left.
    // Inside the window it counts to decision week; during the season, to the opening.
    CHECK_EQ(market::DaysToMarketWindow(2025, DoyFromYmd(2025, 8, 31)), 1);
    CHECK_EQ(market::DaysToMarketWindow(2025, DoyFromYmd(2025, 9,  1)), 0);   // you're already inside it
    CHECK_EQ(market::DaysToDecisionWeek(2025, DoyFromYmd(2025, 12, 14)), 1);
    CHECK_EQ(market::DaysToDecisionWeek(2025, DoyFromYmd(2025, 12, 15)), 0);
    // once decision week has passed, the NEXT window is next year's: never a negative number
    CHECK(market::DaysToMarketWindow(2025, DoyFromYmd(2025, 12, 20)) > 0);
    CHECK(market::DaysToDecisionWeek(2025, DoyFromYmd(2025, 12, 20)) > 0);
}

// The rivalry loop was open on one side. Beef was born on track and only decayed
// (BeefDecayAtRollover); the return path was missing: losing a seat to someone RAISES beef with them. With this the
// cycle closes -- friction on track -> they contest your seat (trio ranked by beef) -> they take it -> more friction -> you
// face them again next season. The rule lives in the ENGINE, not in the bridge that closes
// the observation period (career_overlay.cpp, outside this harness), the same criterion SeatWatchActionNow already follows.
static void test_beef_rises_when_seat_lost() {
    using namespace career;
    SeatWatch w; w.series_id = "gt3_eu"; w.team_label = "Alpha Corse";
    w.rival_id = "rk_nemesis"; w.rival_name = "Nemesis";

    // LOSING it raises beef with whoever took it, and stamps a date so the yearly decay knows how to count it
    SaveData perdida; perdida.current_world_year = 2027;
    BeefOnSeatLost(perdida, w, false);
    CHECK_EQ(perdida.beef["rk_nemesis"].level, bal::MK_BEEF_SEAT_LOST);
    CHECK_EQ(perdida.beef["rk_nemesis"].last_year, 2027);
    // and in one shot it reaches the inbox's "beef" threshold: losing a seat isn't a scrape, it's a grievance
    CHECK(perdida.beef["rk_nemesis"].level >= bal::MK_BEEF_LEVEL_BEEF);

    // WINNING it doesn't touch this: resentment comes from losing, not from competing
    SaveData ganada; ganada.current_world_year = 2027;
    BeefOnSeatLost(ganada, w, true);
    CHECK(ganada.beef.find("rk_nemesis") == ganada.beef.end());

    // IT ACCUMULATES: two seats lost to the same person weigh more than one
    SaveData dos; dos.current_world_year = 2027;
    BeefOnSeatLost(dos, w, false);
    BeefOnSeatLost(dos, w, false);
    CHECK_EQ(dos.beef["rk_nemesis"].level, bal::MK_BEEF_SEAT_LOST * 2);

    // ...but CAPPED at 5, the same cap as the on-track duel and the spicy press response
    SaveData tope; tope.current_world_year = 2027;
    for (int i = 0; i < 10; i++) BeefOnSeatLost(tope, w, false);
    CHECK_EQ(tope.beef["rk_nemesis"].level, 5);

    // with no rival recorded (you competed alone) there's nobody to be angry at, and NO empty entry gets created
    SeatWatch sinRival; sinRival.series_id = "gt3_eu"; sinRival.team_label = "Alpha Corse";
    SaveData nadie; nadie.current_world_year = 2027;
    BeefOnSeatLost(nadie, sinRival, false);
    CHECK(nadie.beef.empty());

    // the loop genuinely closes: after losing the seat, that rival heads the trio next time even though
    // they're still the worst of the three by score. Without this check, the two halves of the feature could
    // each be correct on their own and still fail to connect.
    std::vector<SeatCandidate> rank;
    { SeatCandidate c; c.id="rk_a";       c.name="A";       c.fit=0.90; rank.push_back(c); }
    { SeatCandidate p; p.id="player";     p.name="Yo";      p.fit=0.85; p.is_player=true; rank.push_back(p); }
    { SeatCandidate c; c.id="rk_b";       c.name="B";       c.fit=0.70; rank.push_back(c); }
    { SeatCandidate c; c.id="rk_nemesis"; c.name="Nemesis"; c.fit=0.60; rank.push_back(c); }
    CHECK(ShortlistFromRank(rank, &perdida)[0].id == "rk_nemesis");
}

// The trio used to come purely from score, so it was ALWAYS the same people. Measured on 04/08
// on a real save: the same three drivers across fourteen contests (distinct ids=3). And the player DID have
// a rivalry with someone eligible (beef with rk_amara, tier 1-7), simply buried by score. Now the
// trio's first slot is reserved for whoever has history with you. They go FIRST, not just somewhere inside, because
// SeatWatchOpen takes contenders[0] as the observation's rival: they're who you're measured against.
static void test_shortlist_prefers_rival_with_history() {
    using namespace career;
    std::vector<SeatCandidate> rank;
    { SeatCandidate c; c.id="rk_a"; c.name="A"; c.fit=0.90; rank.push_back(c); }
    { SeatCandidate p; p.id="player"; p.name="Yo"; p.fit=0.85; p.is_player=true; rank.push_back(p); }
    { SeatCandidate c; c.id="rk_b"; c.name="B"; c.fit=0.70; rank.push_back(c); }
    { SeatCandidate c; c.id="rk_nemesis"; c.name="Nemesis"; c.fit=0.60; rank.push_back(c); }
    { SeatCandidate c; c.id="rk_d"; c.name="D"; c.fit=0.50; rank.push_back(c); }

    // with no save -> EXACTLY today's trio (backward compatible: the old caller doesn't change)
    std::vector<SeatContender> sinSave = ShortlistFromRank(rank);
    CHECK(sinSave[0].id == "rk_a" && sinSave[1].id == "rk_b" && sinSave[2].id == "rk_nemesis");

    // a save with NO rivalry at all -> also today's trio: the function doesn't invent a new order for no reason
    SaveData limpio;
    std::vector<SeatContender> sinBeef = ShortlistFromRank(rank, &limpio);
    for (size_t i = 0; i < sinSave.size(); i++) CHECK(sinBeef[i].id == sinSave[i].id);

    // with beef present, the third-by-score moves to FIRST, and the other two still come out by score
    SaveData conBeef;
    conBeef.beef["rk_nemesis"].level = 1;
    std::vector<SeatContender> sl = ShortlistFromRank(rank, &conBeef);
    CHECK_EQ((int)sl.size(), bal::MK_SEAT_WATCH_SHORTLIST);
    CHECK(sl[0].id == "rk_nemesis");
    CHECK(sl[0].name == "Nemesis");                  // with a name, which is what gets shown
    CHECK(sl[1].id == "rk_a" && sl[2].id == "rk_b"); // the rest by score, without duplicating the one above
    for (const auto& c : sl) CHECK(c.id != "player");

    // whoever ISN'T in the table doesn't sneak in: the trio gets REORDERED, not injected. If it were injected, the
    // contest would stop being the merit-based model that was just calibrated.
    SaveData fuera;
    fuera.beef["rk_fantasma"].level = 5;             // maximum rivalry with someone who isn't a candidate
    std::vector<SeatContender> sl2 = ShortlistFromRank(rank, &fuera);
    for (const auto& c : sl2) CHECK(c.id != "rk_fantasma");
    CHECK(sl2[0].id == "rk_a");                      // and the trio stays as it was

    // h2h also counts, but ONE race against each other isn't "a long-running fight"
    SaveData pocoH2H; pocoH2H.h2h["rk_nemesis"].w = 1;
    CHECK(ShortlistFromRank(rank, &pocoH2H)[0].id == "rk_a");
    SaveData muchoH2H;
    muchoH2H.h2h["rk_nemesis"].w = bal::MK_RIVAL_TERNA_MIN_H2H - 1;
    muchoH2H.h2h["rk_nemesis"].l = 1;                // right at the minimum, counting wins AND losses
    CHECK(ShortlistFromRank(rank, &muchoH2H)[0].id == "rk_nemesis");

    // between TWO rivals with history, the higher beef wins, not the score: if score decided,
    // the tiebreak would be the usual one, and the driver you're genuinely at war with would never come out on top.
    SaveData dos;
    dos.beef["rk_a"].level = 1;
    dos.beef["rk_nemesis"].level = 3;
    CHECK(ShortlistFromRank(rank, &dos)[0].id == "rk_nemesis");

    // the player NEVER enters their own trio, even if corrupted data somehow gave them beef with themselves
    SaveData raro; raro.beef["player"].level = 5;
    for (const auto& c : ShortlistFromRank(rank, &raro)) CHECK(c.id != "player");
}

// A player's feedback: "if you're being watched and your rival starts beating you, they give the seat to the other guy".
// The rule for the observation period: you're only kept under watch while you REMAIN a candidate. It lives in SeatWatchActionNow, not
// in the bridge, specifically so it can be locked down here (the screen/overlay aren't part of this harness).
static void test_seat_watch_action_now() {
    using namespace career;
    SaveData save;
    save.class_stats["GT3"].races = 5;
    const int day0 = 739000;
    std::vector<SeatContender> lista;
    { SeatContender c; c.id = "rd_ana"; c.name = "Ana Ferrer"; lista.push_back(c); }
    CHECK(SeatWatchOpen(save, "gt3_eu", "GT3", "Alpha Corse", lista, day0));
    const SeatWatch& w = save.seat_watches[0];

    // you're still within the band and there's time left -> you're still being watched
    CHECK_EQ(SeatWatchActionNow(save, w, SEAT_CONTEST_WATCH, day0 + 5), (int)SEATWATCH_KEEP);
    // ONE bad race does NOT cost you the seat: falling behind today isn't enough on its own, that's the margin
    CHECK_EQ(SeatWatchActionNow(save, w, SEAT_CONTEST_LOST, day0 + 5), (int)SEATWATCH_KEEP);
    // and the reverse: if you pull ahead early, you don't have to run out the full 3 races as a formality
    CHECK_EQ(SeatWatchActionNow(save, w, SEAT_CONTEST_WON, day0 + 5), (int)SEATWATCH_CLOSE_WON);

    // they beat you in all 3 races they were watching -> it's THEIRS, without waiting for the deadline to run out
    {
        SaveData s2; s2.class_stats["GT3"].races = 5;
        CHECK(SeatWatchOpen(s2, "gt3_eu", "GT3", "Alpha Corse", lista, day0));
        SeatWatch& w2 = s2.seat_watches[0];
        for (int i = 1; i <= bal::MK_SEAT_WATCH_RACES; i++) {
            s2.class_stats["GT3"].races = 5 + i;
            CHECK(SeatWatchNoteRaces(s2, w2, /*rivalAhead*/ true));
            CHECK_EQ(w2.rival_ahead_streak, i);
            const int esperado = (i >= bal::MK_SEAT_WATCH_RACES) ? (int)SEATWATCH_CLOSE_LOST : (int)SEATWATCH_KEEP;
            CHECK_EQ(SeatWatchActionNow(s2, w2, SEAT_CONTEST_WATCH, day0 + i), esperado);
        }
    }
    // ...but if you beat them just ONCE in between, the count resets to zero: two in a row no longer count for them
    {
        SaveData s3; s3.class_stats["GT3"].races = 5;
        CHECK(SeatWatchOpen(s3, "gt3_eu", "GT3", "Alpha Corse", lista, day0));
        SeatWatch& w3 = s3.seat_watches[0];
        s3.class_stats["GT3"].races = 6; CHECK(SeatWatchNoteRaces(s3, w3, true));
        s3.class_stats["GT3"].races = 7; CHECK(SeatWatchNoteRaces(s3, w3, true));
        CHECK_EQ(w3.rival_ahead_streak, 2);
        s3.class_stats["GT3"].races = 8; CHECK(SeatWatchNoteRaces(s3, w3, false));   // you beat them this time
        CHECK_EQ(w3.rival_ahead_streak, 0);
        CHECK_EQ(w3.races_seen, 3);
        // with no new races nothing gets recorded (opening the market 10 times doesn't move the streak)
        CHECK(!SeatWatchNoteRaces(s3, w3, true));
        CHECK_EQ(w3.rival_ahead_streak, 0);
        // several races at once (you didn't open the market in between) all get recorded
        s3.class_stats["GT3"].races = 11; CHECK(SeatWatchNoteRaces(s3, w3, true));
        CHECK_EQ(w3.rival_ahead_streak, 3);
        CHECK_EQ(SeatWatchActionNow(s3, w3, SEAT_CONTEST_WATCH, day0 + 5), (int)SEATWATCH_CLOSE_LOST);
    }

    // once the deadline runs out WITHOUT you pulling ahead -> it closes against you
    save.class_stats["GT3"].races = 5 + bal::MK_SEAT_WATCH_RACES;
    CHECK_EQ(SeatWatchActionNow(save, w, SEAT_CONTEST_WATCH, day0 + 5), (int)SEATWATCH_CLOSE_LOST);
    // ...but if you're ahead right at that moment, you win it (the deadline doesn't cost it)
    CHECK_EQ(SeatWatchActionNow(save, w, SEAT_CONTEST_WON, day0 + 5), (int)SEATWATCH_CLOSE_WON);

    // one that's already closed doesn't get re-decided (a board refresh can't reopen or reverse anything)
    SeatWatch cerrada = w; cerrada.state = 2; cerrada.resolved_day = day0 + 9;
    CHECK_EQ(SeatWatchActionNow(save, cerrada, SEAT_CONTEST_WON, day0 + 20), (int)SEATWATCH_KEEP);
    CHECK(!SeatWatchNoteRaces(save, cerrada, true));
}

// A player's feedback: "I get the part where they're watching me, but there's no input on whether I got offered or
// rejected". The observation used to close IN SILENCE: the panel just vanished. A process that doesn't tell you how
// it ended isn't a process. Now the team answers you by email, whoever wins.
static void test_seat_watch_mail() {
    using namespace career;
    SeatWatch w;
    w.series_id = "gt3_eu"; w.class_name = "GT3"; w.team_label = "Alpha Corse";
    w.rival_id = "rd_ana"; w.rival_name = "Ana Ferrer";

    SaveData ganada;
    EmitSeatWatchMail(ganada, w, "GT3 Europe", true, 2026, 120, "Alex Vega");
    CHECK_EQ((int)ganada.emails.size(), 1);
    const GeneratedEmail& g = ganada.emails[0];
    CHECK(g.payload_key == "seatwatch_won");
    CHECK_EQ(g.family, 1); CHECK_EQ(g.subtype, 13);
    CHECK(g.from_name == "Alpha Corse");
    CHECK_EQ(g.year, 2026); CHECK_EQ(g.day, 120);
    { MailParams p = MailParamsDecode(g.params);
      std::map<std::string,std::string> m; for (const auto& kv : p) m[kv.first] = kv.second;
      CHECK(m["team"] == "Alpha Corse");
      CHECK(m["series"] == "GT3 Europe");          // the display name, not the id: that's what gets read in the email
      CHECK(m["rival"] == "Ana Ferrer");
      CHECK(m["player"] == "Alex");                // first name only, like the rest of the channel
    }
    // dedup: refreshing the board can't flood your inbox with the same notice
    EmitSeatWatchMail(ganada, w, "GT3 Europe", true, 2026, 121, "Alex Vega");
    CHECK_EQ((int)ganada.emails.size(), 1);

    // losing it ALSO notifies you (this was the silence being reported), with a different template and subject
    SaveData perdida;
    EmitSeatWatchMail(perdida, w, "GT3 Europe", false, 2026, 120, "Alex Vega");
    CHECK_EQ((int)perdida.emails.size(), 1);
    CHECK(perdida.emails[0].payload_key == "seatwatch_lost");
    CHECK_EQ(perdida.emails[0].subtype, 14);
    CHECK(perdida.emails[0].id != ganada.emails[0].id);   // different ids: winning and losing don't collide

    // with a sealed rival, a variant that NAMES them gets picked; v0 is the only one that doesn't mention them, so with no
    // rival it's forced. (The rule is tested standalone: MailVariantCount needs the templates, and the harness doesn't
    // load them, so inside EmitSeatWatchMail the count comes out 0 and this couldn't be distinguished otherwise.)
    for (int vc = 2; vc <= 4; vc++) {
        CHECK_EQ(SeatWatchMailVariant(vc, false, "sw_x"), 0);            // no rival -> always v0
        const int v = SeatWatchMailVariant(vc, true, "sw_x");
        CHECK(v >= 1 && v < vc);                                          // with a rival -> never v0, and within range
    }
    CHECK_EQ(SeatWatchMailVariant(1, true, "sw_x"), 0);                   // a single template: nothing to choose from
    CHECK_EQ(SeatWatchMailVariant(0, true, "sw_x"), 0);                   // with no templates loaded: v0, no division by zero
    CHECK_EQ(SeatWatchMailVariant(3, true, "sw_a"), SeatWatchMailVariant(3, true, "sw_a"));   // deterministic

    // with no sealed rival, v0 is used, which doesn't mention one: no adversary gets invented just to fill the gap
    SeatWatch solo = w; solo.rival_id.clear(); solo.rival_name.clear();
    SaveData sinRival;
    EmitSeatWatchMail(sinRival, solo, "GT3 Europe", false, 2026, 120, "Alex Vega");
    CHECK_EQ((int)sinRival.emails.size(), 1);
    CHECK_EQ(sinRival.emails[0].variant, 0);
    { MailParams p = MailParamsDecode(sinRival.emails[0].params);
      for (const auto& kv : p) CHECK(kv.first != "rival"); }

    // an observation period with no resolvable seat emits nothing (a corrupted line -> no email gets invented)
    SaveData vacia; SeatWatch rota;
    EmitSeatWatchMail(vacia, rota, "", false, 2026, 120, "Alex Vega");
    CHECK_EQ((int)vacia.emails.size(), 0);
}

// the observation period survives save/load. Without this there would be no period worth having: every
// game launch would either reset your window or wipe it out.
static void test_seat_watch_roundtrip() {
    using namespace career;
    SaveData d;
    SeatWatch w;
    w.series_id = "gt3_eu"; w.class_name = "GT3"; w.team_label = "Alpha Corse";
    w.rival_id = "rd_ana"; w.rival_name = "Ana Ferrer";
    w.opened_day = 739000; w.races_at_open = 5; w.races_window = 3; w.state = 0; w.resolved_day = 0;
    w.races_seen = 2; w.rival_ahead_streak = 2;   // the streak HAS to survive: it's what decides the seat
    { SeatContender c; c.id = "rd_ana";  c.name = "Ana Ferrer";  w.contenders.push_back(c); }
    { SeatContender c; c.id = "rd_caio"; c.name = "Caio Duarte"; w.contenders.push_back(c); }
    d.seat_watches.push_back(w);
    SeatWatch c;
    c.series_id = "harbor_championship_5234"; c.class_name = "GT4"; c.team_label = "Beta Racing";
    c.opened_day = 738900; c.races_at_open = 1; c.races_window = 3; c.state = 2; c.resolved_day = 738950;
    d.seat_watches.push_back(c);

    const char* path = "test_seatwatch_roundtrip.sav";
    CHECK(SaveCareer(d, path));
    SaveData e;
    CHECK(LoadCareer(e, path));
    CHECK_EQ((int)e.seat_watches.size(), 2);
    const SeatWatch& a = e.seat_watches[0];
    CHECK(a.series_id == "gt3_eu" && a.class_name == "GT3" && a.team_label == "Alpha Corse");
    CHECK(a.rival_id == "rd_ana" && a.rival_name == "Ana Ferrer");
    CHECK_EQ(a.opened_day, 739000); CHECK_EQ(a.races_at_open, 5); CHECK_EQ(a.races_window, 3);
    CHECK_EQ(a.state, 0); CHECK_EQ(a.resolved_day, 0);
    CHECK_EQ(a.races_seen, 2); CHECK_EQ(a.rival_ahead_streak, 2);
    // the sealed LIST survives, and IN ORDER: otherwise, reloading the career would let phase 2 be decided again
    // among whoever happened to exist at that moment, which is exactly what sealing the list is meant to prevent.
    CHECK_EQ((int)a.contenders.size(), 2);
    CHECK(a.contenders[0].id == "rd_ana" && a.contenders[0].name == "Ana Ferrer");
    CHECK(a.contenders[1].id == "rd_caio" && a.contenders[1].name == "Caio Duarte");
    // the CLOSED one comes back too, which is what sustains the cooldown across sessions
    const SeatWatch& b = e.seat_watches[1];
    CHECK(b.team_label == "Beta Racing"); CHECK_EQ(b.state, 2); CHECK_EQ(b.resolved_day, 738950);
    CHECK(b.rival_name.empty());                    // no rival: an empty field, not garbage
    CHECK_EQ((int)b.contenders.size(), 0);          // had no list: comes back empty, not with the one from the seat next door
    CHECK(SeatWatchOnCooldown(e, "harbor_championship_5234", "Beta Racing", 738951));
    // and a save with NO contests loads cleanly (back-compat: the line is additive)
    SaveData vacio; const char* p2 = "test_seatwatch_none.sav";
    CHECK(SaveCareer(vacio, p2));
    SaveData e2; CHECK(LoadCareer(e2, p2));
    CHECK_EQ((int)e2.seat_watches.size(), 0);
    remove(path); remove(p2);
}

// (the cohort competes too): the rollover's AI->AI refill used to be "take the first open seat in
// your tier", walking the map of promoted drivers in KEY order. Meaning whoever had the alphabetically lowest id
// got the best team, and nothing in the world decided the outcome. Now every team scores the candidates
// with the same model it uses to evaluate the player. What must NOT change is how many seats get filled.


// Promotion-destination resolver -- Kingsmere (parent) signs in Falcon Cup, so
// from a level-3 academy the destination is the lowest-level Falcon Cup series above 3.


// AppendAcademyPromotions issues the promotion offer when the player (an active
// contract in the Kingsmere Kor964 rothbury_dax147, parent Kingsmere) beats their cohort.


// AppendAcademyPromotions shares its offer id ("of_"+destId) with the rest of the
// market -- a withdrawn/expired series must NOT reappear as a Promotion. Same fixture as
// test_academy_promotion_offer (the promotion SIGNS with no suppression), differential: seeding withdrawn_offers/
// lapsed_offers with "of_beacon_championship_2774" turns off the promotion; removing it shows it again.


// the academy promotion does NOT skip the super-license. Same fixture as test_academy_promotion_offer,
// differential: a temporary PSV adds a synthetic qualifier whose destination (unlocks) is beacon_championship_2774 ->
// the promotion's destination becomes GATED. Without the gate, the offer arrives as COURTED ("requires
// superlicense"); with "beacon_championship_2774" in unlocked_gates it becomes actionable again (the same gateLock as the
// main loop, which this appendix used to bypass with an unconditional held=false).


// LoadTeamRelationships/TeamRelationsCount/TeamRelationsFor -- a team<->team graph
// (docs/team_relationships.psv). 'known' is derived from g_packTeamClass -> load it first.


// Byte-compat invariant that the next phase must preserve. With the relationship graph LOADED,
// a relationship with NO history (ex-team/courted/snubbed) still returns EXACTLY REL_BASE --
// TeamRelationship doesn't read the graph yet (that comes next); this documents the current no-op.


// AllyReach (decayed multi-hop ally reach) + RivalWeight (direct rivalry). PURE
// helpers over the team<->team relationship graph, not yet integrated into TeamRelationship.






// FIX (from a report: "a 50%-length race lands on a x3 consumption multiplier and the AI runs out of fuel").
// The INVARIANT locked down here is physical, not a matter of taste: AMS2 sizes the fuel tank, and the AI's
// fuel strategy, for ONE full race. So the total fuel the mod can ever end up
// requesting, `laps_run x multiplier`, must NEVER exceed the full race distance. If anyone ever touches
// the formula again and breaks this, the test goes red before anyone gets stranded on track.
static void test_wear_mult() {
    using namespace career;
    // The multiplier depends ONLY on the duration %, not on the race length (that was the bug: it used
    // to compare against a fixed 20-lap constant, so the same % gave x2 or x5 depending on the series).
    CHECK_EQ(WearMultForLaps(20, 20), 1);    // 100%
    CHECK_EQ(WearMultForLaps(15, 20), 1);    // 75% -> floor(1.33), NEVER x2
    CHECK_EQ(WearMultForLaps(10, 20), 2);    // 50%
    CHECK_EQ(WearMultForLaps(5,  20), 4);    // 25%
    // with scaling ON, distance-based scaling ALWAYS wins --
    // the player's global setting only matters with the toggle OFF (the mod touches nothing). A global set to OFF
    // used to leave tires green for the whole race, which read as "wear isn't working".
    // Tires (mapping: higher index = less wear; 6=Authentic, 7=x0.5, 8=OFF):
    CHECK_EQ(TireWearIdxForMult(1), 6);   // reference -> x1 Authentic, regardless of the global setting
    CHECK_EQ(TireWearIdxForMult(0), 6);   // degenerate m -> x1
    CHECK_EQ(TireWearIdxForMult(2), 5);   // 50% -> x2
    CHECK_EQ(TireWearIdxForMult(4), 3);   // 25% -> x4
    // hub (30/08): cap at x5 -- indices 1 and 0 (x6/x7) are NOT in the game's menu, and a 5% race
    // announced "x7" on the AMS2 screen (tester's screenshot). We only write a scale that exists.
    CHECK_EQ(TireWearIdxForMult(5), 2);   // capped at x5
    CHECK_EQ(TireWearIdxForMult(9), 2);   // above the cap -> x5, never x6/x7
    // Fuel (mapping BY SCREEN: 0=Authentic, 1="Slow", 6=x2, 5=x3, 4=x4, 3=x5; cap x5):
    CHECK_EQ(FuelUsageIdxForMult(1), 0);  // reference -> Authentic (index 1 shows as "Slow")
    CHECK_EQ(FuelUsageIdxForMult(2), 6);  // 50% -> x2
    CHECK_EQ(FuelUsageIdxForMult(5), 3);  // capped at x5
    CHECK_EQ(FuelUsageIdxForMult(7), 3);  // above the cap -> x5
    // The exact case reported: 14 laps at 50%. Before, round(20/7) = x3 -> 21 laps' worth of fuel in a
    // 14-lap tank. Now x2 -> exactly the 14 that fit.
    CHECK_EQ(WearMultForLaps(7, 14), 2);
    // And the one that didn't even need trimming: short series AT 100% that were already being scaled.
    CHECK_EQ(WearMultForLaps(12, 12), 1);
    CHECK_EQ(WearMultForLaps(6,  6),  1);
    CHECK_EQ(WearMultForLaps(8,  8),  1);
    // Degradation: with no known full distance, nothing gets scaled.
    CHECK_EQ(WearMultForLaps(7, 0), 1);
    CHECK_EQ(WearMultForLaps(0, 20), 1);
    // THE INVARIANT, swept exhaustively: for every race from 1 to 60 laps and every % in the catalog, what gets consumed
    // (laps run x multiplier) never exceeds the full race. Holds for both axes, with their respective caps.
    for (int full = 1; full <= 60; full++) {
        for (const int* p = kDurationPcts; *p; ++p) {
            int eff = full * *p / 100; if (eff < 1) eff = 1;
            CHECK(eff * WearMultFuel(eff, full) <= full);
            CHECK(eff * WearMultTyre(eff, full) <= full);
            CHECK(WearMultFuel(eff, full) <= 5);   // cap on AMS2's fuel-consumption setting
            CHECK(WearMultTyre(eff, full) <= 5);   // cap on the tire setting -- the SAME one that gets written
        }
    }
}

// FIX 01/08 (report: "I won the Oakfield Motors championship round and got 13 points instead of 25").
// 25 x 0.5 = 12.5 -> 13. The SPRINT format's half-points were being applied to EVERY sprint round, and there are 13 series
// in the catalog (Oakfield Motors Lum695, Kingsmere, trucks, karts) where EVERY round is a sprint: there, halving doesn't
// change any standings, it just makes a win worth 13. It only means something when a championship mixes formats.
static void test_round_points_scale() {
    using namespace career;
    auto mk = [](std::initializer_list<int> fmts) {
        std::vector<CalRound> v; int r = 1;
        for (int f : fmts) { CalRound c; c.round = r++; c.fmt = f; v.push_back(c); }
        return v;
    };
    // The reported case: an all-sprint championship -> FULL points on every round.
    std::vector<CalRound> oakfield_motors = mk({0,0,0,0,0,0,0});
    for (int i = 0; i < 7; i++) CHECK_EQ((long long)(RoundPointsScale(oakfield_motors, i) * 100), 100);
    // A championship that MIXES formats (drift_championship_2323, lantern_cup_8145): there the sprint really is worth less than the feature race.
    std::vector<CalRound> mixto = mk({0,1,0,1});
    CHECK_EQ((long long)(RoundPointsScale(mixto, 0) * 100), 50);    // sprint
    CHECK_EQ((long long)(RoundPointsScale(mixto, 1) * 100), 100);   // feature
    CHECK_EQ((long long)(RoundPointsScale(mixto, 2) * 100), 50);
    std::vector<CalRound> mixtoEnd = mk({0,2});                     // sprint + endurance
    CHECK_EQ((long long)(RoundPointsScale(mixtoEnd, 0) * 100), 50);
    // With no sprints, there's nothing to scale, and an out-of-range index never invents a weird factor.
    std::vector<CalRound> feature = mk({1,1,2});
    for (int i = 0; i < 3; i++) CHECK_EQ((long long)(RoundPointsScale(feature, i) * 100), 100);
    CHECK_EQ((long long)(RoundPointsScale(oakfield_motors, -1) * 100), 100);
    CHECK_EQ((long long)(RoundPointsScale(oakfield_motors, 99) * 100), 100);
    CHECK_EQ((long long)(RoundPointsScale(mk({}), 0) * 100), 100);
}

static void test_dateutil() {
    using namespace career::dateutil;
    // leap years
    CHECK(IsLeapYear(2028)); CHECK(!IsLeapYear(2025)); CHECK(!IsLeapYear(2100)); CHECK(IsLeapYear(2000));
    CHECK_EQ(DaysInYear(2028), 366); CHECK_EQ(DaysInYear(2025), 365);
    CHECK_EQ(DaysInMonth(2028, 2), 29); CHECK_EQ(DaysInMonth(2025, 2), 28);
    // era + known dates
    CHECK_EQ(AbsDayFromYmd(2025, 1, 1), 0);
    CHECK_EQ(AbsDayFromYmd(2025, 12, 31), 364);
    CHECK_EQ(AbsDayFromYmd(2026, 1, 1), 365);
    CHECK_EQ(AbsDayFromYmd(2028, 3, 1), AbsDayFromYmd(2028, 2, 29) + 1);   // Feb 29th exists
    // weekday: 2025-01-01 Wednesday(3); 2025-01-05 Sunday(0); 2025-06-15 Sunday(0)
    CHECK_EQ(WeekdayFromAbsDay(0), 3);
    CHECK_EQ(WeekdayFromAbsDay(4), 0);
    CHECK_EQ(WeekdayFromAbsDay(AbsDayFromYmd(2025, 6, 15)), 0);
    // round-trip year/doy
    int yy, dd; YearDoyFromAbsDay(365, yy, dd); CHECK_EQ(yy, 2026); CHECK_EQ(dd, 1);
    YearDoyFromAbsDay(AbsDayFromYearDoy(2030, 100), yy, dd); CHECK_EQ(yy, 2030); CHECK_EQ(dd, 100);
    // 28-year cycle: Jan 1 2025 and Jan 1 2053 fall on the same day of the week
    CHECK_EQ(WeekdayFromAbsDay(AbsDayFromYmd(2025, 1, 1)), WeekdayFromAbsDay(AbsDayFromYmd(2053, 1, 1)));
}

// RealignDoy places a date on the same month + Nth weekday in the target year.
static void test_realign_doy() {
    using namespace career::dateutil;
    // idempotence: same year -> same doy (key: the base year 2025 doesn't change)
    for (int doy = 1; doy <= 365; ++doy) CHECK_EQ(RealignDoy(2025, doy, 2025), doy);
    // June 15, 2025 = the 3rd Sunday of June. In 2026 the 3rd Sunday of June is June 21st (doy 172).
    CHECK_EQ(RealignDoy(2025, 166, 2026), DoyFromYmd(2026, 6, 21));
    // the result ALWAYS falls in the same month and on the same day of the week as the reference
    int m0,d0; YmdFromYearDoy(2025,166,m0,d0);
    int wdRef = WeekdayFromAbsDay(AbsDayFromYmd(2025,m0,d0));
    for (int ty = 2026; ty <= 2045; ++ty) {
        int rd = RealignDoy(2025, 166, ty); int m,d; YmdFromYearDoy(ty, rd, m, d);
        CHECK_EQ(m, 6);                                              // still in June
        CHECK_EQ(WeekdayFromAbsDay(AbsDayFromYmd(ty,m,d)), wdRef);   // still a Sunday
    }
    // 25/09 ([tester], rc.3): the 4th and 5th Friday of January 2025 (24 and 31, Aurora Series 3799) NEVER fall on the same day:
    // the nonexistent 5th occurrence jumps to the following week (2029: 26-Jan and 2-Feb), not back to the 4th.
    for (int ty = 2026; ty <= 2045; ++ty) {
        const int a = RealignDoy(2025, 24, ty), b = RealignDoy(2025, 31, ty);
        CHECK(a < b);
        CHECK_EQ(b - a, 7);                                          // one week exactly, same Friday
    }
    CHECK_EQ(RealignDoy(2025, 31, 2029), DoyFromYmd(2029, 2, 2));
}

// LoadCalendar migrates the 1-based year from legacy saves to the real calendar year.
static void test_calendar_load_legacy_year() {
    using namespace career;
    const char* p = "build/test_legacy_cal.sav";   // relative: the harness runs from the repo root
    // legacy save: year=1 (pre-kStartYear), doy 75
    { FILE* f = fopen(p, "wb"); CHECK(f != nullptr); fprintf(f, "C|1|75|0|0|0|0\r\n"); fclose(f); }
    CareerCalendar cc;
    CHECK(LoadCalendar(cc, p));
    CHECK_EQ(cc.year, kStartYear);        // 1 -> 2025
    CHECK_EQ(cc.cursor_doy, 75);
    // year=3 -> 2027
    { FILE* f = fopen(p, "wb"); CHECK(f != nullptr); fprintf(f, "C|3|10|0|0|0|0\r\n"); fclose(f); }
    CHECK(LoadCalendar(cc, p));
    CHECK_EQ(cc.year, kStartYear + 2);
    // modern save (real year) untouched
    { FILE* f = fopen(p, "wb"); CHECK(f != nullptr); fprintf(f, "C|2030|100|0|0|0|0\r\n"); fclose(f); }
    CHECK(LoadCalendar(cc, p));
    CHECK_EQ(cc.year, 2030);
    CHECK_EQ(cc.cursor_doy, 100);
    remove(p);
}

// LoadCareer discards offer_first_seen values on the old scale (year*365+doy) so the
// offer TTL doesn't break on a pre-migration save; an entry already on the new scale (abs_day) is kept.
static void test_offer_first_seen_scale_heal() {
    using namespace career;
    const char* path = "build/test_ofs_heal.sav";   // relative: the harness runs from the repo root
    SaveData old; old.offer_first_seen["of_pinnacle_series_4783"] = 2025 * 365 + 100;   // ~739325: OLD scale
    CHECK(SaveCareer(old, path));
    SaveData loaded;
    CHECK(LoadCareer(loaded, path));
    CHECK(loaded.offer_first_seen.empty());                                  // discarded
    SaveData fresh; fresh.offer_first_seen["of_pinnacle_series_4783"] = 120;            // NEW scale (abs_day)
    CHECK(SaveCareer(fresh, path));
    SaveData loaded2;
    CHECK(LoadCareer(loaded2, path));
    CHECK_EQ((long)loaded2.offer_first_seen.size(), 1);
    CHECK_EQ(loaded2.offer_first_seen["of_pinnacle_series_4783"], 120);                 // kept
    remove(path);
}

// ProjectSeason re-dates the reference calendar (2025) to the requested year; 2025 == identity.


// BuildMasterCalendar (what the player SEES) uses
// ProjectSeason(seriesId, cc.year) -- dates RE-ALIGNED to the current year -- but PendingSlot/SlotForRound
// kept using CalendarForSeries (RAW doys from the base year 2025). In kStartYear it makes no difference (RealignDoy is
// the identity there -> zero divergence, which is why the whole suite passed green), but from year=kStartYear+1 onward
// the two sources can diverge by up to ~6 days. Real consequence: the cursor lands on the PROJECTED date
// (AdvanceToNextEvent -> BuildMasterCalendar), and if the RAW doy of the round you just travelled to
// falls behind that cursor, DnfPassedRounds (which compares against PendingSlot) marks it DNF the moment
// you arrive: you lose the very race you just showed up for.


// CalendarForSeriesInYear wraps ProjectSeason with a memo cache keyed by (seriesId,year) -- see the
// full contract in career_calendar.h/cpp. This test covers: (1) identity at kStartYear, (2) that the
// projection matches ProjectSeason for a REAL series/year where it diverges from the raw value, and (3) the
// CRITICAL point -- that the cache gets invalidated when LoadSeriesCalendar/ReplaceCalendar replace the base
// calendar, so a reload never serves STALE dates (exactly the bug the cache could introduce if nobody
// cleared it: see the comment next to g_calInYearCache in career_calendar.cpp).


// Migrating UI/query paths to PROJECTED dates: QueryMemories (career_api_queries.cpp) used to decide
// a PERIOD series' round state ("open"/"upcoming") by comparing the cursor against the RAW doy from
// CalendarForSeries (the kStartYear=2025 reference calendar), instead of the doy PROJECTED to the current year
// (CalendarForSeriesInYear/ProjectSeason). At kStartYear the two agree; the divergence only shows up from
// the 2nd season onward. It finds, PROGRAMMATICALLY (the same search pattern as
// test_pending_slot_projected_year/test_calendar_in_year), a real period series and a year where the
// PROJECTED doy lands AHEAD of the RAW one (proj < raw), and places the cursor EXACTLY at proj_doy: the round has
// ALREADY arrived according to the re-aligned clock, but the raw value (pre-fix) doesn't see it as arrived yet -> the engine would mark it
// "upcoming" when it should be "open". Currently failing: QueryMemories uses CalendarForSeries (raw) via in.year
// (not yet consumed).


// bug reported (05/08, "next event"): the next-event button wasn't moving the clock. NextEventAbsDay
// picks the earliest round AHEAD of the cursor and subtracts its footprint's lead time to land at the start
// of the weekend -- without checking that the destination was still ahead. With an event less than 'lead' days away
// (and 105 of the 115 series have lead>=1), the destination came out <= today, and AdvanceToDate doesn't advance with days<=0:
// a silent no-op. Measured against the production calendar: 281 of the year's 351 days have an event
// ahead of them, and in 138 the destination landed BEFORE today. It's the same footprint arithmetic behind the next-day DNF
// next, as seen from the clock (see test_consecutive_day_rounds_no_false_dnf).
// The invariant being pinned is the player's: if any event remains, the jump ADVANCES. And without loosening
// with the weekend not yet started it still lands on doy - lead.


// the per-series footprint governs the occupancy window for travel conflicts.


// AdvanceToNextEvent lands at the START of the weekend (doy - footprint.lead), not on race day.
// NOTE (correcting an earlier assumption): at frontier_phase=7 the "reachable" universe of NextEventAbsDay
// is practically the ENTIRE calendar (105+ series) -- enrolled or merely open in the future counts the same
// (same criterion as WeeksToNextEvent), so rolling forward into nimbus_championship_1339 does NOT guarantee it's the winning round:
// with cursor_doy=20 almost any mid/high-tier series has an earlier round in the year. That's why
// the real winner is computed here with the same BuildMasterCalendar (an already-tested primitive), without touching
// its selection criteria -- this only verifies the footprint subtraction added on top of that
// winner, and lead>0 is required so the CHECK isn't vacuous (if the winner had lead=0, a bug that
// "forgets" to subtract would pass anyway).


// the year+1 fallback uses the RE-ALIGNED calendar for next year (not this year's doys).


// SessionDatesForSlot derives real P/Q/C dates within the weekend from the footprint.


// Showcase price ("from X credits"): the price shown is that of the REAL cheapest car in the class, not the
// economy row's base value. Aurora_Masters: base purchase 150k, but the real cars in the catalog
// (ams2_vehclass.psv) have a REAL override in ams2_vehicle_prices.psv (520k/540k) -> the minimum is 520k.
// Purchase prices are not compressed (the collector case exists) -- compression applies only
// to the per-race ECONOMIC value (CarItem.runValue), covered in test_price_compression.


//
// a real, anonymized fixture, plus verifiable guarantees about it.
// Phase tracer -- walks the entire path the following tasks will walk: create an artifact,
// write a test that uses it, register it in main(), watch the harness go green, sabotage-test that it actually bites.
//

// C1 (/): the stop rules live in the save, 'stoprules' line, write-when-non-default.
// A save with the default rules does NOT gain a line (byte-identical, safe downgrade); a changed rule
// survives the round-trip; an old save without the line loads the defaults.
static void test_stoprules_roundtrip() {
    using namespace career;
    const char* path = "build/stoprules_rt.sav";
    paths::EnsureParentDir(path);
    {   // defaults -> no line
        SaveData a; CHECK(a.stop_rules == StopRules{});
        CHECK(SaveCareer(a, path));
        std::string bytes = SlurpBytes(path);
        CHECK(bytes.find("stoprules") == std::string::npos);
        SaveData b; CHECK(LoadCareer(b, path));
        CHECK(b.stop_rules == StopRules{});
    }
    {   // changed -> line and exact round-trip
        SaveData a; a.stop_rules.offers = false; a.stop_rules.anyRace = true; a.stop_rules.relation = true;
        CHECK(SaveCareer(a, path));
        std::string bytes = SlurpBytes(path);
        CHECK(bytes.find("stoprules 0 1 1 0 1\r\n") != std::string::npos);
        SaveData b; CHECK(LoadCareer(b, path));
        CHECK(b.stop_rules == a.stop_rules);
        CHECK(!b.stop_rules.offers); CHECK(b.stop_rules.myRaces); CHECK(b.stop_rules.anyRace);
        CHECK(!b.stop_rules.mail);   CHECK(b.stop_rules.relation);
    }
}

// Tracer: loads the real fixture, saves it, reloads that save, saves it again
