// The contract exercised on the real subject. Loads the world data through the
// SHARED function (career::LoadSeasonData) -- never with hand-written file paths --
// the harness's first consumer of that contract.


// career::FormatDataRootFingerprint is PURE -- it's tested here on a
// hand-built report (without touching disk), which is exactly the advantage of it being pure.

// 07/09 - THE APP LOCK. Reported by the developer of another mod that also writes the
// CustomAIDrivers XML files: a file of ours left orphaned in the game's folder (killing the app, a hang, a power cut, or
// closing it with AMS2 still open) makes EVERY start of AMS2 load the engine and overwrite somebody else's
// files, with Career Engine closed. The new rule is that with no app alive NOTHING runs.
//
// The lock has to be a KERNEL object and not a flag file: a file would have EXACTLY the
// same problem as the file above -staying behind when its owner dies abruptly- and we would be fixing
// the fault with a copy of the fault. What is tested here is exactly that property, in the third CHECK.


static void test_fingerprint_format() {
    using namespace career;

    SeasonDataReport report;
    {
        SeasonDataset a; a.name = "series"; a.rel = "series.psv"; a.root = "data";
        a.opened = true; a.has_count = true; a.rows = 14;
        report.datasets.push_back(a);
    }
    {
        // A MEASURABLE zero rows (has_count=true, rows=0): it has to come out with a real '0'.
        SeasonDataset b; b.name = "class_difficulty"; b.rel = "class_difficulty.psv"; b.root = "data";
        b.opened = false; b.has_count = true; b.rows = 0;
        b.reason = "ausente del data root hoy";
        report.datasets.push_back(b);
    }
    {
        // WITHOUT a measurable number (has_count=false): it has to come out with the NO-NUMBER marker, never a '0'.
        SeasonDataset c; c.name = "special_events"; c.rel = "special_events.json"; c.root = "data";
        c.opened = true; c.has_count = false; c.rows = 0;
        c.reason = "recuento dependiente del reloj";
        report.datasets.push_back(c);
    }

    const std::string f1 = FormatDataRootFingerprint(report);
    const std::string f2 = FormatDataRootFingerprint(report);
    CHECK(f1 == f2);      // formatting the same report twice gives EXACTLY the same string
    CHECK(!f1.empty());

    // No absolute Windows path (drive letter + colon + backslash) in the output.
    {
        bool anyAbsolute = false;
        for (size_t i = 0; i + 2 < f1.size(); i++) {
            char ch = f1[i];
            bool isLetter = (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
            if (isLetter && f1[i + 1] == ':' && f1[i + 2] == '\\') { anyAbsolute = true; break; }
        }
        CHECK(!anyAbsolute);
    }
    // No digits shaped like a timestamp (NN:NN:NN).
    {
        auto isDigit = [](char c) { return c >= '0' && c <= '9'; };
        bool anyClockStamp = false;
        for (size_t i = 0; i + 8 <= f1.size(); i++) {
            if (isDigit(f1[i]) && isDigit(f1[i + 1]) && f1[i + 2] == ':' &&
                isDigit(f1[i + 3]) && isDigit(f1[i + 4]) && f1[i + 5] == ':' &&
                isDigit(f1[i + 6]) && isDigit(f1[i + 7])) { anyClockStamp = true; break; }
        }
        CHECK(!anyClockStamp);
    }

    // Line order matches the report order: series -> class_difficulty -> special_events.
    {
        size_t posSeries = f1.find("series ");
        size_t posDifficulty = f1.find("class_difficulty");
        size_t posSpecial = f1.find("special_events");
        CHECK(posSeries != std::string::npos);
        CHECK(posDifficulty != std::string::npos);
        CHECK(posSpecial != std::string::npos);
        CHECK(posSeries < posDifficulty);
        CHECK(posDifficulty < posSpecial);
    }

    // class_difficulty (a MEASURABLE zero) comes out DIFFERENT from special_events (no measurable number): they're never
    // confused -- only the second carries the NO-NUMBER marker.
    {
        size_t posDifficulty = f1.find("class_difficulty");
        size_t posSpecial = f1.find("special_events");
        std::string lineDifficulty = f1.substr(posDifficulty, f1.find('\n', posDifficulty) - posDifficulty);
        std::string lineSpecial = f1.substr(posSpecial, f1.find('\n', posSpecial) - posSpecial);
        CHECK(lineDifficulty.find("SIN-NUMERO") == std::string::npos);
        CHECK(lineSpecial.find("SIN-NUMERO") != std::string::npos);
    }

    // The status line says NOT CLEAN: there are affected entries.
    CHECK(f1.find("NO LIMPIA") != std::string::npos);
    CHECK(!SeasonDataIsClean(report));

    // On the REAL report from the repo's data root: one line per dataset.
    SeasonDataOpts opts; opts.useJson = false;
    SeasonDataReport real;
    LoadSeasonData(opts, real);
    const std::string realFp = FormatDataRootFingerprint(real);
    int lineCount = 0;
    for (const auto& d : real.datasets)
        if (realFp.find(d.name) != std::string::npos) lineCount++;
    CHECK_EQ((long long)lineCount, (long long)real.datasets.size());
}

