// The 'seatocc' line is written "<key>|<driver>" and was read by splitting on the FIRST '|'. The slot
// key IS "<series>|<veh>|<livery>", so "seatocc gt3|12345|7|rd_hamilton" was reread with key "gt3" and
// occupant "123457rd_hamilton": the whole save wrecked without a single warning. It is split on the LAST, which with
// a legacy key is the same one and with the new one is the correct one.
static void test_save_roundtrip_slot_keys() {
    using namespace career;
    SaveData a;
    a.prog.credits = 4242;
    a.seat_occupant["onyx_cup_4824|12345|7"]  = "rd_lewis_hamilton";   // key by SLOT (with pipes inside)
    a.seat_occupant["harbor_trophy_6546#0"]      = "rk_lucia";            // LEGACY key, in the same save
    a.seat_occupant["onyx_cup_4824|12345|9"]  = kSeatOpen;             // and the open sentinel
    a.seat_contract_start["onyx_cup_4824|12345|7"] = 2033;
    a.seat_contract_start["harbor_trophy_6546#0"]     = 2031;
    a.primary_seat_by_driver["rd_lewis_hamilton"] = "onyx_cup_4824|12345|7";
    a.seat_key_epoch = 1;

    const char* p = "build/test_slotkeys.sav";
    CHECK(SaveCareer(a, p));
    SaveData b;
    CHECK(LoadCareer(b, p));
    CHECK(b.seat_occupant == a.seat_occupant);                    // key AND occupant, as is
    CHECK(b.seat_contract_start == a.seat_contract_start);
    CHECK(b.primary_seat_by_driver == a.primary_seat_by_driver);
    CHECK(b.seat_key_epoch == 1);
    CHECK(b.seat_occupant["onyx_cup_4824|12345|7"] == "rd_lewis_hamilton");
    // And the full cycle once more: saving what was read must give the same thing (format idempotence).
    const char* q = "build/test_slotkeys2.sav";
    CHECK(SaveCareer(b, q));
    SaveData c;
    CHECK(LoadCareer(c, q));
    CHECK(c.seat_occupant == a.seat_occupant);
}

// //— the world stated in CONTRACTS, and who rules when someone has two seats.


// — the secondary rule, in isolation: same series NO, two-tier jump NO, other family NO.


// ===================================================================================================
// — the v2 identity catalog (dll/career/career_registry.*)
// ===================================================================================================

// THE PHASE INVARIANT (): "the 572 known fictional drivers are not labeled as real in the
// new catalog". Today `kind=real` in drivers.json means "is not from the cohort", not "is a
// real person", and that ambiguity is what prevents imposing different rules on real, cohort, reserve and generated drivers.


// One identity per person: the genome comes from the id and nothing else, the name always resolves to the same id, and
// registering someone already there does not overwrite them (published IDs are neither removed nor reused).


static void test_canon_vocab() {
    using namespace career::canon;
    // Round trip of the six families: the index of affinity_vector/family_experience depends on the
    // enum order and the names order never drifting apart.
    for (int i = 0; i < (int)Family::Count; i++) {
        Family f = (Family)i, back = Family::Historic;
        CHECK(FamilyFromName(FamilyName(f), back));
        CHECK((int)back == i);
    }
    // A string that is not a family must say NO and not touch the output: "I don't know" and "it's single-seater" are
    // different answers, and confusing them is how the cohort would end up with invented affinity.
    Family sentinel = Family::Oval;
    CHECK(!FamilyFromName("gt3", sentinel));
    CHECK(sentinel == Family::Oval);
    CHECK(!FamilyFromName("", sentinel));
    CHECK(std::string(OriginName(Origin::Real)) == "real");
    CHECK(std::string(RoleName(PopRole::Cohort)) == "cohort");
    CHECK(std::string(StateName(LifeState::FreeAgent)) == "free_agent");
}

// The ADAPTER contract: what it builds must be internally coherent. It does not judge whether today's world
// is good (it is not, and that is why the following phases exist) — it judges that the reading is faithful.


// "shuffling the order of the series produces the same world" is still NOT met (that is .5),
// but the ADAPTER does have to be reproducible: two reads of the same save give the same census. Without
// this, comparing the census between phases means nothing.


// THE MEASUREMENT PHASE A EXISTS FOR. It does not check that the world is fine —it is bad, and measured—
// but that the INSTRUMENT sees it. If one day the census stopped counting unseeded occupants or the
// classes that mix scales, phases C.5 and D would go back to being validated by eye, which is exactly how the
// five attempts of 09/08 were lost.


// THE OTHER CENSUS, the one that truly describes the knot: the COMPOSED grid. Worth separating
// because it contradicts the seats one and that contradiction is information — the people who race do not come from the
// seats model, so fixing the seats does not fix the grid (the closes that).


// ===================================================================================================
// seedlab: the SEEDING TEST BENCH (precondition of .5)
// ===================================================================================================
//
// WHY IT EXISTS. .5 asks for two things and one of them clashes head-on with a user decision:
//   · "seeding independent of traversal order" () — a pure fix, nobody disputes it.
//   · "bring CastSeedFromBase to the level-anchored scale" — but on 02/07 the OPPOSITE was decided ON
//     purpose: the cohort is "the worst generation", monsters from day one, and its seeding is
//     TIER-INDEPENDENT by design (see the comment on CAST_SEED_RATING_HI in career_balance.h).
//
// That decision cannot be made by code. What code can do is MEASURE each option before
// writing any, which is exactly what was missing in the five attempts of 09/08. This bench composes the
// 100 production grids with each seeding rule and outputs the same table for all of them.
//
// It does NOT touch production: the variants are built on the engine's primitives (LevelAnchoredSeed,
// CastSeedFromBase, FieldOccupantId, WorldContracts) and only HOW they are composed changes, which is exactly what
// is being evaluated. None of this is linked into the DLL.
namespace seedlab {

using namespace career;

// A seeding entry as LevelAnchoredSeed would see it, with the series it comes from.
struct Cand { std::string series; int level = 1, order = 0, fieldSize = 0; bool iconic = false; };

// All candidates by id: the FULL traversal (fields + pinned rosters) with the id resolution
// shared. It is the "unified id" half of the fix measured on 09/08.
static std::map<std::string, std::vector<Cand>> Candidatos() {
    std::map<std::string, std::vector<Cand>> m;
    for (const auto& sd : AllSeries()) {
        std::vector<FieldDriver> field = FieldForSeries(sd.id);
        for (const auto& fd : field) {
            const std::string id = FieldOccupantId(fd);
            if (id.empty()) continue;
            m[id].push_back(Cand{ sd.id, sd.level, fd.order, (int)field.size(), fd.iconic });
        }
        std::vector<PinnedDriver> pin = PinnedRosterForSeries(sd.id);
        for (int i = 0; i < (int)pin.size(); i++) {
            const std::string id = PinnedOccupantId(pin[i]);
            if (id.empty()) continue;
            // The order of the pinned file IS the standings one: row i is the i-th of the real season.
            m[id].push_back(Cand{ sd.id, sd.level, i + 1, (int)pin.size(), false });
        }
    }
    return m;
}

// — THE SEAT PEOPLE, which every variant has to seed or it does not measure what it thinks.
//
// Production seeds in three passes: fields+pinned, anchored cohort, and the seat occupants (each series' own
// tail and the pack drivers). The bench variants build their map by hand from
// `Candidatos()`, which only walks the first two — so they were left with 244 rows without ELO and went back to
// measuring "two scales in the same grid" instead of what they wanted to measure. Same idempotence guard as
// production: whoever already has a rating is not touched.
static void SembrarAsientos(std::map<std::string, double>& r) {
    for (const auto& sd : AllSeries()) {
        const std::vector<std::string> ocupantes = DerivedSeatOccupants(sd.id);
        const int n = (int)ocupantes.size();
        for (int i = 0; i < n; i++) {
            if (ocupantes[i].empty() || r.count(ocupantes[i])) continue;
            r[ocupantes[i]] = LevelAnchoredSeed(sd.level, i + 1, n, /*iconic=*/false);
        }
    }
}

// The cohort with its usual seeding (tier-independent, decision of 02/07).
static void SembrarCohorteComoHoy(std::map<std::string, double>& r) {
    for (int t = 1; t <= 7; t++)
        for (const auto& rd : RosterForTier(t))
            if (!rd.id.empty() && !r.count(rd.id)) r[rd.id] = CastSeedFromBase(rd.base_skill);
}

// The cohort ANCHORED to its home tier (.5 as written). The order within the cast comes
// from its authored base_skill, which is the hierarchy the user curated.
static void SembrarCohorteAnclada(std::map<std::string, double>& r) {
    std::vector<RosterDriver> cast = RosterForTier(1);
    std::sort(cast.begin(), cast.end(), [](const RosterDriver& a, const RosterDriver& b) {
        if (a.base_skill != b.base_skill) return a.base_skill > b.base_skill;
        return a.id < b.id;
    });
    for (int i = 0; i < (int)cast.size(); i++) {
        if (cast[i].id.empty() || r.count(cast[i].id)) continue;
        r[cast[i].id] = LevelAnchoredSeed(bal::COHORT_HOME_MAX_TIER, i + 1, (int)cast.size(), cast[i].hot);
    }
    SembrarCohorteComoHoy(r);   // in case some roster row did not get in above
}

// V0 — TODAY: production as is.
static std::map<std::string, double> V0() {
    std::map<std::string, double> r; SeedAllDrivers(r); return r;
}

// V1 — unified id, first-wins (the traversal decides, as today). Cohort intact.
static std::map<std::string, double> V1() {
    std::map<std::string, double> r;
    for (const auto& sd : AllSeries()) {
        std::vector<FieldDriver> field = FieldForSeries(sd.id);
        for (const auto& fd : field) {
            const std::string id = FieldOccupantId(fd);
            if (id.empty() || r.count(id)) continue;
            r[id] = LevelAnchoredSeed(sd.level, fd.order, (int)field.size(), fd.iconic);
        }
        std::vector<PinnedDriver> pin = PinnedRosterForSeries(sd.id);
        for (int i = 0; i < (int)pin.size(); i++) {
            const std::string id = PinnedOccupantId(pin[i]);
            if (id.empty() || r.count(id)) continue;
            r[id] = LevelAnchoredSeed(sd.level, i + 1, (int)pin.size(), false);
        }
    }
    SembrarCohorteComoHoy(r);
    SembrarAsientos(r);            // the seat people, as production
    return r;
}

// V2 — V1 + cohort anchored to level. It is .5 literally.
static std::map<std::string, double> V2() {
    std::map<std::string, double> r = V1();
    std::map<std::string, double> soloCohorte;
    SembrarCohorteAnclada(soloCohorte);
    for (const auto& kv : soloCohorte) r[kv.first] = kv.second;   // overrides the cast's
    return r;
}

// V3 — unified id + seeding by the PRINCIPAL SEAT, cohort intact.
// It is the option that only exists since the "your category is that of your principal contract" () is
// independent of traversal order WITHOUT being "the highest level you race in", which is measured and
// makes the ace worse. And it does not touch the cohort seeding, which is a user decision.
static std::map<std::string, double> V3(const SaveData& save) {
    std::map<std::string, double> r;
    const std::map<std::string, std::vector<Cand>> cands = Candidatos();
    std::map<std::string, std::string> serieDelPrincipal;
    for (const auto& c : WorldContracts(save)) if (c.primary) serieDelPrincipal[c.driver_id] = c.series_id;

    for (const auto& kv : cands) {
        const std::vector<Cand>& v = kv.second;
        if (v.empty()) continue;
        const Cand* elegido = &v[0];
        auto sp = serieDelPrincipal.find(kv.first);
        if (sp != serieDelPrincipal.end())
            for (const auto& c : v) if (c.series == sp->second) { elegido = &c; break; }
        r[kv.first] = LevelAnchoredSeed(elegido->level, elegido->order, elegido->fieldSize, elegido->iconic);
    }
    SembrarCohorteComoHoy(r);
    SembrarAsientos(r);            // ditto
    return r;
}

// V4 - V3 + anchored cohort: the only one that meets BOTH halves of .5 at once (cohort at level
// And seeding independent of traversal order, ). It is V2 minus the order dependency.
static std::map<std::string, double> V4(const SaveData& save) {
    std::map<std::string, double> r = V3(save);
    std::map<std::string, double> soloCohorte;
    SembrarCohorteAnclada(soloCohorte);
    for (const auto& kv : soloCohorte) r[kv.first] = kv.second;
    return r;
}

// V5 — THE AUTHORED CAPACITY AS SEEDING (/, the core of ).
//
// Today `ratingSkill` REPLACES the authored talent with RatingQuality(ELO). says something else: capacity
// rules, and the ELO only contributes a BOUNDED `form_delta` weighted by confidence --
//     form_delta = clamp((results_rating - pace_rating) * races/(races+window), +-CAP)
// In year 1 nobody has races, so confidence is 0 and the grid is 100% authored. That is the
// variant measured here: `pace_rating` converted from the authored talent, with no ELO at all.
//
// The conversion is LINEAR from the corpus's real range to the ladder band. It is not the final one -- the
// final one comes from the anchors of .0 -- but it serves the only thing needed now: to see
// HOW MUCH the saturated corpus compresses the front, which is the user's objection, with a number.
static std::map<std::string, double> V5() {
    std::map<std::string, double> r;
    // real range of the authored corpus
    double lo = 1e9, hi = -1e9;
    for (const auto& kv : AllAuthoredProfiles()) { lo = std::min(lo, kv.second.talent); hi = std::max(hi, kv.second.talent); }
    if (!(hi > lo)) return r;
    const double rLo = bal::RATING_ROOKIE_BASE, rHi = bal::CAST_SEED_RATING_HI;
    auto aPuntos = [&](double t) { return rLo + (t - lo) / (hi - lo) * (rHi - rLo); };

    // Everyone who races, with the SAME id resolution as the composer.
    const std::map<std::string, std::vector<Cand>> cands = Candidatos();
    for (const auto& kv : cands) {
        const canon::DriverIdentity* di = registry::ById(kv.first);
        const AuthoredProfile* ap = di ? AuthoredProfileFor(di->display_name) : nullptr;
        if (ap && ap->talent > 0.0) r[kv.first] = aPuntos(ap->talent);
        else if (!kv.second.empty()) {
            // Without an authored card there is no capacity to use: it keeps the level anchor, which is what
            // there is. They are the ones .0 has to cover.
            const Cand& c = kv.second[0];
            r[kv.first] = LevelAnchoredSeed(c.level, c.order, c.fieldSize, c.iconic);
        }
    }
    // The cohort, ANCHORED to its home tier just as in production (.5). Seeding it by its
    // authored base_skill on this scale undoes the 10/08 decision -- measured: the youth academy went on to
    // lead 17 classes out of 100, with Kenji Mori and Lars Vogt on the GT3 podium. The authored capacity rules
    // for the REAL ones; the cohort has its own rule and is not touched here.
    {
        std::vector<RosterDriver> cast = RosterForTier(1);
        std::sort(cast.begin(), cast.end(), [](const RosterDriver& a, const RosterDriver& b) {
            if (a.base_skill != b.base_skill) return a.base_skill > b.base_skill;
            return a.id < b.id;
        });
        for (int i = 0; i < (int)cast.size(); i++)
            if (!cast[i].id.empty()) r[cast[i].id] = CohortAnchoredSeed(i + 1, (int)cast.size(), cast[i].hot);
    }
    SembrarAsientos(r);            // the series' own tail and the pack drivers race too
    return r;
}

}   // namespace seedlab

// ===================================================================================================
// world <file.txt>: THE MARKET INSTRUMENT ()
// ===================================================================================================
//
// IT GOES FIRST, AND THAT IS HALF OF ITS VALUE. moves the anchor from the driver to the team and lets the
// distribution by level EMERGE from an economy instead of being imposed. That is the easiest thing to break in the
// whole design: if offers are generated badly, an 80 stays in tier 1 forever and **no rule
// can rescue him**. Without a measurement, we would tune budgets blindly — which is exactly how the
// five attempts of 09/08 were lost.
//
// WHAT IT MEASURES TODAY AND WHAT IT DOES NOT. A driver's "value" in will be their attribute average; it does not exist yet, so
// ELO is plugged in here, which is what fills that role today. The instrument is written against an
// ABSTRACT VALUE (`ValorDe`) precisely so that the day it lands that function is swapped and the
// five measures keep meaning the same. ECONOMIC pressure cannot be measured yet —the
// budgets are — so occupancy is measured instead, which is its antechamber.
namespace worldlab {

using namespace career;

// A driver's value. TODAY the ELO; with , their attribute average. A single place to change.
static double ValorDe(const SaveData& save, const std::string& id) {
    const auto it = save.driver_ratings.find(id);
    return it == save.driver_ratings.end() ? 0.0 : it->second;
}

// Which level does that value BELONG to? The nearest midpoint of the ladder scale. It is what turns
// "1850 points" into "this is level-6 people" and allows saying someone is misplaced.
static int NivelDelValor(double v) {
    int mejor = 1; double d = 1e18;
    for (int t = 1; t <= 7; t++) {
        const double dd = std::fabs(v - bal::LEVEL_SEED_MIDPOINT[t - 1]);
        if (dd < d) { d = dd; mejor = t; }
    }
    return mejor;
}

struct Foto {
    int temporada = 0;
    int asientos = 0, ocupados = 0, libres = 0;
    int ocupantes = 0;                       // distinct people with a seat
    int reales = 0, cohorte = 0, generados = 0;
    double p10[8] = {0}, p50[8] = {0}, p90[8] = {0};   // value per tier (1..7)
    int porTier[8] = {0};
    int arribaDeSuSitio = 0, abajoDeSuSitio = 0;       // misplaced by >= 2 levels
    // NO VALUE: occupants with a seat and no ELO. It goes on the face of the report because it is the only way for
    // the histogram not to lie: if these people are not counted and not mentioned, a level can come out with n=1
    // looking empty when it is actually full of people the measure does not see. It really happened the first
    // time this was run (level 1 with n=1 at 20 seasons, and they were 908 unseeded rookies).
    int sinValor = 0;
    int movidos = 0;                                   // changed tier compared to the previous snapshot
    std::string peorArriba, peorAbajo;
    // THE GUARD AGAINST MISREADING THE MISPLACED. `NivelDelValor` compares the value with the FIXED
    // midpoints of the ladder, so if the ELO merely SPREADS OUT more within each series —which is what
    // an ELO does as soon as people really race— more people end up near the midpoint of another level without
    // anyone being misplaced. The count would rise by itself and look like a broken world.
    //
    // This number breaks the tie: it is the ELO width WITHIN a series (p90-p10), median of all of them. If it grows
    // at the same rate as the misplaced, what is being measured is the spread; if the misplaced
    // grow and this does not, people really are in the wrong place.
    double anchoIntraP50 = 0.0;
    // THE SECOND GUARD, and it is needed: "misplaced" compares a value with the FIXED midpoints of the
    // ladder, but the ELO is spread WITHIN each series. With an intra-series width of ~400 points and levels
    // ~126 apart, the tail of ANY grid falls two levels by pure arithmetic, whoever is in
    // it. So part of the count does not say "these people are surplus here", it says "every grid has a tail".
    //
    // This separates it: of the misplaced downward, how many are simply the back quarter of their
    // own field. Those who are NOT really are misplaced -- they trail even their own tail.
    int abajoQueSonLaCola = 0;
    // ~~~01/09 — THE SAME GUARD, BUT AT THE TOP. The artifact is SYMMETRIC and was only corrected on one
    //  side: if the tail of any grid falls two levels by arithmetic, the FRONT rises two for the
    //  same reason. Without this, "510 misplaced upward" mixes those who deserve to move up with the quarter
    //  at the front of each field, which is where it should be.
    int arribaQueSonLaPunta = 0;
    // And WHO we are talking about. A REAL driver does not move up by rule (their ceiling is their current category), so
    //  if the misplaced upward are real there is no ladder to fix. If they are GENERATED, there is.
    int arribaReal = 0, arribaCohorte = 0, arribaGenerado = 0;
    // AND THE QUESTION THAT CLOSES THE MATTER: of the generated drivers worth more than what they race, how many
    //  does the ceiling BLOCK. `tier_max <= tier` = already at their career ceiling, so no promotion path
    //  can take them (all of them check `r.tier_max < tier`). That one is not stuck for lack of
    //  openings: it is stuck BY DEFINITION, and their value will keep growing above with no way out.
    int arribaGenTechoTocado = 0;
};

// ===================================================================================================
// THE LIVE YARDSTICK AGAINST THE FROZEN YARDSTICK (17/08)
// ===================================================================================================
//
// Answers the user's question: "is the distribution immune to the evolution of the driver market? Is it going
// to flatten? What you feel in season 1 vs season 6 should be similar."
//
// Measures, at each milestone, the TALENT spread the grid the world has seated REALLY has, and
// compares it with the yardstick used today to divide that gap (`TalentRefSpanFor` = derived from the level x curated
// trim of the class). The two things that come out of here:
//
//   · live/frozen ratio — if it moves with the seasons, the TALENT-based system goes out of sync. It is
//     exactly what the 28/07 note left written ("the live talent span measures double the class's
//     yardstick") and what ended up sending the grid to Curve.
//   · how many series GO OUT OF THE ENVELOPE (ratio > 1) — there the last one falls into the affine extrapolation branch of
//     `RaceSkillShaped` and the 0.30 cap picks it up. It is the measured origin of the 44 piled on the floor.
//
// The LIVE yardstick cannot get out of sync by construction (the ace and the last define the extremes), so
// this measure serves two purposes at once: quantifying the defect of the frozen system and fixing the
// invariant the new one has to meet.
struct FotoVara {
    int temporada = 0;
    int series = 0, seSalen = 0;
    double p10 = 0, p50 = 0, p90 = 0;          // live/frozen ratio
    double reinaVivo = 0, reinaVara = 0;
    std::string reinaClase;
    double pctCongelada = 0, pctViva = 0;      // % of lap that each system WOULD DELIVER at the queen
    // THE STABLE MEDIAN PROVES NOTHING BY ITSELF: classes could be swapping places
    // and the p50 would not move. This keeps the ratio of EACH class so T1 can be compared against T20 one by one,
    // which is what "what you feel in season 1 vs season 6" really asks.
    std::map<std::string, double> porClase;
    std::map<std::string, double> vivoPorClase;
};

static FotoVara MedirVara(const SaveData& save, int temporada, int tierReina) {
    FotoVara f; f.temporada = temporada;
    std::vector<double> ratios;
    for (const auto& sd : AllSeries()) {
        if (IsEraMemorySeries(sd)) continue;                 // frozen: does not take part in the live world
        const std::vector<SeatRow> asientos = SeatRowsForSeries(save, sd.id);
        if (asientos.size() < 8) continue;
        // 18/08 (Task 3) — THE LAST THREE, BECAUSE PRODUCTION PASSES THEM. An instrument that composes
        // differently from production measures a grid the game does not write, and this project has lost three
        // measurements for exactly that. Without the curve, the birth and the year, this measure saw the
        // raw CLONED card -- i.e. the disease (the 19-year-old clone entering at the level of the adult it comes from)
        // but not the cure, and would have written off a fix that is in fact working.
        // The two reference rows of this plan (before the clone, and with the clone) are NOT re-derived and remain
        // valid: in those commits these three arguments did not exist, so production did not
        // pass them either and the instrument was aligned BY CONSTRUCTION. Only the new row needs them.
        const std::vector<GridDriver> grid = ComposeSeasonGrid(
            sd.id, sd.level, /*playerForm=*/0.0, (int)asientos.size(), /*useHomage=*/false,
            save.rival_form, /*exclude=*/nullptr, &save.driver_ratings,
            ClassRole::SingleClass, &asientos, /*skipLiveries=*/nullptr, &save.driver_races,
            &save.driver_curve, &save.birth_year, save.current_world_year);
        if (grid.size() < 8) continue;
        double lo = 2.0, hi = -2.0;
        for (const auto& d : grid) { if (d.talent < lo) lo = d.talent; if (d.talent > hi) hi = d.talent; }
        const double vivo = hi - lo;
        const double vara = TalentRefSpanFor(sd.class_name, sd.level);
        if (vivo <= 0.0 || vara <= 0.0) continue;
        f.series++;
        const double r = vivo / vara;
        ratios.push_back(r);
        f.porClase[sd.class_name] = r;
        f.vivoPorClase[sd.class_name] = vivo;
        if (r > 1.0) f.seSalen++;                            // the last one goes out of the measured envelope
        // The class the user is testing in game, named and apart from the automatic "queen".
        // No `empty()` guard on purpose: this class RULES over the automatic queen. The first version
        // had the guard and the block came out labeled "Juniper_Cup" with the numbers of Cinder_Series,
        // because the queen was found earlier in the traversal.
        if (sd.class_name == "Juniper_Cup") {
            f.reinaClase = sd.class_name; f.reinaVivo = vivo; f.reinaVara = vara;
            EnsureClassPaceLoaded();
            const ClassPace cp = ClassPaceFor(sd.class_name);
            const double spreadDriver = DriverSpreadPct(sd.id, sd.class_name, cp.spread_dry);
            const double suelo = FloorForSpread(spreadDriver);
            double v = (r <= 1.0) ? (1.0 - (1.0 - suelo) * r)
                                  : (suelo - (1.0 - suelo) * (r - 1.0));
            if (v < kMinDriveableSkill) v = kMinDriveableSkill;
            f.pctCongelada = PctOffForRaceSkill(v);
            f.pctViva      = spreadDriver;
            continue;
        }
        if (sd.level == tierReina && f.reinaClase.empty()) {
            f.reinaClase = sd.class_name; f.reinaVivo = vivo; f.reinaVara = vara;
            // What each system WOULD DELIVER for the last of this grid, in % of lap.
            EnsureClassPaceLoaded();
            const ClassPace cp = ClassPaceFor(sd.class_name);
            const double spreadDriver = DriverSpreadPct(sd.id, sd.class_name, cp.spread_dry);
            const double suelo = FloorForSpread(spreadDriver);
            const double u = r;                              // gap of the last, in yardsticks
            double v = (u <= 1.0) ? (1.0 - (1.0 - suelo) * u)         // inside the envelope
                                  : (suelo - (1.0 - suelo) * (u - 1.0));  // affine extrapolation
            if (v < kMinDriveableSkill) v = kMinDriveableSkill;
            f.pctCongelada = PctOffForRaceSkill(v);
            f.pctViva      = spreadDriver;                   // the live one ALWAYS delivers the class's datum
        }
    }
    if (!ratios.empty()) {
        std::sort(ratios.begin(), ratios.end());
        auto q = [&](double p) {
            const double i = p * (double)(ratios.size() - 1);
            const size_t lo = (size_t)i, hi = lo + 1 < ratios.size() ? lo + 1 : lo;
            return ratios[lo] + (i - (double)lo) * (ratios[hi] - ratios[lo]);
        };
        f.p10 = q(0.10); f.p50 = q(0.50); f.p90 = q(0.90);
    }
    return f;
}

// ===================================================================================================
// WHO ANCHORS THE GRID: A PERSON OR THE CAR? (re-measurement 18/08)
// ===================================================================================================
//
// Repeats the 18/08 measurement (the cards-vs-curve note in the 2026-08-17 grid-order plan)
// AFTER the `PersonForOccupant` cascade gives the generated tail its own card. Back then there were
// two categories ("with card" / "from curve"); now there are THREE, and separating them is exactly what is measured:
//
//   · AUTHORED — the card that already existed: pinned roster, field, pool, cohort or pack (via AuthoredProfileFor);
//   · CLONED   — the one added by the 18/08 plug: RookieProfileTalentCloned over the card corpus;
//   · CURVE    — without a card of any kind: the caller falls to the gap's curve point, i.e. the CAR's pace.
//
// WHY THE CASCADE HAS TO BE RE-DERIVED AND NOT A FIELD LOOKED AT. `GridDriver` carries NO provenance flag, and
// `authored_talent` cannot tell them apart: `ApplyDriverModel` writes
// `authored_talent = authoredBase > 0 ? authoredBase : baseTalent`, so it is ALWAYS > 0, with a card and without
// one. Asking `authored_talent > 0` gives "100 %" before and after the change — it cannot fail, and that is why it does not
// measure anything. The only thing that tells the three sources apart is WHERE the number came from, and that is only known by repeating
// the cascade.
//
// `PersonForOccupant` (career_fields.cpp:808) lives in an anonymous `namespace` and this is another translation
// unit, so it is COPIED to the letter, with the same public functions and the same order of
// precedence. The copy is VALIDATED at each milestone: production writes `authored_talent = p.talent` for every row
// with a card, so for every row classified here as with a card the two numbers have to match down to
// the last bit. The mismatch count goes in the report: if the copy drifts, it shows.
enum class Fuente { Autorada, Clonada, Curva };

// The per-series index, built the same way as in `ComposeGridFromSeats` (the vectors are KEPT: the three
// functions return by value and a pointer to their temporary would dangle).
struct IxFichas {
    std::vector<PinnedDriver> pinnedV;
    std::vector<FieldDriver>  fieldV;
    std::vector<std::vector<RosterDriver>> castV;
    std::map<std::string, const PinnedDriver*> pinned;
    std::map<std::string, const FieldDriver*>  field;
    std::map<std::string, const RosterDriver*> cast;
};

static IxFichas IndiceDeSerie(const std::string& seriesId) {
    IxFichas ix;
    ix.pinnedV = PinnedRosterForSeries(seriesId);
    for (const auto& pd : ix.pinnedV) { const std::string id = PinnedOccupantId(pd); if (!id.empty()) ix.pinned.emplace(id, &pd); }
    ix.fieldV = FieldForSeries(seriesId);
    for (const auto& fd : ix.fieldV) { const std::string id = FieldOccupantId(fd); if (!id.empty()) ix.field.emplace(id, &fd); }
    ix.castV.reserve(7);
    for (int t = 1; t <= 7; t++) ix.castV.push_back(RosterForTier(t));
    for (const auto& v : ix.castV) for (const auto& rd : v) if (!rd.id.empty()) ix.cast.emplace(rd.id, &rd);
    return ix;
}

struct FichaDe { double talento = 0.0; Fuente fuente = Fuente::Curva; bool resuelto = false; };

// The SAME seed used by `career_fields.cpp::SeedFromGeneratedId` (literal copy, same FNV-1a).
static unsigned long FichaFnv1a(const std::string& s) {
    unsigned long h = 2166136261ul;
    for (char c : s) { h ^= (unsigned char)c; h *= 16777619ul; }
    return h;
}
static unsigned long SemillaDeGenerado(const std::string& id) {
    const size_t u = id.rfind('_');
    if (u != std::string::npos && u + 1 < id.size()) {
        const std::string cola = id.substr(u + 1);
        if (!cola.empty() && cola.find_first_not_of("0123456789") == std::string::npos)
            return (unsigned long)strtoul(cola.c_str(), nullptr, 10);
    }
    return FichaFnv1a(id);
}

// To-the-letter copy of `PersonForOccupant`, keeping only the talent and its provenance.
static FichaDe FichaDeLaPersona(const std::string& id, const IxFichas& ix) {
    FichaDe r;
    if (id.empty()) return r;
    // 1) PINNED roster of the series
    const auto itp = ix.pinned.find(id);
    if (itp != ix.pinned.end()) {
        r.resuelto = true; r.talento = itp->second->skill;
        r.fuente = r.talento > 0.0 ? Fuente::Autorada : Fuente::Curva;
        return r;
    }
    // 2) FIELD of the series (its authored card rules over the PSV curve)
    const auto itf = ix.field.find(id);
    if (itf != ix.field.end()) {
        const FieldDriver& fd = *itf->second;
        const AuthoredProfile* ap = AuthoredProfileFor(fd.name);
        r.resuelto = true; r.talento = ap ? ap->talent : fd.skill;
        r.fuente = r.talento > 0.0 ? Fuente::Autorada : Fuente::Curva;
        return r;
    }
    // 3) global POOL
    if (const PoolDriver* pd = DriverById(id)) {
        const AuthoredProfile* ap = AuthoredProfileFor(pd->name);
        r.resuelto = true; r.talento = ap ? ap->talent : pd->base_skill;
        r.fuente = r.talento > 0.0 ? Fuente::Autorada : Fuente::Curva;
        return r;
    }
    // 4) COHORT
    const auto itc = ix.cast.find(id);
    if (itc != ix.cast.end()) {
        r.resuelto = true; r.talento = itc->second->base_skill;
        r.fuente = r.talento > 0.0 ? Fuente::Autorada : Fuente::Curva;
        return r;
    }
    // 5) livery PACKS: talent 0 unless they also have a card
    if (const PackDriver* pk = PackDriverById(id)) {
        const AuthoredProfile* ap = AuthoredProfileFor(pk->name);
        r.resuelto = true;
        if (ap && ap->talent > 0.0) { r.talento = ap->talent; r.fuente = Fuente::Autorada; }
        else                        { r.talento = 0.0;        r.fuente = Fuente::Curva; }
        return r;
    }
    // 6) THE GENERATED TAIL (`fl_*`, `gn_*`): since 18/08 its card comes from the corpus.
    const std::string nombre = DriverDisplayName(id);
    if (!nombre.empty() && nombre != id) {
        r.resuelto = true;
        const double ficha = RookieProfileTalentCloned(SemillaDeGenerado(id));
        if (ficha > 0.0) { r.talento = ficha; r.fuente = Fuente::Clonada; }
        else             { r.talento = 0.0;   r.fuente = Fuente::Curva; }
        return r;
    }
    return r;   // unresolved: the row does not reach the grid
}

struct FotoFichas {
    int temporada = 0;
    int series = 0, filas = 0;
    int autorada = 0, clonada = 0, curva = 0;
    int nFilas[8] = {0}, nAut[8] = {0}, nClon[8] = {0}, nCurva[8] = {0};   // per series level 1..7
    int seriesNivel[8] = {0};
    int asCurva = 0, medianaCurva = 0, ultimoCurva = 0;         // the anchor is a CURVE row
    int asClonada = 0, medianaClonada = 0, ultimoClonada = 0;   // ...and when it is a person, authored or cloned?
    int asAutorada = 0, medianaAutorada = 0, ultimoAutorada = 0;
    int asCurvaNivel[8] = {0};
    int sinNingunaFicha = 0;
    int desajustes = 0, validadas = 0;      // the validation of the method
    int sinResolver = 0;                    // rows whose occupant matches NO step of the cascade
    std::vector<double> huecos;             // gap of the curve ace over the best card of its grid
    double peorHueco = 0.0;
    std::string peorClase, peorAs, peorFicha;
    std::vector<std::string> sinFichaClases;   // grids with NOT A SINGLE card, by name
    std::map<std::string, int> curvaPorEscalon;   // which step the rows still without a card come from
    // THE SECOND VALIDATION, AND IT GOES THE OTHER WAY. The one on mismatches checks that the rows I
    // classified WITH a card really carry that number; it says nothing about those I classified as CURVE. This one does:
    // a card belongs to the PERSON and does not change from grid to grid; a curve point belongs to the SLOT and
    // changes with the car. So, of the people who race in 2+ grids, those with a card must come out
    // stable and those from the curve must not. If it came out the other way round, my classification would be backwards.
    // The CLONED one is the most demanding of the three: it comes from the id and nothing else, so it must come out stable
    // at 100 %. A single unstable one would reveal that what I am calling "cloned" is not.
    int multiAut = 0, multiAutInestable = 0;
    int multiClon = 0, multiClonInestable = 0;
    int multiCurva = 0, multiCurvaInestable = 0;
};

static FotoFichas MedirFichas(const SaveData& save, int temporada) {
    FotoFichas f; f.temporada = temporada;
    std::map<std::string, std::pair<Fuente, std::vector<double>>> porPersona;   // the 2nd validation
    for (const auto& sd : AllSeries()) {
        if (IsEraMemorySeries(sd)) continue;                 // frozen: does not take part in the live world
        const std::vector<SeatRow> asientos = SeatRowsForSeries(save, sd.id);
        if (asientos.size() < 8) continue;
        // The PRODUCTION GATE: the same helper the three real XML writers call. The grid
        // size comes from the SEATS, just like production.
        const std::vector<GridDriver> grid = ComposeSeasonGridForSave(save, sd.id, (int)asientos.size());
        if (grid.size() < 8) continue;
        const IxFichas ix = IndiceDeSerie(sd.id);
        const int niv = (sd.level >= 1 && sd.level <= 7) ? sd.level : 1;
        f.series++; f.seriesNivel[niv]++;

        struct Fila { double authored; Fuente fuente; std::string nombre; };
        std::vector<Fila> filas;
        double mejorFicha = -1.0; std::string mejorFichaNombre;
        for (const auto& d : grid) {
            const FichaDe fd = FichaDeLaPersona(d.driver_id, ix);
            if (!fd.resuelto) f.sinResolver++;
            filas.push_back({ d.authored_talent, fd.fuente, d.name });
            f.filas++; f.nFilas[niv]++;
            if (fd.fuente == Fuente::Autorada)      { f.autorada++; f.nAut[niv]++; }
            else if (fd.fuente == Fuente::Clonada)  { f.clonada++;  f.nClon[niv]++; }
            else                                    { f.curva++;    f.nCurva[niv]++;
                // WHICH ROWS STILL HAVE NO CARD, by cascade step. It is what the exit criterion asks to
                // state if it is not met: the number is not enough, one must know where they get in.
                const std::string& id = d.driver_id;
                const char* esc = !fd.resuelto                        ? "0-sin resolver"
                                : ix.pinned.count(id)                 ? "1-pinneado"
                                : ix.field.count(id)                  ? "2-field"
                                : DriverById(id)                      ? "3-pool"
                                : ix.cast.count(id)                   ? "4-cohorte"
                                : PackDriverById(id)                  ? "5-pack"
                                                                      : "6-generado";
                f.curvaPorEscalon[esc]++;
            }
            // THE VALIDATION: production writes `authored_talent = p.talent` when there is a card. If the copy of
            // the cascade had drifted, a mismatch would show up here.
            // 18/08 (Task 3) — and for a CLONE, production writes `card x GrowthProgress(age)`: the copy
            // has to do the same math or the column stops validating the method and starts measuring the
            // multiplier. Without this it flagged 1000 mismatches out of 1903 at T20, which were not a deviation of
            // the cascade but the instrument reading a scale production no longer uses.
            // 19/08 — and they are BOTH halves: `GrowthProgress` (rise) x `AgeDeclinePart` (what age
            // takes away past 32, ). With only one, this column would again flag a mismatch on
            // every cloned veteran -- and again it would not be the cascade, it would be the instrument.
            if (fd.fuente != Fuente::Curva) {
                f.validadas++;
                double esperado = fd.talento;
                if (fd.fuente == Fuente::Clonada) {
                    const auto by = save.birth_year.find(d.driver_id);
                    if (by != save.birth_year.end()) {
                        const int edad = save.current_world_year - by->second;
                        esperado *= GrowthProgress(save.driver_curve, d.driver_id, edad, 0)
                                  * AgeDeclinePart(edad, 0);
                    }
                }
                if (std::fabs(esperado - d.authored_talent) > 1e-9) f.desajustes++;
                if (fd.talento > mejorFicha) { mejorFicha = fd.talento; mejorFichaNombre = d.name; }
            }
            if (!d.driver_id.empty()) {
                auto& e = porPersona[d.driver_id];
                e.first = fd.fuente;
                e.second.push_back(d.authored_talent);
            }
        }
        if (filas.empty()) continue;
        if (mejorFicha < 0.0) { f.sinNingunaFicha++; f.sinFichaClases.push_back(sd.class_name); }

        // The three anchors, by value of `authored_talent` (which is what the conversion reads).
        std::vector<double> vals; vals.reserve(filas.size());
        for (const auto& r : filas) vals.push_back(r.authored);
        std::sort(vals.begin(), vals.end());
        const double vAs = vals.back(), vUlt = vals.front(), vMed = vals[vals.size() / 2];
        // TIES: the anchor is counted as a PERSON if any of the tied rows is one (conservative
        // reading: it counts FEWER curve anchors than there are). Authored beats cloned.
        auto fuenteDe = [&](double v) {
            bool aut = false, clon = false;
            for (const auto& r : filas) if (std::fabs(r.authored - v) <= 1e-12) {
                if (r.fuente == Fuente::Autorada) aut = true;
                else if (r.fuente == Fuente::Clonada) clon = true;
            }
            return aut ? Fuente::Autorada : (clon ? Fuente::Clonada : Fuente::Curva);
        };
        const Fuente fAs = fuenteDe(vAs), fMed = fuenteDe(vMed), fUlt = fuenteDe(vUlt);
        if (fAs == Fuente::Curva) { f.asCurva++; f.asCurvaNivel[niv]++; } else if (fAs == Fuente::Clonada) f.asClonada++; else f.asAutorada++;
        if (fMed == Fuente::Curva) f.medianaCurva++; else if (fMed == Fuente::Clonada) f.medianaClonada++; else f.medianaAutorada++;
        if (fUlt == Fuente::Curva) f.ultimoCurva++; else if (fUlt == Fuente::Clonada) f.ultimoClonada++; else f.ultimoAutorada++;

        // (3) THE ACE'S GAP when the curve sets it: how far above the best PERSON of that
        // same grid it goes. With no card at all the gap is not defined and the grid is excluded.
        if (fAs == Fuente::Curva && mejorFicha >= 0.0) {
            const double hueco = vAs - mejorFicha;
            f.huecos.push_back(hueco);
            if (hueco > f.peorHueco) {
                f.peorHueco = hueco; f.peorClase = sd.class_name; f.peorFicha = mejorFichaNombre;
                for (const auto& r : filas) if (std::fabs(r.authored - vAs) <= 1e-12 && r.fuente == Fuente::Curva) { f.peorAs = r.nombre; break; }
            }
        }
    }
    // The 2nd validation, now with all the milestone's grids seen.
    for (const auto& kv : porPersona) {
        if (kv.second.second.size() < 2) continue;
        bool inestable = false;
        for (size_t i = 1; i < kv.second.second.size(); i++)
            if (std::fabs(kv.second.second[i] - kv.second.second[0]) > 1e-9) { inestable = true; break; }
        if (kv.second.first == Fuente::Curva)         { f.multiCurva++; if (inestable) f.multiCurvaInestable++; }
        else if (kv.second.first == Fuente::Clonada)  { f.multiClon++;  if (inestable) f.multiClonInestable++; }
        else                                          { f.multiAut++;   if (inestable) f.multiAutInestable++; }
    }
    return f;
}

// ===================================================================================================
// THE CORPUS SPREAD AGAINST WHAT THE GRID DELIVERS (18/08, Task 3)
// ===================================================================================================
//
// The yardstick measure says that at T20 the grid delivers 0.6x of the yardstick and not the 0.77 from before the clone,
// and that aging the clone recovers part but not all. The suspicion, with the coverage data in front (at T20
// 58.9% of rows are CLONED), is that what is missing is no longer "the clone enters at its ceiling" but WHERE
// ITS NUMBER COMES FROM: if the card corpus is narrow, or if the draw does not reach its extremes, a
// mostly cloned grid cannot be wider than what that draw allows -- however well each one
// is aged.
//
// This measures it instead of assuming it, and separates the three questions:
//   · the whole CORPUS, which is the theoretical ceiling of what a clone can yield;
//   · what the draw ACTUALLY reaches (`RookiePercentile` confines each one to the bracket of its
//     archetype, so the available corpus and the used corpus need not measure the same);
//   · and within each grid, the spread put by the CLONED rows against that put by the AUTHORED ones.
//     If the first is systematically narrower, there is what is missing, and with a number.
struct FotoCorpus {
    int series = 0, filasClon = 0, filasAut = 0;
    double corpusN = 0, corpusMin = 0, corpusP10 = 0, corpusP50 = 0, corpusP90 = 0, corpusMax = 0;
    double usadoMin = 0, usadoP10 = 0, usadoP50 = 0, usadoP90 = 0, usadoMax = 0;
    double spanClonP50 = 0, spanAutP50 = 0, spanTotalP50 = 0, varaP50 = 0;
    int clasesMixtas = 0;                    // classes with >=3 cloned AND >=3 authored (the comparable ones)
    double spanClonMixtaP50 = 0, spanAutMixtaP50 = 0;
};

static double PctlOrdenado(std::vector<double>& v, double p) {
    if (v.empty()) return 0.0;
    std::sort(v.begin(), v.end());
    const double i = p * (double)(v.size() - 1);
    const size_t lo = (size_t)i, hi = lo + 1 < v.size() ? lo + 1 : lo;
    return v[lo] + (i - (double)lo) * (v[hi] - v[lo]);
}

static FotoCorpus MedirCorpusContraParrilla(const SaveData& save) {
    FotoCorpus f;
    {   // 1) the whole corpus, just as `RookieProfileTalentCloned` reads it
        std::vector<double> c = ProfileTalentCorpus();
        f.corpusN = (double)c.size();
        if (!c.empty()) {
            f.corpusMin = c.front(); f.corpusMax = c.back();
            f.corpusP10 = PctlOrdenado(c, 0.10);
            f.corpusP50 = PctlOrdenado(c, 0.50);
            f.corpusP90 = PctlOrdenado(c, 0.90);
        }
    }
    std::vector<double> usado, spanClon, spanAut, spanTotal, varas, spanClonMix, spanAutMix;
    for (const auto& sd : AllSeries()) {
        if (IsEraMemorySeries(sd)) continue;
        const std::vector<SeatRow> asientos = SeatRowsForSeries(save, sd.id);
        if (asientos.size() < 8) continue;
        // The SAME composition as `MedirVara`, so the two numbers can be put side by side.
        const std::vector<GridDriver> grid = ComposeSeasonGrid(
            sd.id, sd.level, /*playerForm=*/0.0, (int)asientos.size(), /*useHomage=*/false,
            save.rival_form, /*exclude=*/nullptr, &save.driver_ratings,
            ClassRole::SingleClass, &asientos, /*skipLiveries=*/nullptr, &save.driver_races,
            &save.driver_curve, &save.birth_year, save.current_world_year);
        if (grid.size() < 8) continue;
        const IxFichas ix = IndiceDeSerie(sd.id);
        double cLo = 2.0, cHi = -2.0, aLo = 2.0, aHi = -2.0, tLo = 2.0, tHi = -2.0;
        int nClon = 0, nAut = 0;
        for (const auto& d : grid) {
            if (d.talent < tLo) tLo = d.talent;
            if (d.talent > tHi) tHi = d.talent;
            const FichaDe fd = FichaDeLaPersona(d.driver_id, ix);
            if (fd.fuente == Fuente::Clonada) {
                nClon++; usado.push_back(fd.talento);          // the RAW drawn card, without the progress
                if (d.authored_talent < cLo) cLo = d.authored_talent;
                if (d.authored_talent > cHi) cHi = d.authored_talent;
            } else if (fd.fuente == Fuente::Autorada) {
                nAut++;
                if (d.authored_talent < aLo) aLo = d.authored_talent;
                if (d.authored_talent > aHi) aHi = d.authored_talent;
            }
        }
        f.series++; f.filasClon += nClon; f.filasAut += nAut;
        if (tHi > tLo) { spanTotal.push_back(tHi - tLo); varas.push_back(TalentRefSpanFor(sd.class_name, sd.level)); }
        if (nClon >= 2 && cHi > cLo) spanClon.push_back(cHi - cLo);
        if (nAut  >= 2 && aHi > aLo) spanAut.push_back(aHi - aLo);
        // The CLEAN comparison: only the classes where both provenances coexist with enough sample.
        // Comparing the spread of an all-cloned grid with that of an all-authored one would mix
        // provenance with class, which are two different variables.
        if (nClon >= 3 && nAut >= 3 && cHi > cLo && aHi > aLo) {
            f.clasesMixtas++;
            spanClonMix.push_back(cHi - cLo);
            spanAutMix.push_back(aHi - aLo);
        }
    }
    if (!usado.empty()) {
        std::sort(usado.begin(), usado.end());
        f.usadoMin = usado.front(); f.usadoMax = usado.back();
        f.usadoP10 = PctlOrdenado(usado, 0.10);
        f.usadoP50 = PctlOrdenado(usado, 0.50);
        f.usadoP90 = PctlOrdenado(usado, 0.90);
    }
    f.spanClonP50      = PctlOrdenado(spanClon,   0.50);
    f.spanAutP50       = PctlOrdenado(spanAut,    0.50);
    f.spanTotalP50     = PctlOrdenado(spanTotal,  0.50);
    f.varaP50          = PctlOrdenado(varas,      0.50);
    f.spanClonMixtaP50 = PctlOrdenado(spanClonMix, 0.50);
    f.spanAutMixtaP50  = PctlOrdenado(spanAutMix,  0.50);
    return f;
}

static Foto Medir(const SaveData& save, int temporada, const std::map<std::string,int>& tierPrevio,
                  std::map<std::string,int>& tierAhora) {
    Foto f; f.temporada = temporada;
    std::set<std::string> cohorteIds;
    for (int t = 1; t <= 7; t++) for (const auto& rd : RosterForTier(t)) if (!rd.id.empty()) cohorteIds.insert(rd.id);

    std::vector<double> porTierVal[8];
    std::vector<double> anchosIntra;                            // p90-p10 of the ELO WITHIN each series
    std::set<std::string> vistos;
    double peorD1 = 0, peorD2 = 0;
    for (const auto& sd : AllSeries()) {
        if (IsEraMemorySeries(sd)) continue;                    // frozen: does not take part in the live world
        const int tier = (sd.level >= 1 && sd.level <= 7) ? sd.level : 1;
        std::vector<double> deLaSerie;                          // the guard: how much the ELO separates in here
        for (const auto& a : SeatsForClass(sd.id, save))
            if (!a.occupant_id.empty()) {
                const double vv = ValorDe(save, a.occupant_id);
                if (vv > 0.0) deLaSerie.push_back(vv);
            }
        double corteCola = -1.0;      // the first quartile of THIS series' ELO
        double cortePunta = -1.0;     // ...and the third
        if (deLaSerie.size() >= 8) {
            std::sort(deLaSerie.begin(), deLaSerie.end());
            anchosIntra.push_back(deLaSerie[(deLaSerie.size() * 9) / 10] - deLaSerie[deLaSerie.size() / 10]);
            corteCola = deLaSerie[deLaSerie.size() / 4];
            cortePunta = deLaSerie[(deLaSerie.size() * 3) / 4];   // the FRONT quarter
        }
        for (const auto& a : SeatsForClass(sd.id, save)) {
            f.asientos++;
            if (a.occupant_id.empty()) { f.libres++; continue; }
            f.ocupados++;
            if (!vistos.insert(a.occupant_id).second) continue;  // a person is counted once
            f.ocupantes++;
            if (a.occupant_id.rfind("fl_", 0) == 0 || a.occupant_id.rfind("gn_", 0) == 0) f.generados++;
            else if (cohorteIds.count(a.occupant_id)) f.cohorte++;
            else f.reales++;

            const double v = ValorDe(save, a.occupant_id);
            if (v <= 0.0) { f.sinValor++; continue; }
            porTierVal[tier].push_back(v);
            f.porTier[tier]++;
            tierAhora[a.occupant_id] = tier;

            const int suyo = NivelDelValor(v);
            if (suyo - tier >= 2) { f.arribaDeSuSitio++;
                if (cortePunta > 0.0 && v >= cortePunta) f.arribaQueSonLaPunta++;
                if (a.occupant_id.rfind("fl_", 0) == 0 || a.occupant_id.rfind("gn_", 0) == 0) f.arribaGenerado++;
                else if (cohorteIds.count(a.occupant_id)) f.arribaCohorte++;
                else f.arribaReal++;
                if (a.occupant_id.rfind("gn_", 0) == 0 || a.occupant_id.rfind("fl_", 0) == 0) {
                    const auto gd = save.gen_drivers.find(a.occupant_id);
                    if (gd != save.gen_drivers.end() && gd->second.tier_max <= tier) f.arribaGenTechoTocado++;
                }
                if (suyo - tier > peorD1) { peorD1 = suyo - tier; f.peorArriba = a.occupant_id + " (t" + std::to_string(tier) + ", vale t" + std::to_string(suyo) + ")"; } }
            if (tier - suyo >= 2) { f.abajoDeSuSitio++;
                if (corteCola > 0.0 && v <= corteCola) f.abajoQueSonLaCola++;   // is the tail of their field
                if (tier - suyo > peorD2) { peorD2 = tier - suyo; f.peorAbajo = a.occupant_id + " (t" + std::to_string(tier) + ", vale t" + std::to_string(suyo) + ")"; } }

            const auto pv = tierPrevio.find(a.occupant_id);
            if (pv != tierPrevio.end() && pv->second != tier) f.movidos++;
        }
    }
    for (int t = 1; t <= 7; t++) {
        auto& v = porTierVal[t];
        if (v.empty()) continue;
        std::sort(v.begin(), v.end());
        f.p10[t] = v[v.size() / 10];
        f.p50[t] = v[v.size() / 2];
        f.p90[t] = v[(v.size() * 9) / 10];
    }
    if (!anchosIntra.empty()) {
        std::sort(anchosIntra.begin(), anchosIntra.end());
        f.anchoIntraP50 = anchosIntra[anchosIntra.size() / 2];
    }
    return f;
}

// ===================================================================================================
// THE MOVEMENTS REPORT — WHO MOVES UP, WHO MOVES DOWN AND WHO LEAVES (13/08)
// ===================================================================================================
//
// The five measures of say the SHAPE of the world, but do not answer the question anyone asks
// looking at a grid: "and who drops out of F1 this year?". This answers it with names.
//
// It is obtained by DIFFING the world before and after each season, not by reading the rollover report. That is on
// purpose: the report counts what each mechanism BELIEVES it did (`promotions`, `retirements`...), and here
// what is needed is what really ended up happening, adding up all the causes — the one who drops for not renewing, the one who
// drops dragged by the cascade, the one who falls because another took their place. Asking the result cannot
// get out of sync with the mechanisms.
struct Asiento1 { std::string serie; int tier = 0; };

// Who occupies each series, series by series. IT IS NEEDED APART FROM `DondeEstaCadaUno`, and the first version
// of this diagnostic did not have it: there each person appears only by their HIGHEST seat, so someone with a
// seat in several series (there are 346, one with twelve) appeared as a "new face" in all the others without ever having
// moved. With that I published that Alonso entered four series and Schumacher three — and Schumacher is
// from '69: in 2025 he signs for nobody, he was in the PERIOD grids from the start.
static std::map<std::string, std::set<std::string>> QuienOcupaCadaSerie(const SaveData& save) {
    std::map<std::string, std::set<std::string>> out;
    for (const auto& sd : AllSeries()) {
        if (IsEraMemorySeries(sd)) continue;
        for (const auto& a : SeatsForClass(sd.id, save)) {
            if (a.open || a.occupant_id.empty()) continue;
            if (save.retired.count(a.occupant_id)) continue;
            out[sd.id].insert(a.occupant_id);
        }
    }
    return out;
}

// Where each one is: their HIGHEST seat, which is the one that defines their category (346 have several).
static std::map<std::string, Asiento1> DondeEstaCadaUno(const SaveData& save) {
    std::map<std::string, Asiento1> out;
    for (const auto& sd : AllSeries()) {
        if (IsEraMemorySeries(sd)) continue;
        const int tier = (sd.level >= 1 && sd.level <= 7) ? sd.level : 1;
        for (const auto& a : SeatsForClass(sd.id, save)) {
            if (a.open || a.occupant_id.empty()) continue;
            if (save.retired.count(a.occupant_id)) continue;
            auto it = out.find(a.occupant_id);
            if (it == out.end() || tier > it->second.tier) out[a.occupant_id] = Asiento1{ sd.id, tier };
        }
    }
    return out;
}

struct Movimientos {
    int suben = 0, bajan = 0, entran = 0, salen = 0;
    int subenCohorte = 0, subenGenerados = 0, subenReales = 0;
    int bajanCohorte = 0, bajanGenerados = 0, bajanReales = 0;
};

static const char* NombreDe(const std::string& id) {
    const PoolDriver* pd = DriverById(id);
    return (pd && !pd->name.empty()) ? pd->name.c_str() : id.c_str();
}

static std::string Linea(const Foto& f) {
    char b[512];
    snprintf(b, sizeof(b),
             "T%-3d  asientos %4d (%4d ocupados, %3d libres)  personas %4d  [real %4d cohorte %3d generados %4d]"
             "  descolocados %3d arriba / %3d abajo (%3d son la cola de su campo)  movidos %4d"
             "  ancho ELO intra-serie %4.0f\n",
             f.temporada, f.asientos, f.ocupados, f.libres, f.ocupantes, f.reales, f.cohorte, f.generados,
             f.arribaDeSuSitio, f.abajoDeSuSitio, f.abajoQueSonLaCola, f.movidos, f.anchoIntraP50);
    char b2[256];
    snprintf(b2, sizeof(b2),
             "       de los ARRIBA: %3d son la punta de su campo  ·  real %3d  ·  cohorte %3d  ·  GENERADO %3d (de esos, con el TECHO tocado %3d)\n",
             f.arribaQueSonLaPunta, f.arribaReal, f.arribaCohorte, f.arribaGenerado, f.arribaGenTechoTocado);
    return std::string(b) + b2;
}

// ===================================================================================================
// — IS THERE A SIGNAL FOR THE TEAM BAND? (census, 12/08)
// ===================================================================================================
//
// decides that the budget is SERIES SCALE x TEAM BAND, and takes for granted that the band is "in
// ferred by an AI" from three signals that "are already in the data": allies degree, real pack team versus
// generic label, and the previous year's results. Before building on top of it the measurement has to be
// COVERAGE, because a signal that only reaches a handful of teams does not distribute a world of a thousand-odd.
//
// And the question that really decides the design is not how many teams a signal reaches, but whether it separates
// the teams WITHIN A SINGLE SERIES. The series scale already tells F1 from karting; the band only
// serves to say who is rich in THAT paddock. If within a series all teams are identical for
// all signals, the band cannot be DERIVED and has to come from a file — which is another design
// decision, and it has to be taken with the number in front of you instead of discovering it after writing it.
struct FotoEquipos {
    int temporada = 0;
    int asientos = 0;
    int pares = 0;              // distinct (series, team): the grain at which a band would be requested
    int equipos = 0;            // distinct team labels across the whole world
    int equiposReales = 0;      // label that appears among the REAL teams of its class
    int conAliados = 0;         // teams with at least one family/ally edge
    int asientosConAliados = 0; // seats whose team has edges (the weight of the signal where it matters)
    int multiSerie = 0;         // teams present in more than one series
    int seriesMax = 0;          // the one in the most series
    int cochesP50 = 0, cochesMax = 0;   // cars per (series, team)
    std::string ejemploGordo;   // the (series, team) with the most cars: tells whether it is a team or an artifact
    // The deciding measure: in how many live series some signal separates two teams.
    int seriesVivas = 0, sepAliados = 0, sepReal = 0, sepCoches = 0, sepAlguna = 0;
    std::string ejemploPlano;   // a series with several teams in which NO signal separates them
    // THE WEIGHT, which is what really decides: not how many SERIES are left without a signal, but how many
    // SEATS. Thirty one-seat series do not matter; thirty series with half a grid in them do.
    int asientosSinSenal = 0;
    int seriesMonomarca = 0;    // all its seats belong to the same "team" (a school, not a paddock)
    // Reconciliation: it cites "1,491 teams and 2,020 pairs". That count includes the PERIOD MEMORY series,
    // which are frozen and have no market. Both are counted so that the spec's number
    // can be reconciled instead of silently contradicting it.
    int equiposTodo = 0, paresTodo = 0;
};

static FotoEquipos MedirEquipos(const SaveData& save, int temporada) {
    FotoEquipos f; f.temporada = temporada;
    std::set<std::string> equipos, pares, realesVistos, conAli, equiposTodo, paresTodo;
    std::map<std::string, std::set<std::string>> seriesDe;   // team -> series it appears in
    std::vector<int> coches;
    int gordo = 0;

    for (const auto& sd : AllSeries()) {
        // The "all" count includes the period memory, which is what matches the spec's number.
        for (const auto& a : SeatsForClass(sd.id, save)) {
            if (a.team_label.empty()) continue;
            equiposTodo.insert(a.team_label);
            paresTodo.insert(sd.id + "|" + a.team_label);
        }
        if (IsEraMemorySeries(sd)) continue;
        f.seriesVivas++;
        const std::vector<std::string> realesClase = TeamLabelsForClass(sd.class_name);
        const std::set<std::string> reales(realesClase.begin(), realesClase.end());
        std::map<std::string, int> cochesDe;                 // team -> cars IN THIS series
        std::set<int> valAli; std::set<bool> valReal;        // distinct values each signal takes here
        for (const auto& a : SeatsForClass(sd.id, save)) {
            if (a.team_label.empty()) continue;
            f.asientos++;
            equipos.insert(a.team_label);
            pares.insert(sd.id + "|" + a.team_label);
            seriesDe[a.team_label].insert(sd.id);
            cochesDe[a.team_label]++;
            const int grado = TeamAllyDegree(a.team_label);
            if (grado > 0) { conAli.insert(a.team_label); f.asientosConAliados++; }
            if (reales.count(a.team_label)) realesVistos.insert(a.team_label);
            valAli.insert(grado);
            valReal.insert(reales.count(a.team_label) != 0);
        }
        std::set<int> valCoches;
        for (const auto& kv : cochesDe) {
            coches.push_back(kv.second); valCoches.insert(kv.second);
            if (kv.second > gordo) { gordo = kv.second; f.ejemploGordo = sd.id + " / " + kv.first; }
        }
        const bool sA = valAli.size() > 1, sR = valReal.size() > 1, sC = valCoches.size() > 1;
        if (sA) f.sepAliados++;
        if (sR) f.sepReal++;
        if (sC) f.sepCoches++;
        if (cochesDe.size() <= 1) f.seriesMonomarca++;   // a single "team": there is no paddock to distribute
        if (sA || sR || sC) f.sepAlguna++;
        else {
            for (const auto& kv : cochesDe) f.asientosSinSenal += kv.second;
            if (f.ejemploPlano.empty() && cochesDe.size() > 1) f.ejemploPlano = sd.id;
        }
    }
    f.equipos = (int)equipos.size();
    f.pares = (int)pares.size();
    f.equiposReales = (int)realesVistos.size();
    f.conAliados = (int)conAli.size();
    f.equiposTodo = (int)equiposTodo.size();
    f.paresTodo = (int)paresTodo.size();
    for (const auto& kv : seriesDe) {
        if (kv.second.size() > 1) f.multiSerie++;
        if ((int)kv.second.size() > f.seriesMax) f.seriesMax = (int)kv.second.size();
    }
    if (!coches.empty()) {
        std::sort(coches.begin(), coches.end());
        f.cochesP50 = coches[coches.size() / 2];
        f.cochesMax = coches.back();
    }
    return f;
}

static std::string LineaEquipos(const FotoEquipos& f) {
    char b[900];
    snprintf(b, sizeof(b),
             "T%-3d  asientos %4d  equipos %4d  pares (serie,equipo) %4d  coches por entrada p50 %d / max %d\n"
             "      (con la memoria de epoca incluida: %4d equipos, %4d pares — asi cuadra el «1.491» del spec)\n"
             "      la entrada mas gorda: %s\n"
             "      con aristas de aliado %3d equipos (%4d asientos, %4.1f%%)  ·  etiqueta de equipo REAL %4d\n"
             "      en mas de una serie %3d equipos (max %d series)\n"
             "      SEPARA DENTRO DE LA SERIE: aliados %3d · real/generica %3d · nº de coches %3d"
             "  ·  alguna %3d de %d series\n"
             "      ★sin ninguna señal: %d series, %d asientos (%4.1f%% del mundo)  ·  monomarca %d series\n",
             f.temporada, f.asientos, f.equipos, f.pares, f.cochesP50, f.cochesMax,
             f.equiposTodo, f.paresTodo,
             f.ejemploGordo.empty() ? "ninguna" : f.ejemploGordo.c_str(),
             f.conAliados, f.asientosConAliados,
             f.asientos ? 100.0 * f.asientosConAliados / f.asientos : 0.0, f.equiposReales,
             f.multiSerie, f.seriesMax,
             f.sepAliados, f.sepReal, f.sepCoches, f.sepAlguna, f.seriesVivas,
             f.seriesVivas - f.sepAlguna, f.asientosSinSenal,
             f.asientos ? 100.0 * f.asientosSinSenal / f.asientos : 0.0, f.seriesMonomarca);
    return b;
}

// ===================================================================================================
// — HOW MUCH ROOM IS THERE TO GROW?
// ===================================================================================================
//
// Before replacing the universal ramp with five shapes we need to know whether they have anywhere to show. Today
// `AgeCurveMultiplier` gives EVERYONE the same: ×0.82 at 18 rising to ×1.00 at 27, plateau until
// 32, decline afterwards. That 18% is ~270 rating points, close to a whole ladder level.
//
// Three things decide whether the new model can shine:
//   · how many people are IN THE RISING PHASE at a given moment (if it is four, it does not matter how nice the curve is)
//   · how much age separates TODAY two people of the same raw value (the gap the shapes will distribute)
//   · whether people live long enough in the world for one shape to be told apart from another
struct FotoEdad {
    int temporada = 0;
    int conEdad = 0, sinEdad = 0;
    int subiendo = 0, meseta = 0, declive = 0;   // <27 · 27-32 · >32
    // The 55 is an ABSURDITY CAP, not a criterion: a driver leaves the seat when they no longer make the level, not
    // for having birthdays (Phase 0c, and the user reaffirms it on 12/08 — "age is not a reason by itself"). The
    // engine's own comment says it should almost never fire, so it is COUNTED: if it fires
    // a lot, it means the cascade of drops is not doing its job and the cap is covering for it.
    int cerca50 = 0, pasados55 = 0;
    // THE REAL QUESTION: not how many are older, but how many the engine WOULD say should be retired and
    // are still there. Each one's threshold is 55 + their class's ceiling - 40 + their dispersion, so a driver
    // of endurance at 58 can be perfectly legitimate and a school one at 45 cannot.
    int diriaRetirar = 0;
    double multMin = 9.9, multMax = 0.0, multP50 = 0.0;
    double edadP50 = 0.0;
};

static FotoEdad MedirEdad(const SaveData& save, int temporada, int anioMundo) {
    FotoEdad f; f.temporada = temporada;
    // The world census with the age_shift of its class set: it is EXACTLY what the rollover passes to
    // `ShouldRetire`, so asking it here answers for the real world and not an approximation.
    for (auto r : WorldOccupants(save)) {
        const auto by = save.birth_year.find(r.id);
        if (by != save.birth_year.end() && by->second) r.birth_year = by->second;
        if (save.retired.count(r.id)) continue;
        if (ShouldRetire(r, anioMundo, 0.0)) f.diriaRetirar++;
    }
    std::vector<double> mults, edades;
    std::set<std::string> vistos;
    for (const auto& sd : AllSeries()) {
        if (IsEraMemorySeries(sd)) continue;
        for (const auto& a : SeatsForClass(sd.id, save)) {
            if (a.occupant_id.empty() || !vistos.insert(a.occupant_id).second) continue;
            // THE SAVE RULES OVER THE POOL, and getting this wrong falsifies the whole measure: `BirthYearFor` only
            // looks at the pool, but the age of generated drivers is written in `save.birth_year` (the canonical map).
            // Measuring only the pool, every newcomer looked "ageless" and the world came out geriatric.
            int by = 0;
            const auto itB = save.birth_year.find(a.occupant_id);
            if (itB != save.birth_year.end() && itB->second) by = itB->second;
            else by = BirthYearFor(a.occupant_id);
            if (by <= 0) { f.sinEdad++; continue; }
            f.conEdad++;
            const int edad = DriverAge(by, anioMundo);
            if (edad < bal::AGE_PEAK_LO)      f.subiendo++;
            else if (edad <= bal::AGE_PEAK_HI) f.meseta++;
            else                               f.declive++;
            if (edad >= 50) f.cerca50++;
            if (edad >= bal::RETIRE_AGE_HARD) f.pasados55++;
            const double m = AgeCurveMultiplier(edad, 0);
            mults.push_back(m); edades.push_back(edad);
            if (m < f.multMin) f.multMin = m;
            if (m > f.multMax) f.multMax = m;
        }
    }
    if (!mults.empty()) {
        std::sort(mults.begin(), mults.end()); std::sort(edades.begin(), edades.end());
        f.multP50 = mults[mults.size() / 2];
        f.edadP50 = edades[edades.size() / 2];
    } else { f.multMin = 0.0; }
    return f;
}

static std::string LineaEdad(const FotoEdad& f) {
    char b[400];
    const int n = f.subiendo + f.meseta + f.declive;
    snprintf(b, sizeof(b),
             "T%-3d  con edad %4d (sin edad %4d)  ·  subiendo %4d (%2.0f%%)  meseta %4d  declive %4d"
             "  ·  edad p50 %2.0f  ·  50+ %3d  55+ %3d  ·  DIRIA RETIRAR %3d  ·  mult %.2f-%.2f (p50 %.2f)\n",
             f.temporada, f.conEdad, f.sinEdad, f.subiendo, n ? 100.0 * f.subiendo / n : 0.0,
             f.meseta, f.declive, f.edadP50, f.cerca50, f.pasados55, f.diriaRetirar,
             f.multMin, f.multMax, f.multP50);
    return b;
}

}   // namespace worldlab

// ~~~16/09: the seed `--world` runs with (flag `--semilla N`). 0 = the usual one, so previous
//  measurements keep coming out the same without passing anything.
static unsigned long g_worldSeed = 0;

static int dump_world(const char* outPath) {
    using namespace career;
    using namespace worldlab;
    if (!canon_load_prod()) { printf("WORLD FAIL: no se pudieron cargar los datos\n"); return 1; }
    // ~~~02/09 — THE REGISTRY, FROM THE START. (23/09: the "in production it is loaded by canon::Load()" was
    //  FALSE: nobody loaded it in the game until LoadSeasonData did so on 23/09, .) Here nobody
    //  loaded it, so the RESERVE pool was empty during the twenty seasons and the measure
    //  said "it is never used" when what happened was that it did not exist.
    registry::Load();
    // 23/09: ZTA_WORLD_NO_REGISTRY=1 reproduces the GAME from before 23/09, which did not load the registry
    // (reserve of the empty in game). Only to measure what changes by loading it; by default it does nothing.
    if (const char* nr = std::getenv("ZTA_WORLD_NO_REGISTRY")) if (nr[0] == '1') registry::Clear();

    SaveData save;
    // ~~~16/09 — THE RACE SEED, BY ARGUMENT. The dump ALWAYS ran with seed 0, so
    //  each measure was ONE sample and there was no way to separate a signal from the draw of THAT world. From
    //  `career_seed` hang the rookie's talent lottery, their name and their country, and the world's season
    //  (`RunWorldSeason`): changing it gives another world with the SAME data, which is exactly what is needed to
    //  say "mean and range" instead of a single number.
    save.career_seed = g_worldSeed;
    SeedAllDrivers(save.driver_ratings);
    CareerCalendar cc; cc.year = kStartYear; cc.cursor_doy = 1;
    CareerProgress prog; prog.rating = bal::RATING_PLAYER_SEED;

    char semb[120];
    snprintf(semb, sizeof(semb), "== EL MUNDO A 20 TEMPORADAS (§21.1) — semilla %lu ==\n\n", save.career_seed);
    std::string out = semb;
    // ~~~02/09 — WHERE A ROOKIE'S TALENT COMES FROM, IN NUMBERS. `RookieTalentCloned` samples the
    //  talent corpus of the WHOLE ladder (karting..F1) by the percentile of their archetype. If that
    //  corpus is much higher than the grid they are born into, each batch raises the level-1 median.
    {   const std::vector<double>& c = TalentCorpus();
        char cb[400];
        if (c.size() >= 10)
            snprintf(cb, sizeof(cb),
                     "★CORPUS DE TALENTO (de donde se clona cada novato): n=%d  ·  p10 %.0f  ·  p25 %.0f  ·"
                     "  p37 %.0f  ·  p50 %.0f  ·  p63 %.0f  ·  p90 %.0f\n\n",
                     (int)c.size(), c[c.size()/10], c[c.size()/4], c[(c.size()*37)/100],
                     c[c.size()/2], c[(c.size()*63)/100], c[(c.size()*9)/10]);
        else snprintf(cb, sizeof(cb), "★CORPUS DE TALENTO: insuficiente\n\n");
        out += cb; }
    out += "★El «valor» es HOY el ELO; con §20 sera la media de atributos. Se cambia `ValorDe` y estas\n"
           "  mismas cinco medidas siguen significando lo mismo.\n"
           "★«descolocado ARRIBA» = su valor pertenece a un nivel >=2 por ENCIMA del que corre: merece subir.\n"
           "  «descolocado ABAJO» = corre >=2 niveles por encima de lo que vale: deberia bajar y nadie lo baja.\n"
           "★★12/08 — EL CANAL DE DESCENSO ESTABA CERRADO, y ahora esta a medio abrir. Los que deberian bajar\n"
           "  iban de 13 a 402 en veinte temporadas, y la causa no era el numero de vacantes: la decision de si\n"
           "  sigues (`ExpireSeatContracts`) se tomaba con la capacidad AUTORADA y la curva de edad, sin leer un\n"
           "  solo resultado. La unica forma de decaer era cumplir años. Y no era un olvido -- hasta que el\n"
           "  mundo empezo a correr (`RunWorldSeason`) no habia resultados que leer.\n"
           "  Con los resultados dentro: 402 -> 360 descolocados, menos plazas desiertas (95 -> 73), menos\n"
           "  churn (302 -> 221 movidos) y el ELO deja de abrirse (446 -> 401).\n"
           "★★§20.6 (12/08) — LA CURVA YA ES DE CADA UNO: el arquetipo pone la forma, el techo es de la PERSONA\n"
           "  y la circunstancia dobla el camino sin bajar el techo. Con eso, 360 -> 344.\n"
           "★★★Y AQUI LA CORRECCION QUE IMPORTA MAS QUE LA CIFRA: la mayor parte de ese numero NO era gente mal\n"
           "  colocada, era LA DEFINICION DE LA MEDIDA. «Descolocado» compara con los puntos medios FIJOS del\n"
           "  ladder, pero el ELO se reparte DENTRO de cada serie: con ~400 puntos de ancho intra-serie y los\n"
           "  niveles a ~126, la cola de CUALQUIER parrilla cae dos niveles por pura aritmetica. De los 344,\n"
           "  244 son exactamente eso -- el cuarto de atras de su propio campo. Los mal colocados DE VERDAD,\n"
           "  los que van por detras hasta de su cola, son 100 sobre 1.970 asientos: un 5%, que es justo lo que\n"
           "  §21.1 pide («pocos, y con explicacion»). El 402 que persegui, y el 310 de antes, eran sobre todo\n"
           "  el artefacto. ★Por eso la columna va SIEMPRE al lado del total.\n\n";

    // The QUEEN category is discovered, not hardcoded: the highest level that has a live series. A hand-written id
    // ("f1_2024") would go stale with the first pack.
    int kTierReina = 1;
    for (const auto& sd : AllSeries())
        if (!IsEraMemorySeries(sd) && sd.level > kTierReina && sd.level <= 7) kTierReina = sd.level;
    std::set<std::string> cohorteMundo;
    for (int t = 1; t <= 7; t++) for (const auto& rd : RosterForTier(t)) if (!rd.id.empty()) cohorteMundo.insert(rd.id);
    std::vector<Movimientos> movs;
    std::vector<std::string> caenTrasT1;
    std::string estadoReina;
    std::string bailef1;
    std::string presupuesto;
    std::string nivelf1;
    // THE SPEED OF THE LADDER: when each one appears, where they are born and how far they get.
    struct Trayecto { int nace = 0, tierNace = 0, tierMax = 0, tempMax = 0; };
    std::map<std::string, Trayecto> trayecto;

    std::map<std::string,int> tierPrevio;
    const int kHitos[] = { 0, 1, 2, 5, 10, 20 };
    int siguiente = 0;
    std::vector<Foto> fotos;
    std::vector<FotoEdad> fotosEdad;
    std::vector<FotoVara> varas;
    std::vector<FotoFichas> fichas;      // 18/08: does a PERSON or the car anchor the grid?
    FotoCorpus corpusT20;                // 18/08 (Task 3): is it the CORPUS that narrows the grid?
    // ~~~02/09 — FOLLOWING AN ACE YEAR BY YEAR. Two hypotheses failed by reasoning: look.
    // ~~~02/09 () — the starting snapshot of the young REAL ones: name and their ELO quality at T0.
    std::map<std::string, std::pair<std::string, double> > jovenesT0;
    std::string radioT0;
    std::string aseguido; std::string trazaAs;
    std::string huecosPorHito;     // ~~~16/09 (card 13): empty seats per LEVEL at each milestone
    career::g_trazaRutas = true;   // ~~~02/09: each one's route, to know HOW they arrive
    for (int temporada = 0; temporada <= 20; temporada++) {
        if (temporada == 0) {
            // ~~~02/09 () — the SAME count at T0, which is the world a player sees when starting.
            int cf = 0, mv = 0, jv = 0, vt = 0; double sJ = 0.0, sV = 0.0;
            std::set<std::string> vis0;
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
                for (const auto& st : SeatsForClass(sd.id, save)) {
                    const std::string& id = st.occupant_id;
                    if (st.open || id.empty()) continue;
                    if (id.rfind("gn_",0) == 0 || id.rfind("fl_",0) == 0) continue;
                    if (!vis0.insert(id).second) continue;
                    const AuthoredProfile* ap = AuthoredProfileFor(NombreDe(id));
                    if (!ap || ap->talent <= 0.0) continue;
                    cf++;
                    const auto by = save.birth_year.find(id);
                    int nac = (by != save.birth_year.end()) ? by->second : BirthYearFor(id);
                    if (nac <= 0) continue;
                    const int ed = cc.year - nac;
                    const double pr = GrowthProgress(save.driver_curve, id, ed, 0);
                    const double ca = ap->talent * (1.0 - pr);
                    if (ca <= 0.001) continue;
                    mv++;
                    if (ed < bal::AGE_PEAK_LO) { jv++; sJ += ca; } else { vt++; sV += ca; }
                }
            }
            char t0b[300];
            snprintf(t0b, sizeof(t0b),
                     "\n== §20.6.2 — LO MISMO EN T0 (el mundo con el que empieza un jugador) ==\n"
                     "  con ficha curada %d  ·  les cambiaria %d  ·  JOVENES (<%d) %d con caida media %.3f"
                     "  ·  meseta/declive %d con %.3f\n\n",
                     cf, mv, bal::AGE_PEAK_LO, jv, jv ? sJ / jv : 0.0, vt, vt ? sV / vt : 0.0);
            radioT0 = t0b;
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
                for (const auto& st : SeatsForClass(sd.id, save)) {
                    const std::string& id = st.occupant_id;
                    if (st.open || id.empty()) continue;
                    if (id.rfind("gn_",0) == 0 || id.rfind("fl_",0) == 0) continue;   // REAL
                    const auto by = save.birth_year.find(id);
                    int nac = (by != save.birth_year.end()) ? by->second : BirthYearFor(id);
                    if (nac <= 0) continue;
                    if (cc.year - nac > 22) continue;                                  // young
                    const auto rt = save.driver_ratings.find(id);
                    if (rt == save.driver_ratings.end()) continue;
                    jovenesT0[id] = std::make_pair(NombreDe(id), RatingQuality(rt->second));
                }
            }
        }
        { if (aseguido.empty()) {
              for (const auto& kv : save.gen_drivers)
                  if (bal::RATING_SEED_BOTTOM + kv.second.talent >= 1669.0) { aseguido = kv.first; break; }
          }
          if (!aseguido.empty()) {
              const auto cv = save.driver_curve.find(aseguido);
              const auto rt = save.driver_ratings.find(aseguido);
              const auto by = save.birth_year.find(aseguido);
              char tb[200];
              snprintf(tb, sizeof(tb), "  [traza] T%-2d  curva %.3f  ELO %.0f  edad %d  retirado %d\n",
                       temporada, cv == save.driver_curve.end() ? -1.0 : cv->second,
                       rt == save.driver_ratings.end() ? -1.0 : rt->second,
                       by == save.birth_year.end() ? -1 : cc.year - by->second,
                       (int)save.retired.count(aseguido));
              trazaAs += tb;
          } }

        if (siguiente < (int)(sizeof(kHitos)/sizeof(kHitos[0])) && kHitos[siguiente] == temporada) {
            std::map<std::string,int> tierAhora;
            Foto f = Medir(save, temporada, tierPrevio, tierAhora);
            fotos.push_back(f);
            fotosEdad.push_back(MedirEdad(save, temporada, cc.year));
            varas.push_back(MedirVara(save, temporada, kTierReina));
            fichas.push_back(MedirFichas(save, temporada));
            if (temporada == 20) corpusT20 = MedirCorpusContraParrilla(save);
            out += Linea(f);
            // ~~~16/09 (card 13, 2nd round) — EMPTY SEATS, PER LEVEL AND AT EACH MILESTONE. The milestone already says
            //  how many there are in total; what decides whether a class is left lame is WHERE they fall, and until now that
            //  was only seen at the end. It is accumulated here and printed together with the list per championship.
            {   int porNivel[8] = {0,0,0,0,0,0,0,0};
                int total = 0;
                for (const auto& sd : AllSeries()) {
                    if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
                    const int niv = (sd.level >= 1 && sd.level <= 7) ? sd.level : 1;
                    for (const auto& st : SeatsForClass(sd.id, save))
                        if (st.open || st.occupant_id.empty()) { porNivel[niv]++; total++; }
                }
                char hb[220];
                snprintf(hb, sizeof(hb),
                         "T%-4d vacios %3d  ·  n1 %3d  n2 %3d  n3 %3d  n4 %3d  n5 %3d  n6 %3d  n7 %3d\n",
                         (int)temporada, total, porNivel[1], porNivel[2], porNivel[3], porNivel[4],
                         porNivel[5], porNivel[6], porNivel[7]);
                huecosPorHito += hb;
            }
            tierPrevio = tierAhora;
            siguiente++;
        }
        if (temporada == 20) break;

        // The movements report: snapshot before, rollover, snapshot after, and the difference.
        const std::map<std::string, Asiento1> antes = DondeEstaCadaUno(save);
        const std::map<std::string, std::set<std::string>> ocupAntes = QuienOcupaCadaSerie(save);
        const RolloverReport rr = RolloverYearReport(cc, prog, save, "Jugador");
        {   // and what if no candidate fits the budget? The breakdown says so.
            char b[220];
            snprintf(b, sizeof(b), "T%-3d  firmados %4d  ·  da el nivel y lo paga %4d  ·  baja el liston %3d"
                     "  ·  se ESTIRA %3d  ·  sin NADIE elegible %3d  ·  ★NOVATOS nacidos %3d\n",
                     (int)temporada + 1, rr.seats_backfilled, rr.signed_on_level, rr.signed_below_bar,
                     rr.seats_unfilled, rr.rookies_born, rr.seats_swapped);
            if (temporada < 5 || temporada == 9 || temporada == 19) presupuesto += b;
        }
        const std::map<std::string, Asiento1> despues = DondeEstaCadaUno(save);
        const std::map<std::string, std::set<std::string>> ocupDespues = QuienOcupaCadaSerie(save);
        for (const auto& kv : despues) {
            auto& t = trayecto[kv.first];
            if (!t.nace) { t.nace = (int)temporada + 1; t.tierNace = kv.second.tier; }
            if (kv.second.tier > t.tierMax) { t.tierMax = kv.second.tier; t.tempMax = (int)temporada + 1; }
        }

        Movimientos mv;
        std::vector<std::string> caenDeArriba;      // those who leave the queen category, with destination
        for (const auto& kv : antes) {
            const bool esGen = kv.first.rfind("fl_", 0) == 0 || kv.first.rfind("gn_", 0) == 0;
            const bool esCoh = cohorteMundo.count(kv.first) != 0;
            const auto it = despues.find(kv.first);
            // WHY they fell: their BARE capacity (without the results term) against the bar of their
            // class. If they were already below, the fall was not caused by it -- it came from the age curve.
            // WHY they fell. NOTE: the first version of this said "RESULTS knock them down" as soon as
            // the capacity exceeded the bar, and it was a FALSE DILEMMA — there are more than two causes. It was left in
            // evidence right away: Kyle Larson came out with capacity 1698 against a bar of 1474, i.e. 224
            // points of margin, when the penalty for results is capped at 70. With that margin NOTHING it
            // does can throw him out. Now what is known is said and what is not is flagged.
            auto porQue = [&](const std::string& id, const std::string& serie) {
                // FIRST: did they really lose that seat? If they are still in their usual series, what
                // has changed is something ELSE of theirs and calling it "drops out" is lying. This check exists
                // because the previous version of this diagnostic already published a movement that did not happen.
                const auto id2 = ocupDespues.find(serie);
                if (id2 != ocupDespues.end() && id2->second.count(id))
                    return std::string("  [★SIGUE en " + serie + ": no ha perdido ese asiento]");
                const double cap = OccupantRating(serie, id, save, cc.year);
                const ClassDemand ex = DemandForClass(serie, save, cc.year);
                const double margen = ex.resolved ? cap - ex.floor : 0.0;
                char b[140];
                const char* causa = !ex.resolved      ? "sin liston"
                                  : (margen < 0.0)    ? "ya caia por EDAD"
                                  : (margen <= bal::FORM_RATING_POINTS_CAP) ? "alcanzable por RESULTADOS"
                                  : "★NO lo explica el liston: OTRA causa";
                snprintf(b, sizeof(b), "  [capacidad %.0f vs liston %.0f, margen %+.0f -> %s]",
                         cap, ex.floor, margen, causa);
                return std::string(b);
            };
            if (it == despues.end()) {
                mv.salen++;
                if (kv.second.tier == kTierReina)
                    caenDeArriba.push_back(std::string(NombreDe(kv.first)) + "  (" + kv.second.serie +
                                           ")  ->  " + (save.retired.count(kv.first) ? "se retira" : "sin asiento") +
                                           porQue(kv.first, kv.second.serie));
                continue;
            }
            if (it->second.tier > kv.second.tier) {
                mv.suben++;
                if (esGen) mv.subenGenerados++; else if (esCoh) mv.subenCohorte++; else mv.subenReales++;
            } else if (it->second.tier < kv.second.tier) {
                mv.bajan++;
                if (esGen) mv.bajanGenerados++; else if (esCoh) mv.bajanCohorte++; else mv.bajanReales++;
                if (kv.second.tier == kTierReina)
                    caenDeArriba.push_back(std::string(NombreDe(kv.first)) + "  (" + kv.second.serie +
                                           ")  ->  " + it->second.serie + " (nivel " +
                                           std::to_string(it->second.tier) + ")" +
                                           porQue(kv.first, kv.second.serie));
            }
        }
        for (const auto& kv : despues) if (!antes.count(kv.first)) mv.entran++;
        movs.push_back(mv);
        // DO THOSE WHO MOVE UP ARRIVE GROWN? User's question (14/08): if the queen category is
        // promoted into because those above retire, not because the one below has grown, the grid
        // degrades by itself and in twenty seasons F1 is raced by people who do not make the level. The GRID'S LEVEL is measured
        // each season: capacity p10/p50/p90 and how much those people have left to their ceiling.
        {
            std::vector<double> caps; double prog = 0.0; int np = 0;
            for (const auto& a : SeatsForClass("pinnacle_championship_1831", save)) {
                if (a.open || a.occupant_id.empty()) continue;
                const double c = OccupantRating("pinnacle_championship_1831", a.occupant_id, save, cc.year);
                if (c > 0.0) caps.push_back(c);
                int by = 0; const auto ib = save.birth_year.find(a.occupant_id);
                if (ib != save.birth_year.end()) by = ib->second;
                if (!by) by = BirthYearFor(a.occupant_id);
                prog += GrowthProgress(save, a.occupant_id, DriverAge(by, cc.year), 0); np++;
            }
            if (caps.size() >= 8) {
                std::sort(caps.begin(), caps.end());
                char b[200];
                snprintf(b, sizeof(b), "T%-3d  capacidad de la parrilla  p10 %5.0f  p50 %5.0f  p90 %5.0f"
                         "   ·  progreso medio hacia su techo %.3f\n",
                         (int)temporada + 1, caps[caps.size()/10], caps[caps.size()/2],
                         caps[(caps.size()*9)/10], np ? prog/np : 0.0);
                nivelf1 += b;
            }
        }

        // THE DANCE OF MODERN F1, season by season and with names. `pinnacle_championship_1831` is the current hybrid
        // F1 (the one Verstappen wins in the 1st), and it is a LIVE MARKET series — so whatever comes out
        // here is the market at work, not period content.
        if (temporada < 5 || temporada == 9 || temporada == 19) {
            const std::string kF1 = "pinnacle_championship_1831";
            const auto ia = ocupAntes.find(kF1), id2 = ocupDespues.find(kF1);
            const std::set<std::string> hab = (ia == ocupAntes.end()) ? std::set<std::string>() : ia->second;
            const std::set<std::string> hay = (id2 == ocupDespues.end()) ? std::set<std::string>() : id2->second;
            std::string campeon = "?";
            for (const auto& c : rr.world_champions) if (c.first == kF1) campeon = NombreDe(c.second);
            std::string se, llegan;
            // It says WHERE THEY END UP, not "where they move to": for someone who already had a period seat, losing the
            // F1 one leaves that one as the highest, and calling it a transfer would be inventing a signing. It is the
            // same mistake this diagnostic already made once with the "new faces".
            auto sitio = [&](const std::string& s) {
                return IsModernSeries(s) ? s : (s + " [de EPOCA: sale del mundo vivo]");
            };
            for (const auto& q : hab)
                if (!hay.count(q)) {
                    const auto d = despues.find(q);
                    se += (se.empty() ? "" : "; ") + std::string(NombreDe(q)) + " -> " +
                          (save.retired.count(q) ? std::string("se retira")
                           : d == despues.end() ? std::string("sin asiento") : sitio(d->second.serie));
                }
            for (const auto& q : hay)
                if (!hab.count(q)) {
                    const auto a2 = antes.find(q);
                    llegan += (llegan.empty() ? "" : "; ") + std::string(NombreDe(q)) + " <- " +
                              (a2 == antes.end() ? std::string("nuevo en el mundo") : sitio(a2->second.serie));
                }
            char b[1200];
            snprintf(b, sizeof(b), "T%d  campeon %s  ·  parrilla %d\n     se van:  %s\n     llegan:  %s\n",
                     (int)temporada + 1, campeon.c_str(), (int)hay.size(),
                     se.empty() ? "nadie" : se.c_str(), llegan.empty() ? "nadie" : llegan.c_str());
            bailef1 += b;
        }

        if (temporada == 0) {
            caenTrasT1 = caenDeArriba;   // the answer to "who drops out after the 1st?"
            // AND WHAT HAPPENED TO THEIR SEAT: it was left open (they were thrown out) or someone else occupies it (it was taken). It is
            // the datum that separates the two families of cause, and without it one can only speculate.
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd) || sd.level != kTierReina) continue;
                int abiertos = 0, ocupados = 0;
                std::vector<std::string> nuevos;
                // PER SERIES, not by "their highest seat": someone who was already HERE is not a new face even if
                // their main category was another. See the note on `QuienOcupaCadaSerie`.
                const auto ia = ocupAntes.find(sd.id);
                const std::set<std::string> habia = (ia == ocupAntes.end()) ? std::set<std::string>() : ia->second;
                for (const auto& a : SeatsForClass(sd.id, save)) {
                    if (a.open || a.occupant_id.empty()) { abiertos++; continue; }
                    ocupados++;
                    if (!habia.count(a.occupant_id) && nuevos.size() < 4) nuevos.push_back(NombreDe(a.occupant_id));
                }
                char b[300];
                std::string ln;
                for (const auto& n : nuevos) ln += (ln.empty() ? "" : ", ") + n;
                snprintf(b, sizeof(b), "  %-18s ocupados %3d, abiertos %3d   caras nuevas: %s\n",
                         sd.id.c_str(), ocupados, abiertos, ln.empty() ? "ninguna" : ln.c_str());
                estadoReina += b;
            }
        }
    }

    // — the room there is to grow. If almost nobody is in the rising phase, or if age already eats
    // the whole gap, the five shapes will have nowhere to show and that must be known BEFORE building them.
    out += "\n== EL SITIO QUE HAY PARA CRECER (§20.6.1) ==\n";
    out += "★Hoy la rampa es UNIVERSAL: x0,82 a los 18 -> x1,00 a los 27, meseta a 32, declive despues.\n"
           "  Ese 18% son ~270 puntos de rating, cerca de un nivel entero del ladder.\n\n";
    for (const auto& f : fotosEdad) out += LineaEdad(f);

    // The shape of the ladder at the start and at the end: if the value per level stops being a ladder, the world
    // has flattened and none of the other measures would say so.
    out += "\n== LA FORMA DEL LADDER (valor p10/p50/p90 por nivel) ==\n";
    for (const auto& f : fotos) {
        if (f.temporada != 0 && f.temporada != 20) continue;
        out += "\nTemporada " + std::to_string(f.temporada) + "\n";
        for (int t = 1; t <= 7; t++) {
            if (!f.porTier[t]) continue;
            char b[200];
            snprintf(b, sizeof(b), "   nivel %d  n=%4d   %6.0f / %6.0f / %6.0f\n",
                     t, f.porTier[t], f.p10[t], f.p50[t], f.p90[t]);
            out += b;
        }
    }
    if (!fotos.empty()) {
        out += "\npeor descolocado hacia ARRIBA: " + (fotos.back().peorArriba.empty() ? std::string("ninguno") : fotos.back().peorArriba) + "\n";
        out += "peor descolocado hacia ABAJO:  " + (fotos.back().peorAbajo.empty()  ? std::string("ninguno") : fotos.back().peorAbajo)  + "\n";
    }
    // THE MOVEMENTS REPORT. The question anyone looking at a grid asks.
    out += "\n== QUIEN SUBE, QUIEN BAJA Y QUIEN SE VA (por temporada) ==\n";
    out += "★«entran» son novatos generados + gente que recupera asiento; «salen» son retiros + los que se\n"
           "  quedan sin sitio. Sale de DIFEAR el mundo antes y despues, asi que suma todas las causas.\n\n";
    out += "temp   suben  (cohorte/gen/reales)   bajan  (cohorte/gen/reales)   entran   salen\n";
    for (size_t i = 0; i < movs.size(); i++) {
        if (i > 4 && i != 9 && i != 19) continue;      // the first 5, the 10th and the 20th: the rest is repetition
        char b[220];
        snprintf(b, sizeof(b), "T%-4d  %4d   (%3d/%3d/%3d)          %4d   (%3d/%3d/%3d)          %4d    %4d\n",
                 (int)i + 1, movs[i].suben, movs[i].subenCohorte, movs[i].subenGenerados, movs[i].subenReales,
                 movs[i].bajan, movs[i].bajanCohorte, movs[i].bajanGenerados, movs[i].bajanReales,
                 movs[i].entran, movs[i].salen);
        out += b;
    }

    // THE SANITY CHECK: who really WINS? If in a category of champions the championship is
    // won by an unknown and the champions end up at the bottom, what fails is not the market -- it is the order of the
    // grid, and everything read afterwards is garbage. It runs on a COPY so as not to disturb the world
    // being measured.
    {
        SaveData copia;
        SeedAllDrivers(copia.driver_ratings);
        const WorldSeasonReport ws = RunWorldSeason(copia, kStartYear, 1ull);
        out += "\n== CAMPEONES DE LA CATEGORIA REINA EN LA TEMPORADA 1 (control de cordura) ==\n";
        for (const auto& s : ws.per_series) {
            const SeriesDef* sd = SeriesById(s.series_id);
            if (!sd || sd->level != kTierReina) continue;
            out += "  " + s.series_id + ": campeon " + NombreDe(s.champion_id) +
                   "  (campo " + std::to_string(s.field) + ", " + std::to_string(s.rounds) + " rondas)\n";
        }
    }

    out += "\n== QUIEN SE CAE DE LA CATEGORIA REINA (nivel " + std::to_string(kTierReina) +
           ") TRAS LA PRIMERA TEMPORADA ==\n";
    {   // DO THE GENERATIONAL TALENTS APPEAR, AND HOW OFTEN? The maximum ceiling the OLD formula could produce
        // was the level-7 anchor plus ONE class spread; anything beyond that can only come from the
        // clone by archetype, so that count is the proof that the change does something.
        const double topeViejo = 6.0 * bal::RATING_TIER_STEP + bal::RATING_CLASS_SPREAD;
        int nacidos = 0, sobreTopeViejo = 0, elite = 0;
        double mejor = 0.0;
        for (const auto& kv : save.gen_drivers) {
            nacidos++;
            if (kv.second.talent > topeViejo) sobreTopeViejo++;
            if (kv.second.talent > mejor) mejor = kv.second.talent;
            if (bal::RATING_SEED_BOTTOM + kv.second.talent >= 1669.0) elite++;   // 1669 = the F1 p90 at T1: ACE level
        }
        char b[420];
        snprintf(b, sizeof(b),
                 "\n★generados vivos %d  ·  por encima del tope de la formula VIEJA (%.0f): %d"
                 "  ·  de nivel AS de F1 (>=1669): %d  ·  el mejor %.0f (capacidad %.0f)\n"
                 "  en 20 temporadas: 1 as cada %.1f años\n",
                 nacidos, topeViejo, sobreTopeViejo, elite, mejor, bal::RATING_SEED_BOTTOM + mejor,
                 elite > 0 ? 20.0 / (double)elite : 0.0);
        out += b;
    }

    // HOW LONG DOES IT TAKE TO RISE? If cracks are born but the ladder takes fifteen years to let them arrive, the
    // top grid degrades just the same: the ace arrives when already in decline, or never arrives.
    {
        // ~~~02/09 (front 5) — THE RESERVE: 245 people with a card who race in no grid.
        //  Does the world get to use them in twenty seasons, or does it invent people while having them sitting there?
        // ~~~02/09 () — THE BLAST RADIUS OF "EXIT 2", which is what is missing to decide.
        //  If the card went from meaning "what it IS TODAY" to "how far they can go", the number the
        //  grid uses would be card x progress. For someone already on the plateau progress is worth ~1, so
        //  it would not move. This counts for how many it would really change and by how much.
        { int conFicha = 0, semueven = 0, bajanMucho = 0, jov = 0, vet = 0;
          double sumaCaida = 0.0, peor = 0.0, sumaJov = 0.0, sumaVet = 0.0;
          std::string peorNombre;
          std::set<std::string> vistosF;
          for (const auto& sd : AllSeries()) {
              if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
              for (const auto& st : SeatsForClass(sd.id, save)) {
                  const std::string& id = st.occupant_id;
                  if (st.open || id.empty()) continue;
                  if (id.rfind("gn_",0) == 0 || id.rfind("fl_",0) == 0) continue;
                  if (!vistosF.insert(id).second) continue;
                  const AuthoredProfile* ap = AuthoredProfileFor(NombreDe(id));
                  if (!ap || ap->talent <= 0.0) continue;
                  conFicha++;
                  const auto by = save.birth_year.find(id);
                  int nac = (by != save.birth_year.end()) ? by->second : BirthYearFor(id);
                  if (nac <= 0) continue;
                  const int edad = cc.year - nac;
                  const double prog = GrowthProgress(save.driver_curve, id, edad, 0);
                  const double caida = ap->talent * (1.0 - prog);
                  if (caida > 0.001) {
                      semueven++; sumaCaida += caida;
                      if (caida > 0.05) bajanMucho++;
                      // the partition that decides: for the YOUNG, exit 2 gives an arc; for one who has passed the
                      //  peak it lowers the card by a decline that `AgeDeclinePart` ALREADY applies separately.
                      if (edad < bal::AGE_PEAK_LO) { jov++; sumaJov += caida; }
                      else { vet++; sumaVet += caida; }
                      if (caida > peor) { peor = caida; peorNombre = NombreDe(id); }
                  }
              }
          }
          char db[300];
          snprintf(db, sizeof(db),
                   "\n== §20.6.2 — RADIO DE DAÑO DE LA SALIDA 2 (la ficha pasa a ser TECHO) ==\n"
                   "  con ficha curada en parrilla %d  ·  a los que les CAMBIARIA %d  ·  de esos, mas de 0,05: %d\n"
                   "  caida media de los que se mueven %.3f  ·  la peor %.3f (%s)\n\n",
                   conFicha, semueven, bajanMucho, semueven ? sumaCaida / semueven : 0.0,
                   peor, peorNombre.c_str());
          out += db;
          char pb[240];
          snprintf(pb, sizeof(pb),
                   "  y por EDAD: jovenes (<%d) %d con caida media %.3f  ·  ya en meseta o declive %d con %.3f\n"
                   "  ★al joven le da un arco; al veterano le baja la ficha por un declive que ya se aplica aparte\n\n",
                   bal::AGE_PEAK_LO, jov, jov ? sumaJov / jov : 0.0, vet, vet ? sumaVet / vet : 0.0);
          out += pb; }
        out += radioT0;

        // ~~~02/09 () — HOW MUCH DOES A YOUNG REAL DRIVER IMPROVE, AND HOW MUCH DOES THE CARD ALLOW?
        //
        // The spec leaves it open because "nobody knows how much Antonelli should have improved in five
        // seasons, nor whether the 0.10 cap is the wrong number or the mechanism is". This measures it:
        // the REAL ones who at T0 are 22 or younger are followed and what their ELO says they have
        // improved (on the TALENT scale, which is the card's unit) is compared against the FORM_RATING_CAP cap.
        { int seguidos = 0, pasanTope = 0; double sumaDelta = 0.0, maxDelta = 0.0;
          std::vector<std::string> ej;
          for (const auto& kv : jovenesT0) {
              const auto rt = save.driver_ratings.find(kv.first);
              if (rt == save.driver_ratings.end()) continue;
              if (save.retired.count(kv.first)) continue;
              const double qT20 = RatingQuality(rt->second);
              const double qT0  = kv.second.second;
              const double d = (qT20 - qT0) * bal::TALENT_SD / 0.237;   // ELO->talent scale ()
              seguidos++; sumaDelta += d; if (fabs(d) > fabs(maxDelta)) maxDelta = d;
              if (fabs(d) > bal::FORM_RATING_CAP) pasanTope++;
              if ((int)ej.size() < 8) {
                  char eb[200];
                  const AuthoredProfile* ap = AuthoredProfileFor(kv.second.first);
                  snprintf(eb, sizeof(eb), "  [joven] %-26s ficha %.3f  ·  su ELO se ha movido %+.3f  ·  la ficha le deja %+.2f",
                           kv.second.first.c_str(), ap ? ap->talent : -1.0, d, bal::FORM_RATING_CAP);
                  ej.push_back(eb);
              }
          }
          char hb[260];
          snprintf(hb, sizeof(hb),
                   "\n== §20.6.2 — EL REAL JOVEN Y EL TOPE DE LA FICHA ==\n"
                   "  seguidos desde T0 (<=22 años) y vivos en T20: %d  ·  su ELO se mueve de media %+.3f (max %+.3f)  ·  POR ENCIMA del tope %.2f: %d\n",
                   seguidos, seguidos ? sumaDelta / seguidos : 0.0, maxDelta, bal::FORM_RATING_CAP, pasanTope);
          out += hb;
          for (const auto& x : ej) out += x + "\n";
          out += "\n"; }

        { int reservas = 0, conAsiento = 0, retiradas = 0, conTalento = 0, conAfinidad = 0;
          double sumaT = 0.0, minT = 1e9, maxT = -1e9;
          std::vector<std::string> ejemplos;
          std::set<std::string> conPlaza;
          for (const auto& sd : AllSeries())
              for (const auto& st : SeatsForClass(sd.id, save))
                  if (!st.open && !st.occupant_id.empty()) conPlaza.insert(st.occupant_id);
          for (const auto& id : registry::Ids()) {
              const canon::DriverIdentity* di = registry::ById(id);
              if (!di || di->population_role != canon::PopRole::Reserve) continue;
              reservas++;
              if (conPlaza.count(id)) conAsiento++;
              else if (save.retired.count(id)) retiradas++;
              else {
                  const double t = BaseTalent(id);
                  if (t > 0.0) { conTalento++; sumaT += t; if (t < minT) minT = t; if (t > maxT) maxT = t; }
                  if (di->affinity_known) conAfinidad++;
                  if ((int)ejemplos.size() < 6) {
                      char eb[160];
                      snprintf(eb, sizeof(eb), "  [reserva] %-28s talento %6.1f  afin %d",
                               di->display_name.c_str(), t, (int)di->affinity_known);
                      ejemplos.push_back(eb);
                  }
              }
          }
          char rb[220];
          snprintf(rb, sizeof(rb),
                   "\n== EL POZO DE RESERVA A T20 ==\n  identidades de reserva %d  ·  CON asiento %d  ·  retiradas %d  ·  paradas %d\n\n",
                   reservas, conAsiento, retiradas, reservas - conAsiento - retiradas);
          out += rb;
          char tb[220];
          snprintf(tb, sizeof(tb), "  de las paradas: con TALENTO %d (min %.0f · media %.0f · max %.0f)  ·  con AFINIDAD %d\n",
                   conTalento, conTalento ? minT : 0.0, conTalento ? sumaT / conTalento : 0.0,
                   conTalento ? maxT : 0.0, conAfinidad);
          out += tb;
          for (const auto& x : ejemplos) out += x + "\n";
          out += "\n"; }
        { std::string q = "\n== POR QUE NO ENTRA NADIE EN NIVEL 7 ==\n";
          for (const auto& kv : career::g_rej7)
              q += "  " + kv.first + ": " + std::to_string(kv.second) + "\n";
          out += q + "\n"; }
        // ~~~16/09 (card 13) — HOW MANY PEOPLE RACE IN A DISCIPLINE THAT IS NOT THEIRS? It is the question with which
        //  `bal::POOL_ORIGIN_AFFINITY` is decided, and it had no count: `career_seats::g_rejPromo` already collected
        //  the promotion rejections by affinity and nobody printed them. The two halves of the answer: what
        //  the guard STOPS along the way (by destination level and pass) and what is left SEATED outside its
        //  discipline after the twenty seasons. The discipline on each side is read with
        //  `DriverAffinity("", "", series)`, i.e. the grid's vote, which does not depend on the switch.
        { std::map<std::string, int> afinClase;
          for (const auto& sd : AllSeries())
              if (!afinClase.count(sd.class_name)) afinClase[sd.class_name] = DriverAffinity("", "", sd.id);
          int conOrigen = 0, fuera = 0;
          std::set<std::string> vistosO;
          for (const auto& sd : AllSeries()) {
              if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
              const int afinAsiento = DriverAffinity("", "", sd.id);
              for (const auto& st : SeatsForClass(sd.id, save)) {
                  if (st.open || st.occupant_id.empty()) continue;
                  if (!vistosO.insert(st.occupant_id).second) continue;
                  const PoolOrigin* o = PoolOriginFor(st.occupant_id);
                  if (!o) continue;
                  conOrigen++;
                  const auto ic = afinClase.find(o->home_class);
                  if (!AffinityAllows(ic == afinClase.end() ? -1 : ic->second, afinAsiento)) fuera++;
              }
          }
          char ab[300];
          snprintf(ab, sizeof(ab),
                   "\n== LA DISCIPLINA DE QUIEN SALE DEL POZO (afinidad de origen %s) ==\n"
                   "  sentados con origen curado %d  ·  ★en una disciplina que su origen NO permite %d\n",
                   career::AfinidadDeOrigenActiva() ? "ENCENDIDA" : "APAGADA", conOrigen, fuera);
          out += ab;
          for (const auto& kv : career::g_rejPromo)
              if (kv.first.find("-afinidad") != std::string::npos)
                  out += "  [para] " + kv.first + ": " + std::to_string(kv.second) + "\n";
          out += "\n  ASIENTOS VACIOS POR NIVEL, HITO A HITO\n" + huecosPorHito;
          // ~~~16/09 — And WHERE the gaps remain. The T20 milestone says HOW MANY seats are left empty, but not
          //  in which championships, and that is exactly the question that decides whether a class is left unable to be filled.
          {   std::map<std::string, int> huecos;     // std::map -> deterministic order
              for (const auto& sd : AllSeries()) {
                  if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
                  int n = 0;
                  for (const auto& st : SeatsForClass(sd.id, save)) if (st.open || st.occupant_id.empty()) n++;
                  if (n > 0) huecos[sd.id] = n;
              }
              int total = 0;
              for (const auto& kv : huecos) total += kv.second;
              out += "  ★ASIENTOS VACIOS A T20: " + std::to_string(total) + " en "
                   + std::to_string((int)huecos.size()) + " campeonatos\n";
              for (const auto& kv : huecos)
                  out += "  [hueco] " + kv.first + ": " + std::to_string(kv.second) + "\n";
          }
          out += "\n"; }
        { std::string r = "\n== LA RUTA DE LOS ASES (como llegan donde estan) ==\n";
          int puestas = 0;
          for (const auto& kv : save.gen_drivers) {
            if (bal::RATING_SEED_BOTTOM + kv.second.talent < 1669.0) continue;
            const auto it = career::g_rutaDe.find(kv.first);
            if (it == career::g_rutaDe.end()) continue;
            r += "  [ruta]" + it->second + "\n";
            if (++puestas >= 12) break;
          }
          out += r + "\n"; }
        out += "\n== LA TRAZA DE UN AS ==\n" + trazaAs;
        out += "\n== LA VELOCIDAD DE LA ESCALERA ==\n";
        out += "★Solo GENERADOS (los reales nacen ya colocados). «Sube» = gano al menos un escalon desde donde\n"
               "  aparecio. Los nacidos al final aun no han tenido tiempo, asi que el % sale conservador.\n\n";
        std::vector<int> pasos;
        int nacen = 0, suben = 0, llegan7 = 0, cracks = 0, cracksArriba = 0;
        std::vector<std::string> fichaAses; std::map<int,int> asesPorTier;
        std::vector<int> anosCrack;
        for (const auto& kv : trayecto) {
            const bool gen = kv.first.rfind("gn_", 0) == 0 || kv.first.rfind("fl_", 0) == 0;
            if (!gen) continue;
            nacen++;
            const Trayecto& t = kv.second;
            const int ganados = t.tierMax - t.tierNace;
            if (ganados > 0) { suben++; pasos.push_back((t.tempMax - t.nace) / ganados); }
            if (t.tierMax >= 7) llegan7++;
            const auto gd = save.gen_drivers.find(kv.first);
            if (gd != save.gen_drivers.end() && bal::RATING_SEED_BOTTOM + gd->second.talent >= 1669.0) {
                cracks++;
                if (t.tierMax >= 7) { cracksArriba++; anosCrack.push_back(t.tempMax - t.nace); }
                // ~~~02/09 — WHERE THEY GET STUCK. Knowing that none arrives does not say whether they get stuck on the way out or
                //  on the last step, and they are two different fixes.
                if ((int)fichaAses.size() < 14) {
                    const auto cv = save.driver_curve.find(kv.first);
                    const auto rt = save.driver_ratings.find(kv.first);
                    char fb[220];
                    snprintf(fb, sizeof(fb),
                             "  [as] nace T%-2d en n%d  ·  llega a n%d en T%-2d  ·  curva %.2f  ·  ELO %.0f  ·  potencial %.0f",
                             t.nace, t.tierNace, t.tierMax, t.tempMax,
                             cv == save.driver_curve.end() ? -1.0 : cv->second,
                             rt == save.driver_ratings.end() ? -1.0 : rt->second,
                             bal::RATING_SEED_BOTTOM + gd->second.talent);
                    fichaAses.push_back(fb);
                }
                asesPorTier[t.tierMax]++;
            }
        }
        std::sort(pasos.begin(), pasos.end());
        std::sort(anosCrack.begin(), anosCrack.end());
        { std::string t = "★DONDE ACABAN LOS ASES:";
          for (const auto& kv : asesPorTier) t += "  n" + std::to_string(kv.first) + ":" + std::to_string(kv.second);
          out += t + "\n";
          for (const auto& f : fichaAses) out += f + "\n";
          out += "\n"; }
        char b[600];
        snprintf(b, sizeof(b),
                 "generados con recorrido %d  ·  suben al menos un escalon %d (%.0f%%)  ·  llegan a nivel 7: %d\n"
                 "años por ESCALON ganado: p50 %d  ·  p90 %d  ·  max %d\n"
                 "★de los que nacen con talento de AS (%d): llegan arriba %d  ·  tardan p50 %d años\n",
                 nacen, suben, nacen ? 100.0 * suben / nacen : 0.0, llegan7,
                 pasos.empty() ? 0 : pasos[pasos.size() / 2],
                 pasos.empty() ? 0 : pasos[(pasos.size() * 9) / 10],
                 pasos.empty() ? 0 : pasos.back(),
                 cracks, cracksArriba, anosCrack.empty() ? 0 : anosCrack[anosCrack.size() / 2]);
        out += b;
    }

    out += "\n== ¿LLEGAN CRECIDOS LOS QUE SUBEN A LA F1? ==\n";
    out += "★Si se asciende porque los de arriba se jubilan y no porque el de abajo haya CRECIDO, la parrilla\n"
           "  se degrada sola. Capacidad = rating absoluto (lleva el ancla de nivel dentro).\n\n";
    out += nivelf1;

    out += "\n== EL PRESUPUESTO: ¿QUE PASA SI NADIE ENCAJA? (§21.2) ==\n";
    out += "★El dinero decide QUIEN entra, nunca SI entra alguien: se baja de exigencia en tres escalones y el\n"
           "  hueco gana siempre. «Sin NADIE elegible» ya no es economia, es falta de CONTENIDO (§21.6).\n\n";
    out += presupuesto;

    out += "\n== EL BAILE DE LA F1 ACTUAL (pinnacle_championship_1831) EN CINCO TEMPORADAS ==\n";
    out += "★Serie de MERCADO VIVO: lo que sale aqui es el mercado moviendo gente, no contenido de epoca.\n\n";
    out += bailef1;

    // IS A PERIOD DRIVER SEATED IN A SERIES THAT THE MARKET MOVES? It is the question that decides whether the
    // ubiquity is a BUG or is CONTENT. A historic grid with Schumacher in it is content — the guy
    // is from '69 and in 2025 he signs for nobody. The problem would be him occupying a seat of a LIVE series,
    // because then he would be taking the place of someone who does race.
    //
    // "live market" = neither period memory nor a period series on the calendar (the same condition the
    // engine uses: `EsMercadoVivo`).
    {
        out += "\n== ¿DONDE SE SIENTAN LOS PILOTOS DE EPOCA? (¿bug o contenido?) ==\n";
        const char* kOjo[] = { "Michael Schumacher", "Fernando Alonso", "Lewis Hamilton", "Kimi Räikkönen",
                               "Sebastian Vettel", "Jenson Button" };
        for (const char* quien : kOjo) {
            std::string id;
            for (const auto& pid : PoolDriverIds()) {
                const PoolDriver* pd = DriverById(pid);
                if (pd && pd->name == quien) { id = pid; break; }
            }
            if (id.empty()) { out += std::string("  ") + quien + ": no esta en el pool\n"; continue; }
            int vivas = 0, epoca = 0;
            std::string detalle;
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd)) continue;
                bool aqui = false;
                for (const auto& a : SeatsForClass(sd.id, save))
                    if (!a.open && a.occupant_id == id) { aqui = true; break; }
                if (!aqui) continue;
                const bool viva = IsModernSeries(sd.id);
                if (viva) vivas++; else epoca++;
                if (detalle.size() < 220) detalle += (detalle.empty() ? "" : ", ") + sd.id + (viva ? " [VIVA]" : " [epoca]");
            }
            char b[420];
            snprintf(b, sizeof(b), "  %-20s %2d asientos de EPOCA + %2d en series VIVAS   %s\n",
                     quien, epoca, vivas, detalle.c_str());
            out += b;
        }
    }

    out += estadoReina;
    if (caenTrasT1.empty()) out += "  nadie\n";
    for (const auto& l : caenTrasT1) out += "  " + l + "\n";

    // — the signals census. It goes BEFORE writing a single line of budget: if the band cannot be
    // derived, what has to be discussed is where it comes from, not how it is tuned.
    out += "\n== ¿HAY SEÑAL PARA LA BANDA DEL EQUIPO? (§21.2) ==\n";
    out += "★La escala de SERIE ya distingue la F1 del karting. La banda solo sirve para decir quien es rico\n"
           "  en ESE paddock, asi que lo que decide es si alguna señal separa a dos equipos de la MISMA serie.\n\n";
    {
        const FotoEquipos fe = MedirEquipos(save, 20);
        out += LineaEquipos(fe);
        if (!fe.ejemploPlano.empty())
            out += "      serie sin ninguna señal que separe: " + fe.ejemploPlano + "\n";
    }

    out += "\n★PENDIENTE de §21.2: la PRESION ECONOMICA (equipos que agotan presupuesto). No se puede medir\n"
           "  hasta que los presupuestos existan; mientras tanto, las plazas libres son su antesala.\n";

    // DOES THE GRID FLATTEN AS THE MARKET EVOLVES? (user's question, 17/08)
    out += "\n== LA VARA VIVA CONTRA LA VARA CONGELADA ==\n";
    out += "★«vivo» = abanico de TALENTO real de la parrilla que el mundo ha sentado (as - ultimo).\n"
           "  «congelado» = la vara con la que hoy se divide ese hueco (TalentRefSpanFor: derivada del nivel\n"
           "  x trim curado de la clase). Si el ratio se MUEVE con las temporadas, el sistema por talento se\n"
           "  desincroniza y lo que sientes en la T1 no es lo que sientes en la T20.\n"
           "★«se salen» = series cuyo ultimo cae FUERA del sobre medido (ratio > 1) y entra en la rama de\n"
           "  extrapolacion afin, donde lo recoge el tope de 0.30. Es el origen de los 44 apilados en el suelo.\n\n";
    for (const auto& v : varas) {
        char b[300];
        snprintf(b, sizeof(b),
                 "T%-3d %3d series  ·  vivo/congelado  p10 %.2f  p50 %.2f  p90 %.2f  ·  se salen del sobre %3d"
                 "  ·  reina %-18s vivo %.3f vara %.3f (%.2fx)\n",
                 v.temporada, v.series, v.p10, v.p50, v.p90, v.seSalen,
                 v.reinaClase.c_str(), v.reinaVivo, v.reinaVara,
                 v.reinaVara > 0.0 ? v.reinaVivo / v.reinaVara : 0.0);
        out += b;
    }
    out += "\n★Y lo que ENTREGARIA cada sistema al ultimo de Juniper_Cup (la que se esta probando), en % de vuelta:\n";
    for (const auto& v : varas) {
        char b[220];
        snprintf(b, sizeof(b), "T%-3d  vara CONGELADA %6.2f%%   ·   vara VIVA %6.2f%%   (la viva es el dato de la clase)\n",
                 v.temporada, v.pctCongelada, v.pctViva);
        out += b;
    }

    // CLASS BY CLASS, T1 AGAINST T20. A stable p50 proves nothing: if classes swap
    // places, the median does not move and what you feel in a specific class does.
    if (varas.size() >= 2) {
        const FotoVara& a = varas[1];                        // T1
        const FotoVara& b = varas.back();                    // T20
        std::vector<std::pair<double,std::string>> deriva;    // |relative change| of the ratio, per class
        for (const auto& kv : a.porClase) {
            const auto it = b.porClase.find(kv.first);
            if (it == b.porClase.end() || kv.second <= 0.0) continue;
            deriva.push_back({ std::fabs(it->second - kv.second) / kv.second, kv.first });
        }
        std::sort(deriva.begin(), deriva.end());
        out += "\n★LA MISMA CLASE, T1 CONTRA T20 (deriva del ratio vivo/congelado):\n";
        if (!deriva.empty()) {
            auto q = [&](double p) {
                const double i = p * (double)(deriva.size() - 1);
                const size_t lo = (size_t)i, hi = lo + 1 < deriva.size() ? lo + 1 : lo;
                return deriva[lo].first + (i - (double)lo) * (deriva[hi].first - deriva[lo].first);
            };
            char bb[320];
            int quietas = 0, movidas = 0;
            for (const auto& d : deriva) { if (d.first <= 0.10) quietas++; if (d.first > 0.25) movidas++; }
            snprintf(bb, sizeof(bb),
                     "  %zu clases  ·  deriva p50 %.1f%%  p90 %.1f%%  max %.1f%% (%s)\n"
                     "  quietas (<=10%%) %d   ·   se mueven mas del 25%%: %d\n",
                     deriva.size(), q(0.50)*100.0, q(0.90)*100.0,
                     deriva.back().first*100.0, deriva.back().second.c_str(), quietas, movidas);
            out += bb;
            out += "  las 5 que mas se mueven: ";
            for (size_t i = deriva.size(); i-- > 0 && i + 5 >= deriva.size(); ) {
                char c[100];
                snprintf(c, sizeof(c), "%s %+.0f%%  ", deriva[i].second.c_str(), deriva[i].first*100.0);
                out += c;
            }
            out += "\n";
        }
    }

    // IS IT THE CARD CORPUS THAT NARROWS THE GRID? (18/08, Task 3)
    {
        const FotoCorpus& c = corpusT20;
        out += "\n== EL ABANICO DEL CORPUS CONTRA EL QUE ENTREGA LA PARRILLA (T20) ==\n";
        out += "★Envejecer al clon recupera parte del ancho y no todo. Como a T20 la mayoria de las filas son\n"
               "  CLONADAS, la pregunta siguiente no es «entra por su techo?» sino «de donde sale su numero?».\n"
               "  Si el corpus es estrecho -- o si el sorteo no alcanza sus extremos -- una parrilla clonada no\n"
               "  puede ser mas ancha que lo que ese sorteo permite, por bien que se envejezca a cada uno.\n\n";
        char b[700];
        snprintf(b, sizeof(b),
                 "  CORPUS entero (%d fichas)   min %.3f  p10 %.3f  p50 %.3f  p90 %.3f  max %.3f  ·  ancho total %.3f  ·  p10-p90 %.3f\n"
                 "  lo que el sorteo USA        min %.3f  p10 %.3f  p50 %.3f  p90 %.3f  max %.3f  ·  ancho total %.3f  ·  p10-p90 %.3f\n",
                 (int)c.corpusN, c.corpusMin, c.corpusP10, c.corpusP50, c.corpusP90, c.corpusMax,
                 c.corpusMax - c.corpusMin, c.corpusP90 - c.corpusP10,
                 c.usadoMin, c.usadoP10, c.usadoP50, c.usadoP90, c.usadoMax,
                 c.usadoMax - c.usadoMin, c.usadoP90 - c.usadoP10);
        out += b;
        snprintf(b, sizeof(b),
                 "\n  %d series  ·  %d filas CLONADAS  ·  %d filas AUTORADAS\n"
                 "  abanico de la parrilla (talento, el de la vara)   p50 %.3f   ·   vara p50 %.3f\n"
                 "  abanico que ponen las CLONADAS de cada clase      p50 %.3f\n"
                 "  abanico que ponen las AUTORADAS de cada clase     p50 %.3f\n",
                 c.series, c.filasClon, c.filasAut, c.spanTotalP50, c.varaP50, c.spanClonP50, c.spanAutP50);
        out += b;
        snprintf(b, sizeof(b),
                 "\n★LA COMPARACION LIMPIA -- solo las %d clases donde conviven >=3 clonadas y >=3 autoradas, para no\n"
                 "  mezclar la procedencia con la clase:  CLONADAS p50 %.3f   ·   AUTORADAS p50 %.3f   (%.2fx)\n",
                 c.clasesMixtas, c.spanClonMixtaP50, c.spanAutMixtaP50,
                 c.spanAutMixtaP50 > 0.0 ? c.spanClonMixtaP50 / c.spanAutMixtaP50 : 0.0);
        out += b;
    }

    // WHO ANCHORS THE GRID: A PERSON OR THE CAR? (re-measurement of 18/08)
    {
        out += "\n== FICHA AUTORADA / FICHA CLONADA / CURVA ==\n";
        out += "★AUTORADA = ficha curada (pinneado, field, pool, cohorte, pack).  CLONADA = ficha sorteada del\n"
               "  corpus para un ocupante generado (18/08).  CURVA = sin ficha: el numero que ancla esa fila es\n"
               "  el punto de curva de su HUECO, o sea el ritmo del COCHE.\n"
               "★La procedencia se RE-DERIVA repitiendo la cascada de PersonForOccupant: `authored_talent` no\n"
               "  sirve para distinguir (siempre es > 0, con ficha y sin ella). La copia se valida contra\n"
               "  `authored_talent` en cada hito -- la columna «desajustes» tiene que ser 0.\n\n";
        out += "(1) COBERTURA\n";
        for (const auto& c : fichas) {
            char b[300];
            snprintf(b, sizeof(b),
                     "T%-3d %3d series  %5d filas  ·  AUTORADA %5d (%5.1f%%)  CLONADA %5d (%5.1f%%)  "
                     "CURVA %5d (%5.1f%%)  ·  desajustes %d/%d  ·  sin resolver %d\n",
                     c.temporada, c.series, c.filas,
                     c.autorada, c.filas ? 100.0 * c.autorada / c.filas : 0.0,
                     c.clonada,  c.filas ? 100.0 * c.clonada  / c.filas : 0.0,
                     c.curva,    c.filas ? 100.0 * c.curva    / c.filas : 0.0,
                     c.desajustes, c.validadas, c.sinResolver);
            out += b;
        }
        out += "\n(1b) COBERTURA POR NIVEL DE SERIE — % de filas CON ficha (autorada+clonada), y (filas) del nivel\n";
        for (const auto& c : fichas) {
            char b[420]; std::string l;
            snprintf(b, sizeof(b), "T%-3d ", c.temporada); l = b;
            for (int t = 1; t <= 7; t++) {
                char q[80];
                const int con = c.nAut[t] + c.nClon[t];
                snprintf(q, sizeof(q), " n%d %5.1f%% (%4d)", t, c.nFilas[t] ? 100.0 * con / c.nFilas[t] : 0.0, c.nFilas[t]);
                l += q;
            }
            out += l + "\n";
        }
        out += "\n     ...y de ese % cuanto es CLONADA (el resto es autorada)\n";
        for (const auto& c : fichas) {
            char b[420]; std::string l;
            snprintf(b, sizeof(b), "T%-3d ", c.temporada); l = b;
            for (int t = 1; t <= 7; t++) {
                char q[80];
                snprintf(q, sizeof(q), " n%d %5.1f%%", t, c.nFilas[t] ? 100.0 * c.nClon[t] / c.nFilas[t] : 0.0);
                l += q;
            }
            out += l + "\n";
        }

        out += "\n(2) LAS TRES ANCLAS — en cuantas parrillas el ancla es fila de CURVA (y de que tipo si es persona)\n";
        for (const auto& c : fichas) {
            char b[420];
            snprintf(b, sizeof(b),
                     "T%-3d  AS curva %2d/%2d (aut %2d, clon %2d)  ·  MEDIANA curva %2d/%2d (aut %2d, clon %2d)"
                     "  ·  ULTIMO curva %2d/%2d (aut %2d, clon %2d)  ·  parrillas sin NINGUNA ficha %2d\n",
                     c.temporada, c.asCurva, c.series, c.asAutorada, c.asClonada,
                     c.medianaCurva, c.series, c.medianaAutorada, c.medianaClonada,
                     c.ultimoCurva, c.series, c.ultimoAutorada, c.ultimoClonada, c.sinNingunaFicha);
            out += b;
        }
        out += "\n     el AS de curva, por nivel de serie (parrillas con as de curva / parrillas del nivel)\n";
        for (const auto& c : fichas) {
            char b[420]; std::string l;
            snprintf(b, sizeof(b), "T%-3d ", c.temporada); l = b;
            for (int t = 1; t <= 7; t++) { char q[60]; snprintf(q, sizeof(q), "  n%d %2d/%2d", t, c.asCurvaNivel[t], c.seriesNivel[t]); l += q; }
            out += l + "\n";
        }

        out += "\n(3) EL HUECO DEL AS cuando lo pone la curva (unidades de talento; excluidas las parrillas sin ninguna ficha)\n";
        for (auto& c : fichas) {
            char b[420];
            if (c.huecos.empty()) { snprintf(b, sizeof(b), "T%-3d  n 0  (ninguna)\n", c.temporada); out += b; continue; }
            std::sort(c.huecos.begin(), c.huecos.end());
            auto q = [&](double p) {
                const double i = p * (double)(c.huecos.size() - 1);
                const size_t lo = (size_t)i, hi = lo + 1 < c.huecos.size() ? lo + 1 : lo;
                return c.huecos[lo] + (i - (double)lo) * (c.huecos[hi] - c.huecos[lo]);
            };
            double s = 0.0; for (double h : c.huecos) s += h;
            snprintf(b, sizeof(b),
                     "T%-3d  n %2zu  min %.4f  p50 %.4f  p90 %.4f  max %.4f  media %.4f  ·  peor %s: %s por encima de %s\n",
                     c.temporada, c.huecos.size(), c.huecos.front(), q(0.50), q(0.90), c.huecos.back(),
                     s / (double)c.huecos.size(), c.peorClase.c_str(), c.peorAs.c_str(), c.peorFicha.c_str());
            out += b;
        }

        out += "\n(4) LA DERIVA ENTRE HITOS\n";
        {
            std::string l1 = "cobertura (con ficha)     ", l2 = "   ...de ella, CLONADA  ",
                        l3 = "AS de curva               ", l4 = "MEDIANA de curva          ",
                        l5 = "ULTIMO de curva           ", l6 = "parrillas sin ninguna ficha";
            for (const auto& c : fichas) {
                char b[64];
                snprintf(b, sizeof(b), " %6.1f%%", c.filas ? 100.0 * (c.autorada + c.clonada) / c.filas : 0.0); l1 += b;
                snprintf(b, sizeof(b), " %6.1f%%", c.filas ? 100.0 * c.clonada / c.filas : 0.0); l2 += b;
                snprintf(b, sizeof(b), " %6.1f%%", c.series ? 100.0 * c.asCurva / c.series : 0.0); l3 += b;
                snprintf(b, sizeof(b), " %6.1f%%", c.series ? 100.0 * c.medianaCurva / c.series : 0.0); l4 += b;
                snprintf(b, sizeof(b), " %6.1f%%", c.series ? 100.0 * c.ultimoCurva / c.series : 0.0); l5 += b;
                snprintf(b, sizeof(b), " %7d", c.sinNingunaFicha); l6 += b;
            }
            std::string cab = "medida                    ";
            for (const auto& c : fichas) { char b[32]; snprintf(b, sizeof(b), " %6s", ("T" + std::to_string(c.temporada)).c_str()); cab += b; }
            out += cab + "\n" + l1 + "\n" + l2 + "\n" + l3 + "\n" + l4 + "\n" + l5 + "\n" + l6 + "\n";
        }

        out += "\n★VALIDACION DEL METODO (2): la MISMA persona en 2+ parrillas, cuantas llevan un numero DISTINTO\n"
               "  en cada una. Una ficha es de la PERSONA y no cambia de coche a coche; un punto de curva es del\n"
               "  HUECO y cambia. La CLONADA sale del id y de nada mas: tiene que ser 0 % inestable, y una sola\n"
               "  delataria que lo que llamo «clonada» no lo es.\n"
               "  ★La AUTORADA no sale 0 % y no es un fallo del metodo: quien NO tiene perfil autorado resuelve\n"
               "  por el FIELD en una serie (fd.skill) y por el POOL en otra (pd->base_skill), y esos dos numeros\n"
               "  no tienen por que coincidir. Es una propiedad de la cascada, anterior a esta medicion.\n";
        for (const auto& c : fichas) {
            char b[320];
            snprintf(b, sizeof(b), "T%-3d  AUTORADA %4d personas, %4d distintas (%5.1f%%)  ·  CLONADA %4d, %4d (%5.1f%%)"
                                   "  ·  CURVA %4d, %4d (%5.1f%%)\n",
                     c.temporada, c.multiAut, c.multiAutInestable,
                     c.multiAut ? 100.0 * c.multiAutInestable / c.multiAut : 0.0,
                     c.multiClon, c.multiClonInestable,
                     c.multiClon ? 100.0 * c.multiClonInestable / c.multiClon : 0.0,
                     c.multiCurva, c.multiCurvaInestable,
                     c.multiCurva ? 100.0 * c.multiCurvaInestable / c.multiCurva : 0.0);
            out += b;
        }

        out += "\n★DE DONDE SALEN LAS FILAS QUE SIGUEN SIN FICHA (escalon de la cascada por el que entran)\n";
        for (const auto& c : fichas) {
            char b[64]; snprintf(b, sizeof(b), "T%-3d ", c.temporada);
            std::string l = b;
            if (c.curvaPorEscalon.empty()) l += " (ninguna)";
            for (const auto& kv : c.curvaPorEscalon) { char q[80]; snprintf(q, sizeof(q), "  %s %d", kv.first.c_str(), kv.second); l += q; }
            out += l + "\n";
        }
        out += "\n★CRITERIO DE SALIDA\n";
        {
            // The criterion, LITERAL: "the ace of a grid is a PERSON in the 90 categories, at T0 and at T20"
            // + "grids with no row with a card: 0 at all milestones".
            int asT0 = -1, asT20 = -1, sinFichaTotal = 0, otrosHitosConAsDeCurva = 0;
            for (const auto& c : fichas) {
                if (c.temporada == 0)  asT0  = c.asCurva;
                if (c.temporada == 20) asT20 = c.asCurva;
                if (c.temporada != 0 && c.temporada != 20 && c.asCurva > 0) otrosHitosConAsDeCurva++;
                sinFichaTotal += c.sinNingunaFicha;
            }
            char b[420];
            snprintf(b, sizeof(b),
                     "  el AS es una PERSONA en las 90 categorias, en T0 y en T20:  T0 %d de curva, T20 %d de curva  ->  %s\n"
                     "  parrillas sin ninguna fila con ficha, en todos los hitos: %d  ->  %s\n"
                     "  ★aparte del criterio, hitos INTERMEDIOS con algun as de curva: %d (ver la tabla (2))\n",
                     asT0, asT20, (asT0 == 0 && asT20 == 0) ? "SI" : "NO",
                     sinFichaTotal, sinFichaTotal == 0 ? "SI" : "NO", otrosHitosConAsDeCurva);
            out += b;
            for (const auto& c : fichas) if (!c.sinFichaClases.empty()) {
                std::string l = "  T" + std::to_string(c.temporada) + " sin ninguna ficha: ";
                for (const auto& s : c.sinFichaClases) l += s + " ";
                out += l + "\n";
            }
        }
    }

    FILE* fp = fopen(outPath, "wb");
    if (fp) { fwrite(out.data(), 1, out.size(), fp); fclose(fp); }
    printf("%s", out.c_str());
    printf("\nmundo -> %s\n", outPath);
    return 0;
}

// ===================================================================================================
// order: THE TWO PATHS THAT COMPOSE THE GRID, SIDE BY SIDE (17/08)
// ===================================================================================================
//
// Bug found and fixed by this dump (Task 4, 17/08): the two places in career_overlay.cpp that
// write the XML right before running (`WriteSeasonGridForEvent` and the launch by calendar) called
// `ComposeSeasonGrid` with NINE arguments and left `seats`, `skipLiveries` and `driverRaces` at their
// default nullptr. That had two effects that were not obvious from reading the call:
//
//   1. without `seats`, `ComposeGridFromSeats` was not entered -> it composed by the STATIC path, not from contracts;
//   2. without `driverRaces`, `EffectivePace` cut off on its first line and returned the WHOLE `RatingQuality(ELO)`
//      > the authored capacity was discarded, which is exactly what the says has to be eliminated.
//
// The pregen (`career_fields.cpp:1918`) DID pass them. Fixed in the same commit that updates this
// dump: the two overlay places now pass `seats` and `driverRaces` (see the long comment in
// `WriteSeasonGridForEvent`), so path (a) below NO longer imitates the old call -- it imitates the
// new one. With the same arguments in (a) and (b), the dump remains a comparison of the two INTERNAL
// paths: if they ever diverge again, either ComposeSeasonGrid stopped being deterministic or someone
// removed an argument again in only one of the two calls.
static int dump_orden(const char* outPath) {
    using namespace career;
    if (!canon_load_prod()) { printf("ORDEN FAIL: no se pudieron cargar los datos\n"); return 1; }

    SaveData save;
    SeedAllDrivers(save.driver_ratings);

    const char* kClase = "Juniper_Cup";
    const SeriesDef* sd = nullptr;
    for (const auto& s : AllSeries())
        if (s.class_name == kClase && !IsEraMemorySeries(s)) { sd = SeriesById(s.id); break; }
    if (!sd) { printf("ORDEN FAIL: no hay serie viva para %s\n", kClase); return 1; }

    const std::vector<SeatRow> asientos = SeatRowsForSeries(save, sd->id);
    const int gs = (int)asientos.size() > 0 ? (int)asientos.size() : GridSizeForClassName(sd->class_name);

    // (a) LIKE THE OVERLAY AT THE EVENT (already fixed, Task 4): with seats and with the races map --
    // before 17/08 this left `seats` and `driverRaces` at nullptr, which is what this dump measured.
    const auto gridEvento = ComposeSeasonGrid(sd->id, sd->level, /*playerForm=*/0.0, gs, false,
                                              save.rival_form, nullptr, &save.driver_ratings,
                                              ClassRoleForSeries(sd->id), &asientos, nullptr,
                                              &save.driver_races);
    // (b) LIKE THE PREGEN: with seats and with the races map.
    const auto gridPregen = ComposeSeasonGrid(sd->id, sd->level, /*playerForm=*/0.0, gs, false,
                                              save.rival_form, nullptr, &save.driver_ratings,
                                              ClassRoleForSeries(sd->id), &asientos, nullptr,
                                              &save.driver_races);

    std::string out = "== LOS DOS CAMINOS DE COMPOSICION, LADO A LADO ==\n\n";
    char b[400];
    snprintf(b, sizeof(b), "serie %s  ·  clase %s  ·  asientos %d  ·  gridSize %d\n\n",
             sd->id.c_str(), kClase, (int)asientos.size(), gs);
    out += b;

    auto pinta = [&](const char* titulo, const std::vector<GridDriver>& g) {
        snprintf(b, sizeof(b), "-- %s: %d pilotos --\n", titulo, (int)g.size());
        out += b;
        std::vector<const GridDriver*> ord;
        for (const auto& d : g) ord.push_back(&d);
        std::sort(ord.begin(), ord.end(), [](const GridDriver* x, const GridDriver* y) {
            return x->race_skill > y->race_skill; });
        for (size_t i = 0; i < ord.size(); i++) {
            snprintf(b, sizeof(b), "  %2d. %-26s talento %.4f  race %.4f\n",
                     (int)i + 1, ord[i]->name.c_str(), ord[i]->talent, ord[i]->race_skill);
            out += b;
        }
        // Does it reproduce the AUTHORED order? The position by race_skill is compared against the position by talent.
        std::vector<const GridDriver*> porTalento = ord;
        std::sort(porTalento.begin(), porTalento.end(), [](const GridDriver* x, const GridDriver* y) {
            return x->talent > y->talent; });
        int desplazados = 0, peor = 0; std::string quien;
        for (size_t i = 0; i < porTalento.size(); i++) {
            size_t j = 0;
            while (j < ord.size() && ord[j] != porTalento[i]) j++;
            const int d = (int)j - (int)i;
            if (d != 0) desplazados++;
            if (std::abs(d) > peor) { peor = std::abs(d); quien = porTalento[i]->name; }
        }
        double lo = 2.0, hi = -2.0;
        for (const auto& d : g) { if (d.talent < lo) lo = d.talent; if (d.talent > hi) hi = d.talent; }
        snprintf(b, sizeof(b), "   -> fuera de su puesto por talento: %d de %d  ·  el peor se mueve %d puestos (%s)"
                 "  ·  abanico de talento %.4f\n\n", desplazados, (int)g.size(), peor, quien.c_str(), hi - lo);
        out += b;
    };
    pinta("(a) COMO EL OVERLAY EN EL EVENTO (ya con asientos y con carreras)", gridEvento);
    pinta("(b) COMO EL PREGEN (con asientos y con carreras)", gridPregen);

    // Is it the SAME people?
    std::set<std::string> na, nb;
    for (const auto& d : gridEvento) na.insert(d.name);
    for (const auto& d : gridPregen) nb.insert(d.name);
    std::vector<std::string> soloA, soloB;
    for (const auto& n : na) if (!nb.count(n)) soloA.push_back(n);
    for (const auto& n : nb) if (!na.count(n)) soloB.push_back(n);
    snprintf(b, sizeof(b), "-- ¿la misma gente? --\n  solo en el camino del EVENTO: %d\n  solo en el PREGEN: %d\n",
             (int)soloA.size(), (int)soloB.size());
    out += b;
    for (const auto& n : soloA) out += "    evento: " + n + "\n";
    for (const auto& n : soloB) out += "    pregen: " + n + "\n";

    FILE* fp = fopen(outPath, "wb");
    if (fp) { fwrite(out.data(), 1, out.size(), fp); fclose(fp); }
    printf("%s", out.c_str());
    return 0;
}

// ===================================================================================================
// silhouette: WHAT EACH CLASS REALLY DELIVERS (19/08, "the gap" plan)
// ===================================================================================================
//
// One row per class with data, at grid size and PRODUCTION level, reading the XML that gets written.
// It is the instrument this task is measured with, and it stays: the three-nail conversion makes
// half of the spec's invariants true BY CONSTRUCTION (), so the only thing that can really be measured
// is the INTERIOR of the grid — top-10, SD, p10 — and the piling up.
//
// Columns:
//   obj_total    `cp.spread_dry`, the class spread: driver + car
//   obj_piloto   `DriverSpreadPct(...)`, what production actually passes to the writer
//   entregado    % of lap read FROM THE XML through the measured transfer (NOT from `PctOffOnPins`: on a flat
//                grid that function returns 0% for everyone while the XML carries the spread distributed)
//   ratio_piloto entregado / obj_piloto
//   top10_%      % of lap spanned by the first 10 (or as many as there are)
//   en_suelo     how many touch the floor of THEIR class   ·   en_0.30  how many touch kMinDriveableSkill
//
// 24/08 — THE OTHER SIDE OF THE A/B IS NO LONGER CURVE. Until task 5 this was measured with `ZTA_CURVE_BY_RANK=1`
// to turn on the distribution by POSITION; that mechanism has been removed entirely. The equivalent lever and the one that
// remains is `ZTA_SILUETA_ABANICO=<%>`: it gives ALL classes the same driver spread instead of their own, which
// is exactly what the distribution by position delivered (all 109 at 11.3%-11.6%). It serves the same purpose —seeing
// that the table is not decorative— without keeping a second full conversion just to be able to ask it.
static int dump_silueta(const char* outPath) {
    using namespace career;
    if (!canon_load_prod()) { printf("SILUETA FAIL: no se pudieron cargar los datos\n"); return 1; }
    const char* env = getenv("ZTA_SILUETA_ABANICO");
    const double forzado = env ? atof(env) : 0.0;

    const std::vector<SiluetaRow> rows = SiluetaDeProduccion(false, forzado);

    std::string out;
    char b[512];
    if (forzado > 0.0)
        snprintf(b, sizeof(b), "== SILUETA DE PRODUCCION ==  conversion: TRES CLAVOS con ABANICO FIJO %.2f%% "
                 "(el dato de clase APAGADO)  ·  kHeadOpen %.2f  ·  clases %d\n\n",
                 forzado, kHeadOpen, (int)rows.size());
    else
        snprintf(b, sizeof(b), "== SILUETA DE PRODUCCION ==  conversion: TRES CLAVOS (vara viva)  ·  "
                 "kHeadOpen %.2f  ·  clases %d\n\n", kHeadOpen, (int)rows.size());
    out += b;
    out += "clase                     |  n | obj_total | obj_piloto | entregado | ratio_piloto | top10_% |"
           "    SD |   p10 | en_suelo | en_0.30\n";
    out += "--------------------------+----+-----------+------------+-----------+--------------+---------+"
           "-------+-------+----------+--------\n";
    std::vector<SiluetaRow> ord = rows;
    std::sort(ord.begin(), ord.end(), [](const SiluetaRow& a, const SiluetaRow& c) { return a.cls < c.cls; });
    for (const auto& r : ord) {
        snprintf(b, sizeof(b), "%-25s | %2d |   %7.3f |    %7.3f |   %7.3f |      %7.3f | %7.3f | %5.3f | %5.3f |"
                 "     %4d |    %4d%s\n",
                 r.cls.c_str(), r.n, r.obj_total, r.obj_piloto, r.entregado, r.ratio, r.top10, r.sd, r.p10,
                 r.en_suelo, r.en_030, r.oval ? "   (OVALO)" : "");
        out += b;
    }

    // aggregates: p10/p50/p90 of each column, over the NON-OVAL classes (on ovals everything goes to 1.0) ----
    std::vector<double> vTot, vPil, vEnt, vRat, vTop, vSd, vP10;
    long long sumSuelo = 0, sum030 = 0; int nOval = 0, nJuzgadas = 0;
    for (const auto& r : rows) {
        if (r.oval) { nOval++; continue; }
        nJuzgadas++;
        vTot.push_back(r.obj_total); vPil.push_back(r.obj_piloto); vEnt.push_back(r.entregado);
        vRat.push_back(r.ratio); vTop.push_back(r.top10); vSd.push_back(r.sd); vP10.push_back(r.p10);
        sumSuelo += r.en_suelo; sum030 += r.en_030;
    }
    auto q = [](std::vector<double>& v, double f) {
        if (v.empty()) return 0.0;
        std::sort(v.begin(), v.end());
        return v[(size_t)(f * (v.size() - 1))];
    };
    out += "\n-- AGREGADOS (p10 / p50 / p90 sobre las clases NO-OVALO) --\n";
    struct Col { const char* nombre; std::vector<double>* v; };
    Col cols[] = { {"obj_total   ", &vTot}, {"obj_piloto  ", &vPil}, {"entregado   ", &vEnt},
                   {"ratio_piloto", &vRat}, {"top10_%     ", &vTop}, {"SD          ", &vSd},
                   {"p10         ", &vP10} };
    for (auto& c : cols) {
        snprintf(b, sizeof(b), "  %s  p10 %8.4f   p50 %8.4f   p90 %8.4f\n",
                 c.nombre, q(*c.v, 0.10), q(*c.v, 0.50), q(*c.v, 0.90));
        out += b;
    }
    // The CHARACTER factor: how much wider the most open class delivers than the most closed. With the fixed
    // spread this is worth 1.0x (all deliver the same); it is the measure of the task.
    const double entMin = vEnt.empty() ? 0.0 : vEnt.front(), entMax = vEnt.empty() ? 0.0 : vEnt.back();
    snprintf(b, sizeof(b), "\n  clases %d (no-ovalo %d, ovalo %d)  ·  entregado MIN %.3f MAX %.3f  ->  "
             "caracter de clase %.2fx\n  pilotos en el SUELO de su clase %lld  ·  en kMinDriveableSkill (0,30) %lld\n",
             (int)rows.size(), nJuzgadas, nOval, entMin, entMax, entMin > 1e-9 ? entMax / entMin : 0.0,
             sumSuelo, sum030);
    out += b;

    FILE* fp = fopen(outPath, "wb");
    if (fp) { fwrite(out.data(), 1, out.size(), fp); fclose(fp); }
    printf("%s", out.c_str());
    return 0;
}

static int dump_seedlab(const char* outPath) {
    using namespace career;
    using namespace career::canon;
    if (!canon_load_prod()) { printf("SEEDLAB FAIL: no se pudieron cargar los datos\n"); return 1; }
    CHECK(registry::Load() > 1000);
    SaveData save;                        // year 1 derived from the data: the world a career starts with

    // Each variant carries TWO halves and they must be movable separately: how it SEEDS (the map) and
    // how the composer LOOKS UP (the switch). Changing only the map fixes nothing — the composer keeps
    // passing the raw id, which is empty in the PSVs — and that is what makes V1 barely move the unseeded
    // rows. The two halves together are the whole fix, and that is why they are measured together.
    struct Var { const char* nombre; std::map<std::string, double> seed; bool resolverId; double afinidad; bool cohorteEnCasa = false; };
    std::vector<Var> vars;
    // V0 IS PRODUCTION, and since the that means the grid built FROM THE SEATS. The snapshot
    // from before lives in tools/fixtures/seedlab_pre_c5.txt (792 rows without ELO, 72 classes mixing, gap
    // 0.461); the one from right before E, in the comment below.
    //
    // ALL the variants of the are NOW measured on the seats path, and this is not a
    // detail: until today they were measured on the static composition, i.e. on a world with 292 cars with no
    // owner, 458 youth-academy rows above their level and two talent scales coexisting. Any
    // conclusion about the MODEL drawn from there was measuring the PLACEMENT. It is exactly the mistake that
    // cost the five reverted attempts of 09/08, and that is why the table is redone entirely.
    vars.push_back(Var{ "V0 PRODUCCION (desde asientos)",  seedlab::V0(),     true,  1.0, false });
    // 27/08 — THE `V-STATIC composition (before E)` ROW IS GONE WITH `g_gridFromSeats`. It was the only one
    // that measured the static path, and measuring it required a rollback switch that retires it.
    // Its last reading (port to 0.7.0, 15/09, on the 0.7.0 data), so that it is not lost:
    //   V-composicion ESTATICA (antes E)  2216 filas  0 sinELO  0/98 mezcla  brecha 0.000
    //     u efectiva 0.72/1.60/4.80 · u DERIVADA 0.84/1.79/4.55 · u>2 26 · coh>t2 310 · cohorte lidera 1/98
    //   V0 PRODUCCION (desde asientos)    2216 filas  0 sinELO  0/98 mezcla  brecha 0.000
    //     u efectiva 0.72/1.42/3.90 · u DERIVADA 0.84/1.65/4.55 · u>2 14 · coh>t2 0   · cohorte lidera 0/98
    // So: the rollback was not insurance, it was 310 youth-academy rows out of place one bool
    // away. The pre-C.5 snapshot remains in tools/fixtures/seedlab_pre_c5.txt.
    vars.push_back(Var{ "V-sin resolver del compositor",   seedlab::V0(),     false, 1.0, false });
    vars.push_back(Var{ "V3 por asiento principal",        seedlab::V3(save), true,  1.0, false });
    vars.push_back(Var{ "V4 V3 + cohorte anclada",         seedlab::V4(save), true,  1.0, false });
    // — HOW MUCH OF THE EXCESS WIDTH IS PUT BY AFFINITY. Same seeding as production, moving only
    // the affinity scale. If `u derivada` does not drop when it is removed, the width comes from elsewhere and
    // recalibrating it does not fix the spread -- which is exactly what must be known before touching it.
    vars.push_back(Var{ "V0 con afinidad x0.5",            seedlab::V0(),     true,  0.5, false });
    vars.push_back(Var{ "V0 con afinidad x0 (ninguna)",    seedlab::V0(),     true,  0.0, false });
    // THE CORE OF PHASE D: the AUTHORED capacity rules and the ELO only perturbs it (/). In
    // year 1 nobody has races, so confidence is 0 and the grid is 100% authored. Measured on the
    // already-placed world, which is the first time this number means anything.
    vars.push_back(Var{ "V5 capacidad AUTORADA (ano 1)",   seedlab::V5(),     true,  1.0, false });

    World base = BuildWorld(save);
    std::string out = "== BANCO DE SIEMBRA (100 parrillas de produccion, ano 1) ==\n\n";
    // The `filas` column is what stops you believing a false improvement: a variant that leaves the grids
    // SHORT lowers the spread and the mixes without fixing anything — it just measures fewer cars. If `filas` drops, the
    // whole row is suspect however good the rest looks.
    out += "variante                        filas  sinELO  mezcla  brecha   u efectiva min/p50/max   u DERIVADA"
           " min/p50/max   u>2  coh>t2  cohorte lidera\n";
    for (auto& v : vars) {
        career::g_seedIdResolveOccupant = v.resolverId;   // the two bench switches, per variant
        career::g_affinityScale = v.afinidad;
        career::g_benchCohortHomeOnly = v.cohorteEnCasa;
        World w = base;
        w.engine_seed = v.seed;
        const GridCensus g = TakeGridCensus(w, save);
        const Census     c = TakeCensus(w, std::vector<Finding>());
        char linea[512];
        snprintf(linea, sizeof(linea),
                 "%-30s %5d %6d %5d/%-3d %7.3f  %5.2f/%.2f/%-5.2f   %5.2f/%.2f/%-5.2f %5d %7d %8d/%d\n",
                 v.nombre, g.rows, g.rows_unseeded, g.classes_mixing_scales, g.classes, g.talent_gap,
                 g.u_min, g.u_p50, g.u_max, g.ud_min, g.ud_p50, g.ud_max,
                 g.classes_u_over_2, g.cohort_rows_above_tier2, g.classes_cohort_leads, g.classes);
        (void)c;
        out += linea;
    }

    // — WHERE THE COHORT REMAINS ABOVE ITS LEVEL. The aggregate number does not say whether what remains
    // is an irreducible remainder or a path not yet touched, and that is exactly the question.
    {
        career::g_seedIdResolveOccupant = true; career::g_affinityScale = 1.0;
        career::g_benchCohortHomeOnly = false;
        std::set<std::string> cohorte;
        for (int t = 1; t <= 7; t++) for (const auto& rd : RosterForTier(t)) if (!rd.id.empty()) cohorte.insert(rd.id);
        std::map<std::string, double> seed = seedlab::V0();
        int modernas = 0, historicas = 0, clasesM = 0, clasesH = 0;
        std::string ejemploH;
        std::set<std::string> vistas;
        for (const auto& sd : AllSeries()) {
            if (!vistas.insert(sd.class_name).second) continue;
            if (sd.level <= 2) continue;
            const int gs = GridSizeForClassName(sd.class_name);
            if (gs < 8) continue;
            const std::vector<SeatRow> filas = SeatRowsForSeries(save, sd.id);
            std::vector<GridDriver> grid = ComposeSeasonGrid(
                sd.id, sd.level, 0.0, gs, false, EmptyRivalForm(), nullptr, &seed,
                ClassRole::SingleClass, filas.empty() ? nullptr : &filas);
            int n = 0;
            for (const auto& d : grid) if (cohorte.count(d.driver_id)) n++;
            if (n == 0) continue;
            if (IsModernSeries(sd.id)) { modernas += n; clasesM++; }
            else { historicas += n; clasesH++; if (ejemploH.empty()) ejemploH = sd.class_name; }
        }
        char linea[300];
        snprintf(linea, sizeof(linea),
                 "\n== COHORTE POR ENCIMA DE SU NIVEL, camino por ASIENTOS ==\n"
                 "  en series MODERNAS:   %4d filas en %d clases\n"
                 "  en series HISTORICAS: %4d filas en %d clases (p.ej. %s)\n",
                 modernas, clasesM, historicas, clasesH, ejemploH.c_str());
        out += linea;
    }

    // The test that decides, and the one set as criterion: do the real ones still stay ahead of the youth academy in
    // the reference classes? The first three by talent of each are shown, in each variant.
    const char* refs[] = { "Ivory_Cup_10072", "Onyx_Cup_4824", "Juniper_Cup" };
    out += "\n== LOS TRES PRIMEROS POR TALENTO (el criterio de salida de §18.1) ==\n";
    for (const char* cls : refs) {
        const SeriesDef* serie = nullptr;
        for (const auto& sd : AllSeries()) if (sd.class_name == cls) { serie = &sd; break; }
        if (!serie) continue;
        out += std::string("\n") + cls + " (nivel " + std::to_string(serie->level) + ")\n";
        for (auto& v : vars) {
            career::g_seedIdResolveOccupant = v.resolverId;
            career::g_affinityScale = v.afinidad;
            career::g_benchCohortHomeOnly = v.cohorteEnCasa;
            const int gs = GridSizeForClassName(cls);
            const std::vector<SeatRow> filas = SeatRowsForSeries(save, serie->id);
            std::vector<GridDriver> grid = ComposeSeasonGrid(
                serie->id, serie->level, 0.0, gs, false, EmptyRivalForm(), nullptr, &v.seed,
                ClassRole::SingleClass, filas.empty() ? nullptr : &filas);
            std::sort(grid.begin(), grid.end(), [](const GridDriver& a, const GridDriver& b) {
                return a.talent > b.talent;
            });
            std::string linea = std::string("  ") + v.nombre;
            while (linea.size() < 34) linea += ' ';
            for (int i = 0; i < 3 && i < (int)grid.size(); i++) {
                linea += grid[i].name;
                if (grid[i].kind == "roster") linea += " [cohorte]";
                linea += (i < 2) ? " / " : "";
            }
            out += linea + "\n";
        }
    }

    career::g_seedIdResolveOccupant = true;   // production post C.5; the bench NEVER leaves anything else set
    career::g_affinityScale = 1.0;
    career::g_benchCohortHomeOnly = false;
    // 27/08: here `g_gridFromSeats` was restored; the switch no longer exists (closed).

    FILE* fp = fopen(outPath, "wb");
    if (fp) { fwrite(out.data(), 1, out.size(), fp); fclose(fp); }
    printf("%s", out.c_str());
    printf("\nbanco -> %s\n", outPath);
    return 0;
}

// ===================================================================================================
// measures: THE FOUR QUESTIONS OF 0.7.0 (16/09)
// ===================================================================================================
//
// READ-ONLY instrument. It does not touch the engine: it runs the same twenty seasons as `--world` and, at the
// milestones, asks four things that `--world` does not separate:
//
//   (1) THE COHORT (`rk_*`): where it sits, what level its series is, what position it gets in the grid of
//       its class, and how many cohort ROWS there are per level — which is what the player meets as
//       it climbs the ladder. With its own block for a specific person (`--medidas` prints it
//       always; the same block exists standalone as `--vega` so it can be compared with an old tree that
//       has neither `--world` nor `--medidas`).
//   (2) DECLARED SEATS against COMPOSED ROWS, per class and per level. It distinguishes "there are gaps" from
//       "there are fewer people": a declared seat nobody occupies is a gap; a grid composed
//       with fewer rows than seats has the gap ON THE ASPHALT.
//   (3) THE F1 FRONT season by season: ELO and capacity of the 1st, 5th and 20th of
//       `pinnacle_championship_1831`. If the front drops, the bottleneck is how many aces are born or that they do not arrive.
//   (4) THE PEOPLE WHO VANISH: the same criterion as `test_fill_pass_distribution` (a slot
//       changes occupant without an author and nothing is known of the previous one), but at TWENTY winters and
//       following them afterwards to answer whether they come back.
//
// A single traversal: the four questions are measured over THE SAME world, so the figures of one
// section can be cross-checked with those of another without repeating twenty rollovers.

// THE PERSON block, apart so it can also live in an old tree under `--vega`.
static std::string MedidasPersona(const career::SaveData& save, const std::string& quien, int temporada) {
    using namespace career;
    std::string out;
    char b[420];

    // who: their cohort id. It is looked up by name in the roster so as not to nail down the id.
    std::string id, nombre;
    std::vector<RosterDriver> coh = RosterForTier(1);
    for (int t = 2; t <= 7; t++) for (const auto& r : RosterForTier(t)) {
        bool visto = false;
        for (const auto& c : coh) if (c.id == r.id) { visto = true; break; }
        if (!visto) coh.push_back(r);
    }
    for (const auto& r : coh) if (r.name == quien) { id = r.id; nombre = r.name; break; }
    if (id.empty()) { snprintf(b, sizeof(b), "  (no hay nadie llamado «%s» en la cohorte)\n", quien.c_str()); return b; }

    const auto rt = save.driver_ratings.find(id);
    const double elo = rt == save.driver_ratings.end() ? 0.0 : rt->second;
    snprintf(b, sizeof(b), "  T%-2d  %s  (%s)  ·  ELO %.0f  ·  calidad %.4f  ·  retirado %d\n",
             temporada, nombre.c_str(), id.c_str(), elo, RatingQuality(elo), (int)save.retired.count(id));
    out += b;

    // Where is she seated, and what position does she get in the grid that is written?
    int asientos = 0;
    for (const auto& sd : AllSeries()) {
        if (IsEraMemorySeries(sd)) continue;
        const std::vector<Seat> ss = SeatsForClass(sd.id, save);
        bool aqui = false;
        for (const auto& s : ss) if (!s.open && s.occupant_id == id) { aqui = true; break; }
        if (!aqui) continue;
        asientos++;
        const std::vector<GridDriver> grid = ComposeSeasonGridForSave(save, sd.id, (int)ss.size());
        int puesto = 0, n = (int)grid.size();
        double mio = -1.0;
        std::vector<double> rs;
        for (const auto& d : grid) { rs.push_back(d.race_skill); if (d.driver_id == id) mio = d.race_skill; }
        if (mio >= 0.0) { puesto = 1; for (double v : rs) if (v > mio) puesto++; }
        snprintf(b, sizeof(b), "       sentada en %-18s (clase %-22s nivel %d)  ·  parrilla %2d  ·  puesto %s\n",
                 sd.id.c_str(), sd.class_name.c_str(), sd.level, n,
                 puesto ? (std::to_string(puesto) + " de " + std::to_string(n)).c_str() : "(no sale en la parrilla)");
        out += b;
    }
    if (!asientos) out += "       SIN ASIENTO en ninguna serie viva\n";

    // Is she still the best of the cohort? The whole cohort is sorted by ELO.
    std::vector<std::pair<double, std::string> > orden;
    for (const auto& r : coh) {
        const auto it = save.driver_ratings.find(r.id);
        orden.push_back(std::make_pair(it == save.driver_ratings.end() ? 0.0 : it->second, r.name));
    }
    std::sort(orden.begin(), orden.end(), [](const std::pair<double,std::string>& a,
                                             const std::pair<double,std::string>& b2) { return a.first > b2.first; });
    int pos = 0; for (size_t i = 0; i < orden.size(); i++) if (orden[i].second == nombre) pos = (int)i + 1;
    snprintf(b, sizeof(b), "       en la cohorte (%d personas) va %d por ELO  ·  la 1ª es %s (%.0f)\n",
             (int)orden.size(), pos, orden.empty() ? "-" : orden[0].second.c_str(),
             orden.empty() ? 0.0 : orden[0].first);
    out += b;
    return out;
}

// ===================================================================================================
// sinnombre: WHERE THE ROWS THAT ARE NOT WRITTEN COME FROM (16/09)
// ===================================================================================================
//
// `--medidas` left question 2 as a number: 71 rows at T5 and 115 at T20 that do not reach the XML, all of
// OCCUPIED seats and all for the same reason (`GridDropReport::unresolved` — "no name"), and all with
// an `rd_<hash>` id. This says WHOSE those ids are.
//
// The identity chain of an occupant (`career_fields.cpp::PersonForOccupant`) is: pinned roster OF THIS
// SERIES -> field OF THIS SERIES -> pool (`drivers.json`) -> cohort -> livery packs -> registered name
// of a generated one. The first two steps are LOCAL to the series being composed. And an `rd_<hash>` id is
// minted in three places (`PinnedOccupantId`, `FieldOccupantId`, `PackDriverId`) when the name is NOT in
// the pool: it is an FNV hash of the name and nothing else.
//
// Hence the hypothesis this checks: a person whose only identity is the hash of their name in the
// pinned roster or the field of series A, when the market moves them to series B, in B nobody knows them — they are not
// in B's pinned roster, nor in its field, nor in the pool, nor in the cohort, nor in the packs. Their seat
// exists, their car exists, and their row cannot be written.
//
// Dump columns: where she is seated today, where her id comes from, and with what name — because if the
// name is known at the origin, the fix is cheap.
//
// `ZTA_SINNOMBRE_SEED=<n>` changes `career_seed` to answer "are they always the same ones?".
static int dump_sinnombre(const char* outPath) {
    using namespace career;
    using namespace worldlab;
    if (!canon_load_prod()) { printf("SINNOMBRE FAIL: no se pudieron cargar los datos\n"); return 1; }
    registry::Load();

    SaveData save;
    SeedAllDrivers(save.driver_ratings);
    const char* envSeed = getenv("ZTA_SINNOMBRE_SEED");
    if (envSeed) save.career_seed = (unsigned long)atol(envSeed);
    CareerCalendar cc; cc.year = kStartYear; cc.cursor_doy = 1;
    CareerProgress prog; prog.rating = bal::RATING_PLAYER_SEED;

    // ORIGIN indices: who mints each id, only once ----
    std::map<std::string, std::string> dePinned, deField, nombreOrigen, paisOrigen;
    std::set<std::string> idsPack, idsCohorte;
    for (const auto& sd : AllSeries()) {
        for (const auto& pd : PinnedRosterForSeries(sd.id)) {
            const std::string id = PinnedOccupantId(pd);
            if (id.empty() || dePinned.count(id)) continue;
            dePinned[id] = sd.id; nombreOrigen[id] = pd.name; paisOrigen[id] = pd.country;
        }
        for (const auto& f : FieldForSeries(sd.id)) {
            const std::string id = FieldOccupantId(f);
            if (id.empty() || deField.count(id)) continue;
            deField[id] = sd.id;
            if (!nombreOrigen.count(id)) { nombreOrigen[id] = f.name; paisOrigen[id] = f.country; }
        }
        for (int k = 0; ; ++k) {
            const PackDriver* pk = PackDriverForClassSlot(sd.class_name, k);
            if (!pk) break;
            const std::string id = PackDriverId(*pk);
            if (!id.empty()) { idsPack.insert(id); if (!nombreOrigen.count(id)) { nombreOrigen[id] = pk->name; paisOrigen[id] = pk->country; } }
        }
    }
    for (int t = 1; t <= 7; t++) for (const auto& rd : RosterForTier(t)) if (!rd.id.empty()) idsCohorte.insert(rd.id);

    std::string out = "== DE QUIEN SON LAS FILAS QUE NO SE ESCRIBEN ==\n\n";
    char b[700];
    snprintf(b, sizeof(b), "semilla de carrera: %lu%s\n"
             "ids acuñados por PINNEADO %d  ·  por FIELD %d  ·  de PACK %d  ·  cohorte %d\n\n",
             save.career_seed, envSeed ? "  (ZTA_SINNOMBRE_SEED)" : "  (la de siempre)",
             (int)dePinned.size(), (int)deField.size(), (int)idsPack.size(), (int)idsCohorte.size());
    out += b;

    std::map<std::string, int> vistoEn;        // id -> first milestone at which it appears without a name
    std::map<std::string, std::string> claseDe;
    const int kHitos[] = { 0, 1, 2, 5, 10, 20 };
    int siguiente = 0;

    for (int temporada = 0; temporada <= 20; temporada++) {
        if (siguiente < (int)(sizeof(kHitos)/sizeof(kHitos[0])) && kHitos[siguiente] == temporada) {
            siguiente++;
            std::map<std::string, int> porOrigen;
            std::vector<std::string> detalle;
            int total = 0, mismaSerie = 0, conNombre = 0, regConNombre = 0, regConPais = 0;
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd)) continue;
                const std::vector<SeatRow> filas = SeatRowsForSeries(save, sd.id);
                if (filas.size() < 8) continue;
                const std::vector<GridDriver> grid = ComposeSeasonGridForSave(save, sd.id, (int)filas.size());
                std::set<std::string> escritos;
                for (const auto& d : grid) if (!d.driver_id.empty()) escritos.insert(d.driver_id);
                for (const auto& f : filas) {
                    if (f.occupant_id.empty() || escritos.count(f.occupant_id)) continue;
                    total++;
                    const std::string& id = f.occupant_id;
                    if (!vistoEn.count(id)) { vistoEn[id] = temporada; claseDe[id] = sd.id; }
                    std::string orig, deDonde;
                    if (DriverById(id))            orig = "pool (drivers.json)";
                    else if (idsCohorte.count(id)) orig = "cohorte";
                    else if (idsPack.count(id))    orig = "pack de libreas";
                    else if (dePinned.count(id))   { orig = "PINNEADO de otra serie"; deDonde = dePinned[id]; }
                    else if (deField.count(id))    { orig = "FIELD de otra serie";    deDonde = deField[id]; }
                    else if (const canon::DriverIdentity* di = registry::ById(id)) {
                        orig = "registro (reserva)";
                        // what decides whether the fix is CODE or CONTENT: the registry gave it an
                        //  id, but did it also give it a name and country? With a name, the composition only has
                        //  to look it up; without a country, the flag is a content decision.
                        if (!di->display_name.empty()) regConNombre++;
                        if (!di->country.empty())      regConPais++;
                        if (!nombreOrigen.count(id) && !di->display_name.empty())
                            nombreOrigen[id] = di->display_name;
                    }
                    else                           orig = "NINGUNO: id huerfano";
                    if (!deDonde.empty() && deDonde == sd.id) { orig += " (¡LA MISMA!)"; mismaSerie++; }
                    porOrigen[orig]++;
                    const auto nm = nombreOrigen.find(id);
                    if (nm != nombreOrigen.end() && !nm->second.empty()) conNombre++;
                    if ((int)detalle.size() < 14) {
                        snprintf(b, sizeof(b), "      %-20s asiento de %-18s  ·  %-26s  ·  viene de %-16s  ·  nombre conocido: %s",
                                 id.c_str(), sd.id.c_str(), orig.c_str(),
                                 deDonde.empty() ? "-" : deDonde.c_str(),
                                 nm == nombreOrigen.end() ? "NO" : nm->second.c_str());
                        detalle.push_back(b);
                    }
                }
            }
            snprintf(b, sizeof(b), "-- T%d: %d filas sin escribir  ·  con nombre conocido en su origen: %d  ·"
                     "  su origen es la MISMA serie donde esta sentada: %d\n"
                     "   de las de RESERVA: el registro le sabe el NOMBRE a %d  ·  y el PAIS a %d\n",
                     temporada, total, conNombre, mismaSerie, regConNombre, regConPais);
            out += b;
            for (const auto& kv : porOrigen) {
                snprintf(b, sizeof(b), "     %-40s %4d\n", kv.first.c_str(), kv.second);
                out += b;
            }
            for (const auto& d : detalle) out += d + "\n";
            out += "\n";
        }
        if (temporada == 20) break;
        RolloverYearReport(cc, prog, save, "Jugador");
    }

    // The full list, so it can be compared across seeds.
    out += "\n-- TODOS los ids que han salido sin nombre en los veinte inviernos --\n";
    snprintf(b, sizeof(b), "   distintos: %d\n", (int)vistoEn.size());
    out += b;
    for (const auto& kv : vistoEn) {
        const auto nm = nombreOrigen.find(kv.first);
        snprintf(b, sizeof(b), "   %-20s  primera vez T%-2d  en %-18s  nombre %s\n",
                 kv.first.c_str(), kv.second, claseDe[kv.first].c_str(),
                 nm == nombreOrigen.end() ? "(desconocido)" : nm->second.c_str());
        out += b;
    }

    FILE* fp = fopen(outPath, "wb");
    if (fp) { fwrite(out.data(), 1, out.size(), fp); fclose(fp); }
    printf("%s", out.c_str());
    printf("\nsinnombre -> %s\n", outPath);
    return 0;
}

static int dump_medidas(const char* outPath) {
    using namespace career;
    using namespace worldlab;
    if (!canon_load_prod()) { printf("MEDIDAS FAIL: no se pudieron cargar los datos\n"); return 1; }
    registry::Load();

    SaveData save;
    SeedAllDrivers(save.driver_ratings);
    CareerCalendar cc; cc.year = kStartYear; cc.cursor_doy = 1;
    CareerProgress prog; prog.rating = bal::RATING_PLAYER_SEED;

    std::set<std::string> cohorteIds;
    std::map<std::string, std::string> cohorteNombre;
    for (int t = 1; t <= 7; t++) for (const auto& rd : RosterForTier(t))
        if (!rd.id.empty()) { cohorteIds.insert(rd.id); cohorteNombre[rd.id] = rd.name; }

    std::string out = "== LAS CUATRO MEDIDAS DE LA 0.7.0 ==\n\n";
    char b[700];
    snprintf(b, sizeof(b), "cohorte declarada: %d personas (ids rk_*)\n\n", (int)cohorteIds.size());
    out += b;

    std::string secCoh = "== (1) LA COHORTE: DONDE CORRE Y QUE PUESTO HACE ==\n";
    std::string secCohFilas = "\n-- filas de COHORTE en las parrillas que se escriben, por NIVEL de serie --\n"
                              "hito | n1  | n2  | n3  | n4  | n5  | n6  | n7  | filas coh | filas tot | % \n"
                              "-----+-----+-----+-----+-----+-----+-----+-----+-----------+-----------+------\n";
    std::string secVega = "\n== (1b) LA PERSONA: Lucia Vega ==\n";
    std::string secAs = "== (2) ASIENTOS DECLARADOS CONTRA FILAS COMPUESTAS ==\n";
    std::string secAsClase;
    std::string secF1 = "== (3) LA CABEZA DE LA F1 (pinnacle_championship_1831), TEMPORADA A TEMPORADA ==\n"
                        "temp | n  |   1º ELO  cap |   5º ELO  cap |  20º ELO  cap | media ELO\n"
                        "-----+----+---------------+---------------+---------------+----------\n";
    std::string secPerd = "== (4) LAS PERSONAS QUE SE ESFUMAN ==\n";

    // (4) tracking the lost ones: id -> season in which they were lost.
    std::map<std::string, int> perdidoEn;
    std::map<int, int> perdidosPorTemp;
    std::vector<std::string> trazaPerdidos;

    const int kHitos[] = { 0, 1, 2, 5, 10, 20 };
    int siguiente = 0;

    for (int temporada = 0; temporada <= 20; temporada++) {
        const bool esHito = siguiente < (int)(sizeof(kHitos)/sizeof(kHitos[0])) && kHitos[siguiente] == temporada;

        // (3) the F1 front, ALL seasons ----------------
        {
            const std::string kF1 = "pinnacle_championship_1831";
            std::vector<std::pair<double,double> > cap;   // (capacity, ELO)
            for (const auto& a : SeatsForClass(kF1, save)) {
                if (a.open || a.occupant_id.empty()) continue;
                const double c = OccupantRating(kF1, a.occupant_id, save, cc.year);
                const auto it = save.driver_ratings.find(a.occupant_id);
                cap.push_back(std::make_pair(c, it == save.driver_ratings.end() ? 0.0 : it->second));
            }
            std::sort(cap.begin(), cap.end(), [](const std::pair<double,double>& x,
                                                 const std::pair<double,double>& y) { return x.first > y.first; });
            auto en = [&](int i) { return (i - 1) < (int)cap.size() ? cap[i - 1] : std::make_pair(0.0, 0.0); };
            double sum = 0.0; for (const auto& c : cap) sum += c.second;
            snprintf(b, sizeof(b), "T%-4d| %2d | %5.0f %5.0f | %5.0f %5.0f | %5.0f %5.0f | %8.0f\n",
                     temporada, (int)cap.size(), en(1).second, en(1).first, en(5).second, en(5).first,
                     en(20).second, en(20).first, cap.empty() ? 0.0 : sum / cap.size());
            secF1 += b;
        }

        if (esHito) {
            siguiente++;
            // (1) the cohort ----------------
            snprintf(b, sizeof(b), "\n-- T%d --\n", temporada);
            secCoh += b;
            int filasCoh[8] = {0,0,0,0,0,0,0,0}, filasTot[8] = {0,0,0,0,0,0,0,0};
            int sentadaN[8] = {0,0,0,0,0,0,0,0};
            long long sumPuesto = 0, sumN = 0; int conPuesto = 0;
            std::map<std::string, std::string> dondeCoh;   // id -> "series(level) position x/n"
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd)) continue;
                const std::vector<SeatRow> filas = SeatRowsForSeries(save, sd.id);
                if (filas.size() < 8) continue;
                const std::vector<GridDriver> grid = ComposeSeasonGridForSave(save, sd.id, (int)filas.size());
                if (grid.size() < 8) continue;
                const int niv = (sd.level >= 1 && sd.level <= 7) ? sd.level : 1;
                // position = order by race_skill within the written grid
                std::vector<double> rs; for (const auto& d : grid) rs.push_back(d.race_skill);
                for (const auto& d : grid) {
                    filasTot[niv]++;
                    if (!cohorteIds.count(d.driver_id)) continue;
                    filasCoh[niv]++;
                    int puesto = 1; for (double v : rs) if (v > d.race_skill) puesto++;
                    sumPuesto += puesto; sumN += (int)grid.size(); conPuesto++;
                    char q[220];
                    snprintf(q, sizeof(q), "%s n%d puesto %d/%d", sd.id.c_str(), niv, puesto, (int)grid.size());
                    if (dondeCoh.count(d.driver_id)) dondeCoh[d.driver_id] += " · " + std::string(q);
                    else dondeCoh[d.driver_id] = q;
                }
            }
            // cohort seats per level (person, not row)
            { std::set<std::string> vistos;
              for (const auto& sd : AllSeries()) {
                  if (IsEraMemorySeries(sd)) continue;
                  const int niv = (sd.level >= 1 && sd.level <= 7) ? sd.level : 1;
                  for (const auto& a : SeatsForClass(sd.id, save)) {
                      if (a.open || a.occupant_id.empty()) continue;
                      if (!cohorteIds.count(a.occupant_id)) continue;
                      if (!vistos.insert(a.occupant_id).second) continue;
                      sentadaN[niv]++;
                  }
              } }
            for (const auto& kv : dondeCoh) {
                const auto rt = save.driver_ratings.find(kv.first);
                snprintf(b, sizeof(b), "   %-22s ELO %5.0f  ·  %s\n",
                         cohorteNombre[kv.first].c_str(),
                         rt == save.driver_ratings.end() ? 0.0 : rt->second, kv.second.c_str());
                secCoh += b;
            }
            { int tp = 0, tf = 0, ts = 0;
              for (int n = 1; n <= 7; n++) { tp += filasCoh[n]; tf += filasTot[n]; ts += sentadaN[n]; }
              snprintf(b, sizeof(b), "   -> personas de cohorte con FILA %d  ·  con ASIENTO %d  ·  puesto medio %.1f de %.1f\n",
                       (int)dondeCoh.size(), ts, conPuesto ? (double)sumPuesto / conPuesto : 0.0,
                       conPuesto ? (double)sumN / conPuesto : 0.0);
              secCoh += b;
              snprintf(b, sizeof(b), "T%-4d| %3d | %3d | %3d | %3d | %3d | %3d | %3d |    %4d   |    %4d   | %5.2f%%\n",
                       temporada, filasCoh[1], filasCoh[2], filasCoh[3], filasCoh[4], filasCoh[5],
                       filasCoh[6], filasCoh[7], tp, tf, tf ? 100.0 * tp / tf : 0.0);
              secCohFilas += b;
              char q[220];
              snprintf(q, sizeof(q), "   asientos de cohorte por nivel: n1 %d n2 %d n3 %d n4 %d n5 %d n6 %d n7 %d\n",
                       sentadaN[1], sentadaN[2], sentadaN[3], sentadaN[4], sentadaN[5], sentadaN[6], sentadaN[7]);
              secCoh += q; }

            secVega += MedidasPersona(save, "Lucia Vega", temporada);

            // (2) seats against rows ----------------
            if (temporada == 0 || temporada == 5 || temporada == 20) {
                int asN[8] = {0}, ocN[8] = {0}, abN[8] = {0}, flN[8] = {0}, declN[8] = {0};
                // WHY a row is missing while the seat is occupied: the composition declares it
                //  (`LastGridDrops`), so there is no need to guess.
                int dDup = 0, dLiv = 0, dMul = 0, dSin = 0, dSize = 0, dJug = 0;
                snprintf(b, sizeof(b), "\n-- T%d: clases con HUECO (asiento declarado sin ocupante, o fila que falta) --\n"
                         "serie                | niv | asientos | ocupados | ABIERTOS | filas | falta | por que falta\n"
                         "---------------------+-----+----------+----------+----------+-------+-------+---------------\n", temporada);
                secAsClase += b;
                for (const auto& sd : AllSeries()) {
                    if (IsEraMemorySeries(sd)) continue;
                    const int niv = (sd.level >= 1 && sd.level <= 7) ? sd.level : 1;
                    const std::vector<Seat> ss = SeatsForClass(sd.id, save);
                    int oc = 0, ab = 0;
                    for (const auto& a : ss) { if (!a.open && !a.occupant_id.empty()) oc++; else ab++; }
                    const std::vector<SeatRow> filas = SeatRowsForSeries(save, sd.id);
                    int nf = 0; GridDropReport dr;
                    if (filas.size() >= 8) {
                        nf = (int)ComposeSeasonGridForSave(save, sd.id, (int)filas.size()).size();
                        dr = LastGridDrops();
                    }
                    asN[niv] += (int)ss.size(); ocN[niv] += oc; abN[niv] += ab; flN[niv] += nf;
                    declN[niv] += WorldGridSizeForClassName(sd.class_name);
                    dDup += dr.dup_driver; dLiv += dr.dup_livery; dMul += dr.multiclass;
                    dSin += dr.unresolved; dSize += dr.over_size; dJug += dr.player_car;
                    if (ab > 0 || (int)ss.size() - nf > 0) {
                        snprintf(b, sizeof(b), "%-20s |  %d  |   %4d   |   %4d   |   %4d   |  %4d |  %4d | mismo piloto %d · misma librea %d · sin nombre %d · sobra %d\n",
                                 sd.id.c_str(), niv, (int)ss.size(), oc, ab, nf, (int)ss.size() - nf,
                                 dr.dup_driver, dr.dup_livery, dr.unresolved, dr.over_size);
                        secAsClase += b;
                    }
                }
                snprintf(b, sizeof(b), "   TOTAL de bajas declaradas por la composicion: mismo piloto en dos coches %d"
                         "  ·  misma librea %d  ·  multiclase %d  ·  sin nombre %d  ·  por encima del tamaño %d"
                         "  ·  coche del jugador %d\n", dDup, dLiv, dMul, dSin, dSize, dJug);
                secAsClase += b;
                // AND WHO THEY ARE. The occupants the bridge delivers are crossed against the `driver_id` that
                //  the grid ends up writing: the difference is exactly the missing rows, with
                //  name and id, without having to open the inner cascade of `PersonForOccupant`.
                {
                    std::map<std::string, int> porPrefijo;
                    std::vector<std::string> ejemplos;
                    for (const auto& sd : AllSeries()) {
                        if (IsEraMemorySeries(sd)) continue;
                        const std::vector<SeatRow> filas = SeatRowsForSeries(save, sd.id);
                        if (filas.size() < 8) continue;
                        const std::vector<GridDriver> grid = ComposeSeasonGridForSave(save, sd.id, (int)filas.size());
                        std::set<std::string> escritos;
                        for (const auto& d : grid) if (!d.driver_id.empty()) escritos.insert(d.driver_id);
                        for (const auto& f : filas) {
                            if (f.occupant_id.empty() || escritos.count(f.occupant_id)) continue;
                            const char* pre = f.occupant_id.rfind("rd_",0) == 0 ? "rd_ (pool real)"
                                            : f.occupant_id.rfind("gn_",0) == 0 ? "gn_ (novato generado)"
                                            : f.occupant_id.rfind("fl_",0) == 0 ? "fl_ (relleno de clase)"
                                            : f.occupant_id.rfind("rk_",0) == 0 ? "rk_ (cohorte)"
                                                                                : "otro";
                            porPrefijo[pre]++;
                            if ((int)ejemplos.size() < 12)
                                ejemplos.push_back("      " + sd.id + "  ->  " + f.occupant_id +
                                                   "  (" + NombreDe(f.occupant_id) + ")  librea " + f.livery_name);
                        }
                    }
                    secAsClase += "   de quien son esas filas que faltan:";
                    for (const auto& kv : porPrefijo) {
                        snprintf(b, sizeof(b), "  %s %d", kv.first.c_str(), kv.second);
                        secAsClase += b;
                    }
                    secAsClase += "\n";
                    for (const auto& e : ejemplos) secAsClase += e + "\n";
                }
                snprintf(b, sizeof(b), "\n-- T%d: por NIVEL --\n"
                         "niv | dato de clase | asientos | ocupados | ABIERTOS | filas compuestas | filas-asientos\n"
                         "----+---------------+----------+----------+----------+------------------+---------------\n", temporada);
                secAs += b;
                int t1=0,t2=0,t3=0,t4=0,t5=0;
                for (int n = 1; n <= 7; n++) {
                    snprintf(b, sizeof(b), " %d  |     %5d     |   %4d   |   %4d   |   %4d   |       %4d       |     %+5d\n",
                             n, declN[n], asN[n], ocN[n], abN[n], flN[n], flN[n] - asN[n]);
                    secAs += b;
                    t1+=declN[n]; t2+=asN[n]; t3+=ocN[n]; t4+=abN[n]; t5+=flN[n];
                }
                snprintf(b, sizeof(b), "TOT |     %5d     |   %4d   |   %4d   |   %4d   |       %4d       |     %+5d\n",
                         t1, t2, t3, t4, t5, t5 - t2);
                secAs += b;
            }
        }

        if (temporada == 20) break;

        // the winter, and (4) who vanishes ----------------
        std::map<std::string, std::string> ocupAntes;   // seat key -> occupant
        for (const auto& sd : AllSeries()) {
            if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
            int idx = 0;
            for (const auto& st : SeatsForClass(sd.id, save)) {
                if (!st.open && !st.occupant_id.empty()) ocupAntes[SeatKey(sd.id, idx)] = st.occupant_id;
                ++idx;
            }
        }
        const RolloverReport r = RolloverYearReport(cc, prog, save, "Jugador");

        std::set<std::string> idAscendido, idFichado;
        for (const auto& p : r.promotions)   idAscendido.insert(p.driver_id);
        for (const auto& m : r.market_moves) idFichado.insert(m.driver_id);
        std::set<std::string> vivosDespues;
        for (const auto& sd : AllSeries()) {
            if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
            for (const auto& st : SeatsForClass(sd.id, save))
                if (!st.open && !st.occupant_id.empty()) vivosDespues.insert(st.occupant_id);
        }
        int perdidosAqui = 0;
        for (const auto& sd : AllSeries()) {
            if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
            int idx = 0;
            for (const auto& st : SeatsForClass(sd.id, save)) {
                const auto it = ocupAntes.find(SeatKey(sd.id, idx));
                ++idx;
                if (it == ocupAntes.end() || st.open || st.occupant_id.empty()) continue;
                if (st.occupant_id == it->second) continue;
                if (idAscendido.count(st.occupant_id) || idFichado.count(st.occupant_id) ||
                    st.occupant_id.rfind("gn_",0) == 0) continue;               // has an author
                if (vivosDespues.count(it->second)) continue;                   // relay
                if (save.retired.count(it->second)) continue;                   // succession
                bool enAlgunSitio = false;
                for (const auto& sd2 : AllSeries()) {
                    for (const auto& st2 : SeatsForClass(sd2.id, save))
                        if (!st2.open && st2.occupant_id == it->second) { enAlgunSitio = true; break; }
                    if (enAlgunSitio) break;
                }
                if (enAlgunSitio) continue;                                     // in a period series
                if (save.seasons_idle.count(it->second)) continue;              // waiting in the pool
                perdidosAqui++;
                if (!perdidoEn.count(it->second)) {
                    perdidoEn[it->second] = temporada + 1;
                    if ((int)trazaPerdidos.size() < 40) {
                        char q[400];
                        snprintf(q, sizeof(q), "  [perdido] T%-2d  %-28s (%s)  ·  su plaza era %s  ·  la coge %s"
                                 "  ·  retirado %d  ·  en el pozo %d\n",
                                 temporada + 1, NombreDe(it->second), it->second.c_str(),
                                 SeatKey(sd.id, idx - 1).c_str(), NombreDe(st.occupant_id),
                                 (int)save.retired.count(it->second), (int)save.seasons_idle.count(it->second));
                        trazaPerdidos.push_back(q);
                    }
                }
            }
        }
        perdidosPorTemp[temporada + 1] = perdidosAqui;
    }

    // Do they come back? The FINAL state (T20) of each lost one is looked at.
    {
        std::set<std::string> sentadosFin, sentadosVivoFin;
        for (const auto& sd : AllSeries()) {
            for (const auto& st : SeatsForClass(sd.id, save)) {
                if (st.open || st.occupant_id.empty()) continue;
                sentadosFin.insert(st.occupant_id);
                if (!IsEraMemorySeries(sd) && IsModernSeries(sd.id)) sentadosVivoFin.insert(st.occupant_id);
            }
        }
        int vuelve = 0, vuelveEpoca = 0, retirado = 0, pozo = 0, nada = 0;
        for (const auto& kv : perdidoEn) {
            if (sentadosVivoFin.count(kv.first))      vuelve++;
            else if (sentadosFin.count(kv.first))     vuelveEpoca++;
            else if (save.retired.count(kv.first))    retirado++;
            else if (save.seasons_idle.count(kv.first)) pozo++;
            else nada++;
        }
        secPerd += "★«perdida» = una plaza cambia de ocupante SIN autor (ni ascenso, ni fichaje, ni novato),\n"
                   "  el anterior no esta sentado en ninguna serie (ni viva ni de epoca), no consta retirado\n"
                   "  y no esta en el pozo de espera. Mismo criterio que `test_fill_pass_distribution`.\n\n";
        char q[500];
        snprintf(q, sizeof(q), "  personas DISTINTAS perdidas en 20 inviernos: %d\n"
                 "  y a T20:  con asiento vivo %d  ·  en una serie de EPOCA %d  ·  retiradas %d  ·"
                 "  en el pozo %d  ·  sin rastro %d\n\n", (int)perdidoEn.size(),
                 vuelve, vuelveEpoca, retirado, pozo, nada);
        secPerd += q;
        secPerd += "  por invierno (perdidas NUEVAS, sin repetir a nadie):\n   ";
        int acum = 0;
        for (const auto& kv : perdidosPorTemp) {
            snprintf(q, sizeof(q), " T%d:%d", kv.first, kv.second);
            secPerd += q; acum += kv.second;
        }
        snprintf(q, sizeof(q), "\n  (suma de eventos %d; personas distintas %d)\n\n", acum, (int)perdidoEn.size());
        secPerd += q;
        for (const auto& l : trazaPerdidos) secPerd += l;
    }

    // SECOND PASS, AND IT IS NEEDED. With the `--world` startup (virgin save, cursor on day 1) this
    //  criterion gives ZERO lost, and `test_fill_pass_distribution` measures TWELVE with the same code. What
    //  changes is not the count: it is the world one starts from. The suite fixes the occupancy by hand BEFORE the
    //  first winter (`MaterializeSeatOccupancy`) and starts on day 360 of the world year, which is the
    //  snapshot of a game that reaches the end of a season. It is measured IN BOTH worlds and both
    //  numbers are stated, because the difference between them is the answer to "where are they lost?".
    {
        SaveData s2;
        // The ELO is NOT seeded by hand: `test_fill_pass_distribution` does not either, and seeding it changes
        //  the world enough for other people to come out. Here the test is imitated, not `--world`.
        s2.current_world_year = kStartYear;
        CareerCalendar c2; c2.year = kStartYear; c2.cursor_doy = 360;
        CareerProgress p2; p2.credits = 1000000;
        const int fijadas = MaterializeSeatOccupancy(s2);
        std::map<std::string, int> perdEn2;
        std::map<int, int> perdTemp2;
        std::vector<std::string> traza2;
        for (int temporada = 0; temporada < 20; temporada++) {
            std::map<std::string, std::string> antes;
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
                int idx = 0;
                for (const auto& st : SeatsForClass(sd.id, s2)) {
                    if (!st.open && !st.occupant_id.empty()) antes[SeatKey(sd.id, idx)] = st.occupant_id;
                    ++idx;
                }
            }
            const RolloverReport r2 = RolloverYearReport(c2, p2, s2, "Jugador");
            // HERE IS THE KEY, AND IT IS NOT THE GAME'S. `test_fill_pass_distribution` calls
            //  `ReplaceWeakIncumbents` AFTER the rollover "to print its report", but that function does not
            //  report: IT MOVES PEOPLE (career_seats.cpp). And the rollover has already run it once inside
            //  (career_calendar.cpp:2093, with `&salientes` to collect the displaced). So the
            //  test does TWO passes of over the same winter, and the second changes occupants without
            //  any author declaring it and without collecting the displaced. It is measured with and without it.
            if (getenv("ZTA_MEDIDAS_DOBLE_SWAP"))
                ReplaceWeakIncumbents(s2, c2.year, std::set<std::string>());
            std::set<std::string> asc, fic, vivos;
            for (const auto& p : r2.promotions)   asc.insert(p.driver_id);
            for (const auto& m : r2.market_moves) fic.insert(m.driver_id);
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
                for (const auto& st : SeatsForClass(sd.id, s2))
                    if (!st.open && !st.occupant_id.empty()) vivos.insert(st.occupant_id);
            }
            int aqui = 0;
            for (const auto& sd : AllSeries()) {
                if (IsEraMemorySeries(sd) || !IsModernSeries(sd.id)) continue;
                int idx = 0;
                for (const auto& st : SeatsForClass(sd.id, s2)) {
                    const auto it = antes.find(SeatKey(sd.id, idx));
                    ++idx;
                    if (it == antes.end() || st.open || st.occupant_id.empty()) continue;
                    if (st.occupant_id == it->second) continue;
                    if (asc.count(st.occupant_id) || fic.count(st.occupant_id) ||
                        st.occupant_id.rfind("gn_",0) == 0) continue;
                    if (vivos.count(it->second) || s2.retired.count(it->second)) continue;
                    bool enAlgunSitio = false;
                    for (const auto& sd2 : AllSeries()) {
                        for (const auto& st2 : SeatsForClass(sd2.id, s2))
                            if (!st2.open && st2.occupant_id == it->second) { enAlgunSitio = true; break; }
                        if (enAlgunSitio) break;
                    }
                    if (enAlgunSitio || s2.seasons_idle.count(it->second)) continue;
                    aqui++;
                    if (!perdEn2.count(it->second)) {
                        perdEn2[it->second] = temporada + 1;
                        if ((int)traza2.size() < 40) {
                            char q[420];
                            snprintf(q, sizeof(q), "  [perdido] T%-2d  %-28s (%s)  ·  su plaza era %s  ·  la coge %s\n",
                                     temporada + 1, NombreDe(it->second), it->second.c_str(),
                                     SeatKey(sd.id, idx - 1).c_str(), NombreDe(st.occupant_id));
                            traza2.push_back(q);
                        }
                    }
                }
            }
            perdTemp2[temporada + 1] = aqui;
        }
        std::set<std::string> finVivo, finTodo;
        for (const auto& sd : AllSeries())
            for (const auto& st : SeatsForClass(sd.id, s2)) {
                if (st.open || st.occupant_id.empty()) continue;
                finTodo.insert(st.occupant_id);
                if (!IsEraMemorySeries(sd) && IsModernSeries(sd.id)) finVivo.insert(st.occupant_id);
            }
        int vuelve = 0, epoca = 0, retirado = 0, pozo = 0, nada = 0;
        for (const auto& kv : perdEn2) {
            if (finVivo.count(kv.first))            vuelve++;
            else if (finTodo.count(kv.first))       epoca++;
            else if (s2.retired.count(kv.first))    retirado++;
            else if (s2.seasons_idle.count(kv.first)) pozo++;
            else nada++;
        }
        char q[600];
        snprintf(q, sizeof(q), "\n-- EL MISMO CRITERIO SOBRE EL MUNDO DE LA SUITE (ocupacion FIJADA antes del\n"
                 "   primer invierno: %d plazas; cursor en el dia 360; SEGUNDA pasada de §21.5: %s) --\n"
                 "  personas DISTINTAS perdidas en 20 inviernos: %d  (eventos por invierno abajo)\n"
                 "  y a T20:  con asiento vivo %d  ·  en EPOCA %d  ·  retiradas %d  ·  en el pozo %d  ·  sin rastro %d\n   ",
                 fijadas, getenv("ZTA_MEDIDAS_DOBLE_SWAP") ? "SI (como la suite)" : "no",
                 (int)perdEn2.size(), vuelve, epoca, retirado, pozo, nada);
        secPerd += q;
        int acum2 = 0, cinco = 0;
        for (const auto& kv : perdTemp2) {
            snprintf(q, sizeof(q), " T%d:%d", kv.first, kv.second);
            secPerd += q; acum2 += kv.second; if (kv.first <= 5) cinco += kv.second;
        }
        snprintf(q, sizeof(q), "\n  eventos: %d en veinte inviernos  ·  %d en los CINCO primeros (la cifra del informe)\n\n",
                 acum2, cinco);
        secPerd += q;
        for (const auto& l : traza2) secPerd += l;
    }

    out += secCoh + secCohFilas + secVega + "\n\n" + secAs + secAsClase + "\n" + secF1 + "\n" + secPerd;

    FILE* fp = fopen(outPath, "wb");
    if (fp) { fwrite(out.data(), 1, out.size(), fp); fclose(fp); }
    printf("%s", out.c_str());
    printf("\nmedidas -> %s\n", outPath);
    return 0;
}

// census <file.txt>: the full canonical census over a save. Without a save argument it uses an
// empty game (year 1 derived from the data), which is the world any new career starts with. It is not a
// test: it is the baseline phases B/C/C.5/D are compared against.
static int dump_census(const char* outPath, const char* savePath) {
    using namespace career;
    using namespace career::canon;
    if (!canon_load_prod()) { printf("CENSUS FAIL: no se pudieron cargar los datos de produccion\n"); return 1; }
    SaveData save;
    if (savePath && *savePath) {
        if (!LoadCareer(save, savePath)) { printf("CENSUS FAIL: no se pudo leer el save %s\n", savePath); return 1; }
        printf("censo sobre el save %s (ano %d)\n", savePath, save.current_world_year);
    }
    World w = BuildWorld(save);
    std::vector<Finding> f = Validate(w);
    Census c = TakeCensus(w, f);

    std::string out = CensusText(c);
    out += "\n" + GridCensusText(TakeGridCensus(w, save));
    out += "\n== HUECOS DEL MODELO (campos de §5 sin fuente hoy) ==\n";
    for (const auto& g : Gaps()) out += "  " + g + "\n";
    out += "\n== HALLAZGOS (hasta 5 por codigo) ==\n";
    out += FindingsText(f, 5);

    FILE* fp = fopen(outPath, "wb");
    if (!fp) { printf("CENSUS FAIL: no se pudo abrir %s\n", outPath); return 1; }
    fwrite(out.data(), 1, out.size(), fp);
    fclose(fp);
    printf("%s", out.c_str());
    printf("censo -> %s (%zu bytes)\n", outPath, out.size());
    return 0;
}

static void test_buildgrid_wet_skill_band() {
    using namespace career;
    auto wetValues = [](const std::string& xml) {
        std::vector<double> values;
        size_t pos = 0;
        while ((pos = xml.find("<wet_skill>", pos)) != std::string::npos) {
            pos += 11;
            values.push_back(atof(xml.c_str() + pos));
        }
        return values;
    };
    std::vector<GridDriver> grid(4);
    const double wet[] = {0.8, 0.2, 0.3, 0.8};
    const double expected[] = {1.0, 0.7, 0.75, 1.0};
    for (int i = 0; i < 4; ++i) {
        grid[i].wet_skill = wet[i];
        grid[i].race_skill = 0.4 + 0.1 * i;
        grid[i].qualifying = grid[i].race_skill;
    }
    for (int ai : {80, 100, 120}) {
        const auto values = wetValues(BuildGridXml(grid, 15.0, 95.0, false, ai));
        CHECK_EQ(values.size(), grid.size());
        for (size_t i = 0; i < values.size(); ++i) {
            CHECK(std::abs(values[i] - expected[i]) < 0.00001);
            CHECK(grid[i].wet_skill == wet[i]); // export never mutates saved traits
        }
    }
    grid.resize(1);
    auto values = wetValues(BuildGridXml(grid));
    CHECK_EQ(values.size(), 1u);
    CHECK(values[0] == 1.0);
    grid.resize(3, grid.front());
    values = wetValues(BuildGridXml(grid));
    CHECK_EQ(values.size(), 3u);
    for (double value : values) CHECK(value == 1.0);
    CHECK(wetValues(BuildGridXml({})).empty());
}

// 04/10 (Josh): the start is written like the wet: per class, the best at 1.0 and the rest spread down to 0.70,
// without going through the human band (which left a quarter of the field at 0.67 and the AI started slowly).
static void test_buildgrid_start_reactions_anchored() {
    using namespace career;
    auto startValues = [](const std::string& xml) {
        std::vector<double> values;
        size_t pos = 0;
        while ((pos = xml.find("<start_reactions>", pos)) != std::string::npos) { pos += 17; values.push_back(atof(xml.c_str() + pos)); }
        return values;
    };
    std::vector<GridDriver> grid(4);
    const double st[] = {0.95, 0.58, 0.67, 0.95};             // raw archetype: fighter, metronome, consistent, fast
    const double expected[] = {1.0, 0.7, 0.7 + 0.3 * (0.09 / 0.37), 1.0};
    for (int i = 0; i < 4; ++i) { grid[i].start_reactions = st[i]; grid[i].race_skill = 0.4 + 0.1 * i; grid[i].qualifying = grid[i].race_skill; }
    for (int ai : {80, 100, 120}) {
        const auto values = startValues(BuildGridXml(grid, 15.0, 95.0, false, ai));
        CHECK_EQ(values.size(), grid.size());
        for (size_t i = 0; i < values.size(); ++i) {
            CHECK(std::abs(values[i] - expected[i]) < 0.0001);
            CHECK(grid[i].start_reactions == st[i]);              // the export does not mutate the saved trait
        }
    }
    grid.resize(1);
    auto values = startValues(BuildGridXml(grid));
    CHECK_EQ(values.size(), 1u); CHECK(values[0] == 1.0);        // just one: the ceiling
    grid.resize(3, grid.front());
    values = startValues(BuildGridXml(grid));
    for (double v : values) CHECK(v == 1.0);                    // equal: the ceiling
    CHECK(startValues(BuildGridXml({})).empty());
}

